INSERT INTO grammar_points VALUES('g_a_ga_ichiban','A が いちばん～',NULL,NULL,'N5','[]','[{"ja":"この中で、寿司が一番好きです。","en":"Of all these, I like sushi the most.","romaji":"Kono naka de, sushi ga ichiban suki desu.","zh":""},{"ja":"彼女はクラスで一番速く泳げます。","en":"She can swim the fastest in the class.","romaji":"Kanojo wa kurasu de ichiban hayaku oyogemasu.","zh":""},{"ja":"この町では、この公園が一番きれいです。","en":"In this town, this park is the most beautiful.","romaji":"Kono machi de wa, kono kouen ga ichiban kirei desu.","zh":""},{"ja":"飲み物の中では、紅茶が一番好きです。","en":"Among all drinks, I like tea the most.","romaji":"Nomimono no naka de wa, koucha ga ichiban suki desu.","zh":""}]',replace('**Short**: Express the superlative degree; ''the most'', ''the best'', ''the least''.\n\n**Formation**: Noun + が + いちばん + Adjective/Verb\n\n**Long**: The A が いちばん～ grammar point is used to express a superlative degree or the highest rank. It can be translated as ''the most'', ''the best'', or ''the least'' in English. The formation is used with various adjectives and verbs, and can also be used in comparison with other items or people.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_keredomo_b','A。けれども、～B。',NULL,NULL,'N5','[]','[{"ja":"今日は晴れている。けれども、寒いです。","en":"It is sunny today. However, it is cold.","romaji":"Kyou wa harete iru. Keredo mo, samui desu.","zh":""},{"ja":"彼女はうるさい。けれども、面白いです。","en":"She is noisy. But, she is interesting.","romaji":"Kanojo wa urusai. Keredo mo, omoshiroi desu.","zh":""},{"ja":"その映画は長かった。けれども、退屈じゃなかった。","en":"The movie was long. But, it wasn''t boring.","romaji":"Sono eiga wa nagakatta. Keredo mo, taikutsu janakatta.","zh":""},{"ja":"彼は運動が得意だ。けれども、勉強は苦手だ。","en":"He is good at sports. However, he is not good at studying.","romaji":"Kare wa undou ga tokui da. Keredo mo, benkyou wa nigate da.","zh":""}]',replace('**Short**: Used to express a contrast between two statements. It can be translated as ''but'' or ''however''.\n\n**Formation**: Statement A + けれども、+ Statement B\n\n**Long**: The grammar point A。けれども、～B。 is used to express a contrast or contradiction between statement A and statement B. It can be translated as ''but'' or ''however'' in English. けれども is a conjunction that links two clauses to show there is a conflicting or opposing idea between them.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_shikashi_b','A。しかし、～B。',NULL,NULL,'N5','[]','[{"ja":"今日は忙しい。しかし、時間があるなら、コーヒーを飲もう。","en":"I''m busy today. However, if I have time, let''s have coffee.","romaji":"Kyou wa isogashii. Shikashi, jikan ga aru nara, koohii o nomou.","zh":""},{"ja":"その映画は面白かった。しかし、長すぎました。","en":"The movie was interesting. But, it was too long.","romaji":"Sono eiga wa omoshirokatta. Shikashi, nagasugimashita.","zh":""},{"ja":"彼は疲れていた。しかし、宿題を終わらせた。","en":"He was tired. However, he finished his homework.","romaji":"Kare wa tsukareteita. Shikashi, shukudai o owaraseta.","zh":""},{"ja":"部屋は狭いです。しかし、便利な場所にあります。","en":"The room is small. But, it is in a convenient location.","romaji":"Heya wa semai desu. Shikashi, benri na basho ni arimasu.","zh":""}]',replace('**Short**: Expresses contrast or contradiction between two clauses; ''A, but B'', ''A, however B''.\n\n**Formation**: Sentence A + しかし + Sentence B.\n\n**Long**: The grammar point A。しかし、～B。 is used to show contrast or contradiction between two clauses. It can be translated as ''A, but B'' or ''A, however B'' in English. しかし is placed between two sentences to indicate a contrast between them.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_ja_b','A。じゃ、～B。',NULL,NULL,'N5','[]','[{"ja":"映画は時間がない。じゃ、また今度行こう。","en":"There''s no time for a movie. Well then, let''s go another time.","romaji":"Eiga wa jikan ga nai. Ja, mata kondo ikou.","zh":""},{"ja":"お腹がすいた。じゃ、レストランに行こう。","en":"I''m hungry. In that case, let''s go to a restaurant.","romaji":"Onaka ga suita. Ja, resutoran ni ikou.","zh":""},{"ja":"電車が遅れた。じゃ、バスで行こう。","en":"The train is late. So, let''s go by bus.","romaji":"Densha ga okureta. Ja, basu de ikou.","zh":""},{"ja":"このシャツは高い。じゃ、別のを買おう。","en":"This shirt is expensive. Well then, let''s buy a different one.","romaji":"Kono shatsu wa takai. Ja, betsu no o kau.","zh":""}]',replace('**Short**: Indicates a decision or suggestion; ''well then'', ''in that case'', ''so''.\n\n**Formation**: A: Sentence, B: Sentence (A and B can be any sentence type)\n\n**Long**: The A。じゃ、～B。grammar point is used to express a decision, suggestion, or course of action based on a given situation or information. It can be translated as ''well then'', ''in that case'', or ''so'' in English. This grammar works with any form of sentence, whether it''s a verb, noun, い-adjective, or な-adjective in both parts (A and B).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_sorejab','A。それじゃ、～B。',NULL,NULL,'N5','[]','[{"ja":"今日は休みです。それじゃ、映画を観に行きましょう。","en":"Today is a day off. In that case, let''s go watch a movie.","romaji":"Kyou wa yasumi desu. Soreja, eiga wo mi ni ikimashou.","zh":""},{"ja":"電気が切れた。それじゃ、ろうそくを使いましょう。","en":"The electricity went out. In that case, let''s use candles.","romaji":"Denki ga kireta. Soreja, rousoku wo tsukaimashou.","zh":""},{"ja":"レストランが混んでいます。それじゃ、別の場所で食べましょう。","en":"The restaurant is crowded. In that case, let''s eat somewhere else.","romaji":"Resutoran ga kondeimasu. Soreja, betsu no basho de tabemashou.","zh":""},{"ja":"明日は雨が降るらしい。それじゃ、ピクニックは中止しましょう。","en":"It seems it will rain tomorrow. In that case, let''s cancel the picnic.","romaji":"Ashita wa ame ga furu rashii. Soreja, pikunikku wa chuushi shimashou.","zh":""}]',replace('**Short**: Connect two sentences; ''A, so/in that case, B''\n\n**Formation**: Sentence A + 。それじゃ、 + Sentence B\n\n**Long**: The A。それじゃ、～B。grammar point is used to connect two sentences or ideas. It translates to ''A, so/in that case, B'' in English. This expression is used when the first sentence (A) creates a situation or context and the second sentence (B) indicates the consequence or response to that situation.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_soredewab','A。それでは、～B。',NULL,NULL,'N5','[]','[{"ja":"今日は休みだ。それでは、映画を見に行こう。","en":"Today is a day off. In that case, let''s go see a movie.","romaji":"Kyou wa yasumi da. Sore dewa, eiga wo mi ni ikou.","zh":""},{"ja":"このパンはもう古いです。それでは、捨てましょう。","en":"This bread is already old. Then, let''s throw it away.","romaji":"Kono pan wa mou furui desu. Sore dewa, sutemashou.","zh":""},{"ja":"雨が降ってきた。それでは、室内で遊ぼう。","en":"It started raining. In that case, let''s play indoors.","romaji":"Ame ga futtekita. Sore dewa, shitsunai de asobou.","zh":""},{"ja":"お腹が空いた。それでは、何か食べに行きましょう。","en":"I''m hungry. So, let''s go eat something.","romaji":"Onaka ga suita. Sore dewa, nani ka tabe ni ikimashou.","zh":""}]',replace('**Short**: Express a change in situation; ''then'', ''in that case'', ''so''.\n\n**Formation**: A (Statement) + 。それでは、 + B (Follow-up action or statement)\n\n**Long**: The A。それでは、～B。grammar point is used to express a change in situation or transition from one action to another. It can be translated as ''then'', ''in that case'', or ''so'' in English. The formation consists of two sentences or clauses, with それでは connecting them and reflecting a change based on the previous statement (A).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_dewa_b','A。 では、～B。',NULL,NULL,'N5','[]','[{"ja":"果物では、リンゴが一番好きです。","en":"As for fruits, apples are my favorite.","romaji":"Kudamono dewa, ringo ga ichiban suki desu.","zh":""},{"ja":"スポーツでは、サッカーが一番人気です。","en":"As for sports, soccer is the most popular.","romaji":"Supōtsu dewa, sakkā ga ichiban ninki desu.","zh":""},{"ja":"今日の天気では、雨が降りそうです。","en":"As for today''s weather, it looks like it will rain.","romaji":"Kyou no tenki dewa, ame ga furisou desu.","zh":""},{"ja":"料理では、和食が一番得意です。","en":"As for cooking, I am best at Japanese cuisine.","romaji":"Ryouri dewa, washoku ga ichiban tokui desu.","zh":""}]',replace('**Short**: Indicates a contrast or comparison between A and B; ''As for A, ~B''.\n\n**Formation**: Noun A + では、 + Subject + Predicate B\n\n**Long**: The A では、～B grammar point is used to indicate a contrast or comparison between A and B. It is used to express that ''As for A, ~ B'' or ''Regarding A, ~ B''. This grammar structure is often used for contrasting or comparing different subjects/topics.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_demo_b','A。でも、～B。',NULL,NULL,'N5','[]','[{"ja":"昨日は寒かった。でも、今日は暖かいです。","en":"Yesterday was cold. But today it''s warm.","romaji":"Kinou wa samukatta. Demo, kyou wa atatakai desu.","zh":""},{"ja":"彼は忙しい。でも、友達と遊ぶ時間がある。","en":"He is busy. However, he still has time to hang out with friends.","romaji":"Kare wa isogashii. Demo, tomodachi to asobu jikan ga aru.","zh":""},{"ja":"試験に合格した。でも、まだ勉強を続けています。","en":"I passed the exam. But I''m still continuing to study.","romaji":"Shiken ni goukaku shita. Demo, mada benkyou wo tsuzuketeimasu.","zh":""},{"ja":"彼女は有名だ。でも、とても謙虚です。","en":"She is famous. However, she''s very humble.","romaji":"Kanojo wa yuumei da. Demo, totemo kenkyo desu.","zh":""}]',replace('**Short**: Used to express contrast between two statements; ''A, but B'', ''A, however B''.\n\n**Formation**: Clause A + でも + Clause B\n\n**Long**: The A。でも、～B。grammar point is used to express contrast or an unexpected continuation from statement A to statement B. It can be translated as ''A, but B'' or ''A, however B'' in English. The formation simply places でも at the beginning of the second sentence to show contrast with the first sentence.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_to_b_to_dochira','Aと Bと どちら～',NULL,NULL,'N5','[]','[{"ja":"りんごとみかんとどちらが好きですか。","en":"Which do you like, apples or oranges?","romaji":"Ringo to mikan to dochira ga suki desu ka?","zh":""},{"ja":"電車とバスとどちらで行くべきですか。","en":"Should I go by train or bus?","romaji":"Densha to basu to dochira de iku beki desu ka?","zh":""},{"ja":"赤いワンピースと青いワンピースとどちらが似合うと思いますか。","en":"Which do you think suits me better, the red dress or the blue dress?","romaji":"Akai wanpiisu to aoi wanpiisu to dochira ga niau to omoimasu ka?","zh":""},{"ja":"このカメラとあのカメラとどちらのほうが使いやすいですか。","en":"Which one is easier to use, this camera or that camera?","romaji":"Kono kamera to ano kamera to dochira no hou ga tsukaiyasui desu ka?","zh":""}]',replace('**Short**: Used to ask which of two alternatives is preferred or to compare two things\n\n**Formation**: Aと Bと どちら + Verb/Adjective/Noun\n\n**Long**: The grammar pattern Aと Bと どちら～ is used to compare two alternatives A and B, and ask which one is preferred, better, or more suitable. It can be used with verbs, adjectives, or nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_to_b_to_docchi','AとBと どっち〜',NULL,NULL,'N5','[]','[{"ja":"コーヒーと紅茶とどっちが好き？","en":"Which do you like, coffee or tea?","romaji":"Koohii to koucha to docchi ga suki?","zh":""},{"ja":"映画と音楽とどっちを楽しむ？","en":"Which do you enjoy, movies or music?","romaji":"Eiga to ongaku to docchi o tanoshimu?","zh":""},{"ja":"赤いシャツと青いシャツとどっちを買う？","en":"Which one will you buy, the red shirt or the blue shirt?","romaji":"Akai shatsu to aoi shatsu to docchi o kau?","zh":""},{"ja":"日本語と韓国語とどっちを勉強したい？","en":"Which do you want to study, Japanese or Korean?","romaji":"Nihongo to kankokugo to docchi o benkyou shitai?","zh":""}]',replace('**Short**: Asking which one; ''which'', ''A or B''.\n\n**Formation**: AとBと どっち + Verb, AかBか どっち + Verb\n\n**Long**: The  AとBと どっち〜 grammar point is used to ask which one to choose between two options, A and B. It can be translated as ''which'', ''A or B'' in English. This is often used in casual speech and can be shortened to  AかBか どっち〜.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_wa_b_ga','A は B が〜',NULL,NULL,'N5','[]','[{"ja":"彼女は髪が長いです。","en":"What''s special about her is that she has long hair.","romaji":"Kanojo wa kami ga nagai desu.","zh":""},{"ja":"このレストランは雰囲気が良いです。","en":"What''s great about this restaurant is the atmosphere.","romaji":"Kono resutoran wa fun''iki ga ii desu.","zh":""},{"ja":"私は朝ごはんが一番好きです。","en":"What I like the most is breakfast.","romaji":"Watashi wa asagohan ga ichiban suki desu.","zh":""},{"ja":"彼は英語が得意です。","en":"He is particularly good at English.","romaji":"Kare wa eigo ga tokui desu.","zh":""}]',replace('**Short**: Indicates that there is something unique or different about A and describes what is special about it.\n\n**Formation**: A は (Topic) + B が (Characteristic/Feature) + Description/Action\n\n**Long**: The A は B が〜 grammar point is used to emphasize the uniqueness or difference of ''A'' by describing a characteristic or feature ''B'' that is specific to ''A''. This structure is used to convey that there is something notable or special about ''A'' when compared to others.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_wa_b_yori','A は B より～',NULL,NULL,'N5','[]','[{"ja":"このジュースはあのジュースより甘いです。","en":"This juice is sweeter than that juice.","romaji":"Kono juusu wa ano juusu yori amai desu.","zh":""},{"ja":"夏は冬より暑いです。","en":"Summer is hotter than winter.","romaji":"Natsu wa fuyu yori atsui desu.","zh":""},{"ja":"彼女は私より速く走ります。","en":"She runs faster than me.","romaji":"Kanojo wa watashi yori hayaku hashirimasu.","zh":""},{"ja":"スーパーはコンビニより安いです。","en":"The supermarket is cheaper than the convenience store.","romaji":"Suupaa wa konbini yori yasui desu.","zh":""}]',replace('**Short**: Express a comparison between A and B; ''A is more/less than B''.\n\n**Formation**: A は B より + Adjective\n\n**Long**: The A は B より grammar point is used to express a comparison between two items or subjects (A and B). It can be translated as ''A is more/less than B'' in English. This structure is followed by an adjective that describes the comparison.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_yori_b_no_hou_ga_n5','A より B のほうが～',NULL,NULL,'N5','[]','[{"ja":"ピザよりハンバーガーのほうが美味しい。","en":"Hamburgers are more delicious than pizza.","romaji":"Piza yori hanbaagaa no hou ga oishii.","zh":""},{"ja":"夏より冬のほうが寒い。","en":"Winter is colder than summer.","romaji":"Natsu yori fuyu no hou ga samui.","zh":""},{"ja":"ここよりそこのほうが静かです。","en":"There is quieter than here.","romaji":"Koko yori soko no hou ga shizuka desu.","zh":""},{"ja":"車より電車のほうが速い。","en":"Trains are faster than cars.","romaji":"Kuruma yori densha no hou ga hayai.","zh":""}]',replace('**Short**: Used to compare two items; ''B is more ～ than A''.\n\n**Formation**: A + より + B + のほうが + Adjective\n\n**Long**: The grammar point A より B のほうが～ is used to compare two items or situations and indicate that one is more (adjective) than the other. It can be translated as ''B is more ～ than A'' in English. It is used with both い-adjectives and な-adjectives.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_i_adjective_ku_verb','い-Adjective く + Verb',NULL,NULL,'N5','[]','[{"ja":"彼は速く走りました。","en":"He ran quickly.","romaji":"Kare wa hayaku hashirimashita.","zh":""},{"ja":"この料理は美味しく食べました。","en":"I enjoyed eating this dish.","romaji":"Kono ryouri wa oishiku tabemashita.","zh":""},{"ja":"彼女は優しく話します。","en":"She speaks kindly.","romaji":"Kanojo wa yasashiku hanashimasu.","zh":""},{"ja":"母は忙しく仕事をしています。","en":"My mother is working busily.","romaji":"Haha wa isogashiku shigoto o shite imasu.","zh":""}]',replace('**Short**: Used to connect an い-adjective to a verb, modifying the verb (adverbial usage).\n\n**Formation**: い-Adjective (remove い) + く + Verb\n\n**Long**: The い-Adjective + く + Verb grammar point transforms an い-adjective into its adverbial form, describing how the verb is performed. In English, this often corresponds to ''-ly'' adverbs (e.g., ''quickly'', ''slowly'').\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_i_adjective_ku_shimasu','い-Adjective く します',NULL,NULL,'N5','[]','[{"ja":"部屋を明るくします。","en":"I will make the room brighter.","romaji":"Heya o akaruku shimasu.","zh":""},{"ja":"友達の気分を楽しくします。","en":"I will make my friend’s mood more pleasant.","romaji":"Tomodachi no kibun o tanoshiku shimasu.","zh":""},{"ja":"仕事が簡単になるように、やり方を早くします。","en":"I will make the way of doing things faster so that the work becomes easier.","romaji":"Shigoto ga kantan ni naru you ni, yarikata o hayaku shimasu.","zh":""},{"ja":"食べ物を美味しくします。","en":"I will make the food delicious.","romaji":"Tabemono o oishiku shimasu.","zh":""}]',replace('**Short**: Use an い-adjective to express ''to make'' or ''to become''.\n\n**Formation**: い-Adjective (remove い) + くします\n\n**Long**: By adding くします to an い-adjective, you express making something (or causing something to become) the quality of that adjective. In English, this often corresponds to phrases like ''make something more ADJECTIVE.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_adjective_negative_polite_form','い-Adjective: Negative Polite Form',NULL,NULL,'N5','[]','[{"ja":"このピザは美味しくないです。","en":"This pizza is not delicious.","romaji":"Kono piza wa oishiku nai desu.","zh":""},{"ja":"この部屋は広くないです。","en":"This room is not spacious.","romaji":"Kono heya wa hiroku nai desu.","zh":""},{"ja":"彼の意見は面白くないです。","en":"His opinion is not interesting.","romaji":"Kare no iken wa omoshiroku nai desu.","zh":""},{"ja":"その映画は楽しくありません。","en":"That movie is not enjoyable.","romaji":"Sono eiga wa tanoshiku arimasen.","zh":""}]',replace('**Short**: Change an い-adjective into a polite negative form with ～くないです (or ～くありません).\n\n**Formation**: い-Adjective (remove い) + くないです\n\n**Long**: To make an い-adjective negative and polite, remove the final い and add くないです. An alternative more formal style is くありません. For example, 美味しい → 美味しくないです / 美味しくありません。\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_i_adjective_te','い-Adjective て',NULL,NULL,'N5','[]','[{"ja":"このリンゴは甘くて美味しいです。","en":"This apple is sweet and delicious.","romaji":"Kono ringo wa amakute oishii desu.","zh":""},{"ja":"彼女は優しくてかわいいです。","en":"She is kind and cute.","romaji":"Kanojo wa yasashikute kawaii desu.","zh":""},{"ja":"映画は面白くて感動的でした。","en":"The movie was interesting and moving.","romaji":"Eiga wa omoshirokute kandouteki deshita.","zh":""},{"ja":"この部屋は広くて明るいです。","en":"This room is spacious and bright.","romaji":"Kono heya wa hirokute akarui desu.","zh":""}]',replace('**Short**: Used to connect two or more い-adjectives to describe something.\n\n**Formation**: い-Adjective (remove い) + くて + い-Adjective\n\n**Long**: The い-Adjective て form is used to connect two or more い-adjectives when listing attributes of something or someone. To form it, replace the final い with くて. For example, かわいい → かわいくて, おいしい → おいしくて.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_adjective_verb','な-Adjective に + Verb',NULL,NULL,'N5','[]','[{"ja":"彼は静かに話す。","en":"He speaks quietly.","romaji":"Kare wa shizuka ni hanasu.","zh":""},{"ja":"部屋をきれいに掃除した。","en":"I cleaned the room neatly.","romaji":"Heya o kirei ni souji shita.","zh":""},{"ja":"彼女は元気に働いています。","en":"She works energetically.","romaji":"Kanojo wa genki ni hataraite imasu.","zh":""},{"ja":"先生は親切に説明してくれる。","en":"The teacher explains kindly.","romaji":"Sensei wa shinsetsu ni setsumei shite kureru.","zh":""}]',replace('**Short**: Turn a な-adjective into an adverb by adding に.\n\n**Formation**: な-Adjective (remove な) + に + Verb\n\n**Long**: To make a な-adjective modify a verb, remove the な and add に. This form describes how an action is performed. For instance, 静か（な） → 静かに, 親切（な） → 親切に.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_na_adjective_de','な-Adjective で～',NULL,NULL,'N5','[]','[{"ja":"彼は綺麗で優しい女性が好きです。","en":"He likes women who are beautiful and kind.","romaji":"Kare wa kirei de yasashii josei ga suki desu.","zh":""},{"ja":"この料理は健康的で、元気な気分になります。","en":"This dish is healthy and makes you feel energetic.","romaji":"Kono ryouri wa kenkouteki de, genki na kibun ni narimasu.","zh":""},{"ja":"彼は静かで落ち着いた環境で仕事をしたい。","en":"He wants to work in a quiet and calm environment.","romaji":"Kare wa shizuka de ochitsuita kankyou de shigoto o shitai.","zh":""},{"ja":"この部屋は清潔で気持ちがいいです。","en":"This room is clean and feels good.","romaji":"Kono heya wa seiketsu de kimochi ga ii desu.","zh":""}]',replace('**Short**: Usage of で to connect or add information with a な-adjective.\n\n**Formation**: な-Adjective + で\n\n**Long**: Use な-adjective + で to connect it to another quality, action, or description. It can combine a な-adjective with another adjective, verb, or clause.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_na_adjective_ni_shimasu','な-Adjective に します',NULL,NULL,'N5','[]','[{"ja":"静かにします。","en":"I will be quiet.","romaji":"Shizuka ni shimasu.","zh":""},{"ja":"部屋をきれいにします。","en":"I will make the room clean.","romaji":"Heya o kirei ni shimasu.","zh":""},{"ja":"明日の会議は簡単にします。","en":"I will make tomorrow’s meeting simple.","romaji":"Ashita no kaigi wa kantan ni shimasu.","zh":""},{"ja":"健康的な食事にします。","en":"I will choose a healthy meal.","romaji":"Kenkou-teki na shokuji ni shimasu.","zh":""}]',replace('**Short**: Expressing a decision or preference with a な-adjective.\n\n**Formation**: な-Adjective + に + します\n\n**Long**: The な-adjective に します pattern is used to express a decision or choice based on a な-adjective. It often translates as ''I’ll make it ...,'' ''I will choose ...,'' or ''I’ve decided on ...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_na_adjective_ni_narimasu','な-Adjective に なります',NULL,NULL,'N5','[]','[{"ja":"この部屋は静かになります。","en":"This room becomes quiet.","romaji":"Kono heya wa shizuka ni narimasu.","zh":""},{"ja":"彼女はきれいになります。","en":"She becomes beautiful.","romaji":"Kanojo wa kirei ni narimasu.","zh":""},{"ja":"彼は元気になります。","en":"He becomes energetic.","romaji":"Kare wa genki ni narimasu.","zh":""},{"ja":"町はにぎやかになります。","en":"The town becomes lively.","romaji":"Machi wa nigiyaka ni narimasu.","zh":""}]',replace('**Short**: Express a change or transformation into a state described by the な-adjective.\n\n**Formation**: な-Adjective (remove な) + に + なります\n\n**Long**: The な-Adjective + に + なります grammar point is used to express a change or transformation into the state described by the な-adjective. It translates to ''become'' or ''turn into'' along with the meaning of the な-adjective.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_ka_noun_ka','Noun か Noun か～',NULL,NULL,'N5','[]','[{"ja":"今日、映画を見るか、散歩するかどちらにしますか？","en":"Will we watch a movie or go for a walk today?","romaji":"Kyou, eiga wo miru ka, sanpo suru ka dochira ni shimasu ka?","zh":""},{"ja":"コーヒーか紅茶か、一つだけ選んでください。","en":"Please choose only one, either coffee or tea.","romaji":"Koohii ka koucha ka, hitotsu dake erande kudasai.","zh":""},{"ja":"電車かバスを使って、学校に行くつもりです。","en":"I plan to go to school using either the train or the bus.","romaji":"Densha ka basu o tsukatte, gakkou ni iku tsumori desu.","zh":""},{"ja":"週末は山に登るか海に行くか、まだ決めていません。","en":"I haven''t decided whether to climb the mountain or go to the beach this weekend.","romaji":"Shuumatsu wa yama ni noboru ka umi ni iku ka, mada kimete imasen.","zh":""}]',replace('**Short**: Expresses choice or alternatives; ''either'', ''or''.\n\n**Formation**: Noun1 + か + Noun2 + か～\n\n**Long**: The Noun か Noun か～ grammar point is used to present two or more alternatives for a choice. It can be translated to ''either'', ''or'' in English. It is formed by placing the particle か in between two nouns or noun phrases.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_ga_dekimasu','Noun が できます',NULL,NULL,'N5','[]','[{"ja":"英語ができます。","en":"I can speak English.","romaji":"Eigo ga dekimasu.","zh":""},{"ja":"料理ができます。","en":"I can cook.","romaji":"Ryouri ga dekimasu.","zh":""},{"ja":"彼は泳ぎができます。","en":"He can swim.","romaji":"Kare wa oyogi ga dekimasu.","zh":""},{"ja":"彼女はピアノができます。","en":"She can play the piano.","romaji":"Kanojo wa piano ga dekimasu.","zh":""}]',replace('**Short**: Express the ability to do something.\n\n**Formation**: Noun + が + できます\n\n**Long**: The Noun が できます grammar point is used to express the ability to do something. In this grammar pattern, the noun is the activity that the speaker or subject can do. It translates as ''can do'' or ''able to do'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ga_hoshii_desu','Noun がほしいです',NULL,NULL,'N5','[]','[{"ja":"新しい車がほしいです。","en":"I want a new car.","romaji":"Atarashii kuruma ga hoshii desu.","zh":""},{"ja":"コーヒーがほしいです。","en":"I would like some coffee.","romaji":"Koohii ga hoshii desu.","zh":""},{"ja":"彼女は花がほしいです。","en":"She wants flowers.","romaji":"Kanojo wa hana ga hoshii desu.","zh":""},{"ja":"友達がほしいです。","en":"I want a friend.","romaji":"Tomodachi ga hoshii desu.","zh":""}]',replace('**Short**: Express a desire or wanting something; ''I want'', ''I would like''.\n\n**Formation**: Noun + が + ほしいです\n\n**Long**: The がほしいです grammar point is used to express a desire or the act of wanting something in polite form. It can be translated as ''I want'' or ''I would like'' in English. It is used with a noun and the particle が.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_kara_noun_made','Noun から Noun まで',NULL,NULL,'N5','[]','[{"ja":"朝9時から午後5時まで働きます。","en":"I work from 9 AM to 5 PM.","romaji":"Asa ku-ji kara gogo go-ji made hatarakimasu.","zh":""},{"ja":"東京から大阪まで電車で行く。","en":"I will go by train from Tokyo to Osaka.","romaji":"Toukyou kara Osaka made densha de iku.","zh":""},{"ja":"地下鉄は午前6時から深夜まで運行しています。","en":"The subway runs from 6 AM until midnight.","romaji":"Chikatetsu wa gozen roku-ji kara shin''ya made unkou shite imasu.","zh":""},{"ja":"月曜日から金曜日まで学校に通います。","en":"I attend school from Monday to Friday.","romaji":"Getsuyoubi kara Kinyoubi made gakkou ni kayoimasu.","zh":""}]',replace('**Short**: Expresses a range; ''from...to'', ''between...and''.\n\n**Formation**: Noun1 + から + Noun2 + まで\n\n**Long**: The から...まで grammar point is used to express a range between two nouns, indicating the starting point and ending point of an action, event, or period of time. It can be translated as ''from...to'' or ''between...and'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_kurai','Noun くらい～',NULL,NULL,'N5','[]','[{"ja":"この本は三百ページくらいあります。","en":"This book has about 300 pages.","romaji":"Kono hon wa sanbyaku peeji kurai arimasu.","zh":""},{"ja":"彼の家まで歩いて20分くらいかかります。","en":"It takes about 20 minutes to walk to his house.","romaji":"Kare no ie made aruite nijuppun kurai kakarimasu.","zh":""},{"ja":"明日は暑くて、30度くらいになるでしょう。","en":"Tomorrow will be hot, about 30 degrees.","romaji":"Ashita wa atsukute, sanjuu-do kurai ni naru deshou.","zh":""},{"ja":"この料理を作るのに、材料は500円くらい必要です。","en":"You need about 500 yen worth of ingredients to make this dish.","romaji":"Kono ryouri o tsukuru no ni, zairyou wa gohyaku-en kurai hitsuyou desu.","zh":""}]',replace('**Short**: Express the extent or degree of something; ''about'', ''approximately'', ''at least''.\n\n**Formation**: Noun + くらい\n\n**Long**: The くらい grammar point is used with a noun to express the extent or degree of something, meaning ''about'', ''approximately'', or ''at least'' in English. It helps to provide a rough estimate or minimum standard to the noun it is attached to.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_gurai','Noun ぐらい～',NULL,NULL,'N5','[]','[{"ja":"一日中勉強したので、１０時間ぐらい勉強しました。","en":"I studied all day, so I studied for about 10 hours.","romaji":"Ichinichijuu benkyou shita node, juu-jikan gurai benkyou shimashita.","zh":""},{"ja":"この本は１００ページぐらいある。","en":"This book has about 100 pages.","romaji":"Kono hon wa hyaku peeji gurai aru.","zh":""},{"ja":"彼は果物を５個ぐらい食べました。","en":"He ate about 5 pieces of fruit.","romaji":"Kare wa kudamono o go-ko gurai tabemashita.","zh":""},{"ja":"駅から家まで歩いて２０分ぐらいかかります。","en":"It takes about 20 minutes to walk from the station to my house.","romaji":"Eki kara ie made aruite nijuppun gurai kakarimasu.","zh":""}]',replace('**Short**: Express an approximate amount or degree; ''about'', ''approximately''.\n\n**Formation**: Noun + ぐらい\n\n**Long**: The ぐらい grammar point is used with nouns to express an approximate amount or degree. It is often translated as ''about'', ''approximately'', or ''around'' in English. This can be used for time, quantity, or other measurements.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_goro','Noun ごろ～',NULL,NULL,'N5','[]','[{"ja":"昼ごろに電話してください。","en":"Please call me around noon.","romaji":"Hiru goro ni denwa shite kudasai.","zh":""},{"ja":"彼は10歳ごろに日本に来ました。","en":"He came to Japan around the age of 10.","romaji":"Kare wa juu-sai goro ni Nihon ni kimashita.","zh":""},{"ja":"午後３時ごろに会いましょう。","en":"Let''s meet around 3 PM.","romaji":"Gogo san-ji goro ni aimashou.","zh":""},{"ja":"昨日の夜8時ごろに帰りました。","en":"I returned home last night around 8 o''clock.","romaji":"Kinou no yoru hachi-ji goro ni kaerimashita.","zh":""}]',replace('**Short**: Expresses ''around'' or ''about'' a certain time or age.\n\n**Formation**: Noun + ごろ\n\n**Long**: The ごろ grammar point is used to indicate ''around'' or ''about'' a certain time or age. It is commonly used with time-related expressions and age-related expressions to give an approximate time or age.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dake','Noun だけ〜',NULL,NULL,'N5','[]','[{"ja":"コーヒーだけ飲んで、帰りました。","en":"I only drank coffee and went home.","romaji":"Koohii dake nonde, kaerimashita.","zh":""},{"ja":"この本は二十ページだけ読んだ。","en":"I only read twenty pages of this book.","romaji":"Kono hon wa nijuu peeji dake yonda.","zh":""},{"ja":"彼女はとても速いですが、走るだけでなく、考えるのも速いです。","en":"She is very fast, not only at running but also at thinking.","romaji":"Kanojo wa totemo hayai desu ga, hashiru dake denaku, kangaeru no mo hayai desu.","zh":""},{"ja":"この部屋は寝るだけの場所です。","en":"This room is a place only for sleeping.","romaji":"Kono heya wa neru dake no basho desu.","zh":""}]',replace('**Short**: Indicates ''only'', ''just'', or ''merely''.\n\n**Formation**: Noun + だけ, Verb-casual + だけ, い-Adjective + だけ, な-Adjective-な + だけ\n\n**Long**: The Noun だけ grammar point is used to emphasize the idea of ''only'', ''just'', or ''merely'' in a sentence. It can be attached to nouns, verbs, い-adjectives, and な-adjectives to show this emphasis. This grammar point is commonly used in both spoken and written Japanese.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_de','Nounで～',NULL,NULL,'N5','[]','[{"ja":"図書館で勉強します。","en":"I study at the library.","romaji":"Toshokan de benkyou shimasu.","zh":""},{"ja":"バスで学校に行きます。","en":"I go to school by bus.","romaji":"Basu de gakkou ni ikimasu.","zh":""},{"ja":"鉛筆で書きました。","en":"I wrote it using a pencil.","romaji":"Enpitsu de kakimashita.","zh":""},{"ja":"英語で話しましょう。","en":"Let''s talk in English.","romaji":"Eigo de hanashimashou.","zh":""}]',replace('**Short**: Indicate a place or means for an action or situation; ''at, in, on'', ''using'', or ''by means of''.\n\n**Formation**: Noun + で\n\n**Long**: The で grammar point is used to indicate a location, method, or tool for doing an action or for being in a situation. It can be translated as ''at, in, on'', ''using'', or ''by means of'' in English. Nounで is formed by adding で after a noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_to','Noun と～',NULL,NULL,'N5','[]','[{"ja":"リンゴとバナナを買いました。","en":"I bought apples and bananas.","romaji":"Ringo to banana wo kaimashita.","zh":""},{"ja":"友達と映画を見に行きます。","en":"I will go to watch a movie with my friend.","romaji":"Tomodachi to eiga wo mi ni ikimasu.","zh":""},{"ja":"父と母と一緒に旅行しました。","en":"I traveled together with my father and mother.","romaji":"Chichi to haha to issho ni ryokou shimashita.","zh":""},{"ja":"彼と彼女は結婚しました。","en":"He and she got married.","romaji":"Kare to kanojo wa kekkon shimashita.","zh":""}]',replace('**Short**: Express ''with'', ''and'' or ''together with'' when connecting nouns.\n\n**Formation**: Noun1 + と + Noun2\n\n**Long**: The Noun と grammar point is used to express a connection between two or more nouns, indicating ''with'', ''and'', or ''together with'' in English. It functions as a particle that is used to simply list multiple items or express companionship.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_ni','Noun に～',NULL,NULL,'N5','[]','[{"ja":"彼女にプレゼントをあげました。","en":"I gave a present to her.","romaji":"Kanojo ni purezento wo agemashita.","zh":""},{"ja":"日本に行きます。","en":"I am going to Japan.","romaji":"Nihon ni ikimasu.","zh":""},{"ja":"6時に集合しましょう。","en":"Let''s meet at 6 o''clock.","romaji":"Roku-ji ni shuugou shimashou.","zh":""},{"ja":"友達に手紙を書きます。","en":"I will write a letter to my friend.","romaji":"Tomodachi ni tegami wo kakimasu.","zh":""}]',replace('**Short**: Express a specific direction, target or purpose; ''to'', ''toward'', ''for''.\n\n**Formation**: Noun + に\n\n**Long**: The ''Noun に'' grammar point is used to express a specific direction, target, or purpose in relation to a noun. It can be translated as ''to'', ''toward'', or ''for'' in English. The に particle is added directly after the noun which indicates direction, target or purpose.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_ni_kaerimasu','Noun に 帰ります',NULL,NULL,'N5','[]','[{"ja":"夏休みが終わったら、学校に帰ります。","en":"When summer vacation ends, I''ll go back to school.","romaji":"Natsuyasumi ga owattara, gakkou ni kaerimasu.","zh":""},{"ja":"買い物を終えたら、家に帰ります。","en":"After finishing shopping, I will go back home.","romaji":"Kaimono o oetara, ie ni kaerimasu.","zh":""},{"ja":"今週末、実家に帰ります。","en":"I''m going back to my parents'' home this weekend.","romaji":"Konshuumatsu, jikka ni kaerimasu.","zh":""},{"ja":"友達と旅行に行ったあと、東京に帰ります。","en":"After traveling with my friend, I''ll return to Tokyo.","romaji":"Tomodachi to ryokou ni itta ato, Toukyou ni kaerimasu.","zh":""}]',replace('**Short**: Express going back or returning to a place: ''to return to'', ''to go back to''.\n\n**Formation**: Noun + に + 帰ります\n\n**Long**: The grammar point ''Noun に 帰ります'' is used to express physically going back or returning to a specific place. It can be translated as ''to go back to'' or ''to return to'' in English. The particle に indicates the destination of the return.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_ni_shimasu','Noun に します',NULL,NULL,'N5','[]','[{"ja":"今日の昼ご飯は寿司にします。","en":"I''ll choose sushi for today''s lunch.","romaji":"Kyou no hirugohan wa sushi ni shimasu.","zh":""},{"ja":"この靴を買うか迷っていますが、赤い色の方にします。","en":"I was hesitating about which shoes to buy, but I''ll go with the red ones.","romaji":"Kono kutsu wo kau ka mayotteimasu ga, akai iro no hou ni shimasu.","zh":""},{"ja":"休みの日に何をするか決めた。映画館に行くことにします。","en":"I''ve decided what to do on my day off. I''ll go to the movie theater.","romaji":"Yasumi no hi ni nani wo suru ka kimeta. Eigakan ni iku koto ni shimasu.","zh":""},{"ja":"フランス語とスペイン語のどちらを勉強するか悩んだが、フランス語にします。","en":"I was torn between studying French and Spanish, but I decided on French.","romaji":"Furansugo to Supeingo no dochira wo benkyou suru ka nayanda ga, Furansugo ni shimasu.","zh":""}]',replace('**Short**: Express a choice or decision; ''choose'', ''decide on''.\n\n**Formation**: Noun + に します\n\n**Long**: The に します grammar point is used to express making a choice or decision. It can be translated as ''choose'' or ''decide on'' in English. It is often used in situations where someone has to make a selection or decide on something, such as ordering food at a restaurant or deciding on a vacation destination.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_ni_narimasu','Noun に なります',NULL,NULL,'N5','[]','[{"ja":"彼は医者になります。","en":"He will become a doctor.","romaji":"Kare wa isha ni narimasu.","zh":""},{"ja":"この茶色の葉が赤になります。","en":"These brown leaves will turn red.","romaji":"Kono chairo no ha ga aka ni narimasu.","zh":""},{"ja":"料理が冷めたら、美味しくなくなります。","en":"When the dish cools down, it becomes less delicious.","romaji":"Ryouri ga sametara, oishikunaku narimasu.","zh":""},{"ja":"来年、東京オリンピックになります。","en":"Next year, it will be the Tokyo Olympics.","romaji":"Rainen, Toukyou Orinpikku ni narimasu.","zh":""}]',replace('**Short**: Expresses change or becoming something; ''to become'', ''to turn into'', ''to be''.\n\n**Formation**: Noun + に + なります\n\n**Long**: The grammar point Noun に なります is used to express a change or transformation into something else, or to indicate that something ''becomes'', ''turns into'', or simply ''is'' something. It is commonly used with nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_ni_kimasu','Noun に 来ます',NULL,NULL,'N5','[]','[{"ja":"友達が私の家に来ます。","en":"My friend will come to my house.","romaji":"Tomodachi ga watashi no ie ni kimasu.","zh":""},{"ja":"今晩、父が駅に迎えに来ます。","en":"Tonight, my father will come to pick me up at the station.","romaji":"Konban, chichi ga eki ni mukae ni kimasu.","zh":""},{"ja":"明日、先生が学校に来ます。","en":"Tomorrow, the teacher will come to school.","romaji":"Ashita, sensei ga gakkou ni kimasu.","zh":""},{"ja":"有名な歌手がこの街に来ます。","en":"A famous singer will come to this town.","romaji":"Yuumei na kashu ga kono machi ni kimasu.","zh":""}]',replace('**Short**: Used to express coming to a place.\n\n**Formation**: Noun + に + 来ます (kimasu)\n\n**Long**: The grammar point Noun に 来ます is used to indicate that someone or something comes to a specific place. The noun before に indicates the destination or place, while the verb 来ます expresses the action of coming. (Similarly, ''Noun に 行きます'' means ''go to [Noun],'' and ''Noun に 帰ります'' means ''return to [Noun].'')\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_ni_ikimasu','Noun に 行きます',NULL,NULL,'N5','[]','[{"ja":"学校に行きます。","en":"I will go to school.","romaji":"Gakkou ni ikimasu.","zh":""},{"ja":"明日、スーパーに行きます。","en":"I will go to the supermarket tomorrow.","romaji":"Ashita, suupaa ni ikimasu.","zh":""},{"ja":"週末に映画館に行きます。","en":"I will go to the movie theater on the weekend.","romaji":"Shuumatsu ni eigakan ni ikimasu.","zh":""},{"ja":"夏休みに海に行きます。","en":"I will go to the sea during the summer vacation.","romaji":"Natsu yasumi ni umi ni ikimasu.","zh":""}]',replace('**Short**: Used to express going to a location.\n\n**Formation**: Noun + に + 行きます\n\n**Long**: The Noun に 行きます grammar point is used to express going to a specific location. This structure requires a noun (indicating the destination) followed by に and the verb 行きます, which means ''to go''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_no_atode','Noun の あとで',NULL,NULL,'N5','[]','[{"ja":"朝ご飯のあとで、歯を磨きます。","en":"After breakfast, I brush my teeth.","romaji":"Asagohan no atode, ha wo migakimasu.","zh":""},{"ja":"映画のあとで、レストランで夕食を食べました。","en":"After the movie, we ate dinner at a restaurant.","romaji":"Eiga no atode, resutoran de yuushoku o tabemashita.","zh":""},{"ja":"会議のあとで、上司と話し合います。","en":"I will discuss with my boss after the meeting.","romaji":"Kaigi no atode, joushi to hanashiaimasu.","zh":""},{"ja":"晩ご飯のあとで、散歩に行きました。","en":"After dinner, I went for a walk.","romaji":"Bangohan no atode, sanpo ni ikimashita.","zh":""}]',replace('**Short**: Expresses the order of events; ''after'', ''later than''.\n\n**Formation**: Noun + の + あとで\n\n**Long**: The の あとで grammar point is used to express the order of events, specifying that an action occurs after or later than the noun mentioned. It translates to ''after'' or ''later than'' in English. This structure is simply formed by attaching の あとで to the noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_no_mae_ni','Noun の 前に',NULL,NULL,'N5','[]','[{"ja":"駅の前にコンビニがあります。","en":"There is a convenience store in front of the station.","romaji":"Eki no mae ni konbini ga arimasu.","zh":""},{"ja":"家の前に車を止めてください。","en":"Please park the car in front of the house.","romaji":"Ie no mae ni kuruma wo tomete kudasai.","zh":""},{"ja":"私の前に彼が立っていました。","en":"He was standing in front of me.","romaji":"Watashi no mae ni kare ga tatte imashita.","zh":""},{"ja":"ホテルの前にタクシーが来た。","en":"A taxi came in front of the hotel.","romaji":"Hoteru no mae ni takushii ga kita.","zh":""}]',replace('**Short**: Used to describe a location or position ''in front of'' a noun.\n\n**Formation**: Noun + の + 前に\n\n**Long**: The grammar point Noun の 前に is used to describe a location or position ''in front of'' a noun. It is formed by adding の 前に after the noun it refers to. (Note that ''Noun の 前に'' can also mean ''before [Noun]'' in time contexts, but these examples focus on physical location.)\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wa','Noun は～',NULL,NULL,'N5','[]','[{"ja":"私は日本の料理が好きです。","en":"As for me, I like Japanese cuisine.","romaji":"Watashi wa Nihon no ryouri ga suki desu.","zh":""},{"ja":"彼は英語が上手です。","en":"As for him, he is good at English.","romaji":"Kare wa eigo ga jouzu desu.","zh":""},{"ja":"この本は面白いです。","en":"As for this book, it''s interesting.","romaji":"Kono hon wa omoshiroi desu.","zh":""},{"ja":"今日は暑いですね。","en":"Speaking of today, it''s hot, isn''t it?","romaji":"Kyou wa atsui desu ne.","zh":""}]',replace('**Short**: Used to mark the topic of a sentence; ''as for'', ''speaking of''.\n\n**Formation**: Noun + は\n\n**Long**: The は (wa) particle is used to indicate the topic of a sentence. It is usually translated as ''as for'', ''speaking of'', or it simply marks what the sentence is about. This is different from が (ga), which marks the subject of a verb.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_mo','Noun も〜',NULL,NULL,'N5','[]','[{"ja":"私も日本語を勉強しています。","en":"I am also studying Japanese.","romaji":"Watashi mo nihongo wo benkyou shiteimasu.","zh":""},{"ja":"彼もケーキが好きです。","en":"He also likes cake.","romaji":"Kare mo keeki ga suki desu.","zh":""},{"ja":"東京も大阪も観光スポットがたくさんあります。","en":"There are many tourist spots in both Tokyo and Osaka.","romaji":"Toukyou mo Oosaka mo kankou supotto ga takusan arimasu.","zh":""},{"ja":"この映画もあの映画も面白かった。","en":"Both this movie and that movie were interesting.","romaji":"Kono eiga mo ano eiga mo omoshirokatta.","zh":""}]',replace('**Short**: Indicates that the action or state is the same for multiple items or people; ''also'', ''as well''.\n\n**Formation**: Noun + も\n\n**Long**: The も grammar point is used after a noun to indicate that the action or state is the same for multiple items or people. It means ''also'', ''as well'', or ''too'' in English. も often replaces は or が in the sentence to show that the same statement applies to this additional noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_ya_noun_nado','Noun や Noun など～',NULL,NULL,'N5','[]','[{"ja":"彼は野菜や果物などを食べるのが好きです。","en":"He likes to eat things like vegetables and fruits.","romaji":"Kare wa yasai ya kudamono nado o taberu no ga suki desu.","zh":""},{"ja":"日本の都市や東京、大阪などに行きたいです。","en":"I want to go to Japanese cities such as Tokyo, Osaka, and so on.","romaji":"Nihon no toshi ya Toukyou, Oosaka nado ni ikitai desu.","zh":""},{"ja":"彼女は猫や犬など動物が好きです。","en":"She likes animals like cats, dogs, and so on.","romaji":"Kanojo wa neko ya inu nado doubutsu ga suki desu.","zh":""},{"ja":"この本屋では漫画や小説などたくさんの本が売られています。","en":"In this bookstore, many books such as manga and novels are sold.","romaji":"Kono honya de wa manga ya shousetsu nado takusan no hon ga urarete imasu.","zh":""}]',replace('**Short**: Lists items or examples but not exhaustively; ''such as'', ''like'', ''and so on''.\n\n**Formation**: Noun1 + や + Noun2 + など\n\n**Long**: The や...など grammar point is used to list a few items or examples that belong to a similar category or context, but it is not exhaustive. It can be translated as ''such as'', ''like'', or ''and so on'' in English. This grammar pattern is used with nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wo','Noun を〜',NULL,NULL,'N5','[]','[{"ja":"私は本を読みます。","en":"I read a book.","romaji":"Watashi wa hon wo yomimasu.","zh":""},{"ja":"彼はケーキを食べました。","en":"He ate a cake.","romaji":"Kare wa keeki wo tabemashita.","zh":""},{"ja":"母はコーヒーを飲むのが好きです。","en":"My mother likes to drink coffee.","romaji":"Haha wa koohii wo nomu no ga suki desu.","zh":""},{"ja":"友達が私のペンを使いました。","en":"My friend used my pen.","romaji":"Tomodachi ga watashi no pen wo tsukaimashita.","zh":""}]',replace('**Short**: Indicates the direct object of a verb.\n\n**Formation**: Noun + を + Verb\n\n**Long**: The を (wo) particle is used to mark the direct object of a verb in a sentence. It shows the noun that the action (verb) is performed on. The particle を is usually pronounced as ''o'' in spoken Japanese.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ta_ato_de','Verb た あとで',NULL,NULL,'N5','[]','[{"ja":"宿題をしたあとで、テレビを見ました。","en":"After doing my homework, I watched TV.","romaji":"Shukudai wo shita ato de, terebi wo mimashita.","zh":""},{"ja":"朝ごはんを食べたあとで、歯を磨きます。","en":"After eating breakfast, I brush my teeth.","romaji":"Asagohan wo tabeta ato de, ha wo migakimasu.","zh":""},{"ja":"仕事が終わったあとで、ジムに行く予定です。","en":"After finishing work, I plan to go to the gym.","romaji":"Shigoto ga owatta ato de, jimu ni iku yotei desu.","zh":""},{"ja":"映画を見たあとで、カフェでコーヒーを飲みました。","en":"After watching the movie, I drank coffee at a cafe.","romaji":"Eiga wo mita ato de, kafe de koohii wo nomimashita.","zh":""}]',replace('**Short**: Indicates an action that takes place after another action.\n\n**Formation**: Verb-た form + あとで\n\n**Long**: The たあとで grammar point is used to indicate that one action takes place after another action is completed. It means ''after'' or ''after doing'' in English. The formation is created with the た form (past tense) of a verb, followed by あとで (ato de).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_taidesu','Verb たいです',NULL,NULL,'N5','[]','[{"ja":"私は寿司を食べたいです。","en":"I want to eat sushi.","romaji":"Watashi wa sushi wo tabetai desu.","zh":""},{"ja":"彼は日本に行きたいです。","en":"He wants to go to Japan.","romaji":"Kare wa Nihon ni ikitai desu.","zh":""},{"ja":"彼女は英語を勉強したいです。","en":"She wants to study English.","romaji":"Kanojo wa eigo wo benkyou shitai desu.","zh":""},{"ja":"子供たちは遊びたいです。","en":"The children want to play.","romaji":"Kodomo-tachi wa asobitai desu.","zh":""}]',replace('**Short**: Express desire or want to do something; ''I want to'', ''I would like to''.\n\n**Formation**: る-Verb: Remove る and add たいです, う-Verb: Replace the final verb character with the ～い form and add たいです, Exception: する becomes したいです\n\n**Long**: The たいです grammar point is used to express the speaker''s desire or want to perform a certain action. It can be translated as ''I want to'' or ''I would like to'' in English. The formation differs depending on whether the verb is a る-verb or an う-verb.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te','Verb て～',NULL,NULL,'N5','[]','[{"ja":"コーヒーを飲んで、出かけます。","en":"After drinking coffee, I will go out.","romaji":"Koohii o nonde, dekakemasu.","zh":""},{"ja":"買い物をして、家に帰りましょう。","en":"Let''s go shopping and then go home.","romaji":"Kaimono o shite, ie ni kaerimashou.","zh":""},{"ja":"宿題をして、寝ます。","en":"After doing my homework, I will sleep.","romaji":"Shukudai o shite, nemasu.","zh":""},{"ja":"友達を待って、一緒に映画を見に行きます。","en":"I will wait for my friend and go watch a movie together.","romaji":"Tomodachi o matte, issho ni eiga o mini ikimasu.","zh":""}]',replace('**Short**: A verb conjugation that connects actions or states.\n\n**Formation**: Verb (Group 1) - Replace last syllable with 〜て, Verb (Group 2) - Replace ''る'' with 〜て, Verb (Group 3) - する becomes して, くる becomes きて\n\n**Long**: The ～て form of a verb is used to connect actions or states in a sequence, implying that the first action is completed before the second one starts. The ～て form is frequently used in casual speech, and it can also be used in polite speech when combined with certain auxiliary verbs like ください (kudasai) or いる (iru).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te_imasu','Verb て います',NULL,NULL,'N5','[]','[{"ja":"彼女は今ピアノを弾いています。","en":"She is playing the piano now.","romaji":"Kanojo wa ima piano wo hiite imasu.","zh":""},{"ja":"私たちは日本語を勉強しています。","en":"We are studying Japanese.","romaji":"Watashitachi wa nihongo wo benkyou shiteimasu.","zh":""},{"ja":"彼は映画を見ています。","en":"He is watching a movie.","romaji":"Kare wa eiga wo miteimasu.","zh":""},{"ja":"入っていますので、お待ちください。","en":"I am in, so please wait.","romaji":"Haitteimasu node, omachi kudasai.","zh":""}]',replace('**Short**: Express ongoing action or state; ''is doing'', ''is doing (continuous)'', ''has been doing''.\n\n**Formation**: Verb て-form + います\n\n**Long**: The て います grammar point is used to express an action that is ongoing, continuous, or has been happening. It is formed by conjugating the verb in its て-form and adding います. It can be translated as ''is doing'', ''is doing (continuous)'', or ''has been doing'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_kara','Verb てから～',NULL,NULL,'N5','[]','[{"ja":"宿題をしてから、テレビを見ました。","en":"I watched TV after doing my homework.","romaji":"Shukudai wo shite kara, terebi wo mimashita.","zh":""},{"ja":"食べてから、歯を磨きましょう。","en":"Let''s brush our teeth after eating.","romaji":"Tabete kara, ha wo migakimashou.","zh":""},{"ja":"仕事が終わってから、友達と飲みに行きます。","en":"I will go drinking with my friends after work is done.","romaji":"Shigoto ga owatte kara, tomodachi to nomi ni ikimasu.","zh":""},{"ja":"学校が終わってから、図書館で勉強します。","en":"I will study in the library after school is over.","romaji":"Gakkou ga owatte kara, toshokan de benkyou shimasu.","zh":""}]',replace('**Short**: Express a sequence of actions or events; ''after'', ''since'', ''once''.\n\n**Formation**: Verb-て形 + から\n\n**Long**: The ～てから grammar point is used to indicate the sequence of actions or events, meaning that one action or event occurs after another. It can be translated as ''after'', ''since'', or ''once'' in English. The て-form indicates the first action and から shows the sequence.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te_kudasai','Verb て ください',NULL,NULL,'N5','[]','[{"ja":"ドアを開けてください。","en":"Please open the door.","romaji":"Doa wo akete kudasai.","zh":""},{"ja":"電話番号を教えてください。","en":"Please tell me your phone number.","romaji":"Denwa bangou wo oshiete kudasai.","zh":""},{"ja":"ゆっくり話してください。","en":"Please speak slowly.","romaji":"Yukkuri hanashite kudasai.","zh":""},{"ja":"コーヒーを一つ持ってきてください。","en":"Please bring me a coffee.","romaji":"Koohii wo hitotsu motte kite kudasai.","zh":""}]',replace('**Short**: A request or command; ''please do''.\n\n**Formation**: Verb-て form + ください\n\n**Long**: The て ください grammar point is used to make a request or command someone to do something politely. The verb is conjugated into its て-form and followed by ください, which means ''please''. This structure is used when asking someone to do something with a polite and respectful tone.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_naide_kudasai','Verb ないで ください',NULL,NULL,'N5','[]','[{"ja":"タバコを吸わないでください。","en":"Please don''t smoke.","romaji":"Tabako wo suwanaide kudasai.","zh":""},{"ja":"ここで走らないでください。","en":"Please don''t run here.","romaji":"Koko de hashiranaide kudasai.","zh":""},{"ja":"大きな声で話さないでください。","en":"Please don''t speak loudly.","romaji":"Ookina koe de hanasanaide kudasai.","zh":""},{"ja":"写真を撮らないでください。","en":"Please don''t take photos.","romaji":"Shashin wo toranaide kudasai.","zh":""}]',replace('**Short**: Used to make a polite request for someone not to do something; ''please don''t''.\n\n**Formation**: Verb-ない-form + で ください\n\n**Long**: The grammar point Verb ないで ください is used to make a polite request for someone not to do a certain action. In English, it can be translated as ''please don''t''. To form this expression, take the verb in its negative form (ない-form) and add で ください.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_ni_modorimasu','Noun に 戻ります',NULL,NULL,'N5','[]','[{"ja":"冷蔵庫に入れると、溶けたアイスクリームは固体に戻ります。","en":"When put in the refrigerator, the melted ice cream returns to its solid state.","romaji":"Reizouko ni ireru to, toketa aisukuriimu wa kotai ni modorimasu.","zh":""},{"ja":"休暇が終わったら、仕事に戻ります。","en":"When the vacation ends, I will return to work.","romaji":"Kyuuka ga owattara, shigoto ni modorimasu.","zh":""},{"ja":"リモートワークが終わった後、元のオフィスに戻ります。","en":"After remote work is over, we will return to our original office.","romaji":"Rimooto waaku ga owatta ato, moto no ofisu ni modorimasu.","zh":""},{"ja":"外国で勉強した後、日本に帰ります。","en":"After studying abroad, I will return to Japan.","romaji":"Gaikoku de benkyou shita ato, Nihon ni kaerimasu.","zh":""}]',replace('**Short**: Expresses the action of returning to a previous state, place, or condition.\n\n**Formation**: Noun + に + 戻ります\n\n**Long**: The Noun に 戻ります grammar point is used to express going back or reverting to a previous state, place, or condition. 戻る (modoru) literally means ''to go back'' or ''to revert''. This is often used after a change has occurred, indicating that something is being undone or returned to its original form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ni_kimasu','Verb に 来ます',NULL,NULL,'N5','[]','[{"ja":"友達に会いに来ました。","en":"I came to meet my friend.","romaji":"Tomodachi ni ai ni kimashita.","zh":""},{"ja":"映画を見に来ました。","en":"I came to watch a movie.","romaji":"Eiga wo mi ni kimashita.","zh":""},{"ja":"先生に質問しに来ました。","en":"I came to ask the teacher a question.","romaji":"Sensei ni shitsumon shi ni kimashita.","zh":""},{"ja":"買い物をしに来ました。","en":"I came to go shopping.","romaji":"Kaimono wo shi ni kimashita.","zh":""}]',replace('**Short**: Expresses the purpose of coming to a place; ''come to (do something)''.\n\n**Formation**: Verb (ます-stem) + に + 来ます\n\n**Long**: The grammar point Verb に きます is used to express the purpose of coming to a place to perform an action. It can be translated as ''come to (do something)'' in English. To form this expression, use the verb''s ます-stem (i.e., remove ます) followed by に きます.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ni_ikimasu','Verb に 行きます',NULL,NULL,'N5','[]','[{"ja":"公園に遊びに行きます。","en":"I will go to the park to play.","romaji":"Kouen ni asobi ni ikimasu.","zh":""},{"ja":"図書館に勉強しに行きます。","en":"I will go to the library to study.","romaji":"Toshokan ni benkyou shi ni ikimasu.","zh":""},{"ja":"スーパーに買い物に行きます。","en":"I will go to the supermarket to do some shopping.","romaji":"Suupaa ni kaimono ni ikimasu.","zh":""},{"ja":"映画館に映画を見に行きます。","en":"I will go to the movie theater to watch a movie.","romaji":"Eigakan ni eiga wo mi ni ikimasu.","zh":""}]',replace('**Short**: To go (somewhere) in order to do an action.\n\n**Formation**: Verb (ます-stem) + に + 行きます\n\n**Long**: The grammar point Verb に 行きます is used when expressing that someone is going to a certain place with the purpose of doing a specific action. Form it by taking the verb''s ます-stem (for suru-verbs, remove する and add し) and then adding に 行きます.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mashou','Verb ましょう',NULL,NULL,'N5','[]','[{"ja":"一緒に映画を見ましょう。","en":"Let''s watch a movie together.","romaji":"Issho ni eiga wo mimashou.","zh":""},{"ja":"散歩しましょう。","en":"Let''s take a walk.","romaji":"Sanpo shimashou.","zh":""},{"ja":"今晩、食事に行きましょう。","en":"Let''s go out for dinner tonight.","romaji":"Konban, shokuji ni ikimashou.","zh":""},{"ja":"明日勉強しましょう。","en":"Let''s study tomorrow.","romaji":"Ashita benkyou shimashou.","zh":""}]',replace('**Short**: Making a suggestion or invitation; ''let''s'' or ''shall we''.\n\n**Formation**: Verb (ます-stem) + ましょう\n\n**Long**: The ましょう grammar point is used to suggest or invite someone to do something in a polite and friendly way. It can be translated as ''let''s'' or ''shall we'' in English. This grammar point is formed by attaching ましょう to the stem of the verb (i.e. remove ます).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mashou_ka','Verb ましょうか。',NULL,NULL,'N5','[]','[{"ja":"一緒に映画を見に行きましょうか。","en":"Shall we go see a movie together?","romaji":"Issho ni eiga wo mi ni ikimashou ka.","zh":""},{"ja":"コーヒーをもう一杯飲みましょうか。","en":"Should we have another cup of coffee?","romaji":"Koohii wo mou ippai nomimashou ka.","zh":""},{"ja":"あなたの荷物を持ちましょうか。","en":"Do you want me to carry your luggage?","romaji":"Anata no nimotsu wo mochimashou ka.","zh":""},{"ja":"窓を開けましょうか。","en":"Shall I open the window?","romaji":"Mado wo akemashou ka.","zh":""}]',replace('**Short**: Used to make a polite suggestion or offer help; ''shall we'', ''should we'', ''do you want me to''.\n\n**Formation**: Verb (ます-stem) + ましょうか\n\n**Long**: The ましょうか grammar point is used to make a polite suggestion, propose an action, or offer help. It can be translated as ''shall we'', ''should we'', or ''do you want me to'' in English. This formation is used with verbs in their ます-form, replacing ます with ましょう and adding か.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_masenka','Verb ませんか。',NULL,NULL,'N5','[]','[{"ja":"一緒に映画を見ませんか。","en":"Won''t you watch a movie together with me?","romaji":"Issho ni eiga wo mimasenka.","zh":""},{"ja":"明日のパーティーに参加しませんか。","en":"Why don''t you join tomorrow''s party?","romaji":"Ashita no paatii ni sanka shimasenka.","zh":""},{"ja":"週末にピクニックに行きませんか。","en":"Shall we go for a picnic on the weekend?","romaji":"Shuumatsu ni pikunikku ni ikimasenka.","zh":""},{"ja":"一緒に勉強しませんか。","en":"How about studying together?","romaji":"Issho ni benkyou shimasenka.","zh":""}]',replace('**Short**: An invitation or suggestion; ''won''t you'', ''why don''t you'', ''shall we''.\n\n**Formation**: Verb (ます-form) + ませんか\n\n**Long**: The ませんか grammar point is used for making invitations or suggestions in a polite manner. The verb is conjugated to its ます form and replaced with ませんか. This can be translated as ''won''t you'', ''why don''t you'', or ''shall we'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ru_koto','Verb ること～',NULL,NULL,'N5','[]','[{"ja":"泳ぐことが大好きです。","en":"I love swimming.","romaji":"Oyogu koto ga daisuki desu.","zh":""},{"ja":"日本語を勉強することは楽しいです。","en":"Studying Japanese is fun.","romaji":"Nihongo wo benkyou suru koto wa tanoshii desu.","zh":""},{"ja":"友達と話すことがストレスを軽減します。","en":"Talking with friends reduces stress.","romaji":"Tomodachi to hanasu koto ga sutoresu wo keigen shimasu.","zh":""},{"ja":"彼は歌うことが得意です。","en":"He is good at singing.","romaji":"Kare wa utau koto ga tokui desu.","zh":""}]',replace('**Short**: Express an action or event as a noun; ''the act of'', ''doing''.\n\n**Formation**: Verb (dictionary form) + こと\n\n**Long**: The ること grammar point is used to nominalize or turn a verb into a noun, which represents the action or event itself as a concept. It can be translated as ''the act of'' or simply ''doing'' in English. This formation is used with verbs in the dictionary (ru-)form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ru_koto_ga_dekimasu','Verb る こと が できます',NULL,NULL,'N5','[]','[{"ja":"この問題を解くことができます。","en":"I can solve this problem.","romaji":"Kono mondai o toku koto ga dekimasu.","zh":""},{"ja":"彼は英語を話すことができます。","en":"He can speak English.","romaji":"Kare wa eigo o hanasu koto ga dekimasu.","zh":""},{"ja":"私は高い所に登ることができません。","en":"I can''t climb to high places.","romaji":"Watashi wa takai tokoro ni noboru koto ga dekimasen.","zh":""},{"ja":"彼女はピアノを弾くことができます。","en":"She can play the piano.","romaji":"Kanojo wa piano o hiku koto ga dekimasu.","zh":""}]',replace('**Short**: Express the potential form, or the ability to do something.\n\n**Formation**: Verb (dictionary form) + ことができます\n\n**Long**: The 〜ることができます grammar point is used to express that someone is capable of doing something or that something is possible. It is essentially the potential form of the verb. The formation is made by changing the verb to a noun phrase with こと and then adding ができます.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ru_koto_ga_dekiru_n5','Verb る こと ができる',NULL,NULL,'N5','[]','[{"ja":"この問題を解くことができる？","en":"Can you solve this problem?","romaji":"Kono mondai o toku koto ga dekiru?","zh":""},{"ja":"彼は泳ぐことができます。","en":"He can swim.","romaji":"Kare wa oyogu koto ga dekimasu.","zh":""},{"ja":"日本に行くことができて、とても嬉しいです。","en":"I''m very happy that I can go to Japan.","romaji":"Nihon ni iku koto ga dekite, totemo ureshii desu.","zh":""},{"ja":"彼女はピアノを弾くことができます。","en":"She can play the piano.","romaji":"Kanojo wa piano o hiku koto ga dekimasu.","zh":""}]',replace('**Short**: Expresses the potential form; ''can'', ''be able to'', ''is possible''.\n\n**Formation**: Verb (dictionary form) + ことができる\n\n**Long**: The る こと ができる grammar point is used to express the potential form of a verb, meaning the ability or possibility to do something. It can be translated as ''can'', ''be able to'', or ''is possible'' in English. This grammar is often used with verbs ending in る, but can also apply to other verbs once they are in the dictionary form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ru_no','Verb る の～',NULL,NULL,'N5','[]','[{"ja":"買い物をするために、銀行でお金をおろすの。","en":"I''m withdrawing money at the bank so I can go shopping.","romaji":"Kaimono o suru tame ni, ginkou de okane o orosu no.","zh":""},{"ja":"友達にプレゼントをあげるので、ケーキを焼くの。","en":"I''m baking a cake because I''m giving my friend a present.","romaji":"Tomodachi ni purezento o ageru node, keeki o yaku no.","zh":""},{"ja":"ダイエットを始めるので、ジムに入会するの。","en":"I’m joining a gym since I''m starting a diet.","romaji":"Daietto o hajimeru node, jimu ni nyuukai suru no.","zh":""},{"ja":"軽い食事がいいので、サラダを作るの。","en":"I''m making a salad because I want a light meal.","romaji":"Karui shokuji ga ii node, sarada o tsukuru no.","zh":""}]',replace('**Short**: Used to express the purpose or reason in casual speech, or nominalize the verb with の.\n\n**Formation**: Verb (dictionary form) + の (casual)\n\n**Long**: The る の～ grammar point is a casual spoken pattern that can nominalize a verb or explain a purpose/reason by adding の. It''s often seen in everyday conversation, and can be used for nuance such as giving an explanation. It''s similar to ること, but is more colloquial or explanatory in tone.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ru_mae_ni','Verb る 前に',NULL,NULL,'N5','[]','[{"ja":"出かける前に、部屋を掃除してください。","en":"Please clean the room before leaving.","romaji":"Dekakeru mae ni, heya o souji shite kudasai.","zh":""},{"ja":"寝る前に、歯を磨きます。","en":"I brush my teeth before going to bed.","romaji":"Neru mae ni, ha o migakimasu.","zh":""},{"ja":"雨が降る前に、洗濯物を取り込むこと。","en":"Take in the laundry before it rains.","romaji":"Ame ga furu mae ni, sentakumono o torikomu koto.","zh":""},{"ja":"会議が始まる前に、資料を準備しましょう。","en":"Let''s prepare the documents before the meeting starts.","romaji":"Kaigi ga hajimaru mae ni, shiryou o junbi shimashou.","zh":""}]',replace('**Short**: Used to express ''before'' in a sense of an action must be done before another action or event.\n\n**Formation**: Verb (dictionary form) + 前に\n\n**Long**: The る前に (ru mae ni) grammar point is used to indicate that an action (in the dictionary form) should be completed before another action occurs or before a specific event happens.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_amari_arimasen','あまり～ありません',NULL,NULL,'N5','[]','[{"ja":"彼はあまり疲れていません。","en":"He is not really tired.","romaji":"Kare wa amari tsukareteimasen.","zh":""},{"ja":"彼女はあまり早くないですよ。","en":"She is not very fast.","romaji":"Kanojo wa amari hayakunai desu yo.","zh":""},{"ja":"私はあまり勉強しないです。","en":"I don''t study very much.","romaji":"Watashi wa amari benkyou shinai desu.","zh":""},{"ja":"あまりお金がありません。","en":"I don''t have much money.","romaji":"Amari okane ga arimasen.","zh":""}]',replace('**Short**: Express ''not very'', ''not much'', or ''not really'' when describing a negative state or situation.\n\n**Formation**: あまり + Verb-ないform + ありません / あまり + い-Adjective-く ありません / あまり + な-Adjective・Noun じゃありません\n\n**Long**: The grammar point あまり～ありません is used to describe a negative state or condition and indicate that it''s not very, not much, or not really. It is commonly used with verbs in the negative form and can be used with い-adjectives, な-adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_amari_nai_desu','あまり～ないです',NULL,NULL,'N5','[]','[{"ja":"あまり食べないです。","en":"I don''t really eat much.","romaji":"Amari tabenai desu.","zh":""},{"ja":"この映画はあまり面白くないです。","en":"This movie is not really interesting.","romaji":"Kono eiga wa amari omoshirokunai desu.","zh":""},{"ja":"彼はあまり親切じゃないです。","en":"He is not very kind.","romaji":"Kare wa amari shinsetsu ja nai desu.","zh":""},{"ja":"私はあまり日本語が上手じゃないです。","en":"I am not very good at Japanese.","romaji":"Watashi wa amari nihongo ga jouzu ja nai desu.","zh":""}]',replace('**Short**: Express ''not really'' or ''not very''; used to soften a negative statement.\n\n**Formation**: あまり + Verb-ないform + です / あまり + い-Adjective-くない + です / あまり + な-Adjective-じゃない + です\n\n**Long**: The あまり～ないです grammar point is used to express that something is ''not really'' or ''not very'' to a certain extent. It is often used to soften a negative statement. It can be used with verbs, い-adjectives, and な-adjectives in their negative forms.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_arimasu','～あります',NULL,NULL,'N5','[]','[{"ja":"教室に机があります。","en":"There is a desk in the classroom.","romaji":"Kyoushitsu ni tsukue ga arimasu.","zh":""},{"ja":"この公園にたくさんの花があります。","en":"There are many flowers in this park.","romaji":"Kono kouen ni takusan no hana ga arimasu.","zh":""},{"ja":"駅の近くにコンビニがあります。","en":"There is a convenience store near the station.","romaji":"Eki no chikaku ni konbini ga arimasu.","zh":""},{"ja":"家の中に古いテレビがあります。","en":"There is an old TV inside the house.","romaji":"Ie no naka ni furui terebi ga arimasu.","zh":""}]',replace('**Short**: Indicate possession or existence of inanimate objects; ''there is'', ''there are''.\n\n**Formation**: Object + が + あります\n\n**Long**: The あります grammar point is used to indicate the possession or existence of inanimate objects. It can be translated as ''there is'' or ''there are'' in English. It is different from います, which is used for people and most living creatures. あります is commonly used with particle が to mark the object.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ikaga_desu_ka','～いかがですか。',NULL,NULL,'N5','[]','[{"ja":"お茶はいかがですか？","en":"How about some tea?","romaji":"Ocha wa ikaga desu ka?","zh":""},{"ja":"このドレスはいかがですか？","en":"How about this dress?","romaji":"Kono doresu wa ikaga desu ka?","zh":""},{"ja":"ケーキを食べてはいかがですか？","en":"How about eating some cake?","romaji":"Keeki wo tabete wa ikaga desu ka?","zh":""},{"ja":"映画を見てはいかがですか？","en":"How about watching a movie?","romaji":"Eiga wo mite wa ikaga desu ka?","zh":""}]',replace('**Short**: A polite way to ask someone''s thoughts, opinions, or preferences; ''how about'', ''how is''.\n\n**Formation**: Noun + は + いかがですか / (Verb-て form + は) いかがですか\n\n**Long**: The ～いかがですか grammar point is used to politely ask someone''s thoughts, opinions, or preferences. It can be translated as ''how about'' or ''how is'' in English. The formation is quite straightforward when used with verbs or nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ikutsu','いくつ～',NULL,NULL,'N5','[]','[{"ja":"リンゴはいくつありますか？","en":"How many apples are there?","romaji":"Ringo wa ikutsu arimasu ka?","zh":""},{"ja":"いくつかの問題を解決しなければなりません。","en":"I have to solve several problems.","romaji":"Ikutsu ka no mondai o kaiketsu shinakereba narimasen.","zh":""},{"ja":"あなたはいくつの言語を話せますか？","en":"How many languages can you speak?","romaji":"Anata wa ikutsu no gengo o hanasemasu ka?","zh":""},{"ja":"パーティーにはいくつかの飲み物があります。","en":"There are several drinks at the party.","romaji":"Paatii ni wa ikutsu ka no nomimono ga arimasu.","zh":""}]',replace('**Short**: Used to express ''how many'' or ask for the number of something.\n\n**Formation**: いくつ + Noun (optional)\n\n**Long**: The grammar point いくつ is used when asking or expressing ''how many'' of something there are, or to indicate an unspecified number. In English, it can be translated as ''how many'' or ''several''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_itsuka','いつか～',NULL,NULL,'N5','[]','[{"ja":"いつか日本に行きたいです。","en":"I want to go to Japan someday.","romaji":"Itsuka Nihon ni ikitai desu.","zh":""},{"ja":"彼はいつか有名な作家になるでしょう。","en":"He will become a famous writer someday.","romaji":"Kare wa itsuka yuumei na sakka ni naru deshou.","zh":""},{"ja":"いつかあの山を登りたいと思っています。","en":"I think I want to climb that mountain someday.","romaji":"Itsuka ano yama wo noboritai to omotte imasu.","zh":""},{"ja":"彼女はいつか夢を叶えることができると信じています。","en":"I believe she can achieve her dream someday.","romaji":"Kanojo wa itsuka yume wo kanaeru koto ga dekiru to shinjiteimasu.","zh":""}]',replace('**Short**: Indicates an unspecified point in time; ''someday'', ''one day'', ''at some point''.\n\n**Formation**: いつか + sentence\n\n**Long**: The grammar point いつか is used to indicate an unspecified point in time, meaning ''someday'', ''one day'', or ''at some point'' in the future or the past. It can be used in sentences to express hopes, dreams, or possibilities.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_itsudemo','いつでも～',NULL,NULL,'N5','[]','[{"ja":"いつでも遊びに来てください。","en":"Please come to play anytime.","romaji":"Itsudemo asobi ni kite kudasai.","zh":""},{"ja":"彼女はいつでも笑顔です。","en":"She is always smiling.","romaji":"Kanojo wa itsudemo egao desu.","zh":""},{"ja":"いつでも電話で連絡できます。","en":"You can contact me by phone anytime.","romaji":"Itsudemo denwa de renraku dekimasu.","zh":""},{"ja":"この店はいつでも混んでいます。","en":"This store is always crowded.","romaji":"Kono mise wa itsudemo konde imasu.","zh":""}]',replace('**Short**: Expresses ''anytime'', ''always'', or ''whenever''.\n\n**Formation**: いつでも + (Verb)\n\n**Long**: The いつでも grammar point is used to express that something occurs, can occur, or is allowed to occur anytime, always, or whenever. It emphasizes the lack of restrictions related to time for a certain action or event.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_itsumo','いつも～',NULL,NULL,'N5','[]','[{"ja":"彼はいつも遅刻します。","en":"He is always late.","romaji":"Kare wa itsumo chikoku shimasu.","zh":""},{"ja":"私はいつも優しい犬が好きです。","en":"I always like gentle dogs.","romaji":"Watashi wa itsumo yasashii inu ga suki desu.","zh":""},{"ja":"彼女はいつも静かな場所で勉強します。","en":"She always studies in a quiet place.","romaji":"Kanojo wa itsumo shizuka na basho de benkyou shimasu.","zh":""},{"ja":"いつも朝ご飯を食べます。","en":"I always eat breakfast.","romaji":"Itsumo asagohan wo tabemasu.","zh":""}]',replace('**Short**: Expressing ''always'' or ''usually'' in a sentence.\n\n**Formation**: いつも + Verb / Adjective / Noun\n\n**Long**: The grammar point いつも (itsumo) is used to express the meaning of ''always'' or ''usually'' when describing a habitual action or situation. It is often used with the present tense or past tense to show that something is done on a regular basis or has been happening consistently.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_imasu','～て います',NULL,NULL,'N5','[]','[{"ja":"今、音楽を聞いています。","en":"I am listening to music right now.","romaji":"Ima, ongaku wo kiite imasu.","zh":""},{"ja":"父は新聞を読んでいます。","en":"My father is reading a newspaper.","romaji":"Chichi wa shinbun wo yonde imasu.","zh":""},{"ja":"彼女は英語を勉強しています。","en":"She is studying English.","romaji":"Kanojo wa eigo wo benkyou shite imasu.","zh":""},{"ja":"子供たちは公園で遊んでいます。","en":"The children are playing in the park.","romaji":"Kodomotachi wa kouen de asonde imasu.","zh":""}]',replace('**Short**: Expresses the present continuous or ongoing action; ''to be doing'', ''currently doing''.\n\n**Formation**: Verb て-form + います\n\n**Long**: The ～て います grammar pattern is used to express that an action is currently happening or ongoing. It can be translated as ''to be doing'' or ''currently doing'' in English. The formation differs depending on whether it is a る-verb, う-verb, or an irregular verb, but all use the verb’s て-form + います.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ga_n5','～が',NULL,NULL,'N5','[]','[{"ja":"私が学生です。","en":"I am a student.","romaji":"Watashi ga gakusei desu.","zh":""},{"ja":"このりんごが美味しい。","en":"This apple is delicious.","romaji":"Kono ringo ga oishii.","zh":""},{"ja":"彼は頭がいいが、性格が悪い。","en":"He is smart but has a bad personality.","romaji":"Kare wa atama ga ii ga, seikaku ga warui.","zh":""},{"ja":"走りたいが、足が痛い。","en":"I want to run, but my leg hurts.","romaji":"Hashiritai ga, ashi ga itai.","zh":""}]',replace('**Short**: Particle indicating the subject of a sentence or expressing ''but''.\n\n**Formation**: Noun + が / い-Adjective + が / な-Adjective + が / Verb + が\n\n**Long**: The ～が grammar point is a particle that is used to indicate the subject of a sentence or to express a contrast similar to ''but'' in English. It has various functions depending on the context.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ga_n5_2','～が、～',NULL,NULL,'N5','[]','[{"ja":"デザートは美味しいが、カロリーが高い。","en":"The dessert is delicious, but it is high in calories.","romaji":"Dezaato wa oishii ga, karorii ga takai.","zh":""},{"ja":"彼は頭がいいが、少し怠け者だ。","en":"He is smart, but a bit lazy.","romaji":"Kare wa atama ga ii ga, sukoshi namakemono da.","zh":""},{"ja":"会社は利益を上げたが、従業員の給与は上がらなかった。","en":"The company made a profit, however, the employees'' salaries did not increase.","romaji":"Kaisha wa rieki wo ageta ga, juugyouin no kyuuyo wa agaranakatta.","zh":""},{"ja":"外国語を勉強することが楽しいが、時々難しい。","en":"Studying foreign languages is fun, but sometimes difficult.","romaji":"Gaikokugo wo benkyou suru koto ga tanoshii ga, tokidoki muzukashii.","zh":""}]',replace('**Short**: Express a contrast between two sentences; ''but'', ''however''.\n\n**Formation**: Sentence 1 + が、+ Sentence 2\n\n**Long**: The ～が、～ grammar point is used to express a contrast or contradiction between two sentences or clauses. It can be translated as ''but'' or ''however'' in English. This grammar point is slightly more formal than けど and is used to show a contrast in the situation.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kara_n5','～から、～',NULL,NULL,'N5','[]','[{"ja":"明日は試験があるから、今晩勉強しなければなりません。","en":"Because I have an exam tomorrow, I must study tonight.","romaji":"Ashita wa shiken ga aru kara, konban benkyou shinakereba narimasen.","zh":""},{"ja":"この部屋は狭いから、もっと大きい部屋を探しています。","en":"Since this room is small, I am looking for a bigger one.","romaji":"Kono heya wa semai kara, motto ookii heya wo sagashiteimasu.","zh":""},{"ja":"彼は友達だから、手伝ってくれるでしょう。","en":"Since he is my friend, he will probably help me.","romaji":"Kare wa tomodachi dakara, tetsudatte kureru deshou.","zh":""},{"ja":"雨が降ったから、外に出られません。","en":"Because it rained, I can''t go outside.","romaji":"Ame ga futta kara, soto ni deraremasen.","zh":""}]',replace('**Short**: Expresses reason or cause; ''because'', ''since'', ''so''.\n\n**Formation**: Verb-casual + から / い-Adjective + から / な-Adjective + だから / Noun + だから\n\n**Long**: The ～から grammar point is used to indicate the reason or cause for something. It can be translated as ''because'', ''since'', or ''so'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kara_desu','～からです',NULL,NULL,'N5','[]','[{"ja":"寒いからです。コートを着ています。","en":"It’s because it’s cold. That’s why I’m wearing a coat.","romaji":"Samui kara desu. Kooto wo kiteimasu.","zh":""},{"ja":"この店は安いからです。よく来ます。","en":"It’s because this store is cheap. That’s why I come often.","romaji":"Kono mise wa yasui kara desu. Yoku kimasu.","zh":""},{"ja":"彼は親切だからです。みんなに好かれています。","en":"It’s because he’s kind. Everyone likes him.","romaji":"Kare wa shinsetsu dakara desu. Minna ni suka-rete imasu.","zh":""},{"ja":"彼女は学生だからです。図書館で勉強しています。","en":"It’s because she’s a student. She studies at the library.","romaji":"Kanojo wa gakusei dakara desu. Toshokan de benkyou shiteimasu.","zh":""}]',replace('**Short**: Express the reason or cause; ''because'', ''since'', ''due to''.\n\n**Formation**: Verb-casual + からです / い-Adjective + からです / な-Adjective + だからです / Noun + だからです\n\n**Long**: The ～からです grammar point is used to state the reason or cause of something, often as a short concluding statement. It can be translated as ''because'', ''since'', or ''due to'' in English. The formation can be used with verbs, い-adjectives, な-adjectives, or nouns, but be careful with な-adjectives and nouns: typically, it''s [Noun/な-adjective] + だからです.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kara_moraimasu','～から もらいます',NULL,NULL,'N5','[]','[{"ja":"友達からプレゼントをもらいました。","en":"I received a present from my friend.","romaji":"Tomodachi kara purezento wo moraimashita.","zh":""},{"ja":"先生に宿題を渡してもらいました。","en":"I had the teacher hand me the homework.","romaji":"Sensei ni shukudai wo watashite moraimashita.","zh":""},{"ja":"お母さんに料理を作ってもらいました。","en":"I got my mom to cook for me.","romaji":"Okaasan ni ryouri wo tsukutte moraimashita.","zh":""},{"ja":"兄に車を貸してもらいました。","en":"I got my older brother to lend me his car.","romaji":"Ani ni kuruma wo kashite moraimashita.","zh":""}]',replace('**Short**: To receive something or get someone to do something.\n\n**Formation**: Noun + から + (Verb-て form) + もらいます\n\n**Long**: The ～からもらいます grammar point is used to express receiving something from someone or getting someone to do something for you. In English, it can be translated as ''to receive from'' or ''to get someone to do something''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ga_watashi_ni_kuremasu','～が 私に くれます',NULL,NULL,'N5','[]','[{"ja":"彼がプレゼントを私にくれました。","en":"He gave me a present.","romaji":"Kare ga purezento wo watashi ni kuremashita.","zh":""},{"ja":"友達が宿題を手伝って私にくれました。","en":"My friend helped me with my homework.","romaji":"Tomodachi ga shukudai wo tetsudatte watashi ni kuremashita.","zh":""},{"ja":"お母さんがお弁当を作って私にくれました。","en":"My mom made me a lunch box.","romaji":"Okaasan ga obentou wo tsukutte watashi ni kuremashita.","zh":""},{"ja":"先生がアドバイスを私にくれました。","en":"The teacher gave me advice.","romaji":"Sensei ga adobaisu wo watashi ni kuremashita.","zh":""}]',replace('**Short**: Used to express that someone gives a gift or favor to ''me''; ''someone gives me''.\n\n**Formation**: Person + が + (Thing or Action) + 私に + くれます\n\n**Long**: The ～が私にくれます grammar point is used to express that someone gives ''me'' something or does something for me. It can be translated as ''someone gives me'' or ''someone does something for me'' in English. Typically, the giver is marked by が, and the receiver is 私に (to me).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kedo','～けど、～',NULL,NULL,'N5','[]','[{"ja":"授業に出たけど、まだ宿題をしないといけない。","en":"I attended the class, but I still have to do my homework.","romaji":"Jugyou ni deta kedo, mada shukudai wo shinai to ikenai.","zh":""},{"ja":"昨日寒かったけど、今日は暖かいです。","en":"Yesterday was cold, but today is warm.","romaji":"Kinou samukatta kedo, kyou wa atatakai desu.","zh":""},{"ja":"彼は親切だけど、ちょっと怖い。","en":"He is kind, but a little scary.","romaji":"Kare wa shinsetsu da kedo, chotto kowai.","zh":""},{"ja":"これはおいしそうだけど、高すぎる。","en":"This looks delicious, but it is too expensive.","romaji":"Kore wa oishisou da kedo, takasugiru.","zh":""}]',replace('**Short**: Used to connect two clauses; ''but'', ''however'', ''although''\n\n**Formation**: Verb-casual + けど / い-adjective + けど / な-adjective + だけど / Noun + だけど\n\n**Long**: The ～けど grammar point is used to connect two clauses, often to show a contrast or to introduce a different point of view. It can be translated as ''but'', ''however'', or ''although'' in English. It''s more casual than けれど or が.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_keredo_n5','～けれど、～',NULL,NULL,'N5','[]','[{"ja":"今日は寒いけれど、散歩に行きます。","en":"Even though it''s cold today, I''ll go for a walk.","romaji":"Kyou wa samui keredo, sanpo ni ikimasu.","zh":""},{"ja":"彼は親切けれど、少し怖いです。","en":"He is kind, but a little scary.","romaji":"Kare wa shinsetsu keredo, sukoshi kowai desu.","zh":""},{"ja":"この部屋は狭いけれど、明るいです。","en":"This room is small, but it''s bright.","romaji":"Kono heya wa semai keredo, akarui desu.","zh":""},{"ja":"彼女は病気だけれど、毎日働いています。","en":"She is sick, but she works every day.","romaji":"Kanojo wa byouki dakeredo, mainichi hataraite imasu.","zh":""}]',replace('**Short**: Expresses a contrast or contradiction; ''but'', ''however'', ''even though''.\n\n**Formation**: Verb-casual + けれど / い-Adjective + けれど / な-Adjective + だけれど / Noun + だけれど\n\n**Long**: The ～けれど grammar point is used to express a contrast or contradiction between two statements. It can be translated as ''but'', ''however'', or ''even though'' in English. This grammar point is slightly more formal than けど.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kochira','こちら～',NULL,NULL,'N5','[]','[{"ja":"こちらは田中さんです。","en":"This is Mr./Ms. Tanaka.","romaji":"Kochira wa Tanaka-san desu.","zh":""},{"ja":"こちらのレストランは美味しいです。","en":"This restaurant is delicious.","romaji":"Kochira no resutoran wa oishii desu.","zh":""},{"ja":"こちらへどうぞ。","en":"Please come this way.","romaji":"Kochira e douzo.","zh":""},{"ja":"こちらの方がいいですか、それともあちらの方がいいですか？","en":"Is this one better, or is that one better?","romaji":"Kochira no hou ga ii desu ka, sore to mo achira no hou ga ii desu ka?","zh":""}]',replace('**Short**: Refers to a person, place or thing; ''this'', ''this one'', ''this way'', ''here''.\n\n**Formation**: こちら / こちら + の + Person/Thing\n\n**Long**: The こちら grammar point is used to refer to a person, place, or thing that is closer to the speaker, or to show politeness when referring to someone. It can mean ''this'', ''this one'', ''this way'', or ''here''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sakki','さっき～',NULL,NULL,'N5','[]','[{"ja":"さっき電話がありました。","en":"There was a phone call just now.","romaji":"Sakki denwa ga arimashita.","zh":""},{"ja":"さっき部屋を掃除しました。","en":"I cleaned the room a short while ago.","romaji":"Sakki heya wo souji shimashita.","zh":""},{"ja":"さっき彼に会いました。","en":"I met him just now.","romaji":"Sakki kare ni aimashita.","zh":""},{"ja":"さっきのニュースを見ましたか？","en":"Did you watch the news a short time ago?","romaji":"Sakki no nyuusu wo mimashita ka?","zh":""}]',replace('**Short**: Refers to a short time ago or just now.\n\n**Formation**: さっき + verb / さっき + phrase\n\n**Long**: The word さっき (sakki) is an adverb used to express that something happened or was done a short time ago or just now. It can be combined with verbs or other phrases to convey that meaning.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sugu_ni','すぐに～',NULL,NULL,'N5','[]','[{"ja":"友達が来たら、すぐに電話をかけてください。","en":"When my friend arrives, please call me right away.","romaji":"Tomodachi ga kitara, sugu ni denwa wo kakete kudasai.","zh":""},{"ja":"そのニュースを聞いたら、すぐに会社に行きました。","en":"Upon hearing that news, I went to the company immediately.","romaji":"Sono nyuusu wo kiitara, sugu ni kaisha ni ikimashita.","zh":""},{"ja":"彼女はすぐに泣き出した。","en":"She started crying right away.","romaji":"Kanojo wa sugu ni nakidashita.","zh":""},{"ja":"教室に入ると、先生はすぐに授業を始めた。","en":"As soon as I entered the classroom, the teacher started the lesson immediately.","romaji":"Kyoushitsu ni hairu to, sensei wa sugu ni jugyou wo hajimeta.","zh":""}]',replace('**Short**: Immediately or right away; used to express promptness or quickness.\n\n**Formation**: すぐに + Verb/Adjective\n\n**Long**: The すぐに～ grammar point is used to express an action happening immediately or right away. It often indicates promptness or quickness and can be used with both verbs and adjectives.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_zenzen','ぜんぜん～',NULL,NULL,'N5','[]','[{"ja":"彼はぜんぜん話さない。","en":"He doesn''t talk at all.","romaji":"Kare wa zenzen hanasanai.","zh":""},{"ja":"この部屋はぜんぜん暗くない。","en":"This room is not dark at all.","romaji":"Kono heya wa zenzen kurakunai.","zh":""},{"ja":"彼女はぜんぜん疲れていない。","en":"She is not tired at all.","romaji":"Kanojo wa zenzen tsukarete inai.","zh":""},{"ja":"その映画はぜんぜん面白くなかった。","en":"That movie was not interesting at all.","romaji":"Sono eiga wa zenzen omoshirokunakatta.","zh":""}]',replace('**Short**: Used to express ''not at all'' or ''completely'' in negative sentences.\n\n**Formation**: ぜんぜん + [Negative verb/adjective]\n\n**Long**: The ぜんぜん grammar point is used to emphasize a negative statement and can be translated as ''not at all'' or ''completely (in negative sense)''. It is commonly used with negative verbs or negative forms of adjectives, placed before the negative part.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_soshite','そして、～',NULL,NULL,'N5','[]','[{"ja":"朝起きて、そして宿題をしました。","en":"I woke up in the morning and then did my homework.","romaji":"Asa okite, soshite shukudai wo shimashita.","zh":""},{"ja":"コーヒーを飲んで、そして新聞を読みました。","en":"I drank coffee and then read the newspaper.","romaji":"Koohii wo nonde, soshite shinbun wo yomimashita.","zh":""},{"ja":"家を出発しました。そして、駅へ行きました。","en":"I left my house and then went to the station.","romaji":"Ie wo shuppatsu shimashita. Soshite, eki e ikimashita.","zh":""},{"ja":"彼はゲームをした。そして、テレビを見ました。","en":"He played games and then watched TV.","romaji":"Kare wa geemu wo shita. Soshite, terebi wo mimashita.","zh":""}]',replace('**Short**: Used to connect two sentences; ''and then'', ''and''.\n\n**Formation**: Sentence 1 + そして + Sentence 2\n\n**Long**: The そして grammar point is used to connect two sentences or ideas, expressing a sequence of events or actions. It is commonly translated to ''and then'' or simply ''and'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sochira','そちら～',NULL,NULL,'N5','[]','[{"ja":"そちらのレストランはどうですか？","en":"How is that restaurant over there?","romaji":"Sochira no resutoran wa dou desu ka?","zh":""},{"ja":"そちらの方、お名前を教えていただけますか？","en":"Could you tell me the name of that person over there?","romaji":"Sochira no kata, onamae o oshiete itadakemasu ka?","zh":""},{"ja":"そちらに行く途中で駅があります。","en":"There is a station on the way to that direction.","romaji":"Sochira ni iku tochuu de eki ga arimasu.","zh":""},{"ja":"そちらのかばん、私のと似ていますね。","en":"That bag over there looks similar to mine.","romaji":"Sochira no kaban, watashi no to niteimasu ne.","zh":""}]',replace('**Short**: Indicates a direction or person in moderate distance; ''that way'', ''that person''.\n\n**Formation**: そちら [alone] / そちら + の + Noun\n\n**Long**: The そちら grammar point is used to refer to a direction or a person that is moderate distance from both the speaker and listener, often closer to the listener. It can be translated as ''that way'', ''that person'', or ''that side''. This is distinct from あちら, used for things far from both speaker and listener.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sorekara','それから、～',NULL,NULL,'N5','[]','[{"ja":"コーヒーを飲んで、それから家を出ました。","en":"I drank coffee, and then I left the house.","romaji":"Koohii o nonde, sorekara ie o demashita.","zh":""},{"ja":"買い物をして、それから映画を見に行きました。","en":"I went shopping, and then I went to watch a movie.","romaji":"Kaimono o shite, sorekara eiga o mini ikimashita.","zh":""},{"ja":"彼女は勉強をして、それから寝ました。","en":"She studied, and then she went to sleep.","romaji":"Kanojo wa benkyou o shite, sorekara nemashita.","zh":""},{"ja":"パーティーに行って、それから友達と話しました。","en":"I went to the party, and then I talked with my friends.","romaji":"Paatii ni itte, sorekara tomodachi to hanashimashita.","zh":""}]',replace('**Short**: Meaning ''after that'', ''and then'' or ''then'', indicating sequence of events.\n\n**Formation**: Clause 1 + それから + Clause 2\n\n**Long**: The それから grammar point is used to describe the sequence of events or actions, indicating that one action or event takes place after another. It can be translated as ''after that'', ''and then'', or ''then'' in English. It can be used with verbs, adjectives, and nouns but should be placed between two clauses.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_daitai','だいたい〜',NULL,NULL,'N5','[]','[{"ja":"だいたい１００人がパーティーに参加しました。","en":"Approximately 100 people attended the party.","romaji":"Daitai hyaku-nin ga paatii ni sanka shimashita.","zh":""},{"ja":"彼女はだいたい２時間でその仕事を終えます。","en":"She finishes that work in roughly two hours.","romaji":"Kanojo wa daitai ni-jikan de sono shigoto o oemasu.","zh":""},{"ja":"だいたい８０％の生徒が試験に合格しました。","en":"About 80% of the students passed the exam.","romaji":"Daitai hachijuu-paasento no seito ga shiken ni goukaku shimashita.","zh":""},{"ja":"今日はだいたい３０度の暑さです。","en":"Today is almost 30 degrees hot.","romaji":"Kyou wa daitai sanjuu-do no atsusa desu.","zh":""}]',replace('**Short**: Expresses ''roughly'', ''approximately'', or ''almost''.\n\n**Formation**: だいたい + Number/Amount/Percentage\n\n**Long**: The だいたい〜 (daitai〜) grammar point is used to express a rough estimate or generalization, meaning ''roughly'', ''approximately'', or ''almost'' in English. It can be used before numbers, amounts, or percentages to show that the value is not exact.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_taitei','たいてい～',NULL,NULL,'N5','[]','[{"ja":"たいてい朝８時に起きます。","en":"I usually wake up at 8 o''clock in the morning.","romaji":"Taitei asa hachi-ji ni okimasu.","zh":""},{"ja":"彼はたいてい遅刻します。","en":"He is usually late.","romaji":"Kare wa taitei chikoku shimasu.","zh":""},{"ja":"この店の商品はたいてい安いです。","en":"The items at this store are usually cheap.","romaji":"Kono mise no shouhin wa taitei yasui desu.","zh":""},{"ja":"たいていの人はその映画が好きです。","en":"Most people like that movie.","romaji":"Taitei no hito wa sono eiga ga suki desu.","zh":""}]',replace('**Short**: Used for expressing ''usually'', ''mostly'', or ''generally''.\n\n**Formation**: たいてい + Verb/い-Adjective/な-Adjective/Noun\n\n**Long**: The たいてい grammar point is used to describe a situation that occurs frequently or under normal circumstances. It can be translated as ''usually'', ''mostly'', or ''generally'' in English. It is often used with verbs, but can also be used with adjectives and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dakara','だから、～',NULL,NULL,'N5','[]','[{"ja":"雨だから、傘を持って行きましょう。","en":"Because it''s raining, let''s bring an umbrella.","romaji":"Ame dakara, kasa wo motte ikimashou.","zh":""},{"ja":"このケーキは有名だから、みんなが食べたいです。","en":"Because this cake is famous, everyone wants to eat it.","romaji":"Kono keeki wa yuumei dakara, minna ga tabetai desu.","zh":""},{"ja":"彼は病気だから、学校に行けません。","en":"Because he is sick, he cannot go to school.","romaji":"Kare wa byouki dakara, gakkou ni ikemasen.","zh":""},{"ja":"彼女は学生だから、このレストランで割引があります。","en":"Because she is a student, there is a discount at this restaurant.","romaji":"Kanojo wa gakusei dakara, kono resutoran de waribiki ga arimasu.","zh":""}]',replace('**Short**: Expresses a reason or cause; ''because'', ''so'', ''therefore''.\n\n**Formation**: Noun + だから / な-Adjective + だから\n\n**Long**: The だから grammar point is used to connect two sentences and express a reason or cause for the second sentence. It is typically used with nouns or な-adjectives, and can be translated as ''because'', ''so'', or ''therefore'' in English. For verbs/い-adjectives, the form is usually ～から (not だから).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tari_tari_shimasu','～たり、～たり します',NULL,NULL,'N5','[]','[{"ja":"休日には、映画を見たり、友達と遊んだりします。","en":"On holidays, I do things like watch movies and hang out with friends.","romaji":"Kyuujitsu ni wa, eiga wo mitari, tomodachi to asondari shimasu.","zh":""},{"ja":"彼は歌ったり、踊ったり、ピアノを弾いたりします。","en":"He sings, dances, plays the piano, among other things.","romaji":"Kare wa utattari, odottari, piano wo hikitari shimasu.","zh":""},{"ja":"このレストランでは、寿司を食べたり、刺身を食べたりします。","en":"At this restaurant, you can eat sushi, sashimi, and so on.","romaji":"Kono resutoran de wa, sushi wo tabetari, sashimi wo tabetari shimasu.","zh":""},{"ja":"彼女は毎朝、ジョギングしたり、ヨガをしたりします。","en":"Every morning, she does things like jogging and yoga.","romaji":"Kanojo wa maiasa, joggingu shitari, yoga wo shitari shimasu.","zh":""}]',replace('**Short**: Used to list multiple actions or states; ''do things like'', ''and''.\n\n**Formation**: Verb-casual-past + たり + Verb-casual-past + たり + します\n\n**Long**: The ～たり、～たり します grammar point is used to list multiple actions or states without fully enumerating them. It can imply that there are more items in the list and can be translated as ''do things like'', ''and'', ''among other things'', or ''and so on'' in English. It is formed by attaching たり to the casual past tense of the verb, followed by します.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dare','だれ～',NULL,NULL,'N5','[]','[{"ja":"だれがその本を買いましたか。","en":"Who bought that book?","romaji":"Dare ga sono hon o kaimashita ka.","zh":""},{"ja":"だれを待っていますか。","en":"Whom are you waiting for?","romaji":"Dare o matteimasu ka.","zh":""},{"ja":"だれがそのリンゴを食べましたか。","en":"Who ate that apple?","romaji":"Dare ga sono ringo o tabemashita ka.","zh":""},{"ja":"だれが鍵を持っていますか。","en":"Who has the key?","romaji":"Dare ga kagi o motteimasu ka.","zh":""}]',replace('**Short**: Asking ''who'' in a sentence, used to inquire about someone''s identity or to clarify who is being referred to.\n\n**Formation**: だれ + appropriate particle (が, は or を)\n\n**Long**: The だれ〜 grammar point is used to ask about the identity of someone in a sentence. It can be translated as ''who'' or ''whom'' in English. It is often used with the particle が, は, or を, but can also be combined with other particles depending on the context.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dareka','だれか〜',NULL,NULL,'N5','[]','[{"ja":"だれかがドアをノックしました。","en":"Someone knocked on the door.","romaji":"Dareka ga doa wo nokku shimashita.","zh":""},{"ja":"だれかが私の傘を盗みました。","en":"Someone stole my umbrella.","romaji":"Dareka ga watashi no kasa wo nusumimashita.","zh":""},{"ja":"だれか助けてください。","en":"Someone, please help.","romaji":"Dareka tasukete kudasai.","zh":""},{"ja":"だれかのせいで、電気がきれました。","en":"Because of someone, the electricity went out.","romaji":"Dareka no sei de, denki ga kiremashita.","zh":""}]',replace('**Short**: Indicates ''someone'' or something done or possessed by ''someone''.\n\n**Formation**: だれか + Verb, だれか + Adjective, だれか + Noun\n\n**Long**: The grammar point だれか〜 is used to suggest that something is done by, possessed by, or related to ''someone'', usually when the actual person is unidentified or not important. It can be used with verbs, adjectives, or nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dare_demo','だれでも～',NULL,NULL,'N5','[]','[{"ja":"だれでもこのゲームができます。","en":"Anyone can play this game.","romaji":"Dare demo kono geemu ga dekimasu.","zh":""},{"ja":"だれでも疲れることがあります。","en":"Everyone gets tired sometimes.","romaji":"Dare demo tsukareru koto ga arimasu.","zh":""},{"ja":"だれでも無料でこのイベントに参加できます。","en":"Anyone can participate in this event for free.","romaji":"Dare demo muryou de kono ibento ni sanka dekimasu.","zh":""},{"ja":"だれでもこの町の観光スポットを楽しむことができます。","en":"No matter who you are, you can enjoy the sightseeing spots in this town.","romaji":"Dare demo kono machi no kankou supotto wo tanoshimu koto ga dekimasu.","zh":""}]',replace('**Short**: Used to express ''anyone'' or ''everyone''; ''no matter who''.\n\n**Formation**: だれでも + Verb/Adjective/Noun\n\n**Long**: The grammar point だれでも is used to emphasize that something applies to everyone or anyone, regardless of who they are. It can be translated as ''anyone'', ''everyone'', or ''no matter who'' in English. It is used in sentences to show that a certain situation, characteristic, or condition applies to all people.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dare_mo_nai_desu','だれも～ないです',NULL,NULL,'N5','[]','[{"ja":"だれも知らないです。","en":"Nobody knows.","romaji":"Daremo shiranai desu.","zh":""},{"ja":"だれも来ないです。","en":"Nobody is coming.","romaji":"Daremo konai desu.","zh":""},{"ja":"彼女はだれも好きじゃないです。","en":"She doesn''t like anyone.","romaji":"Kanojo wa daremo suki ja nai desu.","zh":""},{"ja":"ここにはだれもいないです。","en":"There is nobody here.","romaji":"Koko ni wa daremo inai desu.","zh":""}]',replace('**Short**: Express ''nobody'' or ''no one'' in a negative sentence.\n\n**Formation**: だれも + Verb-negative form (ないです), だれも + い-Adjective-negative form (ないです), だれも + な-Adjective-negative form (じゃないです)\n\n**Long**: The grammar point だれも～ないです is used to express the idea of ''nobody'' or ''no one'' in a negative sentence. だれも is followed by the negative form of a verb or adjective, often using the polite ないです form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_daremo_masen','だれも～ません',NULL,NULL,'N5','[]','[{"ja":"だれも秘密を知りません。","en":"No one knows the secret.","romaji":"Daremo himitsu wo shirimasen.","zh":""},{"ja":"だれもその質問に答えませんでした。","en":"Nobody answered that question.","romaji":"Daremo sono shitsumon ni kotaemasen deshita.","zh":""},{"ja":"だれも彼を助けてあげません。","en":"Nobody will help him.","romaji":"Daremo kare wo tasukete agemasen.","zh":""},{"ja":"だれもその映画を見たがりません。","en":"No one wants to watch that movie.","romaji":"Daremo sono eiga wo mitagarimasen.","zh":""}]',replace('**Short**: Express ''nobody'' or ''no one'' in negative sentences.\n\n**Formation**: だれも + Verb-negative (ません)\n\n**Long**: The grammar point だれも is used in combination with a negative form of the verb, usually ません, to express the idea of ''nobody'' or ''no one'' doing something. It is used with questions or statements and can be translated as ''nobody'' or ''no one'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dou_shimasu_ka','～どう しますか。',NULL,NULL,'N5','[]','[{"ja":"雨が降っているので、どうしますか？","en":"It''s raining, so what will you do?","romaji":"Ame ga futte iru node, dou shimasu ka?","zh":""},{"ja":"この問題について、どうしますか？","en":"What are you going to do about this issue?","romaji":"Kono mondai ni tsuite, dou shimasu ka?","zh":""},{"ja":"彼が来なかったら、どうしますか？","en":"If he doesn''t come, what will you do?","romaji":"Kare ga konakattara, dou shimasu ka?","zh":""},{"ja":"進路を決める時、どうしますか？","en":"What will you do when choosing your career path?","romaji":"Shinro wo kimeru toki, dou shimasu ka?","zh":""}]',replace('**Short**: Asking for someone''s opinion or decision; ''what will you do?'', ''how will you handle it?''.\n\n**Formation**: Situation + どうしますか\n\n**Long**: The ～どうしますか grammar point is used to ask for someone''s opinion, decision, or course of action in a specific situation. It can be translated as ''what will you do?'' or ''how will you handle it?'' in English. This grammar point is formed by attaching どうしますか to the end of a sentence.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dou_desu_ka','～どうですか。',NULL,NULL,'N5','[]','[{"ja":"この映画はどうですか？","en":"How about this movie? / What do you think of this movie?","romaji":"Kono eiga wa dou desu ka?","zh":""},{"ja":"晩ご飯に寿司を食べるのはどうですか？","en":"How about eating sushi for dinner?","romaji":"Bangohan ni sushi wo taberu no wa dou desu ka?","zh":""},{"ja":"この部屋は広いと思いますが、どうですか？","en":"I think this room is spacious, what do you think?","romaji":"Kono heya wa hiroi to omoimasu ga, dou desu ka?","zh":""},{"ja":"新しい会社の要件が厳しいですね。鈴木さん、転職するならどうですか？","en":"The new company''s requirements are strict, aren''t they? Suzuki-san, how about changing jobs if that''s the case?","romaji":"Atarashii kaisha no youken ga kibishii desu ne. Suzuki-san, tenshoku suru nara dou desu ka?","zh":""}]',replace('**Short**: Asking for opinions or suggestions; ''how about'', ''what do you think of''.\n\n**Formation**: Noun + は/が + どうですか / Verb-casual + の + どうですか / い-Adjective + どうですか / な-Adjective + な + どうですか\n\n**Long**: The ～どうですか grammar point is used to ask for someone''s opinion or suggestion on something. It can be translated as ''how about'' or ''what do you think of'' in English. This expression is neither casual nor super-formal, and can be used in various situations.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_douyatte','どうやって～',NULL,NULL,'N5','[]','[{"ja":"どうやってお寿司を作りますか？","en":"How do you make sushi?","romaji":"Douyatte o-sushi wo tsukurimasu ka?","zh":""},{"ja":"どうやって日本語を勉強しましたか？","en":"How did you study Japanese?","romaji":"Douyatte nihongo wo benkyou shimashita ka?","zh":""},{"ja":"どうやってこの問題を解決しますか？","en":"How do you solve this problem?","romaji":"Douyatte kono mondai wo kaiketsu shimasu ka?","zh":""},{"ja":"どうやって駅に行きますか？","en":"How do you go to the station?","romaji":"Douyatte eki ni ikimasu ka?","zh":""}]',replace('**Short**: Ask ''how'' something is done or how to do something.\n\n**Formation**: どうやって + Verb-casual\n\n**Long**: The grammar point どうやって is used to ask how something is done or how to do something, and is translated as ''how'' in English. It is often used in combination with verbs to inquire about the method or process someone goes through to complete a task or action.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dou_iimasu_ka','～どう 言いますか。',NULL,NULL,'N5','[]','[{"ja":"「ありがとう」は英語でどう言いますか。","en":"How do you say ''thank you'' in English?","romaji":"「Arigatou」wa eigo de dou iimasu ka.","zh":""},{"ja":"この言葉を日本語でどう言いますか。","en":"How do you say this word in Japanese?","romaji":"Kono kotoba wo nihongo de dou iimasu ka.","zh":""},{"ja":"「すみません」はフランス語でどう言いますか。","en":"How do you say ''excuse me'' in French?","romaji":"「Sumimasen」wa furansugo de dou iimasu ka.","zh":""},{"ja":"その表現をスペイン語でどう言いますか。","en":"How do you say that expression in Spanish?","romaji":"Sono hyougen wo supeingo de dou iimasu ka.","zh":""}]',replace('**Short**: Asking for the way to say something; ''how do you say''.\n\n**Formation**: Word/Phrase + は [language]でどう言いますか / Word/Phrase + をどう言いますか\n\n**Long**: The ～どう言いますか grammar point is used to ask someone how to express something in a particular language or the appropriate way to say it. It can be translated as ''how do you say'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_toki','～とき',NULL,NULL,'N5','[]','[{"ja":"公園で遊ぶとき、帽子をかぶりましょう。","en":"When playing in the park, let''s wear a hat.","romaji":"Kouen de asobu toki, boushi wo kaburimashou.","zh":""},{"ja":"このりんごが赤いとき、食べごろです。","en":"This apple is ready to eat when it is red.","romaji":"Kono ringo ga akai toki, tabegoro desu.","zh":""},{"ja":"私が勉強するとき、家族は静かにしてくれます。","en":"When I am studying, my family keeps quiet for me.","romaji":"Watashi ga benkyou suru toki, kazoku wa shizuka ni shite kuremasu.","zh":""},{"ja":"子供のとき、よくおばあちゃんの家に遊びに行きました。","en":"When I was a child, I often went to play at my grandmother''s house.","romaji":"Kodomo no toki, yoku obaachan no ie ni asobi ni ikimashita.","zh":""}]',replace('**Short**: Expresses the time when something happens, ''when'', ''at the time''.\n\n**Formation**: Verb-casual + とき / い-Adjective + とき / な-Adjective + なとき / Noun + のとき\n\n**Long**: The ～とき grammar point is used to express the time when something happens or happened. It can be translated as ''when'' or ''at the time'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tokidoki','ときどき～',NULL,NULL,'N5','[]','[{"ja":"彼はときどきケーキを作ります。","en":"He sometimes makes cakes.","romaji":"Kare wa tokidoki keeki o tsukurimasu.","zh":""},{"ja":"ときどき雨が降るので、傘を持って行ったほうがいいです。","en":"It occasionally rains, so it''s better to bring an umbrella.","romaji":"Tokidoki ame ga furu node, kasa o motte itta hou ga ii desu.","zh":""},{"ja":"私はときどきこの店で買い物をします。","en":"I shop at this store now and then.","romaji":"Watashi wa tokidoki kono mise de kaimono o shimasu.","zh":""},{"ja":"彼女はときどき遅刻します。","en":"She is sometimes late.","romaji":"Kanojo wa tokidoki chikoku shimasu.","zh":""}]',replace('**Short**: Used to indicate the frequency of an event; ''sometimes'', ''occasionally'', ''now and then''.\n\n**Formation**: ときどき + Verb/Adjective/Noun\n\n**Long**: The grammar point ときどき is an adverb used to describe an event or action that occurs occasionally or at irregular intervals. It can be translated as ''sometimes'', ''occasionally'', or ''now and then'' in English. It is often used to indicate that the speaker cannot predict the exact time when a certain event occurs.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_doko','どこ～',NULL,NULL,'N5','[]','[{"ja":"駅はどこですか？","en":"Where is the station?","romaji":"Eki wa doko desu ka?","zh":""},{"ja":"どこで映画を見ましたか？","en":"Where did you watch the movie?","romaji":"Doko de eiga wo mimashita ka?","zh":""},{"ja":"どこに住んでいますか？","en":"Where do you live?","romaji":"Doko ni sunde imasu ka?","zh":""},{"ja":"どこへ行きたいですか？","en":"Where do you want to go?","romaji":"Doko e ikitai desu ka?","zh":""}]',replace('**Short**: Express ''where'', used with question words for asking about locations.\n\n**Formation**: どこ + question particle\n\n**Long**: The どこ～ grammar point is used to express ''where'', primarily for asking about locations or places. It is often combined with question words such as どこへ (doko e), どこで (doko de), and どこに (doko ni) to ask about destinations, locations of actions, and existence, respectively.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dokoka','どこか～',NULL,NULL,'N5','[]','[{"ja":"どこかで財布をなくしました。","en":"I lost my wallet somewhere.","romaji":"Dokoka de saifu wo nakushimashita.","zh":""},{"ja":"今日はどこかに行きたいです。","en":"I want to go somewhere today.","romaji":"Kyou wa dokoka ni ikitai desu.","zh":""},{"ja":"どこか安いレストランがありますか？","en":"Is there a cheap restaurant somewhere?","romaji":"Dokoka yasui resutoran ga arimasu ka?","zh":""},{"ja":"どこか静かな場所で勉強したい。","en":"I want to study in a quiet place somewhere.","romaji":"Dokoka shizuka na basho de benkyou shitai.","zh":""}]',replace('**Short**: Expresses ''somewhere'', used when the specific location is unknown or uncertain.\n\n**Formation**: どこか + (Particle, if needed) + Verb/Noun/Adjective\n\n**Long**: The grammar point どこか is used when the speaker wants to express that something is happening or located ''somewhere'', but the exact location is either unknown or uncertain. It can be used by itself or combined with other words.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dokodemo','どこでも～',NULL,NULL,'N5','[]','[{"ja":"どこでも好きな場所で勉強できます。","en":"You can study anywhere you like.","romaji":"Dokodemo sukina basho de benkyou dekimasu.","zh":""},{"ja":"このノートパソコンは便利なので、どこでもインターネットが使えます。","en":"This laptop is convenient, so you can use the internet anywhere.","romaji":"Kono nootopasokon wa benri nano de, dokodemo intaanetto ga tsukaemasu.","zh":""},{"ja":"彼はどこでも寝ることができます。","en":"He can sleep anywhere.","romaji":"Kare wa dokodemo neru koto ga dekimasu.","zh":""},{"ja":"彼女はどこでも歌うのが大好きです。","en":"She loves singing anywhere.","romaji":"Kanojo wa dokodemo utau no ga daisuki desu.","zh":""}]',replace('**Short**: Express ''anywhere'' or ''everywhere'' in Japanese.\n\n**Formation**: Simply use the word どこでも in the sentence as an adverb to indicate ''anywhere'' or ''everywhere''.\n\n**Long**: The grammar point どこでも is used to express ''anywhere'' or ''everywhere'' in Japanese. It is usually used in sentences to indicate that an action or situation could happen or exist in any location.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_doko_ni_mo_verb_nai_desu','どこにも + Verb + ないです',NULL,NULL,'N5','[]','[{"ja":"どこにも傘が売ってないです。","en":"Umbrellas are not sold anywhere.","romaji":"Doko ni mo kasa ga uttenai desu.","zh":""},{"ja":"彼はどこにも見つけられないです。","en":"He cannot be found anywhere.","romaji":"Kare wa doko ni mo mitsukerarenai desu.","zh":""},{"ja":"どこにも勉強できる場所がないです。","en":"There is no place to study anywhere.","romaji":"Doko ni mo benkyou dekiru basho ga nai desu.","zh":""},{"ja":"どこにも美味しいビーガン料理がないです。","en":"There are no delicious vegan dishes anywhere.","romaji":"Doko ni mo oishii bi-gan ryouri ga nai desu.","zh":""}]',replace('**Short**: Express that an action cannot be performed anywhere or something cannot be found anywhere.\n\n**Formation**: どこにも + Verb in ない-form + です\n\n**Long**: The grammar point どこにも + Verb + ないです is used to express that an action cannot be performed anywhere or something cannot be found anywhere. It is used with a negative verb conjugation (ない-form) and highlights the unavailability or impossibility of finding or doing something in any location.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_doko_ni_mo_verb_masen','どこにも + Verb + ません',NULL,NULL,'N5','[]','[{"ja":"どこにもあの猫がいません。","en":"The cat is not anywhere.","romaji":"Doko ni mo ano neko ga imasen.","zh":""},{"ja":"どこにもお金を置いていません。","en":"I didn''t put the money anywhere.","romaji":"Doko ni mo okane wo oiteimasen.","zh":""},{"ja":"この町にはどこにも美味しいラーメン屋がありません。","en":"There are no delicious ramen shops anywhere in this town.","romaji":"Kono machi ni wa doko ni mo oishii raamenya ga arimasen.","zh":""},{"ja":"どこにも彼女の名前が書いていません。","en":"Her name is not written anywhere.","romaji":"Doko ni mo kanojo no namae ga kaiteimasen.","zh":""}]',replace('**Short**: Express ''not anywhere'' or ''nowhere'' with a negative verb.\n\n**Formation**: どこにも + Verb-negative\n\n**Long**: The どこにも～ません grammar point is used to express that something doesn''t exist, appear, or happen anywhere. It means ''not anywhere'' or ''nowhere'' when used with a negative verb. The formation is quite simple as you just need to add どこにも before the negative verb.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_doko_e_mo_verb_nai_desu','どこへも Verb ないです',NULL,NULL,'N5','[]','[{"ja":"今週末どこへも行かないです。","en":"I''m not going anywhere this weekend.","romaji":"Konshuumatsu doko e mo ikanai desu.","zh":""},{"ja":"彼女はどこへも買い物に行きませんでした。","en":"She didn''t go shopping anywhere.","romaji":"Kanojo wa doko e mo kaimono ni ikimasen deshita.","zh":""},{"ja":"スーパーはどこへも売らないです。","en":"It''s not sold at any supermarket.","romaji":"Suupaa wa doko e mo uranai desu.","zh":""},{"ja":"私はどこへも行く予定がないです。","en":"I have no plans to go anywhere.","romaji":"Watashi wa doko e mo iku yotei ga nai desu.","zh":""}]',replace('**Short**: Express that an action doesn''t take place anywhere; ''nowhere'', ''not anywhere''.\n\n**Formation**: どこへも + Verb in negative form (ないです)\n\n**Long**: The どこへも + Verb ないです grammar point is used to express a situation where an action doesn''t occur or isn''t applicable anywhere. It emphasizes a strong sense of not performing the action anywhere. Keep in mind that only negative verbs can follow ''どこへも'' in this construction.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_doko_e_mo_verb_masen','どこへも Verb ません',NULL,NULL,'N5','[]','[{"ja":"今日はどこへも行きません。","en":"I won''t go anywhere today.","romaji":"Kyou wa doko e mo ikimasen.","zh":""},{"ja":"彼はどこへも走りませんでした。","en":"He didn''t run anywhere.","romaji":"Kare wa doko e mo hashirimasen deshita.","zh":""},{"ja":"どこへも買い物に行きませんでした。","en":"I didn''t go shopping anywhere.","romaji":"Doko e mo kaimono ni ikimasen deshita.","zh":""},{"ja":"彼女はどこへも連れて行かせません。","en":"She won''t take me anywhere.","romaji":"Kanojo wa doko e mo tsurete ikasemasen.","zh":""}]',replace('**Short**: Nowhere; Not to any place\n\n**Formation**: どこへも + Verb-negative\n\n**Long**: The grammar point どこへも is used to express the idea of ''nowhere'' or ''not to any place''. It is combined with the negative form of a verb to indicate that the action does not happen to any place or destination.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dokomo_verb_naidesu','どこも Verb ないです',NULL,NULL,'N5','[]','[{"ja":"どこもうちわがないです。","en":"I can''t find fans anywhere.","romaji":"Doko mo uchiwa ga nai desu.","zh":""},{"ja":"この町ではどこも美味しいラーメンがないです。","en":"There are no delicious ramen shops anywhere in this town.","romaji":"Kono machi de wa doko mo oishii raamen ga nai desu.","zh":""},{"ja":"どこも駐車場がないです。","en":"There is no parking anywhere.","romaji":"Doko mo chuushajou ga nai desu.","zh":""},{"ja":"どこも席がないです。","en":"There are no seats available anywhere.","romaji":"Doko mo seki ga nai desu.","zh":""}]',replace('**Short**: Express that something cannot be found anywhere or in any place; ''nowhere'', ''in no place''.\n\n**Formation**: どこも + Verb-negative\n\n**Long**: The どこも～ないです grammar point is used to express that something cannot be found anywhere or in any place. It can be translated as ''nowhere'' or ''in no place'' in English. It is used in combination with a negative verb (ないです) to indicate the absence of something.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dokomo_verb_masen','どこも Verb ません',NULL,NULL,'N5','[]','[{"ja":"どこも静かじゃありません。","en":"Nowhere is quiet.","romaji":"Doko mo shizuka ja arimasen.","zh":""},{"ja":"どこもその本を売っていません。","en":"Nowhere sells that book.","romaji":"Doko mo sono hon wo utte imasen.","zh":""},{"ja":"この地域では、どこもインターネットに接続できません。","en":"In this area, nowhere can connect to the internet.","romaji":"Kono chiiki de wa, doko mo intaanetto ni setsuzoku dekimasen.","zh":""},{"ja":"どこも彼を知りません。","en":"No place knows him.","romaji":"Doko mo kare wo shirimasen.","zh":""}]',replace('**Short**: Express that ''nowhere'' meets the verb action; ''nowhere does/can''.\n\n**Formation**: どこも + Verb-ます form + ません\n\n**Long**: The どこも + Verb ません grammar point is used to express that nowhere does or can fulfill the verb action. It is a negative statement and can be translated as ''nowhere (+ verb)'' in English. Note that the first example below uses an adjective rather than a verb, which still conveys ''nowhere is ...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dochira','どちら～',NULL,NULL,'N5','[]','[{"ja":"この二つのリンゴ、どちらが美味しいですか？","en":"Which of these two apples is delicious?","romaji":"Kono futatsu no ringo, dochira ga oishii desu ka?","zh":""},{"ja":"どちらのドレスを着たいですか？","en":"Which dress would you like to wear?","romaji":"Dochira no doresu wo kitai desu ka?","zh":""},{"ja":"この二つの町、どちらに行きたいですか？","en":"Which of these two towns do you want to go to?","romaji":"Kono futatsu no machi, dochira ni ikitai desu ka?","zh":""},{"ja":"どちらの映画が面白いと思いますか？","en":"Which movie do you think is interesting?","romaji":"Dochira no eiga ga omoshiroi to omoimasu ka?","zh":""}]',replace('**Short**: Used to ask about two choices or options.\n\n**Formation**: どちら + が/を + verb, どちら + が/を + adjective, どちら + が/を + noun\n\n**Long**: The どちら grammar point is used to ask about two choices or options. It translates to ''which of the two'' or simply ''which'' in English. It is commonly used with question words like どちらが or どちらを and can be combined with verbs, adjectives, and nouns to ask about preferences or to make comparisons.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_donata','どなた～',NULL,NULL,'N5','[]','[{"ja":"すみません、どなたが山田さんですか？","en":"Excuse me, who is Mr. Yamada?","romaji":"Sumimasen, donata ga Yamada-san desu ka?","zh":""},{"ja":"どなたも知っている有名な俳優です。","en":"He is a famous actor whom everyone knows.","romaji":"Donata mo shitte iru yuumei na haiyuu desu.","zh":""},{"ja":"明日のパーティーにはどなたが来ますか？","en":"Who is coming to the party tomorrow?","romaji":"Ashita no paatii ni wa donata ga kimasu ka?","zh":""},{"ja":"どなたか手伝っていただけますか？","en":"Could someone please help me?","romaji":"Donata ka tetsudatte itadakemasu ka?","zh":""}]',replace('**Short**: A polite way to ask ''who'', used for asking about someone''s identity or when seeking information about an unknown person.\n\n**Formation**: どなた\n\n**Long**: The word どなた is a polite version of the question word だれ (who). It is used when asking about someone''s identity or when seeking information about an unknown person in a polite or formal context. It can be used in questions and sometimes with も to express ''no matter who''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dono_noun','どの Noun',NULL,NULL,'N5','[]','[{"ja":"どの本が一番面白いですか。","en":"Which book is the most interesting?","romaji":"Dono hon ga ichiban omoshiroi desu ka?","zh":""},{"ja":"どの服を着たいですか。","en":"Which clothes do you want to wear?","romaji":"Dono fuku wo kitai desu ka?","zh":""},{"ja":"どの色が好きですか。","en":"Which color do you like?","romaji":"Dono iro ga suki desu ka?","zh":""},{"ja":"どのレストランに行きたいですか。","en":"Which restaurant do you want to go to?","romaji":"Dono resutoran ni ikitai desu ka?","zh":""}]',replace('**Short**: Expresses ''which''; used to ask about specific items within a group.\n\n**Formation**: どの + Noun\n\n**Long**: The どの Noun grammar point is used to ask about specific items or objects within a group. It is the combination of the question word ど (which) and the particle の to connect to a noun. In English, it can be translated as ''which'' depending on the context.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dore_demo','どれでも～',NULL,NULL,'N5','[]','[{"ja":"どれでもいいですか？","en":"Is any choice okay?","romaji":"Dore demo ii desu ka?","zh":""},{"ja":"どれでも選んでください。","en":"Please choose whichever you like.","romaji":"Dore demo erande kudasai.","zh":""},{"ja":"どれでもおいしいです。","en":"All of them are delicious.","romaji":"Dore demo oishii desu.","zh":""},{"ja":"この中でどれでも好きなものを持って行ってください。","en":"Please take whichever you like from these.","romaji":"Kono naka de dore demo suki na mono wo motte itte kudasai.","zh":""}]',replace('**Short**: Indicates ''any'' or ''whichever'' when referring to multiple items.\n\n**Formation**: どれ + でも\n\n**Long**: The どれでも grammar point is used to express that any option or element among multiple choices is acceptable. It can be translated as ''any'' or ''whichever'' in English. It is often used in questions or suggestions and is commonly seen with でも, but it can also be used with だれでも, いつでも, どこでも, etc.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_donna','どんな Noun',NULL,NULL,'N5','[]','[{"ja":"どんな音楽が好きですか？","en":"What kind of music do you like?","romaji":"Donna ongaku ga suki desu ka?","zh":""},{"ja":"彼女はどんな映画が好きだと思う？","en":"What kind of movies do you think she likes?","romaji":"Kanojo wa donna eiga ga suki da to omou?","zh":""},{"ja":"どんな本が一番面白いですか？","en":"What kind of books are the most interesting?","romaji":"Donna hon ga ichiban omoshiroi desu ka?","zh":""},{"ja":"どんな料理が得意ですか？","en":"What kind of dishes are you good at making?","romaji":"Donna ryouri ga tokui desu ka?","zh":""}]',replace('**Short**: Used to ask or describe ''what kind'' or ''what type'' of something.\n\n**Formation**: どんな + Noun\n\n**Long**: The どんな (donna) grammar point is used to ask or describe ''what kind'' or ''what type'' of something. It is usually followed by a noun. It is similar to the English expression ''What kind of'' or ''What type of'' when asking about a specific characteristic or attribute.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nani','なに～',NULL,NULL,'N5','[]','[{"ja":"これはなにですか。","en":"What is this?","romaji":"Kore wa nani desu ka?","zh":""},{"ja":"あの人はなにをしているのですか？","en":"What is that person doing?","romaji":"Ano hito wa nani wo shite iru no desu ka?","zh":""},{"ja":"なにが好きですか？","en":"What do you like?","romaji":"Nani ga suki desu ka?","zh":""},{"ja":"今日の天気はなにですか？","en":"What is today''s weather?","romaji":"Kyou no tenki wa nani desu ka?","zh":""}]',replace('**Short**: Asking about ''what'' or ''which'' in Japanese\n\n**Formation**: Verb + なに, い-Adjective + なに, な-Adjective + なに, Noun + なに\n\n**Long**: The なに～ grammar point is used to ask questions about ''what'' or ''which'' in Japanese. It can be combined with various parts of speech to create different questions. The formation differs depending on whether it''s used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nanika','なにか～',NULL,NULL,'N5','[]','[{"ja":"なにか飲み物を持ってきてください。","en":"Please bring some kind of drink.","romaji":"Nanika nomimono wo motte kite kudasai.","zh":""},{"ja":"なにか質問があれば、遠慮なく聞いてください。","en":"If you have any questions, please feel free to ask.","romaji":"Nanika shitsumon ga areba, enryo naku kiite kudasai.","zh":""},{"ja":"彼女はなにかプレゼントを持っている。","en":"She has some kind of present.","romaji":"Kanojo wa nanika purezento wo motte iru.","zh":""},{"ja":"なにか助けが必要なら、言ってください。","en":"If you need any help, please let me know.","romaji":"Nanika tasuke ga hitsuyou nara, itte kudasai.","zh":""}]',replace('**Short**: Indicates ''something'' or ''some kind of''.\n\n**Formation**: なにか + Noun\n\n**Long**: The なにか grammar point is used to express the idea of ''something'' or ''some kind of'' in Japanese. It is often used when the speaker is unsure or not specific about the details of the noun being referred to. なにか is used before the noun it modifies.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nani_monai_desu','なにも～ないです',NULL,NULL,'N5','[]','[{"ja":"彼はなにも言わなかったです。","en":"He didn''t say anything.","romaji":"Kare wa nani mo iwanakatta desu.","zh":""},{"ja":"私はなにも食べないです。","en":"I don''t eat anything.","romaji":"Watashi wa nani mo tabenai desu.","zh":""},{"ja":"彼女はなにも持っていないです。","en":"She doesn''t have anything.","romaji":"Kanojo wa nani mo motte inai desu.","zh":""},{"ja":"この箱にはなにも入っていないです。","en":"There is nothing in this box.","romaji":"Kono hako ni wa nani mo haitte inai desu.","zh":""}]',replace('**Short**: Used to express ''not any'' or ''nothing'' in a negative sentence.\n\n**Formation**: なにも + Verb-negative\n\n**Long**: The なにも～ないです grammar point is used in negative sentences to express the idea of ''not any'', ''not at all'', ''nothing'', or ''none''. It is commonly used with verbs in the negative form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nanimomasen','なにも～ません',NULL,NULL,'N5','[]','[{"ja":"昨日はなにも食べませんでした。","en":"I didn''t eat anything yesterday.","romaji":"Kinou wa nanimo tabemasen deshita.","zh":""},{"ja":"彼はなにも話しません。","en":"He doesn''t say anything.","romaji":"Kare wa nanimo hanashimasen.","zh":""},{"ja":"この部屋ではなにも見えません。","en":"I cannot see anything in this room.","romaji":"Kono heya de wa nanimo miemasen.","zh":""},{"ja":"彼女はなにも買いませんでした。","en":"She didn''t buy anything.","romaji":"Kanojo wa nanimo kaimasen deshita.","zh":""}]',replace('**Short**: Used to express ''not anything'', ''nothing''.\n\n**Formation**: なにも + Verb-ます form + ません\n\n**Long**: The grammar point なにも～ません is used to express the idea of ''not anything'' or ''nothing'' in negative sentences. It is placed before the verb in its negative form (～ません).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nan','なん～',NULL,NULL,'N5','[]','[{"ja":"あなたはなん歳ですか？","en":"How old are you?","romaji":"Anata wa nan-sai desu ka?","zh":""},{"ja":"これはなんですか？","en":"What is this?","romaji":"Kore wa nan desu ka?","zh":""},{"ja":"彼はなんで来ましたか？","en":"Why did he come?","romaji":"Kare wa nan de kimashita ka?","zh":""},{"ja":"あのレストランはなんと言う名前ですか？","en":"What is the name of that restaurant?","romaji":"Ano resutoran wa nan to iu namae desu ka?","zh":""}]',replace('**Short**: Used to form interrogative questions and emphasize the question word for ''what'', ''how''.\n\n**Formation**: なん + Counter / なん + Verb / なん + Adjective\n\n**Long**: The なん～ grammar point is used to form interrogative questions and emphasize the question word for ''what'' or ''how''. It is an abbreviation of ''何'' meaning ''what''. Its usage can vary depending on whether it is used with a counter, verb, or adjective.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nande','なんで～',NULL,NULL,'N5','[]','[{"ja":"なんで遅れたの？","en":"Why were you late?","romaji":"Nande okureta no?","zh":""},{"ja":"なんでこの部屋はこんなに汚いの？","en":"Why is this room so dirty?","romaji":"Nande kono heya wa konna ni kitanai no?","zh":""},{"ja":"なんで彼女は怒っているの？","en":"Why is she angry?","romaji":"Nande kanojo wa okotte iru no?","zh":""},{"ja":"なんで今日は休みなの？","en":"Why is today a holiday?","romaji":"Nande kyou wa yasumi na no?","zh":""}]',replace('**Short**: Asking the reason or cause; ''why'', ''how come''.\n\n**Formation**: なんで + [phrase or sentence]\n\n**Long**: The なんで grammar point is used to ask the reason or cause behind something. It can be translated as ''why'' or ''how come'' in English. It is a casual way of asking for an explanation, and it can be used with verbs, い-adjectives, な-adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nandemo','なんでも～',NULL,NULL,'N5','[]','[{"ja":"なんでも食べられるから、何を頼んでも大丈夫です。","en":"I can eat anything, so it''s okay to order whatever you want.","romaji":"Nandemo taberareru kara, nani wo tanondemo daijoubu desu.","zh":""},{"ja":"なんでもよければ、この本をおすすめします。","en":"If you''re okay with anything, I recommend this book.","romaji":"Nandemo yokereba, kono hon wo osusume shimasu.","zh":""},{"ja":"なんでもできるスタッフを探しています。","en":"We are looking for a staff member who can do anything.","romaji":"Nandemo dekiru sutaffu wo sagashiteimasu.","zh":""},{"ja":"この食堂では、なんでも美味しくて安い料理が出されます。","en":"In this cafeteria, any dish served is delicious and inexpensive.","romaji":"Kono shokudou de wa, nandemo oishikute yasui ryouri ga dasaremasu.","zh":""}]',replace('**Short**: Means ''any'', ''anything'', ''anyone''.\n\n**Formation**: なんでも + Verb / なんでも + Adjective / なんでも + Noun\n\n**Long**: The なんでも grammar point is used to express the concept of ''any'', ''anything'', or ''anyone'' in Japanese. It can be used with verbs, adjectives, and nouns. It is often used in the meaning of ''no matter what'' or ''regardless of''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nan_to_iimasu_ka','～なんと 言いますか。',NULL,NULL,'N5','[]','[{"ja":"この花はなんと言いますか。","en":"How do you say this flower?","romaji":"Kono hana wa nan to iimasu ka.","zh":""},{"ja":"この料理はなんと言いますか。","en":"What do you call this dish?","romaji":"Kono ryouri wa nan to iimasu ka.","zh":""},{"ja":"日本でこれはなんと言いますか。","en":"How do you say this in Japanese?","romaji":"Nihon de kore wa nan to iimasu ka.","zh":""},{"ja":"その映画の名前はなんと言いますか。","en":"What is the name of that movie?","romaji":"Sono eiga no namae wa nan to iimasu ka.","zh":""}]',replace('**Short**: Asking how something is called or referred to; ''how do you say''\n\n**Formation**: Noun + は/が + なんと言いますか\n\n**Long**: The ～なんと言いますか grammar point is used to ask how something is called, expressed, or referred to in a polite manner. It can be translated as ''how do you say'' or ''what do you call'' in English. The formation is used with a noun or a topic where you would like to know the proper expression or name for something.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_agemasu','～に あげます',NULL,NULL,'N5','[]','[{"ja":"私は友達に本をあげました。","en":"I gave a book to my friend.","romaji":"Watashi wa tomodachi ni hon wo agemashita.","zh":""},{"ja":"彼にプレゼントをあげましょう。","en":"Let''s give him a present.","romaji":"Kare ni purezento wo agemashou.","zh":""},{"ja":"先生に花をあげます。","en":"I will give flowers to the teacher.","romaji":"Sensei ni hana wo agemasu.","zh":""},{"ja":"お母さんにチョコレートをあげたいです。","en":"I want to give chocolate to my mom.","romaji":"Okaasan ni chokoreeto wo agetai desu.","zh":""}]',replace('**Short**: Used to express giving something to someone; ''give'', ''offer''.\n\n**Formation**: Receiver + に + Object + を + あげます\n\n**Long**: The ～に あげます grammar point is used when the speaker offers or gives something to someone. It emphasizes that the action is performed for the benefit of the receiver. The formation involves using the particle ''に'' after the person receiving the item, followed by the verb あげます.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_moraimasu','～に もらいます',NULL,NULL,'N5','[]','[{"ja":"友達にプレゼントをもらいました。","en":"I received a gift from my friend.","romaji":"Tomodachi ni purezento wo moraimashita.","zh":""},{"ja":"先生にアドバイスをもらいました。","en":"I got advice from my teacher.","romaji":"Sensei ni adobaisu wo moraimashita.","zh":""},{"ja":"おばあさんに手紙を書いてもらいました。","en":"I had my grandmother write a letter for me.","romaji":"Obaasan ni tegami wo kaite moraimashita.","zh":""},{"ja":"弟に宿題を手伝ってもらいました。","en":"I got help from my younger brother with my homework.","romaji":"Otouto ni shukudai wo tetsudatte moraimashita.","zh":""}]',replace('**Short**: To receive something or some action from someone; ''to get'', ''to receive''.\n\n**Formation**: Giver + に + Verb-te form + もらいます / Giver + に + Object + を + もらいます\n\n**Long**: The ～に もらいます grammar point is used to express receiving something or some action from someone. It can be translated as ''to get'' or ''to receive'' in English. The formation involves placing に after the giver and もらいます to show the act of receiving.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_no_n5','～の',NULL,NULL,'N5','[]','[{"ja":"これは私の鞄です。","en":"This is my bag.","romaji":"Kore wa watashi no kaban desu.","zh":""},{"ja":"彼女は赤いバッグを持っています。","en":"She has a red bag.","romaji":"Kanojo wa akai baggu o motte imasu.","zh":""},{"ja":"彼はきれいな部屋があります。","en":"He has a clean room.","romaji":"Kare wa kirei na heya ga arimasu.","zh":""},{"ja":"東京の天気は暑いです。","en":"The weather in Tokyo is hot.","romaji":"Toukyou no tenki wa atsui desu.","zh":""}]',replace('**Short**: Express possession, apposition, or description using ''of'' or ''''s''.\n\n**Formation**: Noun1 + の + Noun2, (Adjective/Clause) + の (nominalized), etc.\n\n**Long**: The ～の grammar point is used to express possession, apposition, or description. It functions like ''of'' or an apostrophe + ''s'' (’s) in English. It can be used with nouns, adjectives, and verbs to show relationships between words.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wa_taihen_desu','～はたいへんです',NULL,NULL,'N5','[]','[{"ja":"漢字を覚えるのはたいへんです。","en":"It is difficult to remember kanji.","romaji":"Kanji o oboeru no wa taihen desu.","zh":""},{"ja":"この仕事はたいへんです。","en":"This job is tough.","romaji":"Kono shigoto wa taihen desu.","zh":""},{"ja":"日本の駅のことを理解するのはたいへんです。","en":"Understanding Japanese train stations is difficult.","romaji":"Nihon no eki no koto o rikai suru no wa taihen desu.","zh":""},{"ja":"彼女は病気の時、生活はたいへんです。","en":"When she is sick, life is tough.","romaji":"Kanojo wa byouki no toki, seikatsu wa taihen desu.","zh":""}]',replace('**Short**: Express that something is difficult or tough.\n\n**Formation**: Noun + はたいへんです\n\n**Long**: The ～はたいへんです grammar point is used to express that something is difficult or tough to do, handle, or face. It can be translated as ''is difficult'' or ''is tough'' in English. The formation is used with a noun followed by はたいへんです.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_hotondo','ほとんど〜',NULL,NULL,'N5','[]','[{"ja":"彼女はほとんど英語を話せません。","en":"She can hardly speak English.","romaji":"Kanojo wa hotondo eigo o hanasemasen.","zh":""},{"ja":"ほとんどの人がパーティーに出席しました。","en":"Most people attended the party.","romaji":"Hotondo no hito ga paatii ni shusseki shimashita.","zh":""},{"ja":"私たちはほとんど勉強しないでテストに合格しました。","en":"We passed the test with hardly any studying.","romaji":"Watashitachi wa hotondo benkyou shinaide tesuto ni goukaku shimashita.","zh":""},{"ja":"この本はほとんど読み終わりました。","en":"I have almost finished reading this book.","romaji":"Kono hon wa hotondo yomiowarimashita.","zh":""}]',replace('**Short**: Used to express ''almost'', ''nearly'', or ''most''.\n\n**Formation**: ほとんど + Verb / ほとんど + Noun\n\n**Long**: The ほとんど〜 grammar point is used to express that something is ''almost'', ''nearly'', or ''most''. It can appear in both negative contexts (hardly/barely) or positive contexts (almost all). It is typically followed by a verb or used with a noun to describe the quantity or extent of something.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_maa_maa','まあまあ～',NULL,NULL,'N5','[]','[{"ja":"彼の料理の腕前はまあまあです。","en":"His cooking skills are so-so.","romaji":"Kare no ryouri no udemae wa maa maa desu.","zh":""},{"ja":"今日の天気はまあまあですね。","en":"The weather today is not bad, huh?","romaji":"Kyou no tenki wa maa maa desu ne.","zh":""},{"ja":"あの映画はまあまあ面白かったです。","en":"That movie was somewhat interesting.","romaji":"Ano eiga wa maa maa omoshirokatta desu.","zh":""},{"ja":"彼女の歌はまあまあ上手だと思います。","en":"I think her singing is not bad.","romaji":"Kanojo no uta wa maa maa jouzu da to omoimasu.","zh":""}]',replace('**Short**: Expresses something as ''so-so'', ''not bad'', or ''average''.\n\n**Formation**: Used as an adverb or short expression with no special grammar structure.\n\n**Long**: The expression まあまあ is used to describe something that is neither particularly good nor bad, but rather average or ''so-so''. It is a neutral term and can be used in various contexts when discussing quality, feelings, or situations.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mada','まだ〜',NULL,NULL,'N5','[]','[{"ja":"昼ご飯はまだ食べていません。","en":"I haven''t eaten lunch yet.","romaji":"Hirugohan wa mada tabete imasen.","zh":""},{"ja":"山田さんはまだ来ていません。","en":"Yamada-san has not arrived yet.","romaji":"Yamada-san wa mada kite imasen.","zh":""},{"ja":"この部屋はまだ暑いです。","en":"This room is still hot.","romaji":"Kono heya wa mada atsui desu.","zh":""},{"ja":"彼はまだ学生じゃないです。","en":"He is not a student yet.","romaji":"Kare wa mada gakusei ja nai desu.","zh":""}]',replace('**Short**: Indicates something has not yet happened or is still happening; ''still'', ''not yet''.\n\n**Formation**: まだ + Verb (non-past / negative / te-form), まだ + い-adjective, まだ + な-adjective + じゃない/ではない, まだ + Noun + じゃない/ではない\n\n**Long**: The まだ〜 grammar point is used to express that something has not yet occurred or is still in progress. It can be translated as ''still'' or ''not yet'' in English. Depending on the context or if expressing the negative, まだ can be used with different combinations of verb, adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mada_nai_desu','まだ〜ないです',NULL,NULL,'N5','[]','[{"ja":"まだ宿題をしていないです。","en":"I haven''t done my homework yet.","romaji":"Mada shukudai o shite inai desu.","zh":""},{"ja":"彼はまだ来ないです。","en":"He hasn''t come yet.","romaji":"Kare wa mada konai desu.","zh":""},{"ja":"映画はまだ始まっていないです。","en":"The movie hasn''t started yet.","romaji":"Eiga wa mada hajimatte inai desu.","zh":""},{"ja":"私たちはまだ夕食を食べていないです。","en":"We haven''t eaten dinner yet.","romaji":"Watashitachi wa mada yuushoku o tabete inai desu.","zh":""}]',replace('**Short**: Expresses that something has not happened or been done yet.\n\n**Formation**: まだ + Verb-negative + です\n\n**Long**: The まだ〜ないです grammar point is used to indicate that a certain action or event has not yet happened or been completed. It is used with the negative form of a verb (casual negative + です) and can be translated as ''not yet'', ''still'', or ''haven''t'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mada_masen','まだ～ません',NULL,NULL,'N5','[]','[{"ja":"昼ご飯をまだ食べていません。","en":"I have not eaten lunch yet.","romaji":"Hirugohan o mada tabete imasen.","zh":""},{"ja":"宿題がまだ終わっていません。","en":"I have not finished my homework yet.","romaji":"Shukudai ga mada owatte imasen.","zh":""},{"ja":"東京にはまだ行ったことがありません。","en":"I have not been to Tokyo yet.","romaji":"Toukyou ni wa mada itta koto ga arimasen.","zh":""},{"ja":"彼はまだ来ていません。","en":"He hasn''t come yet.","romaji":"Kare wa mada kite imasen.","zh":""}]',replace('**Short**: Expresses that something has not happened or been done yet (polite form).\n\n**Formation**: まだ + Verb-ます form (negative)\n\n**Long**: The まだ～ません grammar point is used to express that something has not happened or been done yet in a polite register. It is used with the negative ます-form of a verb (～ません). まだ is placed before the verb phrase.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mou','もう～',NULL,NULL,'N5','[]','[{"ja":"もう昼ごはんを食べました。","en":"I already ate lunch.","romaji":"Mou hirugohan o tabemashita.","zh":""},{"ja":"もうここでは働かない。","en":"I won''t work here anymore.","romaji":"Mou koko de wa hatarakanai.","zh":""},{"ja":"もうすぐ夏休みですね。","en":"Summer vacation is coming soon, isn''t it?","romaji":"Mou sugu natsuyasumi desu ne.","zh":""},{"ja":"もう十分です。","en":"It''s already enough.","romaji":"Mou juubun desu.","zh":""}]',replace('**Short**: Expresses ''already'', ''anymore'', or ''soon''.\n\n**Formation**: もう + Verb / もう + Adjective / もう + Noun\n\n**Long**: The もう grammar point is used to express the idea of ''already'', ''anymore'', or ''soon'' in English. It indicates that something has already happened, won''t happen anymore, or will happen soon. It can be used with verbs, adjectives, or nouns depending on context.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mou_sugu','もうすぐ〜',NULL,NULL,'N5','[]','[{"ja":"もうすぐ春が来ます。","en":"Spring is coming soon.","romaji":"Mou sugu haru ga kimasu.","zh":""},{"ja":"もうすぐ彼女の誕生日です。","en":"Her birthday is coming up soon.","romaji":"Mou sugu kanojo no tanjoubi desu.","zh":""},{"ja":"もうすぐ試験が終わる。","en":"The exam will be over soon.","romaji":"Mou sugu shiken ga owaru.","zh":""},{"ja":"もうすぐ雨が止むでしょう。","en":"The rain will likely stop soon.","romaji":"Mou sugu ame ga yamu deshou.","zh":""}]',replace('**Short**: Express an action or event happening soon: ''soon'', ''in a short while'', ''almost''.\n\n**Formation**: もうすぐ + Verb (~ます form or 〜る form)\n\n**Long**: The もうすぐ grammar point is used to express that an action or event is going to happen soon or is almost happening. It can be translated as ''soon'', ''in a short while'', or ''almost'' in English. もうすぐ is usually followed by a verb or a noun indicating an event.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_motto','もっと〜',NULL,NULL,'N5','[]','[{"ja":"もっと勉強しなければなりません。","en":"I have to study more.","romaji":"Motto benkyou shinakereba narimasen.","zh":""},{"ja":"このかばんをもっと大きいサイズに変えたいです。","en":"I want to change this bag to a larger size.","romaji":"Kono kaban o motto ookii saizu ni kaetai desu.","zh":""},{"ja":"もっと静かな場所で働きたいです。","en":"I want to work in a quieter place.","romaji":"Motto shizuka na basho de hatarakitai desu.","zh":""},{"ja":"彼女はもっと上手になりたいと思っています。","en":"She wants to become even better.","romaji":"Kanojo wa motto jouzu ni naritai to omotte imasu.","zh":""}]',replace('**Short**: Expresses ''more'' or ''even more'' when describing a quantity, frequency, or degree.\n\n**Formation**: もっと + Verb / い-Adjective / な-Adjective\n\n**Long**: The もっと〜 grammar point is used to emphasize the desire or need for something to be ''more'' or ''even more'' in terms of quantity, frequency, or degree. It is often translated as ''more'' or ''even more'' in English. もっと can be used with verbs, い-adjectives, or な-adjectives.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_yoku','よく～',NULL,NULL,'N5','[]','[{"ja":"彼はよく勉強します。","en":"He studies often.","romaji":"Kare wa yoku benkyou shimasu.","zh":""},{"ja":"彼女はよく料理を作ります。","en":"She often cooks.","romaji":"Kanojo wa yoku ryouri o tsukurimasu.","zh":""},{"ja":"昔の友達とよく遊んでいました。","en":"I used to play a lot with my old friends.","romaji":"Mukashi no tomodachi to yoku asonde imashita.","zh":""},{"ja":"よくできました！","en":"Well done!","romaji":"Yoku dekimashita!","zh":""}]',replace('**Short**: Often used to express ''doing something well'' or ''often''.\n\n**Formation**: よく + Verb-casual\n\n**Long**: The よく～ grammar point is used to express that someone does something well, frequently, or often. It is often placed before the verb and can also mean ''well done'' or ''good job'' when praising someone''s action.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_basho_ni_ga_arimasu','～（場所）に～があります',NULL,NULL,'N5','[]','[{"ja":"図書館にたくさんの本があります。","en":"There are many books in the library.","romaji":"Toshokan ni takusan no hon ga arimasu.","zh":""},{"ja":"公園に池があります。","en":"There is a pond in the park.","romaji":"Kouen ni ike ga arimasu.","zh":""},{"ja":"駅の前にコンビニがあります。","en":"There is a convenience store in front of the station.","romaji":"Eki no mae ni konbini ga arimasu.","zh":""},{"ja":"山の上に神社があります。","en":"There is a shrine on top of the mountain.","romaji":"Yama no ue ni jinja ga arimasu.","zh":""}]',replace('**Short**: Express the existence or presence of something in a place.\n\n**Formation**: Place + に + Object/Thing + が + あります\n\n**Long**: The ～（場所）に～があります grammar point is used to express the existence or presence of something in a specific location. In this structure, the place is followed by ''に'', then the object, plus が, and finally あります (to exist / there is).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_b_n4','A とか B とか',NULL,NULL,'N4','[]','[{"ja":"週末は映画とか買い物とか楽しいことをしたいです。","en":"I want to do fun things like watching movies and shopping on the weekend.","romaji":"Shuumatsu wa eiga toka kaimono toka tanoshii koto o shitai desu.","zh":""},{"ja":"彼女は英語とかフランス語とかいろいろな言葉を話せます。","en":"She can speak various languages, like English and French.","romaji":"Kanojo wa eigo toka furansugo toka iroirona kotoba o hanasemasu.","zh":""},{"ja":"この店は寿司とか刺身とか日本料理を提供しています。","en":"This restaurant offers Japanese dishes such as sushi and sashimi.","romaji":"Kono mise wa sushi toka sashimi toka nihon ryouri o teikyou shiteimasu.","zh":""},{"ja":"$1BOXとか$5BOXとか、異なる価格のランチBOXがあります。","en":"There are lunch boxes with different prices, like $1 boxes and $5 boxes.","romaji":"Ichi-doru BOX toka go-doru BOX toka, kotonaru kakaku no ranchi BOX ga arimasu.","zh":""}]',replace('**Short**: Used to express multiple examples or possibilities; ''such as'', ''like'', ''for example''.\n\n**Formation**: Noun + とか + Noun + とか\n\n**Long**: The とか grammar point is used to list multiple examples or possibilities. It can be translated as ''such as'', ''like'', or ''for example'' in English. とか is used between the listed items and expresses that the list is not exhaustive.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_wa_b_hodo_arimasen','A は B ほど～ありません',NULL,NULL,'N4','[]','[{"ja":"今日は昨日ほど寒くありません。","en":"Today is not as cold as yesterday.","romaji":"Kyou wa kinou hodo samuku arimasen.","zh":""},{"ja":"彼は私ほど上手に英語を話せません。","en":"He cannot speak English as well as I can.","romaji":"Kare wa watashi hodo jouzu ni eigo o hanasemasen.","zh":""},{"ja":"このレストランはあのレストランほど高くありません。","en":"This restaurant is not as expensive as that restaurant.","romaji":"Kono resutoran wa ano resutoran hodo takaku arimasen.","zh":""},{"ja":"彼女は彼ほど忙しくありません。","en":"She is not as busy as him.","romaji":"Kanojo wa kare hodo isogashiku arimasen.","zh":""}]',replace('**Short**: Express that A is not as much as B; ''not as... as'', ''not... to the extent of''.\n\n**Formation**: A は B ほど Verb/adjective ありません\n\n**Long**: The は B ほど～ありません grammar point is used to express that A is not as much as B or not to the same extent as B, emphasizing the difference. It can be translated as ''not as... as'' or ''not... to the extent of'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_wa_b_hodo_nai','A は B ほど～ない',NULL,NULL,'N4','[]','[{"ja":"山田さんは鈴木さんほど背が高くない。","en":"Yamada is not as tall as Suzuki.","romaji":"Yamada-san wa Suzuki-san hodo se ga takakunai.","zh":""},{"ja":"このリンゴはあのリンゴほど甘くない。","en":"This apple is not as sweet as that apple.","romaji":"Kono ringo wa ano ringo hodo amakunai.","zh":""},{"ja":"彼は私ほど勉強ができない。","en":"He can''t study as well as I can.","romaji":"Kare wa watashi hodo benkyou ga dekinai.","zh":""},{"ja":"このレストランはあのレストランほど静かじゃない。","en":"This restaurant is not as quiet as that restaurant.","romaji":"Kono resutoran wa ano resutoran hodo shizuka janai.","zh":""}]',replace('**Short**: Expressing that A is not as ~ as B; ''not as...as''\n\n**Formation**: A は B ほど + い-Adjective stem (without い) + くない, な-Adjective + じゃない, Verb-negative potential form\n\n**Long**: The A は B ほど～ない grammar point is used to express that A is not as ~ as B in some aspect. It can be translated as ''not as...as'' in English. This structure is commonly used with い-adjectives (without い) and な-adjective. For verbs, you can use the negative potential form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_yori_b_no_hou_ga_n4','A より B のほうが〜',NULL,NULL,'N4','[]','[{"ja":"田中さんより鈴木さんのほうが背が高いです。","en":"Suzuki is taller than Tanaka.","romaji":"Tanaka-san yori Suzuki-san no hou ga se ga takai desu.","zh":""},{"ja":"リンゴよりバナナのほうが甘いです。","en":"Bananas are sweeter than apples.","romaji":"Ringo yori banana no hou ga amai desu.","zh":""},{"ja":"冬より夏のほうが暑いです。","en":"Summer is hotter than winter.","romaji":"Fuyu yori natsu no hou ga atsui desu.","zh":""},{"ja":"東京より京都のほうが歴史があると思います。","en":"I think Kyoto has more history than Tokyo.","romaji":"Toukyou yori Kyouto no hou ga rekishi ga aru to omoimasu.","zh":""}]',replace('**Short**: Comparing two things; ''B is more ~ than A''.\n\n**Formation**: A + より + B + のほうが + Adjective/Verb\n\n**Long**: The より and のほうが grammar pattern is used to compare two things by means of an adjective or verb. In this structure, item A is compared to item B, suggesting that item B is more ~ than item A.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_i_adjective_kusuru_naru','い-Adjective く する/なる',NULL,NULL,'N4','[]','[{"ja":"部屋を明るくします。","en":"I will make the room brighter.","romaji":"Heya o akaruku shimasu.","zh":""},{"ja":"彼の顔は赤くなりました。","en":"His face turned red.","romaji":"Kare no kao wa akaku narimashita.","zh":""},{"ja":"この料理を辛くしてください。","en":"Please make this dish spicy.","romaji":"Kono ryouri o karaku shite kudasai.","zh":""},{"ja":"雨が降ると、道が滑りやすくなります。","en":"When it rains, the road becomes slippery.","romaji":"Ame ga furu to, michi ga suberiyasuku narimasu.","zh":""}]',replace('**Short**: Express a change happening or making something change.\n\n**Formation**: い-Adjective (remove い) + く + する/なる\n\n**Long**: The い-Adjective く する/なる grammar point is used to indicate a change happening (naru) or intentionally making something change (suru). When using this grammatical structure, the い-adjective is changed to its く form, and then is followed by either する (to make the change) or なる (the change happens).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_adjective','な-adjective に する/なる',NULL,NULL,'N4','[]','[{"ja":"部屋をきれいにする。","en":"To make the room clean.","romaji":"Heya o kirei ni suru.","zh":""},{"ja":"彼は元気になりました。","en":"He became energetic.","romaji":"Kare wa genki ni narimashita.","zh":""},{"ja":"毎日静かにすることが大切です。","en":"It is important to make it quiet every day.","romaji":"Mainichi shizuka ni suru koto ga taisetsu desu.","zh":""},{"ja":"日本語の勉強が楽しくなるように努力します。","en":"I will try to make studying Japanese become enjoyable.","romaji":"Nihongo no benkyou ga tanoshiku naru you ni doryoku shimasu.","zh":""}]',replace('**Short**: Used to indicate change or decision; ''to become'' or ''to make'' with na-adjectives.\n\n**Formation**: な-Adjective + に + する/なる\n\n**Long**: The な-adjective に する/なる grammar point is used to express a change or a decision related to a na-adjective. The なる (naru) form indicates a change that occurs by itself, while the する (suru) form indicates a conscious decision made by someone.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_shikanai','Noun しか～ない',NULL,NULL,'N4','[]','[{"ja":"私はリンゴしか食べない。","en":"I eat only apples.","romaji":"Watashi wa ringo shika tabenai.","zh":""},{"ja":"電車で行くしかないです。","en":"There is no other way but to go by train.","romaji":"Densha de iku shika nai desu.","zh":""},{"ja":"彼は一冊の本しか持っていない。","en":"He has only one book.","romaji":"Kare wa isatsu no hon shika motte inai.","zh":""},{"ja":"この店にはビールしかない。","en":"There is nothing but beer in this store.","romaji":"Kono mise ni wa biiru shika nai.","zh":""}]',replace('**Short**: Expresses ''only'', ''nothing but'', or ''no other''.\n\n**Formation**: Noun + しか + Negative Verb\n\n**Long**: The grammar point Noun しか～ない is used to emphasize the small quantity or exclusiveness of something. It can be translated as ''only'', ''nothing but'', or ''no other'' in English. It is used with a negative verb to convey the meaning.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_ni_suru','Noun に する',NULL,NULL,'N4','[]','[{"ja":"メニューからピザにしました。","en":"I decided on pizza from the menu.","romaji":"Menyu kara piza ni shimashita.","zh":""},{"ja":"誕生日プレゼントに時計にするつもりです。","en":"I plan to choose a watch as a birthday present.","romaji":"Tanjoubi purezento ni tokei ni suru tsumori desu.","zh":""},{"ja":"今日の午後は買い物にすることにしました。","en":"I decided to go shopping this afternoon.","romaji":"Kyou no gogo wa kaimono ni suru koto ni shimashita.","zh":""},{"ja":"海外旅行の目的地として、日本にする。","en":"I will choose Japan as the destination for my overseas trip.","romaji":"Kaigai ryokou no mokutekichi toshite, Nihon ni suru.","zh":""}]',replace('**Short**: Used to indicate a choice or decision, ''to decide on'' or ''to choose''.\n\n**Formation**: Noun + に + する\n\n**Long**: The grammar point ''Noun に する'' is used to express making a choice or decision, which can be translated as ''to decide on'' or ''to choose'' in English. It is often used when deciding between different options or making a decision in various situations, such as choosing a menu item, deciding on a plan, or selecting a gift.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_ni_naru','Noun に なる',NULL,NULL,'N4','[]','[{"ja":"彼は医者になりました。","en":"He became a doctor.","romaji":"Kare wa isha ni narimashita.","zh":""},{"ja":"子供の頃、私は先生になりたかったです。","en":"When I was a child, I wanted to become a teacher.","romaji":"Kodomo no koro, watashi wa sensei ni naritakatta desu.","zh":""},{"ja":"彼女は緊張して顔が赤くなりました。","en":"She got nervous, and her face turned red.","romaji":"Kanojo wa kinchou shite kao ga akaku narimashita.","zh":""},{"ja":"春になると桜が咲きます。","en":"When it becomes spring, cherry blossoms bloom.","romaji":"Haru ni naru to sakura ga sakimasu.","zh":""}]',replace('**Short**: To become; to change into; to turn into.\n\n**Formation**: Noun + に + なる\n\n**Long**: The ''Noun に なる'' grammar point is used to show a change or a transformation from one state or form into another. In English, it can be translated as ''to become'', ''to change into'', or ''to turn into''. It is often used with nouns that indicate profession, status, or condition.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_no_tame_ni','のために',NULL,NULL,'N4','[]','[{"ja":"勉強のために、図書館で静かな場所を探しています。","en":"In order to study, I am looking for a quiet place in the library.","romaji":"Benkyou no tame ni, toshokan de shizukana basho o sagashiteimasu.","zh":""},{"ja":"彼は家族のために、一生懸命働いています。","en":"He works hard for the sake of his family.","romaji":"Kare wa kazoku no tame ni, isshoukenmei hataraiteimasu.","zh":""},{"ja":"健康のために、毎日運動をしています。","en":"I exercise every day for the sake of my health.","romaji":"Kenkou no tame ni, mainichi undou o shiteimasu.","zh":""},{"ja":"世界平和のために、みんなで協力しましょう。","en":"Let''s all cooperate for the sake of world peace.","romaji":"Sekai heiwa no tame ni, minna de kyouryoku shimashou.","zh":""}]',replace('**Short**: Used to express purpose or reason; ''for'', ''for the sake of'', ''in order to''.\n\n**Formation**: Noun + のために\n\n**Long**: The のために grammar point is used to express the purpose or reason for doing something, or for the benefit of someone or something. It can be translated as ''for'', ''for the sake of'', or ''in order to'' in English. The formation is straightforward, simply place のために after a noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_no_aida_ni','Noun の 間に',NULL,NULL,'N4','[]','[{"ja":"昼休みの間に銀行に行きます。","en":"I will go to the bank during lunch break.","romaji":"Hiruyasumi no aida ni ginkou ni ikimasu.","zh":""},{"ja":"夏休みの間に海外旅行に行く予定です。","en":"I plan to go on an overseas trip during the summer vacation.","romaji":"Natsuyasumi no aida ni kaigai ryokou ni iku yotei desu.","zh":""},{"ja":"子供たちが学校の間に買い物に行きました。","en":"I went shopping while the kids were at school.","romaji":"Kodomo-tachi ga gakkou no aida ni kaimono ni ikimashita.","zh":""},{"ja":"母の日にお母さんにプレゼントを送りました。","en":"I sent a gift to my mother on Mother’s Day.","romaji":"Haha no hi ni okaasan ni purezento o okurimashita.","zh":""}]',replace('**Short**: Expresses ''while'' or ''during'' a specific period or time.\n\n**Formation**: Noun + の間に\n\n**Long**: The Noun の 間に grammar point is used to indicate a specific period or time during which an action takes place. It is often translated as ''while'' or ''during'' in English. This grammar point requires a noun to represent the time or period.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_bakari_n4','Noun ばかり',NULL,NULL,'N4','[]','[{"ja":"彼はお金の話ばかりする。","en":"He talks about nothing but money.","romaji":"Kare wa okane no hanashi bakari suru.","zh":""},{"ja":"彼女は勉強ばかりしている。","en":"She is always studying.","romaji":"Kanojo wa benkyou bakari shiteiru.","zh":""},{"ja":"デパートには高い商品ばかりだ。","en":"There are only expensive items in the department store.","romaji":"Depaato ni wa takai shouhin bakari da.","zh":""},{"ja":"この部屋は狭いばかりだ。","en":"This room is nothing but small.","romaji":"Kono heya wa semai bakari da.","zh":""}]',replace('**Short**: Expresses ''only'', ''nothing but'', ''always'', or ''just''.\n\n**Formation**: Noun + ばかり, Verb-casual + ばかり, い-Adjective + ばかり, な-Adjective + だ ばかり\n\n**Long**: The ばかり grammar point is used to express that something is only, nothing but, just, or always. It can be attached to nouns, verbs, or adjectives, and has various meanings based on the context.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wo_ageru','Noun を あげる',NULL,NULL,'N4','[]','[{"ja":"プレゼントをあげる。","en":"I give a present.","romaji":"Purezento wo ageru.","zh":""},{"ja":"友達に花をあげた。","en":"I gave flowers to my friend.","romaji":"Tomodachi ni hana wo ageta.","zh":""},{"ja":"父に時計をあげます。","en":"I will give a watch to my father.","romaji":"Chichi ni tokei wo agemasu.","zh":""},{"ja":"彼女に手紙をあげたい。","en":"I want to give her a letter.","romaji":"Kanojo ni tegami wo agetai.","zh":""}]',replace('**Short**: To give something to someone; ''give'', ''offer'', ''present''.\n\n**Formation**: Noun + を + あげる\n\n**Long**: The を あげる grammar point is used to express giving something to someone. It can be translated as ''give'', ''offer'', or ''present'' in English. This construction is commonly used with nouns to indicate giving or offering a tangible item, action, or favor to someone else.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wo_itadaku','Nounをいただく',NULL,NULL,'N4','[]','[{"ja":"プレゼントをいただきありがとうございます。","en":"Thank you for the gift that I received.","romaji":"Purezento wo itadaki arigatou gozaimasu.","zh":""},{"ja":"先生からアドバイスをいただきました。","en":"I received advice from my teacher.","romaji":"Sensei kara adobaisu wo itadakimashita.","zh":""},{"ja":"このコーヒーをいただいていいですか？","en":"May I have this coffee?","romaji":"Kono koohii wo itadaite ii desu ka?","zh":""},{"ja":"会社の上司に昇進のお知らせをいただきました。","en":"I received a promotion notification from my boss at the company.","romaji":"Kaisha no joushi ni shoushin no oshirase wo itadakimashita.","zh":""}]',replace('**Short**: To receive or accept something politely; ''to receive'', ''to get'', ''to accept''.\n\n**Formation**: Noun + を + いただく\n\n**Long**: The Nounをいただく grammar point is used to express the action of receiving or accepting something in a polite or humble manner. The verb ''いただく'' is a more respectful version of the verb ''もらう'' (to receive), so using ''いただく'' shows humility and respect towards the person who is giving you something.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_n4','Nounをくださる',NULL,NULL,'N4','[]','[{"ja":"先生が資料をくださった。","en":"The teacher gave me the materials.","romaji":"Sensei ga shiryou wo kudasatta.","zh":""},{"ja":"お母さんがおやつをくださる。","en":"My mother gives me snacks.","romaji":"Okaasan ga oyatsu wo kudasaru.","zh":""},{"ja":"上司がアドバイスをくださいました。","en":"My boss gave me advice.","romaji":"Joushi ga adobaisu wo kudasaimashita.","zh":""},{"ja":"友達がプレゼントをくださった。","en":"My friend gave me a present.","romaji":"Tomodachi ga purezento wo kudasatta.","zh":""}]',replace('**Short**: Used to express someone doing something as a favor or for the benefit of the speaker.\n\n**Formation**: Noun + を + くださる\n\n**Long**: The grammar point ''Nounをくださる'' is a polite expression used to say that someone is giving or doing something for the benefit of the speaker. It is often used when referring to people who have a higher social status or when expressing gratitude for their actions.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wo_kureru','Noun を くれる',NULL,NULL,'N4','[]','[{"ja":"友達が私にプレゼントをくれました。","en":"My friend gave me a present.","romaji":"Tomodachi ga watashi ni purezento wo kuremashita.","zh":""},{"ja":"彼が私に花をくれた。","en":"He gave me flowers.","romaji":"Kare ga watashi ni hana wo kureta.","zh":""},{"ja":"先生が私に本をくれました。","en":"The teacher gave me a book.","romaji":"Sensei ga watashi ni hon wo kuremashita.","zh":""},{"ja":"お母さんが弟にお菓子をくれました。","en":"Mom gave my little brother some sweets.","romaji":"Okaasan ga otouto ni okashi wo kuremashita.","zh":""}]',replace('**Short**: Expresses that someone gives a thing to the speaker or someone close to the speaker.\n\n**Formation**: Giver + が + Receiver + に + Noun + を + くれる\n\n**Long**: The grammar point Noun を くれる is used to express when someone (other than the speaker) gives something to the speaker or someone close to the speaker. The giver is the subject, and the receiver is the speaker or someone close to the speaker. くれる indicates that the action of giving ''favors'' the speaker or someone close to the speaker.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wo_sashiageru','Noun を さしあげる',NULL,NULL,'N4','[]','[{"ja":"先生に本をさしあげます。","en":"I will give a book to the teacher.","romaji":"Sensei ni hon wo sashiagemasu.","zh":""},{"ja":"お母さんに花をさしあげたいです。","en":"I want to give flowers to my mother.","romaji":"Okaasan ni hana wo sashiagetai desu.","zh":""},{"ja":"お客様にお茶をさしあげましょう。","en":"Let''s offer tea to the guest.","romaji":"Okyakusama ni ocha wo sashiagemashou.","zh":""},{"ja":"先輩にプレゼントをさしあげたら、喜んでいました。","en":"When I gave a present to my senior, they were delighted.","romaji":"Senpai ni purezento wo sashiagetara, yorokonde imashita.","zh":""}]',replace('**Short**: A polite way of expressing to give something.\n\n**Formation**: Noun + を + さしあげる\n\n**Long**: The grammar point Noun を さしあげる is used to say that you are giving something to someone in a polite way. When offering something to a person of higher status, this expression is used. It is used in conjunction with a noun and replaces the regular verb あげる (ageru) to give.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wo_morau','Noun もらう',NULL,NULL,'N4','[]','[{"ja":"友達からプレゼントをもらいました。","en":"I received a gift from my friend.","romaji":"Tomodachi kara purezento wo moraimashita.","zh":""},{"ja":"先生にアドバイスをもらいました。","en":"I got advice from my teacher.","romaji":"Sensei ni adobaisu wo moraimashita.","zh":""},{"ja":"お父さんからお小遣いをもらう。","en":"To receive an allowance from one''s father.","romaji":"Otousan kara okozukai wo morau.","zh":""},{"ja":"彼女に手紙をもらった。","en":"I got a letter from her.","romaji":"Kanojo ni tegami wo moratta.","zh":""}]',replace('**Short**: To receive or get something from someone; ''to receive'', ''to get''.\n\n**Formation**: Noun + を + もらう\n\n**Long**: The もらう (morau) grammar point is used to express the action of receiving or getting something from someone. It usually emphasizes that the action was done for you or you were the beneficiary of the action. The formation requires a noun followed by the particle を (wo) before ''もらう''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_n4_2','Noun + 中',NULL,NULL,'N4','[]','[{"ja":"彼は仕事中です。","en":"He is in the middle of work.","romaji":"Kare wa shigotochuu desu.","zh":""},{"ja":"試験中、携帯電話を使ってはいけません。","en":"During the exam, you must not use your mobile phone.","romaji":"Shiken chuu, keitai denwa wo tsukatte wa ikemasen.","zh":""},{"ja":"映画を観ている最中に、彼は泣き始めました。","en":"In the middle of watching the movie, he started to cry.","romaji":"Eiga o mite iru saichuu ni, kare wa naki hajimemashita.","zh":""},{"ja":"彼女は今勉強中です。","en":"She is currently studying.","romaji":"Kanojo wa ima benkyouchuu desu.","zh":""}]',replace('**Short**: Express ''in the middle of'', ''during'', or ''in the process of''.\n\n**Formation**: Noun + 中 (ちゅう)\n\n**Long**: The 中 (ちゅう) grammar point is used to express that something is in the middle of, during, or in the process of happening. It is attached to a noun to convey this meaning (e.g., 勉強中, 仕事中, 会議中). It is also sometimes read as じゅう depending on the word (e.g., 授業中).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_saserareru','Verb させられる',NULL,NULL,'N4','[]','[{"ja":"子供たちは先生に宿題をやらせられました。","en":"The children were made to do their homework by the teacher.","romaji":"Kodomo-tachi wa sensei ni shukudai wo yaraseraremashita.","zh":""},{"ja":"彼は会社にもっと働かせられた。","en":"He was forced to work more by the company.","romaji":"Kare wa kaisha ni motto hatarakaserareta.","zh":""},{"ja":"私は友達にその機密を話させられました。","en":"I was made to reveal that secret by my friend.","romaji":"Watashi wa tomodachi ni sono kimitsu o hanasaseraremashita.","zh":""},{"ja":"怪我をした選手は、コーチに休ませられました。","en":"The injured player was forced to rest by the coach.","romaji":"Kega wo shita senshu wa, kouchi ni yasumaseraremashita.","zh":""}]',replace('**Short**: Express the passive causative form; ''to be made to'', ''to be forced to''.\n\n**Formation**: Group 1 Verb: Replace ～う with ～わせられる, Group 2 Verb: Replace ～る with ～させられる, Group 3 Verb: する → させられる, くる → こさせられる\n\n**Long**: The Verb させられる grammar point is the passive causative form of the verb. It is used to describe a situation where someone or something causes or forces another person to do something. This construction of passive causative is useful to show that the action was not done voluntarily by the person.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_saseru','Verb させる',NULL,NULL,'N4','[]','[{"ja":"先生が生徒に宿題をさせました。","en":"The teacher made the students do homework.","romaji":"Sensei ga seito ni shukudai o sasemashita.","zh":""},{"ja":"母が私に部屋を掃除させました。","en":"My mother made me clean my room.","romaji":"Haha ga watashi ni heya o souji sasemashita.","zh":""},{"ja":"彼女にピアノを弾かせてあげました。","en":"I let her play the piano.","romaji":"Kanojo ni piano o hikasete agemashita.","zh":""},{"ja":"上司は彼にそのプログラムを作らせました。","en":"The boss made him create the program.","romaji":"Joushi wa kare ni sono puroguramu o tsukurasemashita.","zh":""}]',replace('**Short**: Expresses ''to make someone do something'', ''to let someone do something'', or ''to cause someone to do something''.\n\n**Formation**: Group 1 Verbs: Change the last hiragana to ～せる, Group 2 Verbs: Remove ～る and add ～させる, Group 3 Verbs: する → させる, くる → こさせる\n\n**Long**: The ～させる verb form is used to describe causing or allowing someone to do something. It can be translated as ''to make someone do something'', ''to let someone do something'', or ''to cause someone to do something'' in English. The formation of the ～させる form depends on the verb it is attached to.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ta_koto_ga_aru','Verb た ことがある',NULL,NULL,'N4','[]','[{"ja":"日本に行ったことがあります。","en":"I have been to Japan before.","romaji":"Nihon ni itta koto ga arimasu.","zh":""},{"ja":"寿司を食べたことがありますか？","en":"Have you ever eaten sushi before?","romaji":"Sushi wo tabeta koto ga arimasu ka?","zh":""},{"ja":"彼はマラソンを走ったことがあります。","en":"He has experienced running a marathon.","romaji":"Kare wa marason wo hashitta koto ga arimasu.","zh":""},{"ja":"私はスカイダイビングをしたことがありません。","en":"I have never experienced skydiving.","romaji":"Watashi wa sukaidaibingu wo shita koto ga arimasen.","zh":""}]',replace('**Short**: Expresses the experience of having done something in the past.\n\n**Formation**: Verb-た-form + ことがある\n\n**Long**: The ～たことがある grammar point is used to express the experience of having done an action in the past. It indicates that the speaker has had the experience of doing something at least once before. It is formed by adding ことがある to the た-form of the verb.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb','Verb た ときに',NULL,NULL,'N4','[]','[{"ja":"映画を見たときに、泣きました。","en":"When I watched the movie, I cried.","romaji":"Eiga wo mita toki ni, nakimashita.","zh":""},{"ja":"彼に初めて会ったときに、遅刻していました。","en":"When I first met him, he was late.","romaji":"Kare ni hajimete atta toki ni, chikoku shite imashita.","zh":""},{"ja":"日本へ行ったときに、たくさんの写真を撮りました。","en":"When I went to Japan, I took a lot of photos.","romaji":"Nihon e itta toki ni, takusan no shashin wo torimashita.","zh":""},{"ja":"友達が家に来たときに、ゲームをしました。","en":"When my friend came to my house, we played games.","romaji":"Tomodachi ga ie ni kita toki ni, geemu wo shimashita.","zh":""}]',replace('**Short**: Express an action or event that occurred at a specific time in the past; ''when'', ''at the time''.\n\n**Formation**: Verb-た + ときに\n\n**Long**: The たときに grammar point is used to express an action that happened at a specific time in the past, usually with a focus on a specific event or moment. It can be translated as ''when'' or ''at the time'' in English. This grammar point requires a verb in its た-form followed by ときに to indicate the time at which the action occurred.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ta_tokoro','Verb た ところ',NULL,NULL,'N4','[]','[{"ja":"ドアを開けたところ、猫が飛び出してきた。","en":"When I opened the door, a cat came jumping out.","romaji":"Doa wo aketa tokoro, neko ga tobidashite kita.","zh":""},{"ja":"電話を切ったところ、また鳴った。","en":"Right after I hung up the phone, it rang again.","romaji":"Denwa wo kitta tokoro, mata natta.","zh":""},{"ja":"宿題を終わらせたところで、友達から連絡が来た。","en":"Just as I finished my homework, I got a message from my friend.","romaji":"Shukudai wo owaraseta tokoro de, tomodachi kara renraku ga kita.","zh":""},{"ja":"買い物をして帰ったところ、財布を失くしたことに気づいた。","en":"After shopping and returning home, I realized I had lost my wallet.","romaji":"Kaimono wo shite kaetta tokoro, saifu wo nakushita koto ni kizuita.","zh":""}]',replace('**Short**: Expresses the situation right after an action has taken place.\n\n**Formation**: Verb (た form) + ところ\n\n**Long**: The たところ grammar point is used to describe a situation that occurs right after an action has taken place. It is often translated as ''just now'', ''right after'', or ''when''. The formation is relatively simple as it only requires the verb in its た form (past tense) followed by ところ.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ta_hou_ga_ii','Verb たほうがいい',NULL,NULL,'N4','[]','[{"ja":"早く寝たほうがいい。","en":"It''s better if you go to bed early.","romaji":"Hayaku neta hou ga ii.","zh":""},{"ja":"もっと勉強したほうがいい。","en":"You should study more.","romaji":"Motto benkyou shita hou ga ii.","zh":""},{"ja":"病気の時は、薬を飲んだほうがいい。","en":"It''s a good idea to take medicine when you''re sick.","romaji":"Byouki no toki wa, kusuri wo nonda hou ga ii.","zh":""},{"ja":"コーヒーを飲まないほうがいい。","en":"It''s better if you don''t drink coffee.","romaji":"Koohii wo nomanai hou ga ii.","zh":""}]',replace('**Short**: Used to give advice or make a suggestion to someone - ''it''s better if...''.\n\n**Formation**: Verb (past tense) + ほうがいい\n\n**Long**: The たほうがいい grammar point is used to give advice or make a suggestion to someone. It can be translated as ''it''s better if...'', ''should'', or ''it''s a good idea to''. It is formed by conjugating the verb into the past tense (た-form) and adding ほうがいい.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tame_ni','Verb ために',NULL,NULL,'N4','[]','[{"ja":"試験に合格するために、毎日勉強しています。","en":"I study every day in order to pass the exam.","romaji":"Shiken ni goukaku suru tame ni, mainichi benkyou shiteimasu.","zh":""},{"ja":"健康のために、毎日運動しなければなりません。","en":"For the sake of health, I must exercise daily.","romaji":"Kenkou no tame ni, mainichi undou shinakereba narimasen.","zh":""},{"ja":"仕事が忙しいために、友達と会う時間がありません。","en":"Because my work is busy, I don''t have time to meet friends.","romaji":"Shigoto ga isogashii tame ni, tomodachi to au jikan ga arimasen.","zh":""},{"ja":"雨が降ったために、試合が中止されました。","en":"The game was canceled because of the rain.","romaji":"Ame ga futta tame ni, shiai ga chuushi saremashita.","zh":""}]',replace('**Short**: Used to describe the purpose or reason for an action; ''for the sake of'', ''in order to'', ''because of''.\n\n**Formation**: 1) Verb (dictionary form) + ために (purpose)\n2) い-Adjective + ために (reason)\n3) な-Adjective + な + ために (reason)\n4) Noun + の + ために (reason)\n\n**Long**: The ために (tame ni) grammar point is used to express either the purpose of doing something (in which case it translates to ''for the sake of'' or ''in order to'') or the cause/reason for a situation (in which case it translates to ''because of''). Typically, we use the dictionary form of the verb (e.g., 合格する) for the ''in order to'' meaning. For an adjective or noun, attach ために appropriately (い-Adjective + ために, な-Adjective + な + ために, Noun + の + ために).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tsumori','Verb つもり',NULL,NULL,'N4','[]','[{"ja":"明日、友達に会うつもりです。","en":"I plan to meet my friend tomorrow.","romaji":"Ashita, tomodachi ni au tsumori desu.","zh":""},{"ja":"今夜、晩ご飯を作るつもりです。","en":"I intend to cook dinner tonight.","romaji":"Konya, bangohan o tsukuru tsumori desu.","zh":""},{"ja":"来年、留学するつもりです。","en":"I plan to study abroad next year.","romaji":"Rainen, ryuugaku suru tsumori desu.","zh":""},{"ja":"この週末、山に登るつもりです。","en":"I''m determined to climb the mountain this weekend.","romaji":"Kono shuumatsu, yama ni noboru tsumori desu.","zh":""}]',replace('**Short**: Express the intention, plan, or determination to do something; ''I intend to'', ''I plan to'', ''I''m determined to''.\n\n**Formation**: Verb-casual + つもり\n\n**Long**: The ～つもり grammar point is used to express the intention, plan, or determination to do something. It can be translated as ''I intend to'', ''I plan to'', or ''I''m determined to'' in English. It is used with verbs in the casual form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te_ageru','Verb てあげる',NULL,NULL,'N4','[]','[{"ja":"友達が疲れていたから、荷物を持ってあげた。","en":"Since my friend was tired, I carried their luggage for them.","romaji":"Tomodachi ga tsukareteita kara, nimotsu o motte ageta.","zh":""},{"ja":"弟は宿題がわからなかったので、手伝ってあげた。","en":"My younger brother couldn''t understand the homework, so I helped him.","romaji":"Otouto wa shukudai ga wakaranakatta node, tetsudatte ageta.","zh":""},{"ja":"彼女が遅れそうだったから、駅まで迎えに行ってあげた。","en":"She was running late, so I went to pick her up at the station.","romaji":"Kanojo ga okuresou datta kara, eki made mukae ni itte ageta.","zh":""},{"ja":"犬はのどが渇いたそうだったので、水を飲ませてあげた。","en":"The dog seemed thirsty, so I gave it water to drink.","romaji":"Inu wa nodo ga kawaita sou datta node, mizu o nomasete ageta.","zh":""}]',replace('**Short**: Used to express doing something for someone; ''do something for someone''.\n\n**Formation**: Verb-て form + あげる\n\n**Long**: The てあげる grammar point is used to express that the speaker or someone other than the listener is doing something for someone else. It shows that the action is being done as a favor or out of kindness. This grammar point is used with verbs in their て-form, followed by あげる.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te_aru','Verb て ある',NULL,NULL,'N4','[]','[{"ja":"窓が開けてある。","en":"The window has been opened (and remains open).","romaji":"Mado ga akete aru.","zh":""},{"ja":"宿題がもう終わってある。","en":"The homework has already been done (and remains that way).","romaji":"Shukudai ga mou owatte aru.","zh":""},{"ja":"洗濯物が全部干してある。","en":"The laundry has been hung up to dry (and remains that way).","romaji":"Sentakumono ga zenbu hoshite aru.","zh":""},{"ja":"この部屋はきれいに掃除してある。","en":"This room has been cleaned (and remains clean).","romaji":"Kono heya wa kirei ni souji shite aru.","zh":""}]',replace('**Short**: Indicates that an action has been done and its result is still in effect.\n\n**Formation**: Verb-て form + ある\n\n**Long**: The ～てある grammar point is used to express that an action has been done and its result remains in effect. It indicates that the action was intentionally performed and its effect continues. The formation is done by conjugating the verb into its て-form and then adding ある.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te_iku','Verb て いく',NULL,NULL,'N4','[]','[{"ja":"このまま練習を続けていくと、上達するでしょう。","en":"If you keep practicing like this, you will improve.","romaji":"Kono mama renshuu o tsuzukete iku to, joutatsu suru deshou.","zh":""},{"ja":"彼は成長していくうちに、自立心が強くなった。","en":"As he grew up, his independence became stronger.","romaji":"Kare wa seichou shite iku uchi ni, jiritsushin ga tsuyoku natta.","zh":""},{"ja":"この会社はこれからも技術革新を行っていくでしょう。","en":"This company will continue to innovate in technology in the future.","romaji":"Kono kaisha wa korekara mo gijutsu kakushin o okonatte iku deshou.","zh":""},{"ja":"子供たちはどんどん学んでいく。","en":"Children will keep learning more and more.","romaji":"Kodomo-tachi wa dondon manande iku.","zh":""}]',replace('**Short**: Expresses an action that continues on into the future or a change that progresses over time.\n\n**Formation**: Verb in て-form + いく\n\n**Long**: The て いく grammar point is used to indicate that an action will continue or a change will progress into the future. It can be attached to the て-form of a verb and is often translated as ''to keep'', ''to continue'', or ''to go on'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_itadakitai','Verb ていただきたい',NULL,NULL,'N4','[]','[{"ja":"資料をコピーしていただきたいです。","en":"I would like you to make copies of the documents.","romaji":"Shiryou wo kopii shite itadakitai desu.","zh":""},{"ja":"この仕事を手伝っていただきたいのですが。","en":"I would like to ask for your assistance with this work.","romaji":"Kono shigoto wo tetsudatte itadakitai no desu ga.","zh":""},{"ja":"もしよろしければ、指導していただきたいです。","en":"If it is not too much trouble, I would like you to guide me.","romaji":"Moshi yoroshikereba, shidou shite itadakitai desu.","zh":""},{"ja":"駅まで送っていただきたいんですが。","en":"I was wondering if you could give me a ride to the station.","romaji":"Eki made okutte itadakitain desu ga.","zh":""}]',replace('**Short**: Express a polite request or desire that someone does something for you.\n\n**Formation**: Verb-て form + いただきたい\n\n**Long**: The ていただきたい grammar point is used to express a polite request or a desire for someone to do something for you. It is formed by attaching いただきたい to the て-form of the verb. It is more polite than the て-form + ほしい construction.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_itadaku','Verb ていただく',NULL,NULL,'N4','[]','[{"ja":"メールを送っていただいて、ありがとうございます。","en":"Thank you for kindly sending the email.","romaji":"Meeru o okutte itadaite, arigatou gozaimasu.","zh":""},{"ja":"荷物を運んでいただいて、助かりました。","en":"You really helped me by carrying the luggage.","romaji":"Nimotsu o hakonde itadaite, tasukarimashita.","zh":""},{"ja":"資料をチェックしていただきたいです。","en":"I would like you to kindly check the documents.","romaji":"Shiryou o chekku shite itadakitai desu.","zh":""},{"ja":"先生にアドバイスをしていただきました。","en":"The teacher kindly gave me advice.","romaji":"Sensei ni adobaisu o shite itadakimashita.","zh":""}]',replace('**Short**: Used to express receiving someone''s favor or help; ''to kindly do''.\n\n**Formation**: Verb-て form + いただく\n\n**Long**: The ～ていただく grammar point is used to express that someone has kindly done a favor or provided help. It is a more polite and humble way of saying that you received someone''s help. The formation is created by attaching the て-form of the verb + いただく.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te_itadakemasen_ka','Verb て いただけませんか',NULL,NULL,'N4','[]','[{"ja":"この手紙を投函していただけませんか。","en":"Could you please mail this letter for me?","romaji":"Kono tegami wo toukan shite itadakemasen ka.","zh":""},{"ja":"この荷物を持っていただけませんか。","en":"Could you please carry this luggage for me?","romaji":"Kono nimotsu wo motte itadakemasen ka.","zh":""},{"ja":"隣の部屋にいる人に静かにしていただけませんか。","en":"Could you please ask the person next door to be quiet?","romaji":"Tonari no heya ni iru hito ni shizuka ni shite itadakemasen ka.","zh":""},{"ja":"説明書を読んでいただけませんか。","en":"Could you please read the instruction manual?","romaji":"Setsumeisho wo yonde itadakemasen ka.","zh":""}]',replace('**Short**: A polite request; ''Could you please...'', ''Would you mind...''\n\n**Formation**: Verb-て form + いただけませんか\n\n**Long**: The て いただけませんか grammar point is used to make a polite request to someone. It is a more polite form of て くれませんか, and can be translated as ''Could you please...'' or ''Would you mind...'' in English. To use it, change the verb to its て-form and add いただけませんか.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te_iru','Verb て いる',NULL,NULL,'N4','[]','[{"ja":"今、本を読んでいます。","en":"I am reading a book now.","romaji":"Ima, hon wo yonde imasu.","zh":""},{"ja":"彼は英語を勉強しています。","en":"He is studying English.","romaji":"Kare wa eigo wo benkyou shite imasu.","zh":""},{"ja":"ケーキが冷蔵庫に入っています。","en":"The cake is in the refrigerator.","romaji":"Keeki ga reizouko ni haitte imasu.","zh":""},{"ja":"部屋がきれいになっています。","en":"The room has become clean.","romaji":"Heya ga kirei ni natte imasu.","zh":""}]',replace('**Short**: Expresses an ongoing action or a state resulting from a past action.\n\n**Formation**: Verb (て-form) + いる\n\n**Long**: The ている form is used to express either an ongoing action or a state resulting from a past action. It is formed by conjugating the verb into its て-form and then adding いる. In English, this can be translated as verb-ing or ''have verb-ed''. Its usage depends on the type of verb: action verbs or state verbs.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te_iru_tokoro','Verb て いる ところ',NULL,NULL,'N4','[]','[{"ja":"彼は宿題をしているところです。","en":"He is in the middle of doing his homework.","romaji":"Kare wa shukudai wo shite iru tokoro desu.","zh":""},{"ja":"私たちは映画を見ているところでした。","en":"We were in the process of watching a movie.","romaji":"Watashitachi wa eiga wo mite iru tokoro deshita.","zh":""},{"ja":"子供たちは公園で遊んでいるところです。","en":"The kids are in the middle of playing in the park.","romaji":"Kodomotachi wa kouen de asonde iru tokoro desu.","zh":""},{"ja":"彼女はケーキを作っているところで、すぐ来ます。","en":"She is in the process of making a cake and will come soon.","romaji":"Kanojo wa keeki wo tsukutte iru tokoro de, sugu kimasu.","zh":""}]',replace('**Short**: Describes an action that is currently happening; ''in the middle of'', ''in the process of''.\n\n**Formation**: Verb-て form + いる ところ\n\n**Long**: The て いる ところ grammar point is used to express an action that is currently happening or taking place. It can be translated as ''in the middle of'' or ''in the process of'' in English. It is formed by using the て-form of a verb followed by いる and ところ.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_iru_aida_ni','Verb ている間に',NULL,NULL,'N4','[]','[{"ja":"映画を見ている間に、彼は寝てしまった。","en":"While watching the movie, he fell asleep.","romaji":"Eiga o mite iru aida ni, kare wa nete shimatta.","zh":""},{"ja":"子供が遊んでいる間に、私は料理を作ります。","en":"While the children are playing, I''ll cook.","romaji":"Kodomo ga asonde iru aida ni, watashi wa ryouri o tsukurimasu.","zh":""},{"ja":"会議が行われている間に、雨が降り始めた。","en":"While the meeting was being held, it started raining.","romaji":"Kaigi ga okonawarete iru aida ni, ame ga furihajimeta.","zh":""},{"ja":"彼が仕事をしている間に、私たちは買い物に行く。","en":"While he is working, we''ll go shopping.","romaji":"Kare ga shigoto o shite iru aida ni, watashitachi wa kaimono ni iku.","zh":""}]',replace('**Short**: Expresses ''while'' or ''during the time'' something is happening.\n\n**Formation**: Verb-て form + いる + 間に\n\n**Long**: The ～ている間に grammar point is used to express that an action or event occurs during the time another action or event is happening. It is often translated to ''while'' or ''during the time'' in English. It is formed by combining the て-form of a verb with いる and adding 間に.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_oku','Verb ておく',NULL,NULL,'N4','[]','[{"ja":"駅で切符を買っておこう。","en":"Let''s buy the tickets in advance at the station.","romaji":"Eki de kippu wo katte okou.","zh":""},{"ja":"明日早く起きるために、今晩早く寝ておきます。","en":"I will go to bed early tonight to wake up early tomorrow.","romaji":"Ashita hayaku okiru tame ni, konban hayaku nete okimasu.","zh":""},{"ja":"試験前に勉強しておかないと、失敗するかもしれない。","en":"If I don''t study in advance before the exam, I might fail.","romaji":"Shiken mae ni benkyou shite okanai to, shippai suru kamo shirenai.","zh":""},{"ja":"彼が到着する前に、部屋をきれいに掃除しておきましょう。","en":"Let''s clean the room before he arrives.","romaji":"Kare ga touchaku suru mae ni, heya wo kirei ni souji shite okimashou.","zh":""}]',replace('**Short**: Perform an action in preparation for a future situation; ''to do something in advance''.\n\n**Formation**: Verb-て form + おく\n\n**Long**: The ～ておく grammar point is used when you want to express performing an action in preparation for a future situation or to do something in advance. It is attached to the te-form of a verb and expresses the idea of doing something beforehand, as a preparatory action.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te_kudasaimasen_ka','Verb て くださいませんか',NULL,NULL,'N4','[]','[{"ja":"コーヒーを飲んでくださいませんか。","en":"Would you please drink some coffee?","romaji":"Koohii o nonde kudasaimasen ka.","zh":""},{"ja":"ドアを閉めてくださいませんか。","en":"Would you please close the door?","romaji":"Doa o shimete kudasaimasen ka.","zh":""},{"ja":"明日お昼に会ってくださいませんか。","en":"Would you please meet me at lunch tomorrow?","romaji":"Ashita ohiru ni atte kudasaimasen ka.","zh":""},{"ja":"その資料を送ってくださいませんか。","en":"Would you please send me that document?","romaji":"Sono shiryou o okutte kudasaimasen ka.","zh":""}]',replace('**Short**: Polite request for asking someone for a favor.\n\n**Formation**: Verb in て-form + くださいませんか\n\n**Long**: The て くださいませんか grammar point is a polite way of asking someone for a favor or requesting them to do something. It is more formal than the simple て form followed by ください, and it is commonly used in more formal settings or when speaking to someone who is not close.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te_kudasaru','Verb て くださる',NULL,NULL,'N4','[]','[{"ja":"先生が手伝ってくださる。","en":"The teacher kindly helps.","romaji":"Sensei ga tetsudatte kudasaru.","zh":""},{"ja":"お母さんが美味しい料理を作ってくださる。","en":"My mother kindly cooks delicious meals.","romaji":"Okaasan ga oishii ryouri wo tsukutte kudasaru.","zh":""},{"ja":"友達が私を駅まで送ってくださる。","en":"My friend kindly gives me a ride to the station.","romaji":"Tomodachi ga watashi wo eki made okutte kudasaru.","zh":""},{"ja":"部長がすぐに質問に答えてくださる。","en":"The manager kindly answers the questions immediately.","romaji":"Buchou ga sugu ni shitsumon ni kotaete kudasaru.","zh":""}]',replace('**Short**: Expresses gratitude for receiving someone''s favor; ''to kindly do''.\n\n**Formation**: Verb て-form + くださる\n\n**Long**: The て くださる grammar point is used to express gratitude for receiving a favor or action from someone else. It is an honorific way to say that someone kindly does something for the speaker or the listener. The verb is conjugated to its ～て form and followed by くださる.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te_kuru','Verb て くる',NULL,NULL,'N4','[]','[{"ja":"最近、日本語が分かってくるようになりました。","en":"Recently, I''ve come to understand Japanese.","romaji":"Saikin, nihongo ga wakatte kuru you ni narimashita.","zh":""},{"ja":"寒くなってきたので、コートを着ましょう。","en":"Since it''s gotten cold, let''s put on a coat.","romaji":"Samuku natte kita node, kooto wo kimashou.","zh":""},{"ja":"雨がやんできました。","en":"The rain has stopped (and it''s cleared up).","romaji":"Ame ga yande kimashita.","zh":""},{"ja":"彼がだんだん怖くなってきた。","en":"He has become progressively scarier.","romaji":"Kare ga dandan kowaku natte kita.","zh":""}]',replace('**Short**: An action that starts in the past and continues to the present or future; ''come to'', ''begin to'', ''become''.\n\n**Formation**: Verb て-form + くる\n\n**Long**: The て くる grammar point is used to express an action that starts in the past and continues to the present or future. It can also show a change in state or condition. The formation involves attaching the て-form of the verb followed by くる.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_kuremasen_ka','Verb てくれませんか',NULL,NULL,'N4','[]','[{"ja":"ドアを開けてくれませんか。","en":"Could you please open the door?","romaji":"Doa wo akete kuremasen ka.","zh":""},{"ja":"これを見てくれませんか。","en":"Would you please take a look at this?","romaji":"Kore wo mite kuremasen ka.","zh":""},{"ja":"手伝ってくれませんか。","en":"Won''t you help me?","romaji":"Tetsudatte kuremasen ka.","zh":""},{"ja":"明日、迎えに来てくれませんか。","en":"Could you please come to pick me up tomorrow?","romaji":"Ashita, mukae ni kite kuremasen ka.","zh":""}]',replace('**Short**: A polite way to request someone to do something for you; ''Could you please'', ''Would you please'', ''Won''t you''.\n\n**Formation**: Verb-て form + くれませんか\n\n**Long**: The ～てくれませんか grammar point is used to ask someone politely to do something for you. It is formed by using the て-form of a verb followed by くれませんか. It translates to ''Could you please'', ''Would you please'', or ''Won''t you'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te_kureru','Verb て くれる',NULL,NULL,'N4','[]','[{"ja":"友達が宿題を手伝ってくれました。","en":"My friend helped me with my homework.","romaji":"Tomodachi ga shukudai wo tetsudatte kuremashita.","zh":""},{"ja":"弟が部屋を掃除してくれた。","en":"My younger brother cleaned the room for me.","romaji":"Otouto ga heya wo souji shite kureta.","zh":""},{"ja":"先生が質問に答えてくれます。","en":"The teacher answers my questions for me.","romaji":"Sensei ga shitsumon ni kotaete kuremasu.","zh":""},{"ja":"彼女が手紙を書いてくれる。","en":"She writes a letter for me.","romaji":"Kanojo ga tegami wo kaite kureru.","zh":""}]',replace('**Short**: Expresses that someone does something for the speaker (or another person in speaker''s group); ''to do something for me/us''.\n\n**Formation**: Verb-te form + くれる\n\n**Long**: The て くれる grammar point is used to express when someone does something for, or gives something to the speaker (or someone in the speaker''s group). The action is usually done willingly or as a favor by the person performing the action. It is usually translated into English as ''to do something for me'' or ''to give something to me''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te_sashiageru','Verb て + さしあげる',NULL,NULL,'N4','[]','[{"ja":"お茶を入れてさしあげます。","en":"I will prepare and serve tea (for you).","romaji":"Ocha wo irete sashiagemasu.","zh":""},{"ja":"メッセージを送ってさしあげました。","en":"I have sent the message (for you).","romaji":"Messeiji wo okutte sashiagemashita.","zh":""},{"ja":"荷物を持ってさしあげましょうか。","en":"Shall I carry the luggage (for you)?","romaji":"Nimotsu wo motte sashiagemashou ka.","zh":""},{"ja":"お電話をかけてさしあげます。","en":"I will make a phone call (for you).","romaji":"Odenwa wo kakete sashiagemasu.","zh":""}]',replace('**Short**: A polite way to express giving or doing something for someone.\n\n**Formation**: Verb-てform + さしあげる\n\n**Long**: The grammar point ''Verb て + さしあげる'' is used to express the action of giving or doing something for someone in a polite manner. It is mainly used when the speaker is offering or doing something for someone of higher social status or showing respect towards the person. To form this expression, you need to conjugate the verb into its て-form and attach さしあげる.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_shimau','Verb てしまう',NULL,NULL,'N4','[]','[{"ja":"ケーキを全部食べてしまった。","en":"I ended up eating the whole cake.","romaji":"Keeki wo zenbu tabete shimatta.","zh":""},{"ja":"宿題を忘れてしまいました。","en":"I accidentally forgot my homework.","romaji":"Shukudai wo wasurete shimaimashita.","zh":""},{"ja":"彼に秘密を言ってしまった。","en":"I accidentally told him the secret.","romaji":"Kare ni himitsu wo itte shimatta.","zh":""},{"ja":"値札を見ずに高い服を買ってしまった。","en":"I ended up buying expensive clothes without looking at the price tag.","romaji":"Nefuda wo mizu ni takai fuku wo katte shimatta.","zh":""}]',replace('**Short**: Expresses unintentional actions or actions with regrettable outcomes; ''to end up doing'', ''to accidentally do''.\n\n**Formation**: Verb-te form + しまう\n\n**Long**: The ～てしまう grammar point is used to indicate unintentional actions or actions with regrettable outcomes. It can often be translated as ''to end up doing'' or ''to accidentally do'' in English. The formation requires adding しまう to the て-form of a verb.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te_hoshii','Verb て ほしい',NULL,NULL,'N4','[]','[{"ja":"子供にもっと勉強してほしい。","en":"I want my child to study more.","romaji":"Kodomo ni motto benkyou shite hoshii.","zh":""},{"ja":"彼にもっと早く来てほしい。","en":"I want him to come earlier.","romaji":"Kare ni motto hayaku kite hoshii.","zh":""},{"ja":"友達にその本を読んでほしい。","en":"I want my friend to read that book.","romaji":"Tomodachi ni sono hon o yonde hoshii.","zh":""},{"ja":"先生に質問に答えてほしい。","en":"I want the teacher to answer the question.","romaji":"Sensei ni shitsumon ni kotaete hoshii.","zh":""}]',replace('**Short**: Express a desire for someone else to do something; ''I want (someone) to''.\n\n**Formation**: Verb-て form + ほしい\n\n**Long**: The て ほしい grammar point is used to express the speaker''s desire for someone else to do an action. It is formed by combining the て-form of a verb with ほしい. The subject is usually followed by the particle に, but it can be dropped in casual speech.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_miru_n4','Verb てみる',NULL,NULL,'N4','[]','[{"ja":"この料理を作ってみます。","en":"I will try to make this dish.","romaji":"Kono ryouri o tsukutte mimasu.","zh":""},{"ja":"その服を着てみてください。","en":"Please try on those clothes.","romaji":"Sono fuku o kite mite kudasai.","zh":""},{"ja":"新しいレストランに行ってみよう。","en":"Let''s try going to the new restaurant.","romaji":"Atarashii resutoran ni itte miyou.","zh":""},{"ja":"映画を見てみたいです。","en":"I want to try watching the movie.","romaji":"Eiga o mite mitai desu.","zh":""}]',replace('**Short**: Used to express ''try to'' or ''attempt to do''.\n\n**Formation**: Verb-て form + みる\n\n**Long**: The ～てみる grammar point is used with verbs to express ''trying'' or ''attempting'' to do something. It emphasizes the idea of giving something a go or trying it out, often to see what the results or outcome will be.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_moraitai','Verb てもらいたい',NULL,NULL,'N4','[]','[{"ja":"この荷物を運んでもらいたいです。","en":"I want you to carry this luggage for me.","romaji":"Kono nimotsu o hakonde moraitai desu.","zh":""},{"ja":"彼にそのニュースを教えてもらいたい。","en":"I want him to tell me the news.","romaji":"Kare ni sono nyuusu o oshiete moraitai.","zh":""},{"ja":"友達に日本語を教えてもらいたい。","en":"I want my friend to teach me Japanese.","romaji":"Tomodachi ni Nihongo o oshiete moraitai.","zh":""},{"ja":"スタッフにチェックインの方法を説明してもらいたい。","en":"I want the staff to explain the check-in process to me.","romaji":"Sutaffu ni chekkuin no houhou o setsumei shite moraitai.","zh":""}]',replace('**Short**: Express a desire to receive a favor or service from someone else.\n\n**Formation**: Verb-て-form + もらいたい\n\n**Long**: The ～てもらいたい grammar point is used to express one''s desire to receive a favor, service, or action from someone else. It is formed by attaching もらいたい to the て-form of verbs. This structure emphasizes the help or favor the speaker wants from someone else.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te_morau','Verb て もらう',NULL,NULL,'N4','[]','[{"ja":"友達に宿題を手伝ってもらった。","en":"I had my friend help me with my homework.","romaji":"Tomodachi ni shukudai o tetsudatte moratta.","zh":""},{"ja":"母に部屋を掃除してもらいました。","en":"I had my mother clean my room.","romaji":"Haha ni heya o souji shite moraimashita.","zh":""},{"ja":"彼に荷物を持ってもらいたい。","en":"I want him to carry my luggage for me.","romaji":"Kare ni nimotsu o motte moraitai.","zh":""},{"ja":"先生に質問に答えてもらえますか？","en":"Can I have the teacher answer my question?","romaji":"Sensei ni shitsumon ni kotaete moraemasu ka?","zh":""}]',replace('**Short**: Express receiving a favor or action from someone.\n\n**Formation**: Verb-て form + もらう\n\n**Long**: The Verb て もらう grammar point is used to express that the speaker or a third person receives a favor or action from someone else. It describes an action performed by someone for the benefit of the speaker or a third person, implying gratitude or request from the beneficiary.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_moraemasen_ka','Verb てもらえませんか',NULL,NULL,'N4','[]','[{"ja":"この手紙を見てもらえませんか。","en":"Could you take a look at this letter for me?","romaji":"Kono tegami o mite moraemasen ka?","zh":""},{"ja":"荷物を持ってもらえませんか。","en":"Could you carry this luggage for me?","romaji":"Nimotsu o motte moraemasen ka?","zh":""},{"ja":"部屋を掃除してもらえませんか。","en":"Could you clean the room for me?","romaji":"Heya o souji shite moraemasen ka?","zh":""},{"ja":"明日のミーティングに参加してもらえませんか。","en":"Could you attend tomorrow''s meeting for me?","romaji":"Ashita no miitingu ni sanka shite moraemasen ka?","zh":""}]',replace('**Short**: A polite way to ask for a favor or request someone to do something.\n\n**Formation**: Verb-て form + もらえませんか\n\n**Long**: The ～てもらえませんか grammar point is a polite and indirect way of asking someone to do something for you or asking for a favor. It is formed by conjugating the verb into the て-form and adding もらえませんか. This form is used in conversations to show politeness and humility.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_nai_koto_ga_aru','Verb ない ことがある',NULL,NULL,'N4','[]','[{"ja":"彼は会議に出席しないことがある。","en":"There are times when he doesn''t attend meetings.","romaji":"Kare wa kaigi ni shusseki shinai koto ga aru.","zh":""},{"ja":"この電車は定刻に来ないことがある。","en":"There are occasions when this train doesn''t come on time.","romaji":"Kono densha wa teikoku ni konai koto ga aru.","zh":""},{"ja":"私は朝食を食べないことがある。","en":"There are times when I don''t eat breakfast.","romaji":"Watashi wa choushoku o tabenai koto ga aru.","zh":""},{"ja":"彼女は電話に出ないことがある。","en":"There are occasions when she doesn''t answer the phone.","romaji":"Kanojo wa denwa ni denai koto ga aru.","zh":""}]',replace('**Short**: Expresses that something doesn''t always happen or there are occasions when it doesn''t happen.\n\n**Formation**: Verb-negative form + ことがある\n\n**Long**: The ないことがある grammar point is used to indicate that there are instances or times when something doesn''t happen or isn''t done. It is formed by combining the negative form of a verb (ない) with ことがある.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_nai_koto_ni_suru','Verb ない + ことにする',NULL,NULL,'N4','[]','[{"ja":"明日のパーティーに行かないことにする。","en":"I''ve decided not to go to tomorrow''s party.","romaji":"Ashita no paatii ni ikanai koto ni suru.","zh":""},{"ja":"そのケーキを食べないことにします。","en":"I''ve decided not to eat that cake.","romaji":"Sono keeki wo tabenai koto ni shimasu.","zh":""},{"ja":"今日はジョギングをしないことにする。","en":"I''ve decided not to go jogging today.","romaji":"Kyou wa jogingu wo shinai koto ni suru.","zh":""},{"ja":"彼と会わないことにしました。","en":"I''ve decided not to meet him.","romaji":"Kare to awanai koto ni shimashita.","zh":""}]',replace('**Short**: To decide not to do something.\n\n**Formation**: Verb-ない form + ことにする\n\n**Long**: The grammar point Verb ない + ことにする is used to express the decision not to do something. This structure shows that the speaker has made a conscious choice to not take the action expressed in the verb.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_nai_koto_ni_naru','Verb ない ことになる',NULL,NULL,'N4','[]','[{"ja":"今日彼が来ないことになると、私たちの予定はキャンセルされます。","en":"If he doesn''t come today, our plans will be canceled.","romaji":"Kyou kare ga konai koto ni naru to, watashitachi no yotei wa kyanseru saremasu.","zh":""},{"ja":"このプロジェクトが進まないことになると、収益が減るでしょう。","en":"If this project doesn''t progress, it would mean that revenue will decrease.","romaji":"Kono purojekuto ga susumanai koto ni naru to, shuueki ga heru deshou.","zh":""},{"ja":"彼女は試験に合格しないことになると、卒業が遅れます。","en":"If she ends up not passing the exam, her graduation will be delayed.","romaji":"Kanojo wa shiken ni goukaku shinai koto ni naru to, sotsugyou ga okuremasu.","zh":""},{"ja":"雨が降ると、ピクニックが行われないことになるでしょう。","en":"If it rains, it will become that the picnic doesn''t take place.","romaji":"Ame ga furu to, pikunikku ga okonawarenai koto ni naru deshou.","zh":""}]',replace('**Short**: Expresses a result; ''end up not'', ''it will become that'', ''it would mean that''.\n\n**Formation**: Verb-negative (ない) + ことになる\n\n**Long**: The Verb ない ことになる grammar point is used to express a result or consequence. It translates to ''end up not'', ''it will become that'', or ''it would mean that'' in English. It is formed by using the negative form (ない) of a verb followed by ことになる.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_nai_hou_ga_ii','Verb ないほうがいい',NULL,NULL,'N4','[]','[{"ja":"この薬は飲まないほうがいいです。","en":"It''s better not to take this medicine.","romaji":"Kono kusuri wa nomanai hou ga ii desu.","zh":""},{"ja":"急いでいるときは、走らないほうがいい。","en":"When you''re in a hurry, it''s better not to run.","romaji":"Isoide iru toki wa, hashiranai hou ga ii.","zh":""},{"ja":"彼に秘密を知られたくなければ、話さないほうがいい。","en":"If you don''t want him to know your secret, it''s better not to tell him.","romaji":"Kare ni himitsu o shiraretakunakereba, hanasanai hou ga ii.","zh":""},{"ja":"雨の日には、外出しないほうがいい。","en":"It''s better not to go out on a rainy day.","romaji":"Ame no hi ni wa, gaishutsu shinai hou ga ii.","zh":""}]',replace('**Short**: Expresses the idea that it is better not to do something.\n\n**Formation**: Verb-negative form + ほうがいい\n\n**Long**: The ないほうがいい grammar point is used to suggest that it''s better not to do a certain action. It is formed by taking the negative form of the verb and adding ほうがいい.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nagara_n4','Verb ながら',NULL,NULL,'N4','[]','[{"ja":"テレビを見ながら宿題をしました。","en":"I did my homework while watching television.","romaji":"Terebi wo minagara shukudai wo shimashita.","zh":""},{"ja":"音楽を聞きながら料理をしました。","en":"I cooked while listening to music.","romaji":"Ongaku wo kikinagara ryouri wo shimashita.","zh":""},{"ja":"歩きながらスマホを見るのは危険です。","en":"Looking at your smartphone while walking is dangerous.","romaji":"Arukinagara sumaho wo miru no wa kiken desu.","zh":""},{"ja":"彼は話しながら笑っていました。","en":"He was laughing while talking.","romaji":"Kare wa hanashi nagara waratte imashita.","zh":""}]',replace('**Short**: Expresses ''while'' or ''as'' in the sense of doing two things simultaneously.\n\n**Formation**: Verb-masu stem + ながら\n\n**Long**: The ～ながら grammar point is used to indicate that two actions are happening simultaneously or that one action is happening while another is taking place. This can be translated to ''while'' or ''as'' in English. It is primarily used with verbs.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nasai','Verb なさい',NULL,NULL,'N4','[]','[{"ja":"部屋を掃除しなさい。","en":"Clean your room.","romaji":"Heya wo souji shinasai.","zh":""},{"ja":"勉強しなさい。","en":"Study.","romaji":"Benkyou shinasai.","zh":""},{"ja":"早く起きなさい。","en":"Wake up early.","romaji":"Hayaku okinasai.","zh":""},{"ja":"宿題をやりなさい。","en":"Do your homework.","romaji":"Shukudai wo yarinasai.","zh":""}]',replace('**Short**: A command form used to give orders or instructions; ''Please do'', ''Do this''.\n\n**Formation**: Verb-stem + なさい\n\n**Long**: The なさい grammar point is used to give orders or instructions, often used by teachers, parents, or other authority figures when addressing someone younger or of lower status. It is formed by attaching なさい to the stem of a verb. This form sounds polite, but can be considered strong and direct.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nikui','Verb にくい',NULL,NULL,'N4','[]','[{"ja":"この字は読みにくいです。","en":"This character is hard to read.","romaji":"Kono ji wa yomi nikui desu.","zh":""},{"ja":"このドアは開けにくい。","en":"This door is difficult to open.","romaji":"Kono doa wa ake nikui.","zh":""},{"ja":"彼の字は読みにくい。","en":"His handwriting is hard to read.","romaji":"Kare no ji wa yomi nikui.","zh":""},{"ja":"この料理は作りにくい。","en":"This dish is difficult to make.","romaji":"Kono ryouri wa tsukuri nikui.","zh":""}]',replace('**Short**: Express difficulty or complexity; ''hard to'', ''difficult to'', ''not easily''.\n\n**Formation**: Verb-stem + にくい\n\n**Long**: The ～にくい grammar point is used to express that an action is difficult or relatively hard to do. It is used by attaching にくい to the stem of a verb. It can be translated as ''hard to'', ''difficult to'', or ''not easily'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_yasui','Verb やすい',NULL,NULL,'N4','[]','[{"ja":"この本は読みやすいです。","en":"This book is easy to read.","romaji":"Kono hon wa yomiyasui desu.","zh":""},{"ja":"このシャツは着やすい。","en":"This shirt is easy to wear.","romaji":"Kono shatsu wa kiyasui.","zh":""},{"ja":"彼は話しやすい人です。","en":"He is an easy person to talk to.","romaji":"Kare wa hanashiyasui hito desu.","zh":""},{"ja":"この料理は作りやすい。","en":"This dish is easy to make.","romaji":"Kono ryouri wa tsukuriyasui.","zh":""}]',replace('**Short**: Indicates that something is easy to do; ''easy to'', ''easy for''.\n\n**Formation**: Verb-stem + やすい\n\n**Long**: The やすい grammar point is used to express that something is easy to do or easy for someone. It is attached to the verb stem and can be translated as ''easy to'' or ''easy for'' in English. This formation is used with verbs only.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_you_to_omou','Verb ようと思う',NULL,NULL,'N4','[]','[{"ja":"明日、映画を見ようと思います。","en":"I think I will watch a movie tomorrow.","romaji":"Ashita, eiga o miyou to omoimasu.","zh":""},{"ja":"週末に友達と遊ぼうと思っています。","en":"I plan to hang out with friends on the weekend.","romaji":"Shuumatsu ni tomodachi to asobou to omotteimasu.","zh":""},{"ja":"勉強をもっと頑張ろうと思う。","en":"I intend to study harder.","romaji":"Benkyou o motto ganbarou to omou.","zh":""},{"ja":"来年は海外旅行に行こうと思っている。","en":"I plan to go on an overseas trip next year.","romaji":"Rainen wa kaigai ryokou ni ikou to omotteiru.","zh":""}]',replace('**Short**: Express intention or plan to do something; ''I think I will'', ''I plan to'', ''I intend to''.\n\n**Formation**: Verb-volitional + と思う\n\n**Long**: The ようと思う grammar point is used to express the intention or plan to do something in the future. It can be translated as ''I think I will'', ''I plan to'', or ''I intend to'' in English. The formation involves using the volitional form of the verb followed by と思う.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_you_ni_n4','Verb ように',NULL,NULL,'N4','[]','[{"ja":"彼女は鳥のように軽やかに踊る。","en":"She dances lightly like a bird.","romaji":"Kanojo wa tori no you ni karoyaka ni odoru.","zh":""},{"ja":"覚えたことを忘れないように、毎日復習しましょう。","en":"In order not to forget what you''ve learned, let''s review every day.","romaji":"Oboeta koto wo wasurenai you ni, mainichi fukushuu shimashou.","zh":""},{"ja":"歌手になるように、毎日歌の練習をしています。","en":"In order to become a singer, I practice singing every day.","romaji":"Kashu ni naru you ni, mainichi uta no renshuu wo shiteimasu.","zh":""},{"ja":"道を渡る時、車が来ないように確認してください。","en":"When crossing the road, please make sure no cars are coming.","romaji":"Michi wo wataru toki, kuruma ga konai you ni kakunin shite kudasai.","zh":""}]',replace('**Short**: Used to express ''like'', ''as if'', ''in order to'', or ''so that''.\n\n**Formation**: Examples: Noun + のように / Verb-casual + ように / い-adjective + ように\n\n**Long**: The ～ように grammar point is used to express different meanings depending on the context: ''like'', ''as if'', ''in order to'', or ''so that''. Formation patterns can include: Noun + のように, Verb dictionary/negative form + ように, い-adjective + ように, etc.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_you_ni_suru','Verb ようにする',NULL,NULL,'N4','[]','[{"ja":"毎日運動するようにしています。","en":"I try to exercise every day.","romaji":"Mainichi undou suru you ni shiteimasu.","zh":""},{"ja":"早く寝るようにしてください。","en":"Please try to go to bed early.","romaji":"Hayaku neru you ni shite kudasai.","zh":""},{"ja":"約束を守るようにします。","en":"I will make sure to keep my promise.","romaji":"Yakusoku o mamoru you ni shimasu.","zh":""},{"ja":"彼に会わないようにする。","en":"I will try not to see him.","romaji":"Kare ni awanai you ni suru.","zh":""}]',replace('**Short**: Make an effort to; try to; see to it that; ensure that.\n\n**Formation**: Verb-dictionary form + ようにする\n\n**Long**: The ようにする grammar point is used to express that someone is making an effort, trying, or seeing to it that something happens. It can be translated as ''make sure to'', ''try to'', or ''ensure that'' in English. The formation is simple, involving a verb in the dictionary form followed by ようにする.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_you_ni_naru','Verb ようになる',NULL,NULL,'N4','[]','[{"ja":"日本語が話せるようになりました。","en":"I have become able to speak Japanese.","romaji":"Nihongo ga hanaseru you ni narimashita.","zh":""},{"ja":"最近、早く寝るようになった。","en":"Recently, I have come to go to bed early.","romaji":"Saikin, hayaku neru you ni natta.","zh":""},{"ja":"彼はピアノを弾けるようになりました。","en":"He has become able to play the piano.","romaji":"Kare wa piano wo hikeru you ni narimashita.","zh":""},{"ja":"この仕事を始めてから、毎日忙しいと感じるようになりました。","en":"Since I started this job, I''ve begun to feel busy every day.","romaji":"Kono shigoto o hajimete kara, mainichi isogashii to kanjiru you ni narimashita.","zh":""}]',replace('**Short**: Express a change in ability, situation or state; ''become able to'', ''come to'', ''begin to''.\n\n**Formation**: Verb-dictionary/potential form + ようになる\n\n**Long**: The ようになる grammar implies a change or development involving new abilities, situations or states. It can be translated into English as ''become able to'', ''come to'' or ''begin to''. This grammar is often used when talking about a skill that has been acquired or a change in habit or situation over time.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_you_ni_iu','Verb ように言う',NULL,NULL,'N4','[]','[{"ja":"先生は私たちに宿題をやるように言いました。","en":"The teacher told us to do our homework.","romaji":"Sensei wa watashitachi ni shukudai o yaru you ni iimashita.","zh":""},{"ja":"母は弟に部屋を片付けるように言いました。","en":"My mother told my younger brother to clean his room.","romaji":"Haha wa otouto ni heya wo katazukeru you ni iimashita.","zh":""},{"ja":"上司は私に報告書を提出するように言いました。","en":"My boss told me to submit the report.","romaji":"Joushi wa watashi ni houkokusho wo teishutsu suru you ni iimashita.","zh":""},{"ja":"友達が私に早く来るように言いました。","en":"My friend told me to come early.","romaji":"Tomodachi ga watashi ni hayaku kuru you ni iimashita.","zh":""}]',replace('**Short**: Tell someone to do something; ''tell to do'', ''instruct to do''.\n\n**Formation**: Verb-casual + ように言う\n\n**Long**: The grammar point Verb ように言う is used when someone tells or instructs another person to do something. It can be translated as ''tell to do'' or ''instruct to do'' in English. The formation is created by adding ように言う to the casual form of a verb.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_rareru','Verb られる',NULL,NULL,'N4','[]','[{"ja":"彼は先生に褒められました。","en":"He was praised by the teacher.","romaji":"Kare wa sensei ni homeraremashita.","zh":""},{"ja":"彼は友達に笑われました。","en":"He was laughed at by his friends.","romaji":"Kare wa tomodachi ni warawaremashita.","zh":""},{"ja":"映画は観られましたか？","en":"Were you able to watch the movie?","romaji":"Eiga wa miraremashita ka?","zh":""},{"ja":"彼女はリーダーに選ばれました。","en":"She was chosen as the leader.","romaji":"Kanojo wa riidaa ni erabaremashita.","zh":""}]',replace('**Short**: Expresses passive voice or potential form for verbs.\n\n**Formation**: う-verb (passive): Replace the final う with われる / る-verb (passive & potential): Replace る with られる / Irregular: する → される, くる → こられる\n\n**Long**: The られる grammar point can be used to express passive voice or potential form for verbs. Passive voice indicates that the action is being done to the subject, while potential form expresses the ability or possibility to do an action. The formation of られる depends on the type of verb (う, る, or irregular verbs).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ru_koto_ga_aru','Verb る ことがある',NULL,NULL,'N4','[]','[{"ja":"彼は遅刻することがあります。","en":"He is sometimes late.","romaji":"Kare wa chikoku suru koto ga arimasu.","zh":""},{"ja":"私は寝坊することがあります。","en":"I sometimes oversleep.","romaji":"Watashi wa nebou suru koto ga arimasu.","zh":""},{"ja":"彼女は歌を歌うことがあります。","en":"She sometimes sings songs.","romaji":"Kanojo wa uta o utau koto ga arimasu.","zh":""},{"ja":"子供の頃、よく山に登ることがありました。","en":"When I was a child, I sometimes climbed mountains.","romaji":"Kodomo no koro, yoku yama ni noboru koto ga arimashita.","zh":""}]',replace('**Short**: Used to express that something happens sometimes or has happened before.\n\n**Formation**: Verb-dictionary form + ことがある\n\n**Long**: The grammar point る ことがある is used to express that something occurs sometimes or has occurred in the past. It indicates that the action is not a regular or constant event, but rather something that takes place occasionally or has happened at least once.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ru_koto_ga_dekiru_n4','Verb ることができる',NULL,NULL,'N4','[]','[{"ja":"私は日本語を話すことができます。","en":"I can speak Japanese.","romaji":"Watashi wa nihongo wo hanasu koto ga dekimasu.","zh":""},{"ja":"彼はギターを弾くことができます。","en":"He can play the guitar.","romaji":"Kare wa gitaa wo hiku koto ga dekimasu.","zh":""},{"ja":"この問題を解決することができますか？","en":"Can you solve this problem?","romaji":"Kono mondai wo kaiketsu suru koto ga dekimasu ka?","zh":""},{"ja":"彼女は犬を泳がせることができます。","en":"She can make the dog swim.","romaji":"Kanojo wa inu wo oyogaseru koto ga dekimasu.","zh":""}]',replace('**Short**: Express ability or possibility of doing an action; ''can'', ''be able to'', ''is possible''.\n\n**Formation**: Verb-る + ことができる\n\n**Long**: The ～ることができる grammar point is used to express the ability or possibility of doing an action in Japanese. It can be translated as ''can'', ''be able to'', or ''is possible'' in English. The formation is made by adding the phrase ''ことができる'' to the verb in its conjugated る-form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ru_koto_ni_suru','Verb ることにする',NULL,NULL,'N4','[]','[{"ja":"来週、ジムに行くことにしました。","en":"I decided to go to the gym next week.","romaji":"Raishuu, jimu ni iku koto ni shimashita.","zh":""},{"ja":"この靴を買うことにしました。","en":"I decided to buy these shoes.","romaji":"Kono kutsu wo kau koto ni shimashita.","zh":""},{"ja":"毎日、散歩をすることにしました。","en":"I decided to take a walk every day.","romaji":"Mainichi, sanpo wo suru koto ni shimashita.","zh":""},{"ja":"彼に電話をかけることにします。","en":"I’ve decided to call him.","romaji":"Kare ni denwa wo kakeru koto ni shimasu.","zh":""}]',replace('**Short**: Decide to do something, make a decision.\n\n**Formation**: Verb-る + ことにする\n\n**Long**: The ～ることにする grammar point is used to express that someone has made a decision to do something or has decided on a specific course of action. It is formed by attaching ことにする to the verb in its る form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ru_koto_ni_naru','Verb る ことになる',NULL,NULL,'N4','[]','[{"ja":"今日は会議がなくなることになりました。","en":"It has been decided that there will be no meeting today.","romaji":"Kyou wa kaigi ga nakunaru koto ni narimashita.","zh":""},{"ja":"来週、友達と旅行することになった。","en":"It has been arranged that I will travel with my friends next week.","romaji":"Raishuu, tomodachi to ryokou suru koto ni natta.","zh":""},{"ja":"彼女が今度のプロジェクトのリーダーになることになりました。","en":"It has been decided that she will be the leader of the next project.","romaji":"Kanojo ga kondo no purojekuto no riida ni naru koto ni narimashita.","zh":""},{"ja":"急に仕事が入ったので、休みを取ることになった。","en":"Due to sudden work, it has been decided that I will take a day off.","romaji":"Kyuu ni shigoto ga haitta node, yasumi wo toru koto ni natta.","zh":""}]',replace('**Short**: Indicates that something has been decided or arranged; ''it has been decided that'', ''it turns out that''.\n\n**Formation**: Verb-る + ことになる\n\n**Long**: The る ことになる grammar point is used to express that something has been decided or arranged. It often indicates a decision made by someone else or due to circumstances. It can be translated as ''it has been decided that'' or ''it turns out that'' in English. The formation requires a verb in る (dictionary) form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ru_toki_ni','Verb るときに',NULL,NULL,'N4','[]','[{"ja":"映画を見るときに、ポップコーンを食べます。","en":"When I watch a movie, I eat popcorn.","romaji":"Eiga wo miru toki ni, poppukoon wo tabemasu.","zh":""},{"ja":"寝るときに、部屋の電気を消します。","en":"When I go to bed, I turn off the room lights.","romaji":"Neru toki ni, heya no denki wo keshimasu.","zh":""},{"ja":"運動するときに、水分補給が大切です。","en":"When exercising, it''s important to stay hydrated.","romaji":"Undou suru toki ni, suibun hokyuu ga taisetsu desu.","zh":""},{"ja":"旅行するときに、カメラを持っていくことが好きです。","en":"When I travel, I like to bring a camera.","romaji":"Ryokou suru toki ni, kamera wo motteiku koto ga suki desu.","zh":""}]',replace('**Short**: Describes the time when a certain action takes place; ''when'', ''at the time''.\n\n**Formation**: Verb-る + ときに\n\n**Long**: The ～るときに grammar point is used to indicate the time when a certain action or event happens. It can be translated as ''when'' or ''at the time'' in English. The formation involves attaching ときに to the verb in its dictionary (る) form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ru_tokoro','Verb る ところ',NULL,NULL,'N4','[]','[{"ja":"彼は食べるところです。","en":"He is in the process of eating.","romaji":"Kare wa taberu tokoro desu.","zh":""},{"ja":"私は出かけるところです。","en":"I am just about to leave.","romaji":"Watashi wa dekakeru tokoro desu.","zh":""},{"ja":"彼女は泣くところでした。","en":"She was on the verge of crying.","romaji":"Kanojo wa naku tokoro deshita.","zh":""},{"ja":"私たちは勉強するところです。","en":"We are in the middle of studying.","romaji":"Watashitachi wa benkyou suru tokoro desu.","zh":""}]',replace('**Short**: Expresses the state or moment when an action is about to happen or is happening.\n\n**Formation**: Verb-dictionary form + ところ\n\n**Long**: The grammar point ''Verb る ところ'' is used to express that one is just about to do something, or is in the process of doing it. It can be translated as ''just about to'' or ''in the middle of'' in English, depending on context.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dasu','Verb 出す',NULL,NULL,'N4','[]','[{"ja":"本を棚から出してください。","en":"Please take the book out from the shelf.","romaji":"Hon o tana kara dashite kudasai.","zh":""},{"ja":"彼は部屋から急いで出ました。","en":"He rushed out of the room.","romaji":"Kare wa heya kara isoide demashita.","zh":""},{"ja":"授業が始まる前に宿題を出してください。","en":"Submit your homework before class starts.","romaji":"Jugyou ga hajimaru mae ni shukudai wo dashite kudasai.","zh":""},{"ja":"彼女は歌い出しました。","en":"She began to sing.","romaji":"Kanojo wa utaidashimashita.","zh":""}]',replace('**Short**: Express the action of taking something out, starting an action, or emphasizing a verb.\n\n**Formation**: Verb stem + 出す (~dasu)\n\n**Long**: The verb 出す (~dasu) is used to express the action of taking something out, starting an action, or emphasizing the verb it is attached to. To form this grammar point, simply attach 出す (~dasu) to the stem of the verb.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_hou','Verb 方',NULL,NULL,'N4','[]','[{"ja":"誰かがケーキの作り方を知っていますか？","en":"Does anyone know how to make a cake?","romaji":"Dareka ga keeki no tsukurikata o shitteimasu ka?","zh":""},{"ja":"彼女は英語の話し方を学んでいます。","en":"She is learning how to speak English.","romaji":"Kanojo wa eigo no hanashikata o manandeimasu.","zh":""},{"ja":"このパソコンの使い方を教えてください。","en":"Please teach me how to use this computer.","romaji":"Kono pasokon no tsukaikata o oshiete kudasai.","zh":""},{"ja":"数学の問題の解き方を覚えるのが難しいです。","en":"It is difficult to remember the way to solve math problems.","romaji":"Suugaku no mondai no tokikata o oboeru no ga muzukashii desu.","zh":""}]',replace('**Short**: Indicates the way or method of doing something; often read as ''～かた'' (''how to'', ''the way of'').\n\n**Formation**: Verb-stem + 方 (read as かた)\n\n**Long**: The ～方 grammar point is used to express the way or method of doing something, similar to ''how to'' or ''the way of'' in English. It can be attached to the stem of a verb to form a noun that indicates the method of doing the action. In practice, ～方 is usually read as ''～かた'' (e.g., 作り方＝つくりかた).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_owaru','Verb 終わる',NULL,NULL,'N4','[]','[{"ja":"映画が終わったら、家に帰ります。","en":"When the movie finishes, I''ll go home.","romaji":"Eiga ga owattara, ie ni kaerimasu.","zh":""},{"ja":"仕事が終わるまで、待ってください。","en":"Please wait until the work is finished.","romaji":"Shigoto ga owaru made, matte kudasai.","zh":""},{"ja":"パーティーはもうすぐ終わります。","en":"The party will be over soon.","romaji":"Paatii wa mou sugu owarimasu.","zh":""},{"ja":"試験が終わったら、友達と遊びに行く予定です。","en":"Once the exam is over, I plan to go out with my friends.","romaji":"Shiken ga owattara, tomodachi to asobi ni iku yotei desu.","zh":""}]',replace('**Short**: Verbal action is completed; ''to finish'', ''to end''.\n\n**Formation**: 終わる (owaru) is a godan (u-verb)\n\n**Long**: The verb 終わる (owaru) is used to express that an action has been completed or something has come to an end. Despite ending in る, 終わる is a godan (u-verb), so it does not follow the typical ichidan (る-verb) conjugation. It is translated as ''to finish'', ''to end'' or ''to be over'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tsuzukeru','Verb + 続ける',NULL,NULL,'N4','[]','[{"ja":"彼は毎日ジムで運動を続けています。","en":"He continues to exercise at the gym every day.","romaji":"Kare wa mainichi jimu de undou o tsuzuketeimasu.","zh":""},{"ja":"彼女は勉強を続けるために図書館に行きました。","en":"She went to the library to continue studying.","romaji":"Kanojo wa benkyou o tsuzukeru tame ni toshokan ni ikimashita.","zh":""},{"ja":"私たちは雨にも関わらず散歩を続けました。","en":"We continued walking despite the rain.","romaji":"Watashitachi wa ame ni mo kakawarazu sanpo o tsuzukemashita.","zh":""},{"ja":"彼は仕事を続けることに決めた。","en":"He decided to continue working.","romaji":"Kare wa shigoto o tsuzukeru koto ni kimeta.","zh":""}]',replace('**Short**: To continue doing or to keep doing an action.\n\n**Formation**: Verb-masu-stem + 続ける\n\n**Long**: The grammar point 続ける (tsuzukeru) is attached to the masu-stem form of verbs, and it indicates the ongoing continuity of an action. It can be translated as ''to continue doing'' or ''to keep doing'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kashira','～かしら',NULL,NULL,'N4','[]','[{"ja":"今日は雨が降るかしら？","en":"I wonder if it will rain today?","romaji":"Kyou wa ame ga furu kashira?","zh":""},{"ja":"このケーキは美味しいかしら？","en":"I wonder if this cake is delicious?","romaji":"Kono keeki wa oishii kashira?","zh":""},{"ja":"彼は病気かしら？","en":"I wonder if he is sick?","romaji":"Kare wa byouki kashira?","zh":""},{"ja":"彼女は学生かしら？","en":"I wonder if she is a student?","romaji":"Kanojo wa gakusei kashira?","zh":""}]',replace('**Short**: Indicates uncertainty or doubt; ''I wonder'', ''I''m not sure''.\n\n**Formation**: Verb-casual + かしら, い-Adjective + かしら, な-Adjective + かしら, Noun + かしら\n\n**Long**: The ～かしら grammar point is used to express uncertainty or doubt about a situation. It can be translated as ''I wonder'' or ''I''m not sure'' in English. It is primarily used by females in casual conversations but can be used by males in some contexts as well. ～かしら is used with verbs, い-adjectives, な-adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ka_dou_ka','～かどうか',NULL,NULL,'N4','[]','[{"ja":"彼が来るかどうか知りません。","en":"I don''t know if he will come or not.","romaji":"Kare ga kuru ka dou ka shirimasen.","zh":""},{"ja":"この本が面白いかどうか教えてください。","en":"Please tell me if this book is interesting or not.","romaji":"Kono hon ga omoshiroi ka dou ka oshiete kudasai.","zh":""},{"ja":"彼女が綺麗だかどうかは分かりません。","en":"I don''t know whether she is beautiful or not.","romaji":"Kanojo ga kirei da ka dou ka wa wakarimasen.","zh":""},{"ja":"彼が先生だかどうか覚えていません。","en":"I don''t remember if he is a teacher or not.","romaji":"Kare ga sensei da ka dou ka oboete imasen.","zh":""}]',replace('**Short**: Used to express ''whether'' or ''if'' in indirect questions or statements.\n\n**Formation**: Verb-casual + かどうか, い-Adjective + かどうか, な-Adjective + (だ)かどうか, Noun + (だ)かどうか\n\n**Long**: The ～かどうか grammar point is used to express ''whether'' or ''if'' in indirect questions or statements. It is often used to express uncertainty or to inquire about information in a more polite form. ～かどうか can be used with verbs, い-adjectives, な-adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kanaa_n4','～かなあ',NULL,NULL,'N4','[]','[{"ja":"明日雨が降るかなあ。","en":"I wonder if it will rain tomorrow.","romaji":"Ashita ame ga furu kanaa.","zh":""},{"ja":"このケーキは美味しいかなあ。","en":"I wonder if this cake is delicious.","romaji":"Kono keeki wa oishii kanaa.","zh":""},{"ja":"彼は病気かなあ。","en":"I wonder if he is sick.","romaji":"Kare wa byouki kanaa.","zh":""},{"ja":"彼女は学生かなあ。","en":"I wonder if she is a student.","romaji":"Kanojo wa gakusei kanaa.","zh":""}]',replace('**Short**: Expresses uncertainty or wonder; ''I wonder'', ''I''m not sure''.\n\n**Formation**: Verb-casual + かなあ, い-Adjective + かなあ, (な-Adjective/Noun) + (だ) + かなあ\n\n**Long**: The ～かなあ grammar point is used to express a feeling of uncertainty or wonder about a situation or statement. It can be translated as ''I wonder'' or ''I''m not sure'' in English. In casual spoken Japanese, when using nouns or な-adjectives before かなあ, the copula だ is often omitted or replaced with の (e.g., 学生かなあ or 学生なのかなあ). This grammar point should not be used when asking questions directly to someone, as it may come off as too direct or impolite.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kamoshirenai','～かもしれない',NULL,NULL,'N4','[]','[{"ja":"明日雨が降るかもしれない。","en":"It might rain tomorrow.","romaji":"Ashita ame ga furu kamoshirenai.","zh":""},{"ja":"このケーキは美味しいかもしれない。","en":"This cake might be delicious.","romaji":"Kono keeki wa oishii kamoshirenai.","zh":""},{"ja":"彼が病気かもしれない。","en":"He might be sick.","romaji":"Kare ga byouki kamoshirenai.","zh":""},{"ja":"彼女は学生かもしれない。","en":"She might be a student.","romaji":"Kanojo wa gakusei kamoshirenai.","zh":""}]',replace('**Short**: Express uncertainty; ''maybe'', ''might'', ''possibly''.\n\n**Formation**: Verb-casual + かもしれない, い-Adjective + かもしれない, な-Adjective + だかもしれない, Noun + だかもしれない\n\n**Long**: The ～かもしれない grammar point is used to express uncertainty or the possibility of something occurring. It can be translated as ''maybe'', ''might'', or ''possibly'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun. In everyday speech, speakers often omit だ before かもしれない for nouns and な-adjectives.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kara_n4','～から',NULL,NULL,'N4','[]','[{"ja":"雨が降るから、傘を持って行ってください。","en":"Because it''s raining, please bring an umbrella.","romaji":"Ame ga furu kara, kasa wo motte itte kudasai.","zh":""},{"ja":"このケーキは美味しいから、みんな食べるでしょう。","en":"Because this cake is delicious, everyone will probably eat it.","romaji":"Kono keeki wa oishii kara, minna taberu deshou.","zh":""},{"ja":"彼は病気だから、学校を休みます。","en":"He will be absent from school because he is sick.","romaji":"Kare wa byouki dakara, gakkou wo yasumimasu.","zh":""},{"ja":"今日は日曜日だから、学校がありません。","en":"There is no school today because it is Sunday.","romaji":"Kyou wa nichiyoubi dakara, gakkou ga arimasen.","zh":""}]',replace('**Short**: Express a reason or cause; ''because'', ''since'', ''due to''.\n\n**Formation**: Verb-casual + から, い-Adjective + から, な-Adjective + だから, Noun + だから\n\n**Long**: The ～から grammar point is used to express a reason, cause, or the origin of something. It can be translated as ''because'', ''since'', or ''due to'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_keredo_n4','～けれど',NULL,NULL,'N4','[]','[{"ja":"今日は忙しいけれど、明日はもっと時間がある。","en":"I''m busy today, but I have more time tomorrow.","romaji":"Kyou wa isogashii keredo, ashita wa motto jikan ga aru.","zh":""},{"ja":"このレストランは高いけれど、料理が美味しい。","en":"This restaurant is expensive, but the food is delicious.","romaji":"Kono resutoran wa takai keredo, ryouri ga oishii.","zh":""},{"ja":"彼は若いけれど、とても経験豊富だ。","en":"He is young, but he is very experienced.","romaji":"Kare wa wakai keredo, totemo keiken houfu da.","zh":""},{"ja":"彼女は病気だけれど、明るく元気だ。","en":"She is sick, but she is cheerful and energetic.","romaji":"Kanojo wa byouki da keredo, akaruku genki da.","zh":""}]',replace('**Short**: Indicate a soft contrast or contradiction; ''but'', ''however''.\n\n**Formation**: Verb-casual + けれど, い-Adjective + けれど, な-Adjective + だけれど, Noun + だけれど\n\n**Long**: The ～けれど grammar point is used to express a soft contrast or contradiction between two statements. It can be translated as ''but'' or ''however'' in English. It is relatively informal and can be replaced by more formal expressions like けれども or が. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sasete_kudasai','～させてください',NULL,NULL,'N4','[]','[{"ja":"もう少し考えさせてください。","en":"Please let me think a little more.","romaji":"Mou sukoshi kangaesasete kudasai.","zh":""},{"ja":"写真を撮らせてください。","en":"Please let me take a photo.","romaji":"Shashin o torasete kudasai.","zh":""},{"ja":"もうちょっと練習させてください。","en":"Please let me practice a little more.","romaji":"Mou chotto renshuu sasete kudasai.","zh":""},{"ja":"ここで待たせてください。","en":"Please let me wait here.","romaji":"Koko de matasete kudasai.","zh":""}]',replace('**Short**: Express a polite request to allow or permit someone to do something.\n\n**Formation**: Verb-causative form + ください\n\n**Long**: The ～させてください grammar point is used to make a polite request to allow or permit someone to do something. It can be translated as ''please let me'' or ''please allow me to'' in English. It is formed by taking the causative form of a verb and adding ください.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_shi_shi','～し、～し、～',NULL,NULL,'N4','[]','[{"ja":"彼は若いし、元気だし、フレンドリーだし、みんなと仲良くなれると思います。","en":"He is young, energetic, friendly, and I think he can get along with everyone.","romaji":"Kare wa wakai shi, genki da shi, furendorī da shi, minna to nakayoku nareru to omoimasu.","zh":""},{"ja":"このレストランは料理が美味しいし、雰囲気がいいし、価格も手頃だからお勧めです。","en":"I recommend this restaurant because the food is delicious, the atmosphere is nice, and the prices are reasonable.","romaji":"Kono resutoran wa ryouri ga oishii shi, fun''iki ga ii shi, kakaku mo tegoro dakara osusume desu.","zh":""},{"ja":"彼女は勉強ができるし、スポーツも得意だし、性格もいい。","en":"She is good at studying, good at sports, and has a good personality.","romaji":"Kanojo wa benkyou ga dekiru shi, supōtsu mo tokui da shi, seikaku mo ii.","zh":""},{"ja":"今日は寒いし、雨も降っているし、家でゆっくり休んだ方がいいでしょう。","en":"It''s cold today, and it''s raining, so it''s better to relax at home.","romaji":"Kyou wa samui shi, ame mo futte iru shi, ie de yukkuri yasunda hou ga ii deshou.","zh":""}]',replace('**Short**: Express multiple reasons or characteristics; ''and'', ''because'', ''since''.\n\n**Formation**: Verb-casual + し, い-Adjective + し, な-Adjective + だし, Noun + だし\n\n**Long**: The ～し、～し、～ grammar point is used to connect multiple reasons or characteristics that support a conclusion or statement. It can be translated as ''and'', ''because'', or ''since'' in English. This grammar can be used with verbs, い-adjectives, な-adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sugiru','～すぎる',NULL,NULL,'N4','[]','[{"ja":"この部屋は暑すぎる。","en":"This room is too hot.","romaji":"Kono heya wa atsui sugiru.","zh":""},{"ja":"彼は早く来すぎた。","en":"He came too early.","romaji":"Kare wa hayaku kisugita.","zh":""},{"ja":"この箱は重すぎて持ち上げられない。","en":"This box is too heavy to lift.","romaji":"Kono hako wa omosugite mochiagerarenai.","zh":""},{"ja":"彼女は忙しくて遊びすぎはしない。","en":"She''s too busy to play too much.","romaji":"Kanojo wa isogashikute asobisugi wa shinai.","zh":""}]',replace('**Short**: Expresses that something is excessive or overdone; ''too much'', ''too'', ''over''.\n\n**Formation**: Verb-stem + すぎる, い-Adjective (remove い) + すぎる, な-Adjective + すぎる\n\n**Long**: The ～すぎる grammar point is used to express that something is excessive or beyond a certain level. It can be translated as ''too much'', ''too'', or ''over'' in English. The formation differs depending on whether it is used with a verb, い-adjective, or な-adjective.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_zutsu','～ずつ',NULL,NULL,'N4','[]','[{"ja":"りんごを2つずつ配ります。","en":"I will distribute 2 apples each.","romaji":"Ringo wo futatsu zutsu kubarimasu.","zh":""},{"ja":"私たちは週に一度ずつ掃除をします。","en":"We each clean once per week.","romaji":"Watashitachi wa shuu ni ichido zutsu souji o shimasu.","zh":""},{"ja":"みんなは同じ距離を一歩ずつ歩いた。","en":"Everyone walked the same distance, one step at a time.","romaji":"Minna wa onaji kyori o ippo zutsu aruita.","zh":""},{"ja":"彼女は子供たちに一枚ずつプレゼントをくれました。","en":"She gave one present to each child.","romaji":"Kanojo wa kodomotachi ni ichimai zutsu purezento o kuremashita.","zh":""}]',replace('**Short**: Indicates equal distribution; ''each'', ''per'', ''apiece''.\n\n**Formation**: Noun + ずつ\n\n**Long**: The ～ずつ grammar point is used to express an equal distribution of something, whether it is an action, an amount, or an item. It is translated as ''each'', ''per'', or ''apiece'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sou_da','～そうだ',NULL,NULL,'N4','[]','[{"ja":"その花はとてもきれいそうだ。","en":"That flower looks very beautiful.","romaji":"Sono hana wa totemo kirei sou da.","zh":""},{"ja":"彼は疲れそうだ。","en":"He looks tired.","romaji":"Kare wa tsukare sou da.","zh":""},{"ja":"この本は面白そうだ。","en":"This book looks interesting.","romaji":"Kono hon wa omoshiro sou da.","zh":""},{"ja":"雨が降りそうだ。","en":"It looks like it''s going to rain.","romaji":"Ame ga furi sou da.","zh":""}]',replace('**Short**: Express the appearance, seeming, or feeling of something; ''looks like'', ''seems'', ''appears''.\n\n**Formation**: Verb-ますstem + そうだ, い-Adjective (without い) + そうだ, な-Adjective + そうだ\n\n**Long**: The ～そうだ grammar point is used to describe the appearance or feeling of something based on what is observed or inferred. It can be translated as ''looks like'', ''seems'', or ''appears'' in English. The formation differs depending on whether it is used with a verb, い-adjective, or な-adjective.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sonna_noun','そんな (sonna) + Noun',NULL,NULL,'N4','[]','[{"ja":"そんな話、信じられない。","en":"I can''t believe that kind of story.","romaji":"Sonna hanashi, shinjirarenai.","zh":""},{"ja":"そんな映画、見たくない。","en":"I don''t want to watch that kind of movie.","romaji":"Sonna eiga, mitakunai.","zh":""}]',replace('**Short**: Expresses ''that kind/type of''; referring to something near the listener or previously mentioned.\n\n**Formation**: そんな + Noun\n\n**Long**: The word ''そんな'' is used before a noun to indicate ''that kind of'' or ''that type of'', typically referring to something near the listener or previously mentioned in the conversation. It specifies the noun based on context or shared understanding between the speaker and the listener.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sonna_ni','そんなに～',NULL,NULL,'N4','[]','[{"ja":"そんなに急がなくてもいいですよ。","en":"You don''t have to hurry that much.","romaji":"Sonna ni isoganakutemo ii desu yo.","zh":""},{"ja":"そんなに難しくない問題だと思います。","en":"I don''t think the problem is that difficult.","romaji":"Sonna ni muzukashikunai mondai da to omoimasu.","zh":""},{"ja":"彼女はそんなに背が高くありません。","en":"She is not that tall.","romaji":"Kanojo wa sonna ni se ga takaku arimasen.","zh":""},{"ja":"そんなにたくさん食べる必要はないと思う。","en":"I don''t think there''s a need to eat so much.","romaji":"Sonna ni takusan taberu hitsuyou wa nai to omou.","zh":""}]',replace('**Short**: Expresses ''not so much'', ''not that'', or ''not so ~''.\n\n**Formation**: そんなに + Verb-negation, そんなに + Adjective-negation\n\n**Long**: The grammar point そんなに is an adverb used to express that something is not as extreme as described or not to that extent. It is often translated as ''not so much'', ''not that'', or ''not so ~''. It is commonly followed by a negative form of a verb or adjective.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tara_ii','～たらいい',NULL,NULL,'N4','[]','[{"ja":"もっと勉強したらいいですよ。","en":"It would be good if you studied more.","romaji":"Motto benkyou shitara ii desu yo.","zh":""},{"ja":"雨が止んだらいいな。","en":"I hope the rain stops.","romaji":"Ame ga yandara ii na.","zh":""},{"ja":"早く元気になったらいいですね。","en":"It would be good if you got well soon.","romaji":"Hayaku genki ni nattara ii desu ne.","zh":""},{"ja":"彼に連絡したらいいと思います。","en":"I think it would be good if you contacted him.","romaji":"Kare ni renraku shitara ii to omoimasu.","zh":""}]',replace('**Short**: Expressing a desire or suggestion for a particular outcome; ''it would be good if'', ''should'', ''I hope''.\n\n**Formation**: Verb-casual-past + たらいい\n\n**Long**: The ～たらいい grammar point is used to express a desire, suggestion, or hope for a particular outcome. It can be translated as ''it would be good if'', ''should'', or ''I hope'' in English. The formation is simple, and it is used with verbs in their casual past tense form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tara_ikaga_desu_ka','～たら いかがですか',NULL,NULL,'N4','[]','[{"ja":"図書館に行ったらいかがですか。","en":"How about going to the library?","romaji":"Toshokan ni ittara ikaga desu ka.","zh":""},{"ja":"寒かったらカーディガンを着るのはいかがですか。","en":"How about wearing a cardigan if it''s cold?","romaji":"Samukattara kaadigan wo kiru no wa ikaga desu ka.","zh":""},{"ja":"部屋が暗かったら照明を付けるのはいかがですか。","en":"What if you turn on the light if the room is dark?","romaji":"Heya ga kurakattara shoumei wo tsukeru no wa ikaga desu ka.","zh":""},{"ja":"自分の意見だったら他人に聞くのはいかがですか。","en":"How about asking others if it''s your own opinion?","romaji":"Jibun no iken dattara tanin ni kiku no wa ikaga desu ka.","zh":""}]',replace('**Short**: Making polite suggestions; ''how about if'', ''what if'', ''it would be good if''.\n\n**Formation**: Verb-casual, past + たら いかがですか, い-Adjective + かったら いかがですか, な-Adjective + だったら いかがですか, Noun + だったら いかがですか\n\n**Long**: The ～たら いかがですか grammar point is used to make polite suggestions, ask for opinions, or imply that something would be good or desirable if the condition is met. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tara_doudesuka','～たら どうですか',NULL,NULL,'N4','[]','[{"ja":"スキーに行ったらどうですか？","en":"How about going skiing?","romaji":"Sukii ni ittara doudesuka?","zh":""},{"ja":"少し休んだらどうですか？","en":"What if you take a little break?","romaji":"Sukoshi yasundara doudesuka?","zh":""},{"ja":"この本を読んだらどうですか？","en":"Why don''t you read this book?","romaji":"Kono hon wo yondara doudesuka?","zh":""},{"ja":"タクシーで帰ったらどうですか？","en":"How about going home by taxi?","romaji":"Takushii de kaettara doudesuka?","zh":""}]',replace('**Short**: Express a suggestion or advice; ''what if'', ''how about'', ''why don''t you''.\n\n**Formation**: Verb-た form + ら どうですか\n\n**Long**: The ～たら どうですか grammar point is used to make a suggestion or give advice to someone. It can be translated as ''what if'', ''how about'', or ''why don''t you'' in English. This structure is used with the た-form of verbs to make a gentle, polite suggestion.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tari_tari','～たり～たり',NULL,NULL,'N4','[]','[{"ja":"週末は映画を観たり、本を読んだりする。","en":"On weekends, I do things like watching movies and reading books.","romaji":"Shuumatsu wa eiga wo mitari, hon wo yondari suru.","zh":""},{"ja":"彼女は料理が上手だったり、歌がうまかったりする。","en":"She is good at things like cooking and singing.","romaji":"Kanojo wa ryouri ga jouzu dattari, uta ga umakattari suru.","zh":""},{"ja":"このリゾートではスキーをしたり、温泉に入ったりできる。","en":"At this resort, you can do things like skiing and going to hot springs.","romaji":"Kono rizooto de wa sukii wo shitari, onsen ni haittari dekiru.","zh":""},{"ja":"この地域の天気は暑かったり、寒かったりする。","en":"The weather in this area can be hot or cold.","romaji":"Kono chiiki no tenki wa atsukattari, samukattari suru.","zh":""}]',replace('**Short**: Used to list multiple actions or states; ''doing things like'', ''and so on'', ''etc.''\n\n**Formation**: Verb-ta + り + next verb-ta + り, い-Adjective + かったり + next verb-ta + り, な-Adjective + だったり + next verb-ta + り, Noun + だったり + next verb-ta + り\n\n**Long**: The ～たり～たり grammar point is used to list two or more actions or states, without specifying their order or importance. It implies that these actions or states are representative examples, and there may be others. This construction is useful for describing general or habitual actions.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_darou','～だろう',NULL,NULL,'N4','[]','[{"ja":"明日は晴れるだろう。","en":"It will probably be sunny tomorrow.","romaji":"Ashita wa hareru darou.","zh":""},{"ja":"彼は忙しいだろう。","en":"He is probably busy.","romaji":"Kare wa isogashii darou.","zh":""},{"ja":"この本は面白いだろう。","en":"This book is probably interesting.","romaji":"Kono hon wa omoshiroi darou.","zh":""},{"ja":"彼女は先生だろう。","en":"She is probably a teacher.","romaji":"Kanojo wa sensei darou.","zh":""}]',replace('**Short**: Express probability, likelihood or certainty; ''probably'', ''maybe'', ''I think''.\n\n**Formation**: Verb-casual + だろう, い-Adjective (drop い) + だろう, な-Adjective + だろう, Noun + だろう\n\n**Long**: The ～だろう grammar point is used to express probability, likelihood, or certainty about a situation or event. It can be translated as ''probably'', ''maybe'', or ''I think'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tte_iu','～っていう',NULL,NULL,'N4','[]','[{"ja":"ピザっていう料理が大好きです。","en":"I love the dish called pizza.","romaji":"Piza tte iu ryouri ga daisuki desu.","zh":""},{"ja":"彼っていう男性はすごく面白いです。","en":"That man (called ‘kare’) is really interesting.","romaji":"Kare tte iu dansei wa sugoku omoshiroi desu.","zh":""},{"ja":"この映画っていうのは本当に感動的だよ。","en":"This movie, I mean, is really touching.","romaji":"Kono eiga tte iu no wa hontou ni kandouteki da yo.","zh":""},{"ja":"彼女が言っているっていう店はここではない。","en":"The store she''s talking about, I mean, is not here.","romaji":"Kanojo ga itte iru tte iu mise wa koko de wa nai.","zh":""}]',replace('**Short**: Used to quote, define, or specify a noun.\n\n**Formation**: Noun/Adjective/Verb + っていう + Noun\n\n**Long**: The ～っていう grammar point is used for quoting, defining, or specifying a noun. It can be translated as ''called'', ''that is to say'', or ''I mean'' in English. This expression is similar to ～という, but it is more casual and commonly used in spoken conversations.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_de','～で',NULL,NULL,'N4','[]','[{"ja":"私は自転車で学校に行きます。","en":"I go to school by bicycle.","romaji":"Watashi wa jitensha de gakkou ni ikimasu.","zh":""},{"ja":"彼は日本語で手紙を書いた。","en":"He wrote a letter in Japanese.","romaji":"Kare wa nihongo de tegami wo kaita.","zh":""},{"ja":"鉛筆で絵を描きました。","en":"I drew a picture with a pencil.","romaji":"Enpitsu de e wo kakimashita.","zh":""},{"ja":"レストランで昼食を食べました。","en":"I had lunch at a restaurant.","romaji":"Resutoran de chuushoku wo tabemashita.","zh":""}]',replace('**Short**: Indicates the means, method, or place.\n\n**Formation**: Noun + ～で\n\n**Long**: The ～で grammar point is used to indicate the means or method used to perform an action, or to specify the place where an action took place. It is typically used with verbs and comes after a noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_deshou','～でしょう',NULL,NULL,'N4','[]','[{"ja":"明日は晴れでしょう。","en":"It will probably be sunny tomorrow.","romaji":"Ashita wa hare deshou.","zh":""},{"ja":"彼は元気でしょう。","en":"He is probably fine.","romaji":"Kare wa genki deshou.","zh":""},{"ja":"この本は面白いでしょう。","en":"This book is probably interesting.","romaji":"Kono hon wa omoshiroi deshou.","zh":""},{"ja":"彼女は医者でしょう。","en":"She is probably a doctor.","romaji":"Kanojo wa isha deshou.","zh":""}]',replace('**Short**: A conjecture or probability; ''probably'', ''I think'', ''it seems''.\n\n**Formation**: Verb-ますstem + でしょう, い-Adjective + でしょう, な-Adjective + でしょう, Noun + でしょう\n\n**Long**: The ～でしょう grammar point is used to indicate a conjecture or probability. It can be translated as ''probably'', ''I think'', or ''it seems'' in English. It can be used with verbs, い-adjectives, な-adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_wa_ikenai','～てはいけない',NULL,NULL,'N4','[]','[{"ja":"公園でたばこを吸ってはいけない。","en":"You must not smoke in the park.","romaji":"Kouen de tabako o sutte wa ikenai.","zh":""},{"ja":"ここで写真を撮ってはいけない。","en":"You cannot take pictures here.","romaji":"Koko de shashin o totte wa ikenai.","zh":""},{"ja":"図書館で大きな声を出してはいけない。","en":"You must not speak loudly in the library.","romaji":"Toshokan de ookina koe o dashite wa ikenai.","zh":""},{"ja":"バスの中で立っている人に席を譲ってはいけない。(Note: Unusual in real life, but grammatically correct.)","en":"You should not give up your seat to someone standing on the bus. (Note: Odd in actual social context, but valid grammar.)","romaji":"Basu no naka de tatteiru hito ni seki o yuzutte wa ikenai.","zh":""}]',replace('**Short**: Expresses prohibition; ''must not'', ''cannot''.\n\n**Formation**: Verb-て-form + はいけない\n\n**Long**: The ～てはいけない grammar point is used to express strict prohibition or something that must not be done. It can be translated as ''must not'', ''cannot'', or ''should not'' in English. It is formed by adding て-form of a verb followed by はいけない.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_temo_ii','～てもいい',NULL,NULL,'N4','[]','[{"ja":"ここで写真を撮ってもいいですか。","en":"Is it okay to take a photo here?","romaji":"Koko de shashin wo tottemo ii desu ka?","zh":""},{"ja":"このリンゴを食べてもいいですか。","en":"May I eat this apple?","romaji":"Kono ringo wo tabetemo ii desu ka.","zh":""},{"ja":"試験が終わったら、帰ってもいいです。","en":"You can go home after the exam is over.","romaji":"Shiken ga owattara, kaettemo ii desu.","zh":""},{"ja":"今夜友達と遊んでもいい。","en":"It''s okay to play with friends tonight.","romaji":"Kon''ya tomodachi to asondemo ii.","zh":""}]',replace('**Short**: To give or ask permission; ''it''s okay to'', ''may'', ''can''.\n\n**Formation**: Verb-て form + もいい\n\n**Long**: The ～てもいい grammar point is used to give or ask for permission to do something. It can be translated as ''it''s okay to'', ''may'', or ''can'' in English. The formation is derived by adding てもいい after the て-form of a verb.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_mo_demo','～ても/でも',NULL,NULL,'N4','[]','[{"ja":"雨が降っても、学校に行きます。","en":"Even if it rains, I will go to school.","romaji":"Ame ga futte mo, gakkou ni ikimasu.","zh":""},{"ja":"この部屋が汚くても、掃除しないつもりです。","en":"Even if this room is dirty, I don''t intend to clean it.","romaji":"Kono heya ga kitanakute mo, souji shinai tsumori desu.","zh":""},{"ja":"その映画が面白くなくても、見ます。","en":"Even if that movie is not interesting, I will watch it.","romaji":"Sono eiga ga omoshirokunakute mo, mimasu.","zh":""},{"ja":"彼女が病気でも、働きます。","en":"Even if she is sick, she will work.","romaji":"Kanojo ga byouki demo, hatarakimasu.","zh":""}]',replace('**Short**: Expresses ''even if'' or ''even though''; used to convey contradiction or contrast.\n\n**Formation**: Verb-て-form + も, い-Adjective (-い) + くても, な-Adjective + でも, Noun + でも\n\n**Long**: The ～ても/でも grammar point is used to express ''even if'' or ''even though'' in a sentence, showing the idea of contradiction or contrast. The formation of ても differs depending on whether it is used with a verb, い-adjective, or な-adjective. For nouns, でも is used.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_ii','～といい',NULL,NULL,'N4','[]','[{"ja":"明日晴れるといいね。","en":"I hope it will be sunny tomorrow.","romaji":"Ashita hareru to ii ne.","zh":""},{"ja":"この試験に合格するといい。","en":"I hope to pass this exam.","romaji":"Kono shiken ni goukaku suru to ii.","zh":""},{"ja":"彼が元気だといいな。","en":"I hope he is doing well.","romaji":"Kare ga genki da to ii na.","zh":""},{"ja":"そのレストランが美味しいといいですね。","en":"It would be nice if that restaurant is delicious.","romaji":"Sono resutoran ga oishii to ii desu ne.","zh":""}]',replace('**Short**: Express a wish or hope; ''I hope'', ''it would be good if''.\n\n**Formation**: Verb-casual + といい, い-Adjective + といい, な-Adjective + だといい, Noun + だといい\n\n**Long**: The ～といい grammar point is used to express a wish or hope for a certain situation or outcome. It can be translated as ''I hope'', ''it would be good if'', or ''it would be nice if'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_iu_noun','～という (〜to iu) Noun',NULL,NULL,'N4','[]','[{"ja":"彼は日本語が流暢なアメリカ人という人です。","en":"He is an American who speaks fluent Japanese.","romaji":"Kare wa nihongo ga ryuuchou na amerikajin to iu hito desu.","zh":""},{"ja":"昨日、美味しかったというケーキを食べました。","en":"Yesterday, I ate a cake that was said to be delicious.","romaji":"Kinou, oishikatta to iu keeki wo tabemashita.","zh":""},{"ja":"有名な歌手という彼女は、たくさんのファンがいます。","en":"She, who is called a famous singer, has many fans.","romaji":"Yuumei na kashu to iu kanojo wa, takusan no fan ga imasu.","zh":""},{"ja":"環境に優しいという製品が人気があります。","en":"Products that are said to be environmentally friendly are popular.","romaji":"Kankyou ni yasashii to iu seihin ga ninki ga arimasu.","zh":""}]',replace('**Short**: Used to define or explain a noun more specifically.\n\n**Formation**: Noun + という + Noun, な-Adjective + という + Noun, Adjectival Verb + という + Noun\n\n**Long**: The ～という grammar point is used to define or explain a noun more specifically. It is often translated as ''called'', ''named'', or ''that is to say'' in English. It can be used with nouns, な-adjectives, and adjectival verbs.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dou_iu_noun','どういう Noun',NULL,NULL,'N4','[]','[{"ja":"どういう仕事をしていますか？","en":"What kind of work do you do?","romaji":"Dou iu shigoto wo shite imasu ka?","zh":""},{"ja":"どういう映画が好きですか？","en":"What kind of movies do you like?","romaji":"Dou iu eiga ga suki desu ka?","zh":""},{"ja":"どういう服を着たいですか？","en":"What kind of clothes do you want to wear?","romaji":"Dou iu fuku wo kitai desu ka?","zh":""},{"ja":"どういう理由で遅れましたか？","en":"What sort of reason caused you to be late?","romaji":"Dou iu riyuu de okuremashita ka?","zh":""}]',replace('**Short**: Asking for clarification or more information about a noun; ''what kind of'', ''what sort of''.\n\n**Formation**: どういう + Noun\n\n**Long**: The どういう Noun grammar point is used to ask for more information or clarification about a specific noun. It can be translated as ''what kind of'' or ''what sort of'' in English. The formation is simply using どういう followed by the noun in question.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_omou','～と思う',NULL,NULL,'N4','[]','[{"ja":"明日晴れると思います。","en":"I think it will be sunny tomorrow.","romaji":"Ashita hareru to omoimasu.","zh":""},{"ja":"この映画は面白いと思う。","en":"I think this movie is interesting.","romaji":"Kono eiga wa omoshiroi to omou.","zh":""},{"ja":"彼は親切だと思います。","en":"I think he is kind.","romaji":"Kare wa shinsetsu da to omoimasu.","zh":""},{"ja":"鈴木さんは先生だと思う。","en":"I think Suzuki-san is a teacher.","romaji":"Suzuki-san wa sensei da to omou.","zh":""}]',replace('**Short**: Express one''s thoughts or opinions; ''I think'', ''I believe''.\n\n**Formation**: Verb-casual + と思う, い-Adjective + と思う, な-Adjective + だと思う, Noun + だと思う\n\n**Long**: The ～と思う grammar point is used to express one''s thoughts or opinions on a particular subject or situation. It can be translated as ''I think'' or ''I believe'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_iu_n4','～という',NULL,NULL,'N4','[]','[{"ja":"彼は「好きだ」と言った。","en":"He said ''I like you''.","romaji":"Kare wa ''suki da'' to itta.","zh":""},{"ja":"その映画は面白いという評判があります。","en":"The movie has a reputation for being interesting.","romaji":"Sono eiga wa omoshiroi to iu hyouban ga arimasu.","zh":""},{"ja":"日本には富士山という高い山があります。","en":"In Japan, there is a tall mountain called Mount Fuji.","romaji":"Nihon ni wa Fujisan to iu takai yama ga arimasu.","zh":""},{"ja":"彼女は難しい仕事をしているという話です。","en":"I heard she is doing a difficult job.","romaji":"Kanojo wa muzukashii shigoto o shiteiru to iu hanashi desu.","zh":""}]',replace('**Short**: Used to quote, express hearsay or define something.\n\n**Formation**: Verb-casual + という, い-Adjective + という, な-Adjective + という, Noun + という\n\n**Long**: The ～という grammar point is used to quote someone''s words, express something you heard or read from someone else, or define and clarify the subject. It can be translated as ''called'', ''that'', or ''it is said''. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nai_to_ikenai','～ないといけない',NULL,NULL,'N4','[]','[{"ja":"明日試験があるから、今夜勉強しないといけない。","en":"I have an exam tomorrow, so I have to study tonight.","romaji":"Ashita shiken ga aru kara, kon''ya benkyou shinai to ikenai.","zh":""},{"ja":"９時に出発しないといけない。","en":"We must leave at 9 o''clock.","romaji":"Ku-ji ni shuppatsu shinai to ikenai.","zh":""},{"ja":"風邪をひかないように、手をよく洗わないといけない。","en":"To avoid catching a cold, we have to wash our hands well.","romaji":"Kaze o hikanai you ni, te o yoku arawanai to ikenai.","zh":""},{"ja":"この仕事は明日までに終わらないといけない。","en":"This work must be finished by tomorrow.","romaji":"Kono shigoto wa ashita made ni owaranai to ikenai.","zh":""}]',replace('**Short**: Express a necessity; ''must'', ''have to'', ''need to''.\n\n**Formation**: Verb-negative + といけない\n\n**Long**: The ～ないといけない grammar point is used to express a sense of necessity or obligation, similar to ''must'', ''have to'', or ''need to'' in English. This structure is formed by using the negative form of the verb (ending in ない) followed by といけない.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nakya_ikenai','～なきゃいけない',NULL,NULL,'N4','[]','[{"ja":"明日までに宿題を終わらなきゃいけない。","en":"I have to finish my homework by tomorrow.","romaji":"Ashita made ni shukudai wo owaranakya ikenai.","zh":""},{"ja":"もうすぐ出かけるから、急いで準備しなきゃいけない。","en":"We''re leaving soon, so I have to hurry and get ready.","romaji":"Mou sugu dekakeru kara, isoide junbi shinakya ikenai.","zh":""},{"ja":"このプロジェクトは来週提出しなきゃいけない。","en":"I must submit this project by next week.","romaji":"Kono purojekuto wa raishuu teishutsu shinakya ikenai.","zh":""},{"ja":"電車に乗る前に、切符を買わなきゃいけない。","en":"I have to buy a ticket before getting on the train.","romaji":"Densha ni noru mae ni, kippu wo kawanakya ikenai.","zh":""}]',replace('**Short**: Express a necessity or obligation; ''must'', ''have to''.\n\n**Formation**: Verb-casual (negative form without い) + なきゃいけない\n\n**Long**: The ～なきゃいけない grammar point is used to express a sense of necessity or obligation, similar to saying ''must'' or ''have to'' in English. It is a casual and more colloquial form of the ～なければいけない grammar point. The formation is different for verbs, but it is not used with い-adjectives, な-adjectives, or nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_naku_cha_ikenai','～なくちゃいけない',NULL,NULL,'N4','[]','[{"ja":"仕事に行かなくちゃいけないので、早起きしなければなりません。","en":"I have to go to work, so I must wake up early.","romaji":"Shigoto ni ikanakucha ikenai node, hayaoki shinakereba narimasen.","zh":""},{"ja":"試験があるから、勉強しなくちゃいけません。","en":"I have a test, so I must study.","romaji":"Shiken ga aru kara, benkyou shinakucha ikemasen.","zh":""},{"ja":"パスポートを更新しなくちゃいけないので、大使館に行かなければ。","en":"I have to renew my passport, so I need to go to the embassy.","romaji":"Pasupooto wo koushin shinakucha ikenai node, taishikan ni ikanakereba.","zh":""},{"ja":"今日はお金を払わなくちゃいけないから、銀行に行かないと。","en":"I have to pay money today, so I need to go to the bank.","romaji":"Kyou wa okane wo harawanakucha ikenai kara, ginkou ni ikanaito.","zh":""}]',replace('**Short**: Express the obligation to do something; ''have to'', ''must'', ''need to''.\n\n**Formation**: Verb-ない form (-ない ending is dropped) + なくちゃいけない\n\n**Long**: The ～なくちゃいけない grammar point is used to express that there is an obligation or necessity to do something. It can be translated as ''have to'', ''must'', or ''need to'' in English. This grammar point is mainly used with verbs.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nakute_wa_ikenai','～なくてはいけない',NULL,NULL,'N4','[]','[{"ja":"宿題をしなくてはいけない。","en":"I have to do my homework.","romaji":"Shukudai o shinakute wa ikenai.","zh":""},{"ja":"この手紙を明日までに出さなくてはいけない。","en":"I must send this letter by tomorrow.","romaji":"Kono tegami o ashita made ni dasanakute wa ikenai.","zh":""},{"ja":"食べ物を無駄にしなくてはいけない。","en":"We must not waste food.","romaji":"Tabemono o muda ni shinakute wa ikenai.","zh":""},{"ja":"早退したいが、授業が終わるまで待たなくてはいけない。","en":"I want to leave early, but I have to wait until the class finishes.","romaji":"Soutai shitai ga, jugyou ga owaru made matanakute wa ikenai.","zh":""}]',replace('**Short**: Expresses the necessity or obligation; ''must'', ''have to''.\n\n**Formation**: Verb-negative form + なくてはいけない\n\n**Long**: The ～なくてはいけない grammar point is used to express the necessity or obligation to do something. It can be translated as ''must'' or ''have to'' in English. The formation requires the negative form of a verb and is followed by いけない (cannot go/progress). It indicates that if something is not done, it will be a problem or inappropriate.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nakutemo_ii','～なくてもいい',NULL,NULL,'N4','[]','[{"ja":"コーヒーは飲まなくてもいいです。","en":"You don''t have to drink the coffee.","romaji":"Koohii wa nomanakutemo ii desu.","zh":""},{"ja":"宿題を今日しなくてもいいです。","en":"It''s okay if you don''t do your homework today.","romaji":"Shukudai wo kyou shinakutemo ii desu.","zh":""},{"ja":"すぐに返事をしなくてもいいですよ。","en":"You don''t have to reply immediately.","romaji":"Sugu ni henji wo shinakutemo ii desu yo.","zh":""},{"ja":"全部食べなくてもいいですから、無理しないでください。","en":"You don''t have to eat everything, so please don''t force yourself.","romaji":"Zenbu tabenakutemo ii desu kara, muri shinai de kudasai.","zh":""}]',replace('**Short**: Expresses that something is not necessary to do; ''it''s okay if not'', ''don''t have to''.\n\n**Formation**: Verb-ない-form + てもいい\n\n**Long**: The ～なくてもいい grammar point is used to express that an action or situation is not necessary or required, implying that it''s okay if it does not occur. It can be translated as ''it''s okay if not'' or ''don''t have to'' in English. This grammar is used with verbs.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nakereba_naranai','～なければ ならない',NULL,NULL,'N4','[]','[{"ja":"宿題をやらなければならない。","en":"I have to do my homework.","romaji":"Shukudai wo yaranakereba naranai.","zh":""},{"ja":"明日までにこの本を読まなければならない。","en":"I have to read this book by tomorrow.","romaji":"Ashita made ni kono hon wo yomanakereba naranai.","zh":""},{"ja":"授業に遅れないように、早く起きなければならない。","en":"I have to wake up early so I don''t be late for class.","romaji":"Jugyou ni okurenai you ni, hayaku okinakereba naranai.","zh":""},{"ja":"旅行に行く前に切符を買わなければならない。","en":"I have to buy a ticket before going on a trip.","romaji":"Ryokou ni iku mae ni kippu wo kawanakereba naranai.","zh":""}]',replace('**Short**: Express obligation or necessity; ''must'', ''have to'', ''need to''.\n\n**Formation**: Verb-ない form + なければ ならない\n\n**Long**: The ～なければ ならない grammar point is used to express obligation or necessity. In English, it can be translated as ''must'', ''have to'', or ''need to''. The formation differs depending on whether it is used with a verb. It cannot be used with い-adjectives, な-adjectives or nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni','～に',NULL,NULL,'N4','[]','[{"ja":"母は私にケーキを作りました。","en":"My mother made a cake for me.","romaji":"Haha wa watashi ni keiki wo tsukurimashita.","zh":""},{"ja":"彼女は東京に引っ越しました。","en":"She moved to Tokyo.","romaji":"Kanojo wa Toukyou ni hikkoshimashita.","zh":""},{"ja":"銀行にお金を預けます。","en":"I deposit money in the bank.","romaji":"Ginkou ni okane wo azukemasu.","zh":""},{"ja":"私は７時に起きます。","en":"I wake up at 7 o''clock.","romaji":"Watashi wa shichi ji ni okimasu.","zh":""}]',replace('**Short**: Indicates direction, destination, purpose, or time.\n\n**Formation**: Noun + に\n\n**Long**: The ～に grammar point is one of the most versatile Japanese particles. It is commonly used to indicate the direction or destination of an action, to show the purpose of an action or item, or to specify a point in time. Depending on the context, it can be translated as ''to'', ''at'', ''in'', ''on'', or ''for'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_node','～ので',NULL,NULL,'N4','[]','[{"ja":"明日試験があるので、今晩勉強します。","en":"I will study tonight because there is a test tomorrow.","romaji":"Ashita shiken ga aru node, konban benkyou shimasu.","zh":""},{"ja":"このドレスが高いので、買わないことにします。","en":"I will not buy this dress because it is expensive.","romaji":"Kono doresu ga takai node, kawanai koto ni shimasu.","zh":""},{"ja":"田中さんは病気なので、今日は来ません。","en":"Tanaka-san will not come today since he is sick.","romaji":"Tanaka-san wa byouki na node, kyou wa kimasen.","zh":""},{"ja":"雨が降っているので、外に出ない方がいいですよ。","en":"It is better not to go outside because it is raining.","romaji":"Ame ga futte iru node, soto ni denai hou ga ii desu yo.","zh":""}]',replace('**Short**: Express a reason or a cause for something; ''because'', ''since'', ''so''.\n\n**Formation**: Verb-casual + ので, い-Adjective + ので, な-Adjective + なので, Noun + なので\n\n**Long**: The ～ので grammar point is used to express reason or cause for something. It can be translated as ''because'', ''since'', or ''so'' in English. It is similar to から but is considered more polite and formal. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_no_desu','～のです',NULL,NULL,'N4','[]','[{"ja":"この本は難しいのです。","en":"This book is difficult, you see.","romaji":"Kono hon wa muzukashii no desu.","zh":""},{"ja":"明日は忙しいのです。","en":"The fact is, I am busy tomorrow.","romaji":"Ashita wa isogashii no desu.","zh":""},{"ja":"彼女は英語の先生なのです。","en":"The reason is, she is an English teacher.","romaji":"Kanojo wa eigo no sensei na no desu.","zh":""},{"ja":"私は風邪なのです。","en":"Actually, I’ve got a cold.","romaji":"Watashi wa kaze na no desu.","zh":""}]',replace('**Short**: Provides an explanation or gives background information; ''the fact is'', ''the reason is'', ''actually''.\n\n**Formation**: Verb-casual + のです, い-Adjective + のです, な-Adjective + なのです, Noun + なのです\n\n**Long**: The ～のです grammar point is used to provide an explanation or give background information on a situation, often used when there is a need to justify or clarify one''s statement. It can be translated as ''the fact is'', ''the reason is'', or ''actually'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_no_ni','～のに',NULL,NULL,'N4','[]','[{"ja":"遅刻したのに、先生は怒らなかった。","en":"Even though I was late, the teacher didn''t get angry.","romaji":"Chikoku shita no ni, sensei wa okoranakatta.","zh":""},{"ja":"彼は疲れているのに、まだ働いています。","en":"Despite being tired, he is still working.","romaji":"Kare wa tsukarete iru no ni, mada hataraite imasu.","zh":""},{"ja":"勉強するのに静かな場所が必要です。","en":"In order to study, I need a quiet place.","romaji":"Benkyou suru no ni, shizukana basho ga hitsuyou desu.","zh":""},{"ja":"健康のために毎日運動するのに、うちでヨガをしている。","en":"In order to exercise for my health every day, I do yoga at home.","romaji":"Kenkou no tame ni mainichi undou suru no ni, uchi de yoga wo shite iru.","zh":""}]',replace('**Short**: Used to express contrast between expectation and reality, or to indicate a purpose for doing something\n\n**Formation**: Verb-casual + のに, い-Adjective + のに, な-Adjective + なのに, Noun + なのに\n\n**Long**: The ～のに grammar point has two main usages. The first is to express contrast between an expectation and reality, with translations like ''even though'', ''despite'' or ''in spite of'' in English. The second is to indicate a purpose for doing something, translated as ''in order to'' or ''for the purpose of''. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ba_ii','～ばいい',NULL,NULL,'N4','[]','[{"ja":"もっと勉強すればいい。","en":"You should study more.","romaji":"Motto benkyou sureba ii.","zh":""},{"ja":"お腹が空いたら、何か食べればいい。","en":"If you''re hungry, you should eat something.","romaji":"Onaka ga suita ra, nanika tabereba ii.","zh":""},{"ja":"もっと速く走ればいい。","en":"You should run faster.","romaji":"Motto hayaku hashireba ii.","zh":""},{"ja":"わからなければ、先生に聞けばいい。","en":"If you don''t understand, you should ask the teacher.","romaji":"Wakaranakereba, sensei ni kikeba ii.","zh":""}]',replace('**Short**: Express a suggestion or advice; ''should'', ''it would be good if''.\n\n**Formation**: Verb-ば-form + いい, い-Adjective + ければいい, な-Adjective + であればいい, Noun + であればいい\n\n**Long**: The ～ばいい grammar point is used to express a suggestion, recommendation or advice. It can be translated as ''should'', or ''it would be good if'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_made_n4','～まで',NULL,NULL,'N4','[]','[{"ja":"仕事が終わるまで待っています。","en":"I will wait until work is finished.","romaji":"Shigoto ga owaru made matteimasu.","zh":""},{"ja":"ここから駅まで歩いて10分かかります。","en":"It takes 10 minutes to walk from here to the station.","romaji":"Koko kara eki made aruite juppun kakarimasu.","zh":""},{"ja":"私は彼が成功するまで応援します。","en":"I will support him until he succeeds.","romaji":"Watashi wa kare ga seikou suru made ouen shimasu.","zh":""},{"ja":"彼女は猫まで好きです。","en":"She likes even cats.","romaji":"Kanojo wa neko made suki desu.","zh":""}]',replace('**Short**: Indicates extent, ''until'', ''up to'', ''as far as'', ''even''.\n\n**Formation**: Verb + まで, い-Adjective + まで, な-Adjective + まで, Noun + まで\n\n**Long**: The ～まで grammar point is used to express extent or range in terms of time, distance, or degree. It can be translated as ''until'', ''up to'', ''as far as'', or ''even'' in English. It is used with verbs, い-adjectives, な-adjectives, or nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_made_ni','～までに',NULL,NULL,'N4','[]','[{"ja":"明日の朝８時までに起きてください。","en":"Please wake up by 8 a.m. tomorrow.","romaji":"Ashita no asa hachiji made ni okite kudasai.","zh":""},{"ja":"来週の金曜日までにレポートを提出してください。","en":"Please submit the report by next Friday.","romaji":"Raishuu no kinyoubi made ni repooto wo teishutsu shite kudasai.","zh":""},{"ja":"彼が帰るまでに料理を終わらせたい。","en":"I want to finish cooking before he comes back.","romaji":"Kare ga kaeru made ni ryouri wo owarasetai.","zh":""},{"ja":"３０分までに駅に着く必要があります。","en":"We need to arrive at the station by 30 minutes (from now).","romaji":"Sanjuppun made ni eki ni tsuku hitsuyou ga arimasu.","zh":""}]',replace('**Short**: Express ''by'' or ''before'' a certain time or action.\n\n**Formation**: Verb-casual + までに, Noun + までに, Time expression + までに\n\n**Long**: The ～までに grammar point is used to indicate that something must be completed or occurs by a certain time or before a specific action. It can be used with verbs, nouns, and time expressions.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mama_n4','～まま',NULL,NULL,'N4','[]','[{"ja":"ドアを開けたまま出かけてしまった。","en":"I accidentally left with the door open.","romaji":"Doa o aketa mama dekakete shimatta.","zh":""},{"ja":"彼は目覚まし時計を止めたまま寝てしまった。","en":"He fell asleep with the alarm clock stopped.","romaji":"Kare wa mezamashi dokei o tometa mama nete shimatta.","zh":""},{"ja":"その部屋はきれいなままにしておいてください。","en":"Please keep the room clean.","romaji":"Sono heya wa kirei na mama ni shite oite kudasai.","zh":""},{"ja":"彼女は子供のままの心を持っている。","en":"She has the heart of a child.","romaji":"Kanojo wa kodomo no mama no kokoro o motte iru.","zh":""}]',replace('**Short**: Express ''as it is'', ''while'' or ''unchanged state''.\n\n**Formation**: Verb-てform + いる+ まま, Adjective (い & な) + まま, Noun + のまま\n\n**Long**: The ～まま grammar point is used to express a state or condition that remains unchanged or continues, often translated as ''as it is'', ''while'', or ''unchanged''. It can be used with verbs and adjectives to show that something remains in a certain state or condition.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mitai_da_n4','～みたいだ',NULL,NULL,'N4','[]','[{"ja":"彼女が病気のみたいだ。","en":"She seems to be sick.","romaji":"Kanojo ga byouki no mitai da.","zh":""},{"ja":"このドレスは高いみたいだ。","en":"This dress seems to be expensive.","romaji":"Kono doresu wa takai mitai da.","zh":""},{"ja":"あの人は有名人みたいだ。","en":"That person looks like a celebrity.","romaji":"Ano hito wa yuumeijin mitai da.","zh":""},{"ja":"彼は今忙しいみたいだ。","en":"It seems he is busy right now.","romaji":"Kare wa ima isogashii mitai da.","zh":""}]',replace('**Short**: Indicates similarity, resemblance or ''like''; ''it seems'', ''appears'', ''looks like''.\n\n**Formation**: Verb-casual + みたいだ, い-Adjective + みたいだ, な-Adjective + みたいだ, Noun + みたいだ\n\n**Long**: The ～みたいだ grammar point is used to express that something appears, seems or resembles something else. It can be used with nouns, verbs, い-adjectives, and な-adjectives. It can be translated as ''it seems'', ''appears'', or ''looks like'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mo_n4','～も',NULL,NULL,'N4','[]','[{"ja":"私もお寿司が好きです。","en":"I also like sushi.","romaji":"Watashi mo osushi ga suki desu.","zh":""},{"ja":"彼女は英語も日本語も話せます。","en":"She can speak both English and Japanese.","romaji":"Kanojo wa eigo mo nihongo mo hanasemasu.","zh":""},{"ja":"その映画は面白いし、彼も見たいと言っています。","en":"That movie is interesting, and he also said he wants to see it.","romaji":"Sono eiga wa omoshiroi shi, kare mo mitai to itteimasu.","zh":""},{"ja":"今日は寒いです。明日も寒いでしょう。","en":"It is cold today. It will probably be cold tomorrow as well.","romaji":"Kyou wa samui desu. Ashita mo samui deshou.","zh":""}]',replace('**Short**: Indicates ''also'', ''too'', or ''as well''.\n\n**Formation**: Verb-casual + も, い-Adjective + も, な-Adjective + も, Noun + も\n\n**Long**: The ～も grammar point is used to express that something is also true, or to add some additional information to the previous statement. It can be translated as ''also'', ''too'', or ''as well'' in English. The grammar point can be used with verbs, adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_you_da','～ようだ',NULL,NULL,'N4','[]','[{"ja":"彼は元気がないようだ。","en":"He seems to be lacking energy.","romaji":"Kare wa genki ga nai you da.","zh":""},{"ja":"この料理は美味しいようだ。","en":"This dish seems to be delicious.","romaji":"Kono ryouri wa oishii you da.","zh":""},{"ja":"彼女は有名人のようだ。","en":"She seems like a famous person.","romaji":"Kanojo wa yuumeijin no you da.","zh":""},{"ja":"この部屋は図書館のようだ。","en":"This room looks like a library.","romaji":"Kono heya wa toshokan no you da.","zh":""}]',replace('**Short**: Expresses appearance, similarity or inference; ''it seems'', ''it looks like'', ''it appears''.\n\n**Formation**: Verb-て form + ようだ, い-Adjective (drop い) + ようだ, な-Adjective + のようだ, Noun + のようだ\n\n**Long**: The ～ようだ grammar point is used to express appearance, similarity or inference about a situation or action. It can be translated as ''it seems'', ''it looks like'', or ''it appears'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_n_desu','～んです',NULL,NULL,'N4','[]','[{"ja":"遅れたんですが、電車が遅れました。","en":"I was late because the train was delayed.","romaji":"Okuretan desuga, densha ga okuremashita.","zh":""},{"ja":"疲れたんです。","en":"I''m tired (that''s why).","romaji":"Tsukareta n desu.","zh":""},{"ja":"彼は優しいんです。","en":"The thing is, he is kind.","romaji":"Kare wa yasashii n desu.","zh":""},{"ja":"宿題が多いんです。","en":"The reason is I have a lot of homework.","romaji":"Shukudai ga ooi n desu.","zh":""}]',replace('**Short**: Provide an explanation or reason; ''it is that'', ''the thing is'', ''the reason is''.\n\n**Formation**: Verb-casual + んです, い-Adjective + んです, な-Adjective + なんです, Noun + なんです\n\n**Long**: The ～んです grammar point is used to provide an explanation or reason for a situation or action. It can be translated as ''it is that'', ''the thing is'', or ''the reason is'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_b_n4_2','文A。そのうえ 文B。',NULL,NULL,'N4','[]','[{"ja":"このソフトウェアは使いやすい。そのうえ、価格も手ごろだ。","en":"This software is easy to use. Furthermore, the price is reasonable.","romaji":"Kono sofutouea wa tsukaiyasui. Sono ue, kakaku mo tegoro da.","zh":""},{"ja":"彼女は美人だ。そのうえ、頭もいい。","en":"She is beautiful. In addition, she is smart.","romaji":"Kanojo wa bijin da. Sono ue, atama mo ii.","zh":""},{"ja":"この映画は面白い。そのうえ、俳優たちの演技も素晴らしい。","en":"This movie is interesting. Besides, the actors'' performances are also great.","romaji":"Kono eiga wa omoshiroi. Sono ue, haiyuutachi no engi mo subarashii.","zh":""},{"ja":"東京はたくさんの観光スポットがある。そのうえ、美味しいレストランも多い。","en":"Tokyo has many sightseeing spots. In addition, there are many delicious restaurants.","romaji":"Toukyou wa takusan no kankou supotto ga aru. Sono ue, oishii resutoran mo oi.","zh":""}]',replace('**Short**: Shows additional information; ''furthermore'', ''besides'', ''in addition''.\n\n**Formation**: Sentence A + そのうえ + Sentence B + 。\n\n**Long**: This grammar point is used to connect two sentences, where the first sentence 文A provides some information, and the second sentence 文B adds additional related information. It can be translated as ''furthermore'', ''besides'', or ''in addition'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_bun_a_sorede_bun_b','文A。それで 文B',NULL,NULL,'N4','[]','[{"ja":"今日は暑いです。それで、エアコンをつけました。","en":"It is hot today. So, I turned on the air conditioner.","romaji":"Kyou wa atsui desu. Sorede, eakon wo tsukemashita.","zh":""},{"ja":"電車が遅れました。それで、仕事に遅れてしまいました。","en":"The train was delayed. That''s why I was late for work.","romaji":"Densha ga okuremashita. Sorede, shigoto ni okurete shimaimashita.","zh":""},{"ja":"彼は疲れている。それで、早く寝ることにした。","en":"He is tired. Therefore, he decided to go to bed early.","romaji":"Kare wa tsukarete iru. Sorede, hayaku neru koto ni shita.","zh":""},{"ja":"試験に合格しました。それで、友達とお祝いパーティーを開きました。","en":"I passed the exam. So, I held a celebration party with friends.","romaji":"Shiken ni goukaku shimashita. Sorede, tomodachi to oiwai paatii wo hirakimashita.","zh":""}]',replace('**Short**: Used to connect two sentences; ''So'', ''That''s why'', ''Therefore''.\n\n**Formation**: Sentence A。それで Sentence B。\n\n**Long**: The grammar point 文A。それで 文B is used to connect two sentences and show that the second sentence (文B) is a result or consequence of the first sentence (文A). It can be translated as ''so'', ''that''s why'', or ''therefore'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_bun_a_soreni_bun_b','文A。それに 文B',NULL,NULL,'N4','[]','[{"ja":"彼は頭がいい。それに、スポーツも得意だ。","en":"He is smart. In addition, he is good at sports.","romaji":"Kare wa atama ga ii. Soreni, supo-tsu mo tokui da.","zh":""},{"ja":"このケーキはおいしい。それに、値段も安い。","en":"This cake is delicious. Besides, the price is also cheap.","romaji":"Kono keeki wa oishii. Soreni, nedan mo yasui.","zh":""},{"ja":"私は日本語が話せます。それに、韓国語も話せます。","en":"I can speak Japanese. On top of that, I can also speak Korean.","romaji":"Watashi wa nihongo ga hanasemasu. Soreni, kankokugo mo hanasemasu.","zh":""},{"ja":"彼女は美人だ。それに、性格もいい。","en":"She is beautiful. In addition, she has a good personality.","romaji":"Kanojo wa bijin da. Soreni, seikaku mo ii.","zh":""}]',replace('**Short**: Express ''in addition to; besides,'' used to include additional information.\n\n**Formation**: Sentence A + それに + Sentence B\n\n**Long**: This grammar point 文A。それに 文B is used to express an additional statement on what was mentioned earlier. It can be translated as ''in addition to,'' ''besides,'' or ''on top of that,'' in English. It connects two sentences by highlighting supplementary information, opinions, or reasons.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_bun_a_dakara_bun_b','文A。だから 文B',NULL,NULL,'N4','[]','[{"ja":"明日は試験だ。だから今日勉強しなければならない。","en":"Tomorrow is the exam, so I have to study today.","romaji":"Ashita wa shiken da. Dakara kyou benkyou shinakereba naranai.","zh":""},{"ja":"この料理は簡単だ。だから初心者でも作れる。","en":"This dish is simple, so even beginners can make it.","romaji":"Kono ryouri wa kantan da. Dakara shoshinsha demo tsukureru.","zh":""},{"ja":"彼は病気だ。だから今日学校を休む。","en":"He is sick, so he will take a day off from school today.","romaji":"Kare wa byouki da. Dakara kyou gakkou wo yasumu.","zh":""},{"ja":"駅まで遠い。だからタクシーで行ったほうがいい。","en":"The station is far, so it''s better to go by taxi.","romaji":"Eki made tooi. Dakara takushii de itta hou ga ii.","zh":""}]',replace('**Short**: Express reason or cause; ''because'', ''so'', ''therefore''.\n\n**Formation**: Sentence A + だから + Sentence B\n\n**Long**: The 文A。だから 文B grammar point is used to indicate that the reason or cause of an action or event expressed in the second sentence (文B) is a result or consequence of the situation described in the first sentence (文A). It can be translated as ''because'', ''so'', or ''therefore'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_sono_ue_b','A その上 B',NULL,NULL,'N3','[]','[{"ja":"彼は頭が良い。その上、スポーツも得意だ。","en":"He is smart. In addition, he is also good at sports.","romaji":"Kare wa atama ga ii. Sono ue, supootsu mo tokui da.","zh":""},{"ja":"このカフェは雰囲気がいい。その上、料理も美味しい。","en":"This cafe has a nice atmosphere. Besides, the food is delicious.","romaji":"Kono kafe wa fun''iki ga ii. Sono ue, ryouri mo oishii.","zh":""},{"ja":"このアパートは駅に近い。その上、家賃も安い。","en":"This apartment is close to the station. Furthermore, the rent is also cheap.","romaji":"Kono apaato wa eki ni chikai. Sono ue, yachin mo yasui.","zh":""},{"ja":"彼女は仕事ができる。その上、誰とでも仲良くなれる。","en":"She is competent at work. In addition, she can get along with anyone.","romaji":"Kanojo wa shigoto ga dekiru. Sono ue, dare to demo nakayoku nareru.","zh":""}]',replace('**Short**: Used to express ''in addition to'', ''besides'', or ''furthermore'' when adding information or making a suggestion.\n\n**Formation**: A [sentence/clause] + その上 + B [sentence/clause]\n\n**Long**: The grammar point A その上 B is used to connect two statements, where B is an additional piece of information, a suggestion or reason that is related to statement A. The expression can be translated as ''in addition to'', ''besides'', or ''furthermore''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_uchi_ni_n3','～うちに',NULL,NULL,'N3','[]','[{"ja":"若いうちに、いろいろな経験をしておくことが大切です。","en":"It is important to have various experiences while you are young.","romaji":"Wakai uchi ni, iroiro na keiken wo shite oku koto ga taisetsu desu.","zh":""},{"ja":"雨が降っていないうちに、買い物に行こう。","en":"Let''s go shopping before it starts raining.","romaji":"Ame ga futte inai uchi ni, kaimono ni ikou.","zh":""},{"ja":"料理が熱いうちに食べましょう。","en":"Let''s eat while the food is still hot.","romaji":"Ryouri ga atsui uchi ni tabemashou.","zh":""},{"ja":"休みのうちに、旅行の計画を立てたいです。","en":"I want to plan a trip during the holidays.","romaji":"Yasumi no uchi ni, ryokou no keikaku wo tatetai desu.","zh":""}]',replace('**Short**: Express ''while'', ''before'', or ''during'' a certain condition or situation.\n\n**Formation**: Verb-てform + いる + うちに, い-Adjective + い + うちに, な-Adjective + な + うちに\n\n**Long**: The ～うちに grammar point is used to express the idea of doing something while a certain condition or situation is still present or before it changes. It can be translated as ''while'', ''before'', or ''during'' in English. The formation differs depending on whether it is used with a verb, い-adjective, or な-adjective.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_uto_shita','～うとした',NULL,NULL,'N3','[]','[{"ja":"電話に出ようとしたが、相手は切ってしまった。","en":"I tried to answer the phone, but the other person hung up.","romaji":"Denwa ni deyou to shita ga, aite wa kitte shimatta.","zh":""},{"ja":"彼は大声で話そうとしたが、言葉が出なかった。","en":"He tried to speak loudly, but no words came out.","romaji":"Kare wa oogoe de hanasou to shita ga, kotoba ga denakatta.","zh":""},{"ja":"ケーキを作ろうとしたが、材料が足りなかった。","en":"I tried to make a cake, but I didn''t have enough ingredients.","romaji":"Keeki wo tsukurou to shita ga, zairyou ga tarinakatta.","zh":""},{"ja":"彼女は泳ごうとしたが、怖くて水に入れなかった。","en":"She tried to swim, but she was scared and couldn''t get in the water.","romaji":"Kanojo wa oyogou to shita ga, kowakute mizu ni irenakatta.","zh":""}]',replace('**Short**: Express an action someone tried to do but couldn''t; ''tried to'', ''attempted to''.\n\n**Formation**: Verb-う stem + とした\n\n**Long**: The ～うとした grammar point is used to express an action that someone tried to do but couldn''t complete, for various reasons. The formation differs depending on whether it is used with verbs. This grammar point can be translated as ''tried to'' or ''attempted to'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_okagede','～おかげで',NULL,NULL,'N3','[]','[{"ja":"お母さんのおかげで、私は元気になりました。","en":"Thanks to my mother, I became healthy.","romaji":"Okaasan no okagede, watashi wa genki ni narimashita.","zh":""},{"ja":"先生の助けのおかげで、試験に合格しました。","en":"Thanks to the teacher''s help, I passed the exam.","romaji":"Sensei no tasuke no okagede, shiken ni goukaku shimashita.","zh":""},{"ja":"日本語の勉強のおかげで、この映画が理解できました。","en":"Thanks to studying Japanese, I was able to understand this movie.","romaji":"Nihongo no benkyou no okagede, kono eiga ga rikai dekimashita.","zh":""},{"ja":"晴れた天気のおかげで、ピクニックが楽しかったです。","en":"Thanks to the sunny weather, the picnic was enjoyable.","romaji":"Hareta tenki no okagede, pikunikku ga tanoshikatta desu.","zh":""}]',replace('**Short**: Expresses gratitude or shows a positive result due to a certain factor; ''thanks to'', ''because of''.\n\n**Formation**: Verb-casual + おかげで, い-Adjective + おかげで, な-Adjective + だおかげで, Noun + のおかげで\n\n**Long**: The ～おかげで grammar point is used to express gratitude or show a positive outcome resulting from a certain factor, event or person. It can be translated as ''thanks to'' or ''because of'' in English. The formation is straightforward and can be used with verbs, い-adjectives, な-adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kake','～かけ',NULL,NULL,'N3','[]','[{"ja":"彼は食事を食べかけです。","en":"He is in the middle of eating his meal.","romaji":"Kare wa shokuji wo tabekake desu.","zh":""},{"ja":"この本は読みかけで、まだ終わっていません。","en":"This book is partway read, and it is not yet finished.","romaji":"Kono hon wa yomikake de, mada owatteimasen.","zh":""},{"ja":"この部屋は掃除しかけで、まだ片づいていません。","en":"This room is partway cleaned, and it''s not yet tidied up.","romaji":"Kono heya wa soujishikake de, mada kataduiteimasen.","zh":""},{"ja":"プロジェクトは進行しかけで、来週には完了する予定です。","en":"The project is in progress and is scheduled to be completed next week.","romaji":"Purojekuto wa shinkoushikake de, raishuu ni wa kanryou suru yotei desu.","zh":""}]',replace('**Short**: Expresses the meaning of being in the middle of doing something or of something being partway done.\n\n**Formation**: Verb-ますstem + かけ\n\n**Long**: The ～かけ grammar point is used to indicate that something is in the process of being done or is partway completed. This is often used with verbs to describe an action that is not yet finished or is ongoing. The verb should be in its ます-form, and かけ is added after removing the ます.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kanaa_n3','～かなあ',NULL,NULL,'N3','[]','[{"ja":"明日晴れるかなあ。","en":"I wonder if it will be sunny tomorrow.","romaji":"Ashita hareru kanaa.","zh":""},{"ja":"このスープ、辛いかなあ。","en":"I wonder if this soup is spicy.","romaji":"Kono suupu, karai kanaa.","zh":""},{"ja":"彼は静かだかなあ。","en":"I wonder if he is quiet.","romaji":"Kare wa shizuka da kanaa.","zh":""},{"ja":"彼女は医者だかなあ。","en":"I wonder if she is a doctor.","romaji":"Kanojo wa isha da kanaa.","zh":""}]',replace('**Short**: Expressing uncertainty or a mild wish; ''I wonder'', ''maybe''.\n\n**Formation**: Verb-casual + かなあ, い-Adjective + かなあ, な-Adjective + だかなあ, Noun + だかなあ\n\n**Long**: The ～かなあ grammar point is used to express uncertainty or a mild wish. It can be translated as ''I wonder'' or ''maybe'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_naide','～ないで',NULL,NULL,'N3','[]','[{"ja":"会わないでその電話をかけました。","en":"I made the phone call without meeting them.","romaji":"Awanai de sono denwa wo kakemashita.","zh":""},{"ja":"雨が降るのを待たないで、家を出ました。","en":"I left the house without waiting for it to rain.","romaji":"Ame ga furu no wo matanai de, ie wo demashita.","zh":""},{"ja":"誰にも聞かないで、その秘密を知りました。","en":"I found out the secret without asking anyone.","romaji":"Dare ni mo kikanai de, sono himitsu wo shirimashita.","zh":""},{"ja":"遅れることを知らないで、駅に向かいました。","en":"I headed to the station without knowing I was late.","romaji":"Okureru koto wo shiranai de, eki ni mukaimashita.","zh":""}]',replace('**Short**: Express ''without doing ~'' or ''without ~ing''.\n\n**Formation**: Verb-ない-form + で\n\n**Long**: The ～ないで grammar point is used to express the idea of ''without doing something'' or ''without ~ing'' in English. It is formed by attaching the ない-form of the verb and adding で (de). This is used for expressing when an action is not taken or avoided, without interfering with the main action.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kara_ni_kakete_n3','～から～にかけて',NULL,NULL,'N3','[]','[{"ja":"午前８時から午後５時にかけて働いています。","en":"I work from 8 am to 5 pm.","romaji":"Gozen hachiji kara gogo goji ni kakete hataraiteru.","zh":""},{"ja":"この地域は、北から南にかけて狭いです。","en":"This area is narrow from north to south.","romaji":"Kono chiiki wa, kita kara minami ni kakete semai desu.","zh":""},{"ja":"１０歳から２０歳にかけて成長が早いです。","en":"Growth is rapid from 10 to 20 years of age.","romaji":"Jussai kara nijussai ni kakete seichou ga hayai desu.","zh":""},{"ja":"今年の夏は、６月から８月にかけて雨が多かった。","en":"This summer, there was a lot of rain from June to August.","romaji":"Kotoshi no natsu wa, roku gatsu kara hachi gatsu ni kakete ame ga ookatta.","zh":""}]',replace('**Short**: Expresses a range of something, such as time or space; ''from...to'', ''between''.\n\n**Formation**: Noun (time, place, or measure) + から + Noun (time, place or measure) + にかけて\n\n**Long**: The ～から～にかけて grammar point is used to show a range, whether it is a range of time, space, or another measure. It can be translated as ''from...to'' or ''between'' in English. This grammar point is commonly used with nouns indicating time or place.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kawari_ni','～かわりに',NULL,NULL,'N3','[]','[{"ja":"映画を見るかわりに、本を読んだ。","en":"Instead of watching a movie, I read a book.","romaji":"Eiga wo miru kawari ni, hon wo yonda.","zh":""},{"ja":"お酒を飲むかわりに、水を飲んでください。","en":"Please drink water instead of alcohol.","romaji":"Osake wo nomu kawari ni, mizu wo nonde kudasai.","zh":""},{"ja":"犬のかわりに、猫を飼いたいです。","en":"I want to keep a cat instead of a dog.","romaji":"Inu no kawari ni, neko wo kaitai desu.","zh":""},{"ja":"電車を使わないかわりに、自転車で行くことにしました。","en":"I decided to go by bicycle instead of using the train.","romaji":"Densha wo tsukawanai kawari ni, jitensha de iku koto ni shimashita.","zh":""}]',replace('**Short**: In place of; instead of; as a substitute for.\n\n**Formation**: Verb-casual + かわりに, い-Adjective + かわりに, な-Adjective + だかわりに, Noun + だかわりに\n\n**Long**: The ～かわりに grammar point is used to express doing something in place of or as a substitute for something else. It can be translated as ''instead of'', ''in place of'', or ''as a substitute for'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kiri','～きり',NULL,NULL,'N3','[]','[{"ja":"彼は出かけたきり帰ってきません。","en":"He went out and hasn''t come back since.","romaji":"Kare wa dekaketa kiri kaette kimasen.","zh":""},{"ja":"昨日コーヒーを飲んだきり、何も飲まなかった。","en":"I haven''t had anything to drink since the coffee I had yesterday.","romaji":"Kinou koohii wo nonda kiri, nani mo nomanakatta.","zh":""},{"ja":"卒業したきり、彼女に会っていません。","en":"I haven''t seen her since we graduated.","romaji":"Sotsugyou shita kiri, kanojo ni atte imasen.","zh":""},{"ja":"その映画を見たきり、もう一度見たいと思っています。","en":"I''ve wanted to watch that movie again ever since I saw it.","romaji":"Sono eiga wo mita kiri, mou ichido mitai to omotteimasu.","zh":""}]',replace('**Short**: Expresses the idea of ''only'', ''since'', or ''after''.\n\n**Formation**: Verb-past + きり, Verb-てform + きり (less common), Noun + きり\n\n**Long**: The ～きり grammar point is used to express the idea of ''only'', ''since'', or ''after''. It indicates that a certain action or state continues without any change since a specific point in time or after a certain event. It is commonly used with verbs in the past tense, but can also be used with other forms.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kuse_ni_n3','～くせに',NULL,NULL,'N3','[]','[{"ja":"彼はお金持ちのくせに、ケチです。","en":"Even though he''s rich, he''s stingy.","romaji":"Kare wa okanemochi no kuse ni, kechi desu.","zh":""},{"ja":"この部屋が汚いくせに、文句を言うな。","en":"Don''t complain even though this room is dirty. (criticizing)","romaji":"Kono heya ga kitanai kuse ni, monku wo iu na.","zh":""},{"ja":"彼は暇なくせに、手伝ってくれません。","en":"Even though he''s free, he won''t help me.","romaji":"Kare wa hima na kuse ni, tetsudatte kuremasen.","zh":""},{"ja":"彼女は美人なくせに、デートが続かない。","en":"Even though she''s beautiful, she can''t keep a date going.","romaji":"Kanojo wa bijin na kuse ni, deeto ga tsudzukanai.","zh":""}]',replace('**Short**: Used to express criticism or disapproval; ''even though'', ''despite'', ''in spite of''.\n\n**Formation**: Verb-casual + くせに, い-Adjective + くせに, な-Adjective + な/のくせに, Noun + のくせに\n\n**Long**: The ～くせに grammar point is used to express criticism or disapproval in a sentence. It can be translated as ''even though'', ''despite'', or ''in spite of'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kurai','～くらい',NULL,NULL,'N3','[]','[{"ja":"１０分くらい待ちましょう。","en":"Let''s wait for about 10 minutes.","romaji":"Juppun kurai machimashou.","zh":""},{"ja":"彼女はその映画を５回くらい見ました。","en":"She watched that movie about five times.","romaji":"Kanojo wa sono eiga wo go-kai kurai mimashita.","zh":""},{"ja":"その本は面白いくらい難しいです。","en":"That book is so difficult that it’s interesting.","romaji":"Sono hon wa omoshiroi kurai muzukashii desu.","zh":""},{"ja":"この部屋はきれいなくらい広いです。","en":"This room is spacious to the extent of being beautiful.","romaji":"Kono heya wa kirei na kurai hiroi desu.","zh":""}]',replace('**Short**: Expresses an approximate quantity or degree; ''about'', ''approximately'', or ''to the extent of''.\n\n**Formation**: Verb-casual + くらい, い-Adjective + くらい, な-Adjective + くらい, Noun + くらい\n\n**Long**: The ～くらい grammar point is used to express an approximate quantity, degree, or extent. It can be translated as ''about'', ''approximately'', or ''to the extent of'' in English. The formation is straightforward and can be used with verbs, い-adjectives, な-adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kurai_wa_nai','～くらい～は～ない',NULL,NULL,'N3','[]','[{"ja":"週に一度くらいはジムに行かないと。","en":"I have to go to the gym at least once a week.","romaji":"Shuu ni ichido kurai wa jimu ni ikanai to.","zh":""},{"ja":"毎日くらいは歯を磨かないと。","en":"I have to brush my teeth at least every day.","romaji":"Mainichi kurai wa ha wo migakanai to.","zh":""},{"ja":"この問題くらいは解決しないと。","en":"I have to solve at least this problem.","romaji":"Kono mondai kurai wa kaiketsu shinai to.","zh":""},{"ja":"彼女が泣いているくらいなら慰めないと。","en":"If she is crying that much, I should at least try to comfort her.","romaji":"Kanojo ga naite iru kurai nara nagusamenai to.","zh":""}]',replace('**Short**: Express the least one can do; ''at least'', ''the least'', ''no less than''.\n\n**Formation**: Verb-casual (non-past) + くらい + は + Verb-casual (negative), Adjective (non-past) + くらい + は + Adjective (negative)\n\n**Long**: The ～くらい～は～ない grammar point is used to emphasize the minimum expectation in a situation or the least one can do. It can be translated as ''at least'', ''the least'', or ''no less than'' in English. The formation differs depending on whether it is used with a verb or an adjective.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_koso','～こそ',NULL,NULL,'N3','[]','[{"ja":"今日こそ勉強しなければなりません。","en":"Today, of all days, I must study.","romaji":"Kyou koso benkyou shinakereba narimasen.","zh":""},{"ja":"あなたこそ私の一番の友達です。","en":"You are precisely my best friend.","romaji":"Anata koso watashi no ichiban no tomodachi desu.","zh":""},{"ja":"お金がないことこそ幸せの秘訣ではないか。","en":"Isn''t not having money exactly the key to happiness?","romaji":"O-kane ga nai koto koso shiawase no hiketsu de wa nai ka.","zh":""},{"ja":"彼こそまさにプロの歌手のように歌える。","en":"He can sing precisely like a professional singer.","romaji":"Kare koso masani puro no kashu no you ni utaeru.","zh":""}]',replace('**Short**: Emphasizes the importance or uniqueness of something or someone; ''precisely'', ''exactly'', ''it is...'', ''of all...''.\n\n**Formation**: Noun + こそ, (Verb-て + こそ)\n\n**Long**: The ～こそ grammar point is used to emphasize the importance, uniqueness, or the most suitable thing or person in a specific situation. It can be translated as ''precisely'', ''exactly'', or ''it is...'' in English. In practice, it most often appears after a noun (e.g. 今日こそ), or with verbs in the て-form (e.g. 頑張ってこそ).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_koto','～こと',NULL,NULL,'N3','[]','[{"ja":"日本語を話すことができます。","en":"I can speak Japanese.","romaji":"Nihongo wo hanasu koto ga dekimasu.","zh":""},{"ja":"毎日運動することは健康に良いです。","en":"Exercising every day is good for your health.","romaji":"Mainichi undou suru koto wa kenkou ni ii desu.","zh":""},{"ja":"彼はピアノを弾くことが大好きです。","en":"He loves to play the piano.","romaji":"Kare wa piano wo hiku koto ga daisuki desu.","zh":""},{"ja":"映画を見ることに時間を使いたくない。","en":"I don''t want to spend time watching movies.","romaji":"Eiga wo miru koto ni jikan wo tsukai takunai.","zh":""}]',replace('**Short**: Express an action in a nominal (noun-like) form or state fact or experience.\n\n**Formation**: Verb-plain form + こと, Verb-phrase in plain form + こと\n\n**Long**: The ～こと grammar point is used to turn a verb or verb phrase into a noun or noun phrase. This allows the verb to be talked about as a general concept, fact, or experience. The formation varies slightly depending on whether it is used with a verb or a verb phrase.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_koto_da','～ことだ',NULL,NULL,'N3','[]','[{"ja":"毎日運動することだ。","en":"You should exercise every day.","romaji":"Mainichi undou suru koto da.","zh":""},{"ja":"健康のために、野菜をたくさん食べることだ。","en":"For your health, you should eat lots of vegetables.","romaji":"Kenkou no tame ni, yasai wo takusan taberu koto da.","zh":""},{"ja":"勉強しているとき、静かな場所を選ぶことだ。","en":"When studying, you should choose a quiet place.","romaji":"Benkyou shiteiru toki, shizuka na basho wo erabu koto da.","zh":""},{"ja":"辞書を使って、新しい言葉を覚えることだ。","en":"You should use a dictionary to learn new words.","romaji":"Jisho wo tsukatte, atarashii kotoba wo oboeru koto da.","zh":""}]',replace('**Short**: Expresses advice or recommendation; ''should'', ''it is important'', ''it is necessary''.\n\n**Formation**: Verb-ますstem + ことだ, い-Adjective + ことだ, な-Adjective + なことだ, Noun + のことだ\n\n**Long**: The ～ことだ grammar point is used to express a piece of advice or recommendation to someone. It can be translated as ''should'', ''it is important'', or ''it is necessary'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_koto_ni_shite_iru','～ことにしている',NULL,NULL,'N3','[]','[{"ja":"毎日運動することにしている。","en":"I make it a rule to exercise every day.","romaji":"Mainichi undou suru koto ni shite iru.","zh":""},{"ja":"夜遅くまで働かないことにしている。","en":"I make it a rule not to work late into the night.","romaji":"Yoru osoku made hatarakanai koto ni shite iru.","zh":""},{"ja":"食事の後、歯を磨くことにしている。","en":"I always make sure to brush my teeth after meals.","romaji":"Shokuji no ato, ha wo migaku koto ni shite iru.","zh":""},{"ja":"会議には必ず10分前に着くことにしている。","en":"I always make sure to arrive 10 minutes early for meetings.","romaji":"Kaigi ni wa kanarazu juppun mae ni tsuku koto ni shite iru.","zh":""}]',replace('**Short**: Express a personal rule or habit; ''I make it a rule to'', ''I always make sure to''.\n\n**Formation**: Verb-casual + ことにしている\n\n**Long**: The ～ことにしている grammar point is used to express a personal rule, habit, or decision that the speaker has made for themselves. It can be translated as ''I make it a rule to'' or ''I always make sure to'' in English. This grammar point is formed by attaching ことにしている to the casual form of a verb.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_koto_ni_natte_iru_n3','～ことになっている',NULL,NULL,'N3','[]','[{"ja":"この会社では、20時には仕事を終えることになっている。","en":"In this company, it is decided that work will end at 8 pm.","romaji":"Kono kaisha de wa, 20-ji ni shigoto o oeru koto ni natte iru.","zh":""},{"ja":"日本では、18歳以上の人が選挙に投票することになっている。","en":"In Japan, it is decided that people 18 years old and above will vote in elections.","romaji":"Nihon de wa, 18-sai ijou no hito ga senkyo ni touhyou suru koto ni natte iru.","zh":""},{"ja":"学校では、制服を着ることになっている。","en":"At school, it is decided that students will wear uniforms.","romaji":"Gakkou de wa, seifuku o kiru koto ni natte iru.","zh":""},{"ja":"田中さんが今回のプロジェクトリーダーになることになっている。","en":"It is decided that Tanaka will be the project leader this time.","romaji":"Tanaka-san ga konkai no purojekuto riidaa ni naru koto ni natte iru.","zh":""}]',replace('**Short**: Describes something that is decided, arranged, or expected.\n\n**Formation**: Verb-dictionary form + ことになっている\n\n**Long**: The ～ことになっている grammar point is used to express that something has been decided or arranged, or is expected as a rule or custom. It can be translated as ''it is decided that...'', ''it is arranged that...'', or ''it is expected to...'' in English. The formation is used with verbs in their dictionary form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_koto_wa_ga','～ことは…が',NULL,NULL,'N3','[]','[{"ja":"この映画は面白いことは面白いが、ちょっと長すぎる。","en":"This movie may be interesting, but it is a bit too long.","romaji":"Kono eiga wa omoshiroi koto wa omoshiroi ga, chotto naga-sugiru.","zh":""},{"ja":"彼は親切なことは親切だが、少し無口だ。","en":"He may be kind, but he is a bit quiet.","romaji":"Kare wa shinsetsu na koto wa shinsetsu da ga, sukoshi mukuchi da.","zh":""},{"ja":"このゲームは難しいことは難しいが、やめられない。","en":"This game may be difficult, but I can''t stop playing.","romaji":"Kono geemu wa muzukashii koto wa muzukashii ga, yamerarenai.","zh":""},{"ja":"彼女は美しいことは美しいが、ちょっと高飛車だ。","en":"She may be beautiful, but she is a bit arrogant.","romaji":"Kanojo wa utsukushii koto wa utsukushii ga, chotto koubisha da.","zh":""}]',replace('**Short**: Indicates that while something may be true or valid, there is another contrasting point.\n\n**Formation**: Verb-casual + ことは + が, い-Adjective + ことは + が, な-Adjective + だ + ことは + が, Noun + だ + ことは + が\n\n**Long**: The ～ことは…が grammar point is used to express that although something might be true, there is another point or fact that is being contrasted with it. It can be translated as ''it may be true but...'', ''it is that... however...'', etc. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_koto_wa_nai','～ことはない',NULL,NULL,'N3','[]','[{"ja":"お金があるから、無理に貯金することはない。","en":"Since I have enough money, there''s no need to force myself to save.","romaji":"Okane ga aru kara, muri ni chokin suru koto wa nai.","zh":""},{"ja":"この本は簡単だから、辞書を使うことはない。","en":"Since this book is easy, there''s no need to use a dictionary.","romaji":"Kono hon wa kantan dakara, jisho wo tsukau koto wa nai.","zh":""},{"ja":"彼女は海外旅行に行きたくなければ、行くことはない。","en":"If she doesn''t want to go on an overseas trip, she doesn''t have to go.","romaji":"Kanojo wa kaigai ryokou ni ikitakunakereba, iku koto wa nai.","zh":""},{"ja":"寒くなければ、コートを着ることはない。","en":"If it''s not cold, there''s no need to wear a coat.","romaji":"Samukunakereba, kooto wo kiru koto wa nai.","zh":""}]',replace('**Short**: Expresses that something doesn''t need to be done or there''s no occasion to do it; ''don''t have to'', ''not necessary''.\n\n**Formation**: Verb-dictionary form + ことはない, い-Adjective + ことはない, な-Adjective + であることはない, Noun + であることはない\n\n**Long**: The ～ことはない grammar point is used to express that doing something is not necessary, or there''s no occasion to do it. It implies that although a certain action might not be needed, it does not mean it is forbidden. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sa','～さ',NULL,NULL,'N3','[]','[{"ja":"この料理は辛さが強い。","en":"The spiciness of this dish is strong.","romaji":"Kono ryouri wa karasa ga tsuyoi.","zh":""},{"ja":"彼女の美しさは皆に憧れられる。","en":"Her beauty is admired by everyone.","romaji":"Kanojo no utsukushisa wa mina ni akogarerareru.","zh":""},{"ja":"山田さんの親切さで、困っている人を助けてくれる。","en":"Yamada-san''s kindness helps people in trouble.","romaji":"Yamada-san no shinsetsusa de, komatte iru hito wo tasukete kureru.","zh":""},{"ja":"この部屋の広さは十分だと思う。","en":"I think the size of this room is enough.","romaji":"Kono heya no hirosa wa juubun da to omou.","zh":""}]',replace('**Short**: Express the degree or extent of a quality; ''-ness'', ''degree of''.\n\n**Formation**: い-Adjective (drop い) + さ, な-Adjective + さ\n\n**Long**: The ～さ grammar point is used to express the degree or extent of a certain quality or characteristic. It is often translated as ''-ness'' or ''degree of'' in English. The formation differs depending on whether it is used with an い-adjective or a な-adjective.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sae','～さえ',NULL,NULL,'N3','[]','[{"ja":"お金さえあれば、世界中を旅行できる。","en":"If only I have money, I can travel around the world.","romaji":"Okane sae areba, sekaijuu wo ryokou dekiru.","zh":""},{"ja":"彼は英語さえ話せれば、その仕事ができるだろう。","en":"As long as he can speak English, he can do that job.","romaji":"Kare wa eigo sae hanasereba, sono shigoto ga dekiru darou.","zh":""},{"ja":"彼女は頭がいいだけでなく、運動も上手だ。テニスさえできる。","en":"Not only is she smart, she is also good at sports. She can even play tennis.","romaji":"Kanojo wa atama ga ii dake denaku, undou mo jouzu da. Tenisu sae dekiru.","zh":""},{"ja":"明るい場所で本を読むのが好きだ。部屋の電気さえつけなくても大丈夫だ。","en":"I like reading books in bright places. I''m fine even if I don''t turn on the room light.","romaji":"Akarui basho de hon wo yomu no ga suki da. Heya no denki sae tsukenakute mo daijoubu da.","zh":""}]',replace('**Short**: Emphasizes a specific item or action; ''even'', ''if only'', ''as long as''.\n\n**Formation**: Noun + さえ, Verb-casual + さえ, い-Adjective + さえ, な-Adjective + でさえ\n\n**Long**: The ～さえ grammar point is used to emphasize a specific item, person, or action, implying that it alone is sufficient, remarkable, or an exception. It can be translated as ''even'', ''if only'', or ''as long as'' in English. The formation differs slightly depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_shika_nai','～しかない',NULL,NULL,'N3','[]','[{"ja":"この問題を解決する方法は一つしかない。","en":"There is only one way to solve this problem.","romaji":"Kono mondai wo kaiketsu suru houhou wa hitotsu shika nai.","zh":""},{"ja":"彼が出て行ったら、泣くしかない。","en":"If he leaves, there''s nothing else to do but cry.","romaji":"Kare ga dete ittara, naku shika nai.","zh":""},{"ja":"彼女にはあと一月しかない。","en":"She has only one month left.","romaji":"Kanojo ni wa ato ichigatsu shika nai.","zh":""},{"ja":"僕には君を信じるしかない。","en":"I have no choice but to trust you.","romaji":"Boku ni wa kimi wo shinjiru shika nai.","zh":""}]',replace('**Short**: Express the idea of ''only'', ''no other option but'', ''nothing else but''.\n\n**Formation**: Verb-casual + しかない, い-Adjective + しかない, な-Adjective + しかない, Noun + しかない\n\n**Long**: The ～しかない grammar point is used to emphasize that there are no other options or possibilities, and the subject must follow a specified action or state. It can be translated as ''only'', ''no other option but'', or ''nothing else but'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sukoshimonai','すこしも〜ない',NULL,NULL,'N3','[]','[{"ja":"彼はすこしも悲しそうに見えません。","en":"He doesn''t look sad at all.","romaji":"Kare wa sukoshimo kanashisou ni miemasen.","zh":""},{"ja":"この部屋はすこしも寒くない。","en":"This room is not cold at all.","romaji":"Kono heya wa sukoshimo samukunai.","zh":""},{"ja":"彼女はすこしも心配していない。","en":"She is not worried at all.","romaji":"Kanojo wa sukoshimo shinpai shite inai.","zh":""},{"ja":"まったく知らない人と話すのは怖い。","en":"It''s scary to talk to someone I don''t know at all.","romaji":"Mattaku shiranai hito to hanasu no wa kowai.","zh":""}]',replace('**Short**: Express a negative state or action; ''not at all'', ''none whatsoever''.\n\n**Formation**: すこしも + Verb-negative\n\n**Long**: The すこしも〜ない grammar point is used to emphasize a negative state or action, indicating that something does not exist or happen even a little bit. It can be translated as ''not at all'', ''none whatsoever'', or ''not one bit'' in English. This expression is used with negative verbs.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_zu_ni','～ずに',NULL,NULL,'N3','[]','[{"ja":"彼は笑わずに話を聞いていました。","en":"He was listening to the story without laughing.","romaji":"Kare wa warawazu ni hanashi wo kiiteimashita.","zh":""},{"ja":"食べずに寝るのは良くないです。","en":"It''s not good to go to bed without eating.","romaji":"Tabezu ni neru no wa yokunai desu.","zh":""},{"ja":"コーヒーを飲まずに仕事を始めました。","en":"I started working without drinking coffee.","romaji":"Koohii wo nomazu ni shigoto wo hajimemashita.","zh":""},{"ja":"誰にも言わずに出かけました。","en":"I went out without telling anyone.","romaji":"Dare ni mo iwazu ni dekakemashita.","zh":""}]',replace('**Short**: Express ''without doing'' something or ''not doing'' something.\n\n**Formation**: Verb-ない form (Remove ない) + ずに\n\n**Long**: The ～ずに grammar point is used to express the meaning of not doing something or doing an action without doing another action first. It is similar to the negative ないで form (～ないで) but ～ずに is considered slightly more formal.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sei_de','～せいで',NULL,NULL,'N3','[]','[{"ja":"雨のせいで試合が中止になりました。","en":"The game was cancelled because of the rain.","romaji":"Ame no sei de shiai ga chuushi ni narimashita.","zh":""},{"ja":"彼の遅刻のせいで、みんな待たされました。","en":"Everyone had to wait because of his lateness.","romaji":"Kare no chikoku no sei de, minna matasaremashita.","zh":""},{"ja":"病気のせいで休日が台無しになった。","en":"My holiday was ruined due to illness.","romaji":"Byouki no sei de kyuujitsu ga dainashi ni natta.","zh":""},{"ja":"仕事が忙しくて寝不足なせいで、集中できない。","en":"I can''t concentrate because I''m sleep-deprived due to busy work.","romaji":"Shigoto ga isogashikute nebusoku na sei de, shuuchuu dekinai.","zh":""}]',replace('**Short**: Indicates that something or someone caused an unfortunate result.\n\n**Formation**: Verb-casual + せいで, い-Adjective + せいで, な-Adjective + なせいで, Noun + のせいで\n\n**Long**: The ～せいで grammar point is used to express that something or someone is the reason or cause of an unfortunate result or situation. It can be translated as ''because of'' or ''due to'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sete_kudasai','～せてください',NULL,NULL,'N3','[]','[{"ja":"もう一度説明させてください。","en":"Please let me explain it once more.","romaji":"Mou ichido setsumei sasete kudasai.","zh":""},{"ja":"帰らせてください。","en":"Please let me go home.","romaji":"Kaerasete kudasai.","zh":""},{"ja":"その本を見せてください。","en":"Please let me see that book.","romaji":"Sono hon o misete kudasai.","zh":""},{"ja":"ここで待たせてください。","en":"Please let me wait here.","romaji":"Koko de matasete kudasai.","zh":""}]',replace('**Short**: Requesting someone to allow or let you do something (causative request).\n\n**Formation**: Verb-causative (させ) + て + ください\n\n**Long**: The せてください grammar point is used to request permission or ask someone to allow you to do something. It is a polite way of making a request and can be translated as ''please let me...'' or ''please allow me...'' in English. It is formed by using the causative form of the verb (Verb-させる) in the て-form, plus ください (e.g. 帰らせる → 帰らせて → 帰らせてください).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sono_tame_ni','～そのために',NULL,NULL,'N3','[]','[{"ja":"試験に合格するために、毎日勉強しています。そのために、早く寝て早く起きるようにしています。","en":"I study every day to pass the exam. For that reason, I go to bed early and wake up early.","romaji":"Shiken ni goukaku suru tame ni, mainichi benkyou shiteimasu. Sono tame ni, hayaku nete hayaku okiru you ni shiteimasu.","zh":""},{"ja":"健康的な生活を送りたい。そのために、ジムに通って運動しています。","en":"I want to lead a healthy lifestyle. For that reason, I go to the gym and exercise.","romaji":"Kenkouteki na seikatsu wo okuritai. Sono tame ni, jimu ni kayotte undou shiteimasu.","zh":""},{"ja":"環境を守るために、リサイクルに取り組んでいます。そのために、ゴミを分別して捨てています。","en":"I''m working on recycling to protect the environment. Therefore, I separate and dispose of trash properly.","romaji":"Kankyou wo mamoru tame ni, risaikuru ni torikundeimasu. Sono tame ni, gomi wo bunbetsu shite suteteimasu.","zh":""},{"ja":"新しい仕事を見つけたい。そのために、履歴書を書いて応募しています。","en":"I want to find a new job. So, I''m writing my resume and applying.","romaji":"Atarashii shigoto wo mitsuketai. Sono tame ni, rirekisho wo kaite oubo shiteimasu.","zh":""}]',replace('**Short**: For the purpose of; because of; in order to.\n\n**Formation**: Sentence/phrase 1 + そのために + Sentence/phrase 2\n\n**Long**: The ～そのために grammar point is used to convey the purpose or reason behind an action or situation. It can be translated as ''for that reason'', ''for the purpose of'', or ''in order to'' in English. It connects two sentences, where the first sentence gives a goal or reason, and the second sentence shows the resulting action.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sono_kekka','～その結果',NULL,NULL,'N3','[]','[{"ja":"彼女は毎日練習した。その結果、試合に勝った。","en":"She practiced every day. As a result, she won the match.","romaji":"Kanojo wa mainichi renshuu shita. Sono kekka, shiai ni katta.","zh":""},{"ja":"会社が倒産した。その結果、彼は仕事を失った。","en":"The company went bankrupt. As a result, he lost his job.","romaji":"Kaisha ga tousan shita. Sono kekka, kare wa shigoto wo ushinatta.","zh":""},{"ja":"私たちは遅刻した。その結果、電車に乗れなかった。","en":"We were late. As a result, we couldn''t catch the train.","romaji":"Watashitachi wa chikoku shita. Sono kekka, densha ni norenakatta.","zh":""},{"ja":"彼は勉強を怠った。その結果、試験に落ちた。","en":"He neglected his studies. As a result, he failed the exam.","romaji":"Kare wa benkyou wo okotatta. Sono kekka, shiken ni ochita.","zh":""}]',replace('**Short**: Shows the result or consequence of a previous action or situation; ''as a result'', ''in consequence''.\n\n**Formation**: Situation/ACTION 1 + その結果 + RESULT\n\n**Long**: The ～その結果 grammar point is used to show the result, outcome, or consequence of a previous action or situation. It can be translated as ''as a result'', ''in consequence'', or ''therefore'' in English. It is typically placed between two statements to link cause and effect.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sore_to','～それと～',NULL,NULL,'N3','[]','[{"ja":"買い物に行くつもりです。それと、郵便局にも行かなくては。","en":"I plan to go shopping, and I also have to go to the post office.","romaji":"Kaimono ni iku tsumori desu. Sore to, yuubinkyoku ni mo ikanakute wa.","zh":""},{"ja":"今日はタコスを作りました。それと、サラダも作りました。","en":"Today, I made tacos, and I also made a salad.","romaji":"Kyou wa takosu wo tsukurimashita. Sore to, sarada mo tsukurimashita.","zh":""},{"ja":"出かける前に、部屋を掃除してください。それと、ゴミを捨ててください。","en":"Please clean the room before you go out, and also throw away the trash.","romaji":"Dekakeru mae ni, heya wo souji shite kudasai. Sore to, gomi wo sutete kudasai.","zh":""},{"ja":"彼はフランス語が話せます。それと、スペイン語も話せます。","en":"He can speak French, and he can also speak Spanish.","romaji":"Kare wa furansugo ga hanasemasu. Sore to, supeingo mo hanasemasu.","zh":""}]',replace('**Short**: Used to link two or more items; ''and'', ''also''.\n\n**Formation**: Item1 + それと + Item2\n\n**Long**: The ～それと～ grammar point is used to connect two or more items or actions, similar to how ''and'' or ''also'' is used in English. The expression それと can appear at the start of a new sentence or between items in a list to add another point.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sore_tomo','～？それとも～？',NULL,NULL,'N3','[]','[{"ja":"コーヒーを飲む？それとも紅茶を飲む？","en":"Do you want to drink coffee? Or tea?","romaji":"Koohii o nomu? Sore tomo koucha o nomu?","zh":""},{"ja":"この映画は面白い？それともつまらない？","en":"Is this movie interesting? Or is it boring?","romaji":"Kono eiga wa omoshiroi? Sore tomo tsumaranai?","zh":""},{"ja":"彼は日本人だ？それとも外国人だ？","en":"Is he Japanese? Or is he a foreigner?","romaji":"Kare wa nihonjin da? Sore tomo gaikokujin da?","zh":""},{"ja":"寿司を食べに行く？それともラーメンを食べに行く？","en":"Are we going to eat sushi? Or are we going to eat ramen?","romaji":"Sushi o tabe ni iku? Sore tomo raamen o tabe ni iku?","zh":""}]',replace('**Short**: Presents two alternatives or choices; ''or'', ''either...or''.\n\n**Formation**: Verb-casual + ？それとも + Verb-casual + ？, etc.\n\n**Long**: The ～？それとも～？ grammar point is used to present two alternatives or choices in a single sentence. It is similar to ''or'' or ''either...or'' in English. It can be used with verbs, adjectives, or nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dake_shika','～だけしか',NULL,NULL,'N3','[]','[{"ja":"今日は1時間だけしか勉強できなかった。","en":"Today, I could study for only one hour.","romaji":"Kyou wa ichijikan dake shika benkyou dekinakatta.","zh":""},{"ja":"彼はカレーだけしか食べない。","en":"He eats only curry.","romaji":"Kare wa karee dake shika tabenai.","zh":""},{"ja":"田中さんは5人だけしか招待しなかった。","en":"Tanaka only invited five people.","romaji":"Tanaka-san wa gonin dake shika shoutai shinakatta.","zh":""},{"ja":"あのレストランでは野菜だけしか売っていない。","en":"That restaurant sells only vegetables.","romaji":"Ano resutoran de wa yasai dake shika utte inai.","zh":""}]',replace('**Short**: Emphasizes the scarcity or insufficiency of something; ''only'', ''nothing but''.\n\n**Formation**: Noun/Quantity + だけ + しか + Negative Verb\n\n**Long**: The ～だけしか grammar point is used to emphasize that there is nothing except what is mentioned, and it requires a negative verb. It can be translated as ''only'' or ''nothing but'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dakedo','だけど',NULL,NULL,'N3','[]','[{"ja":"試験に合格したけど、まだ勉強しなければならない。","en":"I passed the exam, but I still have to study.","romaji":"Shiken ni goukaku shita kedo, mada benkyou shinakereba naranai.","zh":""},{"ja":"この部屋は広いけど、家賃が高いです。","en":"This room is spacious, but the rent is high.","romaji":"Kono heya wa hiroi kedo, yachin ga takai desu.","zh":""},{"ja":"彼は優しいけど、時々厳しいです。","en":"He is kind, but sometimes strict.","romaji":"Kare wa yasashii kedo, tokidoki kibishii desu.","zh":""},{"ja":"朝ごはんは作りたいけど、時間がない。","en":"I want to make breakfast, but there''s no time.","romaji":"Asagohan wa tsukuritai kedo, jikan ga nai.","zh":""}]',replace('**Short**: Expresses a contrast or contradiction; ''but'', ''however'', ''even though''.\n\n**Formation**: Sentence 1 + だけど + Sentence 2, or Sentence 1 + 。だけど、Sentence 2\n\n**Long**: The だけど grammar point is used to express a contrast or contradiction between two statements. In written or spoken Japanese, だけど is often placed at the start of a new sentence (after a period) to mean ''however''. Within a single sentence, speakers often just say けど without だ.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tate','～たて',NULL,NULL,'N3','[]','[{"ja":"このパンは焼きたてで、まだ温かいです。","en":"This bread is freshly baked and still warm.","romaji":"Kono pan wa yakitate de, mada atatakai desu.","zh":""},{"ja":"作りたてのお弁当が美味しい。","en":"A freshly made bento is delicious.","romaji":"Tsukuritate no obentou ga oishii.","zh":""},{"ja":"洗いたてのシャツはいい匂いがする。","en":"Freshly washed shirts smell nice.","romaji":"Araitate no shatsu wa ii nioi ga suru.","zh":""},{"ja":"彼女は切りたての野菜をサラダに入れました。","en":"She added freshly cut vegetables to the salad.","romaji":"Kanojo wa kiritate no yasai wo sarada ni iremashita.","zh":""}]',replace('**Short**: Indicates an action that has just been completed; ''freshly'', ''just''.\n\n**Formation**: Verb-stem + たて\n\n**Long**: The ～たて grammar point is used to express that an action has just been completed, and the result or condition is still fresh or new. This is often used with verbs like 焼く (bake), 作る (make), or 洗う (wash).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tatoe_temo','～たとえ～ても',NULL,NULL,'N3','[]','[{"ja":"たとえ雨が降っても、出かけましょう。","en":"Even if it rains, let''s go out.","romaji":"Tatoe ame ga futte mo, dekakemashou.","zh":""},{"ja":"たとえ彼が怒っても、本当のことを言いましょう。","en":"Even if he gets angry, let''s tell the truth.","romaji":"Tatoe kare ga okotte mo, hontou no koto wo iimashou.","zh":""},{"ja":"たとえ寒くても、散歩に行きたい。","en":"Even if it''s cold, I want to go for a walk.","romaji":"Tatoe samukute mo, sanpo ni ikitai.","zh":""},{"ja":"たとえ彼が有名であっても、彼には興味がありません。","en":"Even if he''s famous, I''m not interested in him.","romaji":"Tatoe kare ga yuumei de attemo, kare ni wa kyoumi ga arimasen.","zh":""}]',replace('**Short**: Express a condition with ''even if''; ''no matter how''.\n\n**Formation**: たとえ + Verb-casual + ても, たとえ + い-Adjective + くても, たとえ + な-Adjective + であっても, たとえ + Noun + であっても\n\n**Long**: The ～たとえ～ても grammar point is used to express a hypothetical or conditional situation where the outcome remains the same even if the condition is met. It can be translated as ''even if'' or ''no matter how'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ta_tokoro_n3','～たところ',NULL,NULL,'N3','[]','[{"ja":"宿題をしたところ、先生からもう一つ課題が出された。","en":"Just when I finished my homework, the teacher gave us another assignment.","romaji":"Shukudai wo shita tokoro, sensei kara mou hitotsu kadai ga dasareta.","zh":""},{"ja":"友達に会ったところ、彼が海外に行くと言った。","en":"Upon meeting my friend, he told me he''s going abroad.","romaji":"Tomodachi ni atta tokoro, kare ga kaigai ni iku to itta.","zh":""},{"ja":"食事を食べ終わったところ、電話がかかってきた。","en":"Just when I finished eating, I got a phone call.","romaji":"Shokuji wo tabeowatta tokoro, denwa ga kakatte kita.","zh":""},{"ja":"机を整理したところ、忘れていたメモが見つかった。","en":"After organizing my desk, I found a memo I had forgotten about.","romaji":"Tsukue wo seiri shita tokoro, wasureteita memo ga mitsukatta.","zh":""}]',replace('**Short**: Expresses the result or outcome of an action; ''after'', ''just when'', ''upon''.\n\n**Formation**: Verb-た form + ところ\n\n**Long**: The ～たところ grammar point is used to indicate the result or outcome right after performing an action. It can be translated as ''after'', ''just when'', or ''upon'' in English. It is formed by attaching ところ to the past tense (た-form) of verbs.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ta_totan_n3','～たとたん',NULL,NULL,'N3','[]','[{"ja":"ドアを開けたとたん、猫が逃げ出した。","en":"As soon as I opened the door, the cat ran away.","romaji":"Doa wo aketa totan, neko ga nigedashita.","zh":""},{"ja":"電話をかけたとたん、電池が切れた。","en":"The moment I made the phone call, the battery died.","romaji":"Denwa wo kaketa totan, denchi ga kireta.","zh":""},{"ja":"雨が降り始めたとたん、みんなが傘をさした。","en":"The instant it started raining, everyone put up their umbrellas.","romaji":"Ame ga furihajimeta totan, minna ga kasa wo sashita.","zh":""},{"ja":"彼に会ったとたん、彼の笑顔が消えた。","en":"As soon as he met me, his smile disappeared.","romaji":"Kare ni atta totan, kare no egao ga kieta.","zh":""}]',replace('**Short**: Express the moment something happens; ''as soon as'', ''the moment'', ''the instant''.\n\n**Formation**: Verb-た form + とたん\n\n**Long**: The ～たとたん grammar point is used to express that something occurs immediately at the exact moment another action is completed. It can be translated as ''as soon as'', ''the moment'', or ''the instant'' in English. It is attached to the past tense (た-form) of a verb.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tabi_ni','～たびに',NULL,NULL,'N3','[]','[{"ja":"彼女に会うたびに、心が弾む。","en":"Every time I meet her, my heart leaps.","romaji":"Kanojo ni au tabi ni, kokoro ga hazumu.","zh":""},{"ja":"雨が降るたびに、懐かしい思い出がよみがえる。","en":"Whenever it rains, nostalgic memories come back.","romaji":"Ame ga furu tabi ni, natsukashii omoide ga yomigaeru.","zh":""},{"ja":"この歌を聴くたびに、幸せな気分になる。","en":"Every time I listen to this song, I feel happy.","romaji":"Kono uta wo kiku tabi ni, shiawase na kibun ni naru.","zh":""},{"ja":"家に帰るたびに、猫が出迎えてくれる。","en":"Every time I return home, the cat greets me.","romaji":"Ie ni kaeru tabi ni, neko ga demukaete kureru.","zh":""}]',replace('**Short**: Express ''every time'' or ''whenever''.\n\n**Formation**: Verb-dictionary form + たびに, Noun + のたびに\n\n**Long**: The ～たびに grammar point is used to express that an action or event occurs every time or whenever something else happens. It can be translated as ''every time'', ''whenever'', or ''each time'' in English. Typically, you attach たびに to a verb in its dictionary form, or to a noun plus の.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_da_mono_da','～だものだ',NULL,NULL,'N3','[]','[{"ja":"疲れたんだものだから、休みたい。","en":"I want to rest because I''m tired.","romaji":"Tsukareta n da mono da kara, yasumitai.","zh":""},{"ja":"お腹が空いたんだものだから、何か食べたい。","en":"I want to eat something because I''m hungry.","romaji":"Onaka ga suita n da mono da kara, nanika tabetai.","zh":""},{"ja":"忙しいんだものだから、来られない。","en":"I can''t come because I''m busy.","romaji":"Isogashii n da mono da kara, korarenai.","zh":""},{"ja":"彼は親切なんだものだから、誰も彼が好きだ。","en":"Everyone likes him because he is kind.","romaji":"Kare wa shinsetsu na n da mono da kara, dare mo kare ga suki da.","zh":""}]',replace('**Short**: Express the reason or cause, often used to justify something.\n\n**Formation**: Verb-casual + んだものだ, い-Adjective + んだものだ, な-Adjective + なんだものだ, Noun + なんだものだ (often with から as んだものだから)\n\n**Long**: The ～だものだ grammar point is used to explain a reason or cause in a subjective, explanatory tone (e.g. ''because... after all''). Often, you''ll see it used as ～だものだから (''because... after all'').\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_chatta','～ちゃった',NULL,NULL,'N3','[]','[{"ja":"忘れ物をしちゃった。","en":"I accidentally left something behind.","romaji":"Wasuremono o shichatta.","zh":""},{"ja":"寝坊して遅刻しちゃった。","en":"I overslept and ended up being late.","romaji":"Nebou shite chikoku shichatta.","zh":""},{"ja":"ケーキを全部食べちゃった。","en":"I ended up eating the whole cake.","romaji":"Keeki o zenbu tabechatta.","zh":""},{"ja":"言わないつもりだったけど、言っちゃった。","en":"I wasn''t planning to say it, but I ended up saying it.","romaji":"Iwanai tsumori datta kedo, icchatta.","zh":""}]',replace('**Short**: Express an unintentional action or a regretful action; ''ended up doing'', ''did accidentally''.\n\n**Formation**: Verb-て/で form → ちゃった/じゃった (e.g. 食べてしまった → 食べちゃった)\n\n**Long**: The ～ちゃった grammar point is the informal, colloquial version of ～てしまった. It expresses unintentional or regretful actions and can be translated as ''ended up doing'' or ''did accidentally''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tsuide_ni','～ついでに',NULL,NULL,'N3','[]','[{"ja":"買い物に行くついでに、郵便局で手紙を出しましょう。","en":"Let''s drop off a letter at the post office while going shopping.","romaji":"Kaimono ni iku tsuide ni, yuubinkyoku de tegami wo dashimashou.","zh":""},{"ja":"図書館で本を借りたついでに、友達に会いました。","en":"I met my friend while borrowing a book from the library.","romaji":"Toshokan de hon wo karita tsuide ni, tomodachi ni aimashita.","zh":""},{"ja":"日本に来たついでに、有名な観光地を訪れたいです。","en":"While visiting Japan, I''d like to see some famous tourist spots.","romaji":"Nihon ni kita tsuide ni, yuumei na kankouchi wo otozuretai desu.","zh":""},{"ja":"映画館に行ったついでに、新作のポスターを見ました。","en":"While going to the movie theater, I saw a poster for a new film.","romaji":"Eigakan ni itta tsuide ni, shinsaku no posutaa wo mimashita.","zh":""}]',replace('**Short**: Do something while or after completing another action; ''while'', ''by the way''.\n\n**Formation**: Verb (dictionary or た-form) + ついでに, Noun + の + ついでに, or Verb-て form + いる + ついでに\n\n**Long**: The ～ついでに grammar point is used to express doing something ''on the occasion of'' another action. It can mean ''while you''re at it'', ''by the way'', or ''in passing''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kke','～っけ？',NULL,NULL,'N3','[]','[{"ja":"彼は何時に来るっけ？","en":"What time is he coming again?","romaji":"Kare wa nanji ni kuru kke?","zh":""},{"ja":"この映画、面白かったっけ？","en":"Was this movie interesting?","romaji":"Kono eiga, omoshirokatta kke?","zh":""},{"ja":"彼女は学生だっけ？","en":"She was a student, right?","romaji":"Kanojo wa gakusei dakke?","zh":""},{"ja":"すし屋はどこだっけ？","en":"Where was the sushi place again?","romaji":"Sushiya wa doko dakke?","zh":""}]',replace('**Short**: Used to express that one is trying to recall some information.\n\n**Formation**: Verb-casual + っけ?, い-Adjective + かったっけ?, な-Adjective/Noun + だっけ?\n\n**Long**: The ～っけ？ grammar point is added at the end of a sentence when the speaker is trying to recall something or confirm a memory. It can be used with verbs, adjectives, or nouns in casual form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ppai','～っぱい',NULL,NULL,'N3','[]','[{"ja":"部屋が荷物でいっぱいです。","en":"The room is full of luggage.","romaji":"Heya ga nimotsu de ippai desu.","zh":""},{"ja":"彼女は笑顔でいっぱいでした。","en":"She was full of smiles.","romaji":"Kanojo wa egao de ippai deshita.","zh":""},{"ja":"彼は仕事でいっぱいです。","en":"He is completely busy with work.","romaji":"Kare wa shigoto de ippai desu.","zh":""},{"ja":"公園は花でいっぱいです。","en":"The park is filled with flowers.","romaji":"Kouen wa hana de ippai desu.","zh":""}]',replace('**Short**: Expresses fullness or completeness; ''full'', ''full of'', ''filled with''.\n\n**Formation**: Noun + で + いっぱい (Note: written as いっぱい, read as ''ippai'')\n\n**Long**: The ～っぱい grammar point is used to convey that something is filled or packed with something else. Commonly used as 『Noun + でいっぱい』 (e.g., 荷物でいっぱい) to mean ''full of X''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ppanashi_n3','～っぱなし',NULL,NULL,'N3','[]','[{"ja":"窓を開けっぱなしにすると、虫が入ってくる。","en":"If you leave the window open, bugs will come in.","romaji":"Mado o akeppanashi ni suru to, mushi ga haitte kuru.","zh":""},{"ja":"洗濯物を干しっぱなしで、雨に濡れた。","en":"I left the laundry hanging out, and it got wet in the rain.","romaji":"Sentakumono o hoshippanashi de, ame ni nureta.","zh":""},{"ja":"彼はドアを開けっぱなしにして出かけた。","en":"He went out leaving the door open.","romaji":"Kare wa doa o akeppanashi ni shite dekaketa.","zh":""},{"ja":"テレビをつけっぱなしにして寝てしまった。","en":"I fell asleep with the TV left on.","romaji":"Terebi o tsukeppanashi ni shite nete shimatta.","zh":""}]',replace('**Short**: Indicate a state where an action is left as is (unchanged or unfinished).\n\n**Formation**: Verb-ますstem + っぱなし\n\n**Long**: The ～っぱなし grammar point is used to express that an action happened and was left in that state, unattended or unchanged. It is formed by taking the ます-stem of a verb and adding ～っぱなし.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tsumari','～つまり',NULL,NULL,'N3','[]','[{"ja":"彼は大学の教授です。つまり、専門家です。","en":"He is a university professor. In other words, he is an expert.","romaji":"Kare wa daigaku no kyouju desu. Tsumari, senmonka desu.","zh":""},{"ja":"今日は土曜日だ。つまり、明日は日曜日だ。","en":"Today is Saturday. That is to say, tomorrow is Sunday.","romaji":"Kyou wa doyoubi da. Tsumari, ashita wa nichiyoubi da.","zh":""},{"ja":"山田さんは友達のお姉さんです。つまり、私たちの知り合いです。","en":"Ms. Yamada is my friend''s older sister. In short, she''s someone we know.","romaji":"Yamada-san wa tomodachi no oneesan desu. Tsumari, watashitachi no shiriai desu.","zh":""},{"ja":"彼女はフランス出身です。つまり、フランス語が話せます。","en":"She is from France. In other words, she can speak French.","romaji":"Kanojo wa Furansu shusshin desu. Tsumari, Furansugo ga hanasemasu.","zh":""}]',replace('**Short**: Summarizing, restating, or clarifying a point: ''in other words'', ''that is to say''.\n\n**Formation**: Sentence A + つまり + Sentence B (rephrasing)\n\n**Long**: The ～つまり grammar point is used to restate or clarify in a concise way what has been said. It can be translated as ''in other words'', ''that is to say'', or ''in short''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tsumori_deshita','～つもりでした',NULL,NULL,'N3','[]','[{"ja":"昨日は友達に会うつもりでしたが、風邪を引いてしまいました。","en":"I was planning to meet my friend yesterday, but I caught a cold.","romaji":"Kinou wa tomodachi ni au tsumori deshita ga, kaze o hiite shimaimashita.","zh":""},{"ja":"映画を見るつもりでしたが、時間がなくなりました。","en":"I intended to watch a movie, but I ran out of time.","romaji":"Eiga o miru tsumori deshita ga, jikan ga nakunarimashita.","zh":""},{"ja":"彼らが来るつもりでしたが、電話でキャンセルされました。","en":"They were supposed to come, but they canceled by phone.","romaji":"Karera ga kuru tsumori deshita ga, denwa de kyanseru saremashita.","zh":""},{"ja":"この本を読むつもりでしたが、もう読み終わっていました。","en":"I meant to read this book, but I realized I''d already finished it.","romaji":"Kono hon o yomu tsumori deshita ga, mou yomiowatte imashita.","zh":""}]',replace('**Short**: Expressing a past intention or plan; ''was planning to'', ''meant to''.\n\n**Formation**: Verb-casual (dictionary form) + つもりでした\n\n**Long**: The ～つもりでした grammar point is used to express a past intention or plan that did not happen, or a past belief that turned out incorrect. It can be translated as ''was planning to'', ''intended to'', or ''meant to''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_kureto','～てくれと',NULL,NULL,'N3','[]','[{"ja":"電話をかけてくれと言われました。","en":"I was told to make a phone call.","romaji":"Denwa o kakete kureto iwaremashita.","zh":""},{"ja":"この荷物を運んでくれと頼まれました。","en":"I was asked to carry this luggage.","romaji":"Kono nimotsu o hakonde kureto tanomaremashita.","zh":""},{"ja":"最後まで待ってくれとお願いされました。","en":"I was asked to wait until the end.","romaji":"Saigo made matte kureto onegai saremashita.","zh":""},{"ja":"休んでくれと言われました。","en":"I was told to please take a rest.","romaji":"Yasunde kureto iwaremashita.","zh":""}]',replace('**Short**: Quote someone''s request (telling someone to do something).\n\n**Formation**: Verb-て form + くれと (言う / 頼む / 伝える, etc.)\n\n**Long**: The ～てくれと grammar point is used when quoting a request or command made by someone else. It literally means ''someone said “please do …”''. Typically used as 「～てくれと頼む/言う」 to indicate being asked or told to do something.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_goran','～てごらん',NULL,NULL,'N3','[]','[{"ja":"そのゲームをやってごらん。","en":"Why don''t you try playing that game?","romaji":"Sono geemu o yatte goran.","zh":""},{"ja":"彼に話してごらん。","en":"Try talking to him.","romaji":"Kare ni hanashite goran.","zh":""},{"ja":"新しいレシピを作ってごらん。","en":"Why don''t you try making a new recipe?","romaji":"Atarashii reshipi o tsukutte goran.","zh":""},{"ja":"そのドレスを着てごらん。","en":"Try putting on that dress.","romaji":"Sono doresu o kite goran.","zh":""}]',replace('**Short**: Suggest or invite someone to try doing something; ''Why don''t you try...''.\n\n**Formation**: Verb-て form + ごらん\n\n**Long**: The ～てごらん grammar point is used to gently suggest or invite someone to try doing something. It is softer and more casual than ～てみて, and is used among friends or family.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_desu_kara','ですから～',NULL,NULL,'N3','[]','[{"ja":"今日は寒いですから、コートを着てください。","en":"It''s cold today, so please wear a coat.","romaji":"Kyou wa samui desu kara, kooto o kite kudasai.","zh":""},{"ja":"この映画は面白いですから、ぜひ見てください。","en":"This movie is interesting, so please watch it.","romaji":"Kono eiga wa omoshiroi desu kara, zehi mite kudasai.","zh":""},{"ja":"明日は休みですから、ゆっくり休んでください。","en":"Tomorrow is a day off, so please take your time to rest.","romaji":"Ashita wa yasumi desu kara, yukkuri yasunde kudasai.","zh":""},{"ja":"彼は親切ですから、手伝ってくれるでしょう。","en":"He''s kind, so he''ll probably help you.","romaji":"Kare wa shinsetsu desu kara, tetsudatte kureru deshou.","zh":""}]',replace('**Short**: Expresses reason or cause; ''because'', ''since'', ''so''.\n\n**Formation**: Sentence A + ですから + Sentence B\n\n**Long**: The ですから grammar point is used to indicate the reason or cause for a statement, often in polite speech. It can be translated as ''because'', ''since'', or ''so''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_hajimete','～てはじめて',NULL,NULL,'N3','[]','[{"ja":"海外に行ってはじめて、日本の良さが分かりました。","en":"Only after going abroad did I realize how great Japan is.","romaji":"Kaigai ni itte hajimete, Nihon no yosa ga wakarimashita.","zh":""},{"ja":"彼女と別れてはじめて、彼女の大切さに気づいた。","en":"I realized her importance only after breaking up with her.","romaji":"Kanojo to wakarete hajimete, kanojo no taisetsusa ni kizuita.","zh":""},{"ja":"大学を卒業してはじめて、学生時代の楽しさが分かった。","en":"I understood how fun my student days were only after graduating from university.","romaji":"Daigaku o sotsugyou shite hajimete, gakusei jidai no tanoshisa ga wakatta.","zh":""},{"ja":"子供ができてはじめて、親の気持ちが分かった。","en":"I understood how parents feel only after I had a child.","romaji":"Kodomo ga dekite hajimete, oya no kimochi ga wakatta.","zh":""}]',replace('**Short**: Realization or action done for the first time; ''only after'', ''not until''.\n\n**Formation**: Verb-て form + はじめて\n\n**Long**: The ～てはじめて grammar point indicates that something is realized or happens for the first time only after another action is completed. It can be translated as ''only after'' or ''not until''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_hoshii','～てほしい',NULL,NULL,'N3','[]','[{"ja":"子供にもっと勉強してほしい。","en":"I want my child to study more.","romaji":"Kodomo ni motto benkyou shite hoshii.","zh":""},{"ja":"彼に私に電話してほしい。","en":"I want him to call me.","romaji":"Kare ni watashi ni denwa shite hoshii.","zh":""},{"ja":"友達に手伝ってほしい。","en":"I want my friend to help me.","romaji":"Tomodachi ni tetsudatte hoshii.","zh":""},{"ja":"彼女に明日ここに来てほしい。","en":"I want her to come here tomorrow.","romaji":"Kanojo ni ashita koko ni kite hoshii.","zh":""}]',replace('**Short**: Express a desire for someone else to do something; ''I want you to do...''.\n\n**Formation**: Verb-て form + ほしい\n\n**Long**: The ～てほしい grammar point is used to express a desire that someone else perform an action. It is formed by attaching ほしい to the て-form of a verb. It can be translated as ''I want you to...'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_temo','～ても',NULL,NULL,'N3','[]','[{"ja":"雨が降っても、運動会は開催されます。","en":"Even if it rains, the sports festival will be held.","romaji":"Ame ga futte mo, undoukai wa kaisai saremasu.","zh":""},{"ja":"忙しくても、毎日勉強する時間を作る。","en":"Even though I''m busy, I make time to study every day.","romaji":"Isogashikute mo, mainichi benkyou suru jikan o tsukuru.","zh":""},{"ja":"高くても、良い品質のものを買います。","en":"Even if it''s expensive, I''ll buy something of good quality.","romaji":"Takakute mo, yoi hinshitsu no mono o kaimasu.","zh":""},{"ja":"彼女が有名人でも、私は彼女のことを知らない。","en":"Even if she''s famous, I don''t know her.","romaji":"Kanojo ga yuumeijin demo, watashi wa kanojo no koto o shiranai.","zh":""}]',replace('**Short**: ''Even if'', ''even though'', or ''although''.\n\n**Formation**: Verb-て form + も, い-Adjective (～く) + ても, な-Adjective/Noun (～で) + も\n\n**Long**: The ～ても grammar point expresses that even if a certain condition holds, the outcome or situation doesn''t change. It can be translated as ''even if'' or ''even though''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_ii_naa','～といいなあ',NULL,NULL,'N3','[]','[{"ja":"明日晴れるといいなあ。","en":"I hope it''s sunny tomorrow.","romaji":"Ashita hareru to ii naa.","zh":""},{"ja":"この試験に合格するといいなあ。","en":"I hope I pass this exam.","romaji":"Kono shiken ni goukaku suru to ii naa.","zh":""},{"ja":"彼女が元気だといいなあ。","en":"I hope she is doing well.","romaji":"Kanojo ga genki da to ii naa.","zh":""},{"ja":"彼が新しい仕事が見つかるといいなあ。","en":"I hope he finds a new job.","romaji":"Kare ga atarashii shigoto ga mitsukaru to ii naa.","zh":""}]',replace('**Short**: Express a wish or hope; ''it would be nice if'', ''I hope that''.\n\n**Formation**: Verb-casual + といいなあ, い-Adjective + といいなあ, な-Adjective + だといいなあ, Noun + だといいなあ\n\n**Long**: The ～といいなあ grammar point is used to express a wish or hope for something to happen or to be in a certain way. It can be translated as ''it would be nice if'' or ''I hope that'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_iu_n3','～という',NULL,NULL,'N3','[]','[{"ja":"本屋で「ハリー・ポッター」という本を買いました。","en":"I bought a book called ''Harry Potter'' at the bookstore.","romaji":"Hon''ya de ''Harry Potter'' to iu hon o kaimashita.","zh":""},{"ja":"昨日、美味しいというケーキを食べました。","en":"Yesterday, I ate a cake that is said to be delicious.","romaji":"Kinou, oishii to iu keeki o tabemashita.","zh":""},{"ja":"彼はとても親切だという評判です。","en":"He has a reputation for being very kind.","romaji":"Kare wa totemo shinsetsu da to iu hyouban desu.","zh":""},{"ja":"今年の夏、東京にある「ディズニーランド」というテーマパークに行きたいです。","en":"I want to go to a theme park called ''Disneyland'' in Tokyo this summer.","romaji":"Kotoshi no natsu, Toukyou ni aru ''Disneyland'' to iu teema paaku ni ikitai desu.","zh":""}]',replace('**Short**: Used for quoting, defining, or giving an example; ''called'', ''that is to say'', ''like''.\n\n**Formation**: Noun + という + Noun, Verb-casual + という + Noun, い-Adjective + という + Noun, な-Adjective + という + Noun\n\n**Long**: The ～という grammar point is used to quote, define, or give an example of something. It can be translated as ''called'', ''that is to say'', or ''like'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_iu_koto_da','～ということだ',NULL,NULL,'N3','[]','[{"ja":"彼は来週結婚するということだ。","en":"I heard that he is getting married next week.","romaji":"Kare wa raishuu kekkon suru to iu koto da.","zh":""},{"ja":"この試験は難しいということだ。","en":"It means this exam is difficult.","romaji":"Kono shiken wa muzukashii to iu koto da.","zh":""},{"ja":"彼女が引っ越したということだ。","en":"I heard that she has moved.","romaji":"Kanojo ga hikkoshita to iu koto da.","zh":""},{"ja":"彼は仕事がうまくいかないだということだ。","en":"It can be said that his work is not going well.","romaji":"Kare wa shigoto ga umaku ikanai da to iu koto da.","zh":""}]',replace('**Short**: Express a conclusion or hearsay; ''I heard'', ''it means'', ''it can be said''.\n\n**Formation**: Verb-casual + ということだ, い-Adjective + ということだ, な-Adjective + だということだ, Noun + だということだ\n\n**Long**: The ～ということだ grammar point is used to express a conclusion, summary, or hearsay about a certain situation or statement. It can be translated as ''I heard'', ''it means'', or ''it can be said'' in English. This grammar point is often used with verbs, adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_iu_to','～というと',NULL,NULL,'N3','[]','[{"ja":"日本料理というと、寿司が思い浮かぶ。","en":"When it comes to Japanese cuisine, sushi comes to mind.","romaji":"Nihon ryouri to iu to, sushi ga omoiukabu.","zh":""},{"ja":"パリというと、エッフェル塔を思い出す。","en":"Speaking of Paris, I recall the Eiffel Tower.","romaji":"Pari to iu to, Efferu Tou wo omoidasu.","zh":""},{"ja":"夏休みというと、海に行くことが楽しみだ。","en":"When it comes to summer vacation, I look forward to going to the beach.","romaji":"Natsu yasumi to iu to, umi ni iku koto ga tanoshimi da.","zh":""},{"ja":"彼というと、いつも元気な人だと思う。","en":"Speaking of him, I think he''s always energetic.","romaji":"Kare to iu to, itsumo genki na hito da to omou.","zh":""}]',replace('**Short**: Used to provide an example or characteristic related to the topic; ''when it comes to'', ''speaking of''.\n\n**Formation**: Noun + というと\n\n**Long**: The ～というと grammar point is used to indicate an example, characteristic, or association related to the topic being discussed. It can be translated as ''when it comes to'', ''speaking of'', or ''in terms of'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_iu_no','～というの～',NULL,NULL,'N3','[]','[{"ja":"遅刻したのは、電車が遅れたというのだ。","en":"The reason I was late is because the train was delayed.","romaji":"Chikoku shita no wa, densha ga okureta to iu no da.","zh":""},{"ja":"この部屋が汚いのは、掃除をしなかったというのだ。","en":"The reason this room is dirty is because I didn''t clean it.","romaji":"Kono heya ga kitanai no wa, souji o shinakatta to iu no da.","zh":""},{"ja":"彼女が怒っているのは、彼が約束を破ったというのだ。","en":"The reason she is angry is that he broke his promise.","romaji":"Kanojo ga okotte iru no wa, kare ga yakusoku o yabutta to iu no da.","zh":""},{"ja":"彼が成功したのは、努力して勉強したというのだ。","en":"The reason he succeeded is because he studied hard.","romaji":"Kare ga seikou shita no wa, doryoku shite benkyou shita to iu no da.","zh":""}]',replace('**Short**: Explain or emphasize the reason for a situation or action.\n\n**Formation**: Verb-casual + というの, い-Adjective + というの, な-Adjective + だというの, Noun + だというの\n\n**Long**: The ～というの〜 grammar point is used to provide an explanation or emphasize the reason for a certain situation or action. It can be translated as ''the reason is that...'', or ''it''s because...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_iu_no_wa','～というのは',NULL,NULL,'N3','[]','[{"ja":"日本に行くというのは、日本に旅行することです。","en":"Going to Japan, that is to say, traveling to Japan.","romaji":"Nihon ni iku to iu no wa, Nihon ni ryokou suru koto desu.","zh":""},{"ja":"この問題は難しいというのは、解決に時間がかかるということです。","en":"When I say this problem is difficult, I mean it takes time to solve.","romaji":"Kono mondai wa muzukashii to iu no wa, kaiketsu ni jikan ga kakaru to iu koto desu.","zh":""},{"ja":"彼が怒っているというのは、彼が不満を感じているということです。","en":"By saying that he''s angry, I mean he''s feeling dissatisfied.","romaji":"Kare ga okotteiru to iu no wa, kare ga fuman wo kanjiteiru to iu koto desu.","zh":""},{"ja":"太るというのは、体重が増えるということです。","en":"Gaining weight, that is to say, increasing one''s body weight.","romaji":"Futoru to iu no wa, taijuu ga fueru to iu koto desu.","zh":""}]',replace('**Short**: Used to provide an explanation or definition; ''that is to say...'', ''by that, I mean...''.\n\n**Formation**: Phrase/sentence + というのは + explanation/definition\n\n**Long**: The ～というのは grammar point is used to provide an explanation or definition of the preceding statement or word. It can be translated as ''that is to say...'', ''by that, I mean...'', or ''what I mean by...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_iu_yori','～というより',NULL,NULL,'N3','[]','[{"ja":"この部屋は狭いというより、居心地がいい。","en":"Rather than saying this room is small, it''s more like it''s cozy.","romaji":"Kono heya wa semai to iu yori, igokochi ga ii.","zh":""},{"ja":"彼は怖いというより、頼りがいがある。","en":"Instead of saying he''s scary, he''s more like a reliable person.","romaji":"Kare wa kowai to iu yori, tayori gai ga aru.","zh":""},{"ja":"映画はつまらないというより、ちょっと長かった。","en":"Rather than calling the movie boring, I''d say it was a bit long.","romaji":"Eiga wa tsumaranai to iu yori, chotto nagakatta.","zh":""},{"ja":"彼女は友達だというより、家族のような存在だ。","en":"Rather than a friend, she''s more like family.","romaji":"Kanojo wa tomodachi da to iu yori, kazoku no you na sonzai da.","zh":""}]',replace('**Short**: Express a comparison with preference; ''rather than'', ''more like'', ''instead of''.\n\n**Formation**: Verb-casual + というより, い-Adjective + というより, な-Adjective + だというより, Noun + だというより\n\n**Long**: The ～というより grammar point is used to express a comparison where one description is more accurate than another. Translated as ''rather than'', ''more like'', or ''instead of''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_ittemo','～といっても',NULL,NULL,'N3','[]','[{"ja":"彼は有名だといっても、みんなに知られているわけではありません。","en":"Even though he''s famous, it doesn''t mean everyone knows him.","romaji":"Kare wa yuumei da to ittemo, minna ni shirarete iru wake de wa arimasen.","zh":""},{"ja":"このスープは辛いといっても、私にはちょうどいいです。","en":"Although this soup is spicy, it''s just right for me.","romaji":"Kono suupu wa karai to ittemo, watashi ni wa choudo ii desu.","zh":""},{"ja":"彼女は若いですが、経験があるといっても、まだ新人です。","en":"She''s young, and although she has some experience, she''s still a newcomer.","romaji":"Kanojo wa wakai desu ga, keiken ga aru to ittemo, mada shinjin desu.","zh":""},{"ja":"このレストランは高いだといっても、美味しい料理が食べられるので価値があります。","en":"Even though this restaurant is expensive, it''s worth it because you can enjoy delicious dishes.","romaji":"Kono resutoran wa takai da to ittemo, oishii ryouri ga taberareru node kachi ga arimasu.","zh":""}]',replace('**Short**: Express the meaning ''even though'', ''although'', ''but''.\n\n**Formation**: Verb-casual + といっても, い-Adjective + といっても, な-Adjective + だといっても, Noun + だといっても\n\n**Long**: The ～といっても grammar point is used to show a contrast or clarify that ''even though'' something is the case, it does not necessarily lead to the expected result. It can be translated as ''even though'', ''although'', or ''but''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_toori_n3','～とおり',NULL,NULL,'N3','[]','[{"ja":"先生が言ったとおり、宿題をやりました。","en":"I did my homework exactly as the teacher said.","romaji":"Sensei ga itta toori, shukudai wo yarimashita.","zh":""},{"ja":"地図に書いてあるとおりに行けば、駅に着きます。","en":"If you follow what''s written on the map, you''ll arrive at the station.","romaji":"Chizu ni kaite aru toori ni ikeba, eki ni tsukimasu.","zh":""},{"ja":"レシピのとおりにケーキを作った。","en":"I baked the cake according to the recipe.","romaji":"Reshipi no toori ni keeki o tsukutta.","zh":""},{"ja":"彼女は約束したとおりに時間通りに来ました。","en":"She arrived on time, just as she promised.","romaji":"Kanojo wa yakusoku shita toori ni jikan doori ni kimashita.","zh":""}]',replace('**Short**: Expresses that something is done ''as is'', ''as stated'', or ''as instructed''.\n\n**Formation**: Verb-て form + とおり, Noun + のとおり\n\n**Long**: The ～とおり grammar point is used to express that something is done exactly as stated, instructed, or shown. It is commonly used with verbs and nouns, and can be translated as ''just like'', ''as per'', or ''according to''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_toku','～とく',NULL,NULL,'N3','[]','[{"ja":"夜遅くなるから、今晩のご飯を作っとく。","en":"Since it will be late tonight, I''ll prepare dinner in advance.","romaji":"Yoru osoku naru kara, konban no gohan wo tsukutoku.","zh":""},{"ja":"傘が必要かもしれないので、持っておく。","en":"I might need an umbrella, so I''ll bring one along (just in case).","romaji":"Kasa ga hitsuyou kamoshirenai node, motte oku.","zh":""},{"ja":"試験が近いから、今から勉強しとこう。","en":"The exam is coming up, so I''ll start studying now.","romaji":"Shiken ga chikai kara, ima kara benkyou shitokou.","zh":""},{"ja":"明日は忙しいので、洗濯をしとく。","en":"Since I''ll be busy tomorrow, I''ll do the laundry in advance.","romaji":"Ashita wa isogashii node, sentaku wo shitoku.","zh":""}]',replace('**Short**: Express doing something in advance or for future convenience (casual form of ～ておく).\n\n**Formation**: Verb-て form + とく (e.g., 食べておく→食べとく, 読んでおく→読んどく)\n\n**Long**: The ～とく grammar point (from ～ておく) is used to express doing something in advance or preparing for something. It implies you''re performing an action now to avoid inconvenience later. It is a casual, colloquial contraction of ～ておく.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tokoro_ga','～ところが',NULL,NULL,'N3','[]','[{"ja":"彼はいつも遅刻するところが、今日は早く来ました。","en":"He''s always late, but today he arrived early.","romaji":"Kare wa itsumo chikoku suru tokoro ga, kyou wa hayaku kimashita.","zh":""},{"ja":"昨日は暑かったところが、今日は寒くなりました。","en":"Yesterday was hot, but today it got cold.","romaji":"Kinou wa atsukatta tokoro ga, kyou wa samuku narimashita.","zh":""},{"ja":"試合で負けると思ったところが、意外にも勝ちました。","en":"I thought we would lose the match, but surprisingly we won.","romaji":"Shiai de makeru to omotta tokoro ga, igai ni mo kachimashita.","zh":""},{"ja":"決勝戦で優勝するところが、最後のポイントで負けました。","en":"We were about to win the final, but we lost at the last point.","romaji":"Kesshousen de yuushou suru tokoro ga, saigo no pointo de makemashita.","zh":""}]',replace('**Short**: Expresses a contrast or unexpected outcome; ''however'', ''but'', ''even though''.\n\n**Formation**: Phrase 1 (expected situation) + ところが + Phrase 2 (unexpected result)\n\n**Long**: The ～ところが grammar point is used to express a contrast or an unexpected outcome. It can be translated as ''however'', ''but'', or ''even though'' in English. It emphasizes a situation that contradicts what was expected.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tokoro_datta','～ところだった',NULL,NULL,'N3','[]','[{"ja":"もう少しで遅れるところだった。","en":"I was just about to be late.","romaji":"Mou sukoshi de okureru tokoro datta.","zh":""},{"ja":"彼が危うく事故にあうところだった。","en":"He almost had an accident.","romaji":"Kare ga ayauku jiko ni au tokoro datta.","zh":""},{"ja":"電車に乗るところだったが、ドアが閉まってしまった。","en":"I was just about to get on the train, but the door closed.","romaji":"Densha ni noru tokoro datta ga, doa ga shimatte shimatta.","zh":""},{"ja":"忘れ物をするところだった。","en":"I almost forgot my belongings.","romaji":"Wasuremono wo suru tokoro datta.","zh":""}]',replace('**Short**: Expresses a near miss or a situation that almost happened; ''was just about to'', ''almost'', ''nearly''.\n\n**Formation**: Verb (dictionary form or ている form) + ところだった\n\n**Long**: The ～ところだった grammar point is used to express a situation that almost occurred or something that the speaker was just about to do. It can be translated as ''was just about to'', ''almost'', or ''nearly'' in English. Typically, it is formed with the dictionary form or ている form of a verb + ところだった.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tokorode','ところで',NULL,NULL,'N3','[]','[{"ja":"ところで、昨日の宿題はもう終わりましたか？","en":"By the way, did you finish yesterday''s homework?","romaji":"Tokorode, kinou no shukudai wa mou owari mashita ka?","zh":""},{"ja":"彼はプールで泳いでいます。ところで、お昼ご飯は何にしますか？","en":"He is swimming in the pool. By the way, what do you want for lunch?","romaji":"Kare wa puuru de oyoide imasu. Tokorode, ohiru gohan wa nani ni shimasu ka?","zh":""},{"ja":"昨日は楽しかったですね。ところで、この写真を見ましたか？","en":"Yesterday was fun, wasn''t it? By the way, did you see this photo?","romaji":"Kinou wa tanoshikatta desu ne. Tokorode, kono shashin wo mimashita ka?","zh":""},{"ja":"ところで、明日の会議の時間を知っていますか？","en":"By the way, do you know the time of tomorrow''s meeting?","romaji":"Tokorode, ashita no kaigi no jikan wo shitte imasu ka?","zh":""}]',replace('**Short**: Used for changing the topic or bringing up a new topic; ''by the way'', ''speaking of''.\n\n**Formation**: ところで + new topic or question\n\n**Long**: The ところで (tokorode) grammar point is used to change the topic of conversation or introduce a new topic. It can be translated as ''by the way'' or ''speaking of'' in English. It is often used when the speaker wants to ask a question or share some information on a different subject. It can be placed at the beginning or in the middle of a sentence.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_shitara_n3','～としたら',NULL,NULL,'N3','[]','[{"ja":"明日雨が降るとしたら、傘を持って行きましょう。","en":"If it rains tomorrow, let''s bring an umbrella.","romaji":"Ashita ame ga furu to shitara, kasa wo motte ikimashou.","zh":""},{"ja":"このケーキが美味しくないとしたら、誰も食べないでしょう。","en":"If this cake is not delicious, nobody will eat it.","romaji":"Kono keeki ga oishikunai to shitara, daremo tabenai deshou.","zh":""},{"ja":"彼が病気だとしたら、すぐに病院に行かせてあげてください。","en":"If he is sick, please take him to the hospital right away.","romaji":"Kare ga byouki da to shitara, sugu ni byouin ni ikasete agete kudasai.","zh":""},{"ja":"彼女が学生だとしたら、このレストランは割引があるでしょう。","en":"If she is a student, there will be a discount at this restaurant.","romaji":"Kanojo ga gakusei da to shitara, kono resutoran wa waribiki ga aru deshou.","zh":""}]',replace('**Short**: Express a hypothetical situation; ''if'', ''suppose'', ''assuming''.\n\n**Formation**: Verb-casual + としたら, い-Adjective + としたら, な-Adjective + だとしたら, Noun + だとしたら\n\n**Long**: The ～としたら grammar point is used to express a hypothetical situation or assumption. It can be translated as ''if'', ''suppose'', or ''assuming'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_shite','～として',NULL,NULL,'N3','[]','[{"ja":"彼は弁護士として働いています。","en":"He is working as a lawyer.","romaji":"Kare wa bengoshi to shite hataraite imasu.","zh":""},{"ja":"この料理はスナックとして食べられます。","en":"This dish can be eaten as a snack.","romaji":"Kono ryouri wa sunakku to shite taberaremasu.","zh":""},{"ja":"彼女はリーダーとして尊敬されている。","en":"She is respected as a leader.","romaji":"Kanojo wa riidaa to shite sonkei sarete iru.","zh":""},{"ja":"この本は参考書として使われます。","en":"This book is used as a reference.","romaji":"Kono hon wa sankousho to shite tsukawaremasu.","zh":""}]',replace('**Short**: Indicates a role, capacity, or identity; ''as'', ''in the capacity of''.\n\n**Formation**: Verb-casual + として, い-Adjective + として, な-Adjective + だとして, Noun + だとして\n\n**Long**: The ～として grammar point is used to express a role, capacity, or identity in which someone or something functions. It can be translated as ''as'' or ''in the capacity of'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_donna_ni_koto_ka','～どんなに～ことか',NULL,NULL,'N3','[]','[{"ja":"どんなに疲れたことか、言葉では表せません。","en":"I can''t put into words how tired I am.","romaji":"Donna ni tsukareta koto ka, kotoba de wa arawasemasen.","zh":""},{"ja":"どんなに辛いことか、彼女は毎日頑張って働いています。","en":"How hard it must be, she works hard every day.","romaji":"Donna ni tsurai koto ka, kanojo wa mainichi ganbatte hataraiteimasu.","zh":""},{"ja":"彼の成功はどんなに喜ばしいことか。","en":"How happy his success must be.","romaji":"Kare no seikou wa donna ni yorokobashii koto ka.","zh":""},{"ja":"どんなに楽しいことか、みんなで旅行に行く。","en":"How fun it is to go on a trip with everyone.","romaji":"Donna ni tanoshii koto ka, minna de ryokou ni iku.","zh":""}]',replace('**Short**: Expresses the extent of something or emphasizes the degree of a condition or situation.\n\n**Formation**: どんなに + Adjective + ことか, どんなに + Verb + ことか\n\n**Long**: The ～どんなに～ことか grammar point is used to emphasize the extent of a condition or circumstance, and to express how much or to what degree something is happening. It is often translated as ''how much'', ''how greatly'', or ''to what extent'' in English. This pattern is usually used with an adjective or verb in a sentence.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_donna_ni_temo','どんなに～ても',NULL,NULL,'N3','[]','[{"ja":"どんなに勉強しても、まだわからないことがある。","en":"No matter how much I study, there are still things I don''t understand.","romaji":"Donna ni benkyou shite mo, mada wakaranai koto ga aru.","zh":""},{"ja":"どんなに速く走っても、彼には勝てません。","en":"No matter how fast I run, I can''t beat him.","romaji":"Donna ni hayaku hashitte mo, kare ni wa katemasen.","zh":""},{"ja":"どんなに疲れても、仕事を終わらせるまで帰れません。","en":"No matter how tired I am, I can''t go home until I finish my work.","romaji":"Donna ni tsukarete mo, shigoto o owaraseru made kaeremasen.","zh":""},{"ja":"どんなに美味しくても、これ以上食べられない。","en":"No matter how delicious it is, I can''t eat any more.","romaji":"Donna ni oishikute mo, kore ijou taberarenai.","zh":""}]',replace('**Short**: Expresses ''no matter how much'' or ''even if''; emphasizes the degree of a situation.\n\n**Formation**: どんなに + Verb-てform + も, どんなに + い-Adjective-てform + も, どんなに + な-Adjective + でも\n\n**Long**: The どんなに～ても grammar point is used to emphasize the degree of a situation or condition, often translated as ''no matter how much'' or ''even if'' in English. It can be used with verbs, い-adjectives, and な-adjectives.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nai_koto_wa_nai_n3','～ないことはない',NULL,NULL,'N3','[]','[{"ja":"この問題を解けないことはないが、時間がかかりそうだ。","en":"It''s not that I can''t solve this problem, but it seems like it will take time.","romaji":"Kono mondai wo tokenai koto wa nai ga, jikan ga kakari sou da.","zh":""},{"ja":"彼に会わないことはないけど、あまり話したくない。","en":"It''s not that I can''t meet him, but I don''t really want to talk.","romaji":"Kare ni awanai koto wa nai kedo, amari hanashitakunai.","zh":""},{"ja":"この映画を見ないことはないけれど、他の映画がもっと面白いと思う。","en":"It''s not that I cannot watch this movie, but I think other movies are more interesting.","romaji":"Kono eiga wo minai koto wa nai keredo, hoka no eiga ga motto omoshiroi to omou.","zh":""},{"ja":"その本を読まないことはないが、長いので気をつけてください。","en":"It''s not that I can''t read that book, but it''s long, so be careful.","romaji":"Sono hon wo yomanai koto wa nai ga, nagai node ki wo tsukete kudasai.","zh":""}]',replace('**Short**: Express the idea that ''it''s not that it''s impossible'' or ''it''s not that it cannot be done''.\n\n**Formation**: Verb-ない form + ことはない\n\n**Long**: The ～ないことはない grammar point is used to express that something is not impossible, or not that it cannot be done. It creates a softer, more indirect way of saying that something is possible or can be done, but not necessarily easy or preferred.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nai_to','～ないと',NULL,NULL,'N3','[]','[{"ja":"朝食を食べないと、お腹が空く。","en":"If I don''t eat breakfast, I will be hungry.","romaji":"Asa gohan wo tabenai to, onaka ga suku.","zh":""},{"ja":"宿題をしないと、先生に怒られる。","en":"If I don''t do my homework, the teacher will be angry.","romaji":"Shukudai wo shinai to, sensei ni okorareru.","zh":""},{"ja":"充電をしないと、電話が使えなくなる。","en":"If I don''t charge it, I won''t be able to use the phone.","romaji":"Juden wo shinai to, denwa ga tsukaenaku naru.","zh":""},{"ja":"この事故を報告しないと、問題が大きくなる。","en":"If I don''t report this accident, the problem will become bigger.","romaji":"Kono jiko wo houkoku shinai to, mondai ga ookiku naru.","zh":""}]',replace('**Short**: Express a condition; ''if... not'', ''unless'', ''must''.\n\n**Formation**: Verb-negative form + ないと\n\n**Long**: The ～ないと grammar point is used to express a condition, focusing on the negative consequences if the action is not performed. It can be translated as ''if... not'', ''unless'', or ''must'' in English. The formation is simply attaching ないと to the negative form of a verb.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nazenara','～なぜなら',NULL,NULL,'N3','[]','[{"ja":"このレストランが大好きだ。なぜなら料理が美味しいから。","en":"I love this restaurant because the food is delicious.","romaji":"Kono resutoran ga daisuki da. Nazenara ryouri ga oishii kara.","zh":""},{"ja":"彼女は試験に合格しなかった。なぜなら勉強しなかったから。","en":"She didn''t pass the exam because she didn''t study.","romaji":"Kanojo wa shiken ni goukaku shinakatta. Nazenara benkyou shinakatta kara.","zh":""},{"ja":"私は映画を見に行かない。なぜなら今日は忙しいから。","en":"I won''t go to see a movie because I am busy today.","romaji":"Watashi wa eiga o mi ni ikanai. Nazenara kyou wa isogashii kara.","zh":""},{"ja":"彼はこのプロジェクトを任せられる。なぜなら経験が豊富だから。","en":"He can be trusted with this project because he has a wealth of experience.","romaji":"Kare wa kono purojekuto wo makaserareru. Nazenara keiken ga houfu dakara.","zh":""}]',replace('**Short**: Express a reason or explanation; ''because'', ''the reason is''.\n\n**Formation**: Sentence/Statement + なぜなら + Reason + から/だから\n\n**Long**: The ～なぜなら grammar point is used to provide a reason or explanation for a preceding statement or situation. It can be translated as ''because'' or ''the reason is'' in English. It is often followed by から or だから to emphasize the reason or cause.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nado','～など',NULL,NULL,'N3','[]','[{"ja":"魚、果物などを市場で買いました。","en":"I bought fish, fruits, and such at the market.","romaji":"Sakana, kudamono nado wo ichiba de kaimashita.","zh":""},{"ja":"彼は日本語、英語、中国語などを話せます。","en":"He can speak languages such as Japanese, English, and Chinese.","romaji":"Kare wa nihongo, eigo, chuugokugo nado wo hanasemasu.","zh":""},{"ja":"美術館では絵画、彫刻などの作品を見ました。","en":"At the art museum, I saw works like paintings, sculptures, and others.","romaji":"Bijutsukan de wa kaiga, choukoku nado no sakuhin wo mimashita.","zh":""},{"ja":"この店ではパン、ケーキなどのお菓子を売っています。","en":"This store sells sweets such as bread, cakes, and so on.","romaji":"Kono mise de wa pan, keeki nado no okashi wo utteimasu.","zh":""}]',replace('**Short**: Indicates a non-exhaustive list of examples; ''such as'', ''things like'', ''among others''.\n\n**Formation**: Noun + など\n\n**Long**: The ～など grammar point is used to give a non-exhaustive list of examples, meaning the mentioned items are only some of many possibilities. It can be translated as ''such as'', ''things like'', or ''among others'' in English. This grammar point can be used with nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nanka','～なんか',NULL,NULL,'N3','[]','[{"ja":"お金なんかいらない。","en":"I don''t need money or anything like that.","romaji":"Okane nanka iranai.","zh":""},{"ja":"彼はピアノなんかも弾けます。","en":"He can play things like the piano.","romaji":"Kare wa piano nanka mo hikemasu.","zh":""},{"ja":"忙しいなんかじゃないよ。","en":"I''m not really busy or anything like that.","romaji":"Isogashii nanka janai yo.","zh":""},{"ja":"彼女は親切なんかじゃない。","en":"She''s not kind or anything like that.","romaji":"Kanojo wa shinsetsu nanka janai.","zh":""}]',replace('**Short**: Expresses the idea of ''things like'' or ''something like'', used for listing examples or downplaying something.\n\n**Formation**: Noun + なんか, Verb-casual + なんか, い-Adjective + なんか, な-Adjective + なんか\n\n**Long**: The ～なんか grammar point is used for listing examples by indicating ''things like'' or ''something like''. It can also be used to downplay or devalue something, making it seem less important or less significant than it really is.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_oite_n3','～において',NULL,NULL,'N3','[]','[{"ja":"日本において、お盆は家族が集まる大切な行事です。","en":"In Japan, Obon is an important event where families gather.","romaji":"Nihon ni oite, obon wa kazoku ga atsumaru taisetsu na gyouji desu.","zh":""},{"ja":"会議において、彼の意見が一番説得力がありました。","en":"In the meeting, his opinion was the most persuasive.","romaji":"Kaigi ni oite, kare no iken ga ichiban settokuryoku ga arimashita.","zh":""},{"ja":"科学の分野において、研究が日々進んでいます。","en":"In the field of science, research is advancing daily.","romaji":"Kagaku no bun''ya ni oite, kenkyuu ga hibi susunde imasu.","zh":""},{"ja":"幼少期において、子供たちは勢いよく物を覚えます。","en":"During early childhood, children learn things rapidly.","romaji":"Youshouki ni oite, kodomo-tachi wa ikioi yoku mono wo oboemasu.","zh":""}]',replace('**Short**: Indicates the place, time, or context where an action or situation takes place.\n\n**Formation**: Noun (Place/Time/Context) + において\n\n**Long**: The ～において grammar point is used to indicate where an action or situation occurs. It can often be translated as ''in'', ''at'', or ''on'' in English. In some cases, it can also express a specific context or aspect. This grammar point can be used with verbs, adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_kawatte','～にかわって',NULL,NULL,'N3','[]','[{"ja":"彼が病気なので、私が会議に出席することになりました。私が彼にかわって会議に出席します。","en":"He is sick, so I will attend the meeting. I will attend the meeting on his behalf.","romaji":"Kare ga byouki na no de, watashi ga kaigi ni shusseki suru koto ni narimashita. Watashi ga kare ni kawatte kaigi ni shusseki shimasu.","zh":""},{"ja":"母は忙しいので、私が母にかわって料理を作ります。","en":"My mother is busy, so I will cook the meal instead of her.","romaji":"Haha wa isogashii no de, watashi ga haha ni kawatte ryouri wo tsukurimasu.","zh":""},{"ja":"今度の旅行は妹にかわって、私が一緒に行きます。","en":"For this trip, I will go together instead of my younger sister.","romaji":"Kondo no ryokou wa imouto ni kawatte, watashi ga issho ni ikimasu.","zh":""},{"ja":"先生が出張中でいないので、助手が先生にかわってクラスを担当します。","en":"The teacher is not here because of a business trip, so the assistant will take charge of the class instead of the teacher.","romaji":"Sensei ga shucchou chuu de inai no de, joshu ga sensei ni kawatte kurasu wo tantou shimasu.","zh":""}]',replace('**Short**: Expresses ''in place of'', ''on behalf of'', or ''instead of''.\n\n**Formation**: Noun + にかわって\n\n**Long**: The ～にかわって grammar point is used to express that someone or something is acting in place of, on behalf of, or instead of someone or something else. Typically used with nouns (e.g., 人, 会社, etc.).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_shite_wa','～にしては',NULL,NULL,'N3','[]','[{"ja":"彼女は初心者にしては、上手に水泳ができる。","en":"Considering she is a beginner, she can swim well.","romaji":"Kanojo wa shoshinsha ni shite wa, jouzu ni suiei ga dekiru.","zh":""},{"ja":"このお寿司は安いにしては、とても美味しい。","en":"Considering this sushi is cheap, it''s very delicious.","romaji":"Kono o-sushi wa yasui ni shite wa, totemo oishii.","zh":""},{"ja":"彼は若いにしては、とても落ち着いている。","en":"Considering he is young, he is very calm.","romaji":"Kare wa wakai ni shite wa, totemo ochitsuite iru.","zh":""},{"ja":"あの人は外国人にしては、日本語がうまい。","en":"For a foreigner, that person is good at Japanese.","romaji":"Ano hito wa gaikokujin ni shite wa, nihongo ga umai.","zh":""}]',replace('**Short**: Express ''for'' or ''considering'' in the sense of being unusual or unexpected.\n\n**Formation**: Verb-casual + にしては, い-Adjective + にしては, な-Adjective + にしては, Noun + にしては\n\n**Long**: The ～にしては grammar point is used to express that something is unusual or unexpected considering a specific condition or context. It can be translated as ''for'' or ''considering'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_shitemo','～にしても',NULL,NULL,'N3','[]','[{"ja":"雨が降るにしても、学校へ行かなければなりません。","en":"Even if it rains, I have to go to school.","romaji":"Ame ga furu ni shitemo, gakkou e ikanakereba narimasen.","zh":""},{"ja":"彼女が怒っているにしても、話し合いは避けられない。","en":"Even if she is angry, we can''t avoid talking.","romaji":"Kanojo ga okotte iru ni shitemo, hanashiai wa sakerarenai.","zh":""},{"ja":"このレストランが高いにしても、料理の質がよくておすすめです。","en":"Even if this restaurant is expensive, I recommend it because the quality of the food is good.","romaji":"Kono resutoran ga takai ni shitemo, ryouri no shitsu ga yokute osusume desu.","zh":""},{"ja":"彼が有名だにしても、彼の私生活について話すのは失礼だ。","en":"Even if he is famous, it''s rude to talk about his private life.","romaji":"Kare ga yuumei da ni shitemo, kare no shiseikatsu ni tsuite hanasu no wa shitsurei da.","zh":""}]',replace('**Short**: Expresses ''even if'', ''no matter'', ''regardless of''.\n\n**Formation**: Verb-casual + にしても, い-Adjective + にしても, な-Adjective + だにしても, Noun + だにしても\n\n**Long**: The ～にしても grammar point is used to express that even if a certain condition is true or a certain situation occurs, the outcome will not change. It can be translated as ''even if'', ''no matter'', or ''regardless of'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_tsuite','～について',NULL,NULL,'N3','[]','[{"ja":"日本の文化について学びたいです。","en":"I want to learn about Japanese culture.","romaji":"Nihon no bunka ni tsuite manabitai desu.","zh":""},{"ja":"彼の意見について話し合いましょう。","en":"Let''s discuss his opinion.","romaji":"Kare no iken ni tsuite hanashiaimashou.","zh":""},{"ja":"この問題について詳しく教えてください。","en":"Please explain this issue in detail.","romaji":"Kono mondai ni tsuite kuwashiku oshiete kudasai.","zh":""},{"ja":"子供たちの教育について考えなければなりません。","en":"We have to think about the children''s education.","romaji":"Kodomo-tachi no kyouiku ni tsuite kangaenakereba narimasen.","zh":""}]',replace('**Short**: Expressing ''about'', ''concerning'', or ''regarding''.\n\n**Formation**: Noun + について\n\n**Long**: The ～について grammar point is used to express ''about'', ''concerning'', or ''regarding'' a certain topic or subject. It is often used in both casual and formal contexts. The formation is simple – just add について after the noun that represents the topic you are discussing.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_totte','～にとって',NULL,NULL,'N3','[]','[{"ja":"私にとって、健康は一番大切なことです。","en":"For me, health is the most important thing.","romaji":"Watashi ni totte, kenkou wa ichiban taisetsu na koto desu.","zh":""},{"ja":"あの会社にとって、このプロジェクトは重要な意味があります。","en":"For that company, this project has significant meaning.","romaji":"Ano kaisha ni totte, kono purojekuto wa juuyou na imi ga arimasu.","zh":""},{"ja":"子供たちにとって、おもちゃは楽しいものです。","en":"For children, toys are fun things.","romaji":"Kodomotachi ni totte, omocha wa tanoshii mono desu.","zh":""},{"ja":"外国人にとって、日本語は難しい言語の一つです。","en":"For foreigners, Japanese is one of the difficult languages.","romaji":"Gaikokujin ni totte, nihongo wa muzukashii gengo no hitotsu desu.","zh":""}]',replace('**Short**: Express the meaning ''for'', ''to'', ''from the perspective of''.\n\n**Formation**: Noun (person or thing) + にとって + Verb/Adjective/Noun\n\n**Long**: The ～にとって grammar point is used to express the meaning ''for'', ''to'', or ''from the perspective of'' when describing someone or something''s point of view, feelings, benefits, or importance. It is used with all types of words, such as verbs, adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_yotte','～によって',NULL,NULL,'N3','[]','[{"ja":"その事故は悪天候によって引き起こされた。","en":"The accident was caused by bad weather.","romaji":"Sono jiko wa akutenkou ni yotte hikiokosareta.","zh":""},{"ja":"生活習慣によって、健康状態が変わります。","en":"Health conditions change depending on lifestyle habits.","romaji":"Seikatsu shuukan ni yotte, kenkou joutai ga kawarimasu.","zh":""},{"ja":"彼の成功は努力によって得られたものだ。","en":"His success was achieved through hard work.","romaji":"Kare no seikou wa doryoku ni yotte erareta mono da.","zh":""},{"ja":"結果は試験の難易度によって異なります。","en":"The results vary depending on the difficulty of the exam.","romaji":"Kekka wa shiken no nan''ido ni yotte kotonarimasu.","zh":""}]',replace('**Short**: Indicates the reason or cause, difference depending on a factor, or methods used.\n\n**Formation**: Verb-casual + によって, い-Adjective + によって, な-Adjective + によって, Noun + によって\n\n**Long**: The ～によって grammar point is used to express the reason or cause of something, to show a difference depending on a certain factor, or to indicate the method or means by which something is done. It can be translated as ''by'', ''depending on'', ''due to'', or ''according to'' in English. The formation is the same for verbs, い-adjectives, な-adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_yoreba','～によれば',NULL,NULL,'N3','[]','[{"ja":"天気予報によれば、明日は晴れるでしょう。","en":"According to the weather forecast, it will be sunny tomorrow.","romaji":"Tenki yohou ni yoreba, ashita wa hareru deshou.","zh":""},{"ja":"先生によれば、この問題は簡単だそうです。","en":"According to the teacher, this problem seems to be easy.","romaji":"Sensei ni yoreba, kono mondai wa kantan da sou desu.","zh":""},{"ja":"調査によれば、若者の喫煙率が減っているということです。","en":"According to the survey, the smoking rate among young people is decreasing.","romaji":"Chousa ni yoreba, wakamono no kitsuenritsu ga hette iru to iu koto desu.","zh":""},{"ja":"新聞記事によれば、その企業は倒産の危機にあるらしい。","en":"According to the newspaper article, the company appears to be on the verge of bankruptcy.","romaji":"Shinbun kiji ni yoreba, sono kigyou wa tousan no kiki ni aru rashii.","zh":""}]',replace('**Short**: Means ''according to'', ''based on'' or ''by''.\n\n**Formation**: Noun + によれば\n\n**Long**: The ～によれば grammar point is used to express information, opinions or a judgement made based on a certain source. It can be translated as ''according to'', ''based on'', or ''by'' in English. This grammar point is typically used with a noun that represents the source of information.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_taishite_n3','～に対して',NULL,NULL,'N3','[]','[{"ja":"子供たちに対して、親は常にやさしくあるべきです。","en":"Parents should always be kind towards their children.","romaji":"Kodomotachi ni taishite, oya wa tsune ni yasashiku aru beki desu.","zh":""},{"ja":"彼は質問に対して正直に答えました。","en":"He answered the questions honestly.","romaji":"Kare wa shitsumon ni taishite shoujiki ni kotaemashita.","zh":""},{"ja":"田中さんは成功したに対して、佐藤さんは失敗しました。","en":"In contrast to Tanaka-san''s success, Satou-san failed.","romaji":"Tanaka-san wa seikou shita ni taishite, Satou-san wa shippai shimashita.","zh":""},{"ja":"彼の意見に対して、私は反対の立場を取りました。","en":"In response to his opinion, I took an opposing stance.","romaji":"Kare no iken ni taishite, watashi wa hantai no tachiba wo torimashita.","zh":""}]',replace('**Short**: Indicates a target or contrast; ''toward'', ''against'', ''in contrast to'', ''in response to''.\n\n**Formation**: Verb-casual + に対して, い-Adjective + に対して, な-Adjective + に対して, Noun + に対して\n\n**Long**: The ～に対して grammar point is used to indicate the target or direction of an action, or to show a contrast between two situations or objects. It can be translated as ''toward'', ''against'', ''in contrast to'', or ''in response to'' in English. It can be used with verbs, adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_kurabete','～に比べて',NULL,NULL,'N3','[]','[{"ja":"夏に比べて、冬は寒いです。","en":"Winter is cold compared to summer.","romaji":"Natsu ni kurabete, fuyu wa samui desu.","zh":""},{"ja":"このトマトは赤いトマトに比べて美味しくない。","en":"This tomato is not as delicious compared to the red tomatoes.","romaji":"Kono tomato wa akai tomato ni kurabete oishikunai.","zh":""},{"ja":"彼は私に比べて英語が上手です。","en":"He is better at English compared to me.","romaji":"Kare wa watashi ni kurabete eigo ga jouzu desu.","zh":""},{"ja":"東京に比べて、京都は静かな町です。","en":"Kyoto is a quieter city compared to Tokyo.","romaji":"Toukyou ni kurabete, Kyouto wa shizukana machi desu.","zh":""}]',replace('**Short**: Comparing to; in comparison with; as opposed to.\n\n**Formation**: Verb-casual + に比べて, い-Adjective + に比べて, な-Adjective + だ/である + に比べて, Noun + だ/である + に比べて\n\n**Long**: The ～に比べて grammar point is used to compare two things or situations by highlighting their differences. It can be translated as ''comparing to'', ''in comparison with'', or ''as opposed to'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_kanshite','～に関して',NULL,NULL,'N3','[]','[{"ja":"健康に関して気を付けることが大切です。","en":"It is important to be careful regarding health.","romaji":"Kenkou ni kanshite ki wo tsukeru koto ga taisetsu desu.","zh":""},{"ja":"このプロジェクトに関しては、彼がすべての詳細を知っています。","en":"Regarding this project, he knows all the details.","romaji":"Kono purojekuto ni kanshite wa, kare ga subete no shousai wo shitteimasu.","zh":""},{"ja":"環境問題に関して、私たちはもっと責任を持たなければなりません。","en":"Concerning environmental issues, we must take more responsibility.","romaji":"Kankyou mondai ni kanshite, watashitachi wa motto sekinin wo motanakereba narimasen.","zh":""},{"ja":"この事件に関しての情報はまだ十分ではありません。","en":"The information regarding this incident is still insufficient.","romaji":"Kono jiken ni kanshite no jouhou wa mada juubun de wa arimasen.","zh":""}]',replace('**Short**: Regarding, concerning, about, with respect to.\n\n**Formation**: Noun + に関して\n\n**Long**: The ～に関して grammar point is used to express the topic or subject matter one is talking about. It can be translated as ''regarding'', ''concerning'', ''about'', or ''with respect to'' in English. The formation is simple and remains the same regardless of it being used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_no_n3','～の～',NULL,NULL,'N3','[]','[{"ja":"これは私の傘です。","en":"This is my umbrella.","romaji":"Kore wa watashi no kasa desu.","zh":""},{"ja":"あのビルは東京の有名な観光スポットです。","en":"That building is a famous tourist spot in Tokyo.","romaji":"Ano biru wa Toukyou no yuumei na kankou supotto desu.","zh":""},{"ja":"彼は部長の秘書です。","en":"He is the chief''s secretary.","romaji":"Kare wa buchou no hisho desu.","zh":""},{"ja":"彼女は音楽の先生です。","en":"She is a music teacher.","romaji":"Kanojo wa ongaku no sensei desu.","zh":""}]',replace('**Short**: Indicates possession, attribution, or connection between two nouns.\n\n**Formation**: Noun1 + の + Noun2\n\n**Long**: The ～の～ grammar point is used to show the relationship between two nouns in Japanese. It can be translated as ''of'', ''in'', or ''the'' in English. This grammar point is used to indicate possession, attribution, or connection between the two nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_bakari_n3','～ばかり',NULL,NULL,'N3','[]','[{"ja":"彼はゲームばかりしている。","en":"He is always playing games.","romaji":"Kare wa geemu bakari shite iru.","zh":""},{"ja":"この部屋は綺麗なものばかりだ。","en":"This room has nothing but clean things.","romaji":"Kono heya wa kirei na mono bakari da.","zh":""},{"ja":"彼女は勉強ばかりしていて、遊んでいる暇がない。","en":"She is always studying and has no time to play.","romaji":"Kanojo wa benkyou bakari shite ite, asonde iru hima ga nai.","zh":""},{"ja":"彼の話は嘘ばかりで、信じることができない。","en":"His words are nothing but lies, and I cannot believe them.","romaji":"Kare no hanashi wa uso bakari de, shinjiru koto ga dekinai.","zh":""}]',replace('**Short**: Expresses ''only'', ''nothing but'', ''always'', ''just''.\n\n**Formation**: Verb-ますstem + ばかり, い-Adjective + ばかり, な-Adjective + ばかり, Noun + ばかり\n\n**Long**: The ～ばかり grammar point is used to express that something is only, nothing but, always, or just a certain way. It emphasizes the repeated or continuous nature of an action or state. It can be used with verbs, い-adjectives, な-adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mo_n3','～ばかりか (〜bakarika) ～も',NULL,NULL,'N3','[]','[{"ja":"彼女は英語ばかりか、フランス語も話せます。","en":"Not only can she speak English, but she can also speak French.","romaji":"Kanojo wa eigo bakarika, furansugo mo hanasemasu.","zh":""},{"ja":"このレストランは味が良いばかりか、サービスも素晴らしい。","en":"Not only does this restaurant have great taste, but the service is also wonderful.","romaji":"Kono resutoran wa aji ga yoi bakarika, saabisu mo subarashii.","zh":""},{"ja":"パーティは楽しかったばかりか、料理も美味しかった。","en":"Not only was the party fun, but the food was also delicious.","romaji":"Paatii wa tanoshikatta bakarika, ryouri mo oishikatta.","zh":""},{"ja":"彼は頭がいいばかりか、スポーツも得意だ。","en":"Not only is he smart, but he is also good at sports.","romaji":"Kare wa atama ga ii bakarika, supootsu mo tokui da.","zh":""}]',replace('**Short**: Not only... but also; more than just; not just\n\n**Formation**: Verb-casual + ばかりか/も, い-Adjective + ばかりか/も, な-Adjective + だ + ばかりか/も, Noun + だ + ばかりか/も\n\n**Long**: The grammar point ～ばかりか ～も is used to emphasize that something is not limited to only one thing, but also includes another thing. It can be translated as ''not only... but also'', ''more than just'', or ''not just'' in English. This expression is typically used with verbs, adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_hazu_da','～はずだ',NULL,NULL,'N3','[]','[{"ja":"彼はもう着いたはずだ。","en":"He should have arrived by now.","romaji":"Kare wa mou tsuita hazu da.","zh":""},{"ja":"この薬を飲むと、痛みがなくなるはずだ。","en":"If you take this medicine, the pain should go away.","romaji":"Kono kusuri wo nomu to, itami ga nakunaru hazu da.","zh":""},{"ja":"明日は晴れるはずだ。","en":"It is supposed to be sunny tomorrow.","romaji":"Ashita wa hareru hazu da.","zh":""},{"ja":"彼女は元気なはずだ。","en":"She is supposed to be well.","romaji":"Kanojo wa genki na hazu da.","zh":""}]',replace('**Short**: Expresses an expectation, ''should'' or ''it is supposed to''.\n\n**Formation**: Verb-casual + はずだ, い-Adjective + はずだ, な-Adjective + なはずだ, Noun + のはずだ\n\n**Long**: The ～はずだ grammar point is used to express an expectation or belief that something is true, even if it has not been confirmed. It can be translated as ''should'', ''it is supposed to'', or ''ought to'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ba_noni','～ば～のに',NULL,NULL,'N3','[]','[{"ja":"もっと早く来れば、電車に間に合ったのに。","en":"If only I had come earlier, I would have made it to the train.","romaji":"Motto hayaku kureba, densha ni maniatta noni.","zh":""},{"ja":"もっと勉強すれば、試験に合格したのに。","en":"I wish I had studied more, I would have passed the exam.","romaji":"Motto benkyou sureba, shiken ni goukaku shita noni.","zh":""},{"ja":"彼女がもっと優しければ、彼と上手くいくのに。","en":"If only she were kinder, she would get along with him.","romaji":"Kanojo ga motto yasashikereba, kare to umaku iku noni.","zh":""},{"ja":"日本語が上手であれば、この本が読めるのに。","en":"I wish I were good at Japanese, then I could read this book.","romaji":"Nihongo ga jouzu de areba, kono hon ga yomeru noni.","zh":""}]',replace('**Short**: Expresses regret or dissatisfaction; ''if only'', ''wish''.\n\n**Formation**: Verb-ば form + ～のに, い-Adjective-ば form + ～のに, な-Adjective + であれば + ～のに, Noun + であれば + ～のに\n\n**Long**: The ～ば～のに grammar point is used to express regret or dissatisfaction about a situation that didn''t happen or to express a contrary view of the actual situation. It can be translated as ''if only'' or ''wish'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ba_hodo','～ば～ほど',NULL,NULL,'N3','[]','[{"ja":"早く起きれば起きるほど、時間がたくさんある。","en":"The earlier you wake up, the more time you have.","romaji":"Hayaku okireba okiru hodo, jikan ga takusan aru.","zh":""},{"ja":"練習すればするほど、上達します。","en":"The more you practice, the more you will improve.","romaji":"Renshuu sureba suru hodo, joutatsu shimasu.","zh":""},{"ja":"料理が美味しければ美味しいほど、皆が喜びます。","en":"The more delicious the food is, the happier everyone will be.","romaji":"Ryouri ga oishikereba oishii hodo, mina ga yorokobimasu.","zh":""},{"ja":"日本語が上手であれば上手なほど、日本の生活が楽になります。","en":"The better your Japanese is, the easier life in Japan will be.","romaji":"Nihongo ga jouzu de areba jouzu na hodo, Nihon no seikatsu ga raku ni narimasu.","zh":""}]',replace('**Short**: Expresses ''the more ~, the more ~''; a proportional relationship between two phrases.\n\n**Formation**: Verb-casual + ば + Verb-casual + ほど, い-Adjective + ば + い-Adjective + ほど, な-Adjective + であれば + な-Adjective + ほど\n\n**Long**: The ～ば～ほど grammar point is used to express a proportional relationship between two phrases, meaning ''the more A, the more B''. The formation differs depending on whether it is used with a verb, い-adjective, or な-adjective.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wa_mochiron_mo','～はもちろん～も',NULL,NULL,'N3','[]','[{"ja":"彼は数学はもちろん、英語も得意です。","en":"Not only is he good at math, but he is also good at English.","romaji":"Kare wa suugaku wa mochiron, eigo mo tokui desu.","zh":""},{"ja":"このレストランは和食はもちろん、洋食も美味しいです。","en":"This restaurant not only has delicious Japanese food but also delicious Western food.","romaji":"Kono resutoran wa washoku wa mochiron, youshoku mo oishii desu.","zh":""},{"ja":"私の趣味は音楽はもちろん、読書も大好きです。","en":"My hobbies are not only listening to music, but I also love reading.","romaji":"Watashi no shumi wa ongaku wa mochiron, dokusho mo daisuki desu.","zh":""},{"ja":"東京は観光はもちろん、ビジネスも盛んです。","en":"Tokyo is not only famous for sightseeing but also has a thriving business scene.","romaji":"Toukyou wa kankou wa mochiron, bijinesu mo sakan desu.","zh":""}]',replace('**Short**: Used for emphasizing that not only one thing but also another thing is included. It means ''not only... but also'' or ''of course... and...''.\n\n**Formation**: Noun1 + はもちろん + Noun2 + も\n\n**Long**: The ～はもちろん～も grammar point is used to emphasize that not only the first thing mentioned is included, but also the second thing. It can be translated as ''not only... but also'' or ''of course... and...'' in English. This grammar phrase can be used with nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ba_yokatta','～ばよかった',NULL,NULL,'N3','[]','[{"ja":"もっと早く起きればよかった。","en":"I wish I had woken up earlier.","romaji":"Motto hayaku okireba yokatta.","zh":""},{"ja":"昨日のパーティーに行けばよかった。","en":"I wish I had gone to yesterday''s party.","romaji":"Kinou no paatii ni ikeba yokatta.","zh":""},{"ja":"もっと安いものを買えばよかった。","en":"I wish I had bought something cheaper.","romaji":"Motto yasui mono wo kaeba yokatta.","zh":""},{"ja":"あの時、もっと勉強すればよかった。","en":"I wish I had studied more at that time.","romaji":"Ano toki, motto benkyou sureba yokatta.","zh":""}]',replace('**Short**: Express a sense of regret; ''I wish'', ''it would have been better if''.\n\n**Formation**: Verb-ば-form + よかった, い-Adjective-く + ばよかった, な-Adjective + ならよかった\n\n**Long**: The ～ばよかった grammar point is used to express a sense of regret or to convey that one wishes something had been done differently. It can be translated as ''I wish'' or ''it would have been better if'' in English. The formation differs depending on whether it is used with a verb, い-adjective, or な-adjective.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_furi_wo_suru','～ふりをする',NULL,NULL,'N3','[]','[{"ja":"彼は知らないふりをしました。","en":"He pretended not to know.","romaji":"Kare wa shiranai furi wo shimashita.","zh":""},{"ja":"彼女は病気のふりをして、学校を休みました。","en":"She pretended to be sick and skipped school.","romaji":"Kanojo wa byouki no furi wo shite, gakkou wo yasumimashita.","zh":""},{"ja":"彼は嬉しいふりをしていますが、本当は悲しいです。","en":"He is pretending to be happy, but he is actually sad.","romaji":"Kare wa ureshii furi wo shiteimasu ga, hontou wa kanashii desu.","zh":""},{"ja":"彼女はリーダーのふりをして、チームを率いました。","en":"She pretended to be a leader and led the team.","romaji":"Kanojo wa riidaa no furi wo shite, chiimu wo hikimashita.","zh":""}]',replace('**Short**: Pretending or acting as if; ''pretend'', ''act like''.\n\n**Formation**: Verb (dictionary form) + ふりをする, い-Adjective + ふりをする, な-Adjective + ふりをする, Noun + ふりをする\n\n**Long**: The ～ふりをする grammar point is used to express that someone is pretending or acting as if they are doing something, feeling a certain way, or possessing a certain quality. It can be translated as ''pretend'' or ''act like'' in English. The formation is the same for verbs, い-adjectives, な-adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_beki_da','～べきだ',NULL,NULL,'N3','[]','[{"ja":"勉強するべきだ。","en":"You should study.","romaji":"Benkyou suru beki da.","zh":""},{"ja":"早く寝るべきだ。","en":"You should sleep early.","romaji":"Hayaku neru beki da.","zh":""},{"ja":"静かにするべきだ。","en":"You should be quiet.","romaji":"Shizuka ni suru beki da.","zh":""},{"ja":"彼に謝るべきだ。","en":"You should apologize to him.","romaji":"Kare ni ayamaru beki da.","zh":""}]',replace('**Short**: Express an obligation or something that should be done (mainly with verbs).\n\n**Formation**: Verb-dictionary form + べきだ\n\n**Long**: The ～べきだ grammar point is used to express a sense of obligation or to indicate something that should be done. In modern Japanese, it is almost always used with verbs in the dictionary form. In English, it can be translated as ''should'' or ''ought to''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_hodo','～ほど～',NULL,NULL,'N3','[]','[{"ja":"彼女は私ほど速く走ることができません。","en":"She cannot run as fast as me.","romaji":"Kanojo wa watashi hodo hayaku hashiru koto ga dekimasen.","zh":""},{"ja":"このケーキはあのケーキほど美味しくない。","en":"This cake is not as delicious as that cake.","romaji":"Kono keeki wa ano keeki hodo oishikunai.","zh":""},{"ja":"日本ほど四季がはっきりしている国はない。","en":"There is no country with as distinct seasons as Japan.","romaji":"Nihon hodo shiki ga hakkiri shite iru kuni wa nai.","zh":""},{"ja":"東京は大阪ほど人が多くない。","en":"Tokyo does not have as many people as Osaka.","romaji":"Toukyou wa Oosaka hodo hito ga ookunai.","zh":""}]',replace('**Short**: Expresses the degree or extent; ''about'', ''to the extent'', ''as much as''.\n\n**Formation**: Verb-casual + ほど, い-Adjective + ほど, な-Adjective + ほど, Noun + ほど\n\n**Long**: The ～ほど grammar point is used to express the degree or extent of something. It can be translated as ''about'', ''to the extent'', or ''as much as'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_masu_you_ni','～ますように',NULL,NULL,'N3','[]','[{"ja":"明日のテストで良い点をとりますように。","en":"I hope I get good grades on tomorrow''s test.","romaji":"Ashita no tesuto de ii ten wo torimasu you ni.","zh":""},{"ja":"彼が無事に帰ってきますように。","en":"I hope he comes back safely.","romaji":"Kare ga buji ni kaette kimasu you ni.","zh":""},{"ja":"みんなが健康でいられますように。","en":"I hope everyone stays healthy.","romaji":"Minna ga kenkou de iraremasu you ni.","zh":""},{"ja":"彼女に幸せになりますように。","en":"I hope she becomes happy.","romaji":"Kanojo ni shiawase ni narimasu you ni.","zh":""}]',replace('**Short**: Used to express a wish or hope for oneself or someone else.\n\n**Formation**: Verb-ます form, remove final る + ように\n\n**Long**: The ～ますように grammar point is used to express a wish or hope. It is often used as a closing phrase in letters or messages, and can be applied to both oneself and others. The phrase is typically used with the ます form of the verb, with the final る replaced by ように.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mattaku_nai','まったく～ない',NULL,NULL,'N3','[]','[{"ja":"彼は、まったく覚えていない。","en":"He doesn''t remember at all.","romaji":"Kare wa, mattaku oboete inai.","zh":""},{"ja":"この部屋はまったく暖かくない。","en":"This room is not warm at all.","romaji":"Kono heya wa mattaku atatakakunai.","zh":""},{"ja":"彼女はまったく遅れていない。","en":"She is not late at all.","romaji":"Kanojo wa mattaku okurete inai.","zh":""},{"ja":"これはまったく便利ではない。","en":"This is not convenient at all.","romaji":"Kore wa mattaku benri de wa nai.","zh":""}]',replace('**Short**: Completely not; not at all.\n\n**Formation**: まったく + Verb-negative, まったく + い-Adjective-negative, まったく + な-Adjective-negative\n\n**Long**: The まったく～ない grammar point is used to express that something is not the case at all, or to emphasize the negativity of a situation or action. It is used with negative forms of verbs, い-adjectives, and な-adjectives. It can be translated as ''completely not'' or ''not at all'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_made_n3','～まで',NULL,NULL,'N3','[]','[{"ja":"10時まで働きます。","en":"I will work until 10 o''clock.","romaji":"Ju-ji made hatarakimasu.","zh":""},{"ja":"東京まで電車で行きます。","en":"I will go by train as far as Tokyo.","romaji":"Toukyou made densha de ikimasu.","zh":""},{"ja":"彼は疲れるまで走りました。","en":"He ran until he got tired.","romaji":"Kare wa tsukareru made hashirimashita.","zh":""},{"ja":"5ページまで読んでください。","en":"Please read up to page 5.","romaji":"Go-peeji made yonde kudasai.","zh":""}]',replace('**Short**: Express ''until'', ''up to'', or ''as far as'' to indicate the end point of an action or range.\n\n**Formation**: Verb-casual + まで, い-Adjective + まで, な-Adjective + まで, Noun + まで\n\n**Long**: The ～まで grammar point is used to express the end point, limit, or extent of an action or range in terms of time, space, or quantity. It can be translated as ''until'', ''up to'', or ''as far as'' in English. The formation depends on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mama_n3','～まま',NULL,NULL,'N3','[]','[{"ja":"部屋の窓を開けたまま寝ました。","en":"I slept with the window of the room open.","romaji":"Heya no mado wo aketa mama nemashita.","zh":""},{"ja":"熱いままのコーヒーを飲んで、舌を焦がしました。","en":"I drank the coffee while it was still hot and burned my tongue.","romaji":"Atsui mama no koohii wo nonde, shita wo kogashimashita.","zh":""},{"ja":"彼は忙しいなまま、休みの日も仕事をしています。","en":"He continues to be busy, working even on his days off.","romaji":"Kare wa isogashii na mama, yasumi no hi mo shigoto wo shiteimasu.","zh":""},{"ja":"彼女は故郷にいるまま、外国に行かないで仕事を見つけた。","en":"She found a job without going abroad, staying in her hometown.","romaji":"Kanojo wa furusato ni iru mama, gaikoku ni ikanaide shigoto wo mitsuketa.","zh":""}]',replace('**Short**: Expresses the state or condition remaining unchanged.\n\n**Formation**: Verb-ます stem + まま, い-Adjective + まま, な-Adjective + なまま, Noun + のまま\n\n**Long**: The 〜まま grammar point is used to indicate that a state or condition remains unchanged or continues as it is, without any change or intervention. It can be used with verbs, い-adjectives, な-adjectives, and nouns to express the idea of something being left, kept, or maintained in its current state.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_maru_de_you','まるで～よう',NULL,NULL,'N3','[]','[{"ja":"彼女はまるで天使のように美しい。","en":"She is as beautiful as an angel.","romaji":"Kanojo wa maru de tenshi no you ni utsukushii.","zh":""},{"ja":"彼はまるでロボットのように仕事をしている。","en":"He works as if he is a robot.","romaji":"Kare wa maru de robotto no you ni shigoto wo shite iru.","zh":""},{"ja":"あの家はまるでお城のようだ。","en":"That house is just like a castle.","romaji":"Ano ie wa maru de oshiro no you da.","zh":""},{"ja":"ここはまるで楽園のような場所です。","en":"This place is as though it''s a paradise.","romaji":"Koko wa maru de rakuen no you na basho desu.","zh":""}]',replace('**Short**: Used to express a strong resemblance or similarity; ''as if'', ''just like'', ''as though''.\n\n**Formation**: まるで + phrase/sentence + よう\n\n**Long**: The まるで～よう grammar point is used to emphasize a strong resemblance or similarity between two things or situations. It can be translated as ''as if'', ''just like'', or ''as though'' in English. The formation is まるで + phrase/sentence + よう.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_miru_n3','～てみる',NULL,NULL,'N3','[]','[{"ja":"彼は走ってみたが、まだ膝が痛いと感じた。","en":"He tried running, but he still felt pain in his knee.","romaji":"Kare wa hashitte mita ga, mada hiza ga itai to kanjita.","zh":""},{"ja":"彼女は料理を作ってみたが、失敗してしまった。","en":"She tried cooking but ended up failing.","romaji":"Kanojo wa ryouri o tsukutte mita ga, shippai shite shimatta.","zh":""},{"ja":"初めてのデートで、彼は彼女にサプライズをしようと考え、歌ってみた。","en":"On their first date, he thought of surprising her and tried singing.","romaji":"Hajimete no deeto de, kare wa kanojo ni sapuraizu o shiyou to kangae, utatte mita.","zh":""},{"ja":"このケーキは美味しそうだから、味見に食べてみる。","en":"Since this cake looks delicious, I will try tasting it.","romaji":"Kono keeki wa oishisou dakara, ajimi ni tabete miru.","zh":""}]',replace('**Short**: A grammar structure used to express the action of trying or attempting something to see what happens.\n\n**Formation**: Verb-て form + みる\n\n**Long**: The 〜てみる grammar point is used with a verb in the 〜て form followed by みる. It emphasizes doing something as a trial or to see the result. It often translates as ''to try doing something'' or ''try it out''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mitai_da_n3','～みたいだ',NULL,NULL,'N3','[]','[{"ja":"彼は怒っているみたいだ。","en":"He seems to be angry.","romaji":"Kare wa okotte iru mitai da.","zh":""},{"ja":"そのビルは古いみたいだ。","en":"That building looks old.","romaji":"Sono biru wa furui mitai da.","zh":""},{"ja":"彼女は疲れているみたいだ。","en":"She seems to be tired.","romaji":"Kanojo wa tsukarete iru mitai da.","zh":""},{"ja":"この料理は辛いみたいだ。","en":"This dish seems to be spicy.","romaji":"Kono ryouri wa karai mitai da.","zh":""}]',replace('**Short**: Express similarity or appearance; ''like'', ''seems'', ''looks''.\n\n**Formation**: Verb-casual + みたいだ, い-Adjective + みたいだ, な-Adjective + みたいだ, Noun + みたいだ\n\n**Long**: The ～みたいだ grammar point is used to express similarity, appearance or resemblance to something. It can be translated as ''like'', ''seems'', or ''looks'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_metta_ni_nai_n3','～めったに～ない',NULL,NULL,'N3','[]','[{"ja":"彼はめったに外食しない。","en":"He hardly ever eats out.","romaji":"Kare wa metta ni gaishoku shinai.","zh":""},{"ja":"私はめったに寿司を食べない。","en":"I seldom eat sushi.","romaji":"Watashi wa metta ni sushi wo tabenai.","zh":""},{"ja":"この地域はめったに雪が降らない。","en":"It hardly ever snows in this area.","romaji":"Kono chiiki wa metta ni yuki ga furanai.","zh":""},{"ja":"彼女はめったに怒らない。","en":"She hardly ever gets angry.","romaji":"Kanojo wa metta ni okoranai.","zh":""}]',replace('**Short**: Used to express that something rarely, hardly ever or seldom happens.\n\n**Formation**: めったに + Verb[ない-form] / めったに + い-Adjective[ない-form] / めったに + な-Adjective[じゃない/ではない-form]\n\n**Long**: The ～めったに～ない grammar point is used to express that something rarely, hardly ever or seldom happens. It is a negative expression and always needs to be used with ～ない (negative form) at the end.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_metta_ni_nai_n3_2','～めったにない',NULL,NULL,'N3','[]','[{"ja":"この町では雪が降ることはめったにない。","en":"It hardly ever snows in this town.","romaji":"Kono machi de wa yuki ga furu koto wa metta ni nai.","zh":""},{"ja":"彼はめったに外食しない。","en":"He rarely eats out.","romaji":"Kare wa metta ni gaishoku shinai.","zh":""},{"ja":"友達が遊びに来るのはめったにない。","en":"Friends seldom come to visit.","romaji":"Tomodachi ga asobi ni kuru no wa metta ni nai.","zh":""},{"ja":"彼女はめったに怒らない。","en":"She hardly ever gets angry.","romaji":"Kanojo wa metta ni okoranai.","zh":""}]',replace('**Short**: Expresses the rarity of an action, event or state; ''hardly'', ''rarely'', ''seldom''.\n\n**Formation**: Verb-negative + めったにない, い-Adjective-negative + めったにない, な-Adjective-negative + めったにない, Noun-negative + めったにない\n\n**Long**: The ～めったにない grammar point is used to express that an action, event or state rarely, hardly, or seldom happens. It is usually combined with a negative verb form. Though it can be used with positive verbs, it is uncommon and sounds unnatural.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_moshikasuru_to_kamoshirenai','もしかすると〜かもしれない',NULL,NULL,'N3','[]','[{"ja":"もしかすると彼は遅刻するかもしれない。","en":"Maybe he might be late.","romaji":"Moshikasuru to kare wa chikoku suru kamoshirenai.","zh":""},{"ja":"もしかすると彼女は疲れているかもしれない。","en":"Perhaps she might be tired.","romaji":"Moshikasuru to kanojo wa tsukarete iru kamoshirenai.","zh":""},{"ja":"もしかすると雨が降るかもしれない。","en":"It might rain, maybe.","romaji":"Moshikasuru to ame ga furu kamoshirenai.","zh":""},{"ja":"もしかすると彼らはその映画が好きじゃないかもしれない。","en":"Maybe they might not like that movie.","romaji":"Moshikasuru to karera wa sono eiga ga suki janai kamoshirenai.","zh":""}]',replace('**Short**: Express the possibility of something; ''maybe'', ''perhaps'', ''might''.\n\n**Formation**: もしかすると + Sentence + かもしれない\n\n**Long**: The もしかすると〜かもしれない grammar point is used to indicate that there might be a possibility of a certain situation happening or someone feeling a certain way. This structure is often used to describe uncertain situations and can be translated into English as ''maybe'', ''perhaps'', or ''might''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_moshi_tanara','もし～たなら',NULL,NULL,'N3','[]','[{"ja":"もし雨が降ったなら、傘を持って行きましょう。","en":"If it rains, let''s bring an umbrella.","romaji":"Moshi ame ga futta nara, kasa wo motte ikimashou.","zh":""},{"ja":"もしケーキが美味しくなかったなら、誰も食べないでしょう。","en":"If the cake was not delicious, nobody would eat it.","romaji":"Moshi keeki ga oishikunakatta nara, daremo tabenai deshou.","zh":""},{"ja":"もし彼が病気だったなら、すぐに病院に行かせてあげてください。","en":"If he was sick, please take him to the hospital right away.","romaji":"Moshi kare ga byouki datta nara, sugu ni byouin ni ikasete agete kudasai.","zh":""},{"ja":"もし彼女が学生だったなら、このレストランは割引があるでしょう。","en":"If she were a student, there would be a discount at this restaurant.","romaji":"Moshi kanojo ga gakusei datta nara, kono resutoran wa waribiki ga aru deshou.","zh":""}]',replace('**Short**: Express a hypothetical condition, ''if'' or ''in case''.\n\n**Formation**: もし + Verb-casual past + なら, もし + い-Adjective-casual past + なら, もし + な-Adjective + だったなら, もし + Noun + だったなら\n\n**Long**: The もし～たなら grammar point is used to express a hypothetical condition or situation in a more polite manner. It emphasizes the conditional part of a sentence and can be translated as ''if'' or ''in case'' in English. It is mainly used with verbs in the past tense, casual form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_moshi_temo','もし～ても',NULL,NULL,'N3','[]','[{"ja":"もし雨が降っても、ピクニックに行きます。","en":"Even if it rains, we will go on a picnic.","romaji":"Moshi ame ga futtemo, pikunikku ni ikimasu.","zh":""},{"ja":"もし彼が謝っても、まだ怒っているでしょう。","en":"Even if he apologizes, I will still be angry.","romaji":"Moshi kare ga ayamattemo, mada okotteiru deshou.","zh":""},{"ja":"もし試験に合格しても、まだ勉強を続けます。","en":"Even if I pass the exam, I will still continue studying.","romaji":"Moshi shiken ni goukaku shitemo, mada benkyou wo tsuzukemasu.","zh":""},{"ja":"もし彼女が遅く来ても、待っています。","en":"Even if she comes late, I will wait.","romaji":"Moshi kanojo ga osoku kite mo, matteimasu.","zh":""}]',replace('**Short**: Express a hypothetical situation or assumption with the nuance of ''even if''.\n\n**Formation**: もし + Verb-て form + も / もし + い-Adjective(く) + ても / もし + な-Adjective/Noun + でも\n\n**Long**: The もし～ても grammar point is used to describe a situation in which even if the stated condition is true, the result or decision does not change. It can be translated as ''even if'', ''no matter if'', or ''suppose ~''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_moshimo_nara','もしも～なら',NULL,NULL,'N3','[]','[{"ja":"もしも明日雨が降ったなら、出かけません。","en":"If it rains tomorrow, I won''t go out.","romaji":"Moshimo ashita ame ga futta nara, dekakemasen.","zh":""},{"ja":"もしも彼が来なかったなら、私たちだけでパーティーをします。","en":"If he doesn''t come, we''ll have the party just by ourselves.","romaji":"Moshimo kare ga konakatta nara, watashitachi dake de paatii wo shimasu.","zh":""},{"ja":"もしも彼女が疲れているなら、休ませてあげてください。","en":"If she is tired, please let her rest.","romaji":"Moshimo kanojo ga tsukarete iru nara, yasumasete agete kudasai.","zh":""},{"ja":"もしもそれが真実なら、認めなければなりません。","en":"If that is true, we have to admit it.","romaji":"Moshimo sore ga shinjitsu nara, mitomenakereba narimasen.","zh":""}]',replace('**Short**: Express a hypothetical condition or situation; ''if'', ''in case'', ''suppose''.\n\n**Formation**: Verb-casual + なら, い-Adjective + なら, な-Adjective + なら, Noun + なら\n\n**Long**: The もしも～なら grammar point is used to express a hypothetical condition or situation, often with a sense of uncertainty. It can be translated as ''if'', ''in case'', or ''suppose''. The formation varies slightly based on whether it is used with a verb, an い-adjective, a な-adjective, or a noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_you_to_shinai','～ようとしない',NULL,NULL,'N3','[]','[{"ja":"彼は勉強しようとしない。","en":"He doesn''t show any sign of trying to study.","romaji":"Kare wa benkyou shiyou to shinai.","zh":""},{"ja":"彼女は謝ろうとしない。","en":"She doesn''t show any intention of apologizing.","romaji":"Kanojo wa ayamarou to shinai.","zh":""},{"ja":"息子は部屋を片付けようとしない。","en":"My son doesn''t show any intention of cleaning his room.","romaji":"Musuko wa heya wo katazuke you to shinai.","zh":""},{"ja":"犬は散歩に行こうとしない。","en":"The dog doesn''t show any sign of wanting to go for a walk.","romaji":"Inu wa sanpo ni ikou to shinai.","zh":""}]',replace('**Short**: Not showing any sign or intention to do something.\n\n**Formation**: Verb-volitional form + としない\n\n**Long**: The ～ようとしない grammar point indicates that someone is not showing any sign or intention of doing an action. It is used to express a refusal or unwillingness to do something. It is formed by using the volitional form of a verb followed by としない.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_you_to_omou','～ようと思う',NULL,NULL,'N3','[]','[{"ja":"今日は早く寝ようと思います。","en":"I think I will go to bed early today.","romaji":"Kyou wa hayaku neyou to omoimasu.","zh":""},{"ja":"明日美術館に行こうと思っています。","en":"I am planning to go to the art museum tomorrow.","romaji":"Ashita bijutsukan ni ikou to omotteimasu.","zh":""},{"ja":"新しいカメラを買おうと思います。","en":"I think I will buy a new camera.","romaji":"Atarashii kamera wo kaou to omoimasu.","zh":""},{"ja":"来週友達と映画を見ようと思っています。","en":"I am planning to watch a movie with my friend next week.","romaji":"Raishuu tomodachi to eiga wo miyou to omotteimasu.","zh":""}]',replace('**Short**: Expresses the speaker''s intention or plan to do something.\n\n**Formation**: Verb-volitional + と思う\n\n**Long**: The ～ようと思う grammar point is used to express the speaker''s intention or plan to do something in the future. It can be translated as ''I think I will...'' or ''I am planning to...'' in English. It is formed by taking the volitional form of a verb and adding と思う.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_you_ni_n3','～ように',NULL,NULL,'N3','[]','[{"ja":"早く家に帰るように、仕事を急いで終わらせました。","en":"In order to get home early, I hurried to finish my work.","romaji":"Hayaku ie ni kaeru you ni, shigoto wo isoide owarasemashita.","zh":""},{"ja":"彼女は美しい花のように見えました。","en":"She looked like a beautiful flower.","romaji":"Kanojo wa utsukushii hana no you ni miemashita.","zh":""},{"ja":"この部屋がきれいになるように、掃除をしましょう。","en":"Let''s clean so that this room becomes clean.","romaji":"Kono heya ga kirei ni naru you ni, souji wo shimashou.","zh":""},{"ja":"山田さんは元気なように振る舞っていましたが、実際は疲れているらしいです。","en":"Yamada-san was acting as if he was energetic, but he actually seems to be tired.","romaji":"Yamada-san wa genki na you ni furumatte imashita ga, jissai wa tsukarete iru rashii desu.","zh":""}]',replace('**Short**: Expressing a purpose, a goal or a way of doing something; ''in order to'', ''so that'', ''like'', ''as''\n\n**Formation**: Verb-casual + ように, い-Adjective + ように, な-Adjective + に, Noun + のように\n\n**Long**: The ～ように grammar point is used to express a purpose, a goal, or a way of doing something. It can be translated as ''in order to'', ''so that'', ''like'', or ''as'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_you_ni_n3_2','～ように',NULL,NULL,'N3','[]','[{"ja":"子供が安全に過ごせるように、家の中を整理します。","en":"I will organize the inside of the house so that the children can spend time safely.","romaji":"Kodomo ga anzen ni sugoseru you ni, ie no naka wo seiri shimasu.","zh":""},{"ja":"美しい花のように、彼女は笑顔が素敵です。","en":"Like a beautiful flower, her smile is lovely.","romaji":"Utsukushii hana no you ni, kanojo wa egao ga suteki desu.","zh":""},{"ja":"自然に英語を話せるように、毎日練習しています。","en":"I practice every day to be able to speak English naturally.","romaji":"Shizen ni eigo wo hanaseru you ni, mainichi renshuu shiteimasu.","zh":""},{"ja":"成功するように、計画を立てましょう。","en":"Let''s make a plan to succeed.","romaji":"Seikou suru you ni, keikaku wo tatemashou.","zh":""}]',replace('**Short**: Used to express a purpose, a way, or a natural tendency.\n\n**Formation**: Verb-casual + ように, い-Adjective + ように, な-Adjective + だように, Noun + のように\n\n**Long**: The ～ように grammar point is used to express a purpose, a way or a method, or a natural tendency. It can be used with verbs, い-adjectives, な-adjectives, or nouns. It is frequently used with the verb する (to do) to express the purpose or method.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_you_ni_n3_3','～ように',NULL,NULL,'N3','[]','[{"ja":"分かりやすいように説明してください。","en":"Please explain it in a way that is easy to understand.","romaji":"Wakariyasui you ni setsumei shite kudasai.","zh":""},{"ja":"彼は鳥のように歌います。","en":"He sings like a bird.","romaji":"Kare wa tori no you ni utaimasu.","zh":""},{"ja":"友達と仲良くするように努めています。","en":"I am trying to get along well with my friends.","romaji":"Tomodachi to nakayoku suru you ni tsutometeimasu.","zh":""},{"ja":"日本語が上手になるように勉強しています。","en":"I am studying to become better at Japanese.","romaji":"Nihongo ga jouzu ni naru you ni benkyou shiteimasu.","zh":""}]',replace('**Short**: Used to express purpose or how something is done; ''like'', ''as if'', ''in order to''.\n\n**Formation**: Verb-casual + ように, い-Adjective + ように, な-Adjective + に, Noun + のように\n\n**Long**: The ～ように grammar point is used to express the purpose of an action or the manner in which something is done. It can be translated as ''like'', ''as if'', or ''in order to'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_you_ni_shimashou','～ようにしましょう',NULL,NULL,'N3','[]','[{"ja":"毎日運動するようにしましょう。","en":"Let''s try to exercise every day.","romaji":"Mainichi undou suru you ni shimashou.","zh":""},{"ja":"早く寝るようにしましょう。","en":"Let''s make sure to go to bed early.","romaji":"Hayaku neru you ni shimashou.","zh":""},{"ja":"親切にするようにしましょう。","en":"Let''s try to be kind.","romaji":"Shinsetsu ni suru you ni shimashou.","zh":""},{"ja":"時間を無駄にしないようにしましょう。","en":"Let''s make sure not to waste time.","romaji":"Jikan wo muda ni shinai you ni shimashou.","zh":""}]',replace('**Short**: A suggestion to make an effort or try to do something; ''let''s try to'', ''let''s make sure to''.\n\n**Formation**: Verb-dictionary form + ようにしましょう / Verb-negative form + ようにしましょう\n\n**Long**: The ～ようにしましょう grammar point is used to suggest making an effort or trying to do something. It can be translated as ''let''s try to'' or ''let''s make sure to'' in English. Typically, we use the dictionary or negative form of the verb with ようにする/ようにしましょう to show the effort we want to make.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_you_ni_natta','～ようになった',NULL,NULL,'N3','[]','[{"ja":"彼は料理を作るようになった。","en":"He became able to cook.","romaji":"Kare wa ryouri wo tsukuru you ni natta.","zh":""},{"ja":"その子は読めるようになった。","en":"That child started to be able to read.","romaji":"Sono ko wa yomeru you ni natta.","zh":""},{"ja":"会議は週に一度開催されるようになった。","en":"The meeting started to be held once a week.","romaji":"Kaigi wa shuu ni ichido kaisai sareru you ni natta.","zh":""},{"ja":"日本語がわかるようになった。","en":"I became able to understand Japanese.","romaji":"Nihongo ga wakaru you ni natta.","zh":""}]',replace('**Short**: Express an event or state that became possible; ''became able to'', ''started to'', ''now can''.\n\n**Formation**: Verb-casual + ようになった\n\n**Long**: The ～ようになった grammar point is used to express that an event, ability, or state has become possible or started to occur. It can be translated as ''became able to'', ''started to'', or ''now can'' in English. Usually this is used with verbs in their dictionary or potential form (e.g., 食べられるようになった).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_you_ni_iu','～ように言う',NULL,NULL,'N3','[]','[{"ja":"先生は私にもっと勉強するように言った。","en":"The teacher told me to study more.","romaji":"Sensei wa watashi ni motto benkyou suru you ni itta.","zh":""},{"ja":"彼女は彼に待つように言いました。","en":"She told him to wait.","romaji":"Kanojo wa kare ni matsu you ni iimashita.","zh":""},{"ja":"母は私に部屋を片付けるように言いました。","en":"My mother told me to clean my room.","romaji":"Haha wa watashi ni heya wo katazukeru you ni iimashita.","zh":""},{"ja":"先生は生徒に質問をするように言った。","en":"The teacher told the student to ask a question.","romaji":"Sensei wa seito ni shitsumon wo suru you ni itta.","zh":""}]',replace('**Short**: To convey a message, instruction or request to someone; ''to tell (someone) to'', ''to say to (someone)''.\n\n**Formation**: Verb-dictionary form + ように言う / Verb-nai form + ように言う\n\n**Long**: The ～ように言う grammar point is used to convey a message, instruction or request to someone. It can be translated as ''to tell (someone) to'' or ''to say to (someone)''. It is commonly formed by taking the dictionary (or negative) form of the verb plus ように言う.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_rashii','～らしい',NULL,NULL,'N3','[]','[{"ja":"彼はインフルエンザらしい。","en":"Apparently, he has the flu.","romaji":"Kare wa infuruenza rashii.","zh":""},{"ja":"明日雪が降るらしい。","en":"I heard it will snow tomorrow.","romaji":"Ashita yuki ga furu rashii.","zh":""},{"ja":"このレストランは美味しいらしい。","en":"I heard that this restaurant is delicious.","romaji":"Kono resutoran wa oishii rashii.","zh":""},{"ja":"彼女は医者だらしい。","en":"It seems that she is a doctor.","romaji":"Kanojo wa isha darashii.","zh":""}]',replace('**Short**: Expresses hearsay; ''I heard'', ''it seems'', ''apparently''.\n\n**Formation**: Verb-casual + らしい, い-Adjective + らしい, な-Adjective + だらしい, Noun + だらしい\n\n**Long**: The ～らしい grammar point is used to indicate that the information provided is based on hearsay or an indirect source. In English, this can be translated as ''I heard'', ''it seems'', or ''apparently''. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_rareta','～られた',NULL,NULL,'N3','[]','[{"ja":"この本はたくさんの人に読まれた。","en":"This book was read by many people.","romaji":"Kono hon wa takusan no hito ni yomareta.","zh":""},{"ja":"彼は友達に騙された。","en":"He was deceived by his friend.","romaji":"Kare wa tomodachi ni damasareta.","zh":""},{"ja":"昨日、私の財布が盗まれました。","en":"Yesterday, my wallet was stolen.","romaji":"Kinou, watashi no saifu ga nusumaremashita.","zh":""},{"ja":"彼女は映画に感動させられた。","en":"She was deeply moved by the movie.","romaji":"Kanojo wa eiga ni kandou saserareta.","zh":""}]',replace('**Short**: Express a passive action, ''was/were'', ''has/have been''.\n\n**Formation**: Verb (passive form, past tense) + られた\n\n**Long**: The ～られた grammar point is used to express a passive action or situation. It is formed by conjugating the verb into its passive form in the past tense, which can be translated into English as ''was/were'' or ''has/have been''. This grammar is used in situations where the subject is affected by an action rather than performing the action itself.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_iru','～ている',NULL,NULL,'N3','[]','[{"ja":"窓が開けられている。","en":"The window is open (someone opened it and it remains open).","romaji":"Mado ga akerarete iru.","zh":""},{"ja":"ケーキが全部食べられている。","en":"The whole cake has been eaten.","romaji":"Keeki ga zenbu taberarete iru.","zh":""},{"ja":"彼女は病気で寝込んでいる。","en":"She is bedridden due to illness.","romaji":"Kanojo wa byouki de nekonde iru.","zh":""},{"ja":"宿題が終わっている。","en":"The homework is finished (has been done).","romaji":"Shukudai ga owatte iru.","zh":""}]',replace('**Short**: Expresses a continuing action or a resulting state; ''is ~ing'', ''has been'', ''has''.\n\n**Formation**: Verb-て form + いる\n\n**Long**: The ～ている grammar point is used to describe a continuing or repeated action, or the result/state of a completed action. Depending on the context, it can be translated as ''is ~ing'', ''has been ~ed'', or simply ''has/are/is''. In passive contexts (e.g., 食べられている, 開けられている), it shows that something has been done and remains in that state. With intransitive or non-passive verbs, it shows an ongoing or resultant state (e.g., 寝込んでいる, 終わっている).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wake_ga_nai_n3','～わけがない',NULL,NULL,'N3','[]','[{"ja":"彼がそんなことを言うわけがない。","en":"There''s no way he would say something like that.","romaji":"Kare ga sonna koto wo iu wake ga nai.","zh":""},{"ja":"あのレストランがまずいわけがない。","en":"There''s no way that restaurant tastes bad.","romaji":"Ano resutoran ga mazui wake ga nai.","zh":""},{"ja":"彼女が優しくないわけがない。","en":"There''s no way she''s not kind.","romaji":"Kanojo ga yasashiku nai wake ga nai.","zh":""},{"ja":"彼が試験に合格しないわけがない。","en":"There''s no way he won''t pass the exam.","romaji":"Kare ga shiken ni goukaku shinai wake ga nai.","zh":""}]',replace('**Short**: Expresses that something is impossible or unreasonable; ''there''s no way'', ''can''t be''.\n\n**Formation**: Verb-casual + わけがない, い-Adjective + わけがない, な-Adjective + なわけがない, Noun + のわけがない\n\n**Long**: The ～わけがない grammar point is used to show that something is impossible, non-existent, or unreasonable based on logic or context. It is often translated as ''there''s no way'' or ''it''s impossible''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wake_da_n3','～わけだ',NULL,NULL,'N3','[]','[{"ja":"彼は風邪を引いている。だから、声がかすれているわけだ。","en":"He has a cold. That''s why his voice is hoarse.","romaji":"Kare wa kaze wo hiite iru. Dakara, koe ga kasurete iru wake da.","zh":""},{"ja":"今日は忙しかった。だから、疲れたわけだ。","en":"Today was busy. No wonder I''m tired.","romaji":"Kyou wa isogashikatta. Dakara, tsukareta wake da.","zh":""},{"ja":"田中さんはたくさん勉強している。だから、試験に合格したわけだ。","en":"Tanaka has been studying a lot. It means he passed the exam.","romaji":"Tanaka-san wa takusan benkyou shite iru. Dakara, shiken ni goukaku shita wake da.","zh":""},{"ja":"彼女は有名な歌手の娘なんだ。だから、歌が上手なわけだ。","en":"She''s the daughter of a famous singer. That''s why she''s good at singing.","romaji":"Kanojo wa yuumei na kashu no musume nan da. Dakara, uta ga jouzu na wake da.","zh":""}]',replace('**Short**: Expresses a logical conclusion or reason based on information; ''that''s why'', ''no wonder'', ''it means''.\n\n**Formation**: Verb-casual + わけだ, い-Adjective + わけだ, な-Adjective + なわけだ, Noun + のわけだ\n\n**Long**: The ～わけだ grammar point is used to express a conclusion, reason, or interpretation based on a certain situation or piece of information. It can be translated as ''that''s why'', ''no wonder'', or ''it means''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wake_dewa_nai_n3','～わけではない',NULL,NULL,'N3','[]','[{"ja":"彼が忙しいからといって、友達がいないわけではない。","en":"Just because he''s busy doesn''t mean he has no friends.","romaji":"Kare ga isogashii kara to itte, tomodachi ga inai wake dewa nai.","zh":""},{"ja":"この映画は面白くないわけではないが、好みではない。","en":"It''s not that this movie isn''t interesting; it''s just not my taste.","romaji":"Kono eiga wa omoshirokunai wake dewa nai ga, konomi dewa nai.","zh":""},{"ja":"彼女が病気だからといって、毎日寝ているわけではない。","en":"Just because she''s sick doesn''t mean she''s in bed all day.","romaji":"Kanojo ga byouki dakara to itte, mainichi nete iru wake dewa nai.","zh":""},{"ja":"彼が大学に行っていないからといって、バカだわけではない。","en":"Just because he didn''t go to college doesn''t mean he''s stupid.","romaji":"Kare ga daigaku ni itte inai kara to itte, baka da wake dewa nai.","zh":""}]',replace('**Short**: Denies a general assumption; ''it does not mean that'', ''it''s not the case''.\n\n**Formation**: Verb-casual + わけではない, い-Adjective + わけではない, な-Adjective + だわけではない, Noun + だわけではない\n\n**Long**: The ～わけではない grammar point is used to deny or correct a general assumption or statement without completely negating the situation. It often emphasizes one particular point that is not true, while acknowledging other possibilities.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wake_ni_wa_ikanai_n3','～わけにはいかない',NULL,NULL,'N3','[]','[{"ja":"こんなところで寝るわけにはいかない。","en":"I can''t possibly sleep in a place like this.","romaji":"Konna tokoro de neru wake ni wa ikanai.","zh":""},{"ja":"試験が明日だから、遊びに行くわけにはいかない。","en":"I can''t afford to go out to have fun, since the exam is tomorrow.","romaji":"Shiken ga ashita dakara, asobi ni iku wake ni wa ikanai.","zh":""},{"ja":"こんなに高いものを買うわけにはいかない。","en":"I can''t allow myself to purchase something so expensive.","romaji":"Konna ni takai mono wo kau wake ni wa ikanai.","zh":""},{"ja":"体調が悪いから、パーティーに参加するわけにはいかない。","en":"Since I''m not feeling well, I can''t attend the party.","romaji":"Taichou ga warui kara, paatii ni sanka suru wake ni wa ikanai.","zh":""}]',replace('**Short**: Expresses that something cannot be allowed or permitted due to social/moral obligations.\n\n**Formation**: Verb-casual + わけにはいかない\n\n**Long**: The ～わけにはいかない grammar point is used to express that a particular action cannot be taken due to social or moral obligations, responsibilities, or natural consequences. It often translates as ''I can''t afford to...'' or ''I can''t just...'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wari_ni_wa','～わりには',NULL,NULL,'N3','[]','[{"ja":"彼はあまり勉強しないわりには、テストの点数が高いです。","en":"Despite not studying much, he gets high scores on tests.","romaji":"Kare wa amari benkyou shinai wari ni wa, tesuto no tensuu ga takai desu.","zh":""},{"ja":"この料理は見た目が悪いわりには、味は美味しいです。","en":"Even though this dish doesn''t look good, it tastes delicious.","romaji":"Kono ryouri wa mitame ga warui wari ni wa, aji wa oishii desu.","zh":""},{"ja":"彼女は若いわりには、とても落ち着いていますね。","en":"Considering she''s young, she''s very calm.","romaji":"Kanojo wa wakai wari ni wa, totemo ochitsuite imasu ne.","zh":""},{"ja":"この部屋は狭いわりには、家賃が高いです。","en":"Despite being small, this room’s rent is high.","romaji":"Kono heya wa semai wari ni wa, yachin ga takai desu.","zh":""}]',replace('**Short**: Expresses contrast between expectation and reality; ''despite'', ''considering'', ''even though''.\n\n**Formation**: Verb-casual + わりには, い-Adjective + わりには, な-Adjective + だわりには, Noun + だわりには\n\n**Long**: The ～わりには grammar point is used to highlight a contrast between what is expected from a certain condition and the actual result. It can be translated as ''despite'', ''considering'', or ''even though''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_n_datte','～んだって',NULL,NULL,'N3','[]','[{"ja":"彼は東京に行くんだって。","en":"I heard he''s going to Tokyo.","romaji":"Kare wa Toukyou ni iku n datte.","zh":""},{"ja":"この映画、面白いんだって。","en":"They said this movie is interesting.","romaji":"Kono eiga, omoshiroi n datte.","zh":""},{"ja":"彼女は有名な歌手なんだって。","en":"I heard she''s a famous singer.","romaji":"Kanojo wa yuumei na kashu na n datte.","zh":""},{"ja":"あのレストラン、夜景がきれいなんだって。","en":"They said the night view at that restaurant is beautiful.","romaji":"Ano resutoran, yakei ga kirei na n datte.","zh":""}]',replace('**Short**: Conveys information heard from someone else; ''I heard'', ''They said''.\n\n**Formation**: Verb-casual + んだって, い-Adjective + んだって, な-Adjective + なんだって, Noun + なんだって\n\n**Long**: The ～んだって grammar point is used to relay information the speaker has heard from someone else. It''s a casual way of quoting what was said, effectively combining explanatory のだ (んだ) with the informal quoting particle って. It can be translated as ''I heard...'' or ''They said...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nda_mon','～んだもん',NULL,NULL,'N3','[]','[{"ja":"遅れたんだもん、ごめん。","en":"I was late, that''s why I''m sorry.","romaji":"Okureta nda mon, gomen.","zh":""},{"ja":"おいしいんだもん、もうちょっと食べたい。","en":"It''s delicious, that''s why I want to eat more.","romaji":"Oishii nda mon, mou chotto tabetai.","zh":""},{"ja":"疲れているんだもん、早く寝たい。","en":"I''m tired, that''s why I want to go to bed early.","romaji":"Tsukarete iru nda mon, hayaku netai.","zh":""},{"ja":"彼は友達なんだもん、手伝わないわけにはいかない。","en":"He''s my friend, that''s why I can''t not help him.","romaji":"Kare wa tomodachi nan da mon, tetsudawanai wake ni wa ikanai.","zh":""}]',replace('**Short**: Used to convey a sense of justification; ''because'', ''that''s why'', ''it''s just that''.\n\n**Formation**: Verb-casual + んだもん, い-Adjective + んだもん, な-Adjective + なんだもん, Noun + なんだもん\n\n**Long**: The ～んだもん grammar point is used when someone wants to give a reason, justification, or explanatory information in a more casual and emphatic way. It can be translated as ''because'', ''that''s why'', or ''it''s just that'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ageru','～上げる',NULL,NULL,'N3','[]','[{"ja":"レポートを書き上げるまで、寝られません。","en":"I cannot sleep until I finish writing the report.","romaji":"Repooto o kakiageru made, neraremasen.","zh":""},{"ja":"彼女は早速部屋の掃除を始め、一時間で掃除をやり上げた。","en":"She started cleaning the room right away and finished cleaning it in an hour.","romaji":"Kanojo wa sassoku heya no souji o hajime, ichijikan de souji o yariageta.","zh":""},{"ja":"試験前夜、勉強をやり上げてから寝た。","en":"I went to bed after finishing studying on the night before the exam.","romaji":"Shiken zenya, benkyou o yariagete kara neta.","zh":""},{"ja":"このプロジェクトをやり上げるためには、みんなの協力が必要です。","en":"To finish this project, everyone''s cooperation is needed.","romaji":"Kono purojekuto o yariageru tame ni wa, minna no kyouryoku ga hitsuyou desu.","zh":""}]',replace('**Short**: Indicates to finish doing something completely.\n\n**Formation**: Verb-ますstem + 上げる\n\n**Long**: The ～上げる grammar point is used to express that an action has been completed or finished entirely. It''s often used with verbs that have a ます stem, and can be translated as ''to finish (doing something)'', ''to complete'', or ''to get something done''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kirenai','～切れない',NULL,NULL,'N3','[]','[{"ja":"この本を一晩で読み切れない。","en":"I cannot finish reading this book in one night.","romaji":"Kono hon wo hitoban de yomikirenai.","zh":""},{"ja":"彼は泣き切れないほど嬉しかった。","en":"He was so happy that he couldn''t stop crying.","romaji":"Kare wa nakikirenai hodo ureshikatta.","zh":""},{"ja":"この部屋を一日で掃除し切れない。","en":"I cannot finish cleaning this room in one day.","romaji":"Kono heya wo ichinichi de soujishikirenai.","zh":""},{"ja":"彼女は話し切れないほどの悩みがある。","en":"She has so many worries that she can''t finish talking about them.","romaji":"Kanojo wa hanashikirenai hodo no nayami ga aru.","zh":""}]',replace('**Short**: Expresses inability to completely finish or do something.\n\n**Formation**: Verb-stem + 切れない\n\n**Long**: The ～切れない grammar point is used to express the inability to fully complete, finish, or do something. It is formed by attaching 切れない to the stem of a verb. It often implies that some portion of the action is done, but finishing it entirely is not possible for some reason.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kanarazushimo_towa_kagiranai','必ずしも～とは限らない',NULL,NULL,'N3','[]','[{"ja":"高いものが必ずしも良いとは限らない。","en":"Expensive things are not necessarily better.","romaji":"Takai mono ga kanarazushimo yoi to wa kagiranai.","zh":""},{"ja":"有名な人が必ずしも幸せとは限らない。","en":"Famous people are not necessarily happy.","romaji":"Yuumei na hito ga kanarazushimo shiawase to wa kagiranai.","zh":""},{"ja":"外国語が話せる人が必ずしも英語が得意とは限らない。","en":"People who can speak a foreign language are not always good at English.","romaji":"Gaikokugo ga hanaseru hito ga kanarazushimo eigo ga tokui to wa kagiranai.","zh":""},{"ja":"勉強時間が多い生徒が必ずしも試験で点数が高いとは限らない。","en":"Students who study a lot are not necessarily scoring high on exams.","romaji":"Benkyou jikan ga ooi seito ga kanarazushimo shiken de tensuu ga takai to wa kagiranai.","zh":""}]',replace('**Short**: Not necessarily; not always.\n\n**Formation**: 必ずしも + Statement + とは限らない\n\n**Long**: The 必ずしも～とは限らない grammar point is used to express that something is not necessarily or not always the case, indicating that a certain assumption may not hold true in all situations.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_saichuu_ni','～最中に',NULL,NULL,'N3','[]','[{"ja":"昼寝をしている最中に電話が鳴った。","en":"The phone rang while I was taking a nap.","romaji":"Hirune o shiteiru saichuu ni denwa ga natta.","zh":""},{"ja":"料理を作っている最中に火事が起こった。","en":"A fire broke out in the middle of cooking.","romaji":"Ryouri o tsukutteiru saichuu ni kaji ga okotta.","zh":""},{"ja":"会議の最中に急な用事で出なければならなかった。","en":"I had to leave during the meeting because of an urgent matter.","romaji":"Kaigi no saichuu ni kyuu na youji de denakereba naranakatta.","zh":""},{"ja":"試験の最中に地震が起こった。","en":"An earthquake occurred during the exam.","romaji":"Shiken no saichuu ni jishin ga okotta.","zh":""}]',replace('**Short**: In the middle of / while doing something.\n\n**Formation**: Verb-て form + いる + 最中に, Noun + の + 最中に\n\n**Long**: The ～最中に grammar point is used to indicate that something happens during the middle of an action or situation. It can be translated as ''in the middle of'' or ''while'' in English. It often involves appending 最中に to a verb in 〜ている form or a noun plus の.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kesshite_nai','決して～ない',NULL,NULL,'N3','[]','[{"ja":"彼は決して遅刻しない。","en":"He never arrives late.","romaji":"Kare wa kesshite chikoku shinai.","zh":""},{"ja":"この秘密を決して誰にも言わないでください。","en":"Please never tell this secret to anyone.","romaji":"Kono himitsu o kesshite darenimo iwanai de kudasai.","zh":""},{"ja":"決して諦めないで、最後までがんばりましょう。","en":"Never give up and keep trying until the end.","romaji":"Kesshite akiramenai de, saigo made ganbarimashou.","zh":""},{"ja":"彼女は決して嘘をつかない人です。","en":"She is a person who never lies.","romaji":"Kanojo wa kesshite uso o tsukanai hito desu.","zh":""}]',replace('**Short**: Express ''never'', ''by no means'', or ''not at all'' when negating a statement.\n\n**Formation**: 決して + Verb (negative form)\n\n**Long**: The 決して～ない grammar point is used to emphasize a negative statement or action. It can be translated as ''never'', ''by no means'', or ''not at all''. This grammar point must be paired with a negative verb form to maintain its negative meaning.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_aruiwa_b','A あるいは B',NULL,NULL,'N2','[]','[{"ja":"今日は映画を見るあるいはショッピングをする予定です。","en":"Today, I plan to either watch a movie or go shopping.","romaji":"Kyou wa eiga wo miru aruiwa shoppingu wo suru yotei desu.","zh":""},{"ja":"彼女は英語あるいはドイツ語で話すことができます。","en":"She can speak either English or German.","romaji":"Kanojo wa eigo aruiwa doitsugo de hanasu koto ga dekimasu.","zh":""},{"ja":"僕らはコーヒーあるいは紅茶を飲むのが好きです。","en":"We like to drink either coffee or tea.","romaji":"Bokura wa koohii aruiwa koucha wo nomu no ga suki desu.","zh":""},{"ja":"この仕事は正社員あるいは契約社員として働くことができます。","en":"You can work as either a full-time employee or a contract employee in this job.","romaji":"Kono shigoto wa seishain aruiwa keiyaku shain toshite hataraku koto ga dekimasu.","zh":""}]',replace('**Short**: Indicates alternatives; ''A or B'', ''either A or B''.\n\n**Formation**: Phrase A + あるいは + Phrase B\n\n**Long**: The あるいは grammar point is used to show alternatives or options, similar to ''A or B'' or ''either A or B'' in English. It highlights the possibility of more than one option in a situation. It can be used with verbs, adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_omake_ni','A。おまけに B。',NULL,NULL,'N2','[]','[{"ja":"彼は遅刻した。おまけに宿題も忘れた。","en":"He was late. Moreover, he forgot his homework.","romaji":"Kare wa chikoku shita. Omake ni shukudai mo wasureta.","zh":""},{"ja":"このアパートは狭い。おまけに家賃が高い。","en":"This apartment is small. Besides, the rent is high.","romaji":"Kono apaato wa semai. Omake ni yachin ga takai.","zh":""},{"ja":"彼女は仕事が忙しい。おまけに子供も小さい。","en":"She is busy with work. Not only that, her children are also small.","romaji":"Kanojo wa shigoto ga isogashii. Omake ni kodomo mo chiisai.","zh":""},{"ja":"昨日は雨が降った。おまけに風も強かった。","en":"Yesterday it rained. In addition, the wind was strong.","romaji":"Kinou wa ame ga futta. Omake ni kaze mo tsuyokatta.","zh":""}]',replace('**Short**: Expresses that in addition to A, there is also B; ''moreover'', ''besides'', ''not only'', ''but also''.\n\n**Formation**: Sentence A + おまけに  + Sentence B\n\n**Long**: The A。おまけに B。grammar point is used to express that in addition to the first statement A, there is also the second statement B which often emphasizes the negative aspect or difficulty of the situation. It can be translated as ''moreover'', ''besides'', ''not only'', or ''but also'' in English. The formation is used with two sentences, placing おまけに between those two sentences.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_sate_b','A。さて B。',NULL,NULL,'N2','[]','[{"ja":"今日の仕事が終わった。さて、これから帰るか。","en":"Today''s work is done. Now then, shall we go home?","romaji":"Kyou no shigoto ga owatta. Sate, kore kara kaeru ka.","zh":""},{"ja":"話がちょっと長くなったね。さて、もっと喜美子さんのことを教えてください。","en":"The conversation got a bit lengthy. Well, please tell me more about Kimiko.","romaji":"Hanashi ga chotto nagaku natta ne. Sate, motto Kimiko-san no koto wo oshiete kudasai.","zh":""},{"ja":"映画を見て楽しかった。さて、何を食べに行こう。","en":"Watching the movie was fun. So, what shall we go eat?","romaji":"Eiga wo mite tanoshikatta. Sate, nani wo tabe ni ikou.","zh":""},{"ja":"マラソンが終わった！さて、少し休んでからシャワーを浴びよう。","en":"The marathon is over! Now then, let''s rest a bit and then take a shower.","romaji":"Marason ga owatta! Sate, sukoshi yasunde kara shawaa wo abiyou.","zh":""}]',replace('**Short**: Indicates a sudden change or shift in the topic or situation; ''now then'', ''well'', ''so''.\n\n**Formation**: A + さて + B\n\n**Long**: The さて grammar point is used to indicate a sudden change or shift in the topic or situation. It often expresses a sense of moving on to the next topic or action, acting as a connector between sentences. It can be loosely translated as ''now then'', ''well'', or ''so'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_shikamo_b','A。しかも B。',NULL,NULL,'N2','[]','[{"ja":"この料理は美味しいです。しかも、安いです。","en":"This dish is delicious. Moreover, it is cheap.","romaji":"Kono ryouri wa oishii desu. Shikamo, yasui desu.","zh":""},{"ja":"彼は優秀な学生です。しかも、スポーツが得意です。","en":"He is an excellent student. Besides, he is good at sports.","romaji":"Kare wa yuushuu na gakusei desu. Shikamo, supootsu ga tokui desu.","zh":""},{"ja":"彼女は歌が上手です。しかも、ダンスも上手です。","en":"She is good at singing. Furthermore, she is also good at dancing.","romaji":"Kanojo wa uta ga jouzu desu. Shikamo, dansu mo jouzu desu.","zh":""},{"ja":"このカフェは雰囲気がいいです。しかも、コーヒーも美味しいです。","en":"This cafe has a nice atmosphere. Moreover, the coffee is also delicious.","romaji":"Kono kafe wa fun''iki ga ii desu. Shikamo, koohii mo oishii desu.","zh":""}]',replace('**Short**: Expressing additional information; ''moreover'', ''besides'', ''furthermore''.\n\n**Formation**: Statement A + 。しかも + Statement B。\n\n**Long**: The しかも grammar point is used to express additional information, supplementing or emphasizing what was mentioned before. It can be translated as ''moreover'', ''besides'', or ''furthermore'' in English. Both A and B are independent statements, and しかも is used to connect them.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_shitagatte_b','A。したがって B。',NULL,NULL,'N2','[]','[{"ja":"今日は雨が降っています。したがって、傘を持って行きましょう。","en":"It is raining today. Therefore, let''s bring an umbrella.","romaji":"Kyou wa ame ga futteimasu. Shitagatte, kasa wo motte ikimashou.","zh":""},{"ja":"彼は忙しいです。したがって、彼に連絡するのはやめましょう。","en":"He is busy. Consequently, let''s not contact him.","romaji":"Kare wa isogashii desu. Shitagatte, kare ni renraku suru no wa yamemashou.","zh":""},{"ja":"そのレストランは人気があります。したがって、予約しないと席がないかもしれません。","en":"That restaurant is popular. Therefore, there might be no seats if you don''t make a reservation.","romaji":"Sono resutoran wa ninki ga arimasu. Shitagatte, yoyaku shinai to seki ga nai kamoshiremasen.","zh":""},{"ja":"試験が近いです。したがって、勉強に集中しましょう。","en":"The exam is coming up soon. Consequently, let''s focus on studying.","romaji":"Shiken ga chikai desu. Shitagatte, benkyou ni shuuchuu shimashou.","zh":""}]',replace('**Short**: Express a cause-and-effect relationship; ''therefore'', ''consequently'', ''so''.\n\n**Formation**: A + したがって + B\n\n**Long**: The したがって grammar point is used to express a cause-and-effect relationship between two sentences, where ''A'' is the cause and ''B'' is the effect, result or conclusion. It can be translated as ''therefore'', ''consequently'', or ''so'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_sunawachi_b','A すなわち B。',NULL,NULL,'N2','[]','[{"ja":"私は立派な成果を出したい、すなわち、成功したいのです。","en":"I want to achieve great results, in other words, I want to succeed.","romaji":"Watashi wa rippana seika wo dashitai, sunawachi, seikou shitai no desu.","zh":""},{"ja":"彼は言葉に詰まった、すなわち、何も言えなかった。","en":"He was at a loss for words, that is to say, he couldn''t say anything.","romaji":"Kare wa kotoba ni tsumatta, sunawachi, nani mo ienakatta.","zh":""},{"ja":"彼女は自分の目標に向かって努力し続けている、すなわち、彼女は非常に頑張っている。","en":"She keeps working hard towards her goals, namely, she is trying very hard.","romaji":"Kanojo wa jibun no mokuhyou ni mukatte doryoku shi tsudzukete iru, sunawachi, kanojo wa hijou ni ganbatte iru.","zh":""},{"ja":"この店はお客様の満足を一番大事にしています、すなわち、サービスが良いということです。","en":"This store values customer satisfaction above all else, in other words, it has good service.","romaji":"Kono mise wa okyakusama no manzoku o ichiban daiji ni shiteimasu, sunawachi, saabisu ga yoi to iu koto desu.","zh":""}]',replace('**Short**: Express that A is equivalent to B; ''in other words'', ''namely'', ''that is to say''.\n\n**Formation**: Phrase A + すなわち + Phrase B\n\n**Long**: The grammar point A すなわち B is used to express that two phrases are equivalent or that the second phrase is further explanation, clarification or the true meaning of the first phrase. This can be translated as ''in other words'', ''namely'', or ''that is to say'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_suruto','A。すると B。',NULL,NULL,'N2','[]','[{"ja":"電話をかけると、彼女が出ました。","en":"When I made the phone call, she answered.","romaji":"Denwa wo kakeru to, kanojo ga demashita.","zh":""},{"ja":"このボタンを押すと、ドアが開きます。","en":"If you press this button, the door will open.","romaji":"Kono botan wo osu to, doa ga hirakimasu.","zh":""},{"ja":"コンビニに行くと、たまたま友達に会いました。","en":"When I went to the convenience store, I happened to meet my friend.","romaji":"Konbini ni iku to, tamatama tomodachi ni aimashita.","zh":""},{"ja":"彼が家を出ると、すぐに雨が降り始めました。","en":"As soon as he left the house, it started to rain.","romaji":"Kare ga ie wo deru to, sugu ni ame ga furihajimemashita.","zh":""}]',replace('**Short**: Indicates that when action A is done, action or event B follows; ''then'', ''when'', ''if''.\n\n**Formation**: A (Sentence) + すると + B (Sentence)\n\n**Long**: The A。すると B。grammar point is used to express that when action A is done or takes place, action or event B follows. It can be translated as ''then'', ''when'', or ''if'' in English. It is used to show a natural consequence or result of action A.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_souieba','A。そういえば B。',NULL,NULL,'N2','[]','[{"ja":"映画。そういえば、彼は映画館で働いているんだ。","en":"Movies. Speaking of which, he works at a movie theater.","romaji":"Eiga. Souieba, kare wa eigakan de hataraite irun da.","zh":""},{"ja":"山田さん。そういえば、彼女は今週末旅行しています。","en":"Ms. Yamada. By the way, she is traveling this weekend.","romaji":"Yamada-san. Souieba, kanojo wa konshuumatsu ryokou shite imasu.","zh":""},{"ja":"そのレストラン。そういえば、次の週末そこでパーティーがあるんだ。","en":"That restaurant. Now that you mention it, there''s a party there next weekend.","romaji":"Sono resutoran. Souieba, tsugi no shuumatsu soko de paatii ga arun da.","zh":""},{"ja":"寒い。そういえば、明日雪が降るらしいよ。","en":"It''s cold. Speaking of which, it seems like it will snow tomorrow.","romaji":"Samui. Souieba, ashita yuki ga furu rashii yo.","zh":""}]',replace('**Short**: Recalling something related to A; ''speaking of which'', ''by the way'', ''now that you mention it''.\n\n**Formation**: A + そういえば + B\n\n**Long**: The A。そういえば B。grammar point is used when something related to A is recalled or brought up. It can be translated as ''speaking of which'', ''by the way'', or ''now that you mention it'' in English. It is commonly used to connect two related topics or ideas in a conversation and indicates a change of focus. The formation consists of two clauses: the first being A and the second being B, with ''そういえば'' in between as a connector.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sokode','A。そこで B。',NULL,NULL,'N2','[]','[{"ja":"明日は試験があります。そこで今晩勉強しようと思います。","en":"There is an exam tomorrow. Therefore, I plan to study tonight.","romaji":"Ashita wa shiken ga arimasu. Soko de konban benkyou shiyou to omoimasu.","zh":""},{"ja":"このレストランは混んでいます。そこで別の場所でランチを食べましょう。","en":"This restaurant is crowded. Therefore, let''s eat lunch at a different place.","romaji":"Kono resutoran wa kondeimasu. Soko de betsu no basho de ranchi wo tabemashou.","zh":""},{"ja":"彼女はアレルギーがある。そこで彼女のために別の料理を作ります。","en":"She has an allergy. Therefore, I''ll cook a different dish for her.","romaji":"Kanojo wa arerugii ga aru. Soko de kanojo no tame ni betsu no ryouri wo tsukurimasu.","zh":""},{"ja":"傘を持っていない。そこで雨が止むまで待ちます。","en":"I don''t have an umbrella. Therefore, I''ll wait until the rain stops.","romaji":"Kasa wo motte inai. Soko de ame ga yamu made machimasu.","zh":""}]',replace('**Short**: Expresses ''therefore'' or ''because of that''.\n\n**Formation**: A + そこで + B\n\n**Long**: The A。そこで B。grammar point is used to describe the reason for an action or situation in the A part and the result or decision made in the B part. It can be translated as ''therefore'' or ''because of that'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sorega','A。それがB。',NULL,NULL,'N2','[]','[{"ja":"彼は勉強ができる。それが天才というものだ。","en":"He can study well. That''s what you call a genius.","romaji":"Kare wa benkyou ga dekiru. Sore ga tensai to iu mono da.","zh":""},{"ja":"美味しい料理を作る。それが私の趣味なんです。","en":"I make delicious food. That''s my hobby.","romaji":"Oishii ryouri wo tsukuru. Sore ga watashi no shumi nan desu.","zh":""},{"ja":"彼女は私を助けてくれる。それが友達というものだ。","en":"She helps me. That''s what a friend is.","romaji":"Kanojo wa watashi wo tasukete kureru. Sore ga tomodachi to iu mono da.","zh":""},{"ja":"一人で長い旅をする。それが自由というものだ。","en":"Traveling alone for a long time. That''s what freedom is.","romaji":"Hitori de nagai tabi wo suru. Sore ga jiyuu to iu mono da.","zh":""}]',replace('**Short**: Expressing ''that''s exactly what A is; in other words, B''.\n\n**Formation**: A (Statement)。それが B (Restatement or explanation of A)。\n\n**Long**: The grammar point A。それがB。can be used to restate or clarify that B is precisely what A means. It emphasizes the essence or definition of A by stating B. It can be translated as ''that’s what A is,'' ''that is precisely A/B,'' or ''in other words, B.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sore_de','A。それで B。',NULL,NULL,'N2','[]','[{"ja":"昨日は雨が降っていた。それで公園に行かなかった。","en":"It was raining yesterday. So, I didn''t go to the park.","romaji":"Kinou wa ame ga futte ita. Sore de kouen ni ikanakatta.","zh":""},{"ja":"試験に落ちた。それで再試験を受けなければならない。","en":"I failed the exam. So, I have to take a re-exam.","romaji":"Shiken ni ochita. Sore de sai shiken wo ukenakereba naranai.","zh":""},{"ja":"部屋が寒かった。それで暖房をつけた。","en":"The room was cold. So, I turned on the heater.","romaji":"Heya ga samukatta. Sore de danbou wo tsuketa.","zh":""},{"ja":"今日は休みだ。それで映画を見に行く。","en":"Today is a holiday. So, I''m going to watch a movie.","romaji":"Kyou wa yasumi da. Sore de eiga wo mi ni iku.","zh":""}]',replace('**Short**: Express a sequence of events or cause-and-effect; ''and then'', ''so'', ''because of that''.\n\n**Formation**: Sentence A +。それで+ Sentence B。\n\n**Long**: The A。それで B。grammar point is used to connect two sentences or events, expressing a sequence of events or explaining the reason for the second event based on the first event. Essentially, it means ''and then'', ''so'', or ''because of that'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sore_demo','A。それでも B。',NULL,NULL,'N2','[]','[{"ja":"今日は日曜日です。それでも、仕事に行かなければなりません。","en":"Today is Sunday. Nevertheless, I have to go to work.","romaji":"Kyou wa nichiyoubi desu. Sore demo, shigoto ni ikanakereba narimasen.","zh":""},{"ja":"彼は若いです。それでも、経験が豊富です。","en":"He is young. Even so, he has a lot of experience.","romaji":"Kare wa wakai desu. Sore demo, keiken ga houfu desu.","zh":""},{"ja":"雨が降っています。それでも、散歩に行きたいです。","en":"It''s raining. Still, I want to go for a walk.","romaji":"Ame ga futteimasu. Sore demo, sanpo ni ikitai desu.","zh":""},{"ja":"試験の結果が悪かったです。それでも、諦めません。","en":"The exam results were bad. But I won''t give up.","romaji":"Shiken no kekka ga warukatta desu. Sore demo, akiramenai.","zh":""}]',replace('**Short**: Expresses ''even so'', ''nevertheless'', ''still'', or ''but''; used to contrast two statements.\n\n**Formation**: A (situation) + 。それでも + B (action or thought)\n\n**Long**: The A。それでも B。grammar point is used to show a contrast between two statements. The first statement (A) presents a situation, and the second statement (B) presents an action or thought that might be unexpected or contrary to the initial situation. It can be translated as ''even so'', ''nevertheless'', ''still'', or ''but'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sorenanoni','A。それなのに B。',NULL,NULL,'N2','[]','[{"ja":"彼は頭がいい。それなのに、試験に落ちた。","en":"He is smart. Despite that, he failed the exam.","romaji":"Kare wa atama ga ii. Sore nanoni, shiken ni ochita.","zh":""},{"ja":"私は早く起きた。それなのに、バスに遅れた。","en":"I woke up early. Even so, I was late for the bus.","romaji":"Watashi wa hayaku okita. Sore nanoni, basu ni okureta.","zh":""},{"ja":"昨日は晴れていた。それなのに、彼は傘を持っていた。","en":"It was sunny yesterday. Despite that, he had an umbrella.","romaji":"Kinou wa harete ita. Sore nanoni, kare wa kasa wo motte ita.","zh":""},{"ja":"彼女は運動が苦手だ。それなのに、マラソンを走ることにした。","en":"She is not good at sports. Nevertheless, she decided to run a marathon.","romaji":"Kanojo wa undou ga nigate da. Sore nanoni, marason wo hashiru koto ni shita.","zh":""}]',replace('**Short**: Express contrast or a contradiction between two situations or facts; ''even though'', ''despite'', ''but still''.\n\n**Formation**: A。それなのに B。\n\n**Long**: The A。それなのにB。grammar point is used to express contrast, contradiction or unexpectedness between two situations or facts. It can be translated as ''even though'', ''despite'', or ''but still'' in English. The formation is simple, with A and B representing the two contrasting or contradicting statements.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_sore_nara_b','A。それなら B。',NULL,NULL,'N2','[]','[{"ja":"試験が近い。それなら、もっと勉強しなければならない。","en":"The exam is coming soon. If that''s the case, I must study more.","romaji":"Shiken ga chikai. Sore nara, motto benkyou shinakereba naranai.","zh":""},{"ja":"明日は雨が降るだろう。それなら、傘を持って行こう。","en":"It will probably rain tomorrow. In that case, let''s bring an umbrella.","romaji":"Ashita wa ame ga furudarou. Sore nara, kasa wo motte ikou.","zh":""},{"ja":"彼らはもう帰った。それなら、私も帰ろう。","en":"They have already left. If that''s the case, I''ll go home too.","romaji":"Karera wa mou kaetta. Sore nara, watashi mo kaerou.","zh":""},{"ja":"あのレストランは予約がいっぱいだ。それなら、別の場所を探そう。","en":"Reservations at that restaurant are full. In that case, let''s find another place.","romaji":"Ano resutoran wa yoyaku ga ippai da. Sore nara, betsu no basho wo sagasou.","zh":""}]',replace('**Short**: Express ''if that''s the case, then''; used to show a logical consequence or decision based on a given situation.\n\n**Formation**: Situation A (sentence) + 。それなら + Situation B (sentence)\n\n**Long**: The A。それなら B。grammar point is used to express a logical consequence or decision based on the given situation in the first part of the sentence (A). The phrase それなら can be translated as ''if that''s the case'', ''in that case'', or ''then'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_sore_wa_sou_to_b','A それはそうと B。',NULL,NULL,'N2','[]','[{"ja":"それはそうと、今日の天気はいいですね。","en":"By the way, the weather is nice today, isn''t it?","romaji":"Sore wa sou to, kyou no tenki wa ii desu ne.","zh":""},{"ja":"映画は面白かったです。それはそうと、この店のラーメンはおいしいですよ。","en":"The movie was interesting. Speaking of which, this restaurant''s ramen is delicious.","romaji":"Eiga wa omoshirokatta desu. Sore wa sou to, kono mise no raamen wa oishii desu yo.","zh":""},{"ja":"明日から夏休みですね。それはそうと、新しいカフェがオープンしたみたいです。","en":"Summer vacation starts tomorrow, huh? By the way, it seems a new cafe has opened.","romaji":"Ashita kara natsu yasumi desu ne. Sore wa sou to, atarashii kafe ga oopun shita mitai desu.","zh":""},{"ja":"昨日の試験は難しかった。それはそうと、週末にパーティーがあるのを知ってますか？","en":"Yesterday''s exam was difficult. Speaking of which, do you know there''s a party this weekend?","romaji":"Kinou no shiken wa muzukashikatta. Sore wa sou to, shuumatsu ni paatii ga aru no wo shitte masu ka?","zh":""}]',replace('**Short**: Changing the topic; ''by the way'', ''speaking of which''.\n\n**Formation**: Sentence A + それはそうと + Sentence B\n\n**Long**: The grammar point A それはそうと B is used to change the topic or bring up a new subject in a conversation. It can be translated as ''by the way'' or ''speaking of which'' in English. It''s used to connect two unrelated sentences or ideas, with A being the original topic and B being the new topic brought up.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_daga','A。だが B。',NULL,NULL,'N2','[]','[{"ja":"このレストランは値段が高い。だが、味はとてもいい。","en":"This restaurant is expensive. But, the taste is very good.","romaji":"Kono resutoran wa nedan ga takai. Daga, aji wa totemo ii.","zh":""},{"ja":"彼は疲れている。だが、仕事を終わらせるまで休まない。","en":"He is tired. However, he will not rest until he finishes work.","romaji":"Kare wa tsukarete iru. Daga, shigoto o owaraseru made yasumanai.","zh":""},{"ja":"昨日は寒かった。だが、今日は暖かい。","en":"Yesterday was cold. But, today is warm.","romaji":"Kinou wa samukatta. Daga, kyou wa atatakai.","zh":""},{"ja":"彼女は外見は地味だ。だが、性格が素晴らしい。","en":"Her appearance is plain. However, she has a wonderful personality.","romaji":"Kanojo wa gaiken wa jimi da. Daga, seikaku ga subarashii.","zh":""}]',replace('**Short**: Expresses contrasting ideas or statements; ''but'', ''however''.\n\n**Formation**: Sentence A + だが + Sentence B\n\n**Long**: The A。だが B。grammar point is used to express contrasting ideas or statements. It connects two sentences or phrases with a contrasting meaning. It can be translated as ''but'' or ''however'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tada','A。ただB。',NULL,NULL,'N2','[]','[{"ja":"彼は頭がいい。ただ、努力はあまりしない。","en":"He is smart; however, he doesn''t make much effort.","romaji":"Kare wa atama ga ii. Tada, doryoku wa amari shinai.","zh":""},{"ja":"外は雨が降っている。ただ、家にいると暇だ。","en":"It''s raining outside, but I''m bored at home.","romaji":"Soto wa ame ga futte iru. Tada, ie ni iru to hima da.","zh":""},{"ja":"そのレストランは値段が高い。ただ、サービスが良い。","en":"That restaurant is expensive; however, the service is good.","romaji":"Sono resutoran wa nedan ga takai. Tada, saabisu ga yoi.","zh":""},{"ja":"テストの結果は良くなかった。ただ、やり直すチャンスがある。","en":"The test results were not good, but there''s a chance to retake it.","romaji":"Tesuto no kekka wa yokunakatta. Tada, yarinaosu chansu ga aru.","zh":""}]',replace('**Short**: Express contrast between two situations; ''although'', ''but'', ''however''.\n\n**Formation**: Sentence A + ただ + Sentence B\n\n**Long**: The ただ grammar point is used to express contrast between two situations or facts. It can often be translated as ''although'', ''but'', or ''however'' in English. It is used to show a contradiction or a different aspect of a situation.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_tadashi_b','A。ただしB。',NULL,NULL,'N2','[]','[{"ja":"この部屋を使ってもいいです。ただし、使った後で掃除してください。","en":"You can use this room. However, please clean up after you use it.","romaji":"Kono heya wo tsukatte mo ii desu. Tadashi, tsukatta ato de souji shite kudasai.","zh":""},{"ja":"明日から出張で不在になります。ただし、緊急の場合は携帯に連絡してください。","en":"I''ll be away on a business trip starting tomorrow. However, in case of emergency, please contact me on my cell phone.","romaji":"Ashita kara shucchou de fuzai ni narimasu. Tadashi, kinkyuu no baai wa keitai ni renraku shite kudasai.","zh":""},{"ja":"食事代は全額会社が負担します。ただし、アルコールのみ自己負担となります。","en":"The company will cover the entire meal cost. However, alcohol expenses will be borne by the individual.","romaji":"Shokuji dai wa zengaku kaisha ga futan shimasu. Tadashi, arukooru nomi jiko futan to narimasu.","zh":""},{"ja":"図書館で本を借りることができます。ただし、期限内に返さなければなりません。","en":"You can borrow books from the library. However, you must return them within the deadline.","romaji":"Toshokan de hon wo kariru koto ga dekimasu. Tadashi, kigen nai ni kaesanakereba narimasen.","zh":""}]',replace('**Short**: Adding a condition or exception to a statement; ''however'', ''provided that'', ''but only if''.\n\n**Formation**: Statement A + ただし + Condition B\n\n**Long**: The grammar point A。ただしB is used to add a condition or exception to a previous statement. It can be translated to ''however'', ''provided that'', or ''but only if'' in English. This structure consists of two parts: A (statement) and B (condition/exception). The word ただし is used to connect these two parts.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_datte','A。だって B。',NULL,NULL,'N2','[]','[{"ja":"暇だって、映画を見に行こうよ。","en":"Since we are free, let''s go watch a movie.","romaji":"Hima datte, eiga wo mi ni ikou yo.","zh":""},{"ja":"寒いだって、コートを着てください。","en":"Because it''s cold, please wear a coat.","romaji":"Samui datte, ko-to wo kite kudasai.","zh":""},{"ja":"疲れているだって、休んだほうがいい。","en":"Since you''re tired, it''s better to rest.","romaji":"Tsukarete iru datte, yasunda hou ga ii.","zh":""},{"ja":"彼女が料理上手だって、みんな彼女の作った料理を楽しみにしています。","en":"Because she is good at cooking, everyone is looking forward to her dishes.","romaji":"Kanojo ga ryouri jouzu datte, minna kanojo no tsukutta ryouri wo tanoshimi ni shiteimasu.","zh":""}]',replace('**Short**: Used to give a reason, express cause or bring up a topic; ''because'', ''since'', ''it''s just that''.\n\n**Formation**: Verb-casual + だって、い-Adjective + だって、な-Adjective + だって、Noun + だって\n\n**Long**: The A。だって B。grammar point is used to give a reason, express cause, or introduce a topic in a casual manner. It can be translated as ''because'', ''since'', or ''it''s just that''. A is the reason and B is the statement that follows due to the reason. It can be used with verbs, い-adjectives, な-adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_chinamini_b','A。ちなみに B。',NULL,NULL,'N2','[]','[{"ja":"今日は授業がありません。ちなみに、明日も休みです。","en":"There''s no class today. By the way, tomorrow is also a day off.","romaji":"Kyou wa jugyou ga arimasen. Chinamini, asu mo yasumi desu.","zh":""},{"ja":"この店のラーメンは美味しいです。ちなみに、餃子もおすすめです。","en":"The ramen at this shop is delicious. By the way, their gyoza is also recommended.","romaji":"Kono mise no ramen wa oishii desu. Chinamini, gyoza mo osusume desu.","zh":""},{"ja":"彼は今日は遅刻しました。ちなみに、昨日は欠席しました。","en":"He was late today. By the way, he was absent yesterday.","romaji":"Kare wa kyou wa chikoku shimashita. Chinamini, kinou wa kesseki shimashita.","zh":""},{"ja":"映画は面白かったです。ちなみに、原作の方がもっといいですよ。","en":"The movie was interesting. By the way, the original work is even better.","romaji":"Eiga wa omoshirokatta desu. Chinamini, gensaku no hou ga motto ii desu yo.","zh":""}]',replace('**Short**: Used to give additional information about the topic; ''by the way'', ''incidentally''.\n\n**Formation**: A。ちなみに B。\n\n**Long**: The ちなみに grammar point is used to provide additional information or a side note about a topic that has been previously mentioned. It can be translated as ''by the way'' or ''incidentally'' in English. This grammar point is typically used to give further context, background information, or a slight change in topic.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_to_iu_koto_wa_b','A。ということは B。',NULL,NULL,'N2','[]','[{"ja":"彼女が泣いている。ということは何か悲しいことがあったに違いない。","en":"She is crying. That means something sad must have happened.","romaji":"Kanojo ga naite iru. To iu koto wa nanika kanashii koto ga atta ni chigainai.","zh":""},{"ja":"このケーキが残っている。ということは、みんなお腹がいっぱいだったのかな。","en":"This cake is left over. That means everyone must have been full, I guess.","romaji":"Kono keeki ga nokotte iru. To iu koto wa, minna onaka ga ippai datta no ka na.","zh":""},{"ja":"道が渋滞している。ということは、事故があったのかもしれない。","en":"The road is congested. That means there might have been an accident.","romaji":"Michi ga juutai shite iru. To iu koto wa, jiko ga atta no kamoshirenai.","zh":""},{"ja":"彼が試験に受かった。ということは、勉強がたくさん頑張ったんだね。","en":"He passed the exam. That means he must have studied really hard.","romaji":"Kare ga shiken ni ukatta. To iu koto wa, benkyou ga takusan ganbattan da ne.","zh":""}]',replace('**Short**: Expresses the meaning ''if A, that means B'' or ''A implies B''.\n\n**Formation**: A + ということは + B\n\n**Long**: The A。ということは B。grammar point is used to express the logical conclusion that if A is true, then B must also be true. It can be translated as ''if A, that means B'' or ''A implies B'' in English. This pattern is used when the speaker wants to infer or deduce B based on the information provided by A.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_toiu_no_wa','A。というのは B。',NULL,NULL,'N2','[]','[{"ja":"彼は非常に疲れています。というのは、昨夜、車で遠くまで行ってきたためです。","en":"He is very tired. That is to say, because he went far by car last night.","romaji":"Kare wa hijou ni tsukareteimasu. To iu no wa, sakuya, kuruma de tooku made itte kita tame desu.","zh":""},{"ja":"このレストランはおすすめです。というのは、料理が美味しいし、雰囲気もいいからです。","en":"I recommend this restaurant. That is to say, because the food is delicious and the atmosphere is nice.","romaji":"Kono resutoran wa osusume desu. To iu no wa, ryouri ga oishii shi, fun''iki mo ii kara desu.","zh":""},{"ja":"試験に落ちた。というのは、十分に勉強しなかったからです。","en":"I failed the exam. In other words, because I didn''t study enough.","romaji":"Shiken ni ochita. To iu no wa, juubun ni benkyou shinakatta kara desu.","zh":""},{"ja":"彼女は独特な趣味がある。というのは、昆虫収集だ。","en":"She has a unique hobby. Namely, insect collecting.","romaji":"Kanojo wa dokutoku na shumi ga aru. To iu no wa, konchuu shuushuu da.","zh":""}]',replace('**Short**: Used to give an explanation or provide additional information for A; ''that is to say'', ''in other words''.\n\n**Formation**: [Statement A]。というのは、[Statement B]。\n\n**Long**: The grammar point A。というのは B。 is used to provide an explanation, definition, or further information about statement A. It can be translated as ''that is to say'', ''in other words'', or ''namely'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_nao_b','A。なおB。',NULL,NULL,'N2','[]','[{"ja":"明日は休みです。なお、月曜日も休みです。","en":"Tomorrow is a holiday. Moreover, Monday is also a holiday.","romaji":"Ashita wa yasumi desu. Nao, getsuyoubi mo yasumi desu.","zh":""},{"ja":"彼は頭が良いです。なお、スポーツも得意です。","en":"He is smart. Besides, he is also good at sports.","romaji":"Kare wa atama ga yoi desu. Nao, supootsu mo tokui desu.","zh":""},{"ja":"この本は面白いです。なお、安いです。","en":"This book is interesting. In addition, it is cheap.","romaji":"Kono hon wa omoshiroi desu. Nao, yasui desu.","zh":""},{"ja":"私は日本語を勉強しています。なお、韓国語も勉強しています。","en":"I am studying Japanese. Moreover, I am also studying Korean.","romaji":"Watashi wa nihongo wo benkyou shiteimasu. Nao, kankokugo mo benkyou shiteimasu.","zh":""}]',replace('**Short**: Provides additional information; ''moreover'', ''besides'', ''in addition''.\n\n**Formation**: A (sentence) + なお + B (sentence)\n\n**Long**: The なお grammar point is used to provide additional information or emphasize an existing fact. It can be translated as ''moreover'', ''besides'', or ''in addition'' in English. なお is placed between two sentences to connect them and provide supplementary information.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_motto_mo','A。もっとも B。',NULL,NULL,'N2','[]','[{"ja":"彼は頭がいい。もっとも、勉強も大切だ。","en":"He is smart. However, studying is also important.","romaji":"Kare wa atama ga ii. Mottomo, benkyou mo taisetsu da.","zh":""},{"ja":"このレストランは美味しい。もっとも、値段が高い。","en":"This restaurant is delicious. But, the prices are high.","romaji":"Kono resutoran wa oishii. Mottomo, nedan ga takai.","zh":""},{"ja":"彼女は綺麗だ。もっとも、性格が悪い。","en":"She is beautiful. Although, her personality is bad.","romaji":"Kanojo wa kirei da. Mottomo, seikaku ga warui.","zh":""},{"ja":"日本は面白い国だ。もっとも、住むのが大変そうだ。","en":"Japan is an interesting country. But, it seems difficult to live in.","romaji":"Nihon wa omoshiroi kuni da. Mottomo, sumu no ga taihen sou da.","zh":""}]',replace('**Short**: Express contrasting opinions or facts; ''although'', ''but'', ''however''.\n\n**Formation**: Clause A + もっとも + Clause B\n\n**Long**: The A。もっとも B。 grammar point is used to express contrasting opinions or facts. It can be translated as ''although'', ''but'', or ''however'' in English. This structure connects two clauses and highlights the contrast between them.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_yousuru_ni_b','A。要するに B。',NULL,NULL,'N2','[]','[{"ja":"このプロジェクトは成功しました。要するに、私たちのチームは素晴らしい仕事をしました。","en":"This project was successful. In short, our team did a great job.","romaji":"Kono purojekuto wa seikou shimashita. Yousuru ni, watashitachi no chiimu wa subarashii shigoto o shimashita.","zh":""},{"ja":"彼は料理が上手です。要するに、彼は優れたシェフです。","en":"He is good at cooking. In a nutshell, he is an excellent chef.","romaji":"Kare wa ryouri ga jouzu desu. Yousuru ni, kare wa sugureta shefu desu.","zh":""},{"ja":"昨日はとても忙しかった。要するに、一日中働いていました。","en":"Yesterday was very busy. To sum up, I was working all day.","romaji":"Kinou wa totemo isogashikatta. Yousuru ni, ichinichijuu hataraite imashita.","zh":""},{"ja":"彼女は新しい仕事が好きです。要するに、彼女は満足しています。","en":"She likes her new job. In short, she is satisfied.","romaji":"Kanojo wa atarashii shigoto ga suki desu. Yousuru ni, kanojo wa manzoku shiteimasu.","zh":""}]',replace('**Short**: Expressing ''in short'', ''in a nutshell'', or ''to sum up'' when restating or summarizing A as B.\n\n**Formation**: A。要するに B。\n\n**Long**: The A。要するに B。grammar point is used to restate or summarize the information provided in A more concisely as B. It can be translated as ''in short'', ''in a nutshell'', or ''to sum up'' in English. The formation consists of two sentences or statements, A and B, with 要するに (yousuru ni) in between to indicate the summary or restatement of A as B.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_tsuki','Noun につき',NULL,NULL,'N2','[]','[{"ja":"試験につき、今日は静かにしてください。","en":"Due to the exam, please be quiet today.","romaji":"Shiken ni tsuki, kyou wa shizuka ni shite kudasai.","zh":""},{"ja":"このエリアは工事中につき、通行止めです。","en":"The area is closed for passage due to construction.","romaji":"Kono eria wa koujichuu ni tsuki, tsuukoudome desu.","zh":""},{"ja":"博物館は整備中につき、入場料が無料です。","en":"Due to maintenance, admission to the museum is free.","romaji":"Hakubutsukan wa seibichuu ni tsuki, nyuujouryou ga muryou desu.","zh":""},{"ja":"商品お一つにつき、1000円の割引があります。","en":"There is a 1,000 yen discount per item.","romaji":"Shouhin o hitotsu ni tsuki, sen''en no waribiki ga arimasu.","zh":""}]',replace('**Short**: Indicates the reason, cause, or condition for something; ''due to'', ''regarding'', ''per''.\n\n**Formation**: Noun + につき\n\n**Long**: The につき grammar point is used to express the reason, cause, or condition for an event or situation. In English, it can be translated as ''due to'', ''regarding'', ''per'', or ''for each''. It can be used with nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_nite','Noun にて',NULL,NULL,'N2','[]','[{"ja":"駅前広場にてイベントが開催されます。","en":"An event will be held at the station square.","romaji":"Ekimae hiroba nite ibento ga kaisai saremasu.","zh":""},{"ja":"ホテルにて会議が行われます。","en":"The meeting will take place at the hotel.","romaji":"Hoteru nite kaigi ga okonawaremasu.","zh":""},{"ja":"郵便局にて荷物を受け取りました。","en":"I received the package at the post office.","romaji":"Yubinkyoku nite nimotsu wo uketorimashita.","zh":""},{"ja":"インターネットにて調べたら、答えが見つかりました。","en":"I searched online and found the answer.","romaji":"Intaanetto nite shirabetara, kotae ga mitsukarimashita.","zh":""}]',replace('**Short**: Expresses location or means; ''at'', ''in'', ''by'', ''with''.\n\n**Formation**: Noun + にて\n\n**Long**: The にて grammar point is used to indicate the location, means, or method of an action. It can be translated as ''at'', ''in'', ''by'', or ''with'' in English. It functions similarly to the particle で, but にて is more formal and often used in written language, formal speaking, and announcements.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_no_koto_dakara','Noun の ことだから',NULL,NULL,'N2','[]','[{"ja":"料理が得意な彼のことだから、美味しい料理を作ってくれるでしょう。","en":"Since he’s good at cooking, he’ll probably make delicious food.","romaji":"Ryouri ga tokui na kare no koto dakara, oishii ryouri wo tsukutte kureru deshou.","zh":""},{"ja":"いつも遅刻する彼女のことだから、今日も遅れるかもしれない。","en":"Because she’s always late, she might be late again today.","romaji":"Itsumo chikoku suru kanojo no koto dakara, kyou mo okureru kamoshirenai.","zh":""},{"ja":"安い店のことだから、たくさん売れるはずだ。","en":"Since it’s a cheap store, it should sell a lot.","romaji":"Yasui mise no koto dakara, takusan ureru hazu da.","zh":""},{"ja":"ドラマ好きな彼のことだから、最新のドラマについて話すといいでしょう。","en":"Knowing he likes dramas, it’d be good to talk about the latest shows.","romaji":"Dorama suki na kare no koto dakara, saishin no dorama ni tsuite hanasu to ii deshou.","zh":""}]',replace('**Short**: Used to provide a reason or explanation based on one''s knowledge about the noun; ''since'', ''because'', ''knowing''.\n\n**Formation**: Noun + のことだから\n\n**Long**: The の ことだから (no koto dakara) grammar point is used when giving a reason or explanation based on one’s knowledge or understanding of a particular person or thing. It often implies ''given that this is the kind of person/thing it is''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wo_hajime','Noun を はじめ',NULL,NULL,'N2','[]','[{"ja":"日本料理をはじめ、さまざまな料理がこのレストランで楽しめます。","en":"You can enjoy various dishes in this restaurant, starting with Japanese cuisine.","romaji":"Nihon ryouri wo hajime, samazama na ryouri ga kono resutoran de tanoshimemasu.","zh":""},{"ja":"彼は絵画をはじめ、彫刻や写真もコレクションしている。","en":"He collects not only paintings but also sculptures and photographs.","romaji":"Kare wa kaiga wo hajime, choukoku ya shashin mo korekushon shite iru.","zh":""},{"ja":"京都をはじめ、日本のいくつかの都市で伝統的な祭りが行われている。","en":"Traditional festivals are held in several cities in Japan, including Kyoto.","romaji":"Kyouto wo hajime, Nihon no ikutsu ka no toshi de dentouteki na matsuri ga okonawarete iru.","zh":""},{"ja":"太陽をはじめ、地球や火星などの惑星も太陽系に含まれている。","en":"Not only the Sun, but also planets such as Earth and Mars are included in the solar system.","romaji":"Taiyou wo hajime, chikyuu ya kasei nado no wakusei mo taiyoukei ni fukumarete iru.","zh":""}]',replace('**Short**: Meaning ''starting with'', ''including'', ''not only... but also''.\n\n**Formation**: Noun + をはじめ\n\n**Long**: The grammar point Nounをはじめ is used to show that there are other things or people being included apart from the mentioned noun. It can be used to provide an example, indicate a representative or list items. This can be translated as ''starting with'', ''including'', or ''not only... but also...'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wo_hajime_to_shite','Noun を はじめとして',NULL,NULL,'N2','[]','[{"ja":"東京をはじめとして、日本にはたくさんの観光スポットがあります。","en":"There are many tourist spots in Japan, starting with Tokyo.","romaji":"Tōkyō o hajime to shite, Nihon ni wa takusan no kankō supotto ga arimasu.","zh":""},{"ja":"彼は、ピアノをはじめとして、たくさんの楽器を演奏できます。","en":"He can play many instruments, starting with piano.","romaji":"Kare wa, piano o hajime to shite, takusan no gakki o ensō dekimasu.","zh":""},{"ja":"この本は手作りのガーゼマスクをはじめとして、便利な生活アイディアが満載です。","en":"This book is packed with useful life hacks, including how to make a handmade gauze mask.","romaji":"Kono hon wa tezukuri no gāze masuku o hajime to shite, benrina seikatsu aidea ga mansai desu.","zh":""},{"ja":"そのショッピングモールには、ZARAをはじめとして、多くのブランドが集まっています。","en":"Many brands, including ZARA, gather in that shopping mall.","romaji":"Sono shoppingu mōru ni wa, ZARA o hajime to shite, ōku no burando ga atsumatte imasu.","zh":""}]',replace('**Short**: Expresses ''starting with'', ''beginning with'', or ''including''.\n\n**Formation**: Noun + をはじめとして\n\n**Long**: The grammar point Noun を はじめとして is used to emphasize a particular item or example along with others. It translates to ''starting with'', ''beginning with'', or ''including'' in English. It is used to present a specific case and imply there are more related items.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_o_hajime_to_suru_noun','Noun を はじめとする Noun',NULL,NULL,'N2','[]','[{"ja":"彼はフランス語をはじめとする外国語が話せる。","en":"He can speak foreign languages, starting with French.","romaji":"Kare wa furansugo o hajime to suru gaikokugo ga hanaseru.","zh":""},{"ja":"このコンサートには、BTSをはじめとする人気アーティストが出演する予定です。","en":"This concert is scheduled to feature popular artists, including BTS.","romaji":"Kono konsāto ni wa, BTS o hajime to suru ninki ātisuto ga shutsuen suru yotei desu.","zh":""},{"ja":"彼女は魚をはじめとする海の幸が大好きだ。","en":"She loves seafood, starting with fish.","romaji":"Kanojo wa sakana o hajime to suru umi no sachi ga daisuki da.","zh":""},{"ja":"この図書館には、子供向けの本をはじめとするさまざまなジャンルの本があります。","en":"This library has various genres of books, including children''s books.","romaji":"Kono toshokan ni wa, kodomomuke no hon o hajime to suru samazama na janru no hon ga arimasu.","zh":""}]',replace('**Short**: Indicates a representative example of a group; ''starting with'', ''including'', ''such as''.\n\n**Formation**: Noun1 を はじめとする Noun2\n\n**Long**: The grammar pattern ''Noun を はじめとする Noun'' is used to indicate a representative example of a group and suggests that there are other things besides the mentioned example. It can be translated as ''starting with'', ''including'', or ''such as'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wo_megutte','Noun を めぐって',NULL,NULL,'N2','[]','[{"ja":"環境問題をめぐって、多くの議論が行われています。","en":"Many discussions are held concerning environmental issues.","romaji":"Kankyō mondai o megutte, ōku no giron ga okonawarete imasu.","zh":""},{"ja":"彼の死をめぐって、いくつかの陰謀説が浮かび上がっている。","en":"Several conspiracy theories have emerged regarding his death.","romaji":"Kare no shi o megutte, ikutsuka no inbōsetsu ga ukabiagatte iru.","zh":""},{"ja":"昇給をめぐって会社と労働組合が話し合いをしています。","en":"The company and the labor union are having discussions about pay raises.","romaji":"Shōkyū o megutte kaisha to rōdō kumiai ga hanashiai o shite imasu.","zh":""},{"ja":"この映画をめぐって、賛否両論が存在している。","en":"There are both pros and cons regarding this movie.","romaji":"Kono eiga o megutte, sanpi ryōron ga sonzai shite iru.","zh":""}]',replace('**Short**: Concerning; with regard to; about\n\n**Formation**: Noun + を + めぐって\n\n**Long**: The grammar point Noun を めぐって is used to express that something is concerning, with regard to or about a certain noun. It covers a topic or an issue that is central to a discussion or a situation.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_o_meguru_noun','Noun を めぐる Noun',NULL,NULL,'N2','[]','[{"ja":"この事件をめぐる議論が続いています。","en":"The debate concerning this incident continues.","romaji":"Kono jiken o meguru giron ga tsudzuite imasu.","zh":""},{"ja":"環境問題をめぐる国際会議が開かれます。","en":"An international conference regarding environmental issues will be held.","romaji":"Kankyō mondai o meguru kokusai kaigi ga hirakaremasu.","zh":""},{"ja":"彼の突然の辞任をめぐるうわさが広がっている。","en":"Rumors are spreading concerning his sudden resignation.","romaji":"Kare no totsuzen no jinin o meguru uwasa ga hirogatte iru.","zh":""},{"ja":"映画祭をめぐる活動が多くなっています。","en":"There are increasing activities surrounding the film festival.","romaji":"Eigashai o meguru katsudō ga ōku natte imasu.","zh":""}]',replace('**Short**: Indicate a situation or event revolving around a particular noun; ''concerning'', ''regarding'', ''pertaining to''.\n\n**Formation**: Noun1 + を + めぐる + Noun2\n\n**Long**: The NounをめぐるNoun grammar point is used to express that a situation or event is centered around a particular noun. It can be translated as ''concerning'', ''regarding'', or ''pertaining to'' in English. The formation consists of the particle ''を'' placed between two nouns, and the verb ''めぐる'' (to revolve around) following the first noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_o_moto_ni','Noun を もとに',NULL,NULL,'N2','[]','[{"ja":"この映画は実話をもとに作られました。","en":"This movie was made based on a true story.","romaji":"Kono eiga wa jitsuwa o moto ni tsukuraremashita.","zh":""},{"ja":"彼の経験をもとにアドバイスが必要だ。","en":"Advice is needed based on his experience.","romaji":"Kare no keiken o moto ni adobaisu ga hitsuyō da.","zh":""},{"ja":"データをもとに分析を行いました。","en":"I performed an analysis based on the data.","romaji":"Dēta o moto ni bunseki o okonaimashita.","zh":""},{"ja":"世界中の美術館をもとにコレクションを作りました。","en":"I created a collection based on art galleries all over the world.","romaji":"Sekaijū no bijutsukan o moto ni korekushon o tsukurimashita.","zh":""}]',replace('**Short**: Based on; drawing from; using as a reference.\n\n**Formation**: Noun + をもとに\n\n**Long**: The grammar point Nounをもとに is used to convey that something is based on, drawn from, or using the noun as a reference. It is commonly used when one thing is being used as a foundation, source of information or inspiration for something else.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wo_moto_ni_shite','Noun を もとにして',NULL,NULL,'N2','[]','[{"ja":"彼の意見をもとにして、計画を変更しました。","en":"Based on his opinion, we changed the plan.","romaji":"Kare no iken o moto ni shite, keikaku o henkō shimashita.","zh":""},{"ja":"この小説は実話をもとにして書かれています。","en":"This novel is written based on a true story.","romaji":"Kono shōsetsu wa jitsuwa o moto ni shite kakarete imasu.","zh":""},{"ja":"資料をもとにして、レポートを作成しました。","en":"I created the report based on the materials.","romaji":"Shiryō o moto ni shite, repōto o sakusei shimashita.","zh":""},{"ja":"過去の成功例をもとにして、新しいプロジェクトを進める予定です。","en":"We plan to proceed with the new project based on past successful examples.","romaji":"Kako no seikōrei o moto ni shite, atarashii purojekuto o susumeru yotei desu.","zh":""}]',replace('**Short**: Based on; using; utilizing.\n\n**Formation**: Noun + をもとにして\n\n**Long**: The ''Noun をもとにして'' grammar point is used to express that something is done based on, using, or utilizing the noun. It indicates that the noun is the foundation, source or basis for the action or statement.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kotonaku','Verb ことなく',NULL,NULL,'N2','[]','[{"ja":"彼女は泣くことなく帰ってしまいました。","en":"She went home without crying.","romaji":"Kanojo wa naku koto naku kaette shimaimashita.","zh":""},{"ja":"彼は注意することなく突然出かけた。","en":"He suddenly left without giving any warning.","romaji":"Kare wa chūi suru koto naku totsuzen dekaketa.","zh":""},{"ja":"山田さんは誰にも話すことなく会社を辞めました。","en":"Mr. Yamada quit the company without talking to anyone.","romaji":"Yamada-san wa dare ni mo hanasu koto naku kaisha o yamemashita.","zh":""},{"ja":"２０年間、病気になることなく働いています。","en":"I have been working for 20 years without getting sick.","romaji":"Nijūnenkan, byōki ni naru koto naku hataraite imasu.","zh":""}]',replace('**Short**: Means ''without doing'', ''not doing'', or ''without happening''.\n\n**Formation**: Verb-stem + ことなく\n\n**Long**: The grammar point ことなく is added to the stem of a verb to express that something doesn''t happen or isn''t done. It can be translated as ''without doing'', ''not doing'', or ''without happening''. The formation depends on whether it is used with a verb.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nai_koto_ni_wa_nai','Verb ないことには Verb ない',NULL,NULL,'N2','[]','[{"ja":"薬を飲まないことには、病気が治らない。","en":"Unless you take the medicine, the illness won''t get better.","romaji":"Kusuri o nomanai koto ni wa, byōki ga naoranai.","zh":""},{"ja":"この問題によく考えないことには、解決できない。","en":"Unless you think carefully about this problem, you can''t solve it.","romaji":"Kono mondai ni yoku kangaenai koto ni wa, kaiketsu dekinai.","zh":""},{"ja":"練習をしないことには、スキルが上達しない。","en":"Unless you practice, your skills won''t improve.","romaji":"Renshū o shinai koto ni wa, sukiru ga jōtatsu shinai.","zh":""},{"ja":"手続きをしないことには、新しいパスポートがもらえない。","en":"Unless you go through the procedures, you can''t get a new passport.","romaji":"Tetsuzuki o shinai koto ni wa, atarashii pasupōto ga moraenai.","zh":""}]',replace('**Short**: Express that something cannot be done without meeting a certain condition.\n\n**Formation**: Verb-ない + ことには + Verb-ない\n\n**Long**: The ないことには grammar point is used to indicate that something cannot be done or achieved unless a certain condition is met. This pattern is formed by attaching ないことには to the negative form of a verb, followed by a negative outcome statement. It often appears as V-ない + ことには + V-ない or a negative expression.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ageku','～あげく',NULL,NULL,'N2','[]','[{"ja":"長い時間待ったあげく、電車が来なかった。","en":"After waiting a long time, in the end, the train didn''t come.","romaji":"Nagai jikan matta ageku, densha ga konakatta.","zh":""},{"ja":"いろいろな方法を試したあげく、成功した。","en":"After trying various methods, I finally succeeded.","romaji":"Iroiro na hōhō o tameshita ageku, seikō shita.","zh":""},{"ja":"彼は失敗のあげく、会社を辞める決心をした。","en":"In the end, after his failures, he decided to quit the company.","romaji":"Kare wa shippai no ageku, kaisha o yameru kesshin o shita.","zh":""},{"ja":"彼女は長い間悩んだあげく、その仕事を断った。","en":"After worrying for a long time, she finally turned down the job.","romaji":"Kanojo wa nagai aida nayanda ageku, sono shigoto o kotowatta.","zh":""}]',replace('**Short**: Expresses the outcome of a series of actions or events; ''in the end'', ''finally'', ''after''.\n\n**Formation**: Verb-た + あげく / Noun + の + あげく\n\n**Long**: The ～あげく grammar point is used to express the outcome or result after a series of actions or events. It can usually be translated into English as ''in the end'', ''finally'', or ''after''. The typical formation is adding あげく to the past form of a verb (Verb-た), or adding のあげく to a noun. This indicates that, after a long process or a number of attempts, a certain final outcome is reached—often with a sense that it took considerable effort or time.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_amari','～あまり',NULL,NULL,'N2','[]','[{"ja":"昨日は疲れすぎたあまり、朝まで眠り続けました。","en":"Yesterday, I was so tired that I slept until morning.","romaji":"Kinō wa tsukare-sugita amari, asa made nemuri tsuzukemashita.","zh":""},{"ja":"彼女はうれしいあまり、泣き出してしまった。","en":"She was so happy that she ended up crying.","romaji":"Kanojo wa ureshii amari, nakidashite shimatta.","zh":""},{"ja":"彼は安全を確認するあまり、何回もドアをチェックしている。","en":"He is so concerned about safety that he checks the door many times.","romaji":"Kare wa anzen o kakunin suru amari, nankai mo doa o chekku shite iru.","zh":""},{"ja":"寒さのあまり、彼は震えが止まらなかった。","en":"It was so cold that he couldn''t stop shivering.","romaji":"Samusa no amari, kare wa furue ga tomaranakatta.","zh":""}]',replace('**Short**: Expresses the result of doing something excessively or beyond a certain point.\n\n**Formation**: Verb-ます stem + あまり, い-Adjective + あまり, な-Adjective + のあまり, Noun + のあまり\n\n**Long**: The ～あまり grammar point is used to express a negative or undesirable outcome caused by doing something excessively or beyond a certain point. It often follows verbs, adjectives, and nouns, and is commonly translated as ''so much'', ''too much'', or ''to the extent that''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_uchi_ni_n2','～うちに',NULL,NULL,'N2','[]','[{"ja":"元気なうちに、旅行を楽しんでください。","en":"Enjoy traveling while you are healthy.","romaji":"Genki na uchi ni, ryokō o tanoshinde kudasai.","zh":""},{"ja":"若いうちに、いろいろなことを学ぶべきだ。","en":"One should learn various things while they are young.","romaji":"Wakai uchi ni, iroiro na koto o manabu beki da.","zh":""},{"ja":"子供が寝ているうちに、夕食の準備をしましょう。","en":"Let''s prepare dinner while the kids are sleeping.","romaji":"Kodomo ga nete iru uchi ni, yūshoku no junbi o shimashō.","zh":""},{"ja":"雨が降らないうちに、家に帰りましょう。","en":"Let''s go home before it starts raining.","romaji":"Ame ga furanai uchi ni, ie ni kaerimashō.","zh":""}]',replace('**Short**: Expresses doing something while a certain condition still holds; ''while'', ''before'', ''as long as''.\n\n**Formation**: Verb-casual + うちに, い-Adjective + うちに, な-Adjective + なうちに, Noun + のうちに\n\n**Long**: The ～うちに grammar point is used to indicate that an action should be done while a certain condition still exists or before a situation changes. It can be translated as ''while'', ''before'', or ''as long as'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_gai','～がい',NULL,NULL,'N2','[]','[{"ja":"この本は読みがいがあります。","en":"This book is worth reading.","romaji":"Kono hon wa yomi-gai ga arimasu.","zh":""},{"ja":"早起きしがいがあると思いますよ。","en":"I think it''s worth waking up early.","romaji":"Hayaoki shigai ga aru to omoimasu yo.","zh":""},{"ja":"長い時間をかけがいのある仕事だ。","en":"It''s a job worth spending a long time on.","romaji":"Nagai jikan o kake-gai no aru shigoto da.","zh":""},{"ja":"彼とは話しがいがあるでしょう。","en":"It''s worth talking to him.","romaji":"Kare to wa hanashi-gai ga aru deshō.","zh":""}]',replace('**Short**: Expresses ''worth doing'' for verbs.\n\n**Formation**: Verb-stem + がい\n\n**Long**: The ～がい grammar point is used to express that an action is worth doing or to emphasize the value and importance of doing something. It is attached to verbs in their stem form and can be translated as ''worth doing'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kaiga_atte','～かいがあって',NULL,NULL,'N2','[]','[{"ja":"毎日勉強したかいがあって、テストに合格しました。","en":"Studying every day paid off—I passed the test.","romaji":"Mainichi benkyō shita kai ga atte, tesuto ni gōkaku shimashita.","zh":""},{"ja":"練習のかいがあって、試合に勝つことができた。","en":"The practice paid off, and we were able to win the match.","romaji":"Renshū no kai ga atte, shiai ni katsu koto ga dekita.","zh":""},{"ja":"雨の中を走ってきたかいがあって、電車に間に合った。","en":"Running in the rain was worth it, as I made it to the train on time.","romaji":"Ame no naka o hashitte kita kai ga atte, densha ni maniatta.","zh":""},{"ja":"早起きして掃除をしたかいがあって、部屋がきれいになった。","en":"Waking up early to clean paid off; the room is now spotless.","romaji":"Hayaoki shite sōji o shita kai ga atte, heya ga kirei ni natta.","zh":""}]',replace('**Short**: Used to express that an effort is worth it or has value; ''to be worth the effort'' or ''to pay off''.\n\n**Formation**: Verb-past + かいがあって / Noun + の + かいがあって\n\n**Long**: The ～かいがあって grammar point is used to convey the idea that an action or effort is worth it, or that it has value. It is often translated as ''to be worth the effort'' or ''to pay off'' in English. It is typically associated with actions or efforts that lead to a successful or desirable result.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kai_mo_naku','～かいもなく',NULL,NULL,'N2','[]','[{"ja":"長い間苦労したかいもなく、失敗してしまった。","en":"I struggled for a long time, but in the end, it was all in vain and I failed.","romaji":"Nagai aida kurō shita kai mo naku, shippai shite shimatta.","zh":""},{"ja":"このプロジェクトにたくさん時間をかけたかいもなく、うまくいかなかった。","en":"I spent a lot of time on this project, but it ended fruitlessly.","romaji":"Kono purojekuto ni takusan jikan o kaketa kai mo naku, umaku ikanakatta.","zh":""},{"ja":"助けを求めたかいもなく、誰も来なかった。","en":"He asked for help, but it was in vain as no one came.","romaji":"Tasuke o motometa kai mo naku, dare mo konakatta.","zh":""},{"ja":"色々な方法でダイエットを試みたかいもなく、全然痩せなかった。","en":"I tried various diet methods, but it was all for nothing—I didn''t lose any weight.","romaji":"Iroirona hōhō de daietto o kokoromita kai mo naku, zenzen yasenakatta.","zh":""}]',replace('**Short**: Expresses the meaning of ''without worth'', ''in vain'', ''fruitless''.\n\n**Formation**: Verb-た + かいもなく / Noun + の + かいもなく\n\n**Long**: The ～かいもなく grammar point is used to express that something has been done without worth, in vain, or fruitlessly. It often appears as ''Verb-た + かいもなく'' or ''Noun + の + かいもなく'' to indicate that an effort did not produce the hoped-for result.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kakeru','～かける',NULL,NULL,'N2','[]','[{"ja":"彼女は食べかけのリンゴを置いて出かけた。","en":"She left a partially eaten apple and went out.","romaji":"Kanojo wa tabe-kake no ringo o oite dekaketa.","zh":""},{"ja":"子供たちはやりかけの宿題を机の上に残した。","en":"The children left their half-finished homework on the desk.","romaji":"Kodomotachi wa yari-kake no shukudai o tsukue no ue ni nokoshita.","zh":""},{"ja":"読みかけの本を夜になると探す。","en":"I look for the book I started reading once night comes.","romaji":"Yomi-kake no hon o yoru ni naru to sagasu.","zh":""},{"ja":"オフィスには、作りかけの書類がたくさんある。","en":"There are a lot of documents in the process of being created in the office.","romaji":"Ofisu ni wa, tsukuri-kake no shorui ga takusan aru.","zh":""}]',replace('**Short**: Indicates a process or action is ''in progress'' or ''halfway''.\n\n**Formation**: Verb-stem + かける\n\n**Long**: The ～かける grammar point is used to describe a process or action that is in progress, halfway, or not yet completed. It can be attached to verbs to imply that the action is still ongoing or something is in a certain state of partial completion.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_gachi','～がち',NULL,NULL,'N2','[]','[{"ja":"彼は風邪を引きがちです。","en":"He tends to catch colds easily.","romaji":"Kare wa kaze o hiki-gachi desu.","zh":""},{"ja":"この地域は雨が降りがちです。","en":"This area tends to get a lot of rain.","romaji":"Kono chiiki wa ame ga furi-gachi desu.","zh":""},{"ja":"彼女は忘れ物をしがちです。","en":"She tends to forget things.","romaji":"Kanojo wa wasuremono o shi-gachi desu.","zh":""},{"ja":"私は遅刻しがちなので、もっと早く起きないといけません。","en":"I tend to be late, so I need to wake up earlier.","romaji":"Watashi wa chikoku shi-gachi na no de, motto hayaku okinai to ikemasen.","zh":""}]',replace('**Short**: Expresses that something tends to occur frequently or habitually.\n\n**Formation**: Verb-ます stem + がち / い-Adjective stem + がち / な-Adjective stem + がち\n\n**Long**: The ～がち grammar point is used to express that something has a tendency to occur frequently or habitually. It can be attached to verbs and adjectives to indicate that the action or state tends to occur often.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ka_naika_no_uchi_ni','～か～ないかのうちに',NULL,NULL,'N2','[]','[{"ja":"駅に着くか着かないかのうちに、雨が降り出した。","en":"No sooner had I arrived at the station than it started raining.","romaji":"Eki ni tsuku ka tsukanai ka no uchi ni, ame ga furidashita.","zh":""},{"ja":"ケータイを買うか買わないかのうちに、新しいモデルが発売された。","en":"As soon as I decided to buy the cell phone, a new model was released.","romaji":"Keitai o kau ka kawanai ka no uchi ni, atarashii moderu ga hatsubai sareta.","zh":""},{"ja":"彼が家を出るか出ないかのうちに、電話が鳴った。","en":"The moment he left the house, the phone rang.","romaji":"Kare ga ie o deru ka denai ka no uchi ni, denwa ga natta.","zh":""},{"ja":"パーティーが始まるか始まらないかのうちに、彼女が泣き出した。","en":"As soon as the party began, she started crying.","romaji":"Pātī ga hajimaru ka hajimaranai ka no uchi ni, kanojo ga nakidashita.","zh":""}]',replace('**Short**: Expresses an action that occurs immediately after another action; ''as soon as'', ''no sooner than'', ''the moment''.\n\n**Formation**: Verb-casual + か + Verb-negative form + かのうちに\n\n**Long**: The ～か～ないかのうちに grammar point is used to express that an action occurs immediately after another action. In English, it can be translated as ''as soon as'', ''no sooner than'', or ''the moment''. This grammar point is used with verbs, showing the verb in both affirmative and negative forms with か and ないか, followed by のうちに.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kane_nai','～かねない',NULL,NULL,'N2','[]','[{"ja":"彼はあまりにも無責任で、約束を破りかねない。","en":"He is so irresponsible that he might break his promise.","romaji":"Kare wa amarini mo musekinin de, yakusoku o yaburi-kane nai.","zh":""},{"ja":"注意しないと、事故を起こしかねない。","en":"If you don''t pay attention, you might cause an accident.","romaji":"Chūi shinai to, jiko o okoshi-kane nai.","zh":""},{"ja":"このアプリはバグが多いので、クラッシュしかねない。","en":"Since this app has many bugs, it might crash.","romaji":"Kono apuri wa bagu ga ōi no de, kurasshu shi-kane nai.","zh":""},{"ja":"彼女は緊張しているので、失敗しかねない。","en":"She''s so nervous that she might fail.","romaji":"Kanojo wa kinchō shite iru no de, shippai shi-kane nai.","zh":""}]',replace('**Short**: Express the likelihood of a negative outcome or consequence.\n\n**Formation**: Verb-stem + かねない\n\n**Long**: The ～かねない grammar point is used to express the possibility or likelihood of a negative outcome or consequence, often used when there is concern about the result. It is typically used with verbs in their stem form and can be understood as ''might (have a bad result)''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kaneru','～かねる',NULL,NULL,'N2','[]','[{"ja":"その問題は難しいので、私には解決しかねます。","en":"Since that problem is difficult, I cannot solve it.","romaji":"Sono mondai wa muzukashii no de, watashi ni wa kaiketsu shi-kanemasu.","zh":""},{"ja":"彼の言っていることが真実かどうか判断しかねます。","en":"I cannot judge whether what he is saying is true or not.","romaji":"Kare no itte iru koto ga shinjitsu ka dō ka handan shi-kanemasu.","zh":""},{"ja":"彼女が来るかどうか今すぐには分かりかねます。","en":"I cannot immediately know whether she will come or not.","romaji":"Kanojo ga kuru ka dō ka ima sugu ni wa wakari-kanemasu.","zh":""},{"ja":"詳しい内容については説明しかねます。","en":"I cannot explain the details.","romaji":"Kuwashii naiyō ni tsuite wa setsumei shi-kanemasu.","zh":""}]',replace('**Short**: Express inability or impossibility of doing an action (often as a polite refusal).\n\n**Formation**: Verb-ます stem + かねる\n\n**Long**: The ～かねる grammar point is used to express that someone cannot do an action or that something is impossible to do. It typically has a nuance of reluctance or polite refusal and is formed by adding かねる to the ます-stem of the verb.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ka_no_you_da','～かのようだ',NULL,NULL,'N2','[]','[{"ja":"彼は犬が怖いかのようだ。","en":"He seems as if he is scared of dogs.","romaji":"Kare wa inu ga kowai ka no you da.","zh":""},{"ja":"この部屋は寒いかのようだ。","en":"This room feels as if it''s cold.","romaji":"Kono heya wa samui ka no you da.","zh":""},{"ja":"彼女は有名人であるかのようだ。","en":"She acts as though she is a celebrity.","romaji":"Kanojo wa yuumeijin de aru ka no you da.","zh":""},{"ja":"彼は子供であるかのようだ。","en":"He acts as if he''s a child.","romaji":"Kare wa kodomo de aru ka no you da.","zh":""}]',replace('**Short**: Express a similarity or comparison; ''as if'', ''like'', ''as though''.\n\n**Formation**: Verb-casual + かのようだ, い-Adjective + かのようだ, な-Adjective + であるかのようだ, Noun + であるかのようだ\n\n**Long**: The ～かのようだ grammar point is used to express similarity or comparison between two things or situations. It can be translated as ''as if'', ''like'', or ''as though'' in English. The standard patterns differ depending on whether it’s used with verbs, い-adjectives, な-adjectives, or nouns. For な-adjectives and nouns, we usually insert である before かのようだ.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ka_maika','～か～まいか',NULL,NULL,'N2','[]','[{"ja":"このプロジェクトを引き受けようか引き受けまいか、まだ決めていない。","en":"I haven''t decided whether to take on this project or not.","romaji":"Kono purojekuto o hikiukeyou ka hikiukemai ka, mada kimete inai.","zh":""},{"ja":"彼が成功しようか成功するまいか、今は予測できない。","en":"Whether he will succeed or not is unpredictable at the moment.","romaji":"Kare ga seikou shiyou ka seikou suru maika, ima wa yosoku dekinai.","zh":""},{"ja":"この問題は簡単であるか難しいであるまいか、意見が分かれている。","en":"Opinions are divided on whether this problem is simple or difficult.","romaji":"Kono mondai wa kantan de aru ka muzukashii de aru maika, iken ga wakarete iru.","zh":""},{"ja":"彼はリーダーであるかフォロワーであるまいか、自分で選ぶべきだ。","en":"He should choose for himself whether he is a leader or a follower.","romaji":"Kare wa riidā de aru ka forowā de aru maika, jibun de erabu beki da.","zh":""}]',replace('**Short**: Used to express a dilemma or indecision between two options or actions.\n\n**Formation**: Verb-volitional + か + Verb-volitional + まいか, い-Adjective + であるか + い-Adjective + であるまいか, な-Adjective + であるか + な-Adjective + であるまいか, Noun + であるか + Noun + であるまいか\n\n**Long**: The ～か～まいか grammar point expresses uncertainty or indecision, often with a more formal or literary feel. Typically, it is seen with verbs in the volitional form plus まい (the negative volitional). In more academic or stiff writing, い／な-adjectives and nouns plus である can also appear before まいか.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kara_koso','～からこそ',NULL,NULL,'N2','[]','[{"ja":"失敗したからこそ、成功の意味がわかる。","en":"It is precisely because I failed that I understand the meaning of success.","romaji":"Shippai shita kara koso, seikou no imi ga wakaru.","zh":""},{"ja":"苦しかったからこそ、今日の私がある。","en":"It is precisely because I went through hardships that I am who I am today.","romaji":"Kurushikatta kara koso, kyou no watashi ga aru.","zh":""},{"ja":"彼は親切だからこそ、人気がある。","en":"He is popular precisely because he is kind.","romaji":"Kare wa shinsetsu da kara koso, ninki ga aru.","zh":""},{"ja":"昔の経験があるからこそ、その問題がよく理解できる。","en":"I can understand that problem well precisely because I have past experience.","romaji":"Mukashi no keiken ga aru kara koso, sono mondai ga yoku rikai dekiru.","zh":""}]',replace('**Short**: Express the emphasis on the reason; ''precisely because'', ''it is precisely because''.\n\n**Formation**: Verb-casual + からこそ, い-Adjective + からこそ, な-Adjective + だからこそ, Noun + だからこそ\n\n**Long**: The ～からこそ grammar point is used to emphasize the reason or cause of a situation, often implying that the effect is especially notable or even surprising. It can be translated as ''precisely because'' or ''it is precisely because.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kara_shite','〜からして',NULL,NULL,'N2','[]','[{"ja":"彼の顔つきからして、何か悪いことがあったのだろう。","en":"From his facial expression, something bad must have happened.","romaji":"Kare no kaotsuki kara shite, nanika warui koto ga atta no darou.","zh":""},{"ja":"この料理の見た目からして、おいしくなさそうだ。","en":"Judging from the appearance of this dish, it doesn''t look delicious.","romaji":"Kono ryouri no mitame kara shite, oishikunasa sou da.","zh":""},{"ja":"彼女の試験成績からして、合格するのは難しいでしょう。","en":"Considering her test scores, it will be difficult for her to pass.","romaji":"Kanojo no shiken seiseki kara shite, goukaku suru no wa muzukashii deshou.","zh":""},{"ja":"その映画のタイトルからして、面白くないと思う。","en":"Judging from the title of the movie, I think it''s not interesting.","romaji":"Sono eiga no taitoru kara shite, omoshirokunai to omou.","zh":""}]',replace('**Short**: Expresses that something is exceptional, unusual, or negative based on a particular aspect or point.\n\n**Formation**: Noun + からして\n\n**Long**: The 〜からして grammar point is used when you want to make a conclusion or emphasize that something is exceptional (often negative or surprising) from a certain aspect or starting point. The part before からして serves as the base or clue for the judgment.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kara_suru_to','～からすると',NULL,NULL,'N2','[]','[{"ja":"経験からすると、この仕事は難しいでしょう。","en":"Considering their experience, this job might be difficult.","romaji":"Keiken kara suru to, kono shigoto wa muzukashii deshou.","zh":""},{"ja":"評判からすると、あのレストランはとても美味しいです。","en":"Judging from the reputation, that restaurant is very delicious.","romaji":"Hyouban kara suru to, ano resutoran wa totemo oishii desu.","zh":""},{"ja":"価格からすると、この商品は高品質のものと思われます。","en":"Considering the price, this product seems to be of high quality.","romaji":"Kakaku kara suru to, kono shouhin wa kouhinshitsu no mono to omowaremasu.","zh":""},{"ja":"このエリアですが、交通の便からすると、便利です。","en":"As for this area, considering the transportation convenience, it''s convenient.","romaji":"Kono eria desu ga, koutsuu no ben kara suru to, benri desu.","zh":""}]',replace('**Short**: Expresses a judgment or evaluation based on a certain standard; ''from this perspective'', ''considering'', ''judging from''.\n\n**Formation**: Noun + からすると\n\n**Long**: The ～からすると grammar point is used to make a judgment or evaluation based on some criterion, perspective, or standard. It can be translated as ''from this perspective'', ''considering'', or ''judging from'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kara_to_itte','～からといって',NULL,NULL,'N2','[]','[{"ja":"雨が降ったからといって、試合が中止になるわけではありません。","en":"Just because it rained doesn''t mean the game will be canceled.","romaji":"Ame ga futta kara to itte, shiai ga chuushi ni naru wake de wa arimasen.","zh":""},{"ja":"彼が有名だからといって、彼の意見がいつも正しいわけではない。","en":"Just because he is famous doesn''t mean his opinions are always correct.","romaji":"Kare ga yuumei da kara to itte, kare no iken ga itsumo tadashii wake de wa nai.","zh":""},{"ja":"このスープが辛いからといって、全ての人が辛いと感じるわけではない。","en":"Just because this soup is spicy doesn''t mean everyone will find it spicy.","romaji":"Kono suupu ga karai kara to itte, subete no hito ga karai to kanjiru wake de wa nai.","zh":""},{"ja":"彼女が泣いているからといって、悲しいわけではないかもしれない。","en":"Just because she is crying doesn''t necessarily mean she''s sad.","romaji":"Kanojo ga naiteiru kara to itte, kanashii wake de wa nai kamoshirenai.","zh":""}]',replace('**Short**: Expresses ''just because...doesn''t mean'' or ''even though...not necessarily''.\n\n**Formation**: Verb-casual + からといって, い-Adjective + からといって, な-Adjective + だからといって, Noun + だからといって\n\n**Long**: The ～からといって grammar point is used to convey that even though something is true, it does not necessarily mean a certain result will occur. It can be translated as ''just because...doesn''t mean'' or ''even though...not necessarily.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kara_ni_kakete_n2','～から～にかけて',NULL,NULL,'N2','[]','[{"ja":"午前９時から午後５時にかけて、仕事をしています。","en":"I work from 9 in the morning to 5 in the evening.","romaji":"Gozen ku-ji kara gogo go-ji ni kakete, shigoto wo shite imasu.","zh":""},{"ja":"東京から大阪にかけて、新幹線が走っています。","en":"The bullet train runs from Tokyo to Osaka.","romaji":"Toukyou kara Oosaka ni kakete, shinkansen ga hashitte imasu.","zh":""},{"ja":"春から夏にかけて、花がたくさん咲いています。","en":"Many flowers bloom between spring and summer.","romaji":"Haru kara natsu ni kakete, hana ga takusan saite imasu.","zh":""},{"ja":"２０歳から３０歳にかけて、多くの人が大学を卒業し、仕事に就くことが一般的です。","en":"It is common for many people to graduate from university and start working between the ages of 20 and 30.","romaji":"Hatachi kara sanjuu-sai ni kakete, ooku no hito ga daigaku wo sotsugyou shi, shigoto ni tsuku koto ga ippan-teki desu.","zh":""}]',replace('**Short**: Expresses a range of time, space, or quantities; ''from...to'', ''between...and'', ''over''.\n\n**Formation**: Noun 1 + から + Noun 2 + にかけて\n\n**Long**: The ～から～にかけて grammar pattern is used to indicate a range or scope—often in time or space. It can be translated as ''from...to'', ''between...and'', or ''over'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kara_niwa','～からには',NULL,NULL,'N2','[]','[{"ja":"試験に合格したからには、一所懸命働かなければならない。","en":"Since I passed the exam, I have to work hard.","romaji":"Shiken ni goukaku shita kara niwa, isshokenmei hatarakanakereba naranai.","zh":""},{"ja":"約束したからには、守らなければなりません。","en":"Since I made a promise, I must keep it.","romaji":"Yakusoku shita kara niwa, mamoranakereba narimasen.","zh":""},{"ja":"この映画が面白いからには、友達にも見せたい。","en":"Since this movie is interesting, I want to show it to my friends too.","romaji":"Kono eiga ga omoshiroi kara niwa, tomodachi ni mo misetai.","zh":""},{"ja":"彼女が助けを求めたからには、手伝わなければならない。","en":"Since she asked for help, I must help her.","romaji":"Kanojo ga tasuke wo motometa kara niwa, tetsudawanakereba naranai.","zh":""}]',replace('**Short**: Express a sense of responsibility or determination; ''since'', ''now that'', ''if''.\n\n**Formation**: Noun + だ + からには, な-Adjective + だ + からには, い-Adjective + からには, Verb-casual + からには\n\n**Long**: The ～からには grammar point is used to show a sense of responsibility or strong resolve once a certain condition is met. It can be translated as ''since'', ''now that'', or ''if''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kara_miru_to','～から見ると',NULL,NULL,'N2','[]','[{"ja":"費用から見ると、このプランはお得です。","en":"In terms of cost, this plan is a good deal.","romaji":"Hiyou kara miru to, kono puran wa otoku desu.","zh":""},{"ja":"彼女の意見から見ると、社長の決定は理解できる。","en":"From her perspective, the president''s decision is understandable.","romaji":"Kanojo no iken kara miru to, shachou no kettei wa rikai dekiru.","zh":""},{"ja":"実力から見ると、彼はチームで最も優れている。","en":"In terms of ability, he is the best in the team.","romaji":"Jitsuryoku kara miru to, kare wa chiimu de mottomo sugurete iru.","zh":""},{"ja":"健康面から見ると、この食品は良くない。","en":"From the standpoint of health, this food is not good.","romaji":"Kenkoumen kara miru to, kono shokuhin wa yokunai.","zh":""}]',replace('**Short**: Express a perspective or point of view; ''from the standpoint of'', ''in terms of'', ''from the perspective of''.\n\n**Formation**: Noun + から見ると\n\n**Long**: The ～から見ると grammar point is used to express a particular perspective or point of view. In English, it translates to ''from the standpoint of'', ''from the perspective of'', or ''in terms of''. It is usually used with a noun that indicates the perspective.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kara_iuto','～から言うと',NULL,NULL,'N2','[]','[{"ja":"値段から言うと、この商品が最もお得です。","en":"Speaking from the viewpoint of price, this product is the best deal.","romaji":"Nedan kara iuto, kono shouhin ga mottomo otoku desu.","zh":""},{"ja":"味から言って、このレストランはおいしいと思います。","en":"In terms of taste, I think this restaurant is delicious.","romaji":"Aji kara itte, kono resutoran wa oishii to omoimasu.","zh":""},{"ja":"便利さから言って、このアパートは最適な場所にあります。","en":"Speaking from the perspective of convenience, this apartment is in the best location.","romaji":"Benrisa kara itte, kono apaato wa saiteki na basho ni arimasu.","zh":""},{"ja":"健康から言うと、毎日運動することが大切です。","en":"From the viewpoint of health, it is important to exercise every day.","romaji":"Kenkou kara iuto, mainichi undou suru koto ga taisetsu desu.","zh":""}]',replace('**Short**: Express a judgment or opinion based on a specific criterion; ''speaking from'', ''in terms of'', ''from the viewpoint of''.\n\n**Formation**: Noun + から言うと (common), [Verb-casual / Adjective + から言って] (less common)\n\n**Long**: The ～から言うと grammar point is used to express a judgment or opinion based on a specific criterion or aspect. It can be translated as ''speaking from'', ''in terms of'', or ''from the viewpoint of'' in English. It is most commonly used with nouns, although you may occasionally see other forms (like adjectives).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kuse_ni_n2','～くせに',NULL,NULL,'N2','[]','[{"ja":"彼はいつも遅刻してくるくせに、自分が待たされるのが嫌いだ。","en":"He’s always late, yet he hates being kept waiting.","romaji":"Kare wa itsumo chikoku shite kuru kuse ni, jibun ga matasareru no ga kirai da.","zh":""},{"ja":"悪いなと言ってるくせに、また同じことを繰り返している。","en":"He says he''s sorry, yet he keeps doing the same thing.","romaji":"Warui na to itteru kuse ni, mata onaji koto o kurikaeshite iru.","zh":""},{"ja":"彼は背が高いくせに、バスケが下手だ。","en":"Despite being tall, he''s bad at basketball.","romaji":"Kare wa se ga takai kuse ni, basuke ga heta da.","zh":""},{"ja":"この店は有名なのくせに、サービスが悪い。","en":"Despite being famous, this store has poor service.","romaji":"Kono mise wa yuumei na no kuse ni, saabisu ga warui.","zh":""}]',replace('**Short**: Used to criticize someone for doing something contrary to what one would expect from their nature or situation.\n\n**Formation**: Verb (casual) + くせに / い-Adjective + くせに / な-Adjective + な(or の) + くせに / Noun + の + くせに\n\n**Long**: The grammar point ～くせに is used to express criticism or disapproval toward someone who does something contradictory to their expected nature, role, or prior statement. It''s used in fairly casual or spoken contexts and can sound quite critical or accusing. Note that there''s a colloquial variant ～くせして, but ～くせに is the standard form taught in most references.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_koto_kara','～ことから',NULL,NULL,'N2','[]','[{"ja":"彼は毎日運動することから、体が丈夫です。","en":"Because he exercises every day, he is physically strong.","romaji":"Kare wa mainichi undou suru koto kara, karada ga joubu desu.","zh":""},{"ja":"この店のサービスがいいことから、いつも混んでいます。","en":"This store is always crowded because of its good service.","romaji":"Kono mise no saabisu ga ii koto kara, itsumo konde imasu.","zh":""},{"ja":"彼女は親切なことから、みんなに好かれています。","en":"She’s well-liked by everyone due to her kindness.","romaji":"Kanojo wa shinsetsu na koto kara, minna ni sukarete imasu.","zh":""},{"ja":"その会社の評判が良いことから、就職先として人気があります。","en":"Because that company’s reputation is good, it’s popular as a place to work.","romaji":"Sono kaisha no hyouban ga yoi koto kara, shuushoku-saki toshite ninki ga arimasu.","zh":""}]',replace('**Short**: Indicates the reason or basis for something; ''because'', ''since'', ''due to''.\n\n**Formation**: Verb-casual + ことから / い-Adjective + ことから / な-Adjective + なことから / Noun + のことから\n\n**Long**: The ～ことから grammar point is used to indicate the reason or basis for a conclusion, fact, or premise. It can be translated as ''because'', ''since'', or ''due to'' in English. The same pattern is used whether it’s with verbs, adjectives, or nouns (with the appropriate こと or の).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_koto_ni','～ことに',NULL,NULL,'N2','[]','[{"ja":"彼が急に帰国することに驚いた。","en":"I was surprised that he suddenly returned to his home country.","romaji":"Kare ga kyuu ni kikoku suru koto ni odoroita.","zh":""},{"ja":"彼女が優勝したことに感動した。","en":"I was moved by the fact that she won the championship.","romaji":"Kanojo ga yuushou shita koto ni kandou shita.","zh":""},{"ja":"彼がいつも遅刻することに腹が立つ。","en":"I get angry that he is always late.","romaji":"Kare ga itsumo chikoku suru koto ni hara ga tatsu.","zh":""},{"ja":"彼女がこんなに美しいことに気がつかなかった。","en":"I hadn’t realized how beautiful she was.","romaji":"Kanojo ga konna ni utsukushii koto ni ki ga tsukanakatta.","zh":""}]',replace('**Short**: Used to express feelings or emotions about a situation, action, or outcome.\n\n**Formation**: Verb-casual + ことに / い-Adjective + ことに / な-Adjective + なことに / Noun + のことに\n\n**Long**: The ～ことに grammar point is used to highlight the speaker’s feelings or emotional reaction toward a situation, action, or outcome. It often appears in constructions like 驚いたことに, 残念なことに, 不思議なことに, etc.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_koto_ni_natte_iru_n2','～ことになっている',NULL,NULL,'N2','[]','[{"ja":"日本では、左側を運転することになっています。","en":"In Japan, it is decided that people drive on the left side.","romaji":"Nihon de wa, hidarigawa o unten suru koto ni natte imasu.","zh":""},{"ja":"会社の規則では、制服を着ることになっている。","en":"According to the company rules, we are supposed to wear uniforms.","romaji":"Kaisha no kisoku de wa, seifuku o kiru koto ni natte iru.","zh":""},{"ja":"彼女は明日結婚することになっています。","en":"She is supposed to get married tomorrow.","romaji":"Kanojo wa ashita kekkon suru koto ni natte imasu.","zh":""},{"ja":"この商品は高品質だということになっています。","en":"It is said (or generally accepted) that this product is of high quality.","romaji":"Kono shouhin wa kouhinshitsu da to iu koto ni natte imasu.","zh":""}]',replace('**Short**: Expresses that something is supposed to be or has been decided (rule, plan, custom).\n\n**Formation**: Verb-plain form + ことになっている / い-Adjective + ことになっている / な-Adjective + だ + ことになっている / Noun + だ + ことになっている\n\n**Long**: The ～ことになっている grammar point is used when something has been decided, planned, or there is a rule/custom that everyone follows. It can be translated as ''it is supposed to be,'' ''it is decided,'' or ''it is customary that.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sae_ba','～さえ～ば',NULL,NULL,'N2','[]','[{"ja":"お金さえあれば、幸せです。","en":"As long as I have money, I’m happy.","romaji":"Okane sae areba, shiawase desu.","zh":""},{"ja":"試験に合格しさえすれば、卒業できます。","en":"If only I pass the exam, I can graduate.","romaji":"Shiken ni goukaku shi sae sureba, sotsugyou dekimasu.","zh":""},{"ja":"野菜さえたくさん食べれば、母は喜びます。","en":"As long as I eat plenty of vegetables, my mother will be happy.","romaji":"Yasai sae takusan tabereba, haha wa yorokobimasu.","zh":""},{"ja":"交通費さえ支払ってもらえれば、どこへでも行きます。","en":"As long as my transportation costs are covered, I’ll go anywhere.","romaji":"Koutsuuhi sae shiharatte moraereba, doko e demo ikimasu.","zh":""}]',replace('**Short**: Expresses that, as long as a certain condition is met, something else will follow; ''if only'', ''provided that''.\n\n**Formation**: Noun + さえ + Verb-conditional / Verb-ますstem + さえすれば / etc. (varies by part of speech)\n\n**Long**: The ～さえ～ば grammar point is used to indicate that if a certain single condition is fulfilled, everything else will be fine or a certain result will occur. It often translates as ''as long as...'' or ''if only...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_zaru_wo_enai_n2','～ざるを得ない',NULL,NULL,'N2','[]','[{"ja":"この仕事は締め切りが近いので、残業せざるを得ない。","en":"Since the deadline is near, I have no choice but to work overtime.","romaji":"Kono shigoto wa shimekiri ga chikai no de, zangyou sezaru wo enai.","zh":""},{"ja":"電車が遅れたため、タクシーに乗るざるを得なかった。","en":"Because the train was delayed, I had no choice but to take a taxi.","romaji":"Densha ga okureta tame, takushii ni noru zaru wo enakatta.","zh":""},{"ja":"彼女の説明が納得できなかったが、とりあえず信じざるを得ない。","en":"I couldn’t really accept her explanation, but for now I have no choice but to believe her.","romaji":"Kanojo no setsumei ga nattoku dekinakatta ga, toriaezu shinjizaru wo enai.","zh":""},{"ja":"この状況では、新しい計画を立て直さざるを得ない。","en":"In this situation, we have no choice but to revise the new plan.","romaji":"Kono joukyou de wa, atarashii keikaku wo tatenaosazaru wo enai.","zh":""}]',replace('**Short**: Have no choice but to; cannot help but.\n\n**Formation**: Verb-ない form (drop ない) + ざるを得ない\n\n**Long**: The ～ざるを得ない grammar point is used to indicate that one has no choice but to do something or cannot avoid doing it. It is formed from the negative form (ない) but replaces ない with ざる, followed by を得ない. (Note: する → せざるを得ない.)\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_zu_ni_wa_irarenai','～ずにはいられない',NULL,NULL,'N2','[]','[{"ja":"この曲を聞くと、歌わずにはいられない。","en":"When I hear this song, I can’t help but sing.","romaji":"Kono kyoku o kiku to, utawazu ni wa irarenai.","zh":""},{"ja":"彼女が泣いているのを見ると、慰めずにはいられない。","en":"When I see her crying, I can’t resist comforting her.","romaji":"Kanojo ga naite iru no o miru to, nagusamezu ni wa irarenai.","zh":""},{"ja":"この小説は面白いので、読まずにはいられない。","en":"This novel is so interesting that I can’t help but read it.","romaji":"Kono shousetsu wa omoshiroi no de, yomazu ni wa irarenai.","zh":""},{"ja":"彼はおいしい料理を前にすると、食べずにはいられない。","en":"When he’s faced with delicious food, he can’t help but eat it.","romaji":"Kare wa oishii ryouri o mae ni suru to, tabezu ni wa irarenai.","zh":""}]',replace('**Short**: Cannot help but; cannot resist doing; an irresistible urge.\n\n**Formation**: Verb-ない form (drop ない) + ずにはいられない\n\n**Long**: The ～ずにはいられない grammar point expresses that one cannot resist or help doing something. In other words, there is a strong urge that one cannot suppress. It''s formed from the negative stem of a verb plus ずにはいられない. (Note: する → せずにはいられない.)\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sou_ni_nai','～そうにない',NULL,NULL,'N2','[]','[{"ja":"この雨は止みそうにない。","en":"It doesn''t seem like this rain will stop.","romaji":"Kono ame wa yami sou ni nai.","zh":""},{"ja":"彼が試験に合格しそうにない。","en":"It doesn''t look like he''ll pass the exam.","romaji":"Kare ga shiken ni goukaku shi sou ni nai.","zh":""},{"ja":"この料理がおいしそうにない。","en":"This dish doesn''t look like it will be tasty.","romaji":"Kono ryouri ga oishisou ni nai.","zh":""},{"ja":"この部屋はきれいそうにない。","en":"This room doesn''t seem likely to be clean.","romaji":"Kono heya wa kirei sou ni nai.","zh":""}]',replace('**Short**: Express the unlikelihood of something happening; ''not likely'', ''doesn''t seem''.\n\n**Formation**: Verb-stem + そうにない / い-Adjective (drop い) + そうにない / な-Adjective + そうにない\n\n**Long**: The ～そうにない grammar point is used to indicate that something does not appear likely to happen. Often translated as ''doesn''t seem like'' or ''not likely to...''. Attach そうにない to the verb stem or adjective stem.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ta_ka_to_omottara','～たかと思ったら',NULL,NULL,'N2','[]','[{"ja":"電話をかけたかと思ったら、すぐに彼女が出た。","en":"No sooner had I called than she picked up.","romaji":"Denwa o kaketa ka to omottara, sugu ni kanojo ga deta.","zh":""},{"ja":"離陸したかと思ったら、飛行機が揺れ始めた。","en":"As soon as we took off, the plane started shaking.","romaji":"Ririku shita ka to omottara, hikouki ga yure hajimeta.","zh":""},{"ja":"買い物に行ったかと思ったら、雨が降ってきた。","en":"No sooner had I gone shopping than it began to rain.","romaji":"Kaimono ni itta ka to omottara, ame ga futte kita.","zh":""},{"ja":"仕事を終わったかと思ったら、上司が追加の仕事を持ってきた。","en":"As soon as I finished work, my boss brought more tasks.","romaji":"Shigoto o owatta ka to omottara, joushi ga tsuika no shigoto o motte kita.","zh":""}]',replace('**Short**: Express a sequence of events happening in quick succession; ''as soon as'', ''no sooner than''.\n\n**Formation**: Verb-た form + かと思ったら\n\n**Long**: The ～たかと思ったら grammar point indicates that one action occurs almost immediately after another, often conveying surprise at how quickly it happens. It is frequently translated as ''as soon as...'' or ''no sooner than...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_takiri','～たきり',NULL,NULL,'N2','[]','[{"ja":"彼は会社を辞めたきり、連絡がない。","en":"Ever since he quit the company, there''s been no contact.","romaji":"Kare wa kaisha o yameta kiri, renraku ga nai.","zh":""},{"ja":"昨日の朝、メールを送ったきり、返事がない。","en":"I sent an email yesterday morning, and there''s been no reply since then.","romaji":"Kinō no asa, mēru o okutta kiri, henji ga nai.","zh":""},{"ja":"子供のころ海に行ったきりで、もう20年になる。","en":"It''s been 20 years since I last went to the sea as a child.","romaji":"Kodomo no koro umi ni itta kiri de, mō nijūnen ni naru.","zh":""},{"ja":"彼女と別れたきり、彼女のことを考えなくなった。","en":"Ever since I broke up with her, I stopped thinking about her.","romaji":"Kanojo to wakareta kiri, kanojo no koto o kangaenaku natta.","zh":""}]',replace('**Short**: Express ''since then'' or ''after''; used to indicate that an action occurred once and has not been repeated or that a state has continued since a certain event or time.\n\n**Formation**: Verb-past + きり\n\n**Long**: The ～たきり grammar point is used to express that an action occurred once and has not been repeated, or that a situation or state has continued since a certain event or time. It can be translated as ''since then'', ''after'', or ''one time only'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dake_atte','～だけあって',NULL,NULL,'N2','[]','[{"ja":"彼は日本語が上手だけあって、日本人のように話すことができる。","en":"As expected from his good Japanese skills, he can speak like a native.","romaji":"Kare wa nihongo ga jōzu dake atte, nihonjin no yō ni hanasu koto ga dekiru.","zh":""},{"ja":"このレストランは有名だけあって、料理がとても美味しい。","en":"No wonder this restaurant is famous; the food is very delicious.","romaji":"Kono resutoran wa yūmei dake atte, ryōri ga totemo oishii.","zh":""},{"ja":"彼女は経験豊富なだけあって、その問題を簡単に解決できた。","en":"It''s natural that she''s experienced; she solved the problem easily.","romaji":"Kanojo wa keiken hōfu na dake atte, sono mondai o kantan ni kaiketsu dekita.","zh":""},{"ja":"彼は優秀な学生だけあって、いつもテストの点数が高い。","en":"As expected of an excellent student, he always scores high on tests.","romaji":"Kare wa yūshū na gakusei dake atte, itsumo tesuto no tensū ga takai.","zh":""}]',replace('**Short**: Expresses that something is as expected or deserves its reputation.\n\n**Formation**: Verb-casual + だけあって, い-Adjective + だけあって, な-Adjective + なだけあって, Noun + だけあって\n\n**Long**: The ～だけあって grammar point is used to indicate that something is as expected or deserves its reputation, based on certain facts or qualities. It can be translated as ''no wonder'', ''as expected'', or ''it is natural that'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dake_mashi_da','～だけましだ',NULL,NULL,'N2','[]','[{"ja":"失敗するだけましだ。もっと大変なことにならなくてよかった。","en":"At least we only failed—it could’ve been much worse.","romaji":"Shippai suru dake mashi da. Motto taihen na koto ni naranakute yokatta.","zh":""},{"ja":"遅れるだけましだ。来られないよりはいい。","en":"At least I’m only late. It’s better than not being able to come at all.","romaji":"Okureru dake mashi da. Korarenai yori wa ii.","zh":""},{"ja":"小さな部屋だけましだ。全く部屋がないよりはいい。","en":"At least we have a small room; it’s better than having no room at all.","romaji":"Chīsana heya dake mashi da. Mattaku heya ga nai yori wa ii.","zh":""},{"ja":"彼が結婚しないだけましだ。大変なことになるところだったよ。","en":"At least he’s not getting married—things could have gotten complicated.","romaji":"Kare ga kekkon shinai dake mashi da. Taihen na koto ni naru tokoro datta yo.","zh":""}]',replace('**Short**: Expresses that although the situation isn’t ideal, it could be worse; ''it’s not great, but at least...''.\n\n**Formation**: Verb-casual + だけましだ, い-Adjective + だけましだ, な-Adjective + だけましだ, Noun + だけましだ\n\n**Long**: The ～だけましだ grammar point is used to compare two undesirable or less-than-ideal situations, saying that one is not good, but still better than the worse alternative. It often translates as ''at least (it’s only...)'' or ''it could be worse.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ta_tokoro_n2','～たところ',NULL,NULL,'N2','[]','[{"ja":"掃除したところ、部屋がずっとキレイになりました。","en":"I just finished cleaning, and the room is so much cleaner now.","romaji":"Sōji shita tokoro, heya ga zutto kirei ni narimashita.","zh":""},{"ja":"彼に聞いたところ、その質問の答えは分からないみたいです。","en":"I just asked him, and it seems he doesn''t know the answer.","romaji":"Kare ni kiita tokoro, sono shitsumon no kotae wa wakaranai mitai desu.","zh":""},{"ja":"宿題を出したところ、先生が間違いを見つけました。","en":"As soon as I turned in my homework, the teacher found a mistake.","romaji":"Shukudai o dashita tokoro, sensei ga machigai o mitsukemashita.","zh":""},{"ja":"昼ごはんを食べたところ、気分が良くなりました。","en":"Right after eating lunch, I started feeling better.","romaji":"Hirugohan o tabeta tokoro, kibun ga yoku narimashita.","zh":""}]',replace('**Short**: Used to describe an action that has just been completed, often followed by a result or observation.\n\n**Formation**: Verb-past + ところ\n\n**Long**: The ～たところ grammar point is used when an action has just been completed and the speaker wants to describe an observation or result that follows. It can be translated as ''just finished doing something'' or ''as soon as (I did something)...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ta_totan_n2','～たとたん',NULL,NULL,'N2','[]','[{"ja":"ドアを開けたとたん、雨が降り始めた。","en":"As soon as I opened the door, it started raining.","romaji":"Doa o aketa totan, ame ga furi-hajimeta.","zh":""},{"ja":"電話をかけたとたん、バッテリーが切れた。","en":"Just when I made the phone call, the battery died.","romaji":"Denwa o kaketa totan, batterī ga kireta.","zh":""},{"ja":"彼女に会ったとたん、思い出の歌が流れた。","en":"No sooner had I met her than a nostalgic song started playing.","romaji":"Kanojo ni atta totan, omoide no uta ga nagareta.","zh":""},{"ja":"テストが終わったとたん、リラックスできた。","en":"The moment the test ended, I was able to relax.","romaji":"Tesuto ga owatta totan, rirakkusu dekita.","zh":""}]',replace('**Short**: Express the moment something happens; ''as soon as'', ''just when''.\n\n**Formation**: Verb-past + たとたん\n\n**Long**: The ～たとたん grammar point is used to express that an action or event occurred at the same moment another action or event happened. It can be translated as ''as soon as'' or ''just when.'' It requires the past tense of a verb.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_darake','～だらけ',NULL,NULL,'N2','[]','[{"ja":"彼の部屋はゴミだらけだ。","en":"His room is full of trash.","romaji":"Kare no heya wa gomi darake da.","zh":""},{"ja":"このビーチは岩だらけで泳ぎにくい。","en":"This beach is full of rocks and is difficult to swim at.","romaji":"Kono bīchi wa iwa darake de oyogi nikui.","zh":""},{"ja":"彼の顔はしわだらけだ。","en":"His face is covered with wrinkles.","romaji":"Kare no kao wa shiwa darake da.","zh":""},{"ja":"このリンゴは虫食いだらけだ。","en":"This apple is riddled with wormholes.","romaji":"Kono ringo wa mushikui darake da.","zh":""}]',replace('**Short**: Indicates that something is full of or covered with a certain (usually negative) characteristic.\n\n**Formation**: Noun + だらけ\n\n**Long**: The ～だらけ grammar point is used to express that something is full of, covered with, or filled with a certain characteristic. It frequently has a negative or undesirable nuance.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kkonai','～っこない',NULL,NULL,'N2','[]','[{"ja":"こんなに雪が降っているんだから、学校に間に合いっこない。","en":"With snow falling this heavily, there''s no way we''ll make it to school on time.","romaji":"Konna ni yuki ga futteirun dakara, gakkō ni maniai kkonai.","zh":""},{"ja":"彼は泳げないので、プールの向こう側に泳いで行きっこない。","en":"Since he can’t swim, there’s no way he’ll make it to the other side of the pool.","romaji":"Kare wa oyogenai node, pūru no mukōgawa ni oyoide ikkonai.","zh":""},{"ja":"彼女はとても怖がりなので、一人で夜の公園に行きっこない。","en":"She’s so timid, there’s no chance she’d go to the park alone at night.","romaji":"Kanojo wa totemo kowagari na node, hitori de yoru no kōen ni ikkonai.","zh":""},{"ja":"この短い時間で、その本を全部読むことはできっこない。","en":"It''s impossible to read the entire book in such a short time.","romaji":"Kono mijikai jikan de, sono hon o zenbu yomu koto wa dekikkonai.","zh":""}]',replace('**Short**: Expresses the impossibility or very low probability of something happening; ''no way'', ''impossible''.\n\n**Formation**: Verb-negative stem + っこない\n\n**Long**: The ～っこない grammar point is used to express that something is impossible or extremely unlikely. It’s formed by attaching ～っこない to the negative stem of a verb. It can be translated as ''no way'', ''no chance'', or ''impossible.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tsutsu','～つつ',NULL,NULL,'N2','[]','[{"ja":"彼はテレビを見つつ、宿題をしていました。","en":"He was doing his homework while watching TV.","romaji":"Kare wa terebi o mitsutsu, shukudai o shite imashita.","zh":""},{"ja":"最近忙しいと思いつつ、毎日運動を続けています。","en":"Although I feel busy these days, I still exercise every day.","romaji":"Saikin isogashii to omoi tsutsu, mainichi undō o tsuzukete imasu.","zh":""},{"ja":"彼女は泣きつつ、笑顔で別れを告げた。","en":"She was crying, yet she said goodbye with a smile on her face.","romaji":"Kanojo wa naki tsutsu, egao de wakare o tsugeta.","zh":""},{"ja":"雨に濡れつつ、彼は歩き続けました。","en":"He continued walking even though he was getting soaked by the rain.","romaji":"Ame ni nure tsutsu, kare wa aruki tsuzukemashita.","zh":""}]',replace('**Short**: Shows two actions happening simultaneously or a contrast; ''while'', ''although''.\n\n**Formation**: Verb-stem + つつ\n\n**Long**: The ～つつ grammar point is used to express two actions occurring simultaneously, or to show a contrast between an ongoing action and another factor. It can be translated as ''while'' or ''although.'' It is attached to a verb in its stem form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tsutsu_aru','～つつある',NULL,NULL,'N2','[]','[{"ja":"地球温暖化は進行しつつある。","en":"Global warming is in progress.","romaji":"Chikyū ondanka wa shinkō shitsutsu aru.","zh":""},{"ja":"この町は急速に発展しつつある。","en":"This town is rapidly developing.","romaji":"Kono machi wa kyūsoku ni hatten shitsutsu aru.","zh":""},{"ja":"子供たちは成長しつつある。","en":"The children are growing up.","romaji":"Kodomo-tachi wa seichō shitsutsu aru.","zh":""},{"ja":"景気が回復しつつある。","en":"The economy is recovering.","romaji":"Keiki ga kaifuku shitsutsu aru.","zh":""}]',replace('**Short**: Expresses an ongoing process or gradual change.\n\n**Formation**: Verb-stem + つつある\n\n**Long**: The ～つつある grammar point is used to describe something that is in the middle of a gradual change or development. It can be translated as ''(something) is in the process of ~ing.'' The most common usage is with the verb stem plus つつある.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ppanashi_n2','～っぱなし',NULL,NULL,'N2','[]','[{"ja":"窓を開けっぱなしにして、部屋が寒くなってしまった。","en":"I left the window open, and the room got cold.","romaji":"Mado o akeppanashi ni shite, heya ga samuku natte shimatta.","zh":""},{"ja":"彼は音楽を聴くのが好きで、いつもイヤホンをつけっぱなしです。","en":"He loves listening to music and always has his earphones on.","romaji":"Kare wa ongaku o kiku no ga suki de, itsumo iyahon o tsukeppanashi desu.","zh":""},{"ja":"子供はおもちゃを床に置きっぱなしで、片付けなかった。","en":"The child left the toys on the floor and didn’t put them away.","romaji":"Kodomo wa omocha o yuka ni okippanashi de, katazukenakatta.","zh":""},{"ja":"昨夜は忙しかったので、テレビをつけっぱなしにして寝てしまった。","en":"I was busy last night, so I left the TV on and fell asleep.","romaji":"Sakuya wa isogashikatta node, terebi o tsukeppanashi ni shite nete shimatta.","zh":""}]',replace('**Short**: Express a continuous action or state; ''left as is'', ''non-stop''.\n\n**Formation**: Verb-ます stem + っぱなし\n\n**Long**: The ～っぱなし grammar point is used to express that something is left in a certain condition for an extended time or that an action continues without stopping. It attaches to the ます-stem of verbs.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ppoi','～っぽい',NULL,NULL,'N2','[]','[{"ja":"彼女は大人っぽい服を着ている。","en":"She’s wearing clothes that look mature.","romaji":"Kanojo wa otonappoi fuku o kite iru.","zh":""},{"ja":"この説明は分かりにくっぽい。","en":"This explanation seems hard to understand.","romaji":"Kono setsumei wa wakari nikuppoi.","zh":""},{"ja":"彼は疲れたっぽい顔をしている。","en":"He has a face that looks tired.","romaji":"Kare wa tsukareta ppoi kao o shite iru.","zh":""},{"ja":"この部屋は寒っぽい感じがする。","en":"This room feels kind of chilly.","romaji":"Kono heya wa samuppoi kanji ga suru.","zh":""}]',replace('**Short**: Indicates that something has the appearance, characteristics, or behavior of something else.\n\n**Formation**: Noun + っぽい, Verb-casual + っぽい, い-Adjective + っぽい, な-Adjective + っぽい\n\n**Long**: The ～っぽい grammar point is used when something or someone appears to have characteristics, traits, or a vibe that resemble something else. It can mean ''looks like,'' ''seems like,'' or ''has the quality of.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_irarenai','～ていられない',NULL,NULL,'N2','[]','[{"ja":"こんなに忙しいのに、無理に遊んでいられない。","en":"I''m so busy that I can''t afford to just play around.","romaji":"Konna ni isogashii noni, muri ni asonde irarenai.","zh":""},{"ja":"寒すぎて、外で待っていられない。","en":"It''s too cold; I can''t keep waiting outside.","romaji":"Samusugite, soto de matte irarenai.","zh":""},{"ja":"この問題は重要だから、放っておいていられない。","en":"This issue is too important to ignore.","romaji":"Kono mondai wa jūyō dakara, houtte oite irarenai.","zh":""},{"ja":"彼女の態度が我慢できず、黙っていられない。","en":"I can''t stand her attitude, so I can''t stay silent.","romaji":"Kanojo no taido ga gaman dekizu, damatte irarenai.","zh":""}]',replace('**Short**: Expresses that one cannot afford to do something; ''can''t keep on'', ''unable to continue''.\n\n**Formation**: Verb-て form + いられない\n\n**Long**: The ～ていられない grammar point is used to express a feeling of not being able to continue doing something or remaining in a certain state. It can be translated as ''can''t keep on'', ''unable to continue'', or ''can''t afford to'' in English. The formation is the same for all verb types.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_kanawanai','～てかなわない',NULL,NULL,'N2','[]','[{"ja":"こんなに暑くてかなわない。","en":"I can’t stand this heat.","romaji":"Konnani atsukute kanawanai.","zh":""},{"ja":"彼の話は失礼すぎてかなわない。","en":"His remarks are so rude I can’t put up with them.","romaji":"Kare no hanashi wa shitsurei sugite kanawanai.","zh":""},{"ja":"映画があまりに感動的で、忘れられなくてかなわない。","en":"The movie was so moving that I can’t stand how it stays on my mind.","romaji":"Eiga ga amari ni kandō-teki de, wasurerarenakute kanawanai.","zh":""},{"ja":"彼女の笑顔がまぶしくてかなわない。","en":"Her smile is so dazzling that it’s overwhelming.","romaji":"Kanojo no egao ga mabushikute kanawanai.","zh":""}]',replace('**Short**: Expresses that something cannot be endured, tolerated, or is unbearable.\n\n**Formation**: Adjective (〜く / 〜で) + て + かなわない / Verb phrase (reworded to an adjective/negative) + て + かなわない\n\n**Long**: The ～てかなわない grammar point is typically used with adjectives (or a rephrased verb) in 〜て form to show an unbearable situation or feeling. It means you ''can’t stand'' or ''can’t endure'' something. It often appears with expressions like 「暑くてかなわない」「うるさくてかなわない」 and so on.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_kara_denai_to','～てからでないと',NULL,NULL,'N2','[]','[{"ja":"宿題をしてからでないと、遊びに行けません。","en":"You cannot go play until you’ve finished your homework.","romaji":"Shukudai o shite kara denai to, asobi ni ikemasen.","zh":""},{"ja":"食事をしてからでないと、デザートを食べられません。","en":"You cannot eat dessert until after having a meal.","romaji":"Shokuji o shite kara denai to, dezāto o taberaremasen.","zh":""},{"ja":"チケットを買ってからでないと、映画を見られません。","en":"You can’t watch the movie until after you buy a ticket.","romaji":"Chiketto o katte kara denai to, eiga o miraremasen.","zh":""},{"ja":"試験が終わってからでないと、休みを取れません。","en":"You can’t take time off until the exam is over.","romaji":"Shiken ga owatte kara denai to, yasumi o toremasen.","zh":""}]',replace('**Short**: Indicates that something cannot be done before a certain action is completed; ''not until'', ''only after''.\n\n**Formation**: Verb-て + からでないと\n\n**Long**: The ～てからでないと grammar point is used to express that an action cannot be done before another action has been completed. It can be translated as ''not until'' or ''only after'' in English. It attaches to a verb in the て-form, plus からでないと.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_koso','～てこそ',NULL,NULL,'N2','[]','[{"ja":"勉強してこそ、テストに合格できる。","en":"Only when you study can you pass the test.","romaji":"Benkyō shite koso, tesuto ni gōkaku dekiru.","zh":""},{"ja":"素直になってこそ、相手の気持ちが分かります。","en":"Only when you’re honest can you understand the other person’s feelings.","romaji":"Sunao ni natte koso, aite no kimochi ga wakarimasu.","zh":""},{"ja":"静かでこそ、心が落ち着く。","en":"Only in silence can one’s mind be at peace.","romaji":"Shizuka de koso, kokoro ga ochitsuku.","zh":""},{"ja":"友達でこそ、お互いに助け合うのは当然だ。","en":"Precisely because we’re friends, it’s natural to help each other.","romaji":"Tomodachi de koso, otagai ni tasukeau no wa tōzen da.","zh":""}]',replace('**Short**: Emphasizes the condition; ''only when'', ''precisely because''.\n\n**Formation**: Verb-て form + こそ / い-Adjective + くてこそ / な-Adjective + でこそ / Noun + でこそ\n\n**Long**: The ～てこそ grammar point is used to emphasize that ''only when'' or ''precisely because'' the stated condition is met, a certain result or meaning arises. For nouns and adjectives, similar forms appear (e.g., Noun + でこそ, い-Adjective くてこそ, な-Adjective でこそ).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_deshou_ga_nai','～でしょうがない',NULL,NULL,'N2','[]','[{"ja":"今日は暇で(は)しょうがない。","en":"I’m extremely bored today.","romaji":"Kyō wa hima de shō ga nai.","zh":""},{"ja":"試験が近いから不安でしょうがない。","en":"I’m so anxious because the exam is coming up.","romaji":"Shiken ga chikai kara fuan deshō ga nai.","zh":""},{"ja":"頭が痛くてしょうがないから、早退したい。","en":"My head hurts so much I can’t stand it—I want to leave early.","romaji":"Atama ga itakute shō ga nai kara, sōtai shitai.","zh":""},{"ja":"新しいゲームが気になってしょうがない。","en":"I can’t help but keep thinking about the new game.","romaji":"Atarashii gēmu ga ki ni natte shō ga nai.","zh":""}]',replace('**Short**: Expresses an intense emotional or physical state; ''extremely'', ''can’t help but''.\n\n**Formation**: い-Adjective(く) + てしょうがない / な-Adjective + で(は)しょうがない / Verb-て form + しょうがない\n\n**Long**: The pattern ～(て)しょうがない (or 〜でしょうがない) indicates a condition or feeling so intense that one is almost ''overcome'' by it. It’s often used with emotions (e.g. 退屈で(しょうがない), 嬉しくてしょうがない, 寒くてしょうがない).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_de_tamaranai','～でたまらない',NULL,NULL,'N2','[]','[{"ja":"この暑さは本当に暑くてたまらない。","en":"This heat is absolutely unbearable.","romaji":"Kono atsusa wa hontō ni atsukute tamaranai.","zh":""},{"ja":"彼女のことが好きでたまらない。","en":"I like her so much I can hardly stand it.","romaji":"Kanojo no koto ga suki de tamaranai.","zh":""},{"ja":"この部屋は寒くてたまらない。","en":"This room is unbearably cold.","romaji":"Kono heya wa samukute tamaranai.","zh":""},{"ja":"彼の態度を見ていると、腹が立ってたまらない。","en":"Seeing his attitude makes me extremely angry.","romaji":"Kare no taido o mite iru to, hara ga tatte tamaranai.","zh":""}]',replace('**Short**: Express extremely strong feelings or sensations; ''can''t stand'', ''unbearably''.\n\n**Formation**: い-Adjective (く) + てたまらない / な-Adjective + でたまらない / Verb-て form + たまらない\n\n**Long**: The ～でたまらない grammar point is used to convey very strong emotion or sensation—so strong it’s almost unbearable. It’s common with expressions like 暑くてたまらない, うれしくてたまらない, etc.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_de_naranai','～でならない',NULL,NULL,'N2','[]','[{"ja":"彼の演技が素晴らしくてならない。","en":"I can’t help but be amazed at his wonderful performance.","romaji":"Kare no engi ga subarashikute naranai.","zh":""},{"ja":"合格発表が気になってならない。","en":"I can’t stop worrying about the exam results.","romaji":"Gōkaku happyō ga ki ni natte naranai.","zh":""},{"ja":"友達が引っ越してしまって、寂しくてならない。","en":"My friend moved away, and I feel unbearably lonely.","romaji":"Tomodachi ga hikkoshite shimatte, sabishikute naranai.","zh":""},{"ja":"初めての海外旅行で、不安でならない。","en":"It’s my first trip abroad, and I’m extremely anxious.","romaji":"Hajimete no kaigai ryokō de, fuan de naranai.","zh":""}]',replace('**Short**: Indicates an uncontrollable emotion or feeling; ''can’t help but'', ''overwhelmingly''.\n\n**Formation**: な-Adjective + でならない / い-Adjective (く) + てならない / Verb-て + ならない\n\n**Long**: The ～でならない grammar pattern expresses a very strong, often involuntary feeling—e.g., ''不思議でならない'' (it’s so mysterious I can’t help thinking about it), ''残念でならない'' (I’m so disappointed), ''心配でならない'' (I’m extremely worried).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_de_bakari_wa_irarenai','～でばかりはいられない',NULL,NULL,'N2','[]','[{"ja":"いつも助けてもらってばかりはいられない。","en":"I can’t just keep letting people help me all the time.","romaji":"Itsumo tasukete moratte bakari wa irarenai.","zh":""},{"ja":"好きな仕事ばかりしてはいられない。","en":"I can’t afford to only do the work I love.","romaji":"Suki na shigoto bakari shite wa irarenai.","zh":""},{"ja":"親に頼ってばかりはいられない。","en":"I can’t keep depending on my parents forever.","romaji":"Oya ni tayotte bakari wa irarenai.","zh":""},{"ja":"休んでばかりはいられない。仕事もしなくちゃ。","en":"I can’t just keep taking breaks; I have work to do as well.","romaji":"Yasunde bakari wa irarenai. Shigoto mo shinakucha.","zh":""}]',replace('**Short**: Cannot afford to only do something; cannot always rely on it.\n\n**Formation**: Verb-て form + ばかりはいられない / Noun + ばかりはいられない (with appropriate particles)\n\n**Long**: The ～でばかりはいられない grammar point is used when one realizes they cannot keep doing only that one thing or cannot always rely on a certain situation. It implies the need to take other actions or responsibilities.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_de_wa_nai_ka','～ではないか',NULL,NULL,'N2','[]','[{"ja":"彼は優秀な学生ではないか。","en":"Isn’t he an excellent student?","romaji":"Kare wa yūshū na gakusei de wa nai ka.","zh":""},{"ja":"この料理は美味しいではないか。","en":"Isn’t this dish delicious?","romaji":"Kono ryōri wa oishii de wa nai ka.","zh":""},{"ja":"あなたは彼女の友達ではないか。","en":"Aren’t you her friend?","romaji":"Anata wa kanojo no tomodachi de wa nai ka.","zh":""},{"ja":"明日は休みではないか。","en":"Tomorrow’s a day off, right?","romaji":"Ashita wa yasumi de wa nai ka.","zh":""}]',replace('**Short**: Used to show a strong assertion or emphasis on one’s opinion; ''isn''t it?'', ''aren''t you?'', ''right?''.\n\n**Formation**: Noun + ではないか / い-Adjective + ではないか / な-Adjective + ではないか / Verb-casual + ではないか\n\n**Long**: The ～ではないか grammar point is used at the end of a sentence to make a rhetorical question or a strong, emphatic statement. It often translates as ''isn''t it…?'' ''aren''t you…?'' or ''wouldn’t you say…?''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_wa_naranai','～てはならない',NULL,NULL,'N2','[]','[{"ja":"ここでタバコを吸ってはならない。","en":"You must not smoke here.","romaji":"Koko de tabako o sutte wa naranai.","zh":""},{"ja":"秘密を他人に話してはならない。","en":"You cannot reveal this secret to others.","romaji":"Himitsu o tanin ni hanashite wa naranai.","zh":""},{"ja":"この部屋に入ってはならない。","en":"You must not enter this room.","romaji":"Kono heya ni haitte wa naranai.","zh":""},{"ja":"飲酒運転をしてはならない。","en":"You must not drink and drive.","romaji":"Inshu unten o shite wa naranai.","zh":""}]',replace('**Short**: Express prohibition; ''must not'', ''cannot'', ''should not''.\n\n**Formation**: Verb-て form + はならない\n\n**Long**: The ～てはならない grammar point is used to express a strong prohibition. It is often more formal or strict and can be translated as ''must not'', ''cannot'', or ''should not.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_made','～てまで',NULL,NULL,'N2','[]','[{"ja":"彼は試験に合格するために、徹夜してまで勉強しました。","en":"He studied to the point of staying up all night in order to pass the exam.","romaji":"Kare wa shiken ni gōkaku suru tame ni, tetsuya shite made benkyō shimashita.","zh":""},{"ja":"この商品がほしかったので、朝早く起きてまで並んで買いました。","en":"I wanted this product so much that I went so far as to get up early and wait in line to buy it.","romaji":"Kono shōhin ga hoshikatta node, asa hayaku okite made narande kaimashita.","zh":""},{"ja":"彼女は彼を助けるために、お金を借りてまで手術代を払いました。","en":"In order to help him, she even borrowed money to pay for the surgery.","romaji":"Kanojo wa kare o tasukeru tame ni, okane o karite made shujutsudai o haraimashita.","zh":""},{"ja":"部長はそのプロジェクトを成功させるために、休日も働いてまで取り組んでいます。","en":"The manager is even working on holidays to make the project a success.","romaji":"Buchō wa sono purojekuto o seikō saseru tame ni, kyūjitsu mo hataraite made torikunde imasu.","zh":""}]',replace('**Short**: Express the extent someone goes in order to achieve something; ''to the point of'', ''even'', ''so far as to''.\n\n**Formation**: Verb-て form + まで\n\n**Long**: The ～てまで grammar point is used to convey the extent someone goes to achieve something, highlighting the action one takes or the sacrifice one makes for a certain purpose. It can be translated as ''to the point of'', ''even'', or ''so far as to'' in English. It is used with verbs, not adjectives or nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_t_zen_da','～て当然だ',NULL,NULL,'N2','[]','[{"ja":"彼は毎日勉強しているから、試験に合格して当然だ。","en":"Since he studies every day, it''s only natural that he passes the exam.","romaji":"Kare wa mainichi benkyō shite iru kara, shiken ni gōkaku shite tōzen da.","zh":""},{"ja":"そのレストランは料理が美味しいので、予約がいっぱいになって当然だ。","en":"Because that restaurant’s food is delicious, no wonder its reservations are always full.","romaji":"Sono resutoran wa ryōri ga oishii node, yoyaku ga ippai ni natte tōzen da.","zh":""},{"ja":"彼女は毎晩練習しているので、上手になって当然だ。","en":"She practices every night, so it''s natural that she becomes skilled.","romaji":"Kanojo wa maiban renshū shite iru node, jōzu ni natte tōzen da.","zh":""},{"ja":"彼は仕事で成功していて、お金持ちになって当然だ。","en":"He has succeeded at his job, so it''s only natural that he''s become wealthy.","romaji":"Kare wa shigoto de seikō shite ite, okanemochi ni natte tōzen da.","zh":""}]',replace('**Short**: Expresses that something is natural or expected.\n\n**Formation**: Verb-て form + 当然だ\n\n**Long**: The ～て当然だ grammar point is used to express that something is natural, obvious, or expected under the circumstances. It can be translated as ''it''s natural that'', ''as expected'', or ''no wonder'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_iu_mono_da','～というものだ',NULL,NULL,'N2','[]','[{"ja":"若者の熱情は尊敬に値するというものだ。","en":"The passion of young people is something that deserves respect.","romaji":"Wakamono no netsujō wa sonkei ni ataisuru to iu mono da.","zh":""},{"ja":"勉強は一日でもサボれば遅れるというものだ。","en":"If you skip even a day of studying, you''ll fall behind—that''s just how it is.","romaji":"Benkyō wa ichinichi demo saboreba okureru to iu mono da.","zh":""},{"ja":"成功するためには困難に立ち向かうというものだ。","en":"To succeed, one must face difficulties—that''s just the way it is.","romaji":"Seikō suru tame ni wa konnan ni tachimukau to iu mono da.","zh":""},{"ja":"友情はお金で買えないというものだ。","en":"It is said that friendship cannot be bought with money.","romaji":"Yūjō wa okane de kaenai to iu mono da.","zh":""}]',replace('**Short**: Expressing a general rule or common sense.\n\n**Formation**: Sentence + というものだ\n\n**Long**: The ～というものだ grammar point is used to emphasize a general rule, a piece of common sense, or an indisputable fact. It often appears in comments or observations about something commonly accepted as true.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_d_ni_ka_nai_mono_ka','どうにか～ないものか',NULL,NULL,'N2','[]','[{"ja":"どうにかこの仕事を終わらせないものか。","en":"Isn''t there some way to finish this job?","romaji":"Dō ni ka kono shigoto o owarasenai mono ka.","zh":""},{"ja":"どうにか次の試験で合格しないものか。","en":"Can''t we somehow pass the next exam?","romaji":"Dō ni ka tsugi no shiken de gōkaku shinai mono ka.","zh":""},{"ja":"どうにか込んでいる電車に乗れないものか。","en":"Is there no way to get on the crowded train somehow?","romaji":"Dō ni ka konde iru densha ni norenai mono ka.","zh":""},{"ja":"どうにか彼女と仲直りしないものか。","en":"Isn''t there some way to make up with her?","romaji":"Dō ni ka kanojo to nakanaori shinai mono ka.","zh":""}]',replace('**Short**: Express a strong desire or wish for something to be possible.\n\n**Formation**: どうにか + Verb-negative form + ないものか\n\n**Long**: どうにか～ないものか is used to express a strong desire or wish for something to be resolved or made possible. It translates roughly as ''isn''t there some way...?'', ''can''t we somehow...?'', or ''is there no way...?''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_toori_n2','～とおり',NULL,NULL,'N2','[]','[{"ja":"先生が言ったとおりに宿題をしました。","en":"I did my homework exactly as the teacher said.","romaji":"Sensei ga itta tōri ni shukudai o shimashita.","zh":""},{"ja":"この地図のとおりに歩いてください。","en":"Please walk according to this map.","romaji":"Kono chizu no tōri ni aruite kudasai.","zh":""},{"ja":"彼はいつもルールどおりに遊びます。","en":"He always plays by the rules.","romaji":"Kare wa itsumo rūru-dōri ni asobimasu.","zh":""},{"ja":"その道路は昼間と同じくらい夜も賑やかだというとおりでした。","en":"As I heard, that street was just as lively at night as it is in the daytime.","romaji":"Sono dōro wa hiruma to onaji kurai yoru mo nigiyaka da to iu tōri deshita.","zh":""}]',replace('**Short**: Express doing something as instructed or describing how something matches a rule or guideline; ''as'', ''according to''.\n\n**Formation**: Verb-casual + とおり, い-Adjective + とおり, な-Adjective + だとおり, Noun + だとおり\n\n**Long**: The ～とおり grammar point is used to express doing something exactly as instructed or describing how something matches a guideline or is exactly as one heard/expected. It can be translated as ''as'', ''according to'', or ''the same way...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_ka','～とか',NULL,NULL,'N2','[]','[{"ja":"休日は映画を見るとか、買い物に行くとかして過ごします。","en":"On my days off, I do things like watch movies or go shopping.","romaji":"Kyūjitsu wa eiga o miru to ka, kaimono ni iku to ka shite sugoshimasu.","zh":""},{"ja":"彼女はオーストラリアとかニュージーランドとかに行きたがっています。","en":"She wants to go to places like Australia or New Zealand.","romaji":"Kanojo wa Ōsutoraria to ka Nyūjīrando to ka ni ikitagatte imasu.","zh":""},{"ja":"今日の天気は晴れたり、曇ったりとかだそうです。","en":"I heard today’s weather is something like sunny at times, cloudy at times.","romaji":"Kyō no tenki wa hare tari, kumottari to ka da sō desu.","zh":""},{"ja":"彼は野球をしたり、サッカーをしたりとかしています。","en":"He spends his time playing baseball and soccer and such.","romaji":"Kare wa yakyū o shitari, sakkā o shitari to ka shite imasu.","zh":""}]',replace('**Short**: Used to list examples or express uncertainty; ''such as'', ''like'', ''or something like that''.\n\n**Formation**: Verb-casual + とか, い-Adjective + とか, な-Adjective + だとか, Noun + だとか\n\n**Long**: The ～とか grammar point can be used to list examples or express a somewhat vague mention of items/activities. It can be translated as ''such as'', ''like'', or ''or something like that''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tokoro','～ところ',NULL,NULL,'N2','[]','[{"ja":"出かけるところです。","en":"I''m just about to go out.","romaji":"Dekakeru tokoro desu.","zh":""},{"ja":"映画を見ているところです。","en":"I''m in the middle of watching a movie.","romaji":"Eiga o mite iru tokoro desu.","zh":""},{"ja":"おいしいところで食事をするつもりです。","en":"I plan to have a meal at a good (tasty) place.","romaji":"Oishii tokoro de shokuji o suru tsumori desu.","zh":""},{"ja":"彼は忙しいところを手伝ってくれました。","en":"He helped me when he himself was busy.","romaji":"Kare wa isogashii tokoro o tetsudatte kuremashita.","zh":""}]',replace('**Short**: Express a specific point in time or state; ''when'', ''just about'', or ''in the middle of''.\n\n**Formation**: Verb-casual + ところ, い-Adjective + ところ, な-Adjective + なところ, Noun + のところ\n\n**Long**: The ～ところ grammar point is used to describe a specific point in time or stage of action. Depending on the verb tense, it can mean ''just about to do something'', ''in the middle of doing something'', or ''just did something''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dokoro_ka','～どころか',NULL,NULL,'N2','[]','[{"ja":"彼は歌が上手どころか、プロの歌手みたいだ。","en":"Far from just being good at singing, he sounds like a professional singer.","romaji":"Kare wa uta ga jōzu dokoro ka, puro no kashu mitai da.","zh":""},{"ja":"この料理はおいしいどころか、最高の味だ。","en":"This dish is not just delicious, it’s absolutely the best.","romaji":"Kono ryōri wa oishii dokoro ka, saikō no aji da.","zh":""},{"ja":"彼女はただの友達どころか、私の親友だ。","en":"She’s far from just a friend; she’s my best friend.","romaji":"Kanojo wa tada no tomodachi dokoro ka, watashi no shin’yū da.","zh":""},{"ja":"彼は英語ができるどころか、他の3つの言語も話せる。","en":"Not only can he speak English, he also speaks three other languages.","romaji":"Kare wa eigo ga dekiru dokoro ka, hoka no mittsu no gengo mo hanaseru.","zh":""}]',replace('**Short**: Express ''far from'', ''not just'', ''not only'', or ''to say nothing of''.\n\n**Formation**: Verb-casual + どころか, い-Adjective + どころか, な-Adjective + どころか, Noun + どころか\n\n**Long**: The ～どころか grammar point is used to emphasize that reality is far from what one might expect or that something is not only one way, but actually goes beyond it. It can be translated as ''far from'', ''not just'', or ''to say nothing of''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dokoro_de_wa_nai','～どころではない',NULL,NULL,'N2','[]','[{"ja":"彼の失敗を笑うどころではない。私たちも同じミスをしている。","en":"This is not the time to laugh at his mistakes—we’re making the same ones.","romaji":"Kare no shippai o warau dokoro de wa nai. Watashitachi mo onaji misu o shite iru.","zh":""},{"ja":"病気で寝ている時は、遊ぶどころではない。","en":"When you’re sick in bed, it''s far from the time to play around.","romaji":"Byōki de nete iru toki wa, asobu dokoro de wa nai.","zh":""},{"ja":"試験が近いので、映画を見るどころではない。","en":"Since the exam is coming up, I can’t possibly watch a movie.","romaji":"Shiken ga chikai node, eiga o miru dokoro de wa nai.","zh":""},{"ja":"仕事が忙しすぎて、旅行なんて考えるどころではない。","en":"I''m way too busy with work to even think about going on a trip.","romaji":"Shigoto ga isogashisugite, ryokō nante kangaeru dokoro de wa nai.","zh":""}]',replace('**Short**: Not the time/place for; far from; can''t possibly.\n\n**Formation**: Verb-casual + どころではない, い-Adjective + どころではない, な-Adjective + どころではない, Noun + どころではない\n\n**Long**: The ～どころではない grammar point is used to express that circumstances make it impossible or inappropriate to do something—there’s a much bigger issue at hand. It can also mean ‘far from’ in a figurative sense.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_shitara_n2','～としたら',NULL,NULL,'N2','[]','[{"ja":"明日雨が降るとしたら、傘を持っていきましょう。","en":"If it rains tomorrow, let’s bring umbrellas.","romaji":"Ashita ame ga furu to shitara, kasa o motte ikimashō.","zh":""},{"ja":"このケーキが美味しくないとしたら、誰も食べないだろう。","en":"If this cake isn’t tasty, probably no one will eat it.","romaji":"Kono kēki ga oishikunai to shitara, dare mo tabenai darō.","zh":""},{"ja":"彼が病気だとしたら、早めに病院へ行かないといけません。","en":"If he is sick, he needs to go to the hospital soon.","romaji":"Kare ga byōki da to shitara, hayame ni byōin e ikanai to ikemasen.","zh":""},{"ja":"彼女が学生だとしたら、このレストランは割引があるでしょう。","en":"If she’s a student, there’s probably a discount at this restaurant.","romaji":"Kanojo ga gakusei da to shitara, kono resutoran wa waribiki ga aru deshō.","zh":""}]',replace('**Short**: Express a hypothetical situation; ''if'', ''suppose'', ''assuming''.\n\n**Formation**: Verb-casual + としたら, い-Adjective + としたら, な-Adjective + だとしたら, Noun + だとしたら\n\n**Long**: The ～としたら grammar point is used to express a hypothetical situation or assumption. It can be translated as ''if'', ''suppose'', or ''assuming'' in English. The formation differs depending on whether it’s used with verbs, adjectives, or nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_shite_mo','～としても',NULL,NULL,'N2','[]','[{"ja":"雨が降るとしても、レースは中止しません。","en":"Even if it rains, we won''t cancel the race.","romaji":"Ame ga furu to shite mo, rēsu wa chūshi shimasen.","zh":""},{"ja":"このケーキが美味しくないとしても、私は食べるつもりです。","en":"Even if this cake isn''t delicious, I plan on eating it.","romaji":"Kono kēki ga oishikunai to shite mo, watashi wa taberu tsumori desu.","zh":""},{"ja":"彼女が遅刻するとしても、私たちは待ち続けます。","en":"Even if she is late, we will keep waiting.","romaji":"Kanojo ga chikoku suru to shite mo, watashitachi wa machitsuzukemasu.","zh":""},{"ja":"忙しいだとしても、友達との約束は守りたい。","en":"Even if I''m busy, I want to keep my promise to my friend.","romaji":"Isogashii da to shite mo, tomodachi to no yakusoku wa mamoritai.","zh":""}]',replace('**Short**: Even if, despite, although\n\n**Formation**: Verb-casual + としても, い-Adjective + としても, な-Adjective + だとしても, Noun + だとしても\n\n**Long**: The ～としても grammar point is used to say ‘even if...’ or ‘even assuming that...’, often followed by a conclusion or stance. It’s similar to ～ても, but puts more emphasis on the hypothetical assumption or viewpoint.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_tomoni','～と～ともに',NULL,NULL,'N2','[]','[{"ja":"彼が来るとともに、パーティーが始まりました。","en":"The party started as soon as he arrived.","romaji":"Kare ga kuru to tomoni, paatii ga hajimarimashita.","zh":""},{"ja":"季節が変わるとともに、服のファッションも変わります。","en":"As the seasons change, clothing fashion also changes.","romaji":"Kisetsu ga kawaru to tomoni, fuku no fasshon mo kawarimasu.","zh":""},{"ja":"成長とともに、いろいろな経験を積むことが大切です。","en":"As you grow, it is important to gain various experiences.","romaji":"Seichou to tomoni, iroirona keiken wo tsumu koto ga taisetsu desu.","zh":""},{"ja":"技術の進歩とともに、便利なアプリが増えています。","en":"With the advancement of technology, the number of convenient apps is increasing.","romaji":"Gijutsu no shinpo to tomoni, benrina apuri ga fueteimasu.","zh":""}]',replace('**Short**: Expresses ''together with'' or ''along with''; used to describe two events or actions happening simultaneously or in parallel.\n\n**Formation**: Verb-casual + とともに, い-Adjective + とともに, な-Adjective + とともに, Noun + とともに\n\n**Long**: The ～と～ともに grammar point is used to express that two events or actions are happening simultaneously or in parallel. It is translated as ''together with'' or ''along with'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_wa_kagiranai','～とは限らない',NULL,NULL,'N2','[]','[{"ja":"いつも勉強しているとは限らない。","en":"It''s not always true that I''m studying.","romaji":"Itsumo benkyou shite iru to wa kagiranai.","zh":""},{"ja":"高い商品がいいとは限らない。","en":"Expensive products are not necessarily good.","romaji":"Takai shouhin ga ii to wa kagiranai.","zh":""},{"ja":"彼が正しいとは限らない。","en":"It''s not necessarily true that he is right.","romaji":"Kare ga tadashii to wa kagiranai.","zh":""},{"ja":"雨が降るとは限らない。","en":"It''s not necessarily going to rain.","romaji":"Ame ga furu to wa kagiranai.","zh":""}]',replace('**Short**: Expresses that something is not necessarily true; ''not always'', ''not necessarily''.\n\n**Formation**: Verb-casual + とは限らない, い-Adjective + とは限らない, な-Adjective + だとは限らない, Noun + だとは限らない\n\n**Long**: The ～とは限らない grammar point is used to express that something is not necessarily true or does not always occur. It can be translated as ''not always'' or ''not necessarily'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nai_koto_wa_nai_n2','～ないことはない',NULL,NULL,'N2','[]','[{"ja":"彼が来ないことはない。","en":"It''s not that he won''t come (it''s possible that he will come).","romaji":"Kare ga konai koto wa nai.","zh":""},{"ja":"あの問題が解けないことはない。","en":"It''s not impossible to solve that problem (it can be solved).","romaji":"Ano mondai ga tokenai koto wa nai.","zh":""},{"ja":"その仕事が難しくないことはない。","en":"That job is not without difficulty (it has some difficulties).","romaji":"Sono shigoto ga muzukashikunai koto wa nai.","zh":""},{"ja":"彼女が正しくないことはない。","en":"It''s not impossible that she is right (she could be right).","romaji":"Kanojo ga tadashikunai koto wa nai.","zh":""}]',replace('**Short**: Express that something is not impossible, meaning it is possible or could be done.\n\n**Formation**: Verb-ないform + ことはない\n\n**Long**: The ～ないことはない grammar point is used to express a double negative, meaning that something is not impossible, implying that it is possible or could be done. Essentially, it downplays the possibility or ability to do something but still acknowledges that it''s possible.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nai_koto_mo_nai','～ないこともない',NULL,NULL,'N2','[]','[{"ja":"この問題は解けないこともないけど、難しいです。","en":"It''s not that I can''t solve this problem, but it''s difficult.","romaji":"Kono mondai wa tokenai koto mo nai kedo, muzukashii desu.","zh":""},{"ja":"彼に会わないこともないが、あまり話す時間がない。","en":"It''s not that I can''t meet him, but there''s not much time to talk.","romaji":"Kare ni awanai koto mo nai ga, amari hanasu jikan ga nai.","zh":""},{"ja":"お金がないこともないけれど、節約した方がいい。","en":"It''s not that I don''t have money, but it''s better to save.","romaji":"O-kane ga nai koto mo nai keredo, setsuyaku shita hou ga ii.","zh":""},{"ja":"このゲームが面白くないこともないが、他のゲームの方が楽しい。","en":"It''s not that this game isn''t interesting, but other games are more fun.","romaji":"Kono geemu ga omoshirokunai koto mo nai ga, hoka no geemu no hou ga tanoshii.","zh":""}]',replace('**Short**: Used to express an action or state is ''not impossible'', but emphasizes reluctance or doubt.\n\n**Formation**: Verb-ないForm + こともない, い-adjective + こともない\n\n**Long**: The ～ないこともない grammar point is used to express that something is not impossible, but the speaker is reluctant, has doubts, or deems it as a less favorable option. It can be translated as ''not that one can''t'', ''not that it''s impossible'', or ''it''s not out of the question''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nai_de_wa_irarenai','～ないではいられない',NULL,NULL,'N2','[]','[{"ja":"この映画はとても感動的で、泣かないではいられなかった。","en":"This movie was so touching, I couldn''t help but cry.","romaji":"Kono eiga wa totemo kandouteki de, nakanai de wa irarenakatta.","zh":""},{"ja":"彼女の笑顔を見ると、笑わないではいられない。","en":"When I see her smile, I can''t help but laugh.","romaji":"Kanojo no egao wo miru to, warawanai de wa irarenai.","zh":""},{"ja":"この部屋はとても寒いので、震えないではいられない。","en":"This room is so cold, I can''t help but shiver.","romaji":"Kono heya wa totemo samui node, furuenai de wa irarenai.","zh":""},{"ja":"彼の話はつまらないが、聞かないではいられない。","en":"His story is boring, but I can''t help but listen.","romaji":"Kare no hanashi wa tsumaranai ga, kikanai de wa irarenai.","zh":""}]',replace('**Short**: Cannot help but; cannot avoid; unable to refrain from.\n\n**Formation**: Verb-ない form + ではいられない or じゃいられない\n\n**Long**: The ～ないではいられない grammar point is used to express a strong feeling, urge, or uncontrollable action that someone cannot resist or help doing, even if it may be undesirable. It can be translated as ''cannot help but'', ''cannot avoid'', or ''unable to refrain from'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nagara_n2','～ながら',NULL,NULL,'N2','[]','[{"ja":"テレビを見ながら宿題をしています。","en":"I am doing my homework while watching TV.","romaji":"Terebi wo minagara shukudai wo shiteimasu.","zh":""},{"ja":"彼女は歌いながら料理を作っていました。","en":"She was cooking while singing.","romaji":"Kanojo wa utainagara ryouri wo tsukutte imashita.","zh":""},{"ja":"電車の中で立ちながら本を読んでいる人が多いです。","en":"There are many people who read books while standing on the train.","romaji":"Densha no naka de tachinagara hon wo yonde iru hito ga ooi desu.","zh":""},{"ja":"僕は歩きながらスマホを使っています。","en":"I am using my smartphone while walking.","romaji":"Boku wa arukinagara sumaho wo tsukatteimasu.","zh":""}]',replace('**Short**: Express doing two things simultaneously or at the same time.\n\n**Formation**: Verb-stem + ながら\n\n**Long**: The ～ながら grammar point is used to express the concept of doing two things simultaneously or at the same time. In English, it can be translated as ''while'', ''as'', or ''during''. ～ながら can be attached to the stem of a verb to convey this meaning.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_atari','～にあたり',NULL,NULL,'N2','[]','[{"ja":"入学にあたり、必要な書類を準備してください。","en":"Please prepare the necessary documents upon entering the school.","romaji":"Nyuugaku ni atari, hitsuyou na shorui wo junbi shite kudasai.","zh":""},{"ja":"新年にあたり、抱負を立てる人が多いです。","en":"Many people set goals at the time of the new year.","romaji":"Shinnen ni atari, houfu wo tateru hito ga ooi desu.","zh":""},{"ja":"結婚にあたり、両家は大切な儀式を行います。","en":"Upon getting married, both families conduct an important ceremony.","romaji":"Kekkon ni atari, ryouke wa taisetsu na gishiki wo okonaimasu.","zh":""},{"ja":"新しい仕事を始めるにあたり、準備が必要です。","en":"In starting a new job, preparation is necessary.","romaji":"Atarashii shigoto wo hajimeru ni atari, junbi ga hitsuyou desu.","zh":""}]',replace('**Short**: Expresses the meaning of ''at the time of'', ''in'', ''on'', or ''upon''.\n\n**Formation**: Noun + にあたり\n\n**Long**: The ～にあたり grammar point is used to describe an important event or situation that occurs at a specific moment. It can be translated as ''at the time of'', ''in'', ''on'', or ''upon'' in English. The formation is quite simple, as it only requires a noun before it.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_oite_n2','～において',NULL,NULL,'N2','[]','[{"ja":"この大学において、英語のクラスが一番人気があります。","en":"In this university, English classes are the most popular.","romaji":"Kono daigaku ni oite, eigo no kurasu ga ichiban ninki ga arimasu.","zh":""},{"ja":"彼の研究において新しい発見がありました。","en":"In his research, there were new discoveries.","romaji":"Kare no kenkyuu ni oite atarashii hakken ga arimashita.","zh":""},{"ja":"運動会において、彼は大活躍しました。","en":"At the sports festival, he performed exceptionally well.","romaji":"Undoukai ni oite, kare wa daikatsuyaku shimashita.","zh":""},{"ja":"環境問題においては、みんなが責任を持って行動すべきです。","en":"Regarding environmental issues, everyone should take responsibility and act accordingly.","romaji":"Kankyou mondai ni oite wa, minna ga sekinin wo motte koudou subeki desu.","zh":""}]',replace('**Short**: Indicates the place, time, or context where an action or event occurs; ''in'', ''at'', ''on'', ''regarding''.\n\n**Formation**: Noun + において\n\n**Long**: The ～において grammar point is used to show the place, time, or context where an action or event takes place. It can be translated as ''in'', ''at'', ''on'', or ''regarding'' in English. It is often used in formal situations and can be replaced by more casual equivalents such as で, に, or は in informal contexts.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_kakawarazu','～にかかわらず',NULL,NULL,'N2','[]','[{"ja":"天気にかかわらず、今日の試合は行われます。","en":"The game today will be held, regardless of the weather.","romaji":"Tenki ni kakawarazu, kyou no shiai wa okonawaremasu.","zh":""},{"ja":"彼は年齢にかかわらず、新しいことを学び続けています。","en":"He continues to learn new things, regardless of his age.","romaji":"Kare wa nenrei ni kakawarazu, atarashii koto wo manabi tsuzukete imasu.","zh":""},{"ja":"その仕事が難しいかどうかにかかわらず、彼女は努力し続けた。","en":"Regardless of whether the job is difficult or not, she continued to make an effort.","romaji":"Sono shigoto ga muzukashii ka dou ka ni kakawarazu, kanojo wa doryoku shi tsuzuketa.","zh":""},{"ja":"経験の有無にかかわらず、このプログラムは誰でも利用できます。","en":"Regardless of experience, this program can be used by anyone.","romaji":"Keiken no umu ni kakawarazu, kono puroguramu wa daredemo riyou dekimasu.","zh":""}]',replace('**Short**: Regardless of; irrespective of; (often used as) ''whether or not''.\n\n**Formation**: Verb-dictionary form + にかかわらず, い-Adjective + にかかわらず, な-Adjective + にかかわらず, Noun + にかかわらず\n\n**Long**: The ～にかかわらず grammar point is used to express that something happens or is true regardless of a particular fact, condition, or circumstance. It can be translated as ''regardless of'', ''irrespective of'', or ''whether or not''. It can be used with verbs, い-adjectives, な-adjectives, or nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_kakete_wa','～にかけては',NULL,NULL,'N2','[]','[{"ja":"料理の腕前にかけては、彼女は誰にも負けません。","en":"When it comes to cooking skills, she is second to none.","romaji":"Ryouri no udemae ni kakete wa, kanojo wa dare ni mo makemasen.","zh":""},{"ja":"この町にかけては、彼の店が一番おいしいラーメンを売っています。","en":"As far as this town is concerned, his store sells the most delicious ramen.","romaji":"Kono machi ni kakete wa, kare no mise ga ichiban oishii raamen wo utteimasu.","zh":""},{"ja":"音楽の知識にかけては、彼は私たちの中で一番詳しいです。","en":"When it comes to music knowledge, he is the most knowledgeable among us.","romaji":"Ongaku no chishiki ni kakete wa, kare wa watashitachi no naka de ichiban kuwashii desu.","zh":""},{"ja":"スポーツにかけては、彼はどんな競技も得意です。","en":"When it comes to sports, he excels in any competition.","romaji":"Supootsu ni kakete wa, kare wa donna kyogi mo tokui desu.","zh":""}]',replace('**Short**: Indicates a specific area or aspect in which someone or something excels.\n\n**Formation**: Noun + にかけては\n\n**Long**: The grammar point ～にかけては is used to emphasize a particular area or aspect in which someone or something excels or is exceptional. This structure is often used with positive connotations regarding the subject''s expertise or outstanding qualities.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_shitagatte','～にしたがって',NULL,NULL,'N2','[]','[{"ja":"成長にしたがって、この植物の葉が大きくなります。","en":"As it grows, the leaves of this plant become larger.","romaji":"Seichou ni shitagatte, kono shokubutsu no ha ga ookiku narimasu.","zh":""},{"ja":"説明書にしたがって、家具を組み立ててください。","en":"Please assemble the furniture according to the instructions.","romaji":"Setsumeisho ni shitagatte, kagu wo kumitatete kudasai.","zh":""},{"ja":"年齢にしたがって、人の体力は低下します。","en":"As people age, their physical strength declines.","romaji":"Nenrei ni shitagatte, hito no tairyoku wa teika shimasu.","zh":""},{"ja":"運動にしたがって、心拍数が増加することが一般的です。","en":"It is common for the heart rate to increase with exercise.","romaji":"Undou ni shitagatte, shinpakusuu ga zouka suru koto ga ippan teki desu.","zh":""}]',replace('**Short**: Expresses a natural consequence or a change that occurs according to something else; ''as'', ''with'', ''in accordance with''.\n\n**Formation**: Noun + にしたがって\n\n**Long**: The ～にしたがって grammar point is used to express a natural consequence or a change that occurs according to something else. It can be translated as ''as'', ''with'', or ''in accordance with'' in English. This grammar point is used with nouns and can be used to show a change in proportion or in accordance with a rule or principle.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_shitara','～にしたら',NULL,NULL,'N2','[]','[{"ja":"彼にしたら、早く帰りたいだろう。","en":"From his perspective, he probably wants to go home early.","romaji":"Kare ni shitara, hayaku kaeritai darou.","zh":""},{"ja":"子供たちにしたら、この話はつまらないかもしれない。","en":"If I were the children, this story might be boring.","romaji":"Kodomo-tachi ni shitara, kono hanashi wa tsumaranai kamoshirenai.","zh":""},{"ja":"私にしたら、そのプレゼントは素晴らしいと思います。","en":"From my perspective, I think that present is wonderful.","romaji":"Watashi ni shitara, sono purezento wa subarashii to omoimasu.","zh":""},{"ja":"彼女にしたら、この映画が好きではないでしょう。","en":"If I were her, I would not like this movie.","romaji":"Kanojo ni shitara, kono eiga ga suki dewa nai deshou.","zh":""}]',replace('**Short**: Express a point of view; ''from the perspective of'', ''if I were''.\n\n**Formation**: Noun + にしたら, Pronoun + にしたら\n\n**Long**: The ～にしたら grammar point is used to express a point of view or opinion from someone else''s perspective. It can be translated as ''from the perspective of'' or ''if I were'' in English. The formation differs depending on whether it is used with a noun or a pronoun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_shiro_ni_shiro','～にしろ～にしろ',NULL,NULL,'N2','[]','[{"ja":"行くにしろ行かないにしろ、早く決めてください。","en":"Either way, whether you go or not, please decide quickly.","romaji":"Iku ni shiro ikanai ni shiro, hayaku kimete kudasai.","zh":""},{"ja":"彼が来るにしろ来ないにしろ、パーティーは始めましょう。","en":"Be it if he comes or not, let''s start the party either way.","romaji":"Kare ga kuru ni shiro konai ni shiro, paatii wa hajimemashou.","zh":""},{"ja":"雨が降るにしろ降らないにしろ、傘を持って行ったほうがいいです。","en":"Either way, whether it rains or not, it''s better to bring an umbrella.","romaji":"Ame ga furu ni shiro furanai ni shiro, kasa wo motte itta hou ga ii desu.","zh":""},{"ja":"このレストランが高いにしろ安いにしろ、料理は美味しいです。","en":"In any case, whether this restaurant is expensive or cheap, the food is delicious.","romaji":"Kono resutoran ga takai ni shiro yasui ni shiro, ryouri wa oishii desu.","zh":""}]',replace('**Short**: Expresses ''either way'', ''in any case'', ''be it...'', used when presenting two alternatives.\n\n**Formation**: Verb (dictionary form or negative form) + にしろ, い-Adjective + にしろ, な-Adjective + にしろ, Noun + にしろ\n\n**Long**: The ～にしろ～にしろ grammar point is used to present two alternatives and emphasize that regardless of which one is chosen or occurs, the result or conclusion remains the same. It can be translated as ''either way'', ''in any case'', or ''be it...''. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_tsuke_ni_tsuke','～につけ～につけ',NULL,NULL,'N2','[]','[{"ja":"外国へ行くにつけ、勉強するにつけ、言葉の壁にぶつかる。","en":"Whether I go abroad or study, I always encounter language barriers.","romaji":"Gaikoku e iku ni tsuke, benkyou suru ni tsuke, kotoba no kabe ni butsukaru.","zh":""},{"ja":"彼と話すにつけ、彼が考えるにつけ、彼の知識に驚かされる。","en":"Whenever I talk to him or hear his thoughts, I''m always amazed by his knowledge.","romaji":"Kare to hanasu ni tsuke, kare ga kangaeru ni tsuke, kare no chishiki ni odorokasareru.","zh":""},{"ja":"この公園で遊ぶにつけ、散歩するにつけ、子供時代を思い出す。","en":"Each time I play or take a walk in this park, it reminds me of my childhood.","romaji":"Kono kouen de asobu ni tsuke, sanpo suru ni tsuke, kodomo jidai wo omoidasu.","zh":""},{"ja":"春につけ、秋につけ、彼は母校を訪れる。","en":"Whether in spring or autumn, he visits his alma mater.","romaji":"Haru ni tsuke, aki ni tsuke, kare wa bokou wo otozureru.","zh":""}]',replace('**Short**: Expresses ''whenever'', ''each time'', ''whether...or''.\n\n**Formation**: Verb-casual + につけ, い-Adjective + につけ, な-Adjective + につけ, Noun + につけ\n\n**Long**: The ～につけ～につけ grammar point is used to express that something happens ''each time'' or ''whenever'' a certain event or situation occurs, and can also mean ''whether...or''. This grammar point indicates that the same event or feeling occurs no matter which of the following situations happen.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_tsurete','～につれて',NULL,NULL,'N2','[]','[{"ja":"年を取るにつれて、健康に気をつけなければなりません。","en":"As you get older, you have to pay more attention to your health.","romaji":"Toshi wo toru ni tsurete, kenkou ni ki wo tsukenakereba narimasen.","zh":""},{"ja":"春が近づくにつれて、気温が上がる。","en":"As spring approaches, the temperature rises.","romaji":"Haru ga chikazuku ni tsurete, kion ga agaru.","zh":""},{"ja":"勉強するにつれて、だんだん分かるようになる。","en":"As I study, I gradually come to understand.","romaji":"Benkyou suru ni tsurete, dandan wakaru you ni naru.","zh":""},{"ja":"経験が増えるにつれて、自信もついてくる。","en":"As your experience increases, so does your confidence.","romaji":"Keiken ga fueru ni tsurete, jishin mo tsuite kuru.","zh":""}]',replace('**Short**: Expresses the idea that as one thing changes, so does another; ''as'', ''along with'', ''while''.\n\n**Formation**: Verb (dictionary form) + につれて, Noun + につれて\n\n**Long**: The ～につれて grammar point is used to express the idea that as one thing changes or progresses, another thing changes or progresses simultaneously. In English, it can be translated as ''as'', ''along with'', or ''while''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_tomonatte','～にともなって',NULL,NULL,'N2','[]','[{"ja":"人口が増えるにともなって、交通渋滞も悪化しています。","en":"As the population increases, traffic congestion is also getting worse.","romaji":"Jinkou ga fueru ni tomonatte, koutsuu juutai mo akka shiteimasu.","zh":""},{"ja":"季節の変わり目にともなって、体調を崩しやすくなります。","en":"As the seasons change, it''s easier to get out of shape.","romaji":"Kisetsu no kawarime ni tomonatte, taichou wo kuzushi yasuku narimasu.","zh":""},{"ja":"経済の成長にともなって、雇用の機会も増えるでしょう。","en":"As the economy grows, employment opportunities will also increase.","romaji":"Keizai no seichou ni tomonatte, koyou no kikai mo fueru deshou.","zh":""},{"ja":"彼の昇進にともなって、引っ越しをすることになりました。","en":"As a result of his promotion, we decided to move.","romaji":"Kare no shoushin ni tomonatte, hikkoshi wo suru koto ni narimashita.","zh":""}]',replace('**Short**: Expresses ''along with'' or ''as a result of''; indicates that one event occurs along with another.\n\n**Formation**: Noun (event) + にともなって, Verb-casual + にともなって\n\n**Long**: The ～にともなって grammar point is used to indicate that one event occurs along with another event, or as a result of another event. It can be translated as ''along with'', ''as a result of'', or ''in accordance with'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_hoka_naranai','～にほかならない',NULL,NULL,'N2','[]','[{"ja":"彼の成功は努力にほかならない。","en":"His success is nothing but hard work.","romaji":"Kare no seikou wa doryoku ni hoka naranai.","zh":""},{"ja":"この痛みは寒さにほかならない。","en":"This pain is nothing but the cold.","romaji":"Kono itami wa samusa ni hoka naranai.","zh":""},{"ja":"彼の失敗の原因は慢心にほかならない。","en":"The cause of his failure is nothing but overconfidence.","romaji":"Kare no shippai no gen''in wa manshin ni hoka naranai.","zh":""},{"ja":"彼女の笑顔は明るさにほかならない。","en":"Her smile is none other than brightness.","romaji":"Kanojo no egao wa akarusa ni hoka naranai.","zh":""}]',replace('**Short**: Express that something is ''nothing but'' or ''none other than''.\n\n**Formation**: Verb-plain + にほかならない, い-Adjective + にほかならない, な-Adjective + にほかならない, Noun + にほかならない\n\n**Long**: The ～にほかならない grammar point is used to emphasize that something is no more or no less than what is specified. It can be seen as a strong way to say that something is ''nothing but'' or ''none other than''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_mo_kakawarazu','～にもかかわらず',NULL,NULL,'N2','[]','[{"ja":"忙しいにもかかわらず、彼は毎日運動しています。","en":"Despite being busy, he exercises every day.","romaji":"Isogashii ni mo kakawarazu, kare wa mainichi undou shiteimasu.","zh":""},{"ja":"雨が降っているにもかかわらず、彼女は散歩に行きました。","en":"Even though it was raining, she went for a walk.","romaji":"Ame ga futteiru ni mo kakawarazu, kanojo wa sanpo ni ikimashita.","zh":""},{"ja":"車が古いにもかかわらず、まだよく走ります。","en":"In spite of the car being old, it still runs well.","romaji":"Kuruma ga furui ni mo kakawarazu, mada yoku hashirimasu.","zh":""},{"ja":"結果が良くないにもかかわらず、彼は頑張り続けました。","en":"Despite the results not being good, he continued to do his best.","romaji":"Kekka ga yoku nai ni mo kakawarazu, kare wa ganbari tsuzukemashita.","zh":""}]',replace('**Short**: Expresses ''despite'', ''in spite of'' or ''even though''.\n\n**Formation**: Verb (any tense/form) + にもかかわらず, い-Adjective + にもかかわらず, な-Adjective (or Noun) + であるにもかかわらず\n\n**Long**: The ～にもかかわらず grammar point is used to express that something occurs, or a situation exists, despite or in spite of a contrasting or unfavorable condition. It can be translated as ''despite'', ''in spite of'', or ''even though'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_yori','～により',NULL,NULL,'N2','[]','[{"ja":"この事故は運転手の不注意により起こりました。","en":"This accident occurred due to the driver''s carelessness.","romaji":"Kono jiko wa untenshu no fuchuui ni yori okorimashita.","zh":""},{"ja":"その映画は小説により制作されました。","en":"The movie was produced based on the novel.","romaji":"Sono eiga wa shousetsu ni yori seisaku saremashita.","zh":""},{"ja":"犯人は警察により逮捕されました。","en":"The criminal was arrested by the police.","romaji":"Hannin wa keisatsu ni yori taiho saremashita.","zh":""},{"ja":"会社の成長は従業員の努力により実現しました。","en":"The company''s growth was achieved through the efforts of its employees.","romaji":"Kaisha no seichou wa juugyouin no doryoku ni yori jitsugen shimashita.","zh":""}]',replace('**Short**: Indicates the reason, method, or means by which something happens; ''by'', ''through'', ''due to''.\n\n**Formation**: Noun + により, Verb + により\n\n**Long**: The ～により grammar point is used to indicate the reason, method, or means by which something happens or is done. It can be often translated as ''by'', ''through'', or ''due to'' in English. It can be attached directly to nouns or verbs in plain form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_watatte','～にわたって',NULL,NULL,'N2','[]','[{"ja":"彼女は一年にわたって日本語を勉強しました。","en":"She studied Japanese for over a year.","romaji":"Kanojo wa ichinen ni watatte nihongo wo benkyou shimashita.","zh":""},{"ja":"このプロジェクトは50キロにわたって道路を建設します。","en":"This project will construct roads across 50 kilometers.","romaji":"Kono purojekuto wa gojukiro ni watatte douro wo kensetsu shimasu.","zh":""},{"ja":"彼の著作は数多くの国にわたって読まれている。","en":"His writings are read throughout numerous countries.","romaji":"Kare no chosaku wa kazu ooku no kuni ni watatte yomarete iru.","zh":""},{"ja":"その秘密は世代にわたって保たれ続けた。","en":"The secret was kept over generations.","romaji":"Sono himitsu wa sedai ni watatte tamotsu sareta.","zh":""}]',replace('**Short**: Indicates a range or extent; ''over'', ''throughout'', ''across''.\n\n**Formation**: Noun + にわたって\n\n**Long**: The ～にわたって grammar point is used to express a range or extent of a particular action, event, or situation. It can be translated as ''over'', ''throughout'', or ''across'' in English. This structure can be used with various types of words such as time, distance, and quantity.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_sakidachi','～に先立ち',NULL,NULL,'N2','[]','[{"ja":"会議に先立ち、資料を確認しましょう。","en":"Before the meeting, let''s check the materials.","romaji":"Kaigi ni sakidachi, shiryou wo kakunin shimashou.","zh":""},{"ja":"出発に先立ち、荷物を整理しました。","en":"Before departure, I organized my luggage.","romaji":"Shuppatsu ni sakidachi, nimotsu wo seiri shimashita.","zh":""},{"ja":"就寝に先立ち、歯を磨きます。","en":"Before going to bed, I brush my teeth.","romaji":"Shuushin ni sakidachi, ha wo migakimasu.","zh":""},{"ja":"映画の上映に先立ち、予告編が放映されます。","en":"Before the movie screening, the trailers are shown.","romaji":"Eiga no jouei ni sakidachi, yokokuhen ga houei saremasu.","zh":""}]',replace('**Short**: Express an action or event that occurs before another; ''before'', ''prior to'', ''preceding''.\n\n**Formation**: Noun + に先立ち / Verb-dictionary form + に先立って\n\n**Long**: The ～に先立ち grammar point is used to indicate that a certain action or event occurs before another action or event. It can be translated as ''before'', ''prior to'', or ''preceding'' in English. It is often used with nouns (Noun + に先立ち) or with dictionary-form verbs (Verb-dictionary form + に先立って).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_hanshite','～に反して',NULL,NULL,'N2','[]','[{"ja":"天気予報に反して、今日は雨が降っている。","en":"Contrary to the weather forecast, it is raining today.","romaji":"Tenki yohou ni hanshite, kyou wa ame ga futte iru.","zh":""},{"ja":"彼の予想に反して、試合に勝った。","en":"We won the match against his prediction.","romaji":"Kare no yosou ni hanshite, shiai ni katta.","zh":""},{"ja":"両親の意見に反して、彼と結婚した。","en":"I married him against my parents'' opinion.","romaji":"Ryoushin no iken ni hanshite, kare to kekkon shita.","zh":""},{"ja":"この映画は批評家の評価に反して大ヒットした。","en":"This movie became a big hit contrary to the critics'' ratings.","romaji":"Kono eiga wa hihyouka no hyouka ni hanshite daihitto shita.","zh":""}]',replace('**Short**: Contrary to, against, in spite of\n\n**Formation**: Noun + に反して\n\n**Long**: The ～に反して grammar point is used to express that something is contrary to or against an expectation or belief. It can be translated as ''contrary to'', ''against'', or ''in spite of'' in English. It is generally used with nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_motozuite','～に基づいて',NULL,NULL,'N2','[]','[{"ja":"研究結果に基づいて、新しい治療法が開発されました。","en":"A new treatment method was developed based on the research results.","romaji":"Kenkyuu kekka ni motozuite, atarashii chiryouhou ga kaihatsu saremashita.","zh":""},{"ja":"法律に基づいて、犯罪者は逮捕されました。","en":"The criminal was arrested according to the law.","romaji":"Houritsu ni motozuite, hanzaisha wa taiho saremashita.","zh":""},{"ja":"そのデータに基づいて、結論を出すことができます。","en":"We can draw conclusions based on that data.","romaji":"Sono deeta ni motozuite, ketsuron o dasu koto ga dekimasu.","zh":""},{"ja":"お客様の要望に基づいて、商品の改善が行われます。","en":"Product improvements will be made based on customer requests.","romaji":"Okyakusama no youbou ni motozuite, shouhin no kaizen ga okonawaremasu.","zh":""}]',replace('**Short**: Based on, according to, depending on\n\n**Formation**: Noun + に基づいて\n\n**Long**: The ～に基づいて grammar point is used to express that something is based on, according to, or depending on a certain source or foundation. It can be used with nouns that represent a source, rule, principle, or standard.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_taishite_n2','～に対して',NULL,NULL,'N2','[]','[{"ja":"日本の文化に対して尊敬の念を持っています。","en":"I have a sense of respect towards Japanese culture.","romaji":"Nihon no bunka ni taishite sonkei no nen wo motte imasu.","zh":""},{"ja":"彼に対して無礼な態度を取らないでください。","en":"Please don''t have a rude attitude towards him.","romaji":"Kare ni taishite burei na taido wo toranaide kudasai.","zh":""},{"ja":"先生の質問に対して、彼女はすぐに答えました。","en":"In response to the teacher''s question, she answered immediately.","romaji":"Sensei no shitsumon ni taishite, kanojo wa sugu ni kotaemashita.","zh":""},{"ja":"男性に対して、女性は同じ仕事でも低い給料をもらっている。","en":"In contrast to men, women receive lower salaries for the same job.","romaji":"Dansei ni taishite, josei wa onaji shigoto demo hikui kyuuryou wo moratte iru.","zh":""}]',replace('**Short**: Expresses ''toward'', ''against'', ''in contrast to'', or ''in response to''.\n\n**Formation**: Noun + に対して\n\n**Long**: The ～に対して grammar point is used to indicate a direction or target, showing an action or attitude towards something or someone. It can also be used to show a contrast between two situations or to express ''in response to'' an action or situation.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_kotaete','～に応えて',NULL,NULL,'N2','[]','[{"ja":"お客様の要望に応えて、新しいメニューを作りました。","en":"Responding to the customers'' requests, we created a new menu.","romaji":"Okyaku-sama no youbou ni kotaete, atarashii menyuu o tsukurimashita.","zh":""},{"ja":"彼はチームの期待に応えて素晴らしいプレーを見せた。","en":"He lived up to the team''s expectations and showed a great performance.","romaji":"Kare wa chiimu no kitai ni kotaete, subarashii puree o miseta.","zh":""},{"ja":"政府は国民の声に応えて、新しい法律を制定した。","en":"The government enacted a new law in response to the voice of the people.","romaji":"Seifu wa kokumin no koe ni kotaete, atarashii houritsu o seitei shita.","zh":""},{"ja":"企業は環境問題に応えて、環境に優しい製品を開発している。","en":"Companies are developing environmentally friendly products in response to environmental issues.","romaji":"Kigyou wa kankyou mondai ni kotaete, kankyou ni yasashii seihin o kaihatsu shite iru.","zh":""}]',replace('**Short**: Responding to; living up to; meeting.\n\n**Formation**: Noun + に応えて\n\n**Long**: The ～に応えて grammar point is used to express an action in response to something (an expectation, request, or situation). It can be translated as ''responding to'', ''living up to'', or ''meeting'' in English. This grammar point is generally used with nouns or noun phrases.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_oujite','～に応じて',NULL,NULL,'N2','[]','[{"ja":"仕事の量に応じて給料が変わります。","en":"The salary changes depending on the amount of work.","romaji":"Shigoto no ryou ni oujite kyuuryou ga kawarimasu.","zh":""},{"ja":"季節に応じて服装を選びましょう。","en":"Choose your clothes according to the season.","romaji":"Kisetsu ni oujite fukusou wo erabimashou.","zh":""},{"ja":"お客様の希望に応じてプランを提案します。","en":"We propose plans according to the customers'' wishes.","romaji":"Okyakusama no kibou ni oujite puran wo teian shimasu.","zh":""},{"ja":"年齢に応じて健康診断項目が異なります。","en":"Health check items vary depending on age.","romaji":"Nenrei ni oujite kenkou shindan koumoku ga kotonarimasu.","zh":""}]',replace('**Short**: In accordance with, depending on, in response to.\n\n**Formation**: Noun + に応じて\n\n**Long**: The ～に応じて grammar point is used to express something that varies according to a certain condition or responds to a change. It can be translated as ''in accordance with'', ''depending on'', or ''in response to'' in English. The formation is used with nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_kimatte_iru','～に決まっている',NULL,NULL,'N2','[]','[{"ja":"こんなに暑い日に運動したら、汗をかくに決まっている。","en":"It''s obvious that you''ll sweat if you exercise on such a hot day.","romaji":"Konna ni atsui hi ni undou shitara, ase wo kaku ni kimatte iru.","zh":""},{"ja":"彼が試験に落ちたら、がっかりするに決まっている。","en":"If he fails the exam, it''s obvious he will be disappointed.","romaji":"Kare ga shiken ni ochitara, gakkari suru ni kimatte iru.","zh":""},{"ja":"彼女はいつも遅れるから、今日も遅れるに決まっている。","en":"She''s always late, so it''s obvious she''ll be late today too.","romaji":"Kanojo wa itsumo okureru kara, kyou mo okureru ni kimatte iru.","zh":""},{"ja":"このゲームは楽しいに決まっている。","en":"It''s obvious that this game is fun.","romaji":"Kono geemu wa tanoshii ni kimatte iru.","zh":""}]',replace('**Short**: Express certainty; ''it is obvious'', ''it must be'', ''no doubt''.\n\n**Formation**: Verb-casual + に決まっている, い-Adjective + に決まっている, な-Adjective + だに決まっている, Noun + だに決まっている\n\n**Long**: The ～に決まっている grammar point is used to express certainty or a strong conviction about a situation or event. It can be translated in English as ''it is obvious'', ''it must be'', or ''no doubt''. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_sotte','～に沿って',NULL,NULL,'N2','[]','[{"ja":"川に沿って歩いていくと、橋が見えてきます。","en":"If you walk along the river, you will see a bridge.","romaji":"Kawa ni sotte aruite iku to, hashi ga miete kimasu.","zh":""},{"ja":"このレシピに沿って料理を作れば、間違いありません。","en":"If you cook according to this recipe, there will be no mistakes.","romaji":"Kono reshipi ni sotte ryouri wo tsukureba, machigai arimasen.","zh":""},{"ja":"規則に沿って行動しなければなりません。","en":"We must act in accordance with the rules.","romaji":"Kisoku ni sotte koudou shinakereba narimasen.","zh":""},{"ja":"山道に沿って進むと、小さな神社があります。","en":"If you follow the mountain path, there is a small shrine.","romaji":"Yamamichi ni sotte susumu to, chiisana jinja ga arimasu.","zh":""}]',replace('**Short**: Along with; in accordance with; following\n\n**Formation**: Noun + に沿って\n\n**Long**: The ～に沿って grammar point is used to express that something happens or is done along with, in accordance with, or following a particular line, path, or guideline. It is often used in instructions or explanations. The に沿って is attached to the noun representing the line, path or guideline.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_suginai','～に過ぎない',NULL,NULL,'N2','[]','[{"ja":"彼の失敗はミスに過ぎない。","en":"His failure is nothing more than a mistake.","romaji":"Kare no shippai wa misu ni suginai.","zh":""},{"ja":"この試験は簡単な問題に過ぎない。","en":"This test is nothing more than a simple question.","romaji":"Kono shiken wa kantan na mondai ni suginai.","zh":""},{"ja":"彼女は友達に過ぎない。","en":"She is nothing more than a friend.","romaji":"Kanojo wa tomodachi ni suginai.","zh":""},{"ja":"その発言は冗談に過ぎない。","en":"That remark is nothing more than a joke.","romaji":"Sono hatsugen wa joudan ni suginai.","zh":""}]',replace('**Short**: Expresses that something is ''just'' or ''nothing more than''; ''merely'', ''only'', ''simply''.\n\n**Formation**: Verb-casual + に過ぎない, い-Adjective + に過ぎない, な-Adjective + に過ぎない, Noun + に過ぎない\n\n**Long**: The ～に過ぎない grammar point is used to indicate that something is ''just'' or ''nothing more than'' the stated quality or condition. It implies that the thing is not as significant or important as it might seem at first glance. This grammar point can be translated as ''merely'', ''only'', or ''simply'' in English. It can be used with verbs, い-adjectives, な-adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_kakawatte','～に関わって',NULL,NULL,'N2','[]','[{"ja":"試験の内容に関わって、先生に質問があります。","en":"I have a question for the teacher regarding the content of the exam.","romaji":"Shiken no naiyou ni kakawatte, sensei ni shitsumon ga arimasu.","zh":""},{"ja":"このプロジェクトに関わって、意見があれば、遠慮なく言ってください。","en":"If you have any opinions regarding this project, please feel free to express them.","romaji":"Kono purojekuto ni kakawatte, iken ga areba, enryo naku itte kudasai.","zh":""},{"ja":"健康に関わって、食生活はとても重要です。","en":"Regarding health, dietary habits are very important.","romaji":"Kenkou ni kakawatte, shokuseikatsu wa totemo juuyou desu.","zh":""},{"ja":"その事件に関わって、彼も少し疑われています。","en":"He is also somewhat suspected in connection with the incident.","romaji":"Sono jiken ni kakawatte, kare mo sukoshi utagawarete imasu.","zh":""}]',replace('**Short**: Indicates that something is related to or influenced by a certain matter or factor; ''concerning'', ''in connection with'', ''regarding''.\n\n**Formation**: Verb-casual + に関わって, い-Adjective + に関わって, な-Adjective + に関わって, Noun + に関わって\n\n**Long**: The ～に関わって grammar point is used to express that something is related to, influenced by, or connected with a certain matter or factor. It can be translated as ''concerning'', ''in connection with'', or ''regarding'' in English. The formation depends on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_kagiri','～に限り',NULL,NULL,'N2','[]','[{"ja":"今日に限り、この商品が半額です。","en":"Today only, this product is half price.","romaji":"Kyou ni kagiri, kono shouhin ga hangaku desu.","zh":""},{"ja":"このクーポンはこの店に限り有効です。","en":"This coupon is valid only at this store.","romaji":"Kono kuupon wa kono mise ni kagiri yuukou desu.","zh":""},{"ja":"会員に限り、無料でこのサービスを利用できます。","en":"Only members can use this service for free.","romaji":"Kaiin ni kagiri, muryou de kono saabisu wo riyou dekimasu.","zh":""},{"ja":"この特典は先着10名に限ります。","en":"This benefit is limited to the first 10 people.","romaji":"Kono tokuten wa senchaku 10-mei ni kagirimasu.","zh":""}]',replace('**Short**: Expresses limitation; ''only'', ''limited to'', ''exclusive to''.\n\n**Formation**: Noun + に限り\n\n**Long**: The ～に限り grammar point is used to indicate that something is limited or exclusive to a certain condition or situation. It can be translated as ''only'', ''limited to'', or ''exclusive to'' in English. The formation is simple and can be used with nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_saishite','～に際して',NULL,NULL,'N2','[]','[{"ja":"卒業式に際して、校長先生がスピーチをします。","en":"At the graduation ceremony, the principal gives a speech.","romaji":"Sotsugyoushiki ni saishite, kouchou sensei ga supiichi wo shimasu.","zh":""},{"ja":"この仕事に際して、責任感が大切です。","en":"Responsibility is important when doing this job.","romaji":"Kono shigoto ni saishite, sekininkan ga taisetsu desu.","zh":""},{"ja":"留学に際して、ビザの手続きが必要です。","en":"Visa procedures are necessary when studying abroad.","romaji":"Ryuugaku ni saishite, biza no tetsuzuki ga hitsuyou desu.","zh":""},{"ja":"結婚式に際して、両親に感謝の気持ちを伝えました。","en":"At the time of the wedding ceremony, I conveyed my gratitude to my parents.","romaji":"Kekkonshiki ni saishite, ryoushin ni kansha no kimochi wo tsutaemashita.","zh":""}]',replace('**Short**: Used to express the moment or the occasion of an action; ''at the time of'', ''upon'', ''when''.\n\n**Formation**: Noun + に際して\n\n**Long**: The ～に際して grammar point describes an action that occurs during a specific event, occasion, or when something takes place. It can be translated into English as ''at the time of'', ''upon'', ''when'', or ''in the event of''. This grammar is used with nouns to describe the context or situation during which an action takes place.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_neba_naranai','～ねばならない',NULL,NULL,'N2','[]','[{"ja":"試験に合格するために、もっと勉強せねばならない。","en":"To pass the exam, I must study more.","romaji":"Shiken ni goukaku suru tame ni, motto benkyou se neba naranai.","zh":""},{"ja":"飛行機に間に合うためには、急がねばならない。","en":"To catch the flight, I must hurry.","romaji":"Hikouki ni maniau tame ni wa, isoga neba naranai.","zh":""},{"ja":"６時までに帰らねばならない。","en":"I have to go home by 6 o''clock.","romaji":"Roku ji made ni kaera neba naranai.","zh":""},{"ja":"この仕事を今日中に終わらせねばならない。","en":"I need to finish this work by the end of the day.","romaji":"Kono shigoto wo kyoujuu ni owarase neba naranai.","zh":""}]',replace('**Short**: Expresses obligation or necessity; ''must'', ''have to'', ''need to''.\n\n**Formation**: Verb-ない form → (remove い) → ね + ばならない\n\n**Long**: The ～ねばならない grammar point is used to express obligation or necessity. It can be translated as ''must'', ''have to'', or ''need to'' in English. This grammar point is mainly used with verbs, indicating that the action must be done.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nomi_narazu_mo','～のみならず～も',NULL,NULL,'N2','[]','[{"ja":"彼は英語のみならず、フランス語も話せます。","en":"He can speak not only English but also French.","romaji":"Kare wa eigo nomi narazu, furansugo mo hanasemasu.","zh":""},{"ja":"このレストランは美味しいのみならず、雰囲気も素晴らしいです。","en":"Not only is this restaurant delicious, but the atmosphere is also great.","romaji":"Kono resutoran wa oishii nomi narazu, fun''iki mo subarashii desu.","zh":""},{"ja":"このアプリは便利のみならず、安全性も高いです。","en":"This app is not only convenient but also highly secure.","romaji":"Kono apuri wa benri nomi narazu, anzen-sei mo takai desu.","zh":""},{"ja":"彼女は頭が良いのみならず、スポーツも得意です。","en":"She is not only smart but also good at sports.","romaji":"Kanojo wa atama ga ii nomi narazu, supootsu mo tokui desu.","zh":""}]',replace('**Short**: Not only... but also; as well as.\n\n**Formation**: Verb-casual + のみならず + (も), い-Adjective + のみならず + (も), な-Adjective + のみならず + (も), Noun + のみならず + (も)\n\n**Long**: The ～のみならず～も grammar point is used to show that something applies not only to one thing, but also to another thing. This can be translated as ''not only... but also'', or ''as well as'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_no_mo_mottomo_da','～のももっともだ',NULL,NULL,'N2','[]','[{"ja":"彼が緊張するのももっともだ。","en":"It''s understandable that he is nervous.","romaji":"Kare ga kinchou suru no mo mottomo da.","zh":""},{"ja":"この問題が難しいのももっともだ。","en":"It''s reasonable that this problem is difficult.","romaji":"Kono mondai ga muzukashii no mo mottomo da.","zh":""},{"ja":"彼女が幸せなのももっともだ。","en":"It''s understandable that she is happy.","romaji":"Kanojo ga shiawase na no mo mottomo da.","zh":""},{"ja":"彼がリーダーなのももっともだ。","en":"It''s reasonable that he is the leader.","romaji":"Kare ga riidaa na no mo mottomo da.","zh":""}]',replace('**Short**: Express that something is understandable or reasonable.\n\n**Formation**: Verb-casual + のももっともだ, い-Adjective + のももっともだ, な-Adjective + なのももっともだ, Noun + なのももっともだ\n\n**Long**: The ～のももっともだ grammar point is used to express that a situation, action, or feeling is understandable or reasonable, considering the circumstances. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_no_ue_de_wa','〜の上では',NULL,NULL,'N2','[]','[{"ja":"効率の上では、この方法が最適です。","en":"In terms of efficiency, this method is the best.","romaji":"Kouritsu no ue de wa, kono houhou ga saiteki desu.","zh":""},{"ja":"法律の上では、彼の行為は違法ではありません。","en":"From a legal standpoint, his actions are not illegal.","romaji":"Houritsu no ue de wa, kare no koui wa ihan dewa arimasen.","zh":""},{"ja":"味の上では、このレストランは評価が高いです。","en":"In terms of taste, this restaurant has a high rating.","romaji":"Aji no ue de wa, kono resutoran wa hyouka ga takai desu.","zh":""},{"ja":"成績の上では、彼はクラスで一番優秀です。","en":"On the basis of grades, he is the most outstanding student in the class.","romaji":"Seiseki no ue de wa, kare wa kurasu de ichiban yuushuu desu.","zh":""}]',replace('**Short**: Indicates ''on the basis of'', ''in terms of'', or ''from the standpoint of''.\n\n**Formation**: Noun or Phrase + の上では\n\n**Long**: The 〜の上では grammar point is used to show that you are expressing a view or making a judgment based on a specific standpoint or perspective. It can be translated as ''on the basis of'', ''in terms of'', or ''from the standpoint of''. The formation is straightforward, which involves attaching 〜の上では to a noun or a phrase.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_no_shita_de','～の下で',NULL,NULL,'N2','[]','[{"ja":"先生の下で勉強するのはとても楽しいです。","en":"Studying under the teacher is very enjoyable.","romaji":"Sensei no shita de benkyou suru no wa totemo tanoshii desu.","zh":""},{"ja":"晴天の下でピクニックをしましょう。","en":"Let''s have a picnic under the clear sky.","romaji":"Seiten no shita de pikunikku wo shimashou.","zh":""},{"ja":"緊張感の下で、彼女はスピーチに成功しました。","en":"Under pressure, she succeeded in her speech.","romaji":"Kinchoukan no shita de, kanojo wa supiichi ni seikou shimashita.","zh":""},{"ja":"親の愛情の下で、子供たちは幸せに育ちます。","en":"Under the love of their parents, children grow up happily.","romaji":"Oya no aijou no shita de, kodomo-tachi wa shiawase ni sodachimasu.","zh":""}]',replace('**Short**: Under the context or condition of; under.\n\n**Formation**: Verb-casual + の下で, い-Adjective + の下で, な-Adjective + の下で, Noun + の下で\n\n**Long**: The ～の下で grammar point is used to express that something occurs under a certain context, condition, or circumstance. It can be translated as ''under'' or ''in'' in English. The formation is simple, as it can be used with verbs, い-adjectives, な-adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_bakari_ka_mo','～ばかりか〜も',NULL,NULL,'N2','[]','[{"ja":"彼はかわいいばかりか、賢くもある。","en":"He is not only cute but also smart.","romaji":"Kare wa kawaii bakari ka, kashikoku mo aru.","zh":""},{"ja":"このレストランは味が良いばかりかサービスも素晴らしいです。","en":"This restaurant not only has great taste but also wonderful service.","romaji":"Kono resutoran wa aji ga yoi bakari ka saabisu mo subarashii desu.","zh":""},{"ja":"彼女は日本語が上手ばかりか英語も話せる。","en":"She can speak not only Japanese but also English.","romaji":"Kanojo wa nihongo ga jouzu bakari ka eigo mo hanaseru.","zh":""},{"ja":"彼は歌が上手いばかりかダンスもうまい。","en":"He is not only good at singing but also dancing.","romaji":"Kare wa uta ga umai bakari ka dansu mo umai.","zh":""}]',replace('**Short**: Expresses ''not only... but also''; emphasizing the extent of something.\n\n**Formation**: Noun/Verb/Adjective + ばかりか + Noun/Verb/Adjective + も\n\n**Long**: The ～ばかりか〜も grammar point is used to express the idea of ''not only... but also'' in a sentence. It emphasizes the extent to which something applies, showing a certain component or factor is not the only relevant one.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_bakari_da','～ばかりだ',NULL,NULL,'N2','[]','[{"ja":"彼は文句を言ってばかりだ。","en":"He is always complaining.","romaji":"Kare wa monku wo itte bakari da.","zh":""},{"ja":"この映画は面白くなくて、退屈してばかりだ。","en":"This movie isn''t interesting, and I''m just bored.","romaji":"Kono eiga wa omoshirokunakute, taikutsu shite bakari da.","zh":""},{"ja":"彼女は暇でいるばかりだ。","en":"She is always just idling around with nothing to do.","romaji":"Kanojo wa hima de iru bakari da.","zh":""},{"ja":"最近、仕事の失敗ばかりだ。","en":"Lately, it’s just been one failure at work after another.","romaji":"Saikin, shigoto no shippai bakari da.","zh":""}]',replace('**Short**: Express a continuing state or negative tendency; ''just'', ''only'', ''always''.\n\n**Formation**: Verb-てform + ばかりだ, い-Adjective + ばかりだ, な-Adjective + ばかりだ, Noun + ばかりだ\n\n**Long**: The ～ばかりだ grammar point is used to express a continuing or unchanging state, often emphasizing a negative or undesired tendency. It can be translated as ''just'', ''only'', or ''always'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_bakari_ni','～ばかりに',NULL,NULL,'N2','[]','[{"ja":"雨が降ったばかりに、試合が中止になりました。","en":"Simply because it rained, the match was cancelled.","romaji":"Ame ga futta bakari ni, shiai ga chuushi ni narimashita.","zh":""},{"ja":"彼が遅れたばかりに、私たちも遅刻しました。","en":"Because he was late, we ended up being late too.","romaji":"Kare ga okureta bakari ni, watashitachi mo chikoku shimashita.","zh":""},{"ja":"忘れ物をしたばかりに、買い物に戻らなければなりません。","en":"Simply because I forgot something, I have to go back to the store.","romaji":"Wasuremono wo shita bakari ni, kaimono ni modoranakereba narimasen.","zh":""},{"ja":"彼女が美人なばかりに、みんなが彼女を羨んでいます。","en":"Just because she is beautiful, everyone is envious of her.","romaji":"Kanojo ga bijin na bakari ni, minna ga kanojo wo urayande imasu.","zh":""}]',replace('**Short**: Express an undesired situation or result caused by something; ''simply because'', ''due to'', ''on account of''.\n\n**Formation**: Verb-casual + ばかりに, い-Adjective + ばかりに, な-Adjective + なばかりに, Noun + なばかりに\n\n**Long**: The ～ばかりに grammar point is used to express an undesired situation or result that arises simply because of some factor. It can be translated as ''simply because'', ''due to'', or ''on account of'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ba_to_iu_mono_demo_nai','～ば～というものでもない',NULL,NULL,'N2','[]','[{"ja":"高いものがいいものばかりではない。","en":"Expensive things are not always good.","romaji":"Takai mono ga ii mono bakari de wa nai.","zh":""},{"ja":"英語ができれば、成功するというものでもない。","en":"Just because you can speak English doesn’t mean you’ll succeed.","romaji":"Eigo ga dekireba, seikou suru to iu mono demo nai.","zh":""},{"ja":"見た目が美しいからといって、心も美しいというものでもない。","en":"Just because someone is beautiful on the outside, it doesn’t mean they’re beautiful on the inside.","romaji":"Mitame ga utsukushii kara to itte, kokoro mo utsukushii to iu mono demo nai.","zh":""},{"ja":"有名大学に入れば、将来が安泰だというものでもない。","en":"Getting into a famous university doesn’t guarantee a secure future.","romaji":"Yuumei daigaku ni haireba, shourai ga antai da to iu mono demo nai.","zh":""}]',replace('**Short**: Not necessarily true that if A, then B.\n\n**Formation**: Verb-ば form + というものでもない\n\n**Long**: The ～ば～というものでもない grammar point is used to express that something is not necessarily true even if a certain condition is met. In other words, if A happens, it doesn''t always mean B will happen.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wa_tomokaku_wa','～はともかく～は',NULL,NULL,'N2','[]','[{"ja":"デザインはともかく、機能はこの携帯電話が一番です。","en":"As for design, the functionality of this phone is the best.","romaji":"Dezain wa tomokaku, kinou wa kono keitai denwa ga ichiban desu.","zh":""},{"ja":"彼の容姿はともかく、性格は素晴らしいです。","en":"Putting aside his looks, his personality is wonderful.","romaji":"Kare no youshi wa tomokaku, seikaku wa subarashii desu.","zh":""},{"ja":"料理の味はともかく、盛り付けは綺麗です。","en":"Putting aside the taste of the food, the presentation is beautiful.","romaji":"Ryouri no aji wa tomokaku, moritsuke wa kirei desu.","zh":""},{"ja":"値段はともかく、このバッグの質は良いです。","en":"Ignoring the price, this bag’s quality is good.","romaji":"Nedan wa tomokaku, kono baggu no shitsu wa yoi desu.","zh":""}]',replace('**Short**: Used to compare or contrast two elements; ''as for...''.\n\n**Formation**: Noun1 はともかく Noun2 は\n\n**Long**: The grammar point ～はともかく～は is used to compare or contrast two elements in a sentence. It implies that the first element can be set aside or is less important compared to the second element. It often translates to ''putting A aside, B...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wa_mada_shimo','～はまだしも',NULL,NULL,'N2','[]','[{"ja":"失敗するのはまだしも、やらないで後悔する方がつらい。","en":"Failing is one thing, but regretting not even trying is worse.","romaji":"Shippai suru no wa mada shimo, yaranai de koukai suru hou ga tsurai.","zh":""},{"ja":"このピザは野菜が少ないのはまだしも、味も悪い。","en":"It’s not just that this pizza has few vegetables, it also tastes bad.","romaji":"Kono piza wa yasai ga sukunai no wa mada shimo, aji mo warui.","zh":""},{"ja":"たまに遅刻するのはまだしも、連絡もせずに遅刻するのは許せない。","en":"Being late occasionally might be forgivable, but being late without any contact is unacceptable.","romaji":"Tama ni chikoku suru no wa mada shimo, renraku mo sezu ni chikoku suru no wa yurusenai.","zh":""},{"ja":"難しい質問に答えられないのはまだしも、簡単な質問にも答えられないのは問題だ。","en":"It’s one thing not to be able to answer difficult questions, but it’s a real problem if you can’t even answer simple ones.","romaji":"Muzukashii shitsumon ni kotaerarenai no wa mada shimo, kantan na shitsumon ni mo kotaerarenai no wa mondai da.","zh":""}]',replace('**Short**: Expresses that while the first item is somewhat acceptable, the second item is not.\n\n**Formation**: Noun1 + はまだしも + Noun2\n\n**Long**: The ～はまだしも grammar point is used to show a contrast where the first item or situation might still be understandable or tolerable, whereas the second one is harder to accept. It’s often translated as ''X is one thing, but Y...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wa_moto_yori','～はもとより',NULL,NULL,'N2','[]','[{"ja":"英語はもとより、スペイン語も勉強しています。","en":"I''m studying not only English, but also Spanish.","romaji":"Eigo wa moto yori, supeingo mo benkyou shite imasu.","zh":""},{"ja":"彼女は料理はもとより、お菓子作りも得意です。","en":"She’s not only good at cooking, but also at making sweets.","romaji":"Kanojo wa ryouri wa moto yori, okashi tsukuri mo tokui desu.","zh":""},{"ja":"このホテルは部屋の清潔さはもとより、サービスも素晴らしいです。","en":"This hotel not only has clean rooms but also great service.","romaji":"Kono hoteru wa heya no seiketsusa wa moto yori, saabisu mo subarashii desu.","zh":""},{"ja":"彼は音楽はもとより、絵も上手です。","en":"He’s not only good at music, but also skilled at drawing.","romaji":"Kare wa ongaku wa moto yori, e mo jouzu desu.","zh":""}]',replace('**Short**: Expressing that something is obvious, and there is also something else.\n\n**Formation**: Noun1 + はもとより, Noun2 + も\n\n**Long**: The ～はもとより grammar point is used to emphasize that something is obvious or a given, and on top of that, there’s another aspect to consider. It translates to ''not only…but also…'' or ''of course…and also…''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wa_nuki_ni_shite','～は抜きにして',NULL,NULL,'N2','[]','[{"ja":"値段は抜きにして、味は美味しい。","en":"Leaving aside the price, the taste is delicious.","romaji":"Nedan wa nuki ni shite, aji wa oishii.","zh":""},{"ja":"彼の性格は抜きにして、彼の実力は認めざるを得ない。","en":"Putting aside his personality, I have to acknowledge his ability.","romaji":"Kare no seikaku wa nuki ni shite, kare no jitsuryoku wa mitomezaru o enai.","zh":""},{"ja":"デザインは抜きにして、この携帯電話の機能は優れています。","en":"Leaving aside the design, this phone’s features are excellent.","romaji":"Dezain wa nuki ni shite, kono keitai denwa no kinou wa sugurete imasu.","zh":""},{"ja":"運転の速さは抜きにして、彼女は親切で信頼できる運転手だ。","en":"Leaving aside her driving speed, she''s a kind and trustworthy driver.","romaji":"Unten no hayasa wa nuki ni shite, kanojo wa shinsetsu de shinrai dekiru untenshu da.","zh":""}]',replace('**Short**: Leaving aside, excluding.\n\n**Formation**: Noun + は抜きにして\n\n**Long**: The ～は抜きにして grammar point is used to express the idea of ''leaving aside'' or ''excluding'' a certain aspect. It is often used to focus the discussion or judgment on something else by disregarding the omitted point.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_beki_dewa_nai','～べきではない',NULL,NULL,'N2','[]','[{"ja":"遅れる理由がないなら、遅れるべきではありません。","en":"If there''s no reason to be late, you shouldn’t be late.","romaji":"Okureru riyuu ga nai nara, okureru beki dewa arimasen.","zh":""},{"ja":"子供に悪口を言うべきではありません。","en":"You shouldn’t say hurtful things to children.","romaji":"Kodomo ni waruguchi o iu beki dewa arimasen.","zh":""},{"ja":"この薬は一度に飲みすぎるべきではない。","en":"You should not take too much of this medicine at once.","romaji":"Kono kusuri wa ichido ni nomisugiru beki dewa nai.","zh":""},{"ja":"知らない人と個人情報を共有するべきではない。","en":"You shouldn''t share personal information with strangers.","romaji":"Shiranai hito to kojin jouhou o kyouyuu suru beki dewa nai.","zh":""}]',replace('**Short**: Express that an action should not be done; ''should not'', ''ought not to''.\n\n**Formation**: Verb-dictionary form + べき + ではない\n\n**Long**: The ～べきではない grammar point is used to indicate that an action is not recommended or should not be done. It can be translated as ''should not'' or ''ought not to'' in English. The typical formation is “Verb-dictionary form + べきではない.”\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mai','～まい',NULL,NULL,'N2','[]','[{"ja":"彼は今晩来るまい。","en":"He probably won''t come tonight.","romaji":"Kare wa konban kuru mai.","zh":""},{"ja":"こんなに遅れては、電車に間に合うまい。","en":"Being this late, I probably won''t make it for the train.","romaji":"Konnani okurete wa, densha ni maniau mai.","zh":""},{"ja":"あの人は絶対に忘れるまい。","en":"That person will definitely not forget.","romaji":"Ano hito wa zettai ni wasureru mai.","zh":""},{"ja":"私は二度とその失敗を繰り返すまい。","en":"I will not repeat that mistake again.","romaji":"Watashi wa nidoto sono shippai o kurikaesu mai.","zh":""}]',replace('**Short**: Express a negative conjecture or determination; ''probably not'' or ''I will not''.\n\n**Formation**: Verb-dictionary form + まい\n\n**Long**: The ～まい grammar point is used to express a negative conjecture or a strong determination not to do something. In modern usage, it is generally used with the dictionary form of verbs (来る→来るまい, する→するまい, etc.). It can be translated as ''probably not'' or ''I will not'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_made_te','～まで～て',NULL,NULL,'N2','[]','[{"ja":"9時まで働いて、その後休憩しました。","en":"I worked until 9 o''clock, and then took a break.","romaji":"Ku-ji made hataraite, sono ato kyuukei shimashita.","zh":""},{"ja":"夜まで勉強して、試験に合格しました。","en":"I studied until night, and passed the exam.","romaji":"Yoru made benkyou shite, shiken ni goukaku shimashita.","zh":""},{"ja":"最後のページまで読んで、本を閉じました。","en":"I read until the last page, then closed the book.","romaji":"Saigo no peeji made yonde, hon o tojimashita.","zh":""},{"ja":"電車が着くまで待って、友達と会いました。","en":"I waited until the train arrived, and then met my friend.","romaji":"Densha ga tsuku made matte, tomodachi to aimashita.","zh":""}]',replace('**Short**: Express doing something until a certain time or condition; ''until'', ''to''.\n\n**Formation**: Time/Noun + まで + Verb(て-form)\n\n**Long**: The ～まで～て grammar point is used to show that an action continues until a certain time or condition. In your examples, a time expression (such as 9時) is followed by まで, then the action in the て-form. It can be translated as ''until'' or ''up to the point when/where''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mama_ni','～ままに',NULL,NULL,'N2','[]','[{"ja":"子供が寝ているままに、静かに部屋を出ました。","en":"I quietly left the room while the child was still sleeping.","romaji":"Kodomo ga nete iru mama ni, shizuka ni heya o demashita.","zh":""},{"ja":"窓が開いたままで、寒くなりました。","en":"It got cold with the window left open.","romaji":"Mado ga aita mama de, samuku narimashita.","zh":""},{"ja":"彼は元気なままで老人ホームに入りました。","en":"He entered the nursing home while still in good health.","romaji":"Kare wa genki na mama de roujin hoomu ni hairimashita.","zh":""},{"ja":"昔の思い出のままに、この町に戻りました。","en":"I returned to this town with my old memories intact.","romaji":"Mukashi no omoide no mama ni, kono machi ni modorimashita.","zh":""}]',replace('**Short**: Act according to; leave as is; unchanged.\n\n**Formation**: Verb-て + まま, い-Adjective + のまま, な-Adjective + なまま, Noun + のまま\n\n**Long**: The ～ままに grammar point is used to express leaving something in its current state or doing something exactly as is. It can also imply doing something naturally or without altering the circumstances. Depending on the part of speech, different particles are used: Verb-て + まま, い-Adjective + のまま, な-Adjective + なまま, Noun + のまま.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mo_kamawazu','～もかまわず',NULL,NULL,'N2','[]','[{"ja":"彼は周りの人もかまわず、大声で話しました。","en":"Without worrying about the people around him, he spoke loudly.","romaji":"Kare wa mawari no hito mo kamawazu, oogoe de hanashimashita.","zh":""},{"ja":"彼女は時間もかまわず、ゆっくりと本を読み続けました。","en":"She kept reading the book leisurely, without worrying about the time.","romaji":"Kanojo wa jikan mo kamawazu, yukkuri to hon o yomitsuzukemashita.","zh":""},{"ja":"彼は寒さもかまわず、外で運動しました。","en":"He exercised outside without worrying about the cold.","romaji":"Kare wa samusa mo kamawazu, soto de undou shimashita.","zh":""},{"ja":"彼女は危険もかまわず、火事の中に飛び込んで助けに行きました。","en":"She jumped into the fire without fear of danger to help.","romaji":"Kanojo wa kiken mo kamawazu, kaji no naka ni tobikonde tasuke ni ikimashita.","zh":""}]',replace('**Short**: Express indifference or disregard; ''without hesitating'', ''without worrying about''.\n\n**Formation**: Verb-dictionary form + もかまわず, Noun + もかまわず\n\n**Long**: The ～もかまわず grammar point is used to express indifference or disregard toward possible consequences or external factors. It can be translated as ''without hesitating'', ''without worrying about'', or ''regardless of''. It attaches to verbs in their dictionary form or nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mono_ka','～ものか',NULL,NULL,'N2','[]','[{"ja":"そんなこと、僕がやりたいものか。","en":"No way do I want to do such a thing.","romaji":"Sonna koto, boku ga yaritai mono ka.","zh":""},{"ja":"こんな仕事、誰が引き受けようものか。","en":"Who on earth would take on a job like this? (No one would!)","romaji":"Konna shigoto, dare ga hikiukeyou mono ka.","zh":""},{"ja":"誰が彼に助けを求めようものか。","en":"Who would ever ask him for help? (Certainly no one!)","romaji":"Dare ga kare ni tasuke o motomeyou mono ka.","zh":""},{"ja":"この寒い日に外で遊ぶなんて、無理なものか。","en":"There''s no way we can play outside on a day this cold.","romaji":"Kono samui hi ni soto de asobu nante, muri na mono ka.","zh":""}]',replace('**Short**: Definitely not; no way; no chance.\n\n**Formation**: Verb-casual + ものか, い-Adjective + ものか, な-Adjective + (な)ものか, Noun + (な)ものか\n\n**Long**: The ～ものか grammar point is used to express a strong denial, refusal, or astonishment. It often appears with a rhetorical question tone in casual forms, such as Verb (dictionary/volitional/～たい) + ものか, Adjective + ものか, or Noun + ものか, meaning ''No way...'', ''As if I''d ever...'', etc.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mono_ga_aru','～ものがある',NULL,NULL,'N2','[]','[{"ja":"彼のスピーチには心を打たれるものがある。","en":"There''s something moving about his speech.","romaji":"Kare no supiichi ni wa kokoro o utareru mono ga aru.","zh":""},{"ja":"この映画には考えさせられるものがある。","en":"There''s something about this movie that really makes you think.","romaji":"Kono eiga ni wa kangaesaserareru mono ga aru.","zh":""},{"ja":"彼の言うことにも一理あるものがある。","en":"There''s a certain point in what he says.","romaji":"Kare no iu koto ni mo ichiri aru mono ga aru.","zh":""},{"ja":"毎日忙しすぎる生活には少し息苦しいものがある。","en":"There''s something a bit suffocating about being so busy every day.","romaji":"Mainichi isogashisugiru seikatsu ni wa sukoshi ikigurushii mono ga aru.","zh":""}]',replace('**Short**: Express a strong impression or feeling; ''there''s something about it that...''\n\n**Formation**: Verb-casual + ものがある, い-Adjective + ものがある, な-Adjective + なものがある\n\n**Long**: 「～ものがある」 is used to convey that there is a certain intangible quality or strong feeling about something that the speaker cannot ignore. It is often used with verbs (plain form), い-adjectives, or な-adjectives + な, to show that one ‘feels strongly that...’ or ‘there’s something about it that…’.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mono_da','～ものだ',NULL,NULL,'N2','[]','[{"ja":"若い時はたくさん遊ぶものだ。","en":"It is natural to have a lot of fun when you are young.","romaji":"Wakai toki wa takusan asobu mono da.","zh":""},{"ja":"約束をしたら、守るものだ。","en":"If you make a promise, you should keep it.","romaji":"Yakusoku o shitara, mamoru mono da.","zh":""},{"ja":"お客さんが来ると、お茶を出すものだ。","en":"When guests arrive, it''s customary to serve tea.","romaji":"Okyakusan ga kuru to, ocha o dasu mono da.","zh":""},{"ja":"人生は困難に立ち向かうものだ。","en":"In life, one ought to face hardships.","romaji":"Jinsei wa konnan ni tachimukau mono da.","zh":""}]',replace('**Short**: Expresses something natural or expected; ''it is normal that...'', ''should'', ''ought to''.\n\n**Formation**: Verb-dictionary form + ものだ, な-Adjective + なものだ, (Also: Verb-た form + ものだ for recollections)\n\n**Long**: 「～ものだ」 can indicate that something is regarded as a general truth, common sense, or natural behavior. It can also express strong sentiment or emotion. In the past tense (Verb-た form + ものだ), it often shows nostalgia or recollection (''I used to...'').\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mono_dakara','～ものだから',NULL,NULL,'N2','[]','[{"ja":"試験が近いものだから、毎日勉強しています。","en":"Because the exam is near, I''m studying every day.","romaji":"Shiken ga chikai mono dakara, mainichi benkyou shiteimasu.","zh":""},{"ja":"このレストランはとても人気があるものだから、予約しないと席がないかもしれません。","en":"Because this restaurant is very popular, there might not be any seats if we don''t reserve.","romaji":"Kono resutoran wa totemo ninki ga aru mono dakara, yoyaku shinai to seki ga nai kamoshiremasen.","zh":""},{"ja":"彼は若いものだから、まだたくさんの経験を積んでいない。","en":"Because he is young, he hasn''t accumulated much experience yet.","romaji":"Kare wa wakai mono dakara, mada takusan no keiken wo tsunde inai.","zh":""},{"ja":"今日は寒いものだから、手袋を持って行きましょう。","en":"Since it''s cold today, let''s bring gloves.","romaji":"Kyou wa samui mono dakara, tebukuro wo motte ikimashou.","zh":""}]',replace('**Short**: Express the reason or cause for something; ''because'', ''since'', ''due to''.\n\n**Formation**: Verb-plain + ものだから, い-Adjective + ものだから, な-Adjective + なものだから, Noun + なものだから\n\n**Long**: 「～ものだから」 is used to explain a reason or cause from the speaker’s point of view. It can be translated as ''because'', ''since'', or ''due to''. It often carries the nuance of ''you see, that''s why ...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mono_dewa_nai','～ものではない',NULL,NULL,'N2','[]','[{"ja":"そんなことを言うものではありません。","en":"You should not say such a thing.","romaji":"Sonna koto o iu mono dewa arimasen.","zh":""},{"ja":"公共の場で大声を出すものではない。","en":"You should not raise your voice in public places.","romaji":"Koukyou no ba de oogoe o dasu mono dewa nai.","zh":""},{"ja":"彼の秘密を他の人に教えるものではありません。","en":"You must not tell his secret to other people.","romaji":"Kare no himitsu o hoka no hito ni oshieru mono dewa arimasen.","zh":""},{"ja":"安全な場所では遊んでいいが、危険なところで遊ぶものではない。","en":"It''s okay to play in safe places, but you should not play somewhere dangerous.","romaji":"Anzen na basho de wa asonde ii ga, kiken na tokoro de asobu mono dewa nai.","zh":""}]',replace('**Short**: Expresses a strong negative suggestion or prohibition: ''should not'', ''must not''.\n\n**Formation**: Verb-dictionary form + ものではない\n\n**Long**: 「～ものではない」 is used to indicate that something should not or must not be done. It often appears in written or formal contexts, meaning ''it is not proper to...'' or ''you shouldn’t...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mono_nara','～ものなら',NULL,NULL,'N2','[]','[{"ja":"帰れるものなら、今すぐ国へ帰りたい。","en":"If I could possibly go back, I''d return to my country right now.","romaji":"Kaereru mono nara, ima sugu kuni e kaeritai.","zh":""},{"ja":"できるものなら、世界を一周してみたい。","en":"If it were possible, I''d love to travel around the world.","romaji":"Dekiru mono nara, sekai o isshuu shite mitai.","zh":""},{"ja":"やり直せるものなら、子供の頃に戻りたい。","en":"If I could redo my life, I''d go back to my childhood.","romaji":"Yarinaoseru mono nara, kodomo no koro ni modoritai.","zh":""},{"ja":"元気になれるものなら、どんな薬でも試したい。","en":"If it could make me healthy, I''d try any medicine.","romaji":"Genki ni nareru mono nara, donna kusuri demo tameshitai.","zh":""}]',replace('**Short**: Expresses a conditional wish or unlikely possibility; ''if only'', ''if it were possible''.\n\n**Formation**: Verb-(potential/plain) form + ものなら, etc.\n\n**Long**: 「～ものなら」 is used when expressing a strong wish under a hypothetical or difficult condition. It often implies that fulfilling this condition is unlikely or very hard, but ''if only it could happen, then...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mono_no','～ものの、～',NULL,NULL,'N2','[]','[{"ja":"早起きしたものの、バスに間に合わなかった。","en":"Even though I got up early, I didn''t catch the bus in time.","romaji":"Hayaoki shita mono no, basu ni maniawanakatta.","zh":""},{"ja":"この部屋は広いものの、家具が少ない。","en":"Although this room is spacious, there isn''t much furniture.","romaji":"Kono heya wa hiroi mono no, kagu ga sukunai.","zh":""},{"ja":"彼女は美しいものの、性格が悪い。","en":"She is beautiful, but her personality is bad.","romaji":"Kanojo wa utsukushii mono no, seikaku ga warui.","zh":""},{"ja":"彼は有名な歌手であるものの、コンサートにあまり人が来なかった。","en":"Although he is a famous singer, not many people came to his concert.","romaji":"Kare wa yuumei na kashu de aru mono no, konsaato ni amari hito ga konakatta.","zh":""}]',replace('**Short**: Indicates contrast or contradiction between two clauses; ''although'', ''but''.\n\n**Formation**: Verb-casual + ものの, い-Adjective + ものの, な-Adjective + なものの, Noun + であるものの\n\n**Long**: 「～ものの」 is used to connect two parts of a sentence where the first part is true, yet the second part shows a contrasting or unexpected outcome. It can be translated as ''although'', ''even though'', or ''but still''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mo_ba_mo','～も～ば～も～',NULL,NULL,'N2','[]','[{"ja":"彼は勉強もできればスポーツもできる。","en":"He is good at studying and also at sports.","romaji":"Kare wa benkyou mo dekireba supootsu mo dekiru.","zh":""},{"ja":"このレストランは値段も安ければ味もいい。","en":"This restaurant is cheap, and the food is also good.","romaji":"Kono resutoran wa nedan mo yasukereba aji mo ii.","zh":""},{"ja":"彼女はピアノも弾けばギターも弾く。","en":"She plays both the piano and the guitar.","romaji":"Kanojo wa piano mo hikeba gitaa mo hiku.","zh":""},{"ja":"人生には楽しい時もあれば辛い時もある。","en":"In life, there are both fun times and tough times.","romaji":"Jinsei ni wa tanoshii toki mo areba tsurai toki mo aru.","zh":""}]',replace('**Short**: Lists multiple attributes or actions applying to the same subject: ''both…and…'', ''not only…but also…''.\n\n**Formation**: Noun/Verb/Adjective + も + (Verb/Adjective in ば-form) + も + (Verb/Adjective)\n\n**Long**: 「～も～ば～も～」 is used when describing multiple characteristics or actions. It often appears with the conditional form (ば) plus も, indicating that ''A is true, and also B is true.'' For example, ''He can do X, and he can also do Y.'' It''s different from ''～ば～ほど'', which means ''the more… the more…''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mo_douzen_da','～も同然だ',NULL,NULL,'N2','[]','[{"ja":"彼とは長い付き合いだから、家族も同然だ。","en":"I''ve known him for so long that he''s practically family.","romaji":"Kare to wa nagai tsukiai dakara, kazoku mo douzen da.","zh":""},{"ja":"毎日遅刻するなんて、来ていないも同然だ。","en":"Being late every single day is as good as not coming at all.","romaji":"Mainichi chikoku suru nante, kite inai mo douzen da.","zh":""},{"ja":"彼女と私は幼なじみで、姉妹も同然の仲です。","en":"She and I are childhood friends, practically like sisters.","romaji":"Kanojo to watashi wa osananajimi de, shimai mo douzen no naka desu.","zh":""},{"ja":"こんなに少ない給料じゃ、ただ働きも同然だ。","en":"With such a small salary, it''s practically like working for free.","romaji":"Konna ni sukunai kyuuryou ja, tadabataraki mo douzen da.","zh":""}]',replace('**Short**: Indicates ''as good as'', ''virtually'', or ''practically'' the same as something.\n\n**Formation**: Noun + (も)同然だ, Verb-casual + (も)同然だ, etc.\n\n**Long**: 「～も同然だ」 means something is practically the same as (X). It emphasizes that although it may not be literally identical, there is hardly any difference in reality.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_yara_yara','～やら～やら',NULL,NULL,'N2','[]','[{"ja":"宿題やら掃除やら、やることがたくさんある。","en":"I have lots of things to do, like homework and cleaning.","romaji":"Shukudai yara souji yara, yaru koto ga takusan aru.","zh":""},{"ja":"野菜やら果物やら、色々な食べ物を買いました。","en":"I bought all sorts of foods, such as vegetables and fruits.","romaji":"Yasai yara kudamono yara, iroiro na tabemono wo kaimashita.","zh":""},{"ja":"彼女は歌がうまいやら踊れるやら、本当に多才だ。","en":"She’s really talented—she can sing well, dance, and so on.","romaji":"Kanojo wa uta ga umai yara odoreru yara, hontou ni tasai da.","zh":""},{"ja":"お店にはバッグやら靴やらアクセサリーやらが置いてある。","en":"The store has all kinds of items like bags, shoes, accessories, etc.","romaji":"Omise ni wa baggu yara kutsu yara akusesarii yara ga oite aru.","zh":""}]',replace('**Short**: Expresses various items or actions, ''things like..., and so on''.\n\n**Formation**: Verb-casual + やら, い-Adjective + やら, な-Adjective + やら, Noun + やら\n\n**Long**: 「～やら～やら」 is used to list multiple things or actions in a somewhat non-exhaustive way. It can be translated as ''things like A and B'' or ''A, B, and so on.'' The grammar is often Verb-casual + やら, Noun + やら, い-Adjective + やら, etc.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_you_ga_nai_n2','～ようがない',NULL,NULL,'N2','[]','[{"ja":"彼の連絡先がわからないので、助けようがない。","en":"I don''t know his contact information, so there''s no way I can help him.","romaji":"Kare no renrakusaki ga wakaranai node, tasukeyou ga nai.","zh":""},{"ja":"ここまで壊れてしまったら、もう直しようがない。","en":"Now that it''s broken this badly, there''s no way to fix it.","romaji":"Koko made kowarete shimattara, mou naoshiyou ga nai.","zh":""},{"ja":"証拠が全くないから、彼が犯人だと証明しようがない。","en":"There’s no evidence at all, so there’s no way to prove he’s the culprit.","romaji":"Shouko ga mattaku nai kara, kare ga hannin da to shoumeishiyou ga nai.","zh":""},{"ja":"突然英語で話しかけられて、何と答えればいいか分からず答えようがなかった。","en":"I was suddenly spoken to in English and didn’t know how to respond, so there was no way for me to reply.","romaji":"Totsuzen eigo de hanashikakerarete, nan to kotaereba ii ka wakarazu kotaeyou ga nakatta.","zh":""}]',replace('**Short**: Expresses that there is no way (method) to do something; it''s impossible to do.\n\n**Formation**: Verb-ます stem + ようがない\n\n**Long**: 「～ようがない」 is used with the ます-stem of a verb to indicate that there is no means or method to carry out that action. It conveys the sense that it''s impossible to do something or that there''s absolutely no way to achieve it.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_yori_hoka_nai','～よりほかない',NULL,NULL,'N2','[]','[{"ja":"試験が近いので、勉強するよりほかない。","en":"Since the exam is near, there is no choice but to study.","romaji":"Shiken ga chikai node, benkyou suru yori hoka nai.","zh":""},{"ja":"風邪がひどいので、早く寝るよりほかない。","en":"My cold is severe, so I have no choice but to go to bed early.","romaji":"Kaze ga hidoi node, hayaku neru yori hoka nai.","zh":""},{"ja":"バスが来ないので、歩くよりほかない。","en":"Since the bus isn''t coming, I have no choice but to walk.","romaji":"Basu ga konai node, aruku yori hoka nai.","zh":""},{"ja":"お金がないので、安いものを買うよりほかない。","en":"Since I have no money, I have no choice but to buy cheap things.","romaji":"Okane ga nai node, yasui mono o kau yori hoka nai.","zh":""}]',replace('**Short**: Express that there is no other choice; ''have no choice but'', ''cannot do anything but''.\n\n**Formation**: Verb-dictionary form + よりほかない\n\n**Long**: The ～よりほかない grammar point is used to express that there is no other choice or alternative in a given situation. It can be translated as ''have no choice but to...'', ''nothing but...'', or ''cannot do anything but...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wake_ga_nai_n2','～わけがない',NULL,NULL,'N2','[]','[{"ja":"彼が怪我をしたから、試合に勝てるわけがない。","en":"He got injured, so there''s no way he can win the match.","romaji":"Kare ga kega wo shita kara, shiai ni kateru wake ga nai.","zh":""},{"ja":"嘘ばかり言っている人を、信じるわけがない。","en":"There''s no way I can believe someone who constantly lies.","romaji":"Uso bakari itte iru hito wo, shinjiru wake ga nai.","zh":""},{"ja":"彼女は忙しいから、このパーティーに来るわけがない。","en":"She''s busy, so there''s no way she can come to this party.","romaji":"Kanojo wa isogashii kara, kono paatii ni kuru wake ga nai.","zh":""},{"ja":"昨日はずっと寝ていたから、その事件を知るわけがない。","en":"I was asleep all day yesterday, so there''s no way I could know about that incident.","romaji":"Kinou wa zutto nete ita kara, sono jiken wo shiru wake ga nai.","zh":""}]',replace('**Short**: Expresses ''there’s no way'' or ''it’s impossible'', indicating a high degree of certainty.\n\n**Formation**: Verb-casual + わけがない, い-Adjective + わけがない, な-Adjective + なわけがない, Noun + のわけがない\n\n**Long**: The ～わけがない grammar point is used to express that something is highly unlikely or impossible. It can be translated as ''there''s no way'' or ''it''s impossible''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wake_da_n2','～わけだ',NULL,NULL,'N2','[]','[{"ja":"彼女が遅れたのは、電車が遅れたわけだ。","en":"The reason she was late is that the train was delayed.","romaji":"Kanojo ga okureta no wa, densha ga okureta wake da.","zh":""},{"ja":"授業が面白かったから、みんな熱心に聞いていたわけだ。","en":"The class was interesting, so that''s why everyone was listening intently.","romaji":"Jugyou ga omoshirokatta kara, minna nesshin ni kiiteita wake da.","zh":""},{"ja":"彼はとても忙しいですから、休みがほとんどないわけだ。","en":"He''s really busy, which is why he hardly has any time off.","romaji":"Kare wa totemo isogashii desu kara, yasumi ga hotondo nai wake da.","zh":""},{"ja":"この問題が難しいから、全然わからないわけだ。","en":"This problem is tough, so no wonder I don''t understand it at all.","romaji":"Kono mondai ga muzukashii kara, zenzen wakaranai wake da.","zh":""}]',replace('**Short**: Express a logical conclusion or reason; ''it means'', ''no wonder'', ''the reason is''.\n\n**Formation**: Verb-casual + わけだ, い-Adjective + わけだ, な-Adjective + なわけだ, Noun + のわけだ\n\n**Long**: The ～わけだ grammar point is used to express a logical conclusion or reason. It can be translated as ''it means...'', ''no wonder...'', or ''that explains why...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wake_dewa_nai_n2','～わけではない',NULL,NULL,'N2','[]','[{"ja":"彼が勉強しないわけではないが、成績があまり良くない。","en":"It''s not that he doesn''t study, but his grades aren''t very good.","romaji":"Kare ga benkyou shinai wake dewa nai ga, seiseki ga amari yoku nai.","zh":""},{"ja":"このレストランが高いわけではないけど、毎日通うには少し高いね。","en":"It''s not that this restaurant is expensive, but it''s a bit too pricey to go there every day.","romaji":"Kono resutoran ga takai wake dewa nai kedo, mainichi kayou ni wa sukoshi takai ne.","zh":""},{"ja":"彼女が優しくないわけではないが、時々話し方がきついことがある。","en":"It''s not that she''s unkind, but sometimes her manner of speaking can be harsh.","romaji":"Kanojo ga yasashikunai wake dewa nai ga, tokidoki hanashikata ga kitsui koto ga aru.","zh":""},{"ja":"彼が忙しいわけではないが、時間を上手に使えていないようだ。","en":"It''s not that he''s busy; he just doesn''t seem to use his time effectively.","romaji":"Kare ga isogashii wake dewa nai ga, jikan o jouzu ni tsukaete inai you da.","zh":""}]',replace('**Short**: Not necessarily; it doesn''t mean that ~.\n\n**Formation**: Verb-plain + わけではない, い-Adjective + わけではない, な-Adjective + だわけではない, Noun + だわけではない\n\n**Long**: The ～わけではない grammar point is used to express that something is not necessarily the case or ''it doesn’t mean that...'' It negates a broad assumption or generalization.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wake_ni_wa_ikanai_n2','～わけにはいかない',NULL,NULL,'N2','[]','[{"ja":"試験が近いから、遊ぶわけにはいかない。","en":"Since the exam is close, I can''t afford to just play around.","romaji":"Shiken ga chikai kara, asobu wake ni wa ikanai.","zh":""},{"ja":"田中さんが待っているので、遅れるわけにはいかない。","en":"Mr. Tanaka is waiting, so I absolutely must not be late.","romaji":"Tanaka-san ga matteiru node, okureru wake ni wa ikanai.","zh":""},{"ja":"子供たちのために、この仕事を辞めるわけにはいかない。","en":"For the sake of my kids, I can''t afford to quit this job.","romaji":"Kodomo-tachi no tame ni, kono shigoto o yameru wake ni wa ikanai.","zh":""},{"ja":"この問題は重要だから、無視するわけにはいかない。","en":"This issue is important, so I can''t simply ignore it.","romaji":"Kono mondai wa juuyou dakara, mushi suru wake ni wa ikanai.","zh":""}]',replace('**Short**: Expresses that one cannot (or must not) do something due to responsibility, social pressure, etc.\n\n**Formation**: Verb-dictionary form + わけにはいかない\n\n**Long**: The ～わけにはいかない grammar point is used to express that you cannot afford to do something or are not allowed to do it. It often implies a sense of responsibility, moral/social obligation, or external pressure that prevents you from doing it.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wo_kikkake_ni','～をきっかけに',NULL,NULL,'N2','[]','[{"ja":"結婚をきっかけに、彼は真剣に仕事を頑張り始めた。","en":"Getting married was the catalyst for him to start working seriously.","romaji":"Kekkon o kikkake ni, kare wa shinken ni shigoto o ganbarihajimeta.","zh":""},{"ja":"あの出会いをきっかけに、私たちは友達になりました。","en":"That encounter led us to become friends.","romaji":"Ano deai o kikkake ni, watashitachi wa tomodachi ni narimashita.","zh":""},{"ja":"コンサートをきっかけに、彼女は音楽の道に進むことを決めました。","en":"Inspired by the concert, she decided to pursue music.","romaji":"Konsaato o kikkake ni, kanojo wa ongaku no michi ni susumu koto o kimemashita.","zh":""},{"ja":"留学をきっかけに、私の外国語スキルが向上しました。","en":"Studying abroad gave me the chance to improve my foreign language skills.","romaji":"Ryuugaku o kikkake ni, watashi no gaikokugo sukiru ga koujou shimashita.","zh":""}]',replace('**Short**: Indicates that something serves as a trigger or starting point for another action/event.\n\n**Formation**: Noun + をきっかけに\n\n**Long**: 「～をきっかけに」 is used with a noun to show that an event, thing, or situation became a trigger or motive that led to a new development or action. It translates as ''taking ... as an opportunity,'' ''due to ...,'' or ''inspired by ...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wo_toshite','～を～として',NULL,NULL,'N2','[]','[{"ja":"彼は教師を職業として働いています。","en":"He works as a teacher.","romaji":"Kare wa kyoushi o shokugyou toshite hataraite imasu.","zh":""},{"ja":"彼女はリーダーを役割として受け入れました。","en":"She accepted the role of leader.","romaji":"Kanojo wa riidaa o yakuwari toshite ukeiremashita.","zh":""},{"ja":"私たちは彼を仲間として信頼しています。","en":"We trust him as one of our own (a close companion).","romaji":"Watashitachi wa kare o nakama toshite shinrai shite imasu.","zh":""},{"ja":"このアーティストは伝統を基盤として作品を作ります。","en":"This artist creates works with tradition as the foundation.","romaji":"Kono aatisuto wa dentou o kiban toshite sakuhin o tsukurimasu.","zh":""}]',replace('**Short**: Express ''as'', ''in the capacity of'', or ''taking something as...''.\n\n**Formation**: Noun1 + を + Noun2 + として\n\n**Long**: The grammar pattern 「～を～として」 is used with nouns to indicate taking one thing ''as'' or ''in the role of'' another. It shows how a certain noun is being viewed or utilized.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wo_chuushin_ni','～を中心に',NULL,NULL,'N2','[]','[{"ja":"このイベントは音楽を中心に楽しまれています。","en":"This event is mainly enjoyed for its music.","romaji":"Kono ibento wa ongaku o chuushin ni tanoshimarete imasu.","zh":""},{"ja":"彼の仕事は東京を中心に行われています。","en":"His work is primarily conducted in and around Tokyo.","romaji":"Kare no shigoto wa Toukyou o chuushin ni okonawarete imasu.","zh":""},{"ja":"彼女は健康を中心に本を書いています。","en":"She’s writing a book focusing on health.","romaji":"Kanojo wa kenkou o chuushin ni hon o kaite imasu.","zh":""},{"ja":"最近の研究は環境保護を中心に行われている。","en":"Recent research is being carried out with a primary focus on environmental protection.","romaji":"Saikin no kenkyuu wa kankyou hogo o chuushin ni okonawarete iru.","zh":""}]',replace('**Short**: Indicates that something is centered around or focused on a main topic or area.\n\n**Formation**: Noun + を中心に\n\n**Long**: 「～を中心に」 is used with nouns to show that an action or situation is mainly or primarily about the specified noun. It can be translated as ''centered on'', ''focusing on'', or ''with ... as the main focus''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wo_towazu','～を問わず',NULL,NULL,'N2','[]','[{"ja":"このイベントは、年齢を問わず、誰でも参加できます。","en":"This event is open to everyone, regardless of age.","romaji":"Kono ibento wa, nenrei o towazu, dare demo sanka dekimasu.","zh":""},{"ja":"このスーパーは、日曜日を問わず、毎日開いています。","en":"This supermarket is open every day, regardless of Sunday.","romaji":"Kono suupaa wa, nichiyoubi o towazu, mainichi aite imasu.","zh":""},{"ja":"彼女は、暑さ寒さを問わず、毎朝散歩をしています。","en":"She takes a walk every morning, no matter the heat or cold.","romaji":"Kanojo wa, atsusa samusa o towazu, maiasa sanpo o shite imasu.","zh":""},{"ja":"社長は、国籍を問わず、すべての社員を平等に扱っています。","en":"The company president treats all employees equally, regardless of nationality.","romaji":"Shachou wa, kokuseki o towazu, subete no shain o byoudou ni atsukatte imasu.","zh":""}]',replace('**Short**: Means ''regardless of'' or ''irrespective of''.\n\n**Formation**: Noun + を問わず\n\n**Long**: 「～を問わず」 is used to express that something applies or is available without any distinction regarding the stated nouns/conditions. It means ''regardless of...'' or ''irrespective of...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wo_komete','～を込めて',NULL,NULL,'N2','[]','[{"ja":"愛を込めて料理を作りました。","en":"I cooked the meal with love.","romaji":"Ai wo komete ryouri wo tsukurimashita.","zh":""},{"ja":"感謝を込めて先生にお礼の手紙を書きました。","en":"I wrote a thank-you letter to my teacher, filled with gratitude.","romaji":"Kansha wo komete sensei ni orei no tegami wo kakimashita.","zh":""},{"ja":"彼は全力を込めて最後の瞬間まで戦いました。","en":"He fought until the last moment with all his strength.","romaji":"Kare wa zenryoku wo komete saigo no shunkan made tatakaimashita.","zh":""},{"ja":"彼女は悲しみを込めて友達へ別れの言葉を伝えました。","en":"She conveyed her farewell words to her friend with sadness.","romaji":"Kanojo wa kanashimi wo komete tomodachi e wakare no kotoba wo tsutaemashita.","zh":""}]',replace('**Short**: To express that something is done with a certain feeling, intention, or emotion.\n\n**Formation**: Feeling/emotion/intention Noun + を + 込めて + Verb\n\n**Long**: The ～を込めて grammar point is used to express that an action is done with a certain feeling, intention or emotion. It can be translated as ''with'' or ''filled with'' in English. ～を込めて is typically used with feelings or emotions that the speaker wishes to convey through their actions.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wo_tsuujite','～を通じて',NULL,NULL,'N2','[]','[{"ja":"インターネットを通じて友達と連絡を取ります。","en":"I keep in touch with my friends through the internet.","romaji":"Intaanetto wo tsuujite tomodachi to renraku wo torimasu.","zh":""},{"ja":"彼は一日を通じて熱心に働いています。","en":"He works diligently throughout the day.","romaji":"Kare wa ichinichi wo tsuujite nesshin ni hataraite imasu.","zh":""},{"ja":"このイベントは週末を通じて開催されます。","en":"This event will take place throughout the weekend.","romaji":"Kono ibento wa shuumatsu wo tsuujite kaisai saremasu.","zh":""},{"ja":"その花は春を通じて咲いています。","en":"The flowers bloom throughout the spring.","romaji":"Sono hana wa haru wo tsuujite saiteimasu.","zh":""}]',replace('**Short**: Expresses ''through'', ''throughout'', or ''during''.\n\n**Formation**: Noun + を通じて\n\n**Long**: The ～を通じて grammar point is used to express actions or conditions that occur through or throughout a specific period, medium, or method. It can be translated as ''through'', ''throughout'', or ''during'' in English. It is formed by attaching ''を通じて'' to a noun that represents time, place, or method.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wo_tayori_ni','～を頼りに',NULL,NULL,'N2','[]','[{"ja":"彼女は地図を頼りに旅行をしている。","en":"She is traveling relying on a map.","romaji":"Kanojo wa chizu wo tayori ni ryokou wo shite iru.","zh":""},{"ja":"多くの人が彼の力を頼りに生活している。","en":"Many people are living depending on his strength.","romaji":"Ooku no hito ga kare no chikara wo tayori ni seikatsu shite iru.","zh":""},{"ja":"このプロジェクトでは、君のスキルを頼りにしています。","en":"In this project, we are counting on your skills.","romaji":"Kono purojekuto de wa, kimi no sukiru wo tayori ni shiteimasu.","zh":""},{"ja":"彼は友達の助けを頼りに問題を解決しようとした。","en":"He tried to solve the problem relying on his friend''s help.","romaji":"Kare wa tomodachi no tasuke wo tayori ni mondai wo kaiketsu shiyou to shita.","zh":""}]',replace('**Short**: To rely on or depend on something or someone.\n\n**Formation**: Noun + を頼りに\n\n**Long**: The ～を頼りに grammar point is used to express that someone is relying on or depending on something or someone. It can be translated as ''to rely on'', ''to depend on'', or ''counting on'' in English. This phrase is used with nouns (people or objects) that act as a source of support or help.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ippou','～一方',NULL,NULL,'N2','[]','[{"ja":"技術が進化する一方、生活が忙しくなっている。","en":"While technology advances, life is getting busier.","romaji":"Gijutsu ga shinka suru ippou, seikatsu ga isogashiku natte iru.","zh":""},{"ja":"日本語が上達する一方、英語力が下がっている気がする。","en":"While my Japanese improves, I feel like my English ability is declining.","romaji":"Nihongo ga joutatsu suru ippou, eigo-ryoku ga sagatte iru ki ga suru.","zh":""},{"ja":"この料理は美味しい一方、ちょっと高いです。","en":"While this dish is delicious, it’s a bit expensive.","romaji":"Kono ryouri wa oishii ippou, chotto takai desu.","zh":""},{"ja":"彼は優しい一方、厳しい面もある。","en":"While he is kind, he also has a strict side.","romaji":"Kare wa yasashii ippou, kibishii men mo aru.","zh":""}]',replace('**Short**: Indicates that while one action or situation is happening, another action or situation is also occurring or is in contrast.\n\n**Formation**: Verb-casual + 一方(で), い-Adjective + 一方(で), な-Adjective + な/である一方(で), Noun + である一方(で)\n\n**Long**: The ～一方 grammar point is used to express that while one action or situation is taking place, another is occurring at the same time or in contrast. The clauses connected by 一方 often show simultaneous actions, opposing characteristics, or parallel developments.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ippou_da','～一方だ',NULL,NULL,'N2','[]','[{"ja":"世界の人口は増える一方だ。","en":"The world''s population continues to increase.","romaji":"Sekai no jinkou wa fueru ippou da.","zh":""},{"ja":"この町の治安は悪化する一方だ。","en":"Public safety in this town is getting worse and worse.","romaji":"Kono machi no chian wa akka suru ippou da.","zh":""},{"ja":"僕の日本語は上達する一方だ。","en":"My Japanese keeps improving.","romaji":"Boku no nihongo wa joutatsu suru ippou da.","zh":""},{"ja":"夏になると、暑さが厳しくなる一方だ。","en":"As summer arrives, it just keeps getting hotter.","romaji":"Natsu ni naru to, atsusa ga kibishiku naru ippou da.","zh":""}]',replace('**Short**: Expresses that a situation or condition is continuing to increase or decrease in one direction.\n\n**Formation**: Verb-dictionary form + 一方だ\n\n**Long**: The ～一方だ grammar point is used when something is trending in a single direction over time, often increasing or worsening. It emphasizes that the tendency keeps going in one direction.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ue_de','～上で',NULL,NULL,'N2','[]','[{"ja":"調査を行った上で、結論を出しましょう。","en":"Let''s draw a conclusion after conducting the investigation.","romaji":"Chousa wo okonatta ue de, ketsuron wo dashimashou.","zh":""},{"ja":"就職活動を終えた上で、進学するかどうか決めます。","en":"I will decide whether to continue my studies after finishing my job hunting.","romaji":"Shuushoku katsudou wo oeta ue de, shingaku suru ka dou ka kimemasu.","zh":""},{"ja":"試着した上で、この服を買うかどうか考えます。","en":"I''ll think about whether to buy these clothes after trying them on.","romaji":"Shichaku shita ue de, kono fuku wo kau ka dou ka kangaemasu.","zh":""},{"ja":"経験者の意見を聞いた上で、プロジェクトの方向性を決定しましょう。","en":"Let''s decide the direction of the project after listening to those with experience.","romaji":"Keiken sha no iken wo kiita ue de, purojekuto no houkousei wo kettei shimashou.","zh":""}]',replace('**Short**: Used to express that something is done after or on the basis of something else; ''after'', ''upon''.\n\n**Formation**: Verb-ますstem + 上で, Noun + の上で\n\n**Long**: The ～上で grammar point is used to indicate that an action or decision is made after another action or condition, or based on certain information. It can be translated as ''after doing something'' or ''on the basis of...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ue_ni','～上に',NULL,NULL,'N2','[]','[{"ja":"彼は頭がいい上に、スポーツも得意です。","en":"In addition to being smart, he is also good at sports.","romaji":"Kare wa atama ga ii ue ni, supo-tsu mo tokui desu.","zh":""},{"ja":"このドレスは美しい上に、値段も安いです。","en":"This dress is not only beautiful but also affordable.","romaji":"Kono doresu wa utsukushii ue ni, nedan mo yasui desu.","zh":""},{"ja":"彼女は優しい上に、料理も上手です。","en":"Besides being kind, she is also good at cooking.","romaji":"Kanojo wa yasashii ue ni, ryouri mo jouzu desu.","zh":""},{"ja":"彼は社長の上に、有名な作家でもある。","en":"Not only is he a company president, but he is also a famous writer.","romaji":"Kare wa shachou no ue ni, yuumei na sakka demo aru.","zh":""}]',replace('**Short**: Express ''in addition to'', ''besides'', ''not only... but also''.\n\n**Formation**: Verb-plain + 上に, い-Adjective + 上に, な-Adjective + な上に, Noun + の上に\n\n**Long**: The ～上に grammar point is used to indicate that there is an additional piece of information or situation besides the first one. It can be translated as ''in addition to'', ''besides'', or ''not only... but also''. It can be used with verbs, い-adjectives, な-adjectives, and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ue_wa','～上は',NULL,NULL,'N2','[]','[{"ja":"試験に合格した上は、パーティーを開こう。","en":"Now that I''ve passed the exam, let''s have a party.","romaji":"Shiken ni goukaku shita ue wa, paatii wo hirakou.","zh":""},{"ja":"この仕事を引き受けた上は、最後までやり遂げるつもりだ。","en":"Now that I have taken on this job, I intend to see it through to the end.","romaji":"Kono shigoto wo hikiuketa ue wa, saigo made yaritogeru tsumori da.","zh":""},{"ja":"親切だと言われた上は、手伝ってあげよう。","en":"Since you said I''m kind, I''ll help you out.","romaji":"Shinsetsu da to iwareta ue wa, tetsudatte ageyou.","zh":""},{"ja":"甘いものが好きな上は、このデザートをきっと気に入るでしょう。","en":"Now that you like sweets, you''ll surely enjoy this dessert.","romaji":"Amai mono ga suki na ue wa, kono dezaato wo kitto ki ni iru deshou.","zh":""}]',replace('**Short**: Expresses ''now that'', ''since'', or ''once''.\n\n**Formation**: Verb-casual + 上は, い-Adjective + 上は, な-Adjective + な上は, Noun + の上は\n\n**Long**: The ～上は grammar point is used to express that since a certain condition or situation exists, a certain action or result follows. It can be translated as ''now that'', ''since'', or ''once'' in English. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ijou','～以上',NULL,NULL,'N2','[]','[{"ja":"彼は忙しい以上、手伝いに行っても無駄だろう。","en":"Since he''s busy, it would be pointless to try helping him.","romaji":"Kare wa isogashii ijou, tetsudai ni itte mo muda darou.","zh":""},{"ja":"約束した以上、守るべきだ。","en":"Since I made a promise, I should keep it.","romaji":"Yakusoku shita ijou, mamoru beki da.","zh":""},{"ja":"締め切りが近い以上、全力で仕事をしなければならない。","en":"As long as the deadline is near, I have to work with all my might.","romaji":"Shimekiri ga chikai ijou, zenryoku de shigoto wo shinakereba naranai.","zh":""},{"ja":"彼女は大学生である以上、勉強が優先されるべきだ。","en":"Since she''s a college student, studying should be her priority.","romaji":"Kanojo wa daigakusei de aru ijou, benkyou ga yuusen sareru beki da.","zh":""}]',replace('**Short**: Expresses ''since'' or ''as long as'' in a conditional context.\n\n**Formation**: Verb-casual + 以上, い-Adjective + 以上, な-Adjective + な以上, Noun + の以上\n\n**Long**: The ～以上 grammar point is used to express a condition or requirement, and it can be translated as ''since'', ''as long as'', or ''if''. It often emphasizes that if a certain condition is met, a certain action or consequence will follow.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_irai','～以来',NULL,NULL,'N2','[]','[{"ja":"卒業以来、彼女に会っていない。","en":"I haven''t seen her since we graduated.","romaji":"Sotsugyou irai, kanojo ni atte inai.","zh":""},{"ja":"子供が生まれて以来、忙しくなった。","en":"I''ve been busy ever since my child was born.","romaji":"Kodomo ga umarete irai, isogashiku natta.","zh":""},{"ja":"東京に引っ越して以来、友達が増えた。","en":"I''ve made more friends since I moved to Tokyo.","romaji":"Toukyou ni hikkoshite irai, tomodachi ga fueta.","zh":""},{"ja":"あの映画を見た以来、彼女は怖がりになった。","en":"She''s been easily frightened ever since she watched that movie.","romaji":"Ano eiga wo mita irai, kanojo wa kowagari ni natta.","zh":""}]',replace('**Short**: Indicates something happening ''since'', ''ever since'', or ''after'' a particular time.\n\n**Formation**: Verb-past + 以来, い-Adjective + 以来, Noun + 以来\n\n**Long**: The ～以来 grammar point is used to express a period of time that has continued uninterrupted since a certain point in the past. It can be translated as ''since'', ''ever since'', or ''after''. The formation differs depending on whether it is used with a verb, an adjective, or a noun.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kiru','～切る',NULL,NULL,'N2','[]','[{"ja":"彼は試験勉強をがんばり切るつもりだ。","en":"He intends to give his absolute all to exam study.","romaji":"Kare wa shiken benkyou o ganbari kiru tsumori da.","zh":""},{"ja":"この仕事を終わり切るまで、帰らないでください。","en":"Please don''t go home until you''ve completely finished this job.","romaji":"Kono shigoto o owari kiru made, kaeranai de kudasai.","zh":""},{"ja":"友達と喧嘩して、何も言い切れなかった。","en":"I argued with my friend and couldn''t say everything I wanted to say.","romaji":"Tomodachi to kenka shite, nanimo iikirenakatta.","zh":""},{"ja":"彼らは、そのゲームをやり切ることができました。","en":"They were able to complete that game thoroughly.","romaji":"Karera wa, sono geemu o yarikiru koto ga dekimashita.","zh":""}]',replace('**Short**: To do something completely or thoroughly.\n\n**Formation**: Verb-stem + 切る\n\n**Long**: The ～切る grammar point is added to the verb stem (masu-form) to express doing something completely or thoroughly, often implying a strong sense of finishing or using up everything.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_hanmen','～反面',NULL,NULL,'N2','[]','[{"ja":"この車は速い反面、燃費が悪いです。","en":"On the one hand, this car is fast, but on the other hand, it has poor fuel efficiency.","romaji":"Kono kuruma wa hayai hanmen, nenpi ga warui desu.","zh":""},{"ja":"彼は頭がいい反面、運動が苦手です。","en":"On the one hand, he is smart, but on the other hand, he''s not good at sports.","romaji":"Kare wa atama ga ii hanmen, undou ga nigate desu.","zh":""},{"ja":"彼女は親切である反面、面倒見が良すぎることがある。","en":"On the one hand, she is kind, but on the other hand, she can be too helpful.","romaji":"Kanojo wa shinsetsu de aru hanmen, mendoumi ga yoi sugiru koto ga aru.","zh":""},{"ja":"この仕事は給料が高い反面、ストレスがたくさんあります。","en":"On the one hand, this job pays well, but on the other hand, it''s quite stressful.","romaji":"Kono shigoto wa kyuuryou ga takai hanmen, sutoresu ga takusan arimasu.","zh":""}]',replace('**Short**: Express contrast between two aspects; ''on the one hand'', ''on the other hand''.\n\n**Formation**: Verb-casual + 反面, い-Adjective + 反面, な-Adjective + である反面, Noun + である反面\n\n**Long**: The ～反面 grammar point is used to show a contrast between two aspects of something. It can be translated as ''on the one hand'' or ''on the other hand''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_muke','～向け',NULL,NULL,'N2','[]','[{"ja":"この雑誌は若者向けです。","en":"This magazine is aimed at young people.","romaji":"Kono zasshi wa wakamono-muke desu.","zh":""},{"ja":"スーパーで家族向けの食品セットが売っています。","en":"The supermarket sells food sets intended for families.","romaji":"Suupaa de kazoku-muke no shokuhin setto ga utte imasu.","zh":""},{"ja":"このアプリは初心者向けに作られています。","en":"This application is designed for beginners.","romaji":"Kono apuri wa shoshinsha-muke ni tsukurarete imasu.","zh":""},{"ja":"このレストランはビーガン向けのメニューが充実しています。","en":"This restaurant has an extensive menu aimed at vegans.","romaji":"Kono resutoran wa bi-gan-muke no menyu ga juujitsu shite imasu.","zh":""}]',replace('**Short**: Indicating target or intended audience.\n\n**Formation**: Noun + 向け\n\n**Long**: The ～向け grammar point is used to indicate the target or intended audience for a product, service, or event. It can be translated as ''for'', ''aimed at'', or ''intended for''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_osore_ga_aru','～恐れがある',NULL,NULL,'N2','[]','[{"ja":"地震が来る恐れがあるため、避難所に行ってください。","en":"Please go to the evacuation center because there is a risk of an earthquake.","romaji":"Jishin ga kuru osore ga aru tame, hinanjo ni itte kudasai.","zh":""},{"ja":"彼は事故に遭う恐れがあるので、注意して運転してください。","en":"There''s a possibility he might have an accident, so please drive carefully.","romaji":"Kare wa jiko ni au osore ga aru node, chuui shite unten shite kudasai.","zh":""},{"ja":"この薬を飲みすぎると、副作用の恐れがある。","en":"If you take too much of this medicine, there is a risk of side effects.","romaji":"Kono kusuri wo nomisugiru to, fukusayou no osore ga aru.","zh":""},{"ja":"低い予算でこのプロジェクトを進めると、品質が低くなる恐れがある。","en":"If we proceed with this project on a low budget, the quality may suffer.","romaji":"Hikui yosan de kono purojekuto wo susumeru to, hinshitsu ga hikuku naru osore ga aru.","zh":""}]',replace('**Short**: Express a concern or fear that something undesirable might occur.\n\n**Formation**: Verb-dictionary form + 恐れがある\n\n**Long**: The ～恐れがある grammar point indicates that there is a concern or fear that something undesirable or negative might happen. It is often used for potential problems or risks, and can be translated as ''there is a risk'' or ''there is a possibility''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ori_ni_wa','～折には',NULL,NULL,'N2','[]','[{"ja":"喉が渇く折には、このペットボトルの水を飲んでください。","en":"When you get thirsty, please drink water from this bottle.","romaji":"Nodo ga kawaku ori ni wa, kono pettobotoru no mizu o nonde kudasai.","zh":""},{"ja":"この地域に来る折には、この神社に必ずお参りしましょう。","en":"When you visit this area, make sure to go to this shrine.","romaji":"Kono chiiki ni kuru ori ni wa, kono jinja ni kanarazu omairi shimashou.","zh":""},{"ja":"彼が元気じゃない折には、具合が悪いか尋ねてください。","en":"If he doesn''t seem well, please ask if he''s feeling sick.","romaji":"Kare ga genki ja nai ori ni wa, guai ga warui ka tazunete kudasai.","zh":""},{"ja":"チャンスがある折には、躊躇せずに行動しましょう。","en":"When you have an opportunity, act without hesitation.","romaji":"Chansu ga aru ori ni wa, chuucho sezu ni koudou shimashou.","zh":""}]',replace('**Short**: Expresses ''when'' or ''in case of'' specific situations or timings.\n\n**Formation**: Verb-dictionary form + 折には, Verb-た form + 折には, い-Adjective + 折には, な-Adjective + な折には, Noun + の折には\n\n**Long**: The ～折には grammar point is used to emphasize a specific moment or situation (often not very frequent). It can be translated as ''when (the occasion arises)'' or ''in case of''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sue','～末',NULL,NULL,'N2','[]','[{"ja":"長い議論の末、ようやく意見がまとまった。","en":"After a long discussion, we finally reached a consensus.","romaji":"Nagai giron no sue, youyaku iken ga matomatta.","zh":""},{"ja":"一週間の勉強の末、試験に合格した。","en":"After a week of studying, I passed the exam.","romaji":"Isshuukan no benkyou no sue, shiken ni goukaku shita.","zh":""},{"ja":"何度も失敗の末、成功を手に入れた。","en":"After many failures, I finally achieved success.","romaji":"Nando mo shippai no sue, seikou wo te ni ireta.","zh":""},{"ja":"彼との別れの末、新しい人生を始めた。","en":"After breaking up with him, I started a new life.","romaji":"Kare to no wakare no sue, atarashii jinsei wo hajimeta.","zh":""}]',replace('**Short**: Express the outcome after a period of time or series of actions; ''after'', ''as a result of''.\n\n**Formation**: Noun + 末\n\n**Long**: The ～末 grammar point is used to indicate an outcome or result after a period of time, effort, or a series of actions. It can be translated as ''after'', ''as a result of'', or ''following''. It is typically used with nouns (e.g., ''相談の末'', ''努力の末'').\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_shidai','～次第',NULL,NULL,'N2','[]','[{"ja":"仕事が終わり次第、帰ります。","en":"I will go home as soon as I finish work.","romaji":"Shigoto ga owari shidai, kaerimasu.","zh":""},{"ja":"お客様のご意見次第で、サービスを改善します。","en":"We will improve our services depending on customer feedback.","romaji":"Okyakusama no goiken shidai de, saabisu wo kaizen shimasu.","zh":""},{"ja":"彼の返事次第で、パーティーに行くかどうか決めます。","en":"I will decide whether or not to go to the party depending on his answer.","romaji":"Kare no henji shidai de, paatii ni iku ka dou ka kimemasu.","zh":""},{"ja":"天気次第で、ピクニックを予定しています。","en":"We are planning a picnic depending on the weather.","romaji":"Tenki shidai de, pikunikku wo yotei shite imasu.","zh":""}]',replace('**Short**: Expresses ''as soon as'' (when used with Verb-ますstem) or ''depending on'' (when used with a noun).\n\n**Formation**: Verb-ますstem + 次第, Noun + 次第\n\n**Long**: The grammar pattern ～次第 can mean ''as soon as'' when used with a verb in its ます-stem, and ''depending on'' when used with a noun. For instance, 仕事が終わり次第 (as soon as work finishes) or 天気次第 (depending on the weather).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_shidai_de','～次第で',NULL,NULL,'N2','[]','[{"ja":"仕事の終わり次第で、家に帰る時間が変わります。","en":"Depending on when I finish work, the time I go home may change.","romaji":"Shigoto no owari shidai de, ie ni kaeru jikan ga kawarimasu.","zh":""},{"ja":"天気次第で、ピクニックに行く予定です。","en":"We plan to go on a picnic depending on the weather.","romaji":"Tenki shidai de, pikunikku ni iku yotei desu.","zh":""},{"ja":"彼の気分次第で、パーティーに参加するかどうか決まります。","en":"Whether he participates in the party depends on his mood.","romaji":"Kare no kibun shidai de, paatii ni sanka suru ka dou ka kimarimasu.","zh":""},{"ja":"会議の進行次第で、決定が変わるかもしれません。","en":"The decision may change depending on how the meeting progresses.","romaji":"Kaigi no shinkou shidai de, kettei ga kawaru kamoshiremasen.","zh":""}]',replace('**Short**: Indicates ''depending on; based on'' a certain factor or situation.\n\n**Formation**: Noun + 次第で\n\n**Long**: The ～次第で pattern typically follows a noun to show that something is decided or changes ''depending on'' that factor. It can be translated as ''based on...'' or ''depending on...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_shidai_desu','～次第です',NULL,NULL,'N2','[]','[{"ja":"天気次第ですが、明日はピクニックに行こうと思います。","en":"It depends on the weather, but I’m thinking of going for a picnic tomorrow.","romaji":"Tenki shidai desu ga, ashita wa pikunikku ni ikou to omoimasu.","zh":""},{"ja":"試験の結果次第ですが、留学したいと考えています。","en":"It depends on my exam results, but I''m considering studying abroad.","romaji":"Shiken no kekka shidai desu ga, ryuugaku shitai to kangaete imasu.","zh":""},{"ja":"お客様のご意見次第で新メニューを追加する次第です。","en":"We intend to add a new menu item depending on our customers’ feedback.","romaji":"Okyakusama no goiken shidai de shin menyuu wo tsuika suru shidai desu.","zh":""},{"ja":"申請が完了次第ですので、手続きが終わったらパスポートを受け取れます。","en":"As soon as the application is completed, you''ll be able to receive your passport.","romaji":"Shinsei ga kanryou shidai desu no de, tetsudzuki ga owattara pasupooto wo uketoremasu.","zh":""}]',replace('**Short**: A polite/formal way to say ''it depends on...'' or ''as soon as...'', often used in concluding statements.\n\n**Formation**: Verb-ますstem + 次第です (or Noun + 次第です)\n\n**Long**: 「～次第です」 is frequently used in more formal contexts, either to mean that something depends on certain conditions or to indicate an action will happen as soon as something else is completed. It’s also used as a set phrase to conclude an explanation in writing.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_gimi','～気味',NULL,NULL,'N2','[]','[{"ja":"最近寝不足気味で、ちょっと疲れています。","en":"Lately, I''m feeling somewhat sleep-deprived and a bit tired.","romaji":"Saikin nebusoku gimi de, chotto tsukarete imasu.","zh":""},{"ja":"この部屋は暗い気味だから、もっと明るい照明をつけよう。","en":"This room is a bit dark, so let''s install brighter lighting.","romaji":"Kono heya wa kurai gimi dakara, motto akarui shoumei wo tsukeyou.","zh":""},{"ja":"彼女は緊張気味で話していました。","en":"She was speaking somewhat nervously.","romaji":"Kanojo wa kinchou gimi de hanashite imashita.","zh":""},{"ja":"彼の声は風邪気味だったね。","en":"His voice sounded like he might have a slight cold.","romaji":"Kare no koe wa kaze gimi datta ne.","zh":""}]',replace('**Short**: Indicates a slight feeling or tendency toward a particular state.\n\n**Formation**: Noun + 気味 (e.g., 風邪気味, 寝不足気味, 緊張気味)\n\n**Long**: The suffix ～気味 generally attaches to nouns (or nominalized words) to express a slight feeling, tendency, or inclination toward a particular state. It often translates to ''-ish'' or ''a bit'' in English (e.g., ''sleep-deprived-ish'', ''nervous-ish'').\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kagiri','～限り',NULL,NULL,'N2','[]','[{"ja":"元気な限り、運動し続けます。","en":"As long as I''m healthy, I''ll keep exercising.","romaji":"Genki na kagiri, undou shi tsuzukemasu.","zh":""},{"ja":"お金がある限り、旅行を楽しみたい。","en":"As long as I have money, I''d like to travel.","romaji":"Okane ga aru kagiri, ryokou o tanoshimitai.","zh":""},{"ja":"彼が話し続ける限り、このプロジェクトのメリットが伝わるでしょう。","en":"As long as he keeps talking about it, the benefits of this project will be conveyed.","romaji":"Kare ga hanashi tsudzukeru kagiri, kono purojekuto no meritto ga tsutawaru deshou.","zh":""},{"ja":"勉強する限り、試験に合格できる可能性が高まります。","en":"As long as you study, you''ll have a higher chance of passing the exam.","romaji":"Benkyou suru kagiri, shiken ni goukaku dekiru kanousei ga takamarimasu.","zh":""}]',replace('**Short**: Expresses ''as long as'', ''while'', or ''to the extent that'' a certain condition holds true.\n\n**Formation**: Verb-casual + 限り, い-Adjective + 限り, な-Adjective + な限り, Noun + の限り\n\n**Long**: The phrase ～限り is used to indicate that something continues or is true ''as long as'' or ''while'' a certain condition is met. It can also mean ''to the extent that''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sai_ni','～際に',NULL,NULL,'N2','[]','[{"ja":"出発の際に、パスポートを忘れないでください。","en":"When departing, please don''t forget your passport.","romaji":"Shuppatsu no sai ni, pasupooto wo wasurenai de kudasai.","zh":""},{"ja":"地震が起こる際に、すぐに避難してください。","en":"When an earthquake occurs, please evacuate immediately.","romaji":"Jishin ga okoru sai ni, sugu ni hinan shite kudasai.","zh":""},{"ja":"日本へ来る際に、お土産をたくさん買うつもりです。","en":"When I come to Japan, I plan to buy lots of souvenirs.","romaji":"Nihon e kuru sai ni, omiyage wo takusan kau tsumori desu.","zh":""},{"ja":"面接の際に、スーツを着用してください。","en":"Please wear a suit when attending the interview.","romaji":"Mensetsu no sai ni, suutsu wo chakuyou shite kudasai.","zh":""}]',replace('**Short**: Means ''when'', ''while'', or ''on the occasion of'' a certain event or situation.\n\n**Formation**: Verb-casual + 際に, い-Adjective + 際に, な-Adjective + な際に, Noun + の際に\n\n**Long**: ～際に is used to specify a time or occasion when something happens. It’s more formal than a simple ''とき'' and often appears in announcements or polite instructions.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_uga_b_uga','A うが B うが',NULL,NULL,'N1','[]','[{"ja":"朝早かろうが夜遅かろうが、いつもバスが遅れる。","en":"No matter whether it''s early morning or late at night, the bus is always late.","romaji":"Asa hayakarou ga yoru osokarou ga, itsumo basu ga okureru.","zh":""},{"ja":"彼に話そうが話すまいが、結果は変わらない。","en":"Even if I talk to him or don''t, the outcome won''t change.","romaji":"Kare ni hanasou ga hanasu maiga, kekka wa kawaranai.","zh":""},{"ja":"この仕事をしようがしまいが、給料は同じだ。","en":"Whether I do this job or not, the salary is the same.","romaji":"Kono shigoto o shiyou ga shimai ga, kyuuryou wa onaji da.","zh":""},{"ja":"あの人に話そうが話すまいが、理解してくれるとは思えない。","en":"I don''t think that person would understand whether I talk to them or not.","romaji":"Ano hito ni hanasou ga hanasu maiga, rikai shite kureru to wa omoenai.","zh":""}]',replace('**Short**: Expresses the idea of ''no matter how... or'', ''even if... or''.\n\n**Formation**: Verb-volitional form + うが + Verb-volitional form + うが, or Adjective (-かろう) + が + Adjective (-かろう) + が\n\n**Long**: The ～うが ～うが grammar pattern is used to express that regardless of the conditions in A and B, the result remains the same. Often you’ll see volitional forms or i-adjective ''-かろうが'' forms. It can be translated as ''no matter how... or...'', ''even if... or...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_uto_b_uto','A うと B うと',NULL,NULL,'N1','[]','[{"ja":"雨が降ろうと晴れようと、私は毎日ジョギングをします。","en":"Whether it''s raining or sunny, I jog every day.","romaji":"Ame ga furou to hareyou to, watashi wa mainichi jogingu o shimasu.","zh":""},{"ja":"試験が難しかろうと易しかろうと、一生懸命勉強します。","en":"Whether the exam is difficult or easy, I will study hard.","romaji":"Shiken ga muzukashikarou to yasashikarou to, isshoukenmei benkyou shimasu.","zh":""},{"ja":"彼が学生であろうと社会人であろうと、私は彼を尊敬しています。","en":"Whether he''s a student or a working adult, I respect him.","romaji":"Kare ga gakusei de arou to shakaijin de arou to, watashi wa kare o sonkei shiteimasu.","zh":""},{"ja":"その映画が新しいであろうと古いであろうと、面白ければ観ます。","en":"Whether the movie is new or old, if it''s interesting, I''ll watch it.","romaji":"Sono eiga ga atarashii de arou to furui de arou to, omoshirokereba mimasu.","zh":""}]',replace('**Short**: Shows that the speaker is indifferent to both conditions; ''whether A or B''.\n\n**Formation**: い-adjective (-かろう) + と, な-adjective / Noun + であろうと\n\n**Long**: The うと うと pattern indicates that A and B are both possibilities, yet the speaker''s stance or the outcome doesn’t change. It''s often translated as ''whether A or B''. For i-adjectives, the ''-かろうと'' form is used. For nouns or な-adjectives, you’ll see ''Noun/な-adjective + であろうと''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_katawara_b','A かたわら B',NULL,NULL,'N1','[]','[{"ja":"彼は仕事をするかたわら、大学に通っている。","en":"While working, he also attends university.","romaji":"Kare wa shigoto o suru katawara, daigaku ni kayotte iru.","zh":""},{"ja":"私は学生のかたわら、レストランでアルバイトをしている。","en":"While being a student, I work part-time at a restaurant.","romaji":"Watashi wa gakusei no katawara, resutoran de arubaito o shite iru.","zh":""},{"ja":"彼女は医者のかたわら、趣味で絵を描いている。","en":"While being a doctor, she paints as a hobby.","romaji":"Kanojo wa isha no katawara, shumi de e o kaite iru.","zh":""},{"ja":"彼は仕事をするかたわら、ボランティア活動にも積極的に参加している。","en":"While doing his job, he also actively participates in volunteer work.","romaji":"Kare wa shigoto o suru katawara, borantia katsudou ni mo sekkyokuteki ni sanka shite iru.","zh":""}]',replace('**Short**: Expresses ''while also'', ''at the same time as''.\n\n**Formation**: Verb-dictionary form + かたわら, Noun + のかたわら\n\n**Long**: The ～かたわら grammar point is used when someone is doing B while also doing A. It often implies that both tasks require considerable commitment or skill. It can be translated as ''while also'' or ''at the same time as''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_kare_b_kare','A かれ B かれ',NULL,NULL,'N1','[]','[{"ja":"冬かれ夏かれ、毎日ジョギングする。","en":"Whether it''s winter or summer, I jog every day.","romaji":"Fuyu kare natsu kare, mainichi jogingu suru.","zh":""},{"ja":"彼が来るかれ来ないかれ、パーティーは始める。","en":"Whether he comes or not, the party will start.","romaji":"Kare ga kuru kare konai kare, paatii wa hajimeru.","zh":""},{"ja":"勝つかれ負けるかれ、試合に出ることが大事だ。","en":"Whether we win or lose, it''s important to take part in the match.","romaji":"Katsu kare makeru kare, shiai ni deru koto ga daiji da.","zh":""},{"ja":"雨かれ雪かれ、犬の散歩は欠かさない。","en":"Whether it''s raining or snowing, I never skip walking the dog.","romaji":"Ame kare yuki kare, inu no sanpo wa kakasanai.","zh":""}]',replace('**Short**: Expresses ''whether A or B''; both situations are included.\n\n**Formation**: Commonly i-adjective stems + かれ + i-adjective stems + かれ (e.g. 早かれ遅かれ). Also sometimes Noun + かれ + Noun + かれ in older usage.\n\n**Long**: The grammar point ～AかれBかれ is a somewhat literary/old-fashioned pattern often seen with i-adjectives (e.g., 早かれ遅かれ). It can mean ''whether A or B''. Here it''s shown with nouns or verbs, which is also possible in older or set expressions.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_dano_b_dano','A だの B だの',NULL,NULL,'N1','[]','[{"ja":"彼はいつも遅刻だの、仕事を忘れるだので困る。","en":"I''m troubled because he''s always late, forgets work, and so on.","romaji":"Kare wa itsumo chikoku dano, shigoto o wasureru dano de komaru.","zh":""},{"ja":"彼女は新しい服だの、化粧品だのによくお金を使います。","en":"She often spends money on new clothes, cosmetics, and so on.","romaji":"Kanojo wa atarashii fuku dano, keshouhin dano ni yoku okane o tsukaimasu.","zh":""},{"ja":"彼が言うには、音楽だの映画だの本だのが好きらしい。","en":"He says he likes music, movies, books, and so on.","romaji":"Kare ga iu ni wa, ongaku dano, eiga dano, hon dano ga suki rashii.","zh":""},{"ja":"子供にはお菓子だの、おもちゃだの、好きなものを限りなく与えてあげたい。","en":"I want to give children all the things they like, such as sweets and toys, without limit.","romaji":"Kodomo ni wa okashi dano, omocha dano, suki na mono o kagirinaku ataete agetai.","zh":""}]',replace('**Short**: Used to list examples (often with a critical or complaining tone); ''things like A, B, etc.''.\n\n**Formation**: Noun/Verb casual + だの + Noun/Verb casual + だの\n\n**Long**: The ～だの～だの grammar point is used to list examples, typically in a casual or complaining tone. It can be translated as ''things like... and so on''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_deare_b_deare','A であれ B であれ',NULL,NULL,'N1','[]','[{"ja":"雨であれ雪であれ、試合は中止にならない。","en":"Whether it''s rain or snow, the match will not be canceled.","romaji":"Ame deare yuki deare, shiai wa chuushi ni naranai.","zh":""},{"ja":"男であれ女であれ、平等に扱われるべきだ。","en":"Whether man or woman, everyone should be treated equally.","romaji":"Otoko deare onna deare, byoudou ni atsukawareru beki da.","zh":""},{"ja":"豊かであれ貧乏であれ、真の幸福は金では買えない。","en":"Whether rich or poor, true happiness can''t be bought with money.","romaji":"Yutaka deare binbou deare, shin no shiawase wa kane de wa kaenai.","zh":""},{"ja":"経験者であれ初心者であれ、このゲームは楽しめる。","en":"Whether you''re a veteran or a beginner, you can enjoy this game.","romaji":"Keikensha deare shoshinsha deare, kono geemu wa tanoshimeru.","zh":""}]',replace('**Short**: Indicates the same statement applies to both A and B; ''whether A or B''.\n\n**Formation**: Noun A + であれ + Noun B + であれ\n\n**Long**: The grammar point A であれ B であれ is used to say a statement applies equally whether it''s A or B. Often the nouns/conditions are contrasting pairs, and it''s translated as ''whether A or B''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_to_iu_ka_b_to_iu_ka','A というか B というか',NULL,NULL,'N1','[]','[{"ja":"彼は無礼というか、直接的というか、とにかくはっきりしている。","en":"He''s rather rude, or maybe just direct; in any case, he is very blunt.","romaji":"Kare wa burei to iu ka, chokusetsuteki to iu ka, tonikaku hakkiri shite iru.","zh":""},{"ja":"この映画は面白いというか、変というか、とにかく不思議な雰囲気がある。","en":"This movie is interesting or maybe strange; anyway, it has a mysterious vibe.","romaji":"Kono eiga wa omoshiroi to iu ka, hen to iu ka, tonikaku fushigi na fun''iki ga aru.","zh":""},{"ja":"彼の絵は素晴らしいというか、驚くべきというか、本当に見る価値がある。","en":"His paintings are wonderful, or perhaps astonishing; they''re definitely worth seeing.","romaji":"Kare no e wa subarashii to iu ka, odoroku beki to iu ka, hontou ni miru kachi ga aru.","zh":""},{"ja":"彼女の服はかわいいというか、派手というか、とにかく人目を引く。","en":"Her outfit is cute or maybe flashy; in any case, it grabs people''s attention.","romaji":"Kanojo no fuku wa kawaii to iu ka, hade to iu ka, tonikaku hitome o hiku.","zh":""}]',replace('**Short**: Means ''rather than say A, it''s more like B'', or ''whether to call it A or B''.\n\n**Formation**: Phrase A + というか + Phrase B + というか\n\n**Long**: The grammar ''A というか B というか'' is used when the speaker isn''t sure which expression (A or B) describes the situation better. It can be translated as ''rather than A, it''s more B'' or ''should I call it A or B?''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_tomo_b_tomo','A とも B とも',NULL,NULL,'N1','[]','[{"ja":"決断とも誤りとも、結果は時間が教えてくれるでしょう。","en":"Whether it''s a wise decision or a mistake, time will show the result.","romaji":"Ketsudan tomo ayamari tomo, kekka wa jikan ga oshiete kureru deshou.","zh":""},{"ja":"彼は父とも兄とも、もう何年も話していない。","en":"He hasn''t spoken to either his father or his brother in years.","romaji":"Kare wa chichi tomo ani tomo, mou nannen mo hanashite inai.","zh":""},{"ja":"彼女とも友達とも映画を見に行くつもりです。","en":"I plan to go watch a movie either with my girlfriend or a friend.","romaji":"Kanojo tomo tomodachi tomo eiga o mi ni iku tsumori desu.","zh":""},{"ja":"このゲームには時間とも努力とも言えないほどの根気が必要です。","en":"This game requires a kind of persistence beyond just time or effort.","romaji":"Kono geemu ni wa jikan tomo doryoku tomo ienai hodo no konki ga hitsuyou desu.","zh":""}]',replace('**Short**: Expresses two possibilities; ''either A or B'', ''whether A or B''.\n\n**Formation**: Noun + とも + Noun + とも (or sometimes Verb forms for each A, B)\n\n**Long**: The ''A とも B とも'' grammar pattern indicates two possible scenarios. It can be translated as ''whether A or B'' or ''either A or B''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_nishiro_b_nishiro','A にしろ B にしろ',NULL,NULL,'N1','[]','[{"ja":"暑いにしろ寒いにしろ、毎日運動するべきです。","en":"Whether it''s hot or cold, you should exercise every day.","romaji":"Atsui ni shiro samui ni shiro, mainichi undou suru beki desu.","zh":""},{"ja":"合格するにしろ不合格になるにしろ、最善を尽くしました。","en":"Whether I pass or fail, I did my best.","romaji":"Goukaku suru ni shiro fukougaku ni naru ni shiro, saizen o tsukushimashita.","zh":""},{"ja":"忙しいにしろ暇にしろ、時間を大切にすべきです。","en":"Whether you''re busy or free, you should value your time.","romaji":"Isogashii ni shiro hima ni shiro, jikan o taisetsu ni subeki desu.","zh":""},{"ja":"大きいにしろ小さいにしろ、その箱は全部ここに運んでください。","en":"Whether they''re large or small, please move all those boxes here.","romaji":"Ookii ni shiro chiisai ni shiro, sono hako wa zenbu koko ni hakonde kudasai.","zh":""}]',replace('**Short**: Means ''whether it is A or B''; ''regardless of A or B''.\n\n**Formation**: Noun A + にしろ + Noun B + にしろ, or Verb-casual A + にしろ + Verb-casual B + にしろ\n\n**Long**: A にしろ B にしろ is used to indicate that even though A and B are different possibilities, the statement or conclusion applies regardless. Often translated as ''whether it’s A or B'' or ''regardless of A or B''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_ni_seyo_b_ni_seyo','A にせよ B にせよ',NULL,NULL,'N1','[]','[{"ja":"雨にせよ雪にせよ、試合は中止しない。","en":"Whether it''s rain or snow, the match won''t be cancelled.","romaji":"Ame ni seyo yuki ni seyo, shiai wa chuushi shinai.","zh":""},{"ja":"彼にせよ彼女にせよ、誰か一人が行くべきだ。","en":"Whether it''s him or her, someone should go.","romaji":"Kare ni seyo kanojo ni seyo, dareka hitori ga iku beki da.","zh":""},{"ja":"成果にせよ努力にせよ、どちらも重要だ。","en":"Whether it''s results or effort, both are important.","romaji":"Seika ni seyo doryoku ni seyo, dochira mo juuyou da.","zh":""},{"ja":"春にせよ秋にせよ、私は花が好きだ。","en":"Whether it''s spring or fall, I like flowers.","romaji":"Haru ni seyo aki ni seyo, watashi wa hana ga suki da.","zh":""}]',replace('**Short**: Either A or B; Regardless of whether it''s A or B.\n\n**Formation**: Noun + にせよ + Noun + にせよ (also works with verbs in dictionary form + にせよ)\n\n**Long**: The 〜にせよ 〜にせよ grammar point is used to express two possibilities A and B, indicating that regardless of whether it is A or B, the statement remains valid. It can be translated as ''whether it''s A or B.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_ni_tsuke_b_ni_tsuke','A につけ B につけ',NULL,NULL,'N1','[]','[{"ja":"彼には笑うにつけ泣くにつけ、とても魅力的だ。","en":"He is very charming whether he’s laughing or crying.","romaji":"Kare ni wa warau ni tsuke naku ni tsuke, totemo miryokuteki da.","zh":""},{"ja":"嬉しいにつけ悲しいにつけ、彼はいつも音楽を聴いている。","en":"Whether he''s happy or sad, he''s always listening to music.","romaji":"Ureshii ni tsuke kanashii ni tsuke, kare wa itsumo ongaku o kiite iru.","zh":""},{"ja":"日中につけ夜間につけ、この景色は美しい。","en":"This view is beautiful whether it''s daytime or nighttime.","romaji":"Nitchuu ni tsuke yakan ni tsuke, kono keishiki wa utsukushii.","zh":""},{"ja":"喜びにつけ悲しみにつけ、彼女はいつも私を支えてくれる。","en":"Whether I’m joyful or sorrowful, she always supports me.","romaji":"Yorokobi ni tsuke kanashimi ni tsuke, kanojo wa itsumo watashi o sasaete kureru.","zh":""}]',replace('**Short**: Expresses ''whether... or...'', ''both... and...'', ''in either case''.\n\n**Formation**: Phrase A (dictionary/adjective form) + につけ、Phrase B (dictionary/adjective form) + につけ\n\n**Long**: The ～AにつけBにつけ pattern is used to show that some state or action applies in both situation A and situation B. It often pairs contrasting or related conditions and can be translated as ''whether A or B'', ''in either case'', etc.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_no_yara_b_no_yara','A のやら B のやら',NULL,NULL,'N1','[]','[{"ja":"彼が怒っているのやら、悲しいのやら、私には分からない。","en":"I don''t know whether he''s angry or sad.","romaji":"Kare ga okotte iru no yara, kanashii no yara, watashi ni wa wakaranai.","zh":""},{"ja":"試験の結果が良いのやら悪いのやら、気になって仕方がない。","en":"I can’t help worrying whether my exam results are good or bad.","romaji":"Shiken no kekka ga yoi no yara warui no yara, ki ni natte shikata ga nai.","zh":""},{"ja":"彼女が私を好きなのやら嫌いなのやら、わからない。","en":"I don’t know whether she likes me or hates me.","romaji":"Kanojo ga watashi o suki na no yara kirai na no yara, wakaranai.","zh":""},{"ja":"彼が本当に行くのやら行かないのやら、はっきりしない。","en":"It’s unclear whether he will really go or not.","romaji":"Kare ga hontou ni iku no yara ikanai no yara, hakkiri shinai.","zh":""}]',replace('**Short**: Used when the speaker is unsure or confused between multiple possibilities.\n\n**Formation**: Noun1 + のやら + Noun2 + のやら (also works with adjectives and verbs + のやら)\n\n**Long**: The A のやら B のやら grammar expresses the speaker''s confusion or inability to decide between possibility A and B. It can be translated roughly as ''whether it''s A or B (I don''t know).''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_ga_a_nara_b_mo_b_da','Noun1 が Noun1 なら、 Noun2 も Noun2 だ',NULL,NULL,'N1','[]','[{"ja":"鬼が鬼なら、人間も人間だ。","en":"If demons are indeed demons, humans are likewise humans.","romaji":"Oni ga oni nara, ningen mo ningen da.","zh":""},{"ja":"彼が社長なら、私も社長だ。","en":"If he is the president, then I''m the president too.","romaji":"Kare ga shachou nara, watashi mo shachou da.","zh":""},{"ja":"貴様が戦士なら、俺も戦士だ。","en":"If you''re a warrior, then I''m a warrior as well.","romaji":"Kisama ga senshi nara, ore mo senshi da.","zh":""},{"ja":"ハムスターがペットなら、猫もペットだ。","en":"If a hamster counts as a pet, then a cat is also a pet.","romaji":"Hamusutā ga petto nara, neko mo petto da.","zh":""}]',replace('**Short**: Indicates a parallel or matching situation; ''if Noun1 is (truly) Noun1, then Noun2 is also Noun2''.\n\n**Formation**: Noun1 + が + (repeat Noun1) + なら、Noun2 + も + (repeat Noun2) + だ\n\n**Long**: This structure conveys a comparison: ''If Noun1 is indeed that kind of thing (Noun1), then naturally Noun2 is also that kind of thing (Noun2)''. It’s often used to show parallels or equivalences in a rhetorical way.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_mo_a_nara_b_mo_b_da','Noun1 も Noun1 なら、Noun2 も Noun2 だ',NULL,NULL,'N1','[]','[{"ja":"君も君なら、私も私だ。","en":"If you are you, then I am also me.","romaji":"Kimi mo kimi nara, watashi mo watashi da.","zh":""},{"ja":"夏も夏なら、冬も冬だ。","en":"If it’s said that summer is summer, then winter is also winter.","romaji":"Natsu mo natsu nara, fuyu mo fuyu da.","zh":""},{"ja":"東京も東京なら、大阪も大阪だ。","en":"If Tokyo is Tokyo, then Osaka is also Osaka (they each have their distinctive qualities).","romaji":"Toukyou mo toukyou nara, Oosaka mo Oosaka da.","zh":""},{"ja":"犬も犬なら、猫も猫だ。","en":"If dogs are dogs, then cats are also cats.","romaji":"Inu mo inu nara, neko mo neko da.","zh":""}]',replace('**Short**: Highlights two parallel facts or characteristics; ''if it’s said that ~, then it can also be said that ~''.\n\n**Formation**: Noun1 + も + (repeat Noun1) + なら、Noun2 + も + (repeat Noun2) + だ\n\n**Long**: This grammar point sets two items or facts side by side, emphasizing that both follow a similar logic or share a parallel characteristic. Often it can be rendered as ''If you say Noun1 is Noun1, then Noun2 is also Noun2.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_atte_no_b','Noun + あっての + Noun',NULL,NULL,'N1','[]','[{"ja":"家族あっての私です。","en":"I am who I am thanks to my family.","romaji":"Kazoku atte no watashi desu.","zh":""},{"ja":"お客様あってのビジネスです。","en":"A business is nothing without its customers.","romaji":"Okyakusama atte no bijinesu desu.","zh":""},{"ja":"練習あっての成功です。","en":"Success is nothing without practice.","romaji":"Renshuu atte no seikou desu.","zh":""},{"ja":"健康あっての仕事です。","en":"Work is nothing without your health.","romaji":"Kenkou atte no shigoto desu.","zh":""}]',replace('**Short**: Expresses ''B cannot exist without A''; ''B only exists because of A''.\n\n**Formation**: Noun1 + あっての + Noun2\n\n**Long**: The ''Noun + あっての + Noun'' pattern emphasizes that the second noun (B) exists only thanks to, or on the foundation of, the first noun (A). It''s often translated as ''B is nothing without A'' or ''B exists only because of A''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_kata_gata','Noun かたがた',NULL,NULL,'N1','[]','[{"ja":"東京へ出張のかたがた、友人に会いに行った。","en":"While on a business trip to Tokyo, I also went to see a friend.","romaji":"Toukyou e shucchou no kata gata, yuujin ni ai ni itta.","zh":""},{"ja":"観光のかたがた、お土産を買いました。","en":"While sightseeing, I bought some souvenirs.","romaji":"Kankou no kata gata, omiyage o kaimashita.","zh":""},{"ja":"散歩のかたがた、ゴミを拾った。","en":"While taking a walk, I also picked up trash.","romaji":"Sanpo no kata gata, gomi o hirotta.","zh":""},{"ja":"学習のかたがた、音楽を聞いた。","en":"While studying, I also listened to music.","romaji":"Gakushuu no kata gata, ongaku o kiita.","zh":""}]',replace('**Short**: Do one thing while also doing another; ''while'', ''and at the same time''.\n\n**Formation**: Noun + かたがた\n\n**Long**: 「Noun かたがた」 is a somewhat formal expression for doing one thing while also doing another. The first action is often the main purpose, and the second is done simultaneously or incidentally.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_gatera','Noun がてら',NULL,NULL,'N1','[]','[{"ja":"散歩がてらに、近くの公園で花を摘みました。","en":"While taking a walk, I picked some flowers in the nearby park.","romaji":"Sanpo gatera ni, chikaku no kouen de hana o tsumimashita.","zh":""},{"ja":"買い物がてら、友達に会いに行きました。","en":"While I was out shopping, I went to see a friend.","romaji":"Kaimono gatera, tomodachi ni ai ni ikimashita.","zh":""},{"ja":"彼女は旅行がてら、新しい言語を勉強しました。","en":"She studied a new language while traveling.","romaji":"Kanojo wa ryokou gatera, atarashii gengo o benkyou shimashita.","zh":""},{"ja":"ドライブがてら、新しいアルバムを聞きました。","en":"I listened to a new album while going for a drive.","romaji":"Doraibu gatera, atarashii arubamu o kikimashita.","zh":""}]',replace('**Short**: Means ''while...at the same time'', ''on the occasion of'', or ''along with''.\n\n**Formation**: Noun + がてら\n\n**Long**: The suffix ～がてら is used to show doing one activity alongside another, taking advantage of the opportunity. It can often be translated as ''while'', ''at the same time'', ''along with'', or ''on the occasion of''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kara_aru','Noun からある',NULL,NULL,'N1','[]','[{"ja":"彼のコレクションは500個からある。","en":"He has at least 500 items in his collection.","romaji":"Kare no korekushon wa gohyaku ko kara aru.","zh":""},{"ja":"このビルは40階からある。","en":"This building has at least 40 floors.","romaji":"Kono biru wa yonjuu kai kara aru.","zh":""},{"ja":"彼の財産は10億円からある。","en":"He has assets worth at least one billion yen.","romaji":"Kare no zaisan wa juu oku en kara aru.","zh":""},{"ja":"このマラソンは10kmからある。","en":"This marathon is at least 10 kilometers long.","romaji":"Kono marason wa juu kiro kara aru.","zh":""}]',replace('**Short**: Used with large numbers or measurements to emphasize ''at least that many'' or ''no less than.''\n\n**Formation**: Number + Counter + からある\n\n**Long**: 「Noun + Counter + からある」indicates a large or minimum number, emphasizing that the quantity is at least that high (often more). It conveys the idea that the figure is notably large or impressive.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_kara_suru','Noun からする',NULL,NULL,'N1','[]','[{"ja":"彼の態度からすると、彼はその計画に反対しているようだ。","en":"Judging from his attitude, he seems to be against the plan.","romaji":"Kare no taido kara suru to, kare wa sono keikaku ni hantai shiteiru you da.","zh":""},{"ja":"このレストランの雰囲気からすると、料理もすばらしいはずだ。","en":"Judging from the atmosphere of this restaurant, the food must be wonderful.","romaji":"Kono resutoran no fun''iki kara suru to, ryouri mo subarashii hazu da.","zh":""},{"ja":"彼女の成績からすると、彼女は非常に勉強熱心な人でしょう。","en":"Judging from her grades, she must be a very diligent student.","romaji":"Kanojo no seiseki kara suru to, kanojo wa hijou ni benkyou nesshin na hito deshou.","zh":""},{"ja":"その会社の成長率からすると、将来的には大きな利益を得られるでしょう。","en":"From the company''s growth rate, it seems likely to gain substantial profits in the future.","romaji":"Sono kaisha no seicho-ritsu kara suru to, shouraiteki ni wa ooki na rieki o erareru deshou.","zh":""}]',replace('**Short**: Used to indicate that something is judged, estimated, or considered from a certain point or aspect.\n\n**Formation**: Noun + からする\n\n**Long**: 「Noun + からする」expresses a judgment or estimation based on a particular perspective or aspect. It translates to ''judging from'', ''based on'', or ''from the viewpoint of'' in English, allowing the speaker to form an opinion or conclusion from that point.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kara_no','Noun からの',NULL,NULL,'N1','[]','[{"ja":"日本からの手紙を受け取りました。","en":"I received a letter from Japan.","romaji":"Nihon kara no tegami wo uketorimashita.","zh":""},{"ja":"彼は東京からの旅行者です。","en":"He is a traveler from Tokyo.","romaji":"Kare wa Tokyo kara no ryokousha desu.","zh":""},{"ja":"昨日、母からの電話がありました。","en":"Yesterday, I got a call from my mother.","romaji":"Kinou, haha kara no denwa ga arimashita.","zh":""},{"ja":"彼女は大学からの友人です。","en":"She is a friend from college.","romaji":"Kanojo wa daigaku kara no yuujin desu.","zh":""}]',replace('**Short**: Defines the starting point or the origin; ''from''.\n\n**Formation**: Noun + からの\n\n**Long**: 「Noun + からの」indicates the place, source, or origin of something. It simply means ''from (Noun)''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kara_iwasereba','Noun から言わせれば',NULL,NULL,'N1','[]','[{"ja":"先生から言わせれば、毎日勉強するべきだ。","en":"From the teacher''s point of view, you should study every day.","romaji":"Sensei kara iwasereba, mainichi benkyou suru beki da.","zh":""},{"ja":"子供たちから言わせれば、もっと遊ぶ時間がほしい。","en":"From the children''s perspective, they want more time to play.","romaji":"Kodomo-tachi kara iwasereba, motto asobu jikan ga hoshii.","zh":""},{"ja":"僕から言わせれば、そのプランは実行可能だ。","en":"From my point of view, that plan is feasible.","romaji":"Boku kara iwasereba, sono puran wa jikkou kanou da.","zh":""},{"ja":"犬から言わせれば、もっと散歩したいはずだ。","en":"If the dog could talk, it would probably want more walks.","romaji":"Inu kara iwasereba, motto sanpo shitai hazu da.","zh":""}]',replace('**Short**: Express the perspective of the noun; ''from ~''s point of view.''\n\n**Formation**: Noun + から言わせれば\n\n**Long**: 「Noun + から言わせれば」is used to express an opinion or perspective from that noun''s point of view. It can translate as ''from ~''s perspective'' or ''if ~ had a say...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_gurumi','Noun + ぐるみ',NULL,NULL,'N1','[]','[{"ja":"家族ぐるみで旅行に行きました。","en":"We went on a trip with the whole family.","romaji":"Kazoku gurumi de ryokou ni ikimashita.","zh":""},{"ja":"クラスぐるみで遠足に行きました。","en":"The entire class went on an excursion.","romaji":"Kurasu gurumi de ensoku ni ikimashita.","zh":""},{"ja":"この国は国民ぐるみでその法案を支持しています。","en":"The entire population of the country supports that bill.","romaji":"Kono kuni wa kokumin gurumi de sono houan wo shiji shiteimasu.","zh":""},{"ja":"彼は友人ぐるみでそのクラブに参加した。","en":"He joined the club along with all of his friends.","romaji":"Kare wa yuujin gurumi de sono kurabu ni sanka shita.","zh":""}]',replace('**Short**: Describes ''entirely'', ''all together'', or ''as a whole group''.\n\n**Formation**: Noun + ぐるみ\n\n**Long**: 「Noun + ぐるみ」emphasizes that an action or state involves the entire group or everything related to that noun. It can mean ''altogether'', ''as a whole'', or ''with everyone/everything included.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_koso_are','Noun こそあれ',NULL,NULL,'N1','[]','[{"ja":"問題こそあれ、プロジェクトは順調に進んでいます。","en":"Though there are problems, the project is progressing smoothly.","romaji":"Mondai koso are, purojekuto wa junchou ni susunde imasu.","zh":""},{"ja":"多少のリスクこそあれ、挑戦する価値はある。","en":"Though there is some risk, it''s worth taking on the challenge.","romaji":"Tashou no risuku koso are, chousen suru kachi wa aru.","zh":""},{"ja":"欠点こそあれ、彼の提案は興味深い。","en":"Though it has flaws, his proposal is intriguing.","romaji":"Ketten koso are, kare no teian wa kyoumibukai.","zh":""},{"ja":"不安こそあれ、今が行動するときだ。","en":"Though there is anxiety, now is the time to act.","romaji":"Fuan koso are, ima ga koudou suru toki da.","zh":""}]',replace('**Short**: Expresses ''though there is ... (some negative or burdensome aspect), still ...''.\n\n**Formation**: Noun + こそあれ + (result/continuation)\n\n**Long**: 「Noun こそあれ」is a somewhat formal expression meaning ''Though there is X, (still) Y''. It acknowledges one (often negative) aspect while asserting that it does not prevent or change another fact or outcome.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kosoga','Noun こそ～が',NULL,NULL,'N1','[]','[{"ja":"お金こそ必要だが、それだけが人生のすべてではない。","en":"Money is indeed necessary, but it isn''t everything in life.","romaji":"Okane koso hitsuyou da ga, sore dake ga jinsei no subete de wa nai.","zh":""},{"ja":"努力こそ大事だが、結果も見逃せない。","en":"Effort is certainly crucial, but results also matter.","romaji":"Doryoku koso daiji da ga, kekka mo minogasenai.","zh":""},{"ja":"健康こそ宝だが、ときには仕事を優先せざるを得ない。","en":"Health is indeed a treasure, but sometimes you have to prioritize work.","romaji":"Kenkou koso takara da ga, toki ni wa shigoto o yuusen sezaru wo enai.","zh":""},{"ja":"愛こそ力だが、表現するのは難しい。","en":"Love is certainly a powerful force, but it''s difficult to express.","romaji":"Ai koso chikara da ga, hyougen suru no wa muzukashii.","zh":""}]',replace('**Short**: Emphasizes that ''it is precisely Noun that ...'', then adds a contrasting or additional point.\n\n**Formation**: Noun + こそ + (statement) + が + (contrasting/additional statement)\n\n**Long**: 「Noun こそ～が」highlights the importance or uniqueness of the noun. It often translates as ''Yes, Noun is indeed ... , but ...''. The ''が'' introduces a second, sometimes contrasting statement.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_koso_sure_n1','Noun こそすれ',NULL,NULL,'N1','[]','[{"ja":"感謝こそすれ、非難などできません。","en":"I might feel grateful, but I could never criticize.","romaji":"Kansha koso sure, hinan nado dekimasen.","zh":""},{"ja":"忙しさこそすれ、退屈することはありません。","en":"I may be busy, but I''m never bored.","romaji":"Isogashisa koso sure, taikutsu suru koto wa arimasen.","zh":""},{"ja":"後悔こそすれ、忘れることはできない。","en":"I might regret it, but I can''t forget it.","romaji":"Koukai koso sure, wasureru koto wa dekinai.","zh":""},{"ja":"疑問こそすれ、賛成はできない。","en":"I may have doubts, but I cannot agree.","romaji":"Gimon koso sure, sansei wa dekinai.","zh":""}]',replace('**Short**: An emphatic pattern meaning ''it may be X, but definitely not Y.'' Often pairs with a negative statement.\n\n**Formation**: Noun + こそすれ + (negative or contrasting statement)\n\n**Long**: 「Noun/Verb-ます形 + こそすれ」emphasizes that while one aspect (X) might exist or be true, another aspect (Y) absolutely does not. It''s frequently used with negative expressions (e.g., 〜ない、〜できない) to strongly deny the second possibility.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_gotoki_gotoku','Noun ごとき / Noun ごとく',NULL,NULL,'N1','[]','[{"ja":"彼は天使のごとく純粋だ。","en":"He is as pure as an angel.","romaji":"Kare wa tenshi no gotoku junsui da.","zh":""},{"ja":"悪魔のごとき行為をするな。","en":"Don''t engage in acts like those of a devil.","romaji":"Akuma no gotoki koui o suru na.","zh":""},{"ja":"彼女は雪のごとく白い肌をしている。","en":"She has skin as white as snow.","romaji":"Kanojo wa yuki no gotoku shiroi hada o shiteiru.","zh":""},{"ja":"彼は風のごとく去った。","en":"He left like the wind.","romaji":"Kare wa kaze no gotoku satta.","zh":""}]',replace('**Short**: Means ''like a...'', ''as if...'', expressing a simile or metaphor.\n\n**Formation**: Noun + ごとき, Noun + ごとく, Verb-casual + ごとく, い-Adjective + ごとく\n\n**Long**: 「〜ごとき／〜ごとく」conveys similarity, as if comparing one thing to another. ごとき often modifies nouns, while ごとく can modify verbs or adjectives as well. It''s more formal and literary in tone than simple expressions like みたい or よう.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ja_aru_mai_shi','Noun じゃあるまいし',NULL,NULL,'N1','[]','[{"ja":"彼は子供じゃあるまいし、その問題をしっかりと解決するべきだ。","en":"He’s not a child, so he should solve that problem properly.","romaji":"Kare wa kodomo ja aru mai shi, sono mondai o shikkari to kaiketsu suru beki da.","zh":""},{"ja":"急ぐ必要はない、時間じゃあるまいし。","en":"We don’t need to hurry; it’s not like we’re short of time.","romaji":"Isogu hitsuyou wa nai, jikan ja aru mai shi.","zh":""},{"ja":"監督じゃあるまいし、試合の結果について心配するな。","en":"You’re not the coach, so don’t worry about the game results.","romaji":"Kantoku ja aru mai shi, shiai no kekka ni tsuite shinpai suru na.","zh":""},{"ja":"飴じゃあるまいし、そのまま飲み込んでも大丈夫だよ。","en":"It’s not candy, so it’s okay to just swallow it.","romaji":"Ame ja aru mai shi, sono mama nomikonde mo daijoubu da yo.","zh":""}]',replace('**Short**: Expressing that something ''is not''; ''it''s not like...''. Colloquial/masculine form of ではあるまいし.\n\n**Formation**: Noun or Na-Adjective + じゃあるまいし\n\n**Long**: The phrase 「Noun (or Na-Adjective) + じゃあるまいし」 is a somewhat casual, sometimes masculine-sounding expression meaning ''it''s not like...'', ''it''s not as if...'', or ''there''s no need to...'' in certain contexts. It dismisses the idea that the noun or adjective is the reason or cause for something.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_zukume','Noun ずくめ',NULL,NULL,'N1','[]','[{"ja":"彼は最近、失敗ずくめだ。","en":"He has had nothing but failures recently.","romaji":"Kare wa saikin, shippai zukume da.","zh":""},{"ja":"この冬は雪ずくめで大変だ。","en":"This winter has been nothing but snow, which is tough.","romaji":"Kono fuyu wa yuki zukume de taihen da.","zh":""},{"ja":"彼の話は嘘ずくめだった。","en":"His story was full of nothing but lies.","romaji":"Kare no hanashi wa uso zukume datta.","zh":""},{"ja":"今日の仕事は忙しさずくめだった。","en":"Today''s work was nothing but constant busyness.","romaji":"Kyou no shigoto wa isogashisa zukume datta.","zh":""}]',replace('**Short**: Denotes ''entirely'' or ''nothing but'' the preceding noun.\n\n**Formation**: Noun + ずくめ\n\n**Long**: 「Noun + ずくめ」expresses that something consists entirely of that noun or is ''nothing but'' that noun. It describes a situation with a predominance of one thing.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_dake_dewa_sumanai','Noun だけではすまない',NULL,NULL,'N1','[]','[{"ja":"この問題は謝罪だけではすまない。","en":"This problem cannot be settled with just an apology.","romaji":"Kono mondai wa shazai dake dewa sumanai.","zh":""},{"ja":"彼女が怒っているから、お菓子をあげただけではすまないよ。","en":"She’s angry, so just giving her sweets won''t fix it.","romaji":"Kanojo ga okotte iru kara, okashi o ageta dake dewa sumanai yo.","zh":""},{"ja":"このプロジェクトの成功は努力だけではすまない。","en":"Success on this project cannot be achieved with mere effort.","romaji":"Kono purojekuto no seikou wa doryoku dake dewa sumanai.","zh":""},{"ja":"資金調達だけではすまない、実際のビジネスプランも必要だ。","en":"We can’t just finish with fundraising; we also need a real business plan.","romaji":"Shikin choutatsu dake dewa sumanai, jissai no bijinesu puran mo hitsuyou da.","zh":""}]',replace('**Short**: Expresses ''it can''t be settled with just...'', ''cannot be resolved merely by...''.\n\n**Formation**: Noun + だけではすまない\n\n**Long**: 「Noun + だけではすまない」indicates that simply doing or providing the noun is not sufficient to resolve or finish a matter. Something more is required.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tari_tomo_nai','Noun たりとも～ない',NULL,NULL,'N1','[]','[{"ja":"一分たりとも無駄にするな。","en":"Don’t waste even a single minute.","romaji":"Ippun tari tomo muda ni suru na.","zh":""},{"ja":"彼は一言たりとも話さない。","en":"He doesn''t speak even a single word.","romaji":"Kare wa hitokoto tari tomo hanasanai.","zh":""},{"ja":"彼女は一度たりともその映画を見たことがない。","en":"She has never seen that movie, not even once.","romaji":"Kanojo wa ichido tari tomo sono eiga o mita koto ga nai.","zh":""},{"ja":"私は一枚たりともその写真を持っていない。","en":"I don''t have even a single picture of it.","romaji":"Watashi wa ichimai tari tomo sono shashin o motte inai.","zh":""}]',replace('**Short**: Used to show a strong negative: ''not even ~'', ''not a single ~''.\n\n**Formation**: Noun + たりとも + Negative Verb\n\n**Long**: 「Noun + たりとも + Negative Verb」expresses a strong negation such as ''not even one'', ''not even once'', or ''none at all''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_taru','Noun たる Noun',NULL,NULL,'N1','[]','[{"ja":"リーダーたる者は、常に先を見て行動すべきだ。","en":"A person who is a leader should always look ahead and act accordingly.","romaji":"Riidaa taru mono wa, tsune ni saki o mite koudou subeki da.","zh":""},{"ja":"教師たる者、学生に模範を示すべきである。","en":"Someone who is a teacher should set a good example for the students.","romaji":"Kyoushi taru mono, gakusei ni mohan o shimesu beki de aru.","zh":""},{"ja":"母たる者、家族を愛するのは当然だ。","en":"If you are a mother, it’s natural to love your family.","romaji":"Haha taru mono, kazoku o aisuru no wa touzen da.","zh":""},{"ja":"医者たる者、患者の安全を最優先に考えるべきだ。","en":"A person who is a doctor should make patient safety their top priority.","romaji":"Isha taru mono, kanja no anzen o saiyuusen ni kangaeru beki da.","zh":""}]',replace('**Short**: Indicates ''being in the position/state of'', used for roles or statuses.\n\n**Formation**: Noun1 + たる + Noun2\n\n**Long**: 「Noun1 たる Noun2」expresses that the second noun is in the ''role/state/condition'' of the first. It often has a formal or literary tone, emphasizing that someone/something rightly holds or embodies that status.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_desura','Noun ですら',NULL,NULL,'N1','[]','[{"ja":"明日試験があるのに、彼はテキストですら読まない。","en":"He doesn’t even read the textbook, despite having a test tomorrow.","romaji":"Ashita shiken ga aru noni, kare wa tekisuto desura yomanai.","zh":""},{"ja":"この問題は専門家ですら解けない。","en":"Even an expert can’t solve this problem.","romaji":"Kono mondai wa senmonka desura tokenai.","zh":""},{"ja":"彼女は最後のスピーチですら泣いてしまった。","en":"She ended up crying, even during the final speech.","romaji":"Kanojo wa saigo no supiichi desura naite shimatta.","zh":""},{"ja":"彼は毎日勉強しているが、基本の漢字ですら覚えられない。","en":"He studies every day, but can’t even remember basic kanji.","romaji":"Kare wa mainichi benkyou shite iru ga, kihon no kanji desura oboerarenai.","zh":""}]',replace('**Short**: Means ''even'', ''as much as'', used for emphasis in formal contexts.\n\n**Formation**: Noun + ですら\n\n**Long**: 「Noun + ですら」emphasizes ''even'' in a formal or literary tone. It can carry nuance similar to さえ or すら but is used more in writing or formal speech.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_de_nakute_nandarou','Noun でなくてなんだろう',NULL,NULL,'N1','[]','[{"ja":"これが真実でなくてなんだろう。","en":"If this isn’t the truth, then what is?","romaji":"Kore ga shinjitsu de nakute nandarou.","zh":""},{"ja":"彼がリーダーでなくてなんだろう。","en":"If he isn’t the leader, then who is?","romaji":"Kare ga riidaa de nakute nandarou.","zh":""},{"ja":"これが愛でなくてなんだろう。","en":"If this isn’t love, then what is?","romaji":"Kore ga ai de nakute nandarou.","zh":""},{"ja":"これが最高のレストランでなくてなんだろう。","en":"If this isn’t the best restaurant, then what is?","romaji":"Kore ga saikou no resutoran de nakute nandarou.","zh":""}]',replace('**Short**: A strong rhetorical question: ''If not X, then what is it?''\n\n**Formation**: Noun + でなくてなんだろう\n\n**Long**: 「Noun + でなくてなんだろう」expresses the speaker’s strong conviction that something must be that noun—no other possibility. Literally, ''If it isn''t Noun, then what is it?''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dewa_aru_maishi','Noun ではあるまいし',NULL,NULL,'N1','[]','[{"ja":"彼女はプロの歌手ではあるまいし、完璧を求めるのは酷だ。","en":"She’s not a professional singer, so it’s rather harsh to demand perfection.","romaji":"Kanojo wa puro no kashu de wa aru mai shi, kanpeki o motomeru no wa koku da.","zh":""},{"ja":"彼は子供ではあるまいし、そんなにチョコレートばかり食べるのはどうかと思う。","en":"He’s not a child, so I’m not sure about him eating that much chocolate.","romaji":"Kare wa kodomo de wa aru mai shi, sonnani chokoreeto bakari taberu no wa douka to omou.","zh":""},{"ja":"彼は医者ではあるまいし、あなたの健康状態を詮索する必要はない。","en":"He’s not a doctor, so he has no need to pry into your health.","romaji":"Kare wa isha de wa aru mai shi, anata no kenkou joutai o sensaku suru hitsuyou wa nai.","zh":""},{"ja":"この指輪は高価なものではあるまいし、落としても大したことはない。","en":"It’s not an expensive ring, so dropping it isn’t a big deal.","romaji":"Kono yubiwa wa kouka na mono de wa aru mai shi, otoshite mo taishita koto wa nai.","zh":""}]',replace('**Short**: Means ''it’s not as if...'', ''it’s not that...'', more formal than じゃあるまいし.\n\n**Formation**: Noun + ではあるまいし\n\n**Long**: 「Noun + ではあるまいし」indicates that the noun is not the situation or reason being implied. It dismisses a possibility or justification, e.g. ''It’s not as if X, so don’t worry/do that/etc.'' This is the more formal counterpart to じゃあるまいし.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_to_noun_o_kanete','Noun と Noun を兼ねて',NULL,NULL,'N1','[]','[{"ja":"お父さんは社長と経理部長を兼ねています。","en":"My father serves as both the company president and the head of accounting.","romaji":"Otousan wa shachou to keiri buchou o kanete imasu.","zh":""},{"ja":"彼女は音楽教師とピアニストを兼ねています。","en":"She works as both a music teacher and a pianist.","romaji":"Kanojo wa ongaku kyoushi to pianisuto o kanete imasu.","zh":""},{"ja":"この部屋は寝室と書斎を兼ねています。","en":"This room serves as both a bedroom and a study.","romaji":"Kono heya wa shinshitsu to shosai o kanete imasu.","zh":""},{"ja":"彼は父と母を兼ねて子どもの世話をしている。","en":"He looks after his child, taking on both mother and father roles.","romaji":"Kare wa chichi to haha o kanete kodomo no sewa o shite iru.","zh":""}]',replace('**Short**: Used to indicate doing two things at once or fulfilling two roles/purposes.\n\n**Formation**: Noun + と + Noun + を兼ねて\n\n**Long**: 「Noun と Noun を兼ねて」means that one action or thing serves the purpose of both nouns. It can be translated as ''serving as both… and…'', or ''for both… and…''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_ii_to_ii','Noun といい Noun といい',NULL,NULL,'N1','[]','[{"ja":"日本の食べ物といい観光地といい、すべてが素晴らしいです。","en":"Both Japanese food and tourist spots are all wonderful.","romaji":"Nihon no tabemono to ii kankouchi to ii, subete ga subarashii desu.","zh":""},{"ja":"彼の優しさといい、体力といい、彼は理想的なパートナーだ。","en":"Whether it''s his kindness or stamina, he is an ideal partner.","romaji":"Kare no yasashisa to ii, tairyoku to ii, kare wa risouteki na paatonaa da.","zh":""},{"ja":"この町の映画館といい、公園といい、老若男女が楽しめる。","en":"Not to mention the movie theaters and parks in this town, they are enjoyable for all ages.","romaji":"Kono machi no eigakan to ii, kouen to ii, rounyakunan''nyo ga tanoshimeru.","zh":""},{"ja":"彼の歌唱力といい、ダンスのスキルといい、完璧だ。","en":"Both his singing ability and his dance skills are perfect.","romaji":"Kare no kashou ryoku to ii, dansu no sukiru to ii, kanpeki da.","zh":""}]',replace('**Short**: Used to express ''both A and B''; ''whether it''s A or B''; ''not to mention A and also B''.\n\n**Formation**: Noun1 + といい + Noun2 + といい + Comment\n\n**Long**: This grammar structure is used to provide two examples or two situations to demonstrate a certain characteristic or situation. It''s a way of mentioning two items of the same theme to generalize or emphasize something applicable to them both. In English, it can be understood as ''both A and B'', ''whether it''s A or B'', or ''not to mention A and also B''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_iu_n1','Noun という Noun',NULL,NULL,'N1','[]','[{"ja":"宮崎駿という人は有名なアニメーション監督です。","en":"The person called Hayao Miyazaki is a famous animation director.","romaji":"Miyazaki Hayao to iu hito wa yuumei na animation kantoku desu.","zh":""},{"ja":"その恋人という女性は彼にとても厳しいです。","en":"The woman called his girlfriend is very strict with him.","romaji":"Sono koibito to iu josei wa kare ni totemo kibishii desu.","zh":""},{"ja":"東京という都市は夜も賑やかです。","en":"The city called Tokyo is bustling even at night.","romaji":"Tokyo to iu toshi wa yoru mo nigiyaka desu.","zh":""},{"ja":"私は「ハリーポッター」という本が好きです。","en":"I like the book called ''Harry Potter''.","romaji":"Watashi wa ''Harry Potter'' to iu hon ga suki desu.","zh":""}]',replace('**Short**: Used to specify or define one noun with another; ''the noun called'', ''the noun that is'', or ''a certain''.\n\n**Formation**: Noun1 という Noun2\n\n**Long**: The Noun という Noun construction is used to specify or define one noun with another. It usually translates as ''the noun called'', ''the noun that is'' or simply ''a certain''. It is a very common pattern for clarifying what something is named or known as.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_to_iu_tokoro_da','Noun というところだ',NULL,NULL,'N1','[]','[{"ja":"今回の試験の合格者は半数というところだろう。","en":"The passers in this exam would be approximately half.","romaji":"Konkai no shiken no goukakusha wa hansuu to iu tokoro darou.","zh":""},{"ja":"彼の力は80％というところだ。","en":"His strength is about 80%.","romaji":"Kare no chikara wa hachijuu paasento to iu tokoro da.","zh":""},{"ja":"このプランに賛成の人は7割というところだ。","en":"About 70% of people agree with this plan.","romaji":"Kono puran ni sansei no hito wa nanawari to iu tokoro da.","zh":""},{"ja":"課長の意見には、私としては90％というところでしょう。","en":"As for the section manager''s opinion, I''d say I''m about 90% in agreement.","romaji":"Kachou no iken ni wa, watashi toshite wa kyuujuu paasento to iu tokoro deshou.","zh":""}]',replace('**Short**: Means ''it''s approximately...'' or ''it''s about...''. Used to show approximation or a general assessment.\n\n**Formation**: Noun + というところだ\n\n**Long**: The というところだ grammar point is used to show an approximation or general assessment of something. It is often translated as ''it''s approximately...'', ''around...'', or ''it''s about...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_iu_mono','Noun + というもの',NULL,NULL,'N1','[]','[{"ja":"子供というものは、毎日たくさん遊びます。","en":"Children, as a group, play a lot every day.","romaji":"Kodomo to iu mono wa, mainichi takusan asobimasu.","zh":""},{"ja":"大学生というものは研究に時間をたくさんかけます。","en":"University students spend a lot of time on research.","romaji":"Daigakusei to iu mono wa kenkyuu ni jikan o takusan kakemasu.","zh":""},{"ja":"日本文化というものは伝統的なものと新しいものが混ざっています。","en":"Japanese culture is a mixture of traditional and new.","romaji":"Nihon bunka to iu mono wa dentouteki na mono to atarashii mono ga mazatte imasu.","zh":""},{"ja":"別れというものはいつも悲しいものです。","en":"Goodbyes are always sad.","romaji":"Wakare to iu mono wa itsumo kanashii mono desu.","zh":""}]',replace('**Short**: Used to express a generic concept: ''all ~'', ''any ~ of that kind''.\n\n**Formation**: Noun + というもの\n\n**Long**: The grammar pattern ''Noun + というもの'' refers to the entirety or general nature of that noun—often implying ''all of this category'' or ''this thing called...''. It can also highlight a universal truth about the noun mentioned.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_to_itta_tokoro_da','Noun といったところだ',NULL,NULL,'N1','[]','[{"ja":"彼の英語レベルは初級といったところだ。","en":"His English level is at most beginner level.","romaji":"Kare no eigo reberu wa shokyuu to itta tokoro da.","zh":""},{"ja":"私の日本語の語彙は1000語といったところだ。","en":"My Japanese vocabulary is limited to about 1000 words.","romaji":"Watashi no nihongo no goi wa sen go to itta tokoro da.","zh":""},{"ja":"彼が毎日ランニングできるのは5キロといったところだ。","en":"He can run as much as 5 kilometers a day at most.","romaji":"Kare ga mainichi ranningu dekiru no wa go kiro to itta tokoro da.","zh":""},{"ja":"その会社の従業員は20人といったところだ。","en":"The employees at that company are limited to about 20 people.","romaji":"Sono kaisha no juugyouin wa nijuu nin to itta tokoro da.","zh":""}]',replace('**Short**: Expresses ''at most'', ''as much as'', or ''limited to''.\n\n**Formation**: Noun + といったところだ\n\n**Long**: Noun といったところだ describes an upper limit or a maximum extent, often translating to ''at most'' or ''around...''. It suggests the speaker doesn’t expect anything beyond that limit.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_to_iwazu_b_to_iwazu','Noun といわず Noun といわず',NULL,NULL,'N1','[]','[{"ja":"冬といわず夏といわず、彼はいつもアイスクリームを食べます。","en":"Be it winter or summer, he always eats ice cream.","romaji":"Fuyu to iwazu natsu to iwazu, kare wa itsumo aisukuriimu o tabemasu.","zh":""},{"ja":"老いといわず若きといわず、全ての人がそのイベントを楽しめます。","en":"Whether old or young, everyone can enjoy that event.","romaji":"Oi to iwazu wakaki to iwazu, subete no hito ga sono ibento o tanoshimemasu.","zh":""},{"ja":"男といわず女といわず、誰もがこの映画を楽しむでしょう。","en":"Be it men or women, everyone will enjoy this movie.","romaji":"Otoko to iwazu onna to iwazu, daremo ga kono eiga o tanoshimu deshou.","zh":""},{"ja":"月といわず火といわず、あの店は毎日混んでいます。","en":"Be it Monday or Tuesday, that shop is busy every day.","romaji":"Getsu to iwazu ka to iwazu, ano mise wa mainichi konde imasu.","zh":""}]',replace('**Short**: Expresses ''both A and B'' or ''be it A or B''; applies to both without distinction.\n\n**Formation**: Noun1 + といわず + Noun2 + といわず + (rest of the sentence)\n\n**Long**: The grammar pattern AといわずBといわず means ''be it A or B'' or ''both A and B.'' It emphasizes that something applies widely, without distinguishing between A and B.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tokitara','Noun + ときたら',NULL,NULL,'N1','[]','[{"ja":"寿司ときたら、彼は何も食べられない。","en":"When it comes to sushi, he can''t eat anything.","romaji":"Sushi tokitara, kare wa nanimo taberarenai.","zh":""},{"ja":"数学の問題ときたら、彼女はいつも困っている。","en":"When it comes to math problems, she''s always struggling.","romaji":"Suugaku no mondai tokitara, kanojo wa itsumo komatte iru.","zh":""},{"ja":"あの店のハンバーガーときたら、本当に美味しい。","en":"Speaking of that shop''s hamburgers, they''re really delicious.","romaji":"Ano mise no hanbaagaa tokitara, hontou ni oishii.","zh":""},{"ja":"彼のいつもの態度ときたら、本当に困ったものだ。","en":"Speaking of his usual attitude, it''s truly problematic.","romaji":"Kare no itsumo no taido tokitara, hontou ni komatta mono da.","zh":""}]',replace('**Short**: Expresses strong feelings about a topic; ''speaking of'', ''when it comes to''.\n\n**Formation**: Noun + ときたら\n\n**Long**: Noun + ときたら emphasizes strong feelings—often frustration, admiration, or surprise—about that noun. It can translate as ''when it comes to...'', ''speaking of...'', or ''honestly, about...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_wa_kurabemono_ni_naranai','Noun とは比べものにならない',NULL,NULL,'N1','[]','[{"ja":"新しい車の速さは古い車とは比べものにならない。","en":"The speed of the new car is not comparable to the old one.","romaji":"Atarashii kuruma no hayasa wa furui kuruma to wa kurabemono ni naranai.","zh":""},{"ja":"彼の英語のうまさは私とは比べものにならない。","en":"His English skills are beyond comparison with mine.","romaji":"Kare no eigo no umasa wa watashi to wa kurabemono ni naranai.","zh":""},{"ja":"日本の技術は他の国とは比べものにならない。","en":"Japan''s technology is not comparable to that of other countries.","romaji":"Nihon no gijutsu wa hoka no kuni to wa kurabemono ni naranai.","zh":""},{"ja":"今回の地震の被害は前回とは比べものにならない。","en":"The damage from this earthquake is incomparable to the previous one.","romaji":"Konkai no jishin no higai wa zenkai to wa kurabemono ni naranai.","zh":""}]',replace('**Short**: Indicates something is not comparable; ''beyond comparison''.\n\n**Formation**: Noun + とは比べものにならない\n\n**Long**: Use とは比べものにならない to emphasize that two things differ so greatly they cannot be compared—one is vastly superior or different in scale, quality, etc.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tomoarou','Noun + ともあろう + Noun',NULL,NULL,'N1','[]','[{"ja":"先生ともあろう者が、そんな間違いをするなんて。","en":"For a teacher, it''s shocking to make such a mistake.","romaji":"Sensei tomoarou mono ga, sonna machigai o suru nante.","zh":""},{"ja":"大人ともあろう者が子供みたいにふるまってはいけない。","en":"It''s not right for an adult to behave like a child.","romaji":"Otona tomoarou mono ga kodomo mitai ni furumatte wa ikenai.","zh":""},{"ja":"社長ともあろう人がそんな失礼なことを言うなんて。","en":"It''s shocking that someone who is the company president would say such a rude thing.","romaji":"Shachou tomoarou hito ga sonna shitsurei na koto o iu nante.","zh":""},{"ja":"プロの選手ともあろう者が、試合に遅刻するなんて。","en":"For a professional athlete, being late to a match is unthinkable.","romaji":"Puro no senshu tomoarou mono ga, shiai ni chikoku suru nante.","zh":""}]',replace('**Short**: Used to criticize or question unbecoming behavior by someone of a certain status.\n\n**Formation**: Noun + ともあろう + Noun\n\n**Long**: Noun + ともあろう + Noun is used to express that someone with a certain role or status has done something unbefitting their position. It often carries disapproval or surprise: ''For someone who is supposed to be X, how could they...?''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_mo_naru_to','Noun ともなると',NULL,NULL,'N1','[]','[{"ja":"クリスマスともなると、街中がきらきらと輝いて見えます。","en":"When it comes to Christmas time, the whole city sparkles.","romaji":"Kurisumasu to mo naru to, machijuu ga kirakira to kagayaite miemasu.","zh":""},{"ja":"子供が自分の過ちを認めるともなると、話は別ですね。","en":"When a child admits their mistake, that’s a different story.","romaji":"Kodomo ga jibun no ayamachi o mitomeru to mo naru to, hanashi wa betsu desu ne.","zh":""},{"ja":"夏休みともなると、海辺は観光客で溢れかえります。","en":"When summer vacation comes, the seaside is filled with tourists.","romaji":"Natsu yasumi to mo naru to, umibe wa kankoukyaku de afurekaerimasu.","zh":""},{"ja":"試験週間ともなると、図書館はいつもより混雑します。","en":"When exam week arrives, the library gets more crowded than usual.","romaji":"Shiken shuukan to mo naru to, toshokan wa itsumo yori konzatsu shimasu.","zh":""}]',replace('**Short**: ''When it comes to...'', emphasizes a change of situation or status.\n\n**Formation**: Noun + ともなると\n\n**Long**: Noun + ともなると indicates a change of state or circumstances once that noun becomes relevant or once one attains that position. It conveys that ''once it’s X, things change'' or ''when it comes to X...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_mo_nareba','Noun ともなれば',NULL,NULL,'N1','[]','[{"ja":"試験ともなれば、大抵の人が緊張するものです。","en":"When it comes to exams, most people get nervous.","romaji":"Shiken to mo nareba, taitei no hito ga kinchou suru mono desu.","zh":""},{"ja":"彼がリーダーともなれば、チームの性能はさらに向上するでしょう。","en":"If he becomes the leader, the team''s performance will improve even more.","romaji":"Kare ga riidaa to mo nareba, chiimu no seinou wa sara ni koujou suru deshou.","zh":""},{"ja":"夏休みともなれば、観光地はいつも人であふれている。","en":"When it comes to summer vacation, tourist spots are always packed with people.","romaji":"Natsuyasumi to mo nareba, kankouchi wa itsumo hito de afurete iru.","zh":""},{"ja":"結婚ともなれば、ただ二人が愛し合っているだけではすまされない事情も多い。","en":"When it comes to marriage, there are often issues that can’t be solved by love alone.","romaji":"Kekkon to mo nareba, tada futari ga aishiatte iru dake de wa sumasarenai jijou mo oi.","zh":""}]',replace('**Short**: Expresses ''if it comes to'', ''when'', or ''once''.\n\n**Formation**: Noun + ともなれば\n\n**Long**: The grammar point ～ともなれば is used to stress the likelihood of a change or consequence that comes about due to the situation expressed before ともなれば. It can be translated as ''when it comes to'', ''once'', or ''if it comes to'' in English. It''s usually used with nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_aimatte','Noun と相まって',NULL,NULL,'N1','[]','[{"ja":"天気の良さと相まって、ピクニックは大成功でした。","en":"In combination with the good weather, the picnic was a great success.","romaji":"Tenki no yosa to aimatte, pikunikku wa daiseikou deshita.","zh":""},{"ja":"努力と運と相まって、彼は試験に合格しました。","en":"Thanks to both effort and luck, he passed the exam.","romaji":"Doryoku to un to aimatte, kare wa shiken ni goukaku shimashita.","zh":""},{"ja":"ひまわり油とガーリックと相まって、この料理は美味しいです。","en":"Combined with sunflower oil and garlic, this dish is delicious.","romaji":"Himawari abura to gaarikku to aimatte, kono ryouri wa oishii desu.","zh":""},{"ja":"新しい技術と経験と相まって、私たちはこの問題を克服できました。","en":"Together with new technology and experience, we were able to overcome this problem.","romaji":"Atarashii gijutsu to keiken to aimatte, watashitachi wa kono mondai o kokufuku dekimashita.","zh":""}]',replace('**Short**: Used to express ''in combination with'', ''together with'', ''along with''.\n\n**Formation**: Noun + と相まって\n\n**Long**: The Noun と相まって grammar point is used to indicate that something happens or is the result of two or more factors working together. It can be translated as ''in combination with'', ''together with'' or ''along with'' in English. It is used with nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_nakushite_wa_nai','Noun なくして～はない',NULL,NULL,'N1','[]','[{"ja":"努力なくして成功はない。","en":"There is no success without effort.","romaji":"Doryoku nakushite seikou wa nai.","zh":""},{"ja":"時間なくして完璧な作品は作れない。","en":"You cannot create a perfect work without time.","romaji":"Jikan nakushite kanpeki na sakuhin wa tsukurenai.","zh":""},{"ja":"経験なくして成長はない。","en":"There is no growth without experience.","romaji":"Keiken nakushite seichou wa nai.","zh":""},{"ja":"リーダーシップなくしてグループの成功はない。","en":"Without leadership, there can be no success for the group.","romaji":"Riidaashippu nakushite guruupu no seikou wa nai.","zh":""}]',replace('**Short**: Expresses ''without ~, there can''t be ~''; ''can''t do ~ without first doing ~''.\n\n**Formation**: Noun + なくして + Sentence ～はない\n\n**Long**: The なくして grammar point is used to indicate that something is indispensable or necessary for something else to occur. ''Without'' the first noun, the second part ''cannot exist/occur''. It demonstrates the principle of causality or necessity.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_nashi_de_wa_nai','Noun なしでは～ない',NULL,NULL,'N1','[]','[{"ja":"水なしでは生きられない。","en":"We cannot live without water.","romaji":"Mizu nashi de wa ikirarenai.","zh":""},{"ja":"彼の助けなしでは、この問題を解決することはできない。","en":"Without his help, I cannot solve this problem.","romaji":"Kare no tasuke nashi de wa, kono mondai o kaiketsu suru koto wa dekinai.","zh":""},{"ja":"コンピュータなしでは、現代のビジネスは成り立たない。","en":"Modern business cannot function without computers.","romaji":"Konpyuuta nashi de wa, gendai no bijinesu wa naritatanai.","zh":""},{"ja":"友情なしでは、人生は退屈だろう。","en":"Life would be boring without friendship.","romaji":"Yuujou nashi de wa, jinsei wa taikutsu darou.","zh":""}]',replace('**Short**: Expresses the necessity of something; ''cannot do without'', ''not possible without''.\n\n**Formation**: Noun + なしでは～ない\n\n**Long**: Noun なしでは～ない is used to emphasize that something is indispensable. It can be translated as ''cannot do without'' or ''not possible without.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_nashi_ni_wa_nai','Noun なしには～ない',NULL,NULL,'N1','[]','[{"ja":"お金なしには生活ができない。","en":"I cannot get by without money.","romaji":"Okane nashi ni wa seikatsu ga dekinai.","zh":""},{"ja":"愛情なしには子育てができない。","en":"You cannot raise a child without love.","romaji":"Aijou nashi ni wa kosodate ga dekinai.","zh":""},{"ja":"彼なしにはこのプロジェクトを進められない。","en":"Without him, I cannot move this project forward.","romaji":"Kare nashi ni wa kono purojekuto o susumerarenai.","zh":""},{"ja":"水なしには生きていけない。","en":"I cannot live without water.","romaji":"Mizu nashi ni wa ikite ikenai.","zh":""}]',replace('**Short**: Means ''without'', ''cannot do without'', ''not possible without''.\n\n**Formation**: Noun + なしには + Verb-negative\n\n**Long**: The なしには～ない grammar point is used to express that without the mentioned noun, something is not possible. It can be translated as ''cannot (do) without ~'', or ''not possible without ~''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nara_izashirazu','Noun ならいざ知らず',NULL,NULL,'N1','[]','[{"ja":"数学ならいざ知らず、物理なんて全然わからない。","en":"Math might be manageable, but as for physics, I''m completely clueless.","romaji":"Suugaku nara iza shirazu, butsuri nante zenzen wakaranai.","zh":""},{"ja":"5キロならいざ知らず、10キロなんて走れません。","en":"Maybe I could run 5 kilometers, but 10 kilometers is out of the question.","romaji":"Go kiro nara iza shirazu, juu kiro nante hashiremasen.","zh":""},{"ja":"日本語ならいざ知らず、中国語なんて話せない。","en":"I might be able to speak Japanese, but Chinese is impossible for me.","romaji":"Nihongo nara iza shirazu, chuugokugo nante hanasenai.","zh":""},{"ja":"冷たい水ならいざ知らず、熱い水で泳ぐなんて考えたこともない。","en":"Maybe cold water, but swimming in hot water never even crossed my mind.","romaji":"Tsumetai mizu nara iza shirazu, atsui mizu de oyogu nante kangaeta koto mo nai.","zh":""}]',replace('**Short**: Expresses ''maybe X is possible, but Y is definitely not''. Often ''let alone...''.\n\n**Formation**: Noun1 + ならいざ知らず + Noun2 (comment)\n\n**Long**: 「Xならいざ知らず、Yは…」 emphasizes that while X might be possible or acceptable, Y is out of the question or even more difficult. It can be translated as ''I could understand X, but Y is impossible'' or ''Maybe X, but definitely not Y.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nara_de_wa','Noun + ならでは',NULL,NULL,'N1','[]','[{"ja":"これは日本ならではの風景ですね。","en":"This is a landscape you can only find in Japan.","romaji":"Kore wa Nihon nara dewa no fuukei desu ne.","zh":""},{"ja":"新鮮な魚はこの町ならではの特産品です。","en":"Fresh fish is a specialty unique to this town.","romaji":"Shinsen na sakana wa kono machi nara dewa no tokusanhin desu.","zh":""},{"ja":"彼の技術は彼ならではのものだ。","en":"His skills are unique to him.","romaji":"Kare no gijutsu wa kare nara dewa no mono da.","zh":""},{"ja":"この手作りの一品は、彼女ならではのものです。","en":"This handmade item is something only she could produce.","romaji":"Kono tezukuri no ippin wa, kanojo nara dewa no mono desu.","zh":""}]',replace('**Short**: Expresses something unique or characteristic only of that noun; ''only found in'', ''only possible with''.\n\n**Formation**: Noun + ならでは\n\n**Long**: The pattern Noun + ならでは highlights something that is unique or distinctive to that noun, suggesting that only this place, person, or thing could possess or create it.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_nari_b_nari','Noun なり Noun なり',NULL,NULL,'N1','[]','[{"ja":"映画なり、音楽なり、何か趣味はありますか。","en":"Do you have any hobbies, such as movies or music?","romaji":"Eiga nari, ongaku nari, nanika shumi wa arimasu ka?","zh":""},{"ja":"紅茶なり、コーヒーなり、何か飲み物をください。","en":"Please give me something to drink, like tea or coffee.","romaji":"Koucha nari, koohii nari, nanika nomimono o kudasai.","zh":""},{"ja":"パンなり、おにぎりなり、何か食べてください。","en":"Please eat something—bread, onigiri, or whatever you’d like.","romaji":"Pan nari, onigiri nari, nanika tabete kudasai.","zh":""},{"ja":"タクシーなり、バスなりに乗って来てください。","en":"Please come by either taxi or bus.","romaji":"Takushii nari, basu nari ni notte kite kudasai.","zh":""}]',replace('**Short**: Lists alternatives of the same kind; ''either A or B'', ''A or B, for example''.\n\n**Formation**: Noun + なり + Noun + なり\n\n**Long**: The pattern AなりBなり is used to suggest alternatives or options, usually of the same category. It can be translated as ''whether A or B'' or ''A or B, for example''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nari_tomo','Noun なりとも',NULL,NULL,'N1','[]','[{"ja":"時間が限られているので、一時間なりとも練習すべきだ。","en":"Since time is limited, you should practice for at least an hour.","romaji":"Jikan ga kagirarete iru node, ichi-jikan nari tomo renshuu subeki da.","zh":""},{"ja":"彼には一言なりとも謝罪の言葉を聞きたい。","en":"I’d like to hear at least a word of apology from him.","romaji":"Kare ni wa hitokoto nari tomo shazai no kotoba o kikitai.","zh":""},{"ja":"このプロジェクトには、一人なりともメンバーが必要だ。","en":"We need at least one member for this project.","romaji":"Kono purojekuto ni wa, hitori nari tomo membaa ga hitsuyou da.","zh":""},{"ja":"あなたには、一言なりとも感謝の言葉を述べたい。","en":"I want to offer at least a word of gratitude to you.","romaji":"Anata ni wa, hitokoto nari tomo kansha no kotoba o nobetai.","zh":""}]',replace('**Short**: Indicates even a small amount or degree; ''at least'', ''even a little''.\n\n**Formation**: Noun + なりとも\n\n**Long**: Noun + なりとも is used to show that even a small amount or degree is valuable or needed. It translates as ''at least'' or ''even a little'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_ni_b_wo_kasanete','Noun に Noun を重ねて',NULL,NULL,'N1','[]','[{"ja":"彼女は失敗に失敗を重ねて、とうとう会社を辞めた。","en":"She piled up failures upon failures and finally quit the company.","romaji":"Kanojo wa shippai ni shippai wo kasanete, toutou kaisha wo yameta.","zh":""},{"ja":"仕事に仕事を重ねて、彼は疲れ果てた。","en":"He piled up work upon work and was completely exhausted.","romaji":"Shigoto ni shigoto wo kasanete, kare wa tsukarehateta.","zh":""},{"ja":"彼は試験に不合格になり、失望に失望を重ねていた。","en":"He failed the exam and kept piling up his disappointments.","romaji":"Kare wa shiken ni fugōkaku ni nari, shitsubō ni shitsubō wo kasanete ita.","zh":""},{"ja":"彼は問題に問題を重ねて、とうとう退学になった。","en":"He kept piling up problems upon problems until he was finally expelled.","romaji":"Kare wa mondai ni mondai wo kasanete, toutou taigaku ni natta.","zh":""}]',replace('**Short**: This expression is used to describe repeated actions or states, ''one after another'' or ''pile up''.\n\n**Formation**: Noun に Noun を重ねて\n\n**Long**: The structure Noun に Noun を重ねて is used to indicate the repetition of actions or states. In English, this could be translated as ''one after another'' or ''pile up''. It''s typically used to emphasize a great deal of continuation or accumulation of something.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_ni_atte_ha','Noun にあっては',NULL,NULL,'N1','[]','[{"ja":"戦争時にあっては、すべての人々が困難に直面していました。","en":"In wartime, all people were facing difficulties.","romaji":"Sensouji ni atte wa, subete no hito ga konnan ni chokumen shiteimashita.","zh":""},{"ja":"経済危機にあっては、多くの企業が倒産の危機に瀕している。","en":"In the economic crisis, many companies are on the verge of bankruptcy.","romaji":"Keizai kiki ni atte wa, ooku no kigyou ga tousan no kiki ni hinshite iru.","zh":""},{"ja":"不況下にあっては、どの企業も経費削減を迫られている。","en":"In times of recession, every company is forced to cut costs.","romaji":"Fukyouka ni atte wa, dono kigyou mo keihi sakugen o semararete iru.","zh":""},{"ja":"改革期にあっては、新しいアイデアを大切にする必要がある。","en":"In a period of reform, it''s necessary to value new ideas.","romaji":"Kaikaku ki ni atte wa, atarashii aidea o taisetsu ni suru hitsuyou ga aru.","zh":""}]',replace('**Short**: Indicates a specific situation or environment in which something happens or is the case.\n\n**Formation**: Noun + にあっては\n\n**Long**: The にあっては grammar point is used after a noun that indicates a specific situation or environment. It expresses the context in which an event takes place, or the circumstances that pertain to the information to be explained or highlighted. It can be translated as ''in'', ''at'' or ''under'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_ni_aru_majiki_noun','Noun にあるまじき Noun',NULL,NULL,'N1','[]','[{"ja":"彼は教師にあるまじき言動をとった。","en":"He took actions that are unbecoming of a teacher.","romaji":"Kare wa kyoushi ni aru majiki gendou wo totta.","zh":""},{"ja":"これは人間にあるまじき行為だ。","en":"This is an act that is unfitting for a human.","romaji":"Kore wa ningen ni aru majiki koui da.","zh":""},{"ja":"彼女は社長にあるまじき振る舞いをした。","en":"She behaved in a way that is unbecoming of a president.","romaji":"Kanojo wa shachou ni aru majiki furumai wo shita.","zh":""},{"ja":"それは社会人にあるまじき行動だ。","en":"That is a behaviour that is not suitable for an adult.","romaji":"Sore wa shakaijin ni aru majiki koudou da.","zh":""}]',replace('**Short**: Expresses the idea of ''unfitting'', ''unbecoming'' or ''inappropriate''.\n\n**Formation**: Noun1 にあるまじき Noun2\n\n**Long**: The grammar point Noun にあるまじき Noun is used to express that the noun doesn''t fit or is inappropriate in some way for the other noun. It can translate loosely as ''unfitting for'', ''unbecoming of'' or ''something that must not be for a/ the noun''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_ni_shite','Noun にして',NULL,NULL,'N1','[]','[{"ja":"彼は医者にしてその基本的な知識がないのが信じられない。","en":"I can''t believe that even as a doctor, he doesn''t have that basic knowledge.","romaji":"Kare wa isha ni shite sono kihonteki na chishiki ga nai no ga shinjirarenai.","zh":""},{"ja":"彼は経験豊富な運転手にして、事故を起こした。","en":"Even as an experienced driver, he had an accident.","romaji":"Kare wa keiken houfu na untenshu ni shite, jiko wo okoshita.","zh":""},{"ja":"彼は成績優秀な生徒にして、その問題が解けなかった。","en":"Even as an excellent student, he couldn''t solve that problem.","romaji":"Kare wa seiseki yuushuu na seito ni shite, sono mondai ga tokenakatta.","zh":""},{"ja":"彼は勉強家にして、その問題を理解できなかった。","en":"Even as a studious person, he could not understand that problem.","romaji":"Kare wa benkyouka ni shite, sono mondai o rikai dekinakatta.","zh":""}]',replace('**Short**: Expresses the idea ''even for'', ''even though'', or ''in spite of''.\n\n**Formation**: Noun + にして\n\n**Long**: The grammar point Noun にして expresses a sense of surprise, disbelief or unexpectedness in response to a situation or circumstance. Generally, it is used when the speaker wants to convey that something is unexpected even for someone (noun) or in their situation.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_nishite_hajimete','Noun にして初めて',NULL,NULL,'N1','[]','[{"ja":"大人にして初めて、親の苦労が分かった。","en":"Only when I became an adult did I understand my parents'' struggles for the first time.","romaji":"Otona ni shite hajimete, oya no kurou ga wakatta.","zh":""},{"ja":"彼は40歳にして初めて、海外旅行を経験した。","en":"Only when he turned 40 did he travel abroad for the first time.","romaji":"Kare wa yonjuu-sai ni shite hajimete, kaigai ryokou o keiken shita.","zh":""},{"ja":"彼女は親にして初めて、子育ての大変さを理解した。","en":"It was only after she became a parent that she realized how challenging raising a child can be.","romaji":"Kanojo wa oya ni shite hajimete, kosodate no taihensa o rikai shita.","zh":""},{"ja":"社長にして初めて、会社全体の重責を痛感した。","en":"Only when he became president did he feel the full weight of responsibility for the entire company.","romaji":"Shachou ni shite hajimete, kaisha zentai no juuseki o tsuukan shita.","zh":""}]',replace('**Short**: Expresses ''only when/after... for the first time''.\n\n**Formation**: Noun + にして初めて\n\n**Long**: The phrase Noun にして初めて is used to express a sense of realization or experience that only came about or was felt after reaching that particular stage or status. In English, it could be translated as ''only when/after... for the first time''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_sura','Noun にすら',NULL,NULL,'N1','[]','[{"ja":"彼にすらその問題は解けなかった。","en":"Even he could not solve that problem.","romaji":"Kare ni sura sono mondai wa tokenakatta.","zh":""},{"ja":"彼女はテストにすら合格しなかった。","en":"She did not even pass the test.","romaji":"Kanojo wa tesuto ni sura goukaku shinakatta.","zh":""},{"ja":"この犬は自分の名前にすら反応しない。","en":"This dog doesn''t even respond to its own name.","romaji":"Kono inu wa jibun no namae ni sura hannou shinai.","zh":""},{"ja":"彼にすら話す余裕がなかった。","en":"I didn''t even have the time to talk to him.","romaji":"Kare ni sura hanasu yoyuu ga nakatta.","zh":""}]',replace('**Short**: Expresses the concept of ''even''; ''even in'', ''even as'', ''even to''.\n\n**Formation**: Noun + にすら\n\n**Long**: The 〜にすら grammar point is used to show surprise that an action or situation applies even to the noun in question. It can be translated into English as ''even in'', ''even as'', or ''even to''. It''s often used with negative or unexpected statements, emphasizing that ''even'' in this particular case something can''t or doesn''t happen.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_todomarazu_mo','Noun にとどまらず～も',NULL,NULL,'N1','[]','[{"ja":"このアプリは、日本語にとどまらず、他の言語もサポートしています。","en":"This app not only supports Japanese, but also other languages.","romaji":"Kono apuri wa, nihongo ni todomarazu, hoka no gengo mo sapooto shite imasu.","zh":""},{"ja":"彼は、音楽にとどまらず、映画製作にも興味がある。","en":"He is not only interested in music, but also in filmmaking.","romaji":"Kare wa, ongaku ni todomarazu, eiga seisaku ni mo kyoumi ga aru.","zh":""},{"ja":"彼の影響は、家族にとどまらず、地域全体にも及んでいます。","en":"His influence extends not only to his family but also to the entire region.","romaji":"Kare no eikyou wa, kazoku ni todomarazu, chiiki zentai ni mo oyonde imasu.","zh":""},{"ja":"彼女の才能は、絵画にとどまらず、文学にも及ぶ。","en":"Her talent extends not only to painting, but also to literature.","romaji":"Kanojo no sainou wa, kaiga ni todomarazu, bungaku ni mo oyobu.","zh":""}]',replace('**Short**: This expresses the idea of ''not only...but also'', ''not stopping at...''.\n\n**Formation**: Noun + にとどまらず + Noun + も\n\n**Long**: This grammar point is used to express that something is not limited to just one thing (the thing before にとどまらず), but also includes other things (the thing after も). It can be translated as ''not only... but also...'' or ''not stopping at...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_hikikae_wa','Noun にひきかえ Noun は',NULL,NULL,'N1','[]','[{"ja":"彼の親切さにひきかえ、彼女は無感情だ。","en":"In contrast to his kindness, she is emotionless.","romaji":"Kare no shinsetsusa ni hikikae, kanojo wa mukanjou da.","zh":""},{"ja":"夏にひきかえ、冬は雪で寒い。","en":"As opposed to summer, winter is cold with snow.","romaji":"Natsu ni hikikae, fuyu wa yuki de samui.","zh":""},{"ja":"日本の駅にひきかえ、アメリカの駅は広い。","en":"As opposed to Japanese stations, American stations are wide.","romaji":"Nihon no eki ni hikikae, Amerika no eki wa hiroi.","zh":""},{"ja":"昔にひきかえ、現代はテクノロジーが進歩した。","en":"As opposed to the old days, modern times have advanced technology.","romaji":"Mukashi ni hikikae, gendai wa tekunorojii ga shinpo shita.","zh":""}]',replace('**Short**: Represents ''in contrast to'', ''as opposed to''.\n\n**Formation**: Noun 1 + にひきかえ + Noun 2 + は\n\n**Long**: The grammar point Noun にひきかえ Noun は is used in Japanese to express contrast or opposition between two nouns. It translates to ''as opposed to'' or ''in contrast to'' in English. The first noun represents what is being contrasted against and the second noun represents the main subject.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_mo_mashite','Noun にもまして',NULL,NULL,'N1','[]','[{"ja":"私は彼にもまして、音楽を愛しています。","en":"I love music even more than he does.","romaji":"Watashi wa kare ni mo mashite, ongaku o aishiteimasu.","zh":""},{"ja":"彼女は年齢にもまして、経験豊富です。","en":"She has even more experience than her age would suggest.","romaji":"Kanojo wa nenrei ni mo mashite, keiken houfu desu.","zh":""},{"ja":"今日は昨日にもまして寒いです。","en":"It is even colder today than it was yesterday.","romaji":"Kyou wa kinou ni mo mashite samui desu.","zh":""},{"ja":"このビルは高さにもまして、美しい設計が有名です。","en":"This building is famous for its beautiful design even more than its height.","romaji":"Kono biru wa takasa ni mo mashite, utsukushii sekkei ga yuumei desu.","zh":""}]',replace('**Short**: This expresses ''Even more than; exceeding''.\n\n**Formation**: Noun + にもまして\n\n**Long**: The Nounにもまして grammar point is used to express that something is even more or exceeds the noun that it’s being compared to. It translates to expressions like ''even more than'' or ''exceeding'' in English. It is used when making a comparison to emphasize the greater degree of something.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_yorazu','Noun によらず',NULL,NULL,'N1','[]','[{"ja":"結果は勉強時間によらず変わらないでしょう。","en":"The result will not change regardless of the study time.","romaji":"Kekka wa benkyou jikan ni yorazu kawaranai deshou.","zh":""},{"ja":"季節によらず、この地域は常に暖かいです。","en":"This region is always warm, regardless of the season.","romaji":"Kisetsu ni yorazu, kono chiiki wa tsune ni atatakai desu.","zh":""},{"ja":"年齢によらず、皆が楽しめるイベントです。","en":"It is an event that everyone can enjoy, regardless of age.","romaji":"Nenrei ni yorazu, mina ga tanoshimeru ibento desu.","zh":""},{"ja":"国籍によらず、誰でも参加できます。","en":"Anyone can participate, regardless of nationality.","romaji":"Kokuseki ni yorazu, dare demo sanka dekimasu.","zh":""}]',replace('**Short**: Regardless of, irrespective of.\n\n**Formation**: Noun + によらず\n\n**Long**: The ～によらず grammar point is used to express the meaning ''regardless of'' or ''irrespective of'' in English. It is used when the outcome does not change regardless of differences in conditions.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_saki_gakete','Noun に先駆けて',NULL,NULL,'N1','[]','[{"ja":"この映画は日本に先駆けて、アメリカで公開されました。","en":"This film was released in America ahead of Japan.","romaji":"Kono eiga wa Nippon ni sakigakete, Amerika de koukai saremashita.","zh":""},{"ja":"彼は周りの人々に先駆けて、その発表を聞いた。","en":"He heard the announcement before the people around him.","romaji":"Kare wa mawari no hitobito ni sakigakete, sono happyou o kiita.","zh":""},{"ja":"ジョンソンさんは他の参加者に先駆けて、会場に到着しました。","en":"Mr. Johnson arrived at the venue ahead of the other participants.","romaji":"Jonson-san wa hoka no sankasha ni sakigakete, kaijou ni touchaku shimashita.","zh":""},{"ja":"彼女は同級生に先駆けて卒業することができました。","en":"She was able to graduate before her classmates.","romaji":"Kanojo wa doukyuusei ni sakigakete sotsugyou suru koto ga dekimashita.","zh":""}]',replace('**Short**: Meaning ''ahead of'', ''before'', or ''preceding in time''.\n\n**Formation**: Noun + に先駆けて\n\n**Long**: The grammar point 〜に先駆けて indicates something happening ahead or before something else in terms of time. Typically used in written language or formal speech.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_ni_sokushita_b','Noun に即した Noun',NULL,NULL,'N1','[]','[{"ja":"社会のニーズに即した教育改革が必要だ。","en":"We need an educational reform that is in accordance with the needs of society.","romaji":"Shakai no niizu ni sokushita kyouiku kaikaku ga hitsuyou da.","zh":""},{"ja":"国際法に即した対応をとるべきだ。","en":"We should respond in accordance with international law.","romaji":"Kokusaihou ni sokushita taiou wo toru beki da.","zh":""},{"ja":"チームのポリシーに即した行動を取りましょう。","en":"Let''s take action in accordance with the team''s policy.","romaji":"Chiimu no porishii ni sokushita koudou wo torimashou.","zh":""},{"ja":"現実に即した計画を立てなければならない。","en":"We must make a plan based on reality.","romaji":"Genjitsu ni sokushita keikaku wo tatenakereba naranai.","zh":""}]',replace('**Short**: Expresses the idea of ''in accordance with'', ''based on''.\n\n**Formation**: Noun1 + に即した + Noun2\n\n**Long**: The grammar point ''Noun に即した Noun'' is used to express the idea of something being done in accordance with or based on something else. Usually, the first noun is principle, rule, reality, etc. and the second noun could be action, method, plan, etc.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_soku_shite','Noun に即して Verb',NULL,NULL,'N1','[]','[{"ja":"会社のポリシーに即して行動しましょう。","en":"Let''s act in accordance with the company''s policy.","romaji":"Kaisha no porishii ni soku shite koudou shimashou.","zh":""},{"ja":"法律に即して判断を下すことが重要です。","en":"It''s important to make judgments in accordance with the law.","romaji":"Houritsu ni soku shite hantei o kudasu koto ga juuyou desu.","zh":""},{"ja":"彼の意見に即して、プランを変更しました。","en":"Based on his opinion, we changed the plan.","romaji":"Kare no iken ni soku shite, puran o henkou shimashita.","zh":""},{"ja":"ルールに即して行動すれば、問題は起きません。","en":"If we act in accordance with the rules, there will be no problem.","romaji":"Ruuru ni soku shite koudou sureba, mondai wa okimasen.","zh":""}]',replace('**Short**: The grammar point Noun に即して Verb is used to mean ''to act in accordance with'', ''in line with'' or ''based on''.\n\n**Formation**: Noun + に即して + Verb\n\n**Long**: The formation Noun に即して Verb is used when someone is doing something based on or in accordance with some norms, rules, decisions or principles. This structure is often used in business or official contexts.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_ni_iwasereba','Noun に言わせれば',NULL,NULL,'N1','[]','[{"ja":"先生に言わせれば、毎日勉強することが重要だと言う。","en":"According to the teacher, it''s important to study every day.","romaji":"Sensei ni iwasereba, mainichi benkyou suru koto ga juuyou da to iu.","zh":""},{"ja":"彼に言わせれば、早く結婚する方がいいと思っている。","en":"If you ask him, he thinks it''s better to get married early.","romaji":"Kare ni iwasereba, hayaku kekkon suru hou ga ii to omotte iru.","zh":""},{"ja":"評論家に言わせれば、この映画は今年の最高の映画だそうだ。","en":"According to the critic, this movie is the best of the year.","romaji":"Hyouronka ni iwasereba, kono eiga wa kotoshi no saikou no eiga da sou da.","zh":""},{"ja":"父に言わせれば、海外で働く経験はとても価値がある。","en":"In my father''s opinion, the experience of working overseas is very valuable.","romaji":"Chichi ni iwasereba, kaigai de hataraku keiken wa totemo kachi ga aru.","zh":""}]',replace('**Short**: Expresses ''according to'', ''if you ask'', ''in the opinion of''.\n\n**Formation**: Noun + に言わせれば\n\n**Long**: The に言わせれば grammar point is used when we want to express someone''s opinion or viewpoint. It can be translated as ''according to'', ''if you ask'', or ''in the opinion of''. This form is mostly used in formal or written language.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_kagitta_koto_dewa_nai','Noun に限ったことではない',NULL,NULL,'N1','[]','[{"ja":"この問題は日本に限ったことではない。","en":"This issue is not only limited to Japan.","romaji":"Kono mondai wa Nihon ni kagitta koto dewa nai.","zh":""},{"ja":"英語はアメリカに限ったことではない。","en":"English is not just limited to America.","romaji":"Eigo wa Amerika ni kagitta koto dewa nai.","zh":""},{"ja":"スマホの依存症は若者に限ったことではない。","en":"Smartphone addiction is not only limited to young people.","romaji":"Sumaho no izonshou wa wakamono ni kagitta koto dewa nai.","zh":""},{"ja":"地球温暖化は我々人間に限ったことではない。","en":"Global warming is not just limited to us humans.","romaji":"Chikyuu ondanka wa wareware ningen ni kagitta koto dewa nai.","zh":""}]',replace('**Short**: Indicates that something is not only limited to; ''not only'', ''not just''.\n\n**Formation**: Noun + に限ったことではない\n\n**Long**: This grammar point is used to express that the statement is not only limited to the noun mentioned before it. In English, it can be translated as ''not only'', ''not just'', or sometimes ''not necessarily''. It underscores that what is being said is also true for other things or situations, not just for the specific noun stated.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_kagitta_koto_demo_nai','Noun に限ったことでもない',NULL,NULL,'N1','[]','[{"ja":"この試験が難しいのは、数学に限ったことでもない。","en":"The exam being difficult is not limited to just math.","romaji":"Kono shiken ga muzukashii no wa, suugaku ni kagitta koto demo nai.","zh":""},{"ja":"彼女が可愛いのは顔だけに限ったことでもない。性格も好きだ。","en":"Her being cute is not just limited to her face. I also like her personality.","romaji":"Kanojo ga kawaii no wa kao dake ni kagitta koto demo nai. Seikaku mo suki da.","zh":""},{"ja":"その問題が起こるのは、我々の国に限ったことでもない。","en":"The occurrence of that problem is not limited to our country.","romaji":"Sono mondai ga okoru no wa, wareware no kuni ni kagitta koto demo nai.","zh":""},{"ja":"この作家の本が売れているのは日本に限ったことでもない。","en":"The selling of this author''s books is not limited to just Japan.","romaji":"Kono sakka no hon ga urete iru no wa Nippon ni kagitta koto demo nai.","zh":""}]',replace('**Short**: ''Not limited to''; ''not just'', ''not exclusively''.\n\n**Formation**: Noun + に限ったことでもない\n\n**Long**: The grammar point ''Noun に限ったことでもない'' typically expresses that something is not only limited to a specific instance or category. It insinuates that there are also other instances or categories involved. In English, it can be translated as ''not limited to'', ''not just'', or ''not exclusively''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_kagiru','Noun に限る',NULL,NULL,'N1','[]','[{"ja":"こういう時には家族に話すに限る。","en":"At times like this, there''s nothing better than talking to your family.","romaji":"Kou iu toki ni wa kazoku ni hanasu ni kagiru.","zh":""},{"ja":"寒い冬には温かいお茶に限る。","en":"In cold winter, there''s nothing better than warm tea.","romaji":"Samui fuyu ni wa atatakai ocha ni kagiru.","zh":""},{"ja":"疲れたときは、よい睡眠に限る。","en":"When you are tired, nothing is better than a good sleep.","romaji":"Tsukareta toki wa, yoi suimin ni kagiru.","zh":""},{"ja":"ダイエットするなら、運動に限る。","en":"If you want to go on a diet, there is nothing better than exercise.","romaji":"Daietto suru nara, undou ni kagiru.","zh":""}]',replace('**Short**: Expresses the idea that ''nothing but'', ''nothing is better than''.\n\n**Formation**: Noun + に限る\n\n**Long**: The noun に限る grammar point is used to express the idea that there is nothing better than the noun mentioned in the specific context. It is often used to give personal opinions, advice, or recommendations.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_nuita_b','Noun ぬいた Noun',NULL,NULL,'N1','[]','[{"ja":"このサラダはにんじんをぬいたサラダです。","en":"This is a salad with the carrots removed.","romaji":"Kono sarada wa ninjin o nuita sarada desu.","zh":""},{"ja":"彼はコーヒーから砂糖をぬいた。","en":"He removed the sugar from the coffee.","romaji":"Kare wa koohii kara satou o nuita.","zh":""},{"ja":"私は料理から塩をぬいた。","en":"I removed the salt from the cooking.","romaji":"Watashi wa ryouri kara shio o nuita.","zh":""},{"ja":"彼女は服からシミをぬいた。","en":"She removed the stain from the clothes.","romaji":"Kanojo wa fuku kara shimi o nuita.","zh":""}]',replace('**Short**: Expresses the idea of ''taking something out from something else''.\n\n**Formation**: Noun1 + をぬいた + Noun2\n\n**Long**: This grammar point is used to denote the action of removing or taking out one thing from another. It is usually used with nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_nuite','Noun + ぬいて（~nuite)',NULL,NULL,'N1','[]','[{"ja":"私たちは、彼ぬいて全員が集まることができました。","en":"We were able to gather everyone except for him.","romaji":"Watashitachi wa, kare nuite zen''in ga atsumaru koto ga dekimashita.","zh":""},{"ja":"このレストランはお子様メニューをぬいてすべてが美味しい。","en":"Everything at this restaurant is delicious except for the kids'' menu.","romaji":"Kono resutoran wa okosama menyuu o nuite subete ga oishii.","zh":""},{"ja":"今日の仕事は昼休みをぬいて忙しかった。","en":"Today''s work was busy except for the lunch break.","romaji":"Kyou no shigoto wa hiruyasumi o nuite isogashikatta.","zh":""},{"ja":"休暇の日をぬいて、毎日彼は働きます。","en":"He works every day except for the holidays.","romaji":"Kyuuka no hi o nuite, mainichi kare wa hatarakimasu.","zh":""}]',replace('**Short**: This is a way to express ''minus'' or ''except for'' some specific noun.\n\n**Formation**: Noun + ぬいて\n\n**Long**: The grammar point Noun + ぬいて is used when you want to exclude a certain noun from the whole or mention something about everything else except for a specific noun. It''s usually translated in English as ''minus'' or ''except for''. \n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nuku','～ぬく',NULL,NULL,'N1','[]','[{"ja":"彼は一日中本を読みぬく。","en":"He will read the book all day long.","romaji":"Kare wa ichinichijuu hon o yominuku.","zh":""},{"ja":"私はこのプロジェクトを終わらせぬく。","en":"I will finish this project completely.","romaji":"Watashi wa kono purojekuto o owarasenuku.","zh":""},{"ja":"彼女は毎日ジムに行き、エクササイズを終わりぬく。","en":"She goes to the gym every day and finishes her exercise completely.","romaji":"Kanojo wa mainichi jim ni iki, ekusasaizu o owari nuku.","zh":""},{"ja":"私たちはこのゲームを解きぬく。","en":"We will solve this game completely.","romaji":"Watashitachi wa kono geemu o tokinuku.","zh":""}]',replace('**Short**: Expresses the concept of doing something completely or thoroughly.\n\n**Formation**: Verb-stem + ぬく\n\n**Long**: ''Noun ぬく'' is a phrase that conveys the idea of doing an action thoroughly or completely. It demonstrates a determination to carry out a task until the end. While the formation commonly uses verbs, it does convey a meaning similar to the English phrase ''to do completely''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_no_ikan_da','Noun+のいかんだ',NULL,NULL,'N1','[]','[{"ja":"彼が来るのいかんで決めよう。","en":"Let''s decide depending on whether he comes or not.","romaji":"Kare ga kuru no ikan de kimeyou.","zh":""},{"ja":"試験の結果のいかんで留年が決まります。","en":"Whether you repeat a year or not depends on the test results.","romaji":"Shiken no kekka no ikan de ryuunen ga kimarimasu.","zh":""},{"ja":"天気のいかんでは、ピクニックをキャンセルします。","en":"I''ll cancel the picnic depending on the weather.","romaji":"Tenki no ikan de wa, pikunikku o kyanseru shimasu.","zh":""},{"ja":"彼の回答のいかんで、我々の次の行動が決まる。","en":"Our next action depends on his response.","romaji":"Kare no kaitou no ikan de, wareware no tsugi no koudou ga kimaru.","zh":""}]',replace('**Short**: Depends on; up to\n\n**Formation**: Noun + のいかんだ/Noun + のいかんでは\n\n**Long**: The のいかんだ(Noun no ikan da) grammar point is used to express that something depends on a particular situation or fact. It can be translated as ''Depends on'' or ''up to'' in English. The construction no ikan is usually used with nouns and naru verbs.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_no_ikan_de_wa','Noun のいかんでは',NULL,NULL,'N1','[]','[{"ja":"試験の結果のいかんでは、大学の入学許可を得られるかどうかが決まります。","en":"Whether you can get permission to enter university depends on the result of the exam.","romaji":"Shiken no kekka no ikan dewa, daigaku no nyuugaku kyoka o erareru ka douka ga kimarimasu.","zh":""},{"ja":"天気のいかんでは、ピクニックを延期するかもしれません。","en":"Depending on the weather, we might delay the picnic.","romaji":"Tenki no ikan dewa, pikunikku o enki suru kamoshiremasen.","zh":""},{"ja":"交通事情のいかんでは、遅れることがあります。","en":"Depending on the traffic conditions, I might be late.","romaji":"Koutsuujijou no ikan dewa, okureru koto ga arimasu.","zh":""},{"ja":"経済の状況のいかんでは、会社の将来は決まります。","en":"Depending on the state of the economy, the company''s future is determined.","romaji":"Keizai no joukyou no ikan dewa, kaisha no shourai wa kimarimasu.","zh":""}]',replace('**Short**: It depends on the Noun\n\n**Formation**: Noun + のいかんでは\n\n**Long**: The のいかんでは grammar point is used when you want to express that the outcome or decision hinges on the condition described in the noun preceding this phrase. It can be translated as ''depending on ___'' or ''it depends on ___'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_no_ikan_ni_kakawarazu','Noun のいかんにかかわらず',NULL,NULL,'N1','[]','[{"ja":"結果のいかんにかかわらず、彼は決定を後悔しなかった。","en":"Regardless of the outcome, he didn''t regret his decision.","romaji":"Kekka no ikan ni kakawarazu, kare wa kettei wo koukai shinakatta.","zh":""},{"ja":"年齢のいかんにかかわらず、どんな人でも学ぶことは可能です。","en":"Regardless of age, anyone can learn.","romaji":"Nenrei no ikan ni kakawarazu, donna hito demo manabu koto wa kanou desu.","zh":""},{"ja":"経験のいかんにかかわらず、始めることが大切です。","en":"Regardless of experience, it''s important to start.","romaji":"Keiken no ikan ni kakawarazu, hajimeru koto ga taisetsu desu.","zh":""},{"ja":"天候のいかんにかかわらず、ハイキングは予定通りに行われます。","en":"Regardless of the weather, the hiking will take place as scheduled.","romaji":"Tenkou no ikan ni kakawarazu, haikingu wa yotei doori ni okonawaremasu.","zh":""}]',replace('**Short**: Regardless of, irrespective of.\n\n**Formation**: Noun + のいかんにかかわらず\n\n**Long**: The phrase ''Noun のいかんにかかわらず'' is used to express that something is the case irrespective of a certain condition. It can be translated as ''regardless of'' or ''irrespective of'' in English. This phrase is used with nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_no_ikan_ni_yotte_wa','Noun のいかんによっては',NULL,NULL,'N1','[]','[{"ja":"天気のいかんによっては、ピクニックを延期しましょう。","en":"Depending on the weather, we should postpone the picnic.","romaji":"Tenki no ikan ni yotte wa, pikunikku o enki shimashou.","zh":""},{"ja":"試験の結果のいかんによっては、進学できます。","en":"You can go on to further education, depending on the result of the exam.","romaji":"Shiken no kekka no ikan ni yotte wa, shingaku dekimasu.","zh":""},{"ja":"状況のいかんによっては、早期退職を考えます。","en":"Depending on the situation, I will consider early retirement.","romaji":"Joukyou no ikan ni yotte wa, souki taishoku o kangaemasu.","zh":""},{"ja":"彼の反応のいかんによっては、私たちの次の行動を決めます。","en":"Depending on his reaction, we will decide our next move.","romaji":"Kare no hannou no ikan ni yotte wa, watashitachi no tsugi no koudou o kimemasu.","zh":""}]',replace('**Short**: Depending on the matter; depending on noun\n\n**Formation**: Noun + のいかんによっては\n\n**Long**: The phrase のいかんによっては (no ikan ni yotte wa) is used to express the concept of ''depending on the matter or situation''. It is used to indicate that the outcome may change based on the condition or quality of the noun (matter) in question.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_no_ikan_ni_yorazu','Noun のいかんによらず',NULL,NULL,'N1','[]','[{"ja":"試験の結果のいかんによらず、自分を信じ続けてください。","en":"Regardless of the test results, keep believing in yourself.","romaji":"Shiken no kekka no ikan ni yorazu, jibun o shinji tsudzukete kudasai.","zh":""},{"ja":"天気のいかんによらず、毎日、ジョギングをします。","en":"Regardless of the weather, I jog every day.","romaji":"Tenki no ikan ni yorazu, mainichi, jogingu o shimasu.","zh":""},{"ja":"彼の年齢のいかんによらず、彼は非常に経験豊富です。","en":"Regardless of his age, he is very experienced.","romaji":"Kare no nenrei no ikan ni yorazu, kare wa hijou ni keikenhoufu desu.","zh":""},{"ja":"国籍のいかんによらず、誰でもイベントに参加できます。","en":"Regardless of nationality, anyone can participate in the event.","romaji":"Kokuseki no ikan ni yorazu, daredemo ibento ni sanka dekimasu.","zh":""}]',replace('**Short**: Means ''regardless of'', ''irrespective of'', or ''no matter''\n\n**Formation**: Noun + のいかんによらず\n\n**Long**: The Noun のいかんによらず grammar point is used to express that something is happening, will occur, or is true, regardless of a particular situation or condition. It is often translated as ''irrespective of'', ''regardless of'', or ''no matter'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_no_gotoki_b','Noun のごとき Noun',NULL,NULL,'N1','[]','[{"ja":"彼は神のごとき存在だ。","en":"He is an existence like a god.","romaji":"Kare wa kami no gotoki sonzai da.","zh":""},{"ja":"彼女の美しさは花のごときものだ。","en":"Her beauty is like a flower.","romaji":"Kanojo no utsukushisa wa hana no gotoki mono da.","zh":""},{"ja":"彼は悪魔のごとき行動をした。","en":"He acted like a devil.","romaji":"Kare wa akuma no gotoki koudou o shita.","zh":""},{"ja":"この地方は春のごとき気候だ。","en":"This region has a climate like spring.","romaji":"Kono chiho wa haru no gotoki kiko da.","zh":""}]',replace('**Short**: Expresses ''like'' or ''as if''; something/someone resembles something else strongly.\n\n**Formation**: Noun1 + のごとき + Noun2\n\n**Long**: The のごとき pattern is used to convey the concept of ''just like'' or ''as if''. The comparison here is strong, indicating that the thing/person is very similar to or almost the same as the thing/person compared to. It is a bit archaic and thus is more often found in writings than in everyday conversation.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_no_koto_dakara','Noun のことだから',NULL,NULL,'N1','[]','[{"ja":"彼のことだから、きっと大丈夫だと思う。","en":"Because it''s him, I think it will certainly be fine.","romaji":"Kare no koto dakara, kitto daijoubu da to omou.","zh":""},{"ja":"この店のことだから、料理は美味しいはずです。","en":"Considering it''s this restaurant, the food should be delicious.","romaji":"Kono mise no koto dakara, ryouri wa oishii hazu desu.","zh":""},{"ja":"彼女のことだから、もうすぐ到着するでしょう。","en":"Since it''s her, she will probably arrive soon.","romaji":"Kanojo no koto dakara, mou sugu touchaku suru deshou.","zh":""},{"ja":"この会社のことだから、もうすぐ新製品が発表されるでしょう。","en":"Given this company, a new product will probably be announced soon.","romaji":"Kono kaisha no koto dakara, mou sugu shinseihin ga happyou sareru deshou.","zh":""}]',replace('**Short**: Because it is about ~, considering it''s ~\n\n**Formation**: Noun + のことだから\n\n**Long**: The のことだから grammar point is used to express an expectation or decision that is made specifically because of the person or thing mentioned. Usually it implies that the speaker is familiar with the character or typical behavior of the person or thing being talked about.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_no_kirai_ga_aru','Noun の 嫌いがある',NULL,NULL,'N1','[]','[{"ja":"彼は魚の嫌いがあるので、寿司を食べません。","en":"He has a dislike for fish, so he doesn''t eat sushi.","romaji":"Kare wa sakana no kirai ga aru node, sushi o tabemasen.","zh":""},{"ja":"彼女は高いところの嫌いがあるから、山登りはしない。","en":"She has a dislike for high places, so she doesn''t go mountain climbing.","romaji":"Kanojo wa takai tokoro no kirai ga aru kara, yamanobori wa shinai.","zh":""},{"ja":"私の父は人ごみの嫌いがあるので、混雑した場所には行かない。","en":"My father has a dislike for crowds, so he doesn''t go to crowded places.","romaji":"Watashi no chichi wa hitogomi no kirai ga aru node, konzatsu shita basho ni wa ikanai.","zh":""},{"ja":"子供の頃、私は野菜の嫌いがあったが、今は好きだ。","en":"When I was a child, I had a dislike for vegetables, but now I like them.","romaji":"Kodomo no koro, watashi wa yasai no kirai ga atta ga, ima wa suki da.","zh":""}]',replace('**Short**: Have a dislike for a particular Noun\n\n**Formation**: Noun + の嫌いがある\n\n**Long**: The grammar point ''Nounの嫌いがある'' is used to express a dislike for a particular thing, action or situation, indicated by the noun. This structure is somewhat formal or old-fashioned. In casual speech, people more commonly say ''Noun が嫌い''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_no_temae','Noun の手前',NULL,NULL,'N1','[]','[{"ja":"試験の手前、遊びに行くのはやめた方がいい。","en":"Just before the exam, it''s better to stop going out to play.","romaji":"Shiken no temae, asobi ni iku no wa yameta hou ga ii.","zh":""},{"ja":"彼女と別れる手前、思い直しました。","en":"Just before breaking up with her, I changed my mind.","romaji":"Kanojo to wakareru temae, omoinaoshimashita.","zh":""},{"ja":"締め切りの手前で、やっとレポートが完成しました。","en":"I finally finished the report just before the deadline.","romaji":"Shimekiri no temae de, yatto repooto ga kansei shimashita.","zh":""},{"ja":"選挙の手前、政治の話が多くなります。","en":"Just before the election, there will be a lot of political talk.","romaji":"Senkyo no temae, seiji no hanashi ga ooku narimasu.","zh":""}]',replace('**Short**: Expresses the idea of ''Before doing something; on the verge of''.\n\n**Formation**: Noun + の手前\n\n**Long**: This grammar point is used to express the idea of being on the verge of doing something, or just before some major action/event. Nouns that are frequently used with this structure often denote an action or event (試験の手前, 選挙の手前, etc.).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_no_kiwami','Noun の極み',NULL,NULL,'N1','[]','[{"ja":"彼の料理の極みは、誰もマネできない。","en":"The pinnacle of his cooking is something nobody can imitate.","romaji":"Kare no ryouri no kiwami wa, daremo mane dekinai.","zh":""},{"ja":"彼女の努力の極みが、この成功を作り出した。","en":"The extreme of her effort has created this success.","romaji":"Kanojo no doryoku no kiwami ga, kono seikou wo tsukuridashita.","zh":""},{"ja":"彼は音楽の極みを追求し続けている。","en":"He continues to pursue the pinnacle of music.","romaji":"Kare wa ongaku no kiwami o tsuikyuu shitsuzukete iru.","zh":""},{"ja":"この風景は美の極みだ。","en":"This scenery is the epitome of beauty.","romaji":"Kono fuukei wa bi no kiwami da.","zh":""}]',replace('**Short**: Used to express the extreme or utmost point of something.\n\n**Formation**: Noun + の極み\n\n**Long**: The の極み grammar point is used to express the highest level or the extreme of something. It often describes an extreme state or condition. The noun before の極み usually indicates some situation, state, or quality (e.g., 美の極み, 感動の極み).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_no_itari','Noun の 至り',NULL,NULL,'N1','[]','[{"ja":"彼の冗談には驚きの至りだ。","en":"His jokes are the height of surprise.","romaji":"Kare no joudan ni wa odoroki no itari da.","zh":""},{"ja":"父がプロジェクトのリーダーになったのは、光栄の至りです。","en":"It is the height of honor that my father became the project leader.","romaji":"Chichi ga purojekuto no riidaa ni natta no wa, kouei no itari desu.","zh":""},{"ja":"彼女の素晴らしい演技には感動の至りだった。","en":"Her wonderful performance was the height of emotion.","romaji":"Kanojo no subarashii engi ni wa kandou no itari datta.","zh":""},{"ja":"その失敗は恥ずかしさの至りだった。","en":"That failure was the height of embarrassment.","romaji":"Sono shippai wa hazukashisa no itari datta.","zh":""}]',replace('**Short**: Expresses ''the height of'', ''the extreme of'' something.\n\n**Formation**: Noun + の至り\n\n**Long**: The ''Nounの至り'' grammar point is used to emphasize an extreme or the highest level of something, often an emotional state or an honor. Common nouns include 光栄, 若気, 感激, 恥, etc.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wa_iza_shirazu','Noun はいざ知らず',NULL,NULL,'N1','[]','[{"ja":"彼が遅れるのはいざ知らず、彼女まで遅刻するとは意外だ。","en":"Well, I can understand him being late, but even her...? That''s surprising.","romaji":"Kare ga okureru no wa iza shirazu, kanojo made chikoku suru to wa igai da.","zh":""},{"ja":"夏はいざ知らず、冬にアイスクリームを食べるのは寒すぎませんか？","en":"I can see eating ice cream in summer, but in winter…isn''t it too cold?","romaji":"Natsu wa iza shirazu, fuyu ni aisukuriimu o taberu no wa samusugimasen ka?","zh":""},{"ja":"子供がテレビゲームに夢中になるのはいざ知らず、大人までそんなに夢中になるとは思わなかった。","en":"I can see why kids get hooked on video games, but I didn''t think even adults would get that absorbed.","romaji":"Kodomo ga terebi geemu ni muchuu ni naru no wa iza shirazu, otona made sonnani muchuu ni naru to wa omowanakatta.","zh":""},{"ja":"苦しい時はいざ知らず、平時でもそんなに努力するなんてすばらしい。","en":"Well, I can understand working hard in tough times, but to do so even in normal times is impressive.","romaji":"Kurushii toki wa iza shirazu, heiji demo sonnani doryoku suru nante subarashii.","zh":""}]',replace('**Short**: ‘I can understand it for ~, but for …? (surprising)’\n\n**Formation**: Noun + はいざ知らず, Noun + とは/なんて/しかし etc.\n\n**Long**: The はいざ知らず grammar point is used when contrasting two scenarios: the first being understandable, and the second being unexpected or surprising by comparison. It often translates as “Well, for A, I can understand, but for B…?!”\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wa_oroka_sura','Noun はおろか～すら',NULL,NULL,'N1','[]','[{"ja":"彼は走るはおろか、速く歩くことすらできない。","en":"He can''t even walk fast, let alone run.","romaji":"Kare wa hashiru wa oroka, hayaku aruku koto sura dekinai.","zh":""},{"ja":"日本語はおろか、英語さえ話しません。","en":"He doesn''t even speak English, let alone Japanese.","romaji":"Nihongo wa oroka, eigo sae hanashimasen.","zh":""},{"ja":"彼は食事はおろか、一日中何も飲まなかった。","en":"He didn''t even drink anything all day, let alone eat a meal.","romaji":"Kare wa shokuji wa oroka, ichinichijuu nani mo nomanakatta.","zh":""},{"ja":"このレストランは味はおろか、サービスさえ悪い。","en":"Never mind the taste; even the service is bad.","romaji":"Kono resutoran wa aji wa oroka, saabisu sae warui.","zh":""}]',replace('**Short**: Expresses ''not to mention ~, even ~''.\n\n**Formation**: Noun1 はおろか, Noun2 すら/さえ ～\n\n**Long**: The grammar point Noun はおろか～すら is used to emphasize that a particular statement applies not only to the first noun mentioned, but even more so to what comes after すら or さえ. It can be translated as ‘let alone ~, even ~’.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wa_oroka_made','Noun はおろか～まで',NULL,NULL,'N1','[]','[{"ja":"彼は英語はおろか、日本語までペラペラなんです。","en":"He is not just fluent in English, but even in Japanese.","romaji":"Kare wa eigo wa oroka, nihongo made perapera nan desu.","zh":""},{"ja":"彼女は数学はおろか、物理まで得意なんです。","en":"She is not just good at math, but even at physics.","romaji":"Kanojo wa suugaku wa oroka, butsuri made tokui nan desu.","zh":""},{"ja":"この料理は見た目はおろか、味まで最高だ。","en":"This dish is not only visually appealing, but it even tastes fantastic.","romaji":"Kono ryouri wa mitame wa oroka, aji made saikou da.","zh":""},{"ja":"彼は歌はおろか、ダンスまで上手だ。","en":"He is not just good at singing, but even at dancing.","romaji":"Kare wa uta wa oroka, dansu made umai da.","zh":""}]',replace('**Short**: Means ''not just A, but even B''; ''let alone A, even B''.\n\n**Formation**: Noun1 + はおろか + Noun2 + まで\n\n**Long**: The phrase ''Noun はおろか'' emphasizes something beyond the obvious. It can be translated as ''not only ..., but even ...''. The ''～まで'' part extends that idea further to show an unexpected or more advanced case.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wa_oroka_mo','Noun はおろか～も',NULL,NULL,'N1','[]','[{"ja":"絵を描くことはおろか、字さえ書けない。","en":"Needless to say drawing pictures, he can’t even write letters.","romaji":"E wo kaku koto wa oroka, ji sae kakenai.","zh":""},{"ja":"彼は英語はおろか、日本語もわからない。","en":"Needless to say English, he doesn’t even understand Japanese.","romaji":"Kare wa eigo wa oroka, nihongo mo wakaranai.","zh":""},{"ja":"彼女は数学はおろか、算数も得意ではない。","en":"Needless to say mathematics, she isn’t even good at arithmetic.","romaji":"Kanojo wa suugaku wa oroka, sansuu mo tokui dewa nai.","zh":""},{"ja":"彼は走ることはおろか、歩くことも難しい。","en":"Needless to say running, he finds even walking difficult.","romaji":"Kare wa hashiru koto wa oroka, aruku koto mo muzukashii.","zh":""}]',replace('**Short**: ''Not only...but also'', ''not to mention'', ''to say nothing of''\n\n**Formation**: Noun + はおろか + Noun + も\n\n**Long**: The ''Noun はおろか～も'' grammar point is used to list items with an emphasis on how far the situation extends. It often appears in negative contexts to show that something supposedly more advanced (first part) is out of the question, and even something simpler (second part) is also not possible. It can be translated as ''Needless to say X, (he/she) can''t even do Y.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wa_sateoki','Noun はさておき',NULL,NULL,'N1','[]','[{"ja":"試験の結果はさておき、この学期はとても学ぶことが多かった。","en":"Aside from the exam results, I learned a lot this semester.","romaji":"Shiken no kekka wa sateoki, kono gakki wa totemo manabu koto ga ookatta.","zh":""},{"ja":"天候はさておき、明日のピクニックは楽しみにしています。","en":"Putting aside the weather, I am looking forward to tomorrow''s picnic.","romaji":"Tenkou wa sateoki, ashita no pikunikku wa tanoshimi ni shiteimasu.","zh":""},{"ja":"彼の性格はさておき、彼のスキルは認めざるを得ない。","en":"Notwithstanding his personality, his skills are undeniable.","romaji":"Kare no seikaku wa sateoki, kare no sukiru wa mitomezaru wo enai.","zh":""},{"ja":"彼があまりにも遅いことはさておき、彼が来ると思われること自体が問題だ。","en":"Aside from him being late, the issue is that he is expected to come at all.","romaji":"Kare ga amari ni mo osoi koto wa sateoki, kare ga kuru to omowareru koto jitai ga mondai da.","zh":""}]',replace('**Short**: Means ''putting aside'', ''aside from'', ''notwithstanding''.\n\n**Formation**: Noun + はさておき\n\n**Long**: The grammar point ''Noun はさておき'' is used when highlighting something as an exception from an overall generalization, or when putting aside a particular matter before progressing to another point of discussion. The literal translation would be ''putting Noun aside'', ''aside from Noun'' or ''notwithstanding Noun.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wa_dou_de_are','Noun + はどうであれ',NULL,NULL,'N1','[]','[{"ja":"天候はどうであれ、試合は行われます。","en":"No matter what the weather is, the match will be held.","romaji":"Tenkou wa dou de are, shiai wa okonawaremasu.","zh":""},{"ja":"結果はどうであれ、最善を尽くすだけです。","en":"No matter what the result is, all we can do is try our best.","romaji":"Kekka wa dou de are, saizen wo tsukusu dake desu.","zh":""},{"ja":"あなたの意見はどうであれ、私は彼を信じます。","en":"No matter what your opinion is, I believe him.","romaji":"Anata no iken wa dou de are, watashi wa kare wo shinjimasu.","zh":""},{"ja":"試験の結果はどうであれ、あなたには何も変わりません。","en":"No matter what the result of the test is, nothing will change for you.","romaji":"Shiken no kekka wa dou de are, anata ni wa nani mo kawarimasen.","zh":""}]',replace('**Short**: This phrase means ''regardless of'' or ''no matter how…''.\n\n**Formation**: Noun + はどうであれ\n\n**Long**: It is used to convey indifference about the state or condition of a certain thing or matter. You can think of it as ''no matter what'' or ''regardless of'' in English. The phrase shows the speaker’s strong intention to do something or an assertion that doesn’t change regardless of the noun’s state or condition.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mamire','Noun まみれ',NULL,NULL,'N1','[]','[{"ja":"彼は泥まみれになって帰ってきた。","en":"He returned home covered in mud.","romaji":"Kare wa doro mamire ni natte kaette kita.","zh":""},{"ja":"彼女は涙まみれになりながら告白した。","en":"She confessed while crying her eyes out.","romaji":"Kanojo wa namida mamire ni narinagara kokuhaku shita.","zh":""},{"ja":"その事件後、彼はスキャンダルまみれになった。","en":"After that incident, he was completely embroiled in scandal.","romaji":"Sono jiken go, kare wa sukandaru mamire ni natta.","zh":""},{"ja":"この部屋は埃まみれだ。","en":"This room is covered in dust.","romaji":"Kono heya wa hokori mamire da.","zh":""}]',replace('**Short**: Expresses a state in which something is entirely covered or filled with something else.\n\n**Formation**: Noun + まみれ\n\n**Long**: The まみれ grammar point is used to express a state where someone or something is completely covered, smeared, or filled with another thing. The noun before まみれ indicates what the person or thing is covered in. This grammar point often has a negative connotation.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_a_mo_saru_koto_nagara_b_mo','Noun もさることながら Noun も',NULL,NULL,'N1','[]','[{"ja":"彼の歌唱力もさることながら、ダンスも素晴らしい。","en":"Not only his singing ability but also his dancing is wonderful.","romaji":"Kare no kashou-ryoku mo saru koto nagara, dansu mo subarashii.","zh":""},{"ja":"このレストラン、味もさることながら、サービスもすばらしい。","en":"At this restaurant, not only the taste but also the service is wonderful.","romaji":"Kono resutoran, aji mo saru koto nagara, saabisu mo subarashii.","zh":""},{"ja":"彼女の美しさもさることながら、その知性も魅力的だ。","en":"Not only her beauty but also her intelligence is attractive.","romaji":"Kanojo no utsukushisa mo saru koto nagara, sono chisei mo miryoku-teki da.","zh":""},{"ja":"その映画、ストーリーもさることながら、音楽も素晴らしかった。","en":"In that movie, not only the story but also the music was wonderful.","romaji":"Sono eiga, sutoorii mo saru koto nagara, ongaku mo subarashikatta.","zh":""}]',replace('**Short**: Means ''not only... but also''; the second noun is especially emphasized.\n\n**Formation**: Noun1 + もさることながら + Noun2 + も\n\n**Long**: The grammar point ''Noun もさることながら Noun も'' is used to express that both Nouns are true, important, or relevant. It can be translated as ''not only... but also'' in English. However, among the two nouns, the one coming after もさることながら is more emphasized in comparison to the one before it.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mo_kanete','Noun も兼ねて',NULL,NULL,'N1','[]','[{"ja":"散歩も兼ねて、公園に行きました。","en":"I went to the park, also for a walk.","romaji":"Sanpo mo kanete, kouen ni ikimashita.","zh":""},{"ja":"今日は日本語の勉強も兼ねて、日本の映画を見ます。","en":"Today, I will watch a Japanese movie, also to study Japanese.","romaji":"Kyou wa Nihongo no benkyou mo kanete, Nihon no eiga wo mimasu.","zh":""},{"ja":"仕事も兼ねて、海外に行く予定です。","en":"I plan to go abroad, also for work.","romaji":"Shigoto mo kanete, kaigai ni iku yotei desu.","zh":""},{"ja":"旅行も兼ねて、友人の結婚式に出席します。","en":"I will attend a friend''s wedding, also as a trip.","romaji":"Ryokou mo kanete, yuujin no kekkonshiki ni shusseki shimasu.","zh":""}]',replace('**Short**: Used to express ''as well as'', ''also'', or ''at the same time''.\n\n**Formation**: Noun + も兼ねて\n\n**Long**: The も兼ねて grammar point indicates that two actions or purposes are being served simultaneously. The noun before も兼ねて tells what the additional action or purpose is.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mo_aimatte','Noun も相まって',NULL,NULL,'N1','[]','[{"ja":"気候も相まって、この地域は農業に適しています。","en":"Combined with the climate, this area is suitable for agriculture.","romaji":"Kikou mo aimatte, kono chiiki wa nougyou ni tekishiteimasu.","zh":""},{"ja":"彼の才能も相まって、彼は急速に昇進した。","en":"Combined with his talent, he was rapidly promoted.","romaji":"Kare no sainou mo aimatte, kare wa kyuusoku ni shoushin shita.","zh":""},{"ja":"技術進歩も相まって、私たちはより効率的に仕事をこなすことができるようになりました。","en":"Combined with technological progress, we have become able to handle our work more efficiently.","romaji":"Gijutsu shinpo mo aimatte, watashitachi wa yori kouritsu-teki ni shigoto wo konasu koto ga dekiru you ni narimashita.","zh":""},{"ja":"彼の努力も相まって、プロジェクトは成功しました。","en":"Combined with his efforts, the project was successful.","romaji":"Kare no doryoku mo aimatte, purojekuto wa seikou shimashita.","zh":""}]',replace('**Short**: Used to express that combined with something else, it caused a certain outcome.\n\n**Formation**: Noun + も相まって\n\n**Long**: The grammar point Noun も相まって is used to express the meaning that, combined with something else, it caused a certain result. Literally, it translates to ''also contributes to''. It is generally used with nouns and points out that there are multiple contributing factors.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wo_oite_hoka_ni_nai','Noun を おいて他に Verb ない',NULL,NULL,'N1','[]','[{"ja":"この仕事を彼に任せる人をおいて他にいない。","en":"Apart from him, there''s no one else to entrust this job to.","romaji":"Kono shigoto wo kare ni makaseru hito wo oite hoka ni inai.","zh":""},{"ja":"この問題を解決できるのは彼をおいて他にいない。","en":"Apart from him, there''s no one else who can solve this problem.","romaji":"Kono mondai wo kaiketsu dekiru no wa kare o oite hoka ni inai.","zh":""},{"ja":"この地域で美味しい麺を作る店をおいて他にない。","en":"There is no other restaurant in this area that makes delicious noodles apart from this one.","romaji":"Kono chiiki de oishii men o tsukuru mise o oite hoka ni nai.","zh":""},{"ja":"彼女の歌声を超える歌手をおいて他にいない。","en":"There is no other singer who could surpass her singing voice.","romaji":"Kanojo no utagoe o koeru kashu o oite hoka ni inai.","zh":""}]',replace('**Short**: Means ''apart from ~ there''s nothing else,'' implying the Noun is the best or most suitable choice.\n\n**Formation**: Noun + をおいて他に + Verb negative form\n\n**Long**: The structure Nounをおいて他に〜ない is used to express that there is no substitute for the Noun, no other choice, or that the Noun is the best or the only one to choose among various options. This form is often used in praising or making strong positive comments about someone or something.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wo_motte','Noun をもって',NULL,NULL,'N1','[]','[{"ja":"彼は誠実さをもって人々に信頼されています。","en":"He is trusted by people with his honesty.","romaji":"Kare wa seijitsusa wo motte hitobito ni shinrai sarete imasu.","zh":""},{"ja":"この賞をもって、彼女の努力が認められました。","en":"With this award, her efforts were recognized.","romaji":"Kono shou wo motte, kanojo no doryoku ga mitomeraremashita.","zh":""},{"ja":"彼は強い決意をもって問題に取り組んだ。","en":"He tackled the problem with strong determination.","romaji":"Kare wa tsuyoi ketsui wo motte mondai ni torikunda.","zh":""},{"ja":"3月をもって、この店は閉店します。","en":"This store will close at the end of March.","romaji":"Sangatsu wo motte, kono mise wa heiten shimasu.","zh":""}]',replace('**Short**: Used to indicate means, methods, or time; ''with'', ''by means of'', ''at''.\n\n**Formation**: Noun + をもって\n\n**Long**: The をもって grammar is used to express a means or method to achieve something, or to indicate a point in time. It can be translated as ''with'' or ''by means of'' when indicating means, and ''at'' when indicating a point in time.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wo_mono_tomo_sezu_ni','Noun をものともせずに',NULL,NULL,'N1','[]','[{"ja":"彼女は怖さをものともせずに、暗闇の中へ進んで行った。","en":"Despite her fear, she went ahead into the darkness.","romaji":"Kanojo wa kowasa wo mono tomo sezu ni, kurayami no naka e susunde itta.","zh":""},{"ja":"試験のプレッシャーをものともせずに、彼は自信満々に答えた。","en":"Unfazed by the pressure of the exam, he answered with full confidence.","romaji":"Shiken no puresshaa wo mono tomo sezu ni, kare wa jishin manman ni kotaeta.","zh":""},{"ja":"彼は風雪をものともせずに山を登った。","en":"He climbed the mountain unfazed by the wind and snow.","romaji":"Kare wa fuusetsu wo mono tomo sezu ni, yama wo nobotta.","zh":""},{"ja":"彼は失敗をものともせずに、前に進み続けた。","en":"He continued to move forward, undeterred by failure.","romaji":"Kare wa shippai wo mono tomo sezu ni, mae ni susumi tsuzuketa.","zh":""}]',replace('**Short**: Expresses the idea that ''despite something, action was carried out'', translating to ''without being fazed by something''.\n\n**Formation**: Noun + をものともせずに\n\n**Long**: The ''Nounをものともせずに'' grammar point indicates that something which could potentially be a hindrance or challenge was not taken into account when carrying out an action. The literal idea is ‘not making something an obstacle’, meaning actions were performed without being fazed or distracted by it.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wo_yoso_ni','Noun をよそに',NULL,NULL,'N1','[]','[{"ja":"経済危機をよそに、彼は高級な車を買った。","en":"Despite the economic crisis, he bought a luxury car.","romaji":"Keizai kiki wo yoso ni, kare wa koukyuu na kuruma wo katta.","zh":""},{"ja":"試験が迫るをよそに、彼は遊び続けている。","en":"Despite the approaching test, he keeps on playing.","romaji":"Shiken ga semaru wo yoso ni, kare wa asobi tsuzukete iru.","zh":""},{"ja":"親の反対をよそに、彼女は彼と結婚しました。","en":"Despite her parents'' opposition, she married him.","romaji":"Oya no hantai wo yoso ni, kanojo wa kare to kekkon shimashita.","zh":""},{"ja":"その国の経済状況をよそに、多くの企業が進出し続けている。","en":"Despite the country''s economic situation, many companies continue to expand.","romaji":"Sono kuni no keizai joukyou wo yoso ni, ooku no kigyou ga shinshutsu shi tsuzukete iru.","zh":""}]',replace('**Short**: Despite; Notwithstanding; Regardless of\n\n**Formation**: Noun + をよそに\n\n**Long**: The Japanese phrase ''Nounをよそに'' is used to express a situation where, despite some circumstance (represented by the noun), a certain action takes place. It can convey a feeling of disregard or nonchalance. In English, it can be translated as ''despite'', ''notwithstanding'', or ''regardless of''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wo_yogi_naku_sareru','Noun を余儀なくされる',NULL,NULL,'N1','[]','[{"ja":"彼は経済的困難により、退学を余儀なくされた。","en":"Due to financial difficulties, he was forced to drop out of school.","romaji":"Kare wa keizai-teki konnan ni yori, taigaku wo yogi naku saremashita.","zh":""},{"ja":"厳しい天候によって、私たちは遠足を中止する余儀なくされた。","en":"We were forced to cancel the excursion due to the severe weather.","romaji":"Kibishi tenkou ni yotte, watashitachi wa ensoku wo chushi suru yogi naku sareta.","zh":""},{"ja":"怪我のため、彼は入院を余儀なくされた。","en":"Due to his injury, he was forced to be hospitalized.","romaji":"Kega no tame, kare wa nyuuin wo yogi naku sareta.","zh":""},{"ja":"リストラの恐怖により、多くの従業員が転職を余儀なくされた。","en":"Fear of layoffs forced many employees to change jobs.","romaji":"Risutora no kyoufu ni yori, ooku no juugyouin ga tenshoku wo yogi naku sareta.","zh":""}]',replace('**Short**: Expresses the idea of being forced into a certain situation, ''to be compelled'', ''to be obliged''.\n\n**Formation**: Noun + を + 余儀なくされる\n\n**Long**: The grammar pattern ''Noun を余儀なくされる'' is used to describe circumstances where a person or party is compelled or obliged to do something due to necessity or unavoidable circumstances. It translates as ''to be forced to'', ''to be compelled to'', or ''to have no choice but to''. This form is often used in formal or written Japanese.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wo_zentei_toshite','Noun を前提として',NULL,NULL,'N1','[]','[{"ja":"成功を前提として、ビジネスプランを作成しました。","en":"We made a business plan on the assumption of success.","romaji":"Seikou wo zentei toshite, bijinesu puran wo sakusei shimashita.","zh":""},{"ja":"彼の勝利を前提として、パーティーの準備を始めました。","en":"We started preparing for the party assuming his victory.","romaji":"Kare no shouri wo zentei toshite, paatii no junbi wo hajimemashita.","zh":""},{"ja":"両親の理解を前提として、旅行計画を進めます。","en":"I will proceed with the travel plan based on my parents’ understanding.","romaji":"Ryoushin no rikai wo zentei toshite, ryokou keikaku wo susumemasu.","zh":""},{"ja":"このプロジェクトは、資金が揃うことを前提としています。","en":"This project assumes that the funds will be in place.","romaji":"Kono purojekuto wa, shikin ga sorou koto wo zentei toshiteimasu.","zh":""}]',replace('**Short**: Used to express ''on the assumption of'', ''based on''.\n\n**Formation**: Noun + を前提として\n\n**Long**: The grammar point ''Noun を前提として'' is used to convey that something is done based on or assuming something else. It indicates a preconceived condition or assumption on which the following action or plan relies.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wo_zentei_ni_shite','Noun を前提にして',NULL,NULL,'N1','[]','[{"ja":"好天を前提にして、明日のピクニックの計画を立てました。","en":"We planned tomorrow''s picnic assuming fine weather.","romaji":"Kouten wo zentei ni shite, ashita no pikunikku no keikaku wo tatemashita.","zh":""},{"ja":"彼女の合格を前提にして、祝いのパーティーの準備を始めました。","en":"We started preparing for the celebration party assuming she would pass the exam.","romaji":"Kanojo no goukaku wo zentei ni shite, iwai no paatii no junbi wo hajimemashita.","zh":""},{"ja":"経済成長を前提にして、予算案が作られた。","en":"The budget was made on the assumption of economic growth.","romaji":"Keizai seichou wo zentei ni shite, yosan-an ga tsukurareta.","zh":""},{"ja":"彼の参加を前提にして、会議の日程を決めました。","en":"We decided the meeting schedule assuming his participation.","romaji":"Kare no sanka wo zentei ni shite, kaigi no nittei wo kimemashita.","zh":""}]',replace('**Short**: Assuming; presupposing; on the assumption of.\n\n**Formation**: Noun + を前提にして\n\n**Long**: The grammar point ''Noun を前提にして'' is used to show that something is done assuming or presupposing the noun that comes before it. In English, it can be translated as ''on the assumption of'', ''assuming'', or ''presupposing''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wo_sakai_ni_shite','Noun を境にして',NULL,NULL,'N1','[]','[{"ja":"父の死を境にして、彼の性格が一変した。","en":"His personality changed completely since his father''s death.","romaji":"Chichi no shi wo sakai ni shite, kare no seikaku ga ippen shita.","zh":""},{"ja":"試験を境にして、休暇を取る予定です。","en":"I plan to take a vacation after the exam.","romaji":"Shiken wo sakai ni shite, kyuka wo toru yotei desu.","zh":""},{"ja":"春を境にして、新しい生活を始めるつもりだ。","en":"I intend to start a new life from spring onwards.","romaji":"Haru wo sakai ni shite, atarashii seikatsu o hajimeru tsumori da.","zh":""},{"ja":"彼女は入学を境にして、ファッションに興味を持ち始めた。","en":"She began to take an interest in fashion from the time she entered school.","romaji":"Kanojo wa nyuugaku wo sakai ni shite, fasshon ni kyoumi o mochi hajimeta.","zh":""}]',replace('**Short**: Means ''as a turning point'', ''since (time)'', or ''from (time) on''.\n\n**Formation**: Noun + を境に(して)\n\n**Long**: The grammar point ''Noun を境にして'' is used to indicate a significant change or turning point marked by a specific event or time. It means that after this boundary, some situation changes or a new state begins.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wo_ki_ni_shite','Noun を機にして',NULL,NULL,'N1','[]','[{"ja":"引っ越しを機にして、家具を新しくしました。","en":"I took the opportunity of moving to get new furniture.","romaji":"Hikkoshi wo ki ni shite, kagu wo atarashiku shimashita.","zh":""},{"ja":"卒業を機にして、新しい仕事を探し始めた。","en":"I started looking for a new job on the occasion of graduation.","romaji":"Sotsugyou wo ki ni shite, atarashii shigoto wo sagashi hajimeta.","zh":""},{"ja":"このプロジェクトの失敗を機にして、会社全体の仕事のやり方を見直すことにした。","en":"We decided to review the way the entire company works, taking this project''s failure as an opportunity.","romaji":"Kono purojekuto no shippai wo ki ni shite, kaisha zentai no shigoto no yarikata wo minaosu koto ni shita.","zh":""},{"ja":"結婚を機にして、私たちは新しい町へ引っ越しました。","en":"We moved to a new town on the occasion of our marriage.","romaji":"Kekkon wo ki ni shite, watashitachi wa atarashii machi e hikkoshimashita.","zh":""}]',replace('**Short**: To take the opportunity to; taking the occasion to; on the occasion of.\n\n**Formation**: Noun + を機にして\n\n**Long**: The grammar pattern ''Noun を機にして'' expresses the idea of using a certain event or situation as an opportunity to do something else. It is often used when some change or new step is taken as a result of a specific event.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wo_kawakiri_ni_wo_kawakiri_ni_shite','Noun を皮切りに / を皮切りにして',NULL,NULL,'N1','[]','[{"ja":"彼はその論文を皮切りにして複数の研究を開始した。","en":"Starting with that thesis, he started multiple research projects.","romaji":"Kare wa sono ronbun o kawakiri ni shite fukusū no kenkyū o kaishi shita.","zh":""},{"ja":"彼女はこのコンペティションを皮切りにして彼女のダンスキャリアが飛躍的に成長した。","en":"Starting with this competition, her dance career drastically grew.","romaji":"Kanojo wa kono konpetishon o kawakiri ni shite kanojo no dansu kyaria ga hiyakuteki ni seichō shita.","zh":""},{"ja":"この映画を皮切りに、彼は人気俳優としての立場を確立した。","en":"Starting with this movie, he established his position as a popular actor.","romaji":"Kono eiga o kawakiri ni, kare wa ninki haiyū to shite no tachiba o kakuritsu shita.","zh":""},{"ja":"このプロジェクトを皮切りにして、会社は新たな方向性を示し始めた。","en":"Starting with this project, the company began to show a new direction.","romaji":"Kono purojekuto o kawakiri ni shite, kaisha wa arata na hōkōsei o shimeshi hajimeta.","zh":""}]',replace('**Short**: Used to indicate the starting point of some series of events or actions; ''starting with'', ''beginning with''.\n\n**Formation**: Noun + を皮切りに / を皮切りにして\n\n**Long**: The grammar point ''Noun を皮切りに / を皮切りにして'' is used to convey the idea of something beginning or starting with a certain event or action. This pattern is often used when the speaker wants to highlight the starting point of a series or string of events.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wo_kawakiri_ni_shite','Noun を皮切りにして',NULL,NULL,'N1','[]','[{"ja":"彼はその日を皮切りにして毎日ジムに通い始めました。","en":"Starting from that day, he began to go to the gym every day.","romaji":"Kare wa sono hi o kawakiri ni shite mainichi jimu ni kayoi hajimemashita.","zh":""},{"ja":"新年会を皮切りにして、今年はたくさんのイベントが開催されます。","en":"Starting with the New Year''s party, a lot of events will be held this year.","romaji":"Shinnenkai o kawakiri ni shite, kotoshi wa takusan no ibento ga kaisai saremasu.","zh":""},{"ja":"この映画を皮切りにして彼の人気は急上昇しました。","en":"Beginning with this movie, his popularity skyrocketed.","romaji":"Kono eiga o kawakiri ni shite kare no ninki wa kyūjōshō shimashita.","zh":""},{"ja":"東京を皮切りにして、彼の展示会は全国で開かれる予定です。","en":"Starting in Tokyo, his exhibitions are set to be held nationwide.","romaji":"Tōkyō o kawakiri ni shite, kare no tenjikai wa zenkoku de hirakareru yotei desu.","zh":""}]',replace('**Short**: Used to express ''Starting with'', ''Beginning with''\n\n**Formation**: Noun + を皮切りに (して)\n\n**Long**: ''Noun を皮切りにして'' is a Japanese grammatical form used when one wants to express that something begins with a certain event or action, then continues on in a sequence. It is the same as saying ''starting with...'' or ''beginning with...'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wo_kinjienai','Noun を禁じ得ない',NULL,NULL,'N1','[]','[{"ja":"この結果には驚きを禁じ得ない。","en":"I can''t help but be surprised at this result.","romaji":"Kono kekka ni wa odoroki o kinjienai.","zh":""},{"ja":"そのニュースを聞いて、彼の成功を祝福する気持ちを禁じ得ない。","en":"Hearing that news, I can''t help but feel the urge to celebrate his success.","romaji":"Sono nyūsu o kiite, kare no seikō o shukufuku suru kimochi o kinjienai.","zh":""},{"ja":"彼女の美しさには感動を禁じ得ない。","en":"I can''t help but be moved by her beauty.","romaji":"Kanojo no utsukushisa ni wa kandō o kinjienai.","zh":""},{"ja":"彼の話を聞いて、笑いを禁じ得ない。","en":"Hearing his story, I can''t help but laugh.","romaji":"Kare no hanashi o kiite, warai o kinjienai.","zh":""}]',replace('**Short**: ''Cannot help but do'', or ''inevitable''\n\n**Formation**: Noun + を禁じ得ない\n\n**Long**: The 〜を禁じ得ない (wo kinjienai) grammar point is used to express a situation or emotion that is so strong it can''t be helped or is inevitable. It is used with nouns to express an uncontrollable feeling or action.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wo_hete','Noun を経て',NULL,NULL,'N1','[]','[{"ja":"彼は苦労を経て成功を手に入れた。","en":"He achieved success through hardships.","romaji":"Kare wa kurō o hete seikō o te ni ireta.","zh":""},{"ja":"彼女はニューヨークを経て日本に帰国した。","en":"She returned to Japan via New York.","romaji":"Kanojo wa Nyūyōku o hete Nihon ni kikoku shita.","zh":""},{"ja":"私達は長い議論を経て決定を下した。","en":"We made a decision through a long discussion.","romaji":"Watashitachi wa nagai giron o hete kettei o kudashita.","zh":""},{"ja":"多くの修練を経て、彼は達人のレベルになった。","en":"Through a lot of training, he reached a master''s level.","romaji":"Ōku no shuren o hete, kare wa tatsujin no reberu ni natta.","zh":""}]',replace('**Short**: Expresses the idea of ''through'' or ''via''; going through some process or phase.\n\n**Formation**: Noun + を経て\n\n**Long**: The を経て grammar point is used to express the concept of going through some process, phase, place, or period of time as a means of achieving something or reaching some end point. It can be literally translated as ''through'' or ''via'' in English, and can be used both literally and metaphorically.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_wo_fumaete','Noun を踏まえて',NULL,NULL,'N1','[]','[{"ja":"過去の結果を踏まえて、新たな計画を立てました。","en":"Based on previous results, we have made a new plan.","romaji":"Kako no kekka o fumaete, aratana keikaku o tatemashita.","zh":""},{"ja":"現地の文化を踏まえて、プレゼンテーションを準備します。","en":"I will prepare a presentation taking into account the local culture.","romaji":"Genchi no bunka o fumaete, purezentēshon o junbi shimasu.","zh":""},{"ja":"教師の意見を踏まえて、規則を変更しました。","en":"We changed the rules in light of the teachers'' opinions.","romaji":"Kyōshi no iken o fumaete, kisoku o henkō shimashita.","zh":""},{"ja":"最新の研究結果を踏まえて、新しい薬が開発されました。","en":"Considering the latest research findings, a new medicine has been developed.","romaji":"Saishin no kenkyū kekka o fumaete, atarashii kusuri ga kaihatsu saremashita.","zh":""}]',replace('**Short**: Based on; taking into account; in light of\n\n**Formation**: Noun + を踏まえて\n\n**Long**: The verb 踏まえる (fumaeru) means ''to be based on'' or ''to take into consideration''. When ～を踏まえて is connected with a noun, it implies that actions or decisions are made based on or taking into account the noun. It also expresses looking at a situation from the standpoint of the noun before proceeding to the following action.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_wo_kagiri_ni','Noun を限りに',NULL,NULL,'N1','[]','[{"ja":"今年度を限りに、この大学での教授活動を終えるつもりです。","en":"I intend to end my teaching activities at this university as of this academic year.","romaji":"Konnendo o kagiri ni, kono daigaku de no kyouju katsudou o oeru tsumori desu.","zh":""},{"ja":"今日を限りに、タバコを吸うのをやめます。","en":"As of today, I will stop smoking.","romaji":"Kyou o kagiri ni, tabako o suu no o yamemasu.","zh":""},{"ja":"3月31日を限りに、会社を退職します。","en":"I will leave the company as of March 31.","romaji":"3-gatsu 31-nichi o kagiri ni, kaisha o taishoku shimasu.","zh":""},{"ja":"来週を限りに、この番組は終了します。","en":"This program will end as of next week.","romaji":"Raishuu o kagiri ni, kono bangumi wa shuuryou shimasu.","zh":""}]',replace('**Short**: Expresses the idea of ''as of'', ''with'', or ''from'', indicating the end of something or a point of change.\n\n**Formation**: Noun + を限りに\n\n**Long**: The grammar point Noun を限りに is used to indicate the end point of something or a point of change from that time onward. The noun preceding this expression usually refers to a point in time, signifying that something ends or changes starting at that point.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nami','Noun 並み',NULL,NULL,'N1','[]','[{"ja":"彼はプロのボクサー並みの力を持っています。","en":"He has power equivalent to a professional boxer.","romaji":"Kare wa puro no bokusaa nami no chikara o motte imasu.","zh":""},{"ja":"彼女の料理の腕前はレストラン並みです。","en":"Her cooking skills are like those of a restaurant.","romaji":"Kanojo no ryouri no udemae wa resutoran nami desu.","zh":""},{"ja":"このエリアの夏は砂漠並みの暑さです。","en":"The summer heat in this area is like a desert.","romaji":"Kono eria no natsu wa sabaku nami no atsusa desu.","zh":""},{"ja":"今日の仕事は社長並みの忙しさだった。","en":"Today''s work was as busy as a president''s.","romaji":"Kyou no shigoto wa shachou nami no isogashisa datta.","zh":""}]',replace('**Short**: Indicates ''like'' or ''as'' something or someone; ''equivalent to'', ''around''.\n\n**Formation**: Noun + 並み\n\n**Long**: The Noun 並み grammar point is used to show a comparison, often translated as ''like'' or ''equivalent to''. It can also indicate approximate quantity or extent, similar to ''around''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_noun_zentei_de','Noun + 前提で',NULL,NULL,'N1','[]','[{"ja":"説明できる英語力がある前提で、この仕事を引き受けてください。","en":"Please take on this job on the assumption that you have enough English skills to explain.","romaji":"Setsumei dekiru eigo-ryoku ga aru zentei de, kono shigoto o hikiukete kudasai.","zh":""},{"ja":"彼が一緒に行く前提で、旅行の計画を立てました。","en":"I planned the trip on the assumption that he would go together.","romaji":"Kare ga issho ni iku zentei de, ryokou no keikaku o tatemashita.","zh":""},{"ja":"成功する前提で、このプロジェクトを進めています。","en":"We are moving forward with this project on the assumption that we will succeed.","romaji":"Seikou suru zentei de, kono purojekuto o susumete imasu.","zh":""},{"ja":"雨が降らない前提で、ピクニックの準備をしました。","en":"I prepared for the picnic under the condition that it wouldn''t rain.","romaji":"Ame ga furanai zentei de, pikunikku no junbi o shimashita.","zh":""}]',replace('**Short**: Expresses a condition or requirement for something to be established: ''on the assumption that'', ''under the condition of''.\n\n**Formation**: Noun + 前提で\n\n**Long**: The Noun + 前提で grammar point is used to define the premise, assumption, or requirement necessary for some event or action. It translates to ''on the assumption that'', ''under the condition of'', or ''with the understanding that''. The following clause is based on that premise.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_noun_kagiri_wa','Verbる / Noun(である) + 限り(は) (kagiri (wa))',NULL,NULL,'N1','[]','[{"ja":"私が生きている限りは、あなたを支えます。","en":"As long as I''m alive, I will support you.","romaji":"Watashi ga ikite iru kagiri wa, anata o sasaemasu.","zh":""},{"ja":"子供が学校に通っている限り、私たちは彼らを守ります。","en":"As long as the kids are going to school, we will protect them.","romaji":"Kodomo ga gakkou ni kayotte iru kagiri, watashitachi wa karera o mamorimasu.","zh":""},{"ja":"能力がある限り、最善を尽くします。","en":"I will do my best as long as I have the ability.","romaji":"Nouryoku ga aru kagiri, saizen o tsukushimasu.","zh":""},{"ja":"あなたがここにいる限り、私は安心です。","en":"As long as you''re here, I feel safe.","romaji":"Anata ga koko ni iru kagiri, watashi wa anshin desu.","zh":""}]',replace('**Short**: Expresses ''as long as'', ''while this condition is true''.\n\n**Formation**: Verb-dictionary form + 限り(は)\nNoun(である) + 限り(は)\n\n**Long**: This grammar is used to express that something holds true as long as a particular condition remains in effect. When using a noun, it can appear as Noun(である) + 限り(は). With a verb, use the dictionary form + 限り(は).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_gatera','Verb がてら',NULL,NULL,'N1','[]','[{"ja":"散歩がてらに郵便局へ行った。","en":"I went to the post office while taking a walk.","romaji":"Sanpo gatera ni yūbinkyoku e itta.","zh":""},{"ja":"買い物がてらに友達に会いに行った。","en":"I went to see a friend while doing some shopping.","romaji":"Kaimono gatera ni tomodachi ni ai ni itta.","zh":""},{"ja":"ジョギングがてらに新聞を買いに行った。","en":"I went to buy a newspaper while jogging.","romaji":"Jogingu gatera ni shinbun o kai ni itta.","zh":""},{"ja":"公園でピクニックがてら読書をした。","en":"I read a book while having a picnic in the park.","romaji":"Kōen de pikunikku gatera dokusho o shita.","zh":""}]',replace('**Short**: Expresses doing something while doing another; ''while'', ''on the occasion of''.\n\n**Formation**: Verb (dictionary or -ます stem) + がてら\n\n**Long**: The ～がてら grammar point is used to express doing something else in the middle of or on the occasion of another activity. Often used with verbs of movement or activities that easily combine with a second action.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_koso_sure_n1_2','Verb こそすれ',NULL,NULL,'N1','[]','[{"ja":"彼は友達を助けこそすれ、自分を卑下することはありません。","en":"He might help his friends, but he never belittles himself.","romaji":"Kare wa tomodachi o tasuke koso sure, jibun o higesuru koto wa arimasen.","zh":""},{"ja":"彼女は料理こそすれ、掃除はほとんどしない。","en":"She might cook, but she rarely cleans.","romaji":"Kanojo wa ryōri koso sure, sōji wa hotondo shinai.","zh":""},{"ja":"私の兄は勉強こそすれ、遊ぶ時間がほとんどない。","en":"He might study a lot, but he barely has time to have fun.","romaji":"Watashi no ani wa benkyō koso sure, asobu jikan ga hotondo nai.","zh":""},{"ja":"母は働きこそすれ、自分のために時間を使うことはほとんどない。","en":"My mother might work a lot, but she hardly spends any time on herself.","romaji":"Haha wa hataraki koso sure, jibun no tame ni jikan o tsukau koto wa hotondo nai.","zh":""}]',replace('**Short**: Often used in the pattern ''Xこそすれ、Y〜ない'', meaning ''One might do X, but definitely not Y''.\n\n**Formation**: Verb-ますstem + こそすれ、(絶対に)～ない\n\n**Long**: Verb-ますstem + こそすれ is typically used to emphasize that while someone might certainly do or be X, there''s no way they would do or be Y. The sentence that follows is usually a strong negative, denying the possibility of Y.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_saserareru','Verb させられる',NULL,NULL,'N1','[]','[{"ja":"彼に無理やり飲ませられた。","en":"He forced me to drink against my will.","romaji":"Kare ni muriyari nomaserareta.","zh":""},{"ja":"私は父に勉強させられました。","en":"My father made me study.","romaji":"Watashi wa chichi ni benkyō saseraremashita.","zh":""},{"ja":"子供たちは毎日ピアノを弾かせられる。","en":"The kids are made to play the piano every day.","romaji":"Kodomo-tachi wa mainichi piano o hikaserareru.","zh":""},{"ja":"私たちは強制的に早起きさせられました。","en":"We were forcibly made to wake up early.","romaji":"Watashitachi wa kyōsei-teki ni hayaoki saseraremashita.","zh":""}]',replace('**Short**: Expresses ''being forced to do something'' or ''being made to do something''.\n\n**Formation**: Verb-casual (non-past) + させられる\n\n**Long**: The させられる grammar point is used to express the passive causative form in Japanese. This form is used when you are forced or made to do something by someone or something else. It''s a combination of causative and passive form, and it often implies having been made to do something against one''s will.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_zaru_wo_enai_n1','Verb ざるを得ない',NULL,NULL,'N1','[]','[{"ja":"この仕事が嫌ならもう辞めざるを得ない。","en":"If you hate this job, you have no choice but to quit.","romaji":"Kono shigoto ga iya nara mō yamezaru o enai.","zh":""},{"ja":"試験が近いので、夜遅くまで勉強せざるを得ない。","en":"The exam is near, so I have no choice but to study late into the night.","romaji":"Shiken ga chikai no de, yoru osoku made benkyō sezaru o enai.","zh":""},{"ja":"涙が止まらない。泣かざるを得ない。","en":"My tears won''t stop. I can''t help but cry.","romaji":"Namida ga tomaranai. Nakazaru o enai.","zh":""},{"ja":"先生の命令だから、従わざるを得ない。","en":"It''s the teacher''s order, so I have no choice but to comply.","romaji":"Sensei no meirei dakara, shitagawazaru o enai.","zh":""}]',replace('**Short**: ''Cannot but'', ''have no choice but to'', ''forced to''\n\n**Formation**: Verb-dictionary form + ざるを得ない (する → せざるを得ない)\n\n**Long**: The Verb ざるを得ない construction is used when the subject is compelled or forced to do something out of necessity, leaving no other choice. It conveys the idea of ''cannot but...'' or ''have no choice but...'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_zu_jimai','Verb ずじまい',NULL,NULL,'N1','[]','[{"ja":"日本へ来たのに、一度も富士山を見ずじまいで帰国してしまった。","en":"I came to Japan but ended up going home without ever getting to see Mt. Fuji.","romaji":"Nihon e kita noni, ichidomo Fuji-san o mizu jimai de kikoku shite shimatta.","zh":""},{"ja":"出張のため、彼女に会わずじまいだった。","en":"Because I was on a business trip, I ended up not meeting her.","romaji":"Shucchō no tame, kanojo ni awazu jimai datta.","zh":""},{"ja":"昨日は疲れすぎて、宿題をせずじまいだ。","en":"I was too tired yesterday and ended up not doing my homework.","romaji":"Kinō wa tsukare-sugite, shukudai o sezu jimai da.","zh":""},{"ja":"着物を買ったが、結局、一度も着ずじまいだ。","en":"I bought a kimono, but in the end, I never got the chance to wear it.","romaji":"Kimono o katta ga, kekkyoku, ichido mo kizu jimai da.","zh":""}]',replace('**Short**: Expressing regret for not having done something; not being able to; missing the chance to do it.\n\n**Formation**: Verb-ない form (remove ない) + ずじまい\n\n**Long**: The grammar point ～ずじまい (~zu jimai) is used to express regret for not doing something, not being able to do it, or not getting the chance to do it. It highlights an action that ultimately never happened, despite intentions or opportunities.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_zu_tomo','Verb ずとも',NULL,NULL,'N1','[]','[{"ja":"朝ごはんを食べずとも、働くことができます。","en":"Even without eating breakfast, I can work.","romaji":"Asagohan o tabezu tomo, hataraku koto ga dekimasu.","zh":""},{"ja":"車がなくとも、バスで行くことができます。","en":"Even without a car, you can go by bus.","romaji":"Kuruma ga nakutomo, basu de iku koto ga dekimasu.","zh":""},{"ja":"お金がなくとも、幸せになれる。","en":"Even without money, one can be happy.","romaji":"Okane ga nakutomo, shiawase ni nareru.","zh":""},{"ja":"インターネットがなくとも、情報を得る方法はいくつかあります。","en":"Even without the internet, there are several ways to obtain information.","romaji":"Intānetto ga nakutomo, jōhō o eru hōhō wa ikutsu ka arimasu.","zh":""}]',replace('**Short**: Means ''Even without doing (X), (Y) can still happen''.\n\n**Formation**: Verb-negative stem + ずとも\n\n**Long**: The ～ずとも grammar point is used to express that, even if something isn''t done, the desired result can still be achieved or the situation remains unaffected. It can be translated as ''even without'' or ''even if not''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_zuni_wa_okanai','Verb ずにはおかない',NULL,NULL,'N1','[]','[{"ja":"彼が困っていると聞いたら、助けずにはおかない。","en":"If I hear he is in trouble, I cannot help but assist him.","romaji":"Kare ga komatte iru to kiitara, tasukezuni wa okanai.","zh":""},{"ja":"食事の準備がこのままだと、手伝わずにはおかないだろう。","en":"If the meal prep stays like this, I won''t be able to stop myself from helping.","romaji":"Shokuji no junbi ga kono mama da to, tetsudawazuni wa okanai darō.","zh":""},{"ja":"この問題が解決しないなら、改善策を考えずにはおかない。","en":"If this issue isn''t resolved, I can''t help but think of a solution.","romaji":"Kono mondai ga kaiketsu shinai nara, kaizen-saku o kangaezuni wa okanai.","zh":""},{"ja":"彼女が泣いているのを見たら、慰めずにはおかない。","en":"When I see her crying, I cannot help but comfort her.","romaji":"Kanojo ga naite iru no o mitara, nagusamezuni wa okanai.","zh":""}]',replace('**Short**: Expresses ''cannot help but...'', ''will definitely...'', or ''must do something''.\n\n**Formation**: Verb-ない form (remove ない) + ずにはおかない\n\n**Long**: The ずにはおかない grammar point conveys the sentiment of an inevitable action or a strong emotional compulsion. It can mean ''I can’t let it pass without doing X'' or ''I definitely will do X''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_zuni_wa_sumanai','Verb ずにはすまない',NULL,NULL,'N1','[]','[{"ja":"この問題を解決しないと、社会全体が影響を受けるので、解決せずにはすまない。","en":"Since this issue will affect the entire society if not resolved, we cannot do without solving it.","romaji":"Kono mondai o kaiketsu shinai to, shakai zentai ga eikyō o ukeru node, kaiketsu sezu ni wa sumanai.","zh":""},{"ja":"これは子供たちの未来を思うと、教育改革を行わずにはすまないことだ。","en":"For the sake of the children’s future, we cannot avoid carrying out educational reforms.","romaji":"Kore wa kodomo-tachi no mirai o omou to, kyōiku kaikaku o okonawazu ni wa sumanai koto da.","zh":""},{"ja":"この件については、彼に謝らずにはすまない。","en":"Regarding this matter, I can’t do without apologizing to him.","romaji":"Kono ken ni tsuite wa, kare ni ayamarazu ni wa sumanai.","zh":""},{"ja":"結婚式に出席するなら、プレゼントを渡さずにはすまない。","en":"If you attend a wedding, you have to bring a gift.","romaji":"Kekkonshiki ni shusseki suru nara, purezento o watasazu ni wa sumanai.","zh":""}]',replace('**Short**: ''Cannot do without...'', ''unavoidable'', ''have to''.\n\n**Formation**: Verb-ない form (remove ない) + ずにはすまない\n\n**Long**: The grammar point ずにはすまない is used when something must be done due to social/moral obligation, necessity, or rules. It implies that there is no way around taking that action.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_sou_ni_nai','Verb そうにない',NULL,NULL,'N1','[]','[{"ja":"彼はそんなに早く走れそうにない。","en":"He doesn''t seem likely to run that fast.","romaji":"Kare wa sonna ni hayaku hashire sō ni nai.","zh":""},{"ja":"この書類を明日までに終わりそうにない。","en":"It doesn’t seem like I’ll be able to finish these documents by tomorrow.","romaji":"Kono shorui o ashita made ni owarisō ni nai.","zh":""},{"ja":"今日雨が降りそうにない。","en":"It doesn''t look like it will rain today.","romaji":"Kyō ame ga furisō ni nai.","zh":""},{"ja":"彼女は間違えそうにない。","en":"She doesn’t seem likely to make a mistake.","romaji":"Kanojo wa machigae sō ni nai.","zh":""}]',replace('**Short**: Expresses unlikelihood or that something does not seem likely to happen.\n\n**Formation**: Verb-ますstem + そうにない\n\n**Long**: The そうにない grammar point is typically formed from the verb’s ます-stem plus そうにない, and is used to express that something seems unlikely to happen or that someone seems unlikely to do something.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sou_mo_nai','Verb そうもない',NULL,NULL,'N1','[]','[{"ja":"今日中に仕事を終えそうもない。","en":"It doesn''t seem like I''ll finish my work today.","romaji":"Kyōjū ni shigoto o oesō mo nai.","zh":""},{"ja":"雨が止みそうもない。","en":"It doesn''t seem like the rain will stop.","romaji":"Ame ga yamisō mo nai.","zh":""},{"ja":"彼が約束を守りそうもない。","en":"It doesn''t seem like he will keep his promise.","romaji":"Kare ga yakusoku o mamorisō mo nai.","zh":""},{"ja":"この難しい問題は解決しそうもない。","en":"It doesn''t seem like this difficult problem will be solved.","romaji":"Kono muzukashii mondai wa kaiketsu shisō mo nai.","zh":""}]',replace('**Short**: Expresses negative potential; ''it doesn''t seem like...'', ''it''s not likely...''.\n\n**Formation**: Verb-ますstem + そうもない\n\n**Long**: ～そうもない is used to express a low possibility or unlikelihood of something happening. It is typically attached to the ます-stem of a verb, similar to そうにない but with an even stronger sense of improbability in many contexts.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_soba_kara','Verb そばから',NULL,NULL,'N1','[]','[{"ja":"掃除をするそばから子供たちが散らかす。","en":"As soon as I clean, the kids mess it up.","romaji":"Sōji o suru soba kara kodomo-tachi ga chirakasu.","zh":""},{"ja":"仕事を終えるそばから新たな仕事が舞い込んできた。","en":"As soon as I finished my work, a new task came in.","romaji":"Shigoto o oeru soba kara aratana shigoto ga maikonde kita.","zh":""},{"ja":"それを解決するそばからまた別の問題が出てきた。","en":"As soon as we solve that, another problem arises.","romaji":"Sore o kaiketsu suru soba kara mata betsu no mondai ga detekita.","zh":""},{"ja":"眠りにつくそばから電話が鳴った。","en":"The phone rang as soon as I fell asleep.","romaji":"Nemuri ni tsuku soba kara denwa ga natta.","zh":""}]',replace('**Short**: Expresses that as soon as one action finishes, another begins immediately.\n\n**Formation**: Verb-ますstem + そばから\n\n**Long**: The 〜そばから grammar point is used to indicate that right after a certain action is completed, another action takes place—often suggesting a repetitive or frustrating cycle.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ta_ga_saigo','Verb たが最後',NULL,NULL,'N1','[]','[{"ja":"彼が一度怒ったが最後、誰も彼を止めることはできません。","en":"Once he gets angry, no one can stop him.","romaji":"Kare ga ichido okotta ga saigo, dare mo kare o tomeru koto wa dekimasen.","zh":""},{"ja":"このゲームを始めたが最後、一晩中やり続けた。","en":"As soon as I started this game, I played it all night.","romaji":"Kono gēmu o hajimeta ga saigo, hitobanjū yari tsuzuketa.","zh":""},{"ja":"彼女が部屋を出たが最後、二度と戻ってこなかった。","en":"The moment she left the room, she never came back.","romaji":"Kanojo ga heya o deta ga saigo, nido to modotte konakatta.","zh":""},{"ja":"私がその橋を渡ったが最後、それが最後の別れだった。","en":"Once I crossed that bridge, it was our final goodbye.","romaji":"Watashi ga sono hashi o watatta ga saigo, sore ga saigo no wakare datta.","zh":""}]',replace('**Short**: Emphasizes ''once something happens, there is no going back''; ''once'', ''as soon as'', etc.\n\n**Formation**: Verb-casual, past (た form) + が最後\n\n**Long**: The 〜たが最後 grammar point indicates that once an action is taken or event occurs, some (often irreversible) consequence follows. In English, it can be translated as ''once'', ''as soon as'', or ''the moment that...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ta_koto_ni_shite_kudasai','Verb たことにしてください',NULL,NULL,'N1','[]','[{"ja":"昨日のことは忘れたことにしてください。","en":"Please act as if you have forgotten about yesterday.","romaji":"Kinou no koto wa wasureta koto ni shite kudasai.","zh":""},{"ja":"私がここに来たことを誰にも言わないで、秘密にしたことにしてください。","en":"Please don''t tell anyone that I came here; act as if it’s a secret.","romaji":"Watashi ga koko ni kita koto o dare ni mo iwanaide, himitsu ni shita koto ni shite kudasai.","zh":""},{"ja":"彼が間違えたと思ったことにしてください。","en":"Please pretend that you think he made a mistake.","romaji":"Kare ga machigaeta to omotta koto ni shite kudasai.","zh":""},{"ja":"彼女が帰ったことにしてください。","en":"Let’s pretend that she has gone home.","romaji":"Kanojo ga kaetta koto ni shite kudasai.","zh":""}]',replace('**Short**: Asking someone to pretend or accept that something has already happened or taken a certain state.\n\n**Formation**: Verb (past, casual) + ことにしてください\n\n**Long**: The grammar point ''Verb たことにしてください'' is used to request someone to act as if or pretend that a certain action has already occurred or a certain state exists. It is used in various contexts to express the idea of accepting a hypothetical situation for convenience or to avoid conflicts.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tara_tade','Verb たら Verb たで',NULL,NULL,'N1','[]','[{"ja":"行ったら行ったで大変だし、行かなかったら行かなかったで後悔しそうだ。","en":"If I go, it’s a hassle; if I don’t go, I’ll regret it.","romaji":"Ittara itta de taihen da shi, ikanakattara ikanakatta de kōkai shisō da.","zh":""},{"ja":"買ったら買ったでお金がなくなるし、買わなかったら買わなかったで後で欲しくなる。","en":"If I buy it, I’ll run out of money; if I don’t buy it, I’ll want it later.","romaji":"Kattara katta de okane ga naku naru shi, kawanakattara kawanakatta de ato de hoshiku naru.","zh":""},{"ja":"作ったら作ったで食べきれないし、作らなかったら作らなかったでお腹が空く。","en":"If I cook, I can’t finish it all; if I don’t, I’ll be hungry.","romaji":"Tsukuttara tsukutta de tabekirenai shi, tsukuranakattara tsukuranakatta de onaka ga suku.","zh":""},{"ja":"旅行に出かけたら出かけたで疲れるし、家にいたらいたで退屈する。","en":"If I go on a trip, I''ll get tired, but if I stay home, I''ll be bored.","romaji":"Ryokō ni dekaketara dekaketa de tsukareru shi, ie ni itara itada de taikutsu suru.","zh":""}]',replace('**Short**: Conveys that if something happens (or doesn’t happen), there is a particular consequence or situation either way.\n\n**Formation**: Verb-た form + ら + (same Verb-た form) + で\n\n**Long**: The pattern VerbたらVerbたで is used for scenarios where doing something creates a certain issue or reaction, and not doing it also creates a different concern. It often shows that no matter which side of the condition you end up on, there’s some related result or trouble.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_tara_kiri_ga_nai','Verb たら きりがない',NULL,NULL,'N1','[]','[{"ja":"このエンジンを修理したら、またすぐ壊れて、直したらきりがない。","en":"If I fix this engine, it breaks again, and if I fix it again, it never ends.","romaji":"Kono enjin o shuuri shitara, mata sugu kowarete, naoshitara kiri ga nai.","zh":""},{"ja":"飲み始めたらきりがない。","en":"Once I start drinking, I never stop.","romaji":"Nomihajimetara kiri ga nai.","zh":""},{"ja":"彼女にお金を貸したら、きりがない。","en":"If I lend her money, there will be no end to it.","romaji":"Kanojo ni okane o kashitara, kiri ga nai.","zh":""},{"ja":"彼の話を聞き始めたらきりがない。","en":"Once you start listening to his stories, it never ends.","romaji":"Kare no hanashi o kikihajimetara kiri ga nai.","zh":""}]',replace('**Short**: Indicates an endless or unending cycle once an action is started; ''if one starts doing something, it will not stop.''\n\n**Formation**: Verb-た form + ら + きりがない\n\n**Long**: The たらきりがない grammar pattern is used when something negative or undesirable continues indefinitely once it begins. The implication is that you should avoid initiating the action because it’ll just go on and on.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tara_saigo','Verb たら最後',NULL,NULL,'N1','[]','[{"ja":"このゲームを始めたら最後、時間の経つのを忘れてしまいます。","en":"Once you start this game, you completely lose track of time.","romaji":"Kono gēmu o hajimetara saigo, jikan no tatsu no o wasurete shimaimasu.","zh":""},{"ja":"彼はビールを一杯飲み始めたら最後、止まらなくなります。","en":"Once he starts drinking a beer, he can''t stop.","romaji":"Kare wa bīru o ippai nomihajimetara saigo, tomaranaku narimasu.","zh":""},{"ja":"この本を読み始めたら最後、一気に読破してしまいました。","en":"Once I started reading this book, I ended up finishing it in one go.","romaji":"Kono hon o yomihajimetara saigo, ikki ni dokuha shite shimaimashita.","zh":""},{"ja":"彼を怒らせたら最後、なかなか許してもらえないよ。","en":"Once you make him angry, he won''t forgive you so easily.","romaji":"Kare o okorasetara saigo, nakanaka yurushite moraenai yo.","zh":""}]',replace('**Short**: Expresses that once a certain action happens, the situation changes irreversibly—usually in a negative way.\n\n**Formation**: Verb-た form + ら最後\n\n**Long**: The たら最後 grammar point indicates that once an action (in た-form) occurs, there is no going back and an unpleasant or unavoidable state follows. Often translated as ''once...then it''s all over'' or ''the moment...there’s no turning back.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_tsu_verb_tsu','Verb つ Verb つ',NULL,NULL,'N1','[]','[{"ja":"朝から晩まで働きつ勉強しつで、疲れてしまった。","en":"I’ve been working and studying from morning till night, and now I’m exhausted.","romaji":"Asa kara ban made hataraki tsu benkyō shi tsu de, tsukarete shimatta.","zh":""},{"ja":"彼は話しつ笑いつして楽しんでいた。","en":"He was talking and laughing, having a good time.","romaji":"Kare wa hanashi tsu warai tsu shite tanoshinde ita.","zh":""},{"ja":"子供たちは食べつ遊びつしていた。","en":"The children were eating and playing.","romaji":"Kodomo-tachi wa tabe tsu asobi tsu shite ita.","zh":""},{"ja":"私は読みつ書きつして過ごした。","en":"I spent my time reading and writing.","romaji":"Watashi wa yomi tsu kaki tsu shite sugoshita.","zh":""}]',replace('**Short**: Expresses two alternating actions happening repeatedly.\n\n**Formation**: Verb-ますstem + つ + Verb-ますstem + つ\n\n**Long**: The 〜つ〜つ pattern is used with two verb ます-stems to express two ongoing, repeated or alternating actions. For example, ''push and pull,'' ''go and come back,'' ''eat and play,'' etc. The same subject is typically implied for both verbs.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te_kara_to_iu_mono','Verb てからというもの',NULL,NULL,'N1','[]','[{"ja":"彼女と別れてからというもの、一人で過ごす時間が増えました。","en":"Ever since I broke up with her, I''ve spent more time alone.","romaji":"Kanojo to wakarete kara to iu mono, hitori de sugosu jikan ga fuemashita.","zh":""},{"ja":"子供が生まれてからというもの、自由な時間がなくなった。","en":"Since the baby was born, I have had no free time.","romaji":"Kodomo ga umarete kara to iu mono, jiyū na jikan ga nakunatta.","zh":""},{"ja":"新しい仕事を始めてからというもの、毎日忙しくなりました。","en":"Ever since I started my new job, I''ve been busy every day.","romaji":"Atarashii shigoto o hajimete kara to iu mono, mainichi isogashiku narimashita.","zh":""},{"ja":"大学に入ってからというもの、スポーツをする時間がなくなった。","en":"I haven’t had time to play sports since I entered university.","romaji":"Daigaku ni haitte kara to iu mono, supōtsu o suru jikan ga nakunatta.","zh":""}]',replace('**Short**: Expresses that ever since a certain event happened, a condition has continued until now.\n\n**Formation**: Verb-て form + からというもの\n\n**Long**: The てからというもの grammar point indicates that from the time a certain action happened, a significant change or condition has persisted continuously. It emphasizes that the new situation contrasts with what came before.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te_koso','Verb てこそ',NULL,NULL,'N1','[]','[{"ja":"実際に使ってこそ、その価値を理解できる。","en":"You can only understand its value by actually using it.","romaji":"Jissai ni tsukatte koso, sono kachi o rikai dekiru.","zh":""},{"ja":"自分で経験してこそ、大切なことが学べる。","en":"Only by experiencing it yourself can you learn what’s truly important.","romaji":"Jibun de keiken shite koso, taisetsu na koto ga manaberu.","zh":""},{"ja":"失敗してこそ、成功の味がわかる。","en":"Only by failing do you really understand the taste of success.","romaji":"Shippai shite koso, seikō no aji ga wakaru.","zh":""},{"ja":"努力してこそ、何かを成し遂げることができる。","en":"Only through making an effort can you accomplish anything.","romaji":"Doryoku shite koso, nanika o nashitogeru koto ga dekiru.","zh":""}]',replace('**Short**: Emphasizes ''only by doing something, a certain result or realization can occur.''\n\n**Formation**: Verb-て form + こそ\n\n**Long**: The ～てこそ grammar point is used to highlight that only by performing the verb in て-form can a certain important outcome be achieved or recognized. It often translates as ''only by (doing)'' or ''only when (doing).''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_wa_n1','Verb ては',NULL,NULL,'N1','[]','[{"ja":"彼女に会っては、いつも緊張してしまいます。","en":"Whenever I meet her, I get nervous.","romaji":"Kanojo ni atte wa, itsumo kinchō shite shimaimasu.","zh":""},{"ja":"この部屋を掃除しては乱雑になり、片づけては散らかる。","en":"Whenever I clean this room, it gets messy again, and whenever I tidy it, it gets cluttered again.","romaji":"Kono heya o sōji shite wa konzatsu ni nari, katadzukete wa chirakaru.","zh":""},{"ja":"運動しては食べ、食べては運動する生活が続いている。","en":"I keep exercising and then eating, and then eating and exercising.","romaji":"Undō shite wa tabe, tabete wa undō suru seikatsu ga tsudzuite iru.","zh":""},{"ja":"勉強しては寝て、寝ては勉強する日々です。","en":"My days are spent studying and then sleeping, and then sleeping and studying.","romaji":"Benkyō shite wa nete, nete wa benkyō suru hibi desu.","zh":""}]',replace('**Short**: Expresses a repeated pattern or cycle, often implying a frustrating outcome; ''whenever X happens, Y happens again.''\n\n**Formation**: Verb-て form + は\n\n**Long**: The grammar ～ては is used to show that whenever one action or situation occurs, another action or situation repeatedly follows. It can also be used in an alternating pattern: ''do this, then that, then this, then that.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_te_wa_n1_2','Verb ては Verb',NULL,NULL,'N1','[]','[{"ja":"私が通勤しては、電子書籍を読んでいます。","en":"Whenever I commute, I read e-books.","romaji":"Watashi ga tsūkin shite wa, denshi shoseki o yonde imasu.","zh":""},{"ja":"友達が部屋に来ては、ゲームをしています。","en":"Every time my friend comes to my room, we play games.","romaji":"Tomodachi ga heya ni kite wa, gēmu o shite imasu.","zh":""},{"ja":"彼が酒を飲んでは、運転を止めさせています。","en":"Whenever he drinks alcohol, I make him stop driving.","romaji":"Kare ga sake o nonde wa, unten o tome sasete imasu.","zh":""},{"ja":"私が新しい曲を作っては、すぐに録音します。","en":"Every time I create a new song, I record it immediately.","romaji":"Watashi ga atarashii kyoku o tsukutte wa, sugu ni rokuon shimasu.","zh":""}]',replace('**Short**: Expresses a repeated pattern of action; translates as ''every time'', ''whenever'', etc.\n\n**Formation**: Verb-て form + は + Verb\n\n**Long**: This grammar point is used when you want to express a repeated or cyclical pattern of actions or events. It can be translated as ''every time'', ''whenever'', or ''if at all''. The typical formation is a verb in the て-form, followed by は, and then another verb (often in the same tense or a continuing action).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_temademo','Verb てまでも',NULL,NULL,'N1','[]','[{"ja":"試験に合格するために、寝る時間を削ってまでも勉強します。","en":"I will study to pass the exam, even if it means cutting down on sleep.","romaji":"Shiken ni gōkaku suru tame ni, neru jikan o kezutte mademo benkyō shimasu.","zh":""},{"ja":"彼女と結婚できるなら、どんな苦労をしてまでもお金を貯めたい。","en":"If I can marry her, I''ll save money no matter what hardships it takes.","romaji":"Kanojo to kekkon dekiru nara, donna kurō o shite mademo okane o tametai.","zh":""},{"ja":"この会社で働きたいので、長時間かけてまでも通います。","en":"Because I want to work at this company, I''ll commute even if it means spending hours traveling.","romaji":"Kono kaisha de hatarakitai node, chōjikan kakete mademo kayoimasu.","zh":""},{"ja":"彼の快復のためなら、何をしてまでも支えたい。","en":"For his recovery, I''ll support him no matter what it takes.","romaji":"Kare no kaifuku no tame nara, nani o shite mademo sasaetai.","zh":""}]',replace('**Short**: Expresses ''even if it means doing...'', ''no matter what it takes''.\n\n**Formation**: Verb-て form + までも\n\n**Long**: This grammar point is used when the speaker wants to emphasize the lengths they would go to in order to achieve something. It attaches to the verb''s て-form to mean ''even if it means doing X'', ''even at the cost of X'', or ''no matter what it takes''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te_miseru','Verb てみせる',NULL,NULL,'N1','[]','[{"ja":"彼はそのパズルを解いてみせた。","en":"He solved the puzzle to show me.","romaji":"Kare wa sono pazuru o toite miseta.","zh":""},{"ja":"私はこの仕事ができることをやってみせます。","en":"I will do this job to prove that I can.","romaji":"Watashi wa kono shigoto ga dekiru koto o yatte misemasu.","zh":""},{"ja":"彼女は試験に合格するために一生懸命勉強してみせました。","en":"She studied hard to prove she could pass the exam.","romaji":"Kanojo wa shiken ni gōkaku suru tame ni isshōkenmei benkyō shite misemashita.","zh":""},{"ja":"彼は自分が何も恐れていないと跳んでみせた。","en":"He jumped to show he wasn’t afraid of anything.","romaji":"Kare wa jibun ga nanimo osorete inai to tonde miseta.","zh":""}]',replace('**Short**: ''Show by doing'', ''demonstrate'', ''prove by action''.\n\n**Formation**: Verb-て form + みせる\n\n**Long**: The ～てみせる grammar point is used to express the action of demonstrating or proving something by actually doing it. It can be translated as ''show by doing'', ''demonstrate'', or ''prove by action'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_te_yamanai','Verb てやまない',NULL,NULL,'N1','[]','[{"ja":"私は母を思ってやまない。","en":"I can''t stop thinking of my mother.","romaji":"Watashi wa haha o omotte yamanai.","zh":""},{"ja":"彼は彼女を愛してやまない。","en":"He loves her beyond measure.","romaji":"Kare wa kanojo o aishite yamanai.","zh":""},{"ja":"彼は日本の文化を尊敬してやまない。","en":"He has unceasing respect for Japanese culture.","romaji":"Kare wa Nihon no bunka o sonkei shite yamanai.","zh":""},{"ja":"彼女の成功を願ってやまない。","en":"I can’t stop hoping for her success.","romaji":"Kanojo no seikō o negatte yamanai.","zh":""}]',replace('**Short**: Used with certain emotional/mental verbs to show a strong, unceasing emotion: ''can''t stop'', ''never cease to''.\n\n**Formation**: Verb-て form + やまない (common with certain verbs)\n\n**Long**: The grammar ～てやまない is typically used with verbs like 願う, 祈る, 愛する, 尊敬する, 期待する, etc., expressing a deep, continuous emotional state (love, respect, hope, prayer). It emphasizes that the feeling ''never ceases.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nai_de_wa_okanai','Verb ないではおかない',NULL,NULL,'N1','[]','[{"ja":"彼女は毎回遅刻をしては、先生に怒られないではおかない。","en":"Every time she''s late, she inevitably gets scolded by the teacher.","romaji":"Kanojo wa maikai chikoku o shite wa, sensei ni okorarenaide wa okanai.","zh":""},{"ja":"美味しいものがあれば、彼は食べないではおかない。","en":"If there''s delicious food, he can''t help but eat it.","romaji":"Oishii mono ga areba, kare wa tabenai de wa okanai.","zh":""},{"ja":"この小説は感動的で、読めば涙を流さないではおかない。","en":"This novel is so moving that you can''t help but shed tears when you read it.","romaji":"Kono shōsetsu wa kandōteki de, yomeba namida o nagasanai de wa okanai.","zh":""},{"ja":"毎日練習しているから、試合では勝たないではおかないだろう。","en":"He practices every day, so he''s bound to win the match.","romaji":"Mainichi renshū shite iru kara, shiai de wa katanai de wa okanai darō.","zh":""}]',replace('**Short**: Means ''cannot help but do'', ''will definitely do'', or ''is bound to happen''.\n\n**Formation**: Verb-ない form + ではおかない\n\n**Long**: The pattern Verb ないではおかない indicates that something definitely occurs as a logical or emotional consequence. It can be translated as ''cannot not do'', ''can’t help but do'', or ''will inevitably do''. The verb is put in the negative form followed by ないではおかない.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_nai_dewa_sumanai','Verb ないではすまない',NULL,NULL,'N1','[]','[{"ja":"失敗をしたら、謝らないではすまない。","en":"If you make a mistake, you have to apologize—there’s no way around it.","romaji":"Shippai o shitara, ayamaranai de wa sumanai.","zh":""},{"ja":"この問題は重大なので、報告しないではすまない。","en":"This issue is so serious that I must report it.","romaji":"Kono mondai wa jūdai na node, hōkoku shinai de wa sumanai.","zh":""},{"ja":"この映画はとても感動的で、泣かないではすまない。","en":"This movie is so moving that you can’t help but cry.","romaji":"Kono eiga wa totemo kandōteki de, nakanai de wa sumanai.","zh":""},{"ja":"子供が間違えたら、教えないではすまない。","en":"If a child makes a mistake, you must correct them—there’s no avoiding it.","romaji":"Kodomo ga machigaetara, oshienai de wa sumanai.","zh":""}]',replace('**Short**: ''Cannot end without doing'', ''must do''—an unavoidable moral or social necessity.\n\n**Formation**: Verb-ない form + ではすまない\n\n**Long**: The grammar Verb ないではすまない expresses that something must be done (often for moral, social, or personal reasons) and cannot be left undone. It implies an obligation or inevitability, akin to ''I can''t get away without doing it.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_nai_made_mo','Verb ないまでも',NULL,NULL,'N1','[]','[{"ja":"全てを理解しないまでも、基本的なことは分かってほしい。","en":"Even if you don''t understand everything, I''d like you at least to grasp the basics.","romaji":"Subete o rikai shinai made mo, kihonteki na koto wa wakatte hoshii.","zh":""},{"ja":"会えないまでも、電話で声を聞きたい。","en":"Even if we can’t meet, I still want to hear your voice over the phone.","romaji":"Aenai made mo, denwa de koe o kikitai.","zh":""},{"ja":"毎日は無理にしても、週に一度くらいはジョギングを続けたい。","en":"Even if I can''t do it every day, I want to at least keep jogging once a week.","romaji":"Mainichi wa muri ni shite mo, shū ni ichido kurai wa jogingu o tsuzuketai.","zh":""},{"ja":"全員に気に入られないまでも、誠実に向き合いたい。","en":"Even if not everyone will like me, I still want to face them sincerely.","romaji":"Zen''in ni ki ni irarenai made mo, seijitsu ni mukiai tai.","zh":""}]',replace('**Short**: ''Even if not to the extent of...'', ''although not completely...''.\n\n**Formation**: Verb-ない form + までも\n\n**Long**: The pattern ないまでも is used when acknowledging that something doesn’t reach a certain extreme, but at least some part or degree of it applies. Often translated as ''even if not entirely...'' or ''though not as far as...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_nai_mono_darou_ka','Verb ないものだろうか',NULL,NULL,'N1','[]','[{"ja":"もっと時間があれば、ここに来られないものだろうか。","en":"If I had more time, wouldn''t it be possible to come here?","romaji":"Motto jikan ga areba, koko ni korarenai mono darou ka.","zh":""},{"ja":"彼女にもっとよく説明すれば、理解できないものだろうか。","en":"If I explain it better to her, wouldn''t she understand?","romaji":"Kanojo ni motto yoku setsumei sureba, rikai dekinai mono darou ka.","zh":""},{"ja":"この問題を解決する方法はないものだろうか。","en":"Isn''t there a way to solve this problem?","romaji":"Kono mondai o kaiketsu suru houhou wa nai mono darou ka.","zh":""},{"ja":"自分の間違いを認められないものだろうか。","en":"Can''t I admit my own mistakes?","romaji":"Jibun no machigai o mitomerarenai mono darou ka.","zh":""}]',replace('**Short**: Expressing hope or wonder if something can be done: ''Isn''t there a way...?'', ''Can''t we...?''\n\n**Formation**: Verb-negative (often negative potential) + ものだろうか\n\n**Long**: This grammar point is used when the speaker expresses the hope, wish, or wonder if an action could be possible. It creates the nuance of ''Isn''t there some way...?'' or ''Can''t I/you/we...?'' in English, often with the negative potential form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_nai_mono_demo_nai','Verb ないものでもない',NULL,NULL,'N1','[]','[{"ja":"旅行に行きたいと思わないものでもない。","en":"It''s not that I never want to travel.","romaji":"Ryokou ni ikitai to omowanai mono demo nai.","zh":""},{"ja":"彼の言ったこと全部が間違いないものでもない。","en":"It''s not that everything he said is completely free from mistakes.","romaji":"Kare no itta koto zenbu ga machigai nai mono demo nai.","zh":""},{"ja":"その問題が解けないものでもない。","en":"It''s not that the problem can''t be solved.","romaji":"Sono mondai ga tokenai mono demo nai.","zh":""},{"ja":"彼に会いたくないものでもない。","en":"It''s not that I don''t want to see him.","romaji":"Kare ni aitakunai mono demo nai.","zh":""}]',replace('**Short**: Expresses the idea that it''s not entirely impossible or non-existent: ''It''s not that I don''t...'', ''It''s not that there aren''t...''\n\n**Formation**: Verb-negative form (ない form) + ものでもない\n\n**Long**: The grammar point Verbないものでもない is used to express that a situation is not completely impossible or nonexistent. Literally, it can be translated as ''it''s not that there aren''t...'' or ''it''s not that I never...''. It implies that some possibility or partial truth exists.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_no_nai','Verb の ない Noun',NULL,NULL,'N1','[]','[{"ja":"笑いのない人生は、つまらない。","en":"A life without laughter is boring.","romaji":"Warai no nai jinsei wa, tsumaranai.","zh":""},{"ja":"水のない場所には、人は住めない。","en":"People cannot live in a place without water.","romaji":"Mizu no nai basho ni wa, hito wa sumenai.","zh":""},{"ja":"言葉のない世界は、想像するのが難しい。","en":"It''s hard to imagine a world without words.","romaji":"Kotoba no nai sekai wa, souzou suru no ga muzukashii.","zh":""},{"ja":"愛のない結婚は、長続きしない。","en":"A marriage without love will not last.","romaji":"Ai no nai kekkon wa, nagatsudzuki shinai.","zh":""}]',replace('**Short**: Used to modify a noun with a negative verb form; ''a Noun without (Verb)''.\n\n**Formation**: Verb in negative form + の + Noun\n\n**Long**: VerbのないNoun modifies a noun by describing the absence of the verb''s action. It indicates ''a Noun where the action does not happen'' or ''a Noun without that action.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ba_kiri_ga_nai','Verb ば きりがない',NULL,NULL,'N1','[]','[{"ja":"悪口を言い始めればきりがない。","en":"Once I start speaking ill of someone, there''s no end.","romaji":"Waruguchi o iihajimereba kiri ga nai.","zh":""},{"ja":"彼の欠点を数えればきりがない。","en":"If I start counting his flaws, there will be no end.","romaji":"Kare no ketten o kazoereba kiri ga nai.","zh":""},{"ja":"この国の美しい場所は、挙げればきりがない。","en":"If I start listing this country''s beautiful places, there''s no end.","romaji":"Kono kuni no utsukushii basho wa, agereba kiri ga nai.","zh":""},{"ja":"ほかにも例を挙げればきりがない。","en":"If I start giving more examples, there will be no end.","romaji":"Hoka ni mo rei o agereba kiri ga nai.","zh":""}]',replace('**Short**: Indicates there''s no end once you start listing, doing, or saying something: ''If one starts to..., there will be no end.''\n\n**Formation**: Verb-conditional form (ば) + きりがない\n\n**Long**: The pattern ～ばきりがない is used when expressing that if you start an action—like listing examples or complaining—there is no end. It literally means ''if (you) do X, there''s no limit/end.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mo_shinai_de','Verb もしないで',NULL,NULL,'N1','[]','[{"ja":"調べもしないで、答えを書きました。","en":"I wrote the answer without even investigating.","romaji":"Shirabe mo shinai de, kotae o kakimashita.","zh":""},{"ja":"彼は試験を勉強もしないで、テストに合格した。","en":"He passed the test without even studying.","romaji":"Kare wa shiken o benkyou mo shinai de, tesuto ni goukaku shita.","zh":""},{"ja":"彼女はその本を読みもしないで、レポートを書いた。","en":"She wrote her report without even reading the book.","romaji":"Kanojo wa sono hon o yomi mo shinai de, repooto o kaita.","zh":""},{"ja":"準備もしないで、プレゼンテーションを始めました。","en":"He started the presentation without even preparing.","romaji":"Junbi mo shinai de, purezenteeshon o hajimemashita.","zh":""}]',replace('**Short**: Means ''without even doing''.\n\n**Formation**: Verb (masu stem) + もしないで\n\n**Long**: This pattern is used to express that one has not done (or not even tried to do) some action before proceeding to do something else. It emphasizes doing something ''without even'' doing the prior action.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_yashinai','Verb やしない',NULL,NULL,'N1','[]','[{"ja":"こんな時に泣きやしない。","en":"I would never cry at a time like this.","romaji":"Konna toki ni naki-yashinai.","zh":""},{"ja":"私が彼を助けやしない。","en":"There''s no way I''d help him.","romaji":"Watashi ga kare o tasuke-yashinai.","zh":""},{"ja":"彼がそんなことを言いやしない。","en":"He would never say such a thing.","romaji":"Kare ga sonna koto o ii-yashinai.","zh":""},{"ja":"私がそんな高価なものを買いやしない。","en":"There''s no way I''d buy something so expensive.","romaji":"Watashi ga sonna kouka na mono o kai-yashinai.","zh":""}]',replace('**Short**: Expresses a strong denial or refusal: ''I would never...'', ''No way I would...''.\n\n**Formation**: Verb (masu stem) + やしない\n\n**Long**: This grammar adds a nuance of strong denial or dismissal of the idea that the speaker (or someone) would do the action. Formed by adding やしない to the verb''s stem, it often appears in casual or spoken language.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_you_you_ni','Verb よう',NULL,NULL,'N1','[]','[{"ja":"この問題を解くように努力します。","en":"I will try to solve this problem.","romaji":"Kono mondai o toku you ni doryoku shimasu.","zh":""},{"ja":"彼が言ったようにやりましょう。","en":"Let''s do it the way he said.","romaji":"Kare ga itta you ni yarimashou.","zh":""},{"ja":"毎日走るようにしています。","en":"I make it a point to run every day.","romaji":"Mainichi hashiru you ni shiteimasu.","zh":""},{"ja":"自分の心を大切にするように。","en":"Try to take care of your own heart.","romaji":"Jibun no kokoro o taisetsu ni suru you ni.","zh":""}]',replace('**Short**: Expresses ''the way/manner of doing something'' or ''in order to / so that / try to''.\n\n**Formation**: Verb (dictionary or negative form) + ように (する / etc.)\n\n**Long**: This usage of よう most commonly appears as 「Verb辞書形 + ように」. It can mean ''in order to do something'', ''so that something happens'', or ''in the way someone does something''. It is also used in expressions like ～ようにする (to make an effort to) or ～ように言う (to tell someone to do something).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_you_ka_verb_ru_mai_ka','Verb ようか Verbるまいか',NULL,NULL,'N1','[]','[{"ja":"彼に話そうか話すまいか、本当に迷っている。","en":"I''m really unsure whether to talk to him or not.","romaji":"Kare ni hanasou ka hanasu mai ka, hontou ni mayotte iru.","zh":""},{"ja":"試験を受けようか受けまいか迷っています。","en":"I''m wondering whether to take the exam or not.","romaji":"Shiken o ukeyou ka ukemai ka mayotte imasu.","zh":""},{"ja":"あの人に謝ろうか謝るまいか考えています。","en":"I''m considering whether to apologize to that person or not.","romaji":"Ano hito ni ayamarou ka ayamaru mai ka kangaete imasu.","zh":""},{"ja":"進学しようかしまいか悩んでいる。","en":"I''m worried about whether to continue my studies or not.","romaji":"Shingaku shiyou ka shimai ka nayande iru.","zh":""}]',replace('**Short**: Expresses indecision: ''Should I do it or not?''.\n\n**Formation**: Verb-volitional form + か + Verb-volitional negative form (まい) + か\n\n**Long**: This grammar shows hesitation about whether to do something or not. The volitional form plus まい (negative volitional) suggests an internal debate about two opposite choices of the *same* verb.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_you_ga_verb_ru_mai_ga','Verb ようが Verb るまいが',NULL,NULL,'N1','[]','[{"ja":"彼が来ようが来るまいが、パーティーは始まります。","en":"Whether he comes or not, the party will start.","romaji":"Kare ga koyou ga kurumai ga, paatii wa hajimarimasu.","zh":""},{"ja":"勉強しようがしまいが、テストの結果は変わらない。","en":"Whether you study or not, the test results won''t change.","romaji":"Benkyou shiyou ga shimai ga, tesuto no kekka wa kawaranai.","zh":""},{"ja":"雨が降ろうが降るまいが、ピクニックに行きます。","en":"Whether it rains or not, we''re going on a picnic.","romaji":"Ame ga furou ga furumai ga, pikunikku ni ikimasu.","zh":""},{"ja":"暑かろうが寒かろうが、毎日ジョギングします。","en":"Whether it''s hot or cold, I jog every day.","romaji":"Atsukarou ga samukarou ga, mainichi jogingu shimasu.","zh":""}]',replace('**Short**: Expresses ''whether or not'', ''no matter if something happens or not''.\n\n**Formation**: Verb-volitional form + が + Verb-negative volitional form + が\n\n**Long**: Verbようが Verbるまいが indicates that whatever happens—whether the action is done or not—the outcome remains unchanged or the speaker''s stance remains the same.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_you_ga_nai_n1','Verb ようがない',NULL,NULL,'N1','[]','[{"ja":"電車が混んでいて、動きようがない。","en":"The train is so crowded that I can''t move.","romaji":"Densha ga konde ite, ugoki you ga nai.","zh":""},{"ja":"彼はとても早く走るので、追いつきようがない。","en":"He runs so fast, there''s no way I can catch up.","romaji":"Kare wa totemo hayaku hashiru no de, oitsuki you ga nai.","zh":""},{"ja":"私には理解しようがない。","en":"There''s no way for me to understand it.","romaji":"Watashi ni wa rikai shiyou ga nai.","zh":""},{"ja":"どうやっても、これを直しようがない。","en":"No matter what I try, there''s no way to fix this.","romaji":"Dou yatte mo, kore o naoshi you ga nai.","zh":""}]',replace('**Short**: Expresses ''no way to do something,'' ''impossible to do''.\n\n**Formation**: Verb (masu stem) + ようがない\n\n**Long**: 〜ようがない is used to say that there''s no way or method to do something, even if you wanted to.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_you_to_verb_ru_mai_to','Verb ようと Verbる まいと',NULL,NULL,'N1','[]','[{"ja":"あなたが来ようと来るまいと、パーティーは予定通りに始まります。","en":"Whether you come or not, the party will start as scheduled.","romaji":"Anata ga koyou to kuru mai to, paatii wa yotei doori ni hajimarimasu.","zh":""},{"ja":"彼があそこに行こうと行くまいと、私たちは止めることができません。","en":"Whether he tries to go there or not, we can''t stop him.","romaji":"Kare ga asoko ni ikou to iku mai to, watashitachi wa tomeru koto ga dekimasen.","zh":""},{"ja":"彼女が謝ろうと謝るまいと、事実は変わらない。","en":"Whether she apologizes or not, the fact won''t change.","romaji":"Kanojo ga ayamarou to ayamaru mai to, jijitsu wa kawaranai.","zh":""},{"ja":"試験を受けようと受けるまいと、親として私はあなたを支えます。","en":"Whether you take the exam or not, I will support you as your parent.","romaji":"Shiken o ukeyou to ukeru mai to, oya to shite watashi wa anata o sasaemasu.","zh":""}]',replace('**Short**: This structure indicates that regardless of whether one does (verb) or not, the outcome/attitude remains unchanged.\n\n**Formation**: Verb-volitional + と + Verb-negative volitional (～まい) + と\n\n**Long**: The expression ''Verb-volitional form + と + Verb-negative volitional (～まい) + と'' means ''regardless of whether one does X or not, it doesn''t change the situation''. It shows the speaker''s firm stance or the unchanging nature of some outcome.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_you_ni_mo','Verb ようにも',NULL,NULL,'N1','[]','[{"ja":"もう少し速く走ろうにも、足が痛くて無理だ。","en":"I''d like to run a bit faster, but I can’t because my leg hurts.","romaji":"Mou sukoshi hayaku hashirou ni mo, ashi ga itakute muri da.","zh":""},{"ja":"彼に話そうにも、彼は私を無視している。","en":"I want to talk to him, but he''s ignoring me.","romaji":"Kare ni hanasou ni mo, kare wa watashi o mushi shite iru.","zh":""},{"ja":"もっと勉強しようにも、時間がない。","en":"I want to study more, but I have no time.","romaji":"Motto benkyou shiyou ni mo, jikan ga nai.","zh":""},{"ja":"彼女に謝ろうにも、彼女はもう怒っている。","en":"I would like to apologize to her, but she''s already angry.","romaji":"Kanojo ni ayamarou ni mo, kanojo wa mou okotte iru.","zh":""}]',replace('**Short**: Used to express ''even though one wants to do something, one can''t for some reason''.\n\n**Formation**: Verb-volitional form + にも + (reason/potential negative, etc.)\n\n**Long**: The ～ようにも grammar point indicates that a person wants or tries to do something (volitional form), but for some reason cannot. Often, there''s a second clause explaining what prevents the action.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_you_ni_mo_renai','Verb ようにも Verb れない',NULL,NULL,'N1','[]','[{"ja":"彼を信じようにも信じられない証拠がある。","en":"Even if I want to believe him, there''s evidence that prevents me from doing so.","romaji":"Kare o shinjiyou ni mo shinjirarenai shouko ga aru.","zh":""},{"ja":"早く出発しようにも車が故障してしまった。","en":"Even if I want to leave early, my car has broken down.","romaji":"Hayaku shuppatsu shiyou ni mo kuruma ga koshou shite shimatta.","zh":""},{"ja":"彼に電話しようにも電話番号を知らない。","en":"I want to call him, but I don’t know his phone number.","romaji":"Kare ni denwa shiyou ni mo denwa bangou o shiranai.","zh":""},{"ja":"もっと勉強しようにも時間がない。","en":"I want to study more, but there is no time.","romaji":"Motto benkyou shiyou ni mo jikan ga nai.","zh":""}]',replace('**Short**: Expresses the inability to do something even if one wants/tries.\n\n**Formation**: Verb-volitional form + にも + (potential negative form / reason)\n\n**Long**: This grammar shows that you want (or try) to do something (volitional form), but cannot due to some obstacle. Often it appears as ''Verb-volitional + にも + Verb (potential negative)'' or simply ''Verb-volitional + にも + (reason you can''t)''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_you_mo_nai','Verb ようもない',NULL,NULL,'N1','[]','[{"ja":"この問題は解きようもない。","en":"It''s impossible to solve this problem.","romaji":"Kono mondai wa toki you mo nai.","zh":""},{"ja":"これ以上我慢しようもない。","en":"It''s impossible to endure any further.","romaji":"Kore ijou gaman shiyou mo nai.","zh":""},{"ja":"彼には通じようもない。","en":"There''s no way to get through to him.","romaji":"Kare ni wa tsuujiyou mo nai.","zh":""},{"ja":"その薬は飲みようもない。","en":"It''s impossible to take (swallow) that medicine.","romaji":"Sono kusuri wa nomiyou mo nai.","zh":""}]',replace('**Short**: Expresses ''it''s impossible to do something''.\n\n**Formation**: Verb-ます stem + ようもない\n\n**Long**: ～ようもない typically attaches to the verb''s ます-stem, adding ようもない to indicate that there is ''no way'' or ''no method'' to perform the action. It’s the same nuance as ''Verbようがない'' in many references.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ga_mama_ni','Verbる がままに',NULL,NULL,'N1','[]','[{"ja":"窓を開けるがままにしておいたら、風が部屋に入ってきました。","en":"I left the window open as it was, and the wind came into the room.","romaji":"Mado o akeru ga mama ni shite oitara, kaze ga heya ni haitte kimashita.","zh":""},{"ja":"彼女は涙を流すがままに、ただ黙って座っていた。","en":"She just sat quietly, letting her tears flow.","romaji":"Kanojo wa namida o nagasu ga mama ni, tada damatte suwatte ita.","zh":""},{"ja":"子供たちは笑うがままに、公園で走り回っていた。","en":"The children ran around the park, laughing freely as they pleased.","romaji":"Kodomo-tachi wa warau ga mama ni, kouen de hashirimawatte ita.","zh":""},{"ja":"日が沈むがままに、私たちは海辺で話し続けました。","en":"We kept talking by the sea, letting the sun set as it would.","romaji":"Hi ga shizumu ga mama ni, watashitachi wa umibe de hanashi tsudzukemashita.","zh":""}]',replace('**Short**: Expresses ''letting something happen as it is''; ''just as something does''.\n\n**Formation**: Verb-dictionary form + がままに\n\n**Long**: がままに describes an action happening exactly ''as is,'' without intervention or change, often suggesting doing something passively or naturally.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ru_ga_hayai_ka','Verbる が早いか',NULL,NULL,'N1','[]','[{"ja":"部屋に入るが早いか、彼はテレビをつけた。","en":"No sooner had he entered the room than he turned on the TV.","romaji":"Heya ni hairu ga hayai ka, kare wa terebi o tsuketa.","zh":""},{"ja":"電車に乗るが早いか、私はすぐに眠ってしまった。","en":"As soon as I got on the train, I immediately fell asleep.","romaji":"Densha ni noru ga hayai ka, watashi wa sugu ni nemutte shimatta.","zh":""},{"ja":"彼女が見るが早いか、すぐに泣き始めた。","en":"The moment she looked, she began to cry.","romaji":"Kanojo ga miru ga hayai ka, sugu ni naki hajimeta.","zh":""},{"ja":"給料をもらうが早いか、全て使い果たしてしまった。","en":"No sooner had I received my salary than I spent it all.","romaji":"Kyuuryou o morau ga hayai ka, subete tsukaihatashite shimatta.","zh":""}]',replace('**Short**: Expresses ''as soon as...'' or ''the moment when...''.\n\n**Formation**: Verb-dictionary form + が早いか\n\n**Long**: Verbる が早いか indicates that something happens immediately after something else. It''s similar to ''as soon as...'' or ''no sooner than...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ru_kurai_nara','Verbる くらいなら',NULL,NULL,'N1','[]','[{"ja":"一人で行くくらいなら、家にいるほうがましです。","en":"I''d rather stay at home than go alone.","romaji":"Hitori de iku kurai nara, ie ni iru hou ga mashi desu.","zh":""},{"ja":"負けるくらいなら、試合をしないほうがいい。","en":"Rather than lose, it''s better not to compete.","romaji":"Makeru kurai nara, shiai o shinai hou ga ii.","zh":""},{"ja":"遅刻するくらいなら、一日休んだほうがいい。","en":"It''s better to take a day off than to be late.","romaji":"Chikoku suru kurai nara, ichinichi yasunda hou ga ii.","zh":""},{"ja":"痛い目に遭うくらいなら、そのリスクは避けます。","en":"I''d rather avoid that risk than suffer the consequences.","romaji":"Itai me ni au kurai nara, sono risuku wa sakemasu.","zh":""}]',replace('**Short**: Expresses preference to avoid something: ''rather than...'', ''if it comes to doing X, I''d rather...''.\n\n**Formation**: Verb-dictionary form + くらいなら\n\n**Long**: This grammar is used when the speaker would rather not do something or chooses another option rather than face the stated action. It’s often translated as ''rather than... I''d prefer...'' or ''if it comes down to doing X, I''d rather...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ru_koto_nashi_ni','Verbる こと なし に',NULL,NULL,'N1','[]','[{"ja":"試験を勉強することなしに、合格しました。","en":"I passed the exam without studying.","romaji":"Shiken o benkyou suru koto nashi ni, goukaku shimashita.","zh":""},{"ja":"試着することなしに、服を買いました。","en":"I bought the clothes without trying them on.","romaji":"Shichaku suru koto nashi ni, fuku o kaimashita.","zh":""},{"ja":"彼は働くことなしに生活しています。","en":"He is living without working.","romaji":"Kare wa hataraku koto nashi ni seikatsu shite imasu.","zh":""},{"ja":"手続きをすることなしに、退職しました。","en":"I retired without going through any procedures.","romaji":"Tetsuzuki o suru koto nashi ni, taishoku shimashita.","zh":""}]',replace('**Short**: Used to express ''without doing something''.\n\n**Formation**: Verb-dictionary form + ことなしに\n\n**Long**: Verbることなしに indicates doing something else ''without'' performing the stated action. It can imply skipping or omitting the verb action entirely.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ru_koto_no_nai_you_ni','Verbる ことのないように',NULL,NULL,'N1','[]','[{"ja":"車をなくすことのないように、駐車場で必ずロックしましょう。","en":"Lock your car in the parking lot so you don''t lose it.","romaji":"Kuruma o nakusu koto no nai you ni, chuushajou de kanarazu rokku shimashou.","zh":""},{"ja":"風邪を引くことのないように、手をよく洗いましょう。","en":"Wash your hands well so you don''t catch a cold.","romaji":"Kaze o hiku koto no nai you ni, te o yoku araimashou.","zh":""},{"ja":"試験に落ちることのないように、毎日勉強しましょう。","en":"Study every day so you don''t fail the exam.","romaji":"Shiken ni ochiru koto no nai you ni, mainichi benkyou shimashou.","zh":""},{"ja":"間違いをすることのないように、仕事を慎重に行いましょう。","en":"Let''s work carefully to avoid making mistakes.","romaji":"Machigai o suru koto no nai you ni, shigoto o shinchou ni okonaimashou.","zh":""}]',replace('**Short**: Expresses the desire or effort to prevent something: ''so as not to...'', ''to avoid...''.\n\n**Formation**: Verb-dictionary form + ことのないように\n\n**Long**: Verbる ことのないように is used to show that one is trying or intending to prevent some action from happening. It''s like ''so that this doesn''t happen'' or ''in order not to...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ru_to_kiri_ga_nai','Verbる ときりがない',NULL,NULL,'N1','[]','[{"ja":"彼の悪口を言うときりがない。","en":"If we start talking about his faults, there''s no end.","romaji":"Kare no waruguchi o iu to kiri ga nai.","zh":""},{"ja":"その問題を考えるときりがない。","en":"If you start thinking about that problem, there''s no end.","romaji":"Sono mondai o kangaeru to kiri ga nai.","zh":""},{"ja":"彼女の美点を挙げるときりがない。","en":"If you start listing her virtues, there would be no end.","romaji":"Kanojo no biten o ageru to kiri ga nai.","zh":""},{"ja":"この世でおいしいものを食べるときりがない。","en":"If you start eating all the delicious things in this world, there''s no end.","romaji":"Kono yo de oishii mono o taberu to kiri ga nai.","zh":""}]',replace('**Short**: Used to indicate that something can go on endlessly or without limits.\n\n**Formation**: Verb-casual + と + きりがない\n\n**Long**: The ～るときりがない grammar point is used to express that once you start doing the verb, there’s no end or limit. The phrase ''きりがない'' means ''no end'' or ''endless.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ru_tomonaku_verb','Verbる ともなく Verb',NULL,NULL,'N1','[]','[{"ja":"遠くを見るともなく窓の外を眺めた。","en":"I found myself gazing out the window, not really looking at anything in particular.","romaji":"Tooku o miru tomonaku mado no soto o nagameta.","zh":""},{"ja":"知るともなく、彼が去ったことを感じた。","en":"Without really knowing, I felt that he had left.","romaji":"Shiru tomonaku, kare ga satta koto o kanjita.","zh":""},{"ja":"本を読むともなく、ページをめくっていた。","en":"Without intending to read, I was just flipping through the pages of the book.","romaji":"Hon o yomu tomonaku, peiji o mekutte ita.","zh":""},{"ja":"寝るともなく、ベッドに横になっていた。","en":"I was lying in bed without really intending to sleep.","romaji":"Neru tomonaku, beddo ni yoko ni natte ita.","zh":""}]',replace('**Short**: Used to express ''without a particular intention'', ''unconsciously'', or ''before one knows it''.\n\n**Formation**: Verb-dictionary form + ともなく + Verb\n\n**Long**: The phrase VerbるともなくVerb indicates doing something unintentionally or unconsciously— you just find yourself doing it without a clear aim or intention.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ru_tomonashi_ni_verb','Verbる ともなしに Verb',NULL,NULL,'N1','[]','[{"ja":"本を読むともなしに眠ってしまった。","en":"I ended up falling asleep while reading the book without really meaning to.","romaji":"Hon o yomu tomonashi ni nemutte shimatta.","zh":""},{"ja":"軽い気持ちで手紙を書くともなしに、彼に本心を告白した。","en":"While writing a letter casually, I ended up confessing my true feelings to him.","romaji":"Karui kimochi de tegami o kaku tomonashi ni, kare ni honshin o kokuhaku shita.","zh":""},{"ja":"散歩をするともなしに、新しいカフェを見つけた。","en":"While I was walking with no particular destination, I found a new cafe.","romaji":"Sanpo o suru tomonashi ni, atarashii kafe o mitsuketa.","zh":""},{"ja":"洋服を整理するともなしに、昔の写真を見つけた。","en":"As I was absentmindedly organizing clothes, I came across some old photos.","romaji":"Youfuku o seiri suru tomonashi ni, mukashi no shashin o mitsuketa.","zh":""}]',replace('**Short**: Expresses doing something unintentionally or without conscious thought.\n\n**Formation**: Verb-dictionary form + ともなしに + Verb\n\n**Long**: VerbるともなしにVerb is used to show that you do some action without particularly intending to. Often you ‘end up doing’ something by habit or casually.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ru_nari','Verbる なり',NULL,NULL,'N1','[]','[{"ja":"家に帰るなり、すぐに寝た。","en":"As soon as I got home, I went to sleep.","romaji":"Ie ni kaeru nari, sugu ni neta.","zh":""},{"ja":"彼が駅に着くなり、電話をかけてきた。","en":"He called me the moment he arrived at the station.","romaji":"Kare ga eki ni tsuku nari, denwa o kakete kita.","zh":""},{"ja":"ドアを開けるなり、犬が吠え始めた。","en":"As soon as I opened the door, the dog started barking.","romaji":"Doa o akeru nari, inu ga hoe hajimeta.","zh":""},{"ja":"テストが終わるなり、彼は教室を出て行った。","en":"He left the classroom the moment the test ended.","romaji":"Tesuto ga owaru nari, kare wa kyoushitsu o dete itta.","zh":""}]',replace('**Short**: Expresses ''as soon as'' or ''the moment''.\n\n**Formation**: Verb-dictionary form + なり\n\n**Long**: Verbるなり indicates that the following action happens immediately after the verb action. It can be translated as ''no sooner than...'', ''as soon as...'', or ''the moment...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ru_ni_todomarazu_mo','Verbる にとどまらず～も',NULL,NULL,'N1','[]','[{"ja":"彼は仕事にとどまらず、ボランティア活動もしている。","en":"He does not just work; he also does volunteer activities.","romaji":"Kare wa shigoto ni todomarazu, borantia katsudou mo shite iru.","zh":""},{"ja":"この機能は写真撮影にとどまらず、動画撮影も可能です。","en":"This function is not limited to taking photos; it can also record videos.","romaji":"Kono kinou wa shashin satsuei ni todomarazu, douga satsuei mo kanou desu.","zh":""},{"ja":"このレストランは日本料理にとどまらず、中華料理も提供しています。","en":"This restaurant not only serves Japanese food, but also Chinese cuisine.","romaji":"Kono resutoran wa Nihon ryouri ni todomarazu, Chuuka ryouri mo teikyou shiteimasu.","zh":""},{"ja":"その企業は製造業にとどまらず、流通業務も手がけている。","en":"That company’s operations go beyond manufacturing; they also handle distribution.","romaji":"Sono kigyou wa seizougyou ni todomarazu, ryuutsuugyou mo tegakete iru.","zh":""}]',replace('**Short**: Expresses ''not only… but also'', ''not limited to…''.\n\n**Formation**: Noun / Verb-dictionary form + にとどまらず + も/ほかのこと\n\n**Long**: にとどまらず is used to indicate that something goes beyond just the stated verb or noun. It can be translated as ''not just… but also…'' or ''not limited to…''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ru_ni_wa_ataranai','Verbる にはあたらない',NULL,NULL,'N1','[]','[{"ja":"パニックに陥るにはあたらない。","en":"There’s no need to panic.","romaji":"Panikku ni ochiiru ni wa ataranai.","zh":""},{"ja":"彼に謝るにはあたらない。","en":"There’s no need to apologize to him.","romaji":"Kare ni ayamaru ni wa ataranai.","zh":""},{"ja":"そのようなことを心配するにはあたらない。","en":"It’s not worth worrying about such things.","romaji":"Sono you na koto o shinpai suru ni wa ataranai.","zh":""},{"ja":"それについて深く考えるにはあたらない。","en":"There’s no need to think too deeply about it.","romaji":"Sore ni tsuite fukaku kangaeru ni wa ataranai.","zh":""}]',replace('**Short**: Used to say ''there is no need to...'', ''it’s not necessary to...''.\n\n**Formation**: Verb-dictionary form + にはあたらない\n\n**Long**: Verbる にはあたらない expresses that something is not worth the reaction or there is no need to do the verb. It''s somewhat formal and often used in writing.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ru_ni_mo','Verbる にも',NULL,NULL,'N1','[]','[{"ja":"明日雨が降ったとしても、傘を持つにも荷物が多すぎる。","en":"Even if it rains tomorrow, I have too much luggage to bring an umbrella.","romaji":"Ashita ame ga futta to shite mo, kasa o motsu ni mo nimotsu ga oosugiru.","zh":""},{"ja":"試験に落ちたが、もう一度受けるにもお金が足りない。","en":"I failed the exam, but I don’t have the money to take it again even if I wanted to.","romaji":"Shiken ni ochita ga, mou ichido ukeru ni mo okane ga tarinai.","zh":""},{"ja":"彼に会いたいと思っても、彼に会うにも難しい状況だ。","en":"Even if I want to see him, it''s a difficult situation to meet him.","romaji":"Kare ni aitai to omotte mo, kare ni au ni mo muzukashii joukyou da.","zh":""},{"ja":"この空港から彼女の家に行くにもタクシーが必要だ。","en":"I''d need a taxi to get from this airport to her house, even if I wanted to go.","romaji":"Kono kuukou kara kanojo no ie ni iku ni mo takushii ga hitsuyou da.","zh":""}]',replace('**Short**: Indicates that doing the verb is impossible or difficult, even if one wants to.\n\n**Formation**: Verb-dictionary form + にも + (reason it can''t be done)\n\n**Long**: Verbる にも is often used with an additional clause explaining why the action can’t be done. It can be translated as ''even if (I) want to do X, I can’t (because...)''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ru_ni_mo_verb_re_nai','Verbる にも Verb れない',NULL,NULL,'N1','[]','[{"ja":"彼を理解しようにも理解できない。","en":"Even if I try to understand him, I can''t.","romaji":"Kare o rikai shiyou ni mo rikai dekinai.","zh":""},{"ja":"走ろうにも走れない。","en":"Even if I want to run, I can''t.","romaji":"Hashirou ni mo hashirenai.","zh":""},{"ja":"泣こうにも泣けない。","en":"Even if I want to cry, I can''t.","romaji":"Nakou ni mo nakenai.","zh":""},{"ja":"忘れようにも忘れられない。","en":"Even if I try to forget, I just can’t.","romaji":"Wasureyou ni mo wasurerarenai.","zh":""}]',replace('**Short**: Expresses: ''Even if I try/want to do something, I cannot.''\n\n**Formation**: Verb-volitional + にも + Verb-potential negative\n\n**Long**: This pattern emphasizes that a person wants or attempts to do something (often in volitional form), but is incapable of doing so. It is often used with potential verbs in negative form: ''Even if I try to ~, I can''t ~.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ru_bekara_zaru_noun','Verbる べからざる Noun',NULL,NULL,'N1','[]','[{"ja":"人を裏切るべからざる行為だ。","en":"Betraying others is an act that must not be done.","romaji":"Hito o uragiru bekara zaru koui da.","zh":""},{"ja":"子供を傷つけるべからざる行動だ。","en":"Hurting a child is a behavior that must not happen.","romaji":"Kodomo o kizutsukeru bekara zaru koudou da.","zh":""},{"ja":"公に嘘をつくべからざる行動だ。","en":"Lying publicly is an act that should not be done.","romaji":"Ooyake ni uso o tsuku bekara zaru koudou da.","zh":""},{"ja":"他人の財産を侵すべからざる行為だ。","en":"Infringing on someone else’s property is an act that must not be performed.","romaji":"Tanin no zaisan o okasu bekara zaru koui da.","zh":""}]',replace('**Short**: Used to express what should not be done; ''must not'', ''should not''.\n\n**Formation**: Verb-dictionary form + べからざる + Noun\n\n**Long**: The Japanese grammar point Verbる べからざる Noun is used to indicate something that should not be done, or is not allowed to be done. It translates to ''must not'' or ''should not'' in English. It is often used in formal written Japanese or in formal speeches. It is constructed by using the verb in its dictionary form followed by ''べからざる'' and a noun, usually related to behavior or events.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ru_bekara_zu','Verbる べからず',NULL,NULL,'N1','[]','[{"ja":"嘘をつくべからず。","en":"One must not tell lies.","romaji":"Uso o tsuku bekara zu.","zh":""},{"ja":"彼らの秘密を漏らすべからず。","en":"You must not leak their secrets.","romaji":"Karera no himitsu o morasu bekara zu.","zh":""},{"ja":"ルールを破るべからず。","en":"You must not break the rules.","romaji":"Ruuru o yaburu bekara zu.","zh":""},{"ja":"勉強を怠るべからず。","en":"One must not neglect their studies.","romaji":"Benkyou o okotaru bekara zu.","zh":""}]',replace('**Short**: Expresses the idea of ''must not do'' or ''should not do''.\n\n**Formation**: Verb-ru + べからず\n\n**Long**: The ～るべからず grammar point is used to express a strong prohibition or firmly established rule. It can be translated as ''must not do'' or ''should not do''. It is common in formal or instructive settings (e.g., signs, notices). The formation is straightforward with verbs in dictionary form followed by べからず.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ru_beku','Verbる べく',NULL,NULL,'N1','[]','[{"ja":"成功するべく、日々努力しています。","en":"In order to succeed, I am working hard every day.","romaji":"Seikou suru beku, hibi doryoku shite imasu.","zh":""},{"ja":"健康を維持するべく、毎日運動をしています。","en":"In order to maintain my health, I exercise every day.","romaji":"Kenkou o iji suru beku, mainichi undou o shite imasu.","zh":""},{"ja":"彼は学位を得るべく、毎日勉強しています。","en":"He studies every day in order to get a degree.","romaji":"Kare wa gakui o eru beku, mainichi benkyou shite imasu.","zh":""},{"ja":"早く目的地に到着するべく、タクシーを呼びました。","en":"I called a taxi in order to arrive at the destination quickly.","romaji":"Hayaku mokutekichi ni touchaku suru beku, takushii o yobimashita.","zh":""}]',replace('**Short**: Expresses the meaning of ''in order to'', ''for the purpose of''.\n\n**Formation**: Verb-dictionary form + べく\n\n**Long**: The ''Verbる べく'' grammar point is used to indicate a strong intention or purpose of the speaker. It can be translated as ''in order to'' or ''for the purpose of'' in English. It is more common in written language or formal contexts.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ru_beku_mo_nai','Verbる べくもない',NULL,NULL,'N1','[]','[{"ja":"その問題はとても難しく、解くべくもない。","en":"That problem is so difficult that it''s impossible to solve.","romaji":"Sono mondai wa totemo muzukashiku, toku beku mo nai.","zh":""},{"ja":"彼女はあまりに速く走って、追いつくべくもない。","en":"She runs so fast that there''s no way to catch up.","romaji":"Kanojo wa amari ni hayaku hashitte, oitsuku beku mo nai.","zh":""},{"ja":"試験の筆記用具を忘れた。書くべくもない。","en":"I forgot my writing utensils for the test. It''s impossible to write.","romaji":"Shiken no hikki yougu o wasureta. Kaku beku mo nai.","zh":""},{"ja":"彼はとても高く跳ぶ。追い越すべくもない。","en":"He jumps so high that there''s no way to surpass him.","romaji":"Kare wa totemo takaku tobu. Oikosu beku mo nai.","zh":""}]',replace('**Short**: Means ''it''s impossible to...'' or ''there''s no way to...''.\n\n**Formation**: Verb-dictionary form + べくもない\n\n**Long**: This grammar point is used when you want to express that something is impossible or there is no way to do something. The verb before ''べくもない'' should be in its dictionary form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ru_made_mo_nai','Verbる までもない',NULL,NULL,'N1','[]','[{"ja":"そんなに心配するまでもない。","en":"There''s no need to worry that much.","romaji":"Sonna ni shinpai suru made mo nai.","zh":""},{"ja":"電話するまでもないことだ。","en":"It''s not something you need to call about.","romaji":"Denwa suru made mo nai koto da.","zh":""},{"ja":"小さな失敗であきらめるまでもない。","en":"You don''t need to give up over a small mistake.","romaji":"Chiisana shippai de akirameru made mo nai.","zh":""},{"ja":"この問題は、会議で話し合うまでもない。","en":"This problem doesn''t need to be discussed at a meeting.","romaji":"Kono mondai wa, kaigi de hanashiau made mo nai.","zh":""}]',replace('**Short**: It''s not necessary to the extent of; no need to.\n\n**Formation**: Verb-る + までもない\n\n**Long**: The 〜るまでもない grammar point is used to express that something is not necessary to the extent of doing that action. It can be translated as ''no need to'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ru_mono_to_suru','Verbる ものとする',NULL,NULL,'N1','[]','[{"ja":"ここでの話し合いは秘密とするものとします。","en":"The discussions here are to be kept confidential.","romaji":"Koko de no hanashiai wa himitsu to suru mono to shimasu.","zh":""},{"ja":"この契約は明日から有効とするものとする。","en":"This contract shall become effective from tomorrow.","romaji":"Kono keiyaku wa ashita kara yuukou to suru mono to suru.","zh":""},{"ja":"彼をチームのリーダーとするものとします。","en":"We will designate him as the team leader.","romaji":"Kare o chiimu no riidaa to suru mono to shimasu.","zh":""},{"ja":"この件については終了とするものとする。","en":"We will consider this matter closed.","romaji":"Kono ken ni tsuite wa shuuryou to suru mono to suru.","zh":""}]',replace('**Short**: Assuming or deciding something as...\n\n**Formation**: Verb-dictionary form + ものとする\n\n**Long**: The ～るものとする grammar point is often used in formal or legal contexts to express a decision or assumption. It can be translated as ''it is decided/assumed that...'' or ''shall be deemed that...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_verb_ru_ya_ina_ya','Verbる や否や',NULL,NULL,'N1','[]','[{"ja":"彼女が家に帰るや否や、すぐにテレビをつけました。","en":"As soon as she returned home, she turned on the TV.","romaji":"Kanojo ga ie ni kaeru ya ina ya, sugu ni terebi o tsukemashita.","zh":""},{"ja":"私が郵便箱を開けるや否や、手紙が落ちました。","en":"The moment I opened the mailbox, the letters fell out.","romaji":"Watashi ga yuubinbako o akeru ya ina ya, tegami ga ochimashita.","zh":""},{"ja":"子供たちは学校が終わるや否や、公園に走りました。","en":"As soon as school was over, the children ran to the park.","romaji":"Kodomo-tachi wa gakkou ga owaru ya ina ya, kouen ni hashirimashita.","zh":""},{"ja":"父が新聞を読むや否や、何かに震えていました。","en":"The moment my father read the newspaper, he started trembling about something.","romaji":"Chichi ga shinbun o yomu ya ina ya, nanika ni furuete imashita.","zh":""}]',replace('**Short**: Expresses the idea of ''as soon as'', ''the moment...''.\n\n**Formation**: Verb-dictionary form + や否や\n\n**Long**: The grammar point Verbる や否や is used to express something happening immediately after another action or event. It can be translated as ''as soon as...'' or ''the moment...''. The verb must be in dictionary form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ru_shimatsu_da','Verbる 始末だ',NULL,NULL,'N1','[]','[{"ja":"忘れてしまって、パスポートを家に置いてくる始末だった。","en":"I ended up leaving my passport at home because I forgot.","romaji":"Wasurete shimatte, pasupooto o ie ni oite-kuru shimatsu datta.","zh":""},{"ja":"毎晩遅くまで働いて、倒れる始末だ。","en":"I work until late every night and end up collapsing.","romaji":"Maiban osoku made hataraite, taoreru shimatsu da.","zh":""},{"ja":"勉強しなかったので、試験に落ちる始末だ。","en":"I didn''t study, so I ended up failing the exam.","romaji":"Benkyou shinakatta node, shiken ni ochiru shimatsu da.","zh":""},{"ja":"電車が遅れたため、会議に遅れる始末だ。","en":"Because the train was delayed, I ended up being late for the meeting.","romaji":"Densha ga okureta tame, kaigi ni okureru shimatsu da.","zh":""}]',replace('**Short**: Indicates a (often unfortunate) result or conclusion of an action.\n\n**Formation**: Verb-dictionary form + 始末だ\n\n**Long**: The ～る始末だ grammar point expresses the outcome or conclusion of an action, typically a negative or unfortunate result. It can be translated as ''end up...'', ''the result is...'', or ''the conclusion is...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ru_kirai_ga_aru','Verbる 嫌いがある',NULL,NULL,'N1','[]','[{"ja":"彼女は遅刻する嫌いがある。","en":"She has a tendency to be late.","romaji":"Kanojo wa chikoku suru kirai ga aru.","zh":""},{"ja":"私の父はお酒を飲み過ぎる嫌いがある。","en":"My father has a habit of drinking too much alcohol.","romaji":"Watashi no chichi wa osake o nomisugiru kirai ga aru.","zh":""},{"ja":"彼は物をすぐ忘れる嫌いがある。","en":"He tends to forget things quickly.","romaji":"Kare wa mono o sugu wasureru kirai ga aru.","zh":""},{"ja":"彼女は人の話を途中で切る嫌いがある。","en":"She has a habit of interrupting people while they are speaking.","romaji":"Kanojo wa hito no hanashi o tochuu de kiru kirai ga aru.","zh":""}]',replace('**Short**: Tendency to do a negative action; have a bad habit of ~.\n\n**Formation**: Verb-dictionary form + 嫌いがある\n\n**Long**: The ～る嫌いがある grammar point is used to express a negative tendency or habit. It often carries a critical or disapproving tone and points out someone''s habitual action.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_itsumade_no_yara','いつまで～のやら',NULL,NULL,'N1','[]','[{"ja":"この試験勉強はいつまで続くのやら。","en":"I don''t know when this exam study will end.","romaji":"Kono shiken benkyou wa itsumade tsuzuku no yara.","zh":""},{"ja":"彼の話がいつ終わるのやら、わからない。","en":"I don''t know when his talk will finish.","romaji":"Kare no hanashi ga itsu owaru no yara, wakaranai.","zh":""},{"ja":"この雨がいつまで降り続くのやら。","en":"I don''t know when this rain will stop.","romaji":"Kono ame ga itsumade furitsuzuku no yara.","zh":""},{"ja":"コロナのパンデミックがいつまで続くのやら。","en":"I don''t know when this coronavirus pandemic will end.","romaji":"Korona no pandemikku ga itsumade tsuzuku no yara.","zh":""}]',replace('**Short**: Expresses uncertainty regarding duration; ''don''t know when... will end''.\n\n**Formation**: いつまで + Verb (dictionary form) + のやら\n\n**Long**: The いつまで～のやら grammar point is used to express uncertainty about when something will end or finish. It is often used in situations where the speaker is unsure about when a particular state of affairs or event will conclude.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ga_verb_rareru','～が Verb られる',NULL,NULL,'N1','[]','[{"ja":"彼がこの問題を解けると思いますか？","en":"Do you think he can solve this problem?","romaji":"Kare ga kono mondai o tokeru to omoimasu ka?","zh":""},{"ja":"私がその大きな箱を運べるか？","en":"Can I carry that big box?","romaji":"Watashi ga sono ookina hako o hakoberu ka?","zh":""},{"ja":"彼が早く走れると思います。","en":"I think he can run fast.","romaji":"Kare ga hayaku hashireru to omoimasu.","zh":""},{"ja":"彼女は日本語が話せる。","en":"She can speak Japanese.","romaji":"Kanojo wa nihongo ga hanaseru.","zh":""}]',replace('**Short**: Expresses potential or ability to do something; ''can'', ''able to''.\n\n**Formation**: ❶ (Group 1) Verb:  書く → 書ける / 飲む → 飲める, etc.\n❷ (Group 2) Verb-ます stem + られる (食べる→食べられる、見る→見られる)\n\n**Long**: The ～が Verb られる grammar pattern generally refers to the potential form of Japanese verbs (i.e., ''can do something''). However, the exact formation depends on the verb group. For most Group 1 (五段) verbs, potential form changes the final -u to -eru (e.g., 書く→書ける). For Group 2 (一段) verbs, you often see ～られる (e.g., 食べる→食べられる). In English, it translates as ''can'' or ''able to''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ka_to_omoikiya','～かと思いきや',NULL,NULL,'N1','[]','[{"ja":"明日は晴れるかと思いきや、まさかの雨が降った。","en":"I thought it would be sunny tomorrow, but unexpectedly it rained.","romaji":"Ashita wa hareru ka to omoikiya, masaka no ame ga futta.","zh":""},{"ja":"彼が試験に落ちたかと思いきや、合格していた。","en":"I thought he had failed the test, but he actually passed.","romaji":"Kare ga shiken ni ochita ka to omoikiya, goukaku shite ita.","zh":""},{"ja":"このケーキは美味しそうだったかと思いきや、全然甘くなかった。","en":"I thought this cake would be delicious, but it wasn’t sweet at all.","romaji":"Kono keeki wa oishisou datta ka to omoikiya, zenzen amakunakatta.","zh":""},{"ja":"列車が遅れるかと思いきや、時間通りに到着した。","en":"I thought the train would be late, but it arrived on time.","romaji":"Ressha ga okureru ka to omoikiya, jikan doori ni touchaku shita.","zh":""}]',replace('**Short**: Expressing unexpected outcomes; ''just when I thought...'', ''but...''.\n\n**Formation**: Sentence + かと思いきや (Verb plain form, i-/na-Adjective, or Noun + だ + かと思いきや)\n\n**Long**: The ～かと思いきや grammar point is used when the outcome turns out different from what was initially assumed or expected. It can be translated as ''just when I thought...'' or simply ''but (actually)...''. It often highlights that the speaker’s assumption was proven wrong by subsequent events.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ga_yue_ni','～がゆえに',NULL,NULL,'N1','[]','[{"ja":"愛情がゆえに、彼は彼女を許した。","en":"Because of love, he forgave her.","romaji":"Aijou ga yue ni, kare wa kanojo o yurushita.","zh":""},{"ja":"突然の雨がゆえに、試合は延期された。","en":"Due to the sudden rain, the match was postponed.","romaji":"Totsuzen no ame ga yue ni, shiai wa enki sareta.","zh":""},{"ja":"彼の努力がゆえに、彼は成功を収めた。","en":"Because of his efforts, he achieved success.","romaji":"Kare no doryoku ga yue ni, kare wa seikou o osameta.","zh":""},{"ja":"彼の死がゆえに、彼の家族は深い悲しみに包まれた。","en":"Due to his death, his family was enveloped in deep sorrow.","romaji":"Kare no shi ga yue ni, kare no kazoku wa fukai kanashimi ni tsutsumareta.","zh":""}]',replace('**Short**: Expresses the reason or cause; ''because'', ''due to'', ''as a result of''.\n\n**Formation**: Noun / Verb / Adjective + がゆえに\n\n**Long**: The ～がゆえに grammar point is used to express a reason or cause, often in more formal writing or speech. It roughly corresponds to ''because (of)'', ''due to'', or ''as a result of'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ga_yue_no_noun','～がゆえの Noun',NULL,NULL,'N1','[]','[{"ja":"愛がゆえの悲しみ。","en":"Sadness due to love.","romaji":"Ai ga yue no kanashimi.","zh":""},{"ja":"健康がゆえの幸せ。","en":"Happiness due to good health.","romaji":"Kenkou ga yue no shiawase.","zh":""},{"ja":"悪行がゆえの罰。","en":"Punishment due to wrongdoing.","romaji":"Akugyou ga yue no batsu.","zh":""},{"ja":"努力がゆえの成功。","en":"Success due to effort.","romaji":"Doryoku ga yue no seikou.","zh":""}]',replace('**Short**: Expresses the reason or cause for something; ''because of'', ''due to''.\n\n**Formation**: Noun / Verb-dictionary form + がゆえの + Noun\n\n**Long**: The ～がゆえの Noun pattern is used to describe a noun that exists or occurs due to some cause. It is often used in more literary or formal contexts.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kara_ni_itaru_made','～から Noun に 至る まで',NULL,NULL,'N1','[]','[{"ja":"このバンドの曲は、青年から老人に至るまで、人々に愛されています。","en":"The songs of this band are loved by people ranging from the young to the elderly.","romaji":"Kono bando no kyoku wa, seinen kara roujin ni itaru made, hitobito ni aisarete imasu.","zh":""},{"ja":"小さい物件から大きな建物に至るまで、全てのプロパティの管理を我々が行います。","en":"We handle all property management, ranging from small units to large buildings.","romaji":"Chiisai bukken kara ooki na tatemono ni itaru made, subete no property no kanri o wareware ga okonaimasu.","zh":""},{"ja":"朝のニュース放送から夜のドラマに至るまで、テレビは毎日見ています。","en":"I watch TV every day, from the morning news broadcasts to the night dramas.","romaji":"Asa no nyuusu housou kara yoru no dorama ni itaru made, terebi wa mainichi mite imasu.","zh":""},{"ja":"この地域は、春から冬に至るまで旅行者で賑わいます。","en":"This area is bustling with tourists from spring to winter.","romaji":"Kono chiiki wa, haru kara fuyu ni itaru made ryokousha de nigiwaimasu.","zh":""}]',replace('**Short**: Expressing range from one thing to another; ''from...to'', ''ranging from...to''.\n\n**Formation**: Noun (start) + から + Noun (end) + に至るまで\n\n**Long**: The ～から〜に至るまで grammar point emphasizes a range or scope extending from one extreme to another. It can be translated as ''from...to...'' or ''ranging from...to...'' in English. It can apply to people, places, times, objects, and so on.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_gotoku','～ごとく',NULL,NULL,'N1','[]','[{"ja":"彼は鳥のごとく飛んでいるように見えた。","en":"He looked as though he was flying like a bird.","romaji":"Kare wa tori no gotoku tonde iru you ni mieta.","zh":""},{"ja":"彼は死んだごとく眠っていた。","en":"He was sleeping as though he were dead.","romaji":"Kare wa shinda gotoku nemutte ita.","zh":""},{"ja":"彼女はアイドルのごとく崇められている。","en":"She is revered as if she were an idol.","romaji":"Kanojo wa aidoru no gotoku agamerarete iru.","zh":""},{"ja":"彼は風のごとく走った。","en":"He ran like the wind.","romaji":"Kare wa kaze no gotoku hashitta.","zh":""}]',replace('**Short**: To seem like; as if; as though.\n\n**Formation**: Verb-て + ごとく / Noun + の + ごとく\n\n**Long**: The ～ごとく grammar point is used to express similarity or resemblance. It is quite formal/literary, meaning ''as if,'' ''as though,'' or ''like.'' It can be used with verbs and nouns.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_koto_tote','～こととて',NULL,NULL,'N1','[]','[{"ja":"彼は裁判に勝つために全資産を使うこととて、弁護士に頼んだ。","en":"Since he''s using all his assets to win the trial, he hired a lawyer.","romaji":"Kare wa saiban ni katsu tame ni zenshisan o tsukau koto tote, bengoshi ni tanonda.","zh":""},{"ja":"明日は大切な試験があることとて、今夜は早く寝ます。","en":"Since I have an important exam tomorrow, I’m going to bed early tonight.","romaji":"Ashita wa taisetsu na shiken ga aru koto tote, konya wa hayaku nemasu.","zh":""},{"ja":"このプロジェクトの成功は会社の未来に影響することとて、全力を尽くします。","en":"Because the success of this project will affect the company''s future, I will do my best.","romaji":"Kono purojekuto no seikou wa kaisha no mirai ni eikyou suru koto tote, zenryoku o tsukushimasu.","zh":""},{"ja":"彼が有名人であることとて、プライバシーが保護されるべきだ。","en":"Since he is a celebrity, his privacy should be protected.","romaji":"Kare ga yuumeijin de aru koto tote, puraibashii ga hogo sareru beki da.","zh":""}]',replace('**Short**: Used to express the reason or premise for a decision or judgment; ''since'', ''because''.\n\n**Formation**: Verb (plain form) + こととて / Noun + の + こととて / (な-Adjective + な) + こととて\n\n**Long**: The ～こととて grammar point expresses a reason or premise in a slightly formal or literary way. It can often be interpreted as ''since'' or ''because''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_zuni_sunda','～ずにすんだ',NULL,NULL,'N1','[]','[{"ja":"彼は事故を起こさずにすんだ。","en":"He managed to avoid having an accident.","romaji":"Kare wa jiko o okosazu ni sunda.","zh":""},{"ja":"私は手術せずにすんだ。","en":"I was able to do without surgery.","romaji":"Watashi wa shujutsu sezu ni sunda.","zh":""},{"ja":"雨が降らずにすんだ。","en":"We managed to avoid the rain.","romaji":"Ame ga furazu ni sunda.","zh":""},{"ja":"罰金を払わずにすんだ。","en":"I managed to avoid paying a fine.","romaji":"Bakkin o harawazu ni sunda.","zh":""}]',replace('**Short**: Expresses the idea of ''was able to do without''; ''managed to avoid''.\n\n**Formation**: Verb-ず form + に + すんだ\n\n**Long**: The ～ずにすんだ grammar point indicates that one was able to avoid doing something or managed to get by without doing it. It translates as ''managed to avoid ~'' or ''got by without ~.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_darou_to_nakarou_to','～だろうとなかろうと',NULL,NULL,'N1','[]','[{"ja":"試験が難しいだろうとなかろうと、全力で頑張ります。","en":"Regardless of whether the exam is difficult or not, I will do my best.","romaji":"Shiken ga muzukashii darou to nakarou to, zenryoku de ganbarimasu.","zh":""},{"ja":"彼が来るだろうとなかろうと、私たちは始めます。","en":"Whether he comes or not, we will start.","romaji":"Kare ga kuru darou to nakarou to, watashitachi wa hajimemasu.","zh":""},{"ja":"この仕事が面白いだろうとなかろうと、私は続けます。","en":"Whether this job is interesting or not, I will continue.","romaji":"Kono shigoto ga omoshiroi darou to nakarou to, watashi wa tsuzukemasu.","zh":""},{"ja":"彼が賛成するだろうとなかろうと、私たちは進行します。","en":"Whether he agrees or not, we will proceed.","romaji":"Kare ga sansei suru darou to nakarou to, watashitachi wa shinkou shimasu.","zh":""}]',replace('**Short**: Expresses ''regardless of whether it is or isn''t''.\n\n**Formation**: Noun / i-Adjective / na-Adjective / Verb + だろうとなかろうと\n\n**Long**: The ～だろうとなかろうと grammar point is used to express the idea of ''regardless of whether it is or isn''t.'' It translates roughly as ''whether it is ~ or not'' in English. This construction emphasizes that the speaker’s stance or action does not change, regardless of the two possible conditions.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tsumori_da','～つもりだ',NULL,NULL,'N1','[]','[{"ja":"明日は早く起きるつもりです。","en":"I plan to wake up early tomorrow.","romaji":"Ashita wa hayaku okiru tsumori desu.","zh":""},{"ja":"私は日本語を勉強するつもりです。","en":"I intend to study Japanese.","romaji":"Watashi wa nihongo o benkyou suru tsumori desu.","zh":""},{"ja":"彼は留学するつもりだと言った。","en":"He said he plans to study abroad.","romaji":"Kare wa ryuugaku suru tsumori da to itta.","zh":""},{"ja":"私は来週末に家族と旅行するつもりだ。","en":"I plan to travel with my family next weekend.","romaji":"Watashi wa raishuumatsu ni kazoku to ryokou suru tsumori da.","zh":""}]',replace('**Short**: Expresses the speaker''s intention or plan.\n\n**Formation**: Verb-dictionary form + つもりだ\n\n**Long**: The ～つもりだ grammar point is used to express the speaker''s intention or plan to do something. It translates as ''intend to,'' ''plan to,'' or ''think that (I will).'' It''s often used with the verb in its dictionary form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tsumori_de','～つもりで',NULL,NULL,'N1','[]','[{"ja":"私は日本に住むつもりで日本語を勉強しています。","en":"I am studying Japanese with the intention of living in Japan.","romaji":"Watashi wa Nihon ni sumu tsumori de Nihongo o benkyou shiteimasu.","zh":""},{"ja":"彼は全てを失うつもりでギャンブルをしました。","en":"He gambled with the intention of risking everything.","romaji":"Kare wa subete o ushinau tsumori de gyanburu o shimashita.","zh":""},{"ja":"明日のテストに合格するつもりで一生懸命勉強します。","en":"I will study hard with the intention of passing tomorrow’s test.","romaji":"Ashita no tesuto ni goukaku suru tsumori de isshoukenmei benkyou shimasu.","zh":""},{"ja":"彼は早く起きるつもりで早く寝ました。","en":"He went to bed early with the intention of waking up early.","romaji":"Kare wa hayaku okiru tsumori de hayaku nemashita.","zh":""}]',replace('**Short**: Expresses the speaker''s intention or plan; ''with the intention of'', ''planning to''.\n\n**Formation**: Verb-dictionary form + つもりで\n\n**Long**: The ～つもりで grammar point is used to express the speaker''s intention or mindset when doing something. It can often be translated as ''with the intention of'' or ''with the mindset that.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_dewa_sumanai','～ではすまない',NULL,NULL,'N1','[]','[{"ja":"ただ謝るではすまない。何か行動を取らなければならない。","en":"Just apologizing will not suffice. Some action needs to be taken.","romaji":"Tada ayamaru dewa sumanai. Nanika koudou o toranakereba naranai.","zh":""},{"ja":"この問題は議論だけではすまない。具体的な計画が必要だ。","en":"This problem won''t be solved with just discussions. A concrete plan is needed.","romaji":"Kono mondai wa giron dake dewa sumanai. Gutaiteki na keikaku ga hitsuyou da.","zh":""},{"ja":"彼の失敗は注意だけではすまない。彼はその責任を取るべきだ。","en":"His failure won''t be resolved with just a warning. He should take responsibility.","romaji":"Kare no shippai wa chuui dake dewa sumanai. Kare wa sono sekinin o toru beki da.","zh":""},{"ja":"この失敗は金だけではすまない。信頼を取り戻すため、真心で謝罪するべきだ。","en":"This mistake cannot be settled with money alone. To regain trust, an earnest apology is needed.","romaji":"Kono shippai wa kane dake dewa sumanai. Shinrai o torimodosu tame, magokoro de shazai suru beki da.","zh":""}]',replace('**Short**: Expresses that just doing something is not enough or will not suffice.\n\n**Formation**: Verb-dictionary form + ではすまない / い-Adjective + ではすまない / な-Adjective + ではすまない / Noun + ではすまない\n\n**Long**: The grammar point ～ではすまない is used when the speaker strongly feels that an action or situation alone is not sufficient or acceptable, implying that more serious measures are needed or that the consequences are more severe.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_atte','～とあって',NULL,NULL,'N1','[]','[{"ja":"春休みとあって、公園は子供たちでいっぱいだ。","en":"Because it''s spring break, the park is full of children.","romaji":"Haruyasumi to atte, kouen wa kodomo-tachi de ippai da.","zh":""},{"ja":"試験前とあって、図書館は学生で混んでいる。","en":"With exams coming up, the library is crowded with students.","romaji":"Shiken mae to atte, toshokan wa gakusei de konde iru.","zh":""},{"ja":"開店日とあって、その店にはたくさんの人が並んでいた。","en":"Because it was the store''s opening day, a lot of people lined up.","romaji":"Kaitenbi to atte, sono mise ni wa takusan no hito ga narande ita.","zh":""},{"ja":"彼の誕生日とあって、友人たちはサプライズパーティーを計画した。","en":"Because it was his birthday, his friends planned a surprise party.","romaji":"Kare no tanjoubi to atte, yuujin-tachi wa sapuraizu paatii o keikaku shita.","zh":""}]',replace('**Short**: Expresses a special situation or event due to certain circumstances.\n\n**Formation**: Noun + とあって / (Sometimes Verb + とあって, depending on context)\n\n**Long**: The ～とあって grammar point is used to indicate that, due to a special or noteworthy circumstance, a particular situation has occurred. It often translates as ''because (it is)...'' or ''given that...'' in English, emphasizing the uniqueness of the cause.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_areba','～とあれば',NULL,NULL,'N1','[]','[{"ja":"無料とあれば、誰でも利用したいと思います。","en":"If it''s free, anyone would want to use it.","romaji":"Muryou to areba, dare demo riyou shitai to omoimasu.","zh":""},{"ja":"この曲が流れるとあれば、彼は必ず踊り始めます。","en":"If this song starts playing, he will definitely begin to dance.","romaji":"Kono kyoku ga nagareru to areba, kare wa kanarazu odorihajimemasu.","zh":""},{"ja":"明日が休日だとあれば、今夜は遅くまで起きていられます。","en":"If tomorrow is a holiday, I can stay up late tonight.","romaji":"Ashita ga kyuujitsu da to areba, konya wa osoku made okite iraremasu.","zh":""},{"ja":"彼が参加するとあれば、このイベントは成功でしょう。","en":"If he participates, this event will surely be successful.","romaji":"Kare ga sanka suru to areba, kono ibento wa seikou deshou.","zh":""}]',replace('**Short**: Expresses a condition; ''if'', ''when'', ''since''.\n\n**Formation**: Verb-casual + とあれば / い-Adjective + とあれば / な-Adjective + だとあれば / Noun + だとあれば\n\n**Long**: The ～とあれば grammar point is used to express a condition or premise in which a certain outcome or action naturally follows. It can be translated as ''if,'' ''when,'' or ''since,'' depending on context. It emphasizes that under this specific condition, a certain response is expected.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_iedomo','～といえども',NULL,NULL,'N1','[]','[{"ja":"彼が天才といえども、ミスをすることはあります。","en":"Even though he’s a genius, he still makes mistakes.","romaji":"Kare ga tensai to iedomo, misu o suru koto wa arimasu.","zh":""},{"ja":"このパソコンが新しいといえども、問題があります。","en":"Even though this computer is new, it has problems.","romaji":"Kono pasokon ga atarashii to iedomo, mondai ga arimasu.","zh":""},{"ja":"春といえども、まだ寒い日があります。","en":"Even though it''s spring, there are still cold days.","romaji":"Haru to iedomo, mada samui hi ga arimasu.","zh":""},{"ja":"彼女が一番好きな人といえども、嫌なことは嫌です。","en":"Even though she’s my favorite person, unpleasant things are still unpleasant.","romaji":"Kanojo ga ichiban suki na hito to iedomo, iya na koto wa iya desu.","zh":""}]',replace('**Short**: Even if it is said that; Even though; Although.\n\n**Formation**: Noun + といえども / Verb-plain form + といえども / Adjective + といえども\n\n**Long**: The ～といえども grammar point is used to show a contrast or contradiction. It is similar to ''even though'' or ''although'' in English. It can be used with nouns, verbs, adjectives, etc., to emphasize that the reality is different from the assumption or label.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_ittara_ari_wa_shinai','～といったらありはしない',NULL,NULL,'N1','[]','[{"ja":"彼の英語の上手さといったらありはしない。","en":"His English is unbelievably good.","romaji":"Kare no eigo no jouzusa to ittara ari wa shinai.","zh":""},{"ja":"このスイーツの美味しさといったらありはしない。","en":"These sweets are unbelievably delicious.","romaji":"Kono suiitsu no oishisa to ittara ari wa shinai.","zh":""},{"ja":"その子の頭の良さといったらありはしない。","en":"That kid''s intelligence is unsurpassed.","romaji":"Sono ko no atama no yosa to ittara ari wa shinai.","zh":""},{"ja":"彼女の美しさといったらありはしない。","en":"Her beauty is beyond belief.","romaji":"Kanojo no utsukushisa to ittara ari wa shinai.","zh":""}]',replace('**Short**: Express extreme exclamation; ''extremely'', ''unbelievable'', ''unsurpassed''.\n\n**Formation**: Noun + といったらありはしない / な-Adjective + といったらありはしない\n\n**Long**: The ～といったらありはしない grammar point is used to express an extreme degree of something, often surprise or admiration. It can be loosely translated as ''unbelievably...'' or ''incredibly...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_ittara_arya_shinai','～といったらありゃしない',NULL,NULL,'N1','[]','[{"ja":"その店のラーメンは美味しいといったらありゃしない。","en":"You have no idea how delicious the ramen at that shop is.","romaji":"Sono mise no ramen wa oishii to ittara arya shinai.","zh":""},{"ja":"彼女の料理の腕前は上手だといったらありゃしない。","en":"You have no idea how skilled she is at cooking.","romaji":"Kanojo no ryouri no udemae wa jouzu da to ittara arya shinai.","zh":""},{"ja":"この冬の寒さは厳しいといったらありゃしない。","en":"You have no idea how harsh this winter''s cold is.","romaji":"Kono fuyu no samusa wa kibishii to ittara arya shinai.","zh":""},{"ja":"その小説は面白いといったらありゃしない。","en":"You have no idea how interesting that novel is.","romaji":"Sono shousetsu wa omoshiroi to ittara arya shinai.","zh":""}]',replace('**Short**: Emphasizes that something is to the extreme; ''you have no idea how...'', ''it''s incredibly...''.\n\n**Formation**: Verb-casual + といったらありゃしない / い-Adjective + といったらありゃしない / な-Adjective + だ + といったらありゃしない / Noun + だ + といったらありゃしない\n\n**Long**: The ～といったらありゃしない grammar point is an idiomatic expression used to emphasize that something is extremely or incredibly a certain way—often beyond words. It can be loosely rendered as ''you wouldn''t believe how...'' or ''it''s indescribably...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_ittara_nai','～といったらない',NULL,NULL,'N1','[]','[{"ja":"今日は寒いといったらない。","en":"It’s extremely cold today.","romaji":"Kyou wa samui to ittara nai.","zh":""},{"ja":"彼女の料理の美味しさといったらない。","en":"Nothing can be more delicious than her cooking.","romaji":"Kanojo no ryouri no oishisa to ittara nai.","zh":""},{"ja":"この子の頭の良さだといったらない。","en":"This child is unbelievably smart.","romaji":"Kono ko no atama no yosa da to ittara nai.","zh":""},{"ja":"彼の怠けっぷりだといったらない。","en":"Nobody could be lazier than him.","romaji":"Kare no namakeppuri da to ittara nai.","zh":""}]',replace('**Short**: Expresses the extreme of something; ''nothing can be more ... than this''.\n\n**Formation**: い-Adjective + といったらない / な-Adjective + だといったらない / Noun + だといったらない\n\n**Long**: The ～といったらない grammar point is used to emphasize the high degree or intensity of an action or state. It can be translated as “nothing can be more ... than this” or “it’s extremely...”. It conveys that something is so intense or extreme that it cannot be adequately described.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_kite_iru','～ときている',NULL,NULL,'N1','[]','[{"ja":"仕事が忙しいときているので、なかなか休みが取れません。","en":"Because work is so busy, I just can’t take any time off.","romaji":"Shigoto ga isogashii to kite iru no de, nakanaka yasumi ga toremasen.","zh":""},{"ja":"経済が悪いときているだけに、会社が大量解雇を発表した。","en":"Since the economy is in such bad shape, the company announced mass layoffs.","romaji":"Keizai ga warui to kite iru dake ni, kaisha ga tairyou kaiko o happyou shita.","zh":""},{"ja":"旅行先で荷物を盗まれたときているから、旅行を楽しむどころではない。","en":"Given that my luggage was stolen while traveling, there’s no way I can enjoy the trip.","romaji":"Ryokousaki de nimotsu o nusumareta to kite iru kara, ryokou o tanoshimu dokoro de wa nai.","zh":""},{"ja":"試験が近いときているうえに、課題も山ほどあって大変だ。","en":"Not only are exams coming up, but I also have a mountain of assignments, so it’s really tough.","romaji":"Shiken ga chikai to kite iru ue ni, kadai mo yamahodo atte taihen da.","zh":""}]',replace('**Short**: Highlights a situation or condition that is serious/extreme, often with a negative nuance.\n\n**Formation**: Verb-casual / い-Adjective / な-Adjective（＋だ） / Noun（＋だ） + ときている\n\n**Long**: The grammar point ～ときている is used to emphasize that some circumstance is particularly notable—often negatively. It implies, “Given that things are so ~, it’s no wonder that...” or “Because the situation is (too) ~, such-and-such follows.” It is relatively informal and more common in spoken language.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tokoro_wo','～ところを',NULL,NULL,'N1','[]','[{"ja":"ちょうど映画を見ているところを、停電で真っ暗になった。","en":"Just when I was in the middle of watching a movie, the power went out and everything went dark.","romaji":"Choudo eiga o mite iru tokoro o, teiden de makkura ni natta.","zh":""},{"ja":"美味しく食べているところを、彼が全部横取りしてしまった。","en":"Right when I was enjoying my meal, he took it all away.","romaji":"Oishiku tabete iru tokoro o, kare ga zenbu yokodori shite shimatta.","zh":""},{"ja":"飛行機が離陸しようとしているところを、急にエンジンが止まった。","en":"Just as the plane was about to take off, the engine suddenly stopped.","romaji":"Hikouki ga ririku shiyou to shite iru tokoro o, kyuu ni enjin ga tomatta.","zh":""},{"ja":"彼女が怒っているところを、私は冗談を言ってしまった。","en":"Even though she was angry, I went ahead and made a joke.","romaji":"Kanojo ga okotte iru tokoro o, watashi wa joudan o itte shimatta.","zh":""}]',replace('**Short**: Indicates a contrasting or inconvenient timing; ''just when...'', ''even though...''.\n\n**Formation**: Verb-ている + ところを / Noun + の + ところを / い-Adjective + ところを / な-Adjective + な + ところを\n\n**Long**: The grammar point ～ところを is often used when something happens (or one acts) at a certain moment/condition that makes the timing inconvenient or contrary to what is expected. It can imply “in spite of the fact that...” or “just when...” depending on context.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_sareru','～とされる',NULL,NULL,'N1','[]','[{"ja":"サッカーは世界で最も人気のあるスポーツとされています。","en":"Soccer is considered the most popular sport in the world.","romaji":"Sakkaa wa sekai de mottomo ninki no aru supootsu to sarete imasu.","zh":""},{"ja":"彼は最も有能な科学者とされる。","en":"He is considered the most talented scientist.","romaji":"Kare wa mottomo yuunou na kagakusha to sareru.","zh":""},{"ja":"この建物は地元のランドマークだとされています。","en":"This building is said to be a local landmark.","romaji":"Kono tatemono wa jimoto no randomaaku da to sarete imasu.","zh":""},{"ja":"そのお寺は古代の美術品とされている。","en":"That temple is considered an ancient work of art.","romaji":"Sono otera wa kodai no bijutsuhin to sarete iru.","zh":""}]',replace('**Short**: Indicates a general belief or widely accepted view; ''is considered'', ''is seen as'', ''is said to be''.\n\n**Formation**: Verb-casual + とされる / い-Adjective + とされる / な-Adjective + だとされる / Noun + だとされる\n\n**Long**: The ～とされる grammar point expresses what is generally believed, accepted, or reputed. It can be translated as ''is considered to be,'' ''is seen as,'' or ''is said to be.'' It’s often used in formal or written contexts. The structure differs slightly depending on whether it’s used with a noun, adjective, or verb.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_shita_tokoro_de','～としたところで',NULL,NULL,'N1','[]','[{"ja":"彼が来るとしたところで、何も変わらないだろう。","en":"Even if he comes, nothing will probably change.","romaji":"Kare ga kuru to shita tokoro de, nani mo kawaranai darou.","zh":""},{"ja":"美味しいお菓子を作るとしたところで、それが売れる保証はない。","en":"Even if we make delicious sweets, there''s no guarantee they’ll sell.","romaji":"Oishii okashi o tsukuru to shita tokoro de, sore ga ureru hoshou wa nai.","zh":""},{"ja":"電話をかけるとしたところで、彼女が出るとは限らない。","en":"Even if I call her, she might not pick up.","romaji":"Denwa o kakeru to shita tokoro de, kanojo ga deru to wa kagiranai.","zh":""},{"ja":"最高の材料を使うとしたところで、美味しくなるとは限らない。","en":"Even if you use the best ingredients, it might not turn out delicious.","romaji":"Saikou no zairyou o tsukau to shita tokoro de, oishiku naru to wa kagiranai.","zh":""}]',replace('**Short**: Means ''even if'' or ''even assuming''; emphasizes that the outcome won’t change.\n\n**Formation**: Verb-casual + としたところで / い-Adjective + としたところで / な-Adjective + だとしたところで / Noun + だとしたところで\n\n**Long**: The ～としたところで grammar point means ''even if'' or ''even assuming that ~.'' It highlights that even if the stated condition were met, the result would not significantly change. Often used to convey a sense of futility or skepticism in hypothetical statements.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_suru_to','～とすると',NULL,NULL,'N1','[]','[{"ja":"彼が来るとすると、もうすぐ到着するはずです。","en":"If he’s coming, he should arrive soon.","romaji":"Kare ga kuru to suru to, mou sugu touchaku suru hazu desu.","zh":""},{"ja":"この仕事を終えるとすると、最低でも3日はかかるでしょう。","en":"Assuming we finish this work, it will take at least three days.","romaji":"Kono shigoto o oeru to suru to, saitei demo mikka wa kakaru deshou.","zh":""},{"ja":"戦争が起きるとすると、多くの人々が犠牲になるでしょう。","en":"If a war were to break out, many people would become victims.","romaji":"Sensou ga okiru to suru to, ooku no hitobito ga gisei ni naru deshou.","zh":""},{"ja":"彼が経営者だとすると、多くの責任を負うことになるでしょう。","en":"If he’s the manager, he will bear a lot of responsibility.","romaji":"Kare ga keieisha da to suru to, ooku no sekinin o ou koto ni naru deshou.","zh":""}]',replace('**Short**: Expresses ''if'', ''when'', or ''assuming that'' in a speculative sense.\n\n**Formation**: Verb-casual + とすると / い-Adjective + とすると / な-Adjective + だとすると / Noun + だとすると\n\n**Long**: The ～とすると grammar point is used for hypothetical or speculative situations, often in the sense of ''if we assume...'', ''when it comes to...'', or ''given that...'' . It sets up a condition and then states the expected or possible outcome.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_sureba','～とすれば',NULL,NULL,'N1','[]','[{"ja":"彼が嘘つきだとすれば、その話は信じられない。","en":"If he’s a liar, then his story can’t be believed.","romaji":"Kare ga usotsuki da to sureba, sono hanashi wa shinjirarenai.","zh":""},{"ja":"あなたが一緒に行くとすれば、私も行きます。","en":"If you are going, I''ll go too.","romaji":"Anata ga issho ni iku to sureba, watashi mo ikimasu.","zh":""},{"ja":"彼が浮気しているとすれば、どうすればいい？","en":"If he’s cheating, what should I do?","romaji":"Kare ga uwaki shite iru to sureba, dou sureba ii?","zh":""},{"ja":"その薬が効かないとすれば、他の方法を試すべきだ。","en":"If that medicine doesn’t work, we should try something else.","romaji":"Sono kusuri ga kikanai to sureba, hoka no houhou o tamesu beki da.","zh":""}]',replace('**Short**: Used to express ''if it were the case that...'', ''if we assume that...''.\n\n**Formation**: Verb-casual + とすれば / い-Adjective + とすれば / な-Adjective + だとすれば / Noun + だとすれば\n\n**Long**: The ～とすれば grammar point poses a hypothetical condition and then draws a conclusion or inference. It translates as ''if we suppose/assume that...'' or ''if it is the case that...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_nattara','～となったら',NULL,NULL,'N1','[]','[{"ja":"旅行に行くとなったら、荷造りをしなければいけません。","en":"If it comes to going on a trip, we have to pack.","romaji":"Ryokou ni iku to nattara, nizukuri o shinakereba ikemasen.","zh":""},{"ja":"試験に落ちるとなったら、どうしよう。","en":"What should I do if I fail the exam?","romaji":"Shiken ni ochiru to nattara, dou shiyou.","zh":""},{"ja":"彼女と別れるとなったら、とても悲しいです。","en":"If it comes to breaking up with her, I’ll be very sad.","romaji":"Kanojo to wakareru to nattara, totemo kanashii desu.","zh":""},{"ja":"結婚するとなったら、人生が大きく変わるでしょう。","en":"When it comes to getting married, life will probably change drastically.","romaji":"Kekkon suru to nattara, jinsei ga ookiku kawaru deshou.","zh":""}]',replace('**Short**: Used to express ''if it comes to...'', ''when it becomes the case that...''.\n\n**Formation**: Verb-casual + となったら / Noun + となったら\n\n**Long**: The ～となったら grammar point is used to describe a situation where, if matters progress to that stage, a certain action or outcome will follow. It’s often translated as ''when it comes to...'', ''if it comes to...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_naru_to','～となると',NULL,NULL,'N1','[]','[{"ja":"試験となると、多くの学生が緊張する。","en":"When it comes to exams, many students get nervous.","romaji":"Shiken to naru to, ooku no gakusei ga kinchou suru.","zh":""},{"ja":"東京へ引っ越すとなると、生活費が一気に上がる。","en":"If you move to Tokyo, the cost of living goes up drastically.","romaji":"Toukyou e hikkosu to naru to, seikatsuhi ga ikki ni agaru.","zh":""},{"ja":"締め切りが明日となると、今夜は徹夜になりそうだ。","en":"If the deadline is tomorrow, I’ll probably be up all night.","romaji":"Shimekiri ga ashita to naru to, konya wa tetsuya ni narisou da.","zh":""},{"ja":"彼がリーダーとなると、チームの活動は大きく改善されるかもしれない。","en":"If he becomes the leader, the team’s activities might improve significantly.","romaji":"Kare ga riidaa to naru to, chiimu no katsudou wa ookiku kaizen sareru kamoshirenai.","zh":""}]',replace('**Short**: Used to highlight a certain circumstance; ''when it comes to...'', ''if it becomes...'', ''in the event that...''.\n\n**Formation**: Verb-casual + となると / い-Adjective + となると / な-Adjective + だとなると / Noun + だとなると\n\n**Long**: The ～となると grammar point highlights a specific situation or condition and indicates what normally or naturally happens under that circumstance. It can be translated as ''when it comes to...'', ''if it becomes...'', or ''in the event that...''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_nareba','～となれば',NULL,NULL,'N1','[]','[{"ja":"彼がリーダーとなれば、プロジェクトは成功するでしょう。","en":"If he becomes the leader, the project will probably succeed.","romaji":"Kare ga riidaa to nareba, purojekuto wa seikou suru deshou.","zh":""},{"ja":"明日が雨だとなれば、ピクニックをキャンセルしましょう。","en":"If it turns out to be raining tomorrow, let''s cancel the picnic.","romaji":"Ashita ga ame da to nareba, pikunikku wo kyanseru shimashou.","zh":""},{"ja":"この仕事が終わったとなれば、休暇を取ることができます。","en":"If this job is over, you can take a vacation.","romaji":"Kono shigoto ga owatta to nareba, kyuuka wo toru koto ga dekimasu.","zh":""},{"ja":"そのテストが難しいとなれば、より一層勉強しなければならない。","en":"If that test is difficult, we must study all the more.","romaji":"Sono tesuto ga muzukashii to nareba, yori issou benkyou shinakereba naranai.","zh":""}]',replace('**Short**: Expresses the idea of ''if it comes to...; when we talk about...; in the case of...''.\n\n**Formation**: Verb-casual + となれば, い-Adjective + となれば, な-Adjective + だとなれば, Noun + だとなれば\n\n**Long**: The ～となれば grammar point is used to express a situation where a particular case or condition brings about a certain result or consequence. It translates as ''if it comes to...; when we talk about...; in the case of...'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_no_koto_da','～とのことだ',NULL,NULL,'N1','[]','[{"ja":"週末にパーティーがあるとのことだ。","en":"I''ve heard that there is a party this weekend.","romaji":"Shuumatsu ni paatii ga aru to no koto da.","zh":""},{"ja":"彼は来年ロンドンに引っ越すとのことだ。","en":"I was told that he is moving to London next year.","romaji":"Kare wa rainen Rondon ni hikkosu to no koto da.","zh":""},{"ja":"彼女は新しい仕事についたとのことだ。","en":"I''ve heard that she has gotten a new job.","romaji":"Kanojo wa atarashii shigoto ni tsuita to no koto da.","zh":""},{"ja":"明日は試験がないとのことだ。","en":"I was told that there is no exam tomorrow.","romaji":"Ashita wa shiken ga nai to no koto da.","zh":""}]',replace('**Short**: Expresses something that the speaker heard; ''I''ve heard that'', ''I was told that''.\n\n**Formation**: Simplified phrase + とのことだ\n\n**Long**: The ～とのことだ grammar point is used to express something that the speaker has heard from someone else. It can be roughly translated as ''I''ve heard that'', ''I was told that'' in English. It is a formal way to present hearsay or information the speaker did not directly witness but was informed about.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_wa_ie','～とはいえ',NULL,NULL,'N1','[]','[{"ja":"彼は頭が良いとはいえ、少し怠け者だ。","en":"Although he is smart, he is a bit lazy.","romaji":"Kare wa atama ga yoi to wa ie, sukoshi namakemono da.","zh":""},{"ja":"このレストランは美味しいとはいえ、ちょっと高い。","en":"While this restaurant is delicious, it''s a bit expensive.","romaji":"Kono resutoran wa oishii to wa ie, chotto takai.","zh":""},{"ja":"日本は小さい国だとはいえ、技術は世界一だ。","en":"Even though Japan is a small country, its technology is among the best in the world.","romaji":"Nihon wa chiisai kuni da to wa ie, gijutsu wa sekaiichi da.","zh":""},{"ja":"彼女は若いとはいえ、経験豊富だ。","en":"Even though she is young, she is very experienced.","romaji":"Kanojo wa wakai to wa ie, keiken houfu da.","zh":""}]',replace('**Short**: Even though; although; but\n\n**Formation**: Noun + とはいえ, な-Adjective + だとはいえ, い-Adjective + とはいえ, Verb-casual + とはいえ\n\n**Long**: The ～とはいえ grammar structure is used to express the contradictory nature of a situation or event. It means ''even though'' or ''although'', signifying a sense of contrast or contradiction. The usage of this structure is mainly seen in a formal or written context.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_miete','～とみえて',NULL,NULL,'N1','[]','[{"ja":"彼は運動が得意とみえて、毎日ジムに行っています。","en":"He seems to be good at exercise, as he goes to the gym every day.","romaji":"Kare wa undou ga tokui to miete, mainichi jimu ni itteimasu.","zh":""},{"ja":"彼女は忙しいとみえて、なかなか会えない。","en":"She seems to be busy, as it''s hard to meet her.","romaji":"Kanojo wa isogashii to miete, nakanaka aenai.","zh":""},{"ja":"田中さんは疲れているとみえて、早く帰りました。","en":"It seems that Tanaka-san was tired, as he went home early.","romaji":"Tanaka-san wa tsukarete iru to miete, hayaku kaerimashita.","zh":""},{"ja":"その店は人気だとみえて、いつも行列ができている。","en":"That shop seems to be popular, as there is always a line.","romaji":"Sono mise wa ninki da to miete, itsumo retsu ga dekite iru.","zh":""}]',replace('**Short**: It seems that; apparently\n\n**Formation**: Verb-casual + とみえて, い-Adjective + とみえて, な-Adjective + だとみえて, Noun + だとみえて\n\n**Long**: The ～とみえて grammar point is used to express the speaker''s judgment about a situation based on visible or known information. It is often translated as ''apparently'' or ''it seems that'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_mirareru','～とみられる',NULL,NULL,'N1','[]','[{"ja":"彼の行動は無責任とみられる。","en":"His behavior is considered irresponsible.","romaji":"Kare no koudou wa musekinin to mirareru.","zh":""},{"ja":"この絵はピカソの作品とみられている。","en":"This painting is believed to be a work of Picasso.","romaji":"Kono e wa pikaso no sakuhin to mirareteiru.","zh":""},{"ja":"地震の後、被害はさらに増加するとみられる。","en":"After the earthquake, damage is expected to increase further.","romaji":"Jishin no ato, higai wa sara ni zouka suru to mirareru.","zh":""},{"ja":"週末は天気が良くなるとみられる。","en":"The weather is expected to improve on the weekend.","romaji":"Shuumatsu wa tenki ga yoku naru to mirareru.","zh":""}]',replace('**Short**: It is considered that; It is thought that; It is believed that\n\n**Formation**: Verb-casual + とみられる, Noun + とみられる\n\n**Long**: The ～とみられる grammar point is used to express how an idea, fact, or circumstance is considered or understood. This phrase is often used in news or reports to show the speaker''s or writer''s estimation, judgment, or present belief about something.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_miru_to','～とみると',NULL,NULL,'N1','[]','[{"ja":"この問題を数学の視点でとみると、解決策が見えてきます。","en":"When one sees this problem from a mathematical perspective, a solution begins to emerge.","romaji":"Kono mondai o suugaku no shiten de to miru to, kaiketsusaku ga miete kimasu.","zh":""},{"ja":"彼女が優秀な学生だとみると、その賞をもらったのは当然です。","en":"Considering she is an excellent student, it''s natural that she received that award.","romaji":"Kanojo ga yuushuuna gakusei da to miru to, sono shou o moratta no wa touzen desu.","zh":""},{"ja":"彼が新入社員だとみると、その成果は素晴らしいです。","en":"Viewing him as a new employee, his achievements are exceptional.","romaji":"Kare ga shinnyuushain da to miru to, sono seika wa subarashii desu.","zh":""},{"ja":"このパンダが絶滅危惧種だとみると、保護が必要です。","en":"Considering this panda is an endangered species, it needs protection.","romaji":"Kono panda ga zetsumetsu kigushu da to miru to, hogo ga hitsuyou desu.","zh":""}]',replace('**Short**: Expresses the concept of ''when one sees it as'', ''viewed as'', or ''considering''.\n\n**Formation**: Verb-casual + とみると, い-Adjective + とみると, な-Adjective + だとみると, Noun + だとみると\n\n**Long**: The ～とみると grammar point is used to express the concept of seeing something from a specific perspective and responding accordingly. It often brings awareness toward something or a change in perception. It is translated as ''when one sees it as'', ''viewed as'', or ''considering''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_donna_ni_u_ga','どんなに～うが',NULL,NULL,'N1','[]','[{"ja":"どんなに頑張ろうが、彼の速さには追いつけない。","en":"No matter how hard I try, I can''t catch up with his speed.","romaji":"Donna ni ganbarou ga, kare no hayasa ni wa oitsukenai.","zh":""},{"ja":"どんなに食べようが、彼女は太らない。","en":"No matter how much she eats, she doesn''t gain weight.","romaji":"Donna ni tabeyou ga, kanojo wa futoranai.","zh":""},{"ja":"どんなに寒かろうが、彼は毎日ジョギングをします。","en":"No matter how cold it is, he goes jogging every day.","romaji":"Donna ni samukarou ga, kare wa mainichi jogging wo shimasu.","zh":""},{"ja":"どんなに暑かろうが、エアコンは使いません。","en":"No matter how hot it is, I don''t use air conditioning.","romaji":"Donna ni atsukarou ga, eakon wa tsukaimasen.","zh":""}]',replace('**Short**: Expresses ''no matter how much...'', ''even if...''.\n\n**Formation**: どんなに + Verb-volitional + うが, どんなに + い-Adjective(～かろう) + が, どんなに + な-Adjective + だろうが\n\n**Long**: The grammar point どんなに～うが is used to express a condition that is not affected by the degree of an action or state. It can be translated as ''no matter how much...'' or ''even if...''. It is generally used with verbs, い-adjectives and な-adjectives in their volitional or かろう/だろう form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_iwan_bakari_ni','～と言わんばかりに',NULL,NULL,'N1','[]','[{"ja":"彼女は優勝したと言わんばかりに笑った。","en":"She laughed as if to say she won.","romaji":"Kanojo wa yuushou shita to iwan bakari ni waratta.","zh":""},{"ja":"彼は倒れると言わんばかりの疲労感があった。","en":"He was so fatigued it was as if he might collapse.","romaji":"Kare wa taoreru to iwan bakari no hiroukan ga atta.","zh":""},{"ja":"彼女は雨の日を恐れていて、晴れてほしいと言わんばかりに窓の外を見つめていた。","en":"She was afraid of rainy days, almost as if to say she wanted it to be sunny, as she gazed out the window.","romaji":"Kanojo wa ame no hi o osorete ite, harete hoshii to iwan bakari ni mado no soto o mitsumete ita.","zh":""},{"ja":"彼の行動は、誰にも信じてもらえないと言わんばかりだった。","en":"His behavior was as if to say that no one would believe him.","romaji":"Kare no koudou wa, dare ni mo shinjite moraenai to iwan bakari datta.","zh":""}]',replace('**Short**: Indicates an action or behavior that strongly implies a certain unspoken message or feeling.\n\n**Formation**: Verb-volitional + と言わんばかりに, い-Adjective + と言わんばかりに, な-Adjective + だと言わんばかりに, Noun + だと言わんばかりに\n\n**Long**: The ～と言わんばかりに grammar point is used to express that someone''s action or behavior is so strong that it''s as if they are saying something without actually saying it. It can be translated as ''as if to say'' or ''almost as though stating''. This form is often used when the speaker wants to convey speculation about someone''s unvoiced thoughts or feelings based on their behavior.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_to_iwan_bakari_no_noun','～と言わんばかりの Noun',NULL,NULL,'N1','[]','[{"ja":"田中さんは嬉しくて飛び上がると言わんばかりの笑顔を見せた。","en":"Tanaka showed a smile as if to say he was so happy he could jump for joy.","romaji":"Tanaka-san wa ureshikute tobiagaru to iwan bakari no egao wo miseta.","zh":""},{"ja":"彼女は僕に話しかけると言わんばかりの視線を送った。","en":"She sent me glances as if to say she wanted to speak with me.","romaji":"Kanojo wa boku ni hanashikakeru to iwan bakari no shisen wo okutta.","zh":""},{"ja":"その老人は寒さで震えていると言わんばかりの姿を見せていた。","en":"The old man was shivering as if to say he was freezing from the cold.","romaji":"Sono roujin wa samusa de furueteiru to iwan bakari no sugata wo miseteita.","zh":""},{"ja":"彼の体は緊張で固まっていると言わんばかりの風格を放っている。","en":"He exudes an air as if his body were stiff from tension.","romaji":"Kare no karada wa kinchou de katamatteiru to iwan bakari no fuukaku wo hanatteiru.","zh":""}]',replace('**Short**: Expresses the concept of ''as if to say''; ''almost says''; ''suggests''.\n\n**Formation**: Verb-plain form + と言わんばかりの Noun\n\n**Long**: The ～と言わんばかりの Noun grammar point is used to express that someone''s action or a situation suggests a certain message, even though it is not explicitly said. It can be translated as ''as if to say'', ''almost says'', or ''suggests''. It is typically used to convey an unspoken message through someone''s demeanor or behavior.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nagara_ni','～ながらに',NULL,NULL,'N1','[]','[{"ja":"彼女は生まれながらにして優れた音感を持っている。","en":"She has had an excellent sense of pitch from birth.","romaji":"Kanojo wa umare nagara ni shite sugureta onkan o motte iru.","zh":""},{"ja":"彼は子供ながらに大人の会話を理解していた。","en":"Even though he was just a child, he understood adult conversations.","romaji":"Kare wa kodomo nagara ni otona no kaiwa o rikaishite ita.","zh":""},{"ja":"彼女は涙ながらに真実を訴えた。","en":"She pleaded the truth while in tears.","romaji":"Kanojo wa namida nagara ni shinjitsu o uttaeta.","zh":""},{"ja":"私たちは昔ながらに伝わる祭りを大切にしている。","en":"We cherish the traditional festival that has been passed down unchanged from old times.","romaji":"Watashi-tachi wa mukashi nagara ni tsutawaru matsuri o taisetsu ni shite iru.","zh":""}]',replace('**Short**: Expresses a state or condition continuing just as it is (e.g. ''from birth'', ''while crying'', ''in the old way'').\n\n**Formation**: Common set phrases: 生まれながらに, 涙ながらに, 昔ながらに, 子供ながらに, etc.\n\n**Long**: The ～ながらに grammar point is used to indicate a condition that remains unchanged from some starting point or in a certain manner. It appears in set phrases such as 生まれながらに (from birth), 涙ながらに (while crying), 昔ながらに (in the old/original way), 子供ながらに (even though [still] a child), etc.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nagara_no_noun','～ながらの Noun',NULL,NULL,'N1','[]','[{"ja":"テレビを見ながらの夕食は、子供たちにとって楽しいだろう。","en":"Eating dinner while watching TV might be fun for the children.","romaji":"Terebi o mi-nagara no yuushoku wa, kodomotachi ni totte tanoshii darou.","zh":""},{"ja":"地図を読みながらの運転は危険です。","en":"Driving while reading a map is dangerous.","romaji":"Chizu o yomi-nagara no unten wa kiken desu.","zh":""},{"ja":"散歩しながらの会話はリラックスできます。","en":"Talking during a walk can be relaxing.","romaji":"Sanpo shi-nagara no kaiwa wa rirakkusu dekimasu.","zh":""},{"ja":"音楽を聴きながらの勉強は集中力を高めるかもしれません。","en":"Studying while listening to music might improve concentration.","romaji":"Ongaku o kiki-nagara no benkyou wa shuuchuuryoku o takameru kamoshiremasen.","zh":""}]',replace('**Short**: Indicates one action or state happening at the same time as the noun in question (e.g. ''dinner while watching TV'').\n\n**Formation**: Verb-ますstem (or plain minus る) + ながら + の + Noun\n\n**Long**: The ～ながらの Noun grammar point is used to modify a noun by describing an action happening simultaneously. For example, テレビを見ながらの夕食 means ''dinner while watching TV.'' It can be translated as ''while ~ing'' or ''during ~.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_nagara_mo','～ながらも',NULL,NULL,'N1','[]','[{"ja":"彼は貧しいながらも、幸せな生活を送っている。","en":"Despite being poor, he leads a happy life.","romaji":"Kare wa mazushii nagara mo, shiawase na seikatsu o okutte iru.","zh":""},{"ja":"僕は忙しいながらも、毎日運動しています。","en":"Even though I am busy, I exercise every day.","romaji":"Boku wa isogashii nagara mo, mainichi undou shiteimasu.","zh":""},{"ja":"病気ながらも、彼は仕事を続けました。","en":"Despite being sick, he continued working.","romaji":"Byouki nagara mo, kare wa shigoto o tsuzukemashita.","zh":""},{"ja":"雨が降っているながらも、彼は散歩に出かけた。","en":"Even though it was raining, he went for a walk.","romaji":"Ame ga futte iru nagara mo, kare wa sanpo ni dekaketa.","zh":""}]',replace('**Short**: Means ''even though'' or ''despite''.\n\n**Formation**: Verb stem + ながらも, い-Adjective + ながらも, な-Adjective/Noun + ながらも\n\n**Long**: The ～ながらも grammar point is used to express contrast, highlighting the difference between what is usually expected from a situation and what actually happens. It can be translated as ''even though'' or ''despite.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_naku_wa_nai','～なくはない',NULL,NULL,'N1','[]','[{"ja":"それを終えるのは難しくなくはない。","en":"It''s not that it''s impossible to finish it.","romaji":"Sore o oeru no wa muzukashiku naku wa nai.","zh":""},{"ja":"彼に話すのは怖くなくはない。","en":"It''s not that I''m entirely unafraid to talk to him.","romaji":"Kare ni hanasu no wa kowaku naku wa nai.","zh":""},{"ja":"映画を見に行く時間がなくはない。","en":"It''s not that I don''t have time to go see a movie.","romaji":"Eiga o mi ni iku jikan ga naku wa nai.","zh":""},{"ja":"日本語で講演するのは難しくなくはない。","en":"It''s not impossible to give a lecture in Japanese, but it won''t be easy.","romaji":"Nihongo de kouen suru no wa muzukashiku naku wa nai.","zh":""}]',replace('**Short**: Expresses the idea ''it''s not that it''s impossible'' or ''it''s not that I can''t''.\n\n**Formation**: Verb-ないform + なくはない, い-Adjective－い + くはない, な-Adjective + ではなくはない, Noun + ではなくはない\n\n**Long**: The ～なくはない grammar point implies that while something may not be your first choice or not guaranteed, it''s not outright impossible. Translates to ''It''s not that it''s impossible,'' ''It''s not that I don''t/can''t ~.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_naku_mo_nai','～なくもない',NULL,NULL,'N1','[]','[{"ja":"彼がもうすぐ戻るなら、待つなくもない。","en":"If he’s coming back soon, waiting wouldn’t be a bad idea.","romaji":"Kare ga mou sugu modoru nara, matsu naku mo nai.","zh":""},{"ja":"この本が役に立つなら、買うなくもない。","en":"If this book is useful, it might not be a bad idea to buy it.","romaji":"Kono hon ga yaku ni tatsu nara, kau naku mo nai.","zh":""},{"ja":"天気が良ければ、ピクニックに行くなくもない。","en":"If the weather is nice, it wouldn''t be impossible for us to go on a picnic.","romaji":"Tenki ga yokereba, pikunikku ni iku naku mo nai.","zh":""},{"ja":"そのプロジェクトが成功すれば、プロモーションもあり得なくもない。","en":"If that project succeeds, a promotion might not be out of the question.","romaji":"Sono purojekuto ga seikou sureba, puromooshon mo arienaku mo nai.","zh":""}]',replace('**Short**: Expresses ''not impossible'' or ''might as well''.\n\n**Formation**: Verb-ないform + なくもない, い-Adjective－い + くもない, な-Adjective + でもない, Noun + でもない\n\n**Long**: The ～なくもない grammar point is used to suggest that something is not necessarily preferred or likely, but it''s also not out of the question. It can often translate to ''It’s not a bad idea'' or ''It might be feasible.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_unnamed','～なら～なりに',NULL,NULL,'N1','[]','[{"ja":"彼はまだ初心者なら初心者なりに頑張っている。","en":"Since he’s still a beginner, he’s doing his best in his own beginner way.","romaji":"Kare wa mada shoshinsha nara shoshinsha nari ni ganbatteiru.","zh":""},{"ja":"この料理は辛いなら辛いなりに美味しい。","en":"If this dish is spicy, it’s delicious in its own spicy way.","romaji":"Kono ryouri wa karai nara karai nari ni oishii.","zh":""},{"ja":"あの人は変なら変なりに面白い。","en":"If that person is strange, they’re interesting in their own strange way.","romaji":"Ano hito wa hen nara hen nari ni omoshiroi.","zh":""},{"ja":"この町は小さいなら小さいなりに楽しい。","en":"If this town is small, it’s fun in its own small way.","romaji":"Kono machi wa chiisai nara chiisai nari ni tanoshii.","zh":""}]',replace('**Short**: Means ''if it is X, then it''s X in its own way'', emphasizing unique qualities.\n\n**Formation**: Noun/Adjective + なら + (same Noun/Adjective) + なりに\n\n**Long**: The ～なら～なりに grammar point shows that something has its own particular way or style of being, based on that condition. It often conveys a positive acceptance or appreciation of the situation ''in its own way.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_wa_oyobanai','～には及ばない',NULL,NULL,'N1','[]','[{"ja":"ファーストクラスに乗るには及ばない、エコノミーでも十分だ。","en":"There’s no need to go as far as flying first class; economy is enough.","romaji":"Faasuto kurasu ni noru ni wa oyobanai, ekonomii demo juubun da.","zh":""},{"ja":"毎回会うたびにギフトを持って行くには及ばない。","en":"There’s no need to bring a gift every time you meet her.","romaji":"Maikai au tabi ni gifuto o motte iku ni wa oyobanai.","zh":""},{"ja":"その問題は先生に聞くには及ばない、自分で解決できる。","en":"That issue doesn’t warrant asking the teacher; you can solve it yourself.","romaji":"Sono mondai wa sensei ni kiku ni wa oyobanai, jibun de kaiketsu dekiru.","zh":""},{"ja":"小さな失敗のために、あんなに辛辣な言葉を使うには及ばないだろう。","en":"For such a small mistake, there’s no need to use such harsh words.","romaji":"Chiisana shippai no tame ni, anna ni shinratsu na kotoba o tsukau ni wa oyobanai darou.","zh":""}]',replace('**Short**: Means ''no need to go that far'' or ''not necessary''.\n\n**Formation**: Verb-dictionary form + には及ばない\n\n**Long**: The ～には及ばない grammar point is used to show that an action or degree of effort is unnecessary or excessive. It often translates to ''there’s no need to...'' or ''it doesn’t warrant...'' in English.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_taenai','～に堪えない',NULL,NULL,'N1','[]','[{"ja":"彼の冗談は聞くに堪えない。","en":"His jokes are unbearable to listen to.","romaji":"Kare no joudan wa kiku ni taenai.","zh":""},{"ja":"その映画は見るに堪えないほどひどい出来だ。","en":"That movie is so bad that it’s unbearable to watch.","romaji":"Sono eiga wa miru ni taenai hodo hidoi deki da.","zh":""},{"ja":"この小説は読むに堪えないほど退屈だ。","en":"This novel is so boring that it’s unbearable to read.","romaji":"Kono shousetsu wa yomu ni taenai hodo taikutsu da.","zh":""},{"ja":"彼の行動は見るに堪えない。","en":"His behavior is unbearable to watch.","romaji":"Kare no koudou wa miru ni taenai.","zh":""}]',replace('**Short**: Indicates something is unbearable or not worth doing (e.g., ''unbearable to watch'', ''unbearable to listen to'').\n\n**Formation**: Verb-dictionary form + に堪えない, Noun + に堪えない\n\n**Long**: The ～に堪えない grammar pattern is used when something is so unpleasant, awful, or painful that one cannot tolerate it. Common verbs include 見るに堪えない, 聞くに堪えない, 読むに堪えない, etc., meaning ''unbearable to see/hear/read.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_taeru_n1','～に堪える',NULL,NULL,'N1','[]','[{"ja":"彼の歌声は聞くに堪える。","en":"His singing voice is worth listening to.","romaji":"Kare no utagoe wa kiku ni taeru.","zh":""},{"ja":"この小説は読むに堪える内容だ。","en":"This novel is worth reading.","romaji":"Kono shousetsu wa yomu ni taeru naiyou da.","zh":""},{"ja":"あの映画は見るに堪える名作だ。","en":"That movie is a masterpiece worth watching.","romaji":"Ano eiga wa miru ni taeru meisaku da.","zh":""},{"ja":"彼の意見は十分に参考に堪える。","en":"His opinion is definitely worth considering.","romaji":"Kare no iken wa juubun ni sankou ni taeru.","zh":""}]',replace('**Short**: Used to say that something is ''worth doing'' or ''can stand up to'' something (the positive counterpart of ～に堪えない).\n\n**Formation**: Verb-dictionary form + に堪える, Noun + に堪える\n\n**Long**: The ～に堪える grammar point indicates that something is good enough or worthy enough to do (read, see, listen to, etc.). Common examples include 読むに堪える, 見るに堪える, 聞くに堪える, etc., meaning ''worth reading/watching/listening to.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_taeru_n1_2','～に耐える',NULL,NULL,'N1','[]','[{"ja":"彼は厳しい修行に耐えた。","en":"He endured the harsh training.","romaji":"Kare wa kibishii shugyou ni taeta.","zh":""},{"ja":"この橋は強風に耐えられる。","en":"This bridge can withstand strong winds.","romaji":"Kono hashi wa kyoufuu ni taerareru.","zh":""},{"ja":"彼女は苦しみに耐えた。","en":"She endured the pain.","romaji":"Kanojo wa kurushimi ni taeta.","zh":""},{"ja":"この建物は地震に耐えることができます。","en":"This building can withstand an earthquake.","romaji":"Kono tatemono wa jishin ni taeru koto ga dekimasu.","zh":""}]',replace('**Short**: To endure or withstand something; ''endure'', ''withstand'', ''tolerate''.\n\n**Formation**: Noun + に耐える\n\n**Long**: The ～に耐える grammar point is used to express the concept of enduring or withstanding something, often involving a degree of difficulty or hardship. It can be translated as ''endure'', ''withstand'', or ''tolerate'' in English. Here we focus on usage with nouns (e.g., a force or a hardship to endure).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_itatta','～に至った',NULL,NULL,'N1','[]','[{"ja":"彼は練習を重ねて、ついにプロのギタリストに至った。","en":"After repeated practice, he finally became a professional guitarist.","romaji":"Kare wa renshuu o kasanete, tsui ni puro no gitarisuto ni itatta.","zh":""},{"ja":"調査を進めるうちに、驚くべき結論に至った。","en":"As the investigation progressed, it led to a surprising conclusion.","romaji":"Chousa o susumeru uchi ni, odoroku beki ketsuron ni itatta.","zh":""},{"ja":"この問題はついに国際的な対立に至った。","en":"This issue finally led to an international conflict.","romaji":"Kono mondai wa tsui ni kokusaiteki na tairitsu ni itatta.","zh":""},{"ja":"たくさんの失敗を経て、成功に至った。","en":"After many failures, I finally achieved success.","romaji":"Takusan no shippai o hete, seikou ni itatta.","zh":""}]',replace('**Short**: Expresses the outcome or final conclusion of a process; ''reached the point'', ''led to''.\n\n**Formation**: Verb-てform + に至った or Noun / Verb-dictionary + に至る (more general).\n\n**Long**: The ～に至った grammar point is used to express the final outcome or conclusion that has been reached as a result of a process or a series of events. It can be translated as ''reached the point'', ''led to'', or ''resulted in'' in English. It often indicates a significant outcome.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_koshita_koto_wa_nai','～に越したことはない',NULL,NULL,'N1','[]','[{"ja":"早く準備するに越したことはない。","en":"It''s best to prepare early.","romaji":"Hayaku junbi suru ni koshita koto wa nai.","zh":""},{"ja":"新鮮な食材を使うに越したことはない。","en":"There''s nothing better than using fresh ingredients.","romaji":"Shinsen na shokuzai o tsukau ni koshita koto wa nai.","zh":""},{"ja":"安全運転に越したことはない。","en":"Safe driving is always best.","romaji":"Anzen unten ni koshita koto wa nai.","zh":""},{"ja":"健康的な生活を送るに越したことはない。","en":"There''s nothing better than leading a healthy lifestyle.","romaji":"Kenkouteki na seikatsu o okuru ni koshita koto wa nai.","zh":""}]',replace('**Short**: Expresses that something is the best or most desirable course of action; ''nothing better than...''.\n\n**Formation**: Verb (dictionary form) + に越したことはない, い-Adjective + に越したことはない, な-Adjective/Noun + である + に越したことはない\n\n**Long**: The ～に越したことはない grammar point indicates that a certain state or action is the most favorable or ideal. It literally conveys the idea that nothing surpasses the stated condition.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ni_katakunai','～に難くない',NULL,NULL,'N1','[]','[{"ja":"彼の喜びは想像に難くない。","en":"It''s not hard to imagine his delight.","romaji":"Kare no yorokobi wa souzou ni katakunai.","zh":""},{"ja":"この結果が彼女を失望させたことは理解に難くない。","en":"It''s not difficult to understand that this outcome disappointed her.","romaji":"Kono kekka ga kanojo o shitsubou saseta koto wa rikai ni katakunai.","zh":""},{"ja":"彼が怒る気持ちは察するに難くない。","en":"It''s not hard to guess why he is angry.","romaji":"Kare ga okoru kimochi wa sassuru ni katakunai.","zh":""},{"ja":"このような状況が起こった理由は想像に難くない。","en":"It''s not hard to imagine why this situation occurred.","romaji":"Kono youna joukyou ga okotta riyuu wa souzou ni katakunai.","zh":""}]',replace('**Short**: Expresses ''not difficult to ~'' in a formal/literary sense; e.g., ''not hard to imagine/understand''.\n\n**Formation**: Verb-dictionary form + に難くない (commonly with 想像する, 理解する, 察する, etc.)\n\n**Long**: The ～に難くない (～にかたくない) grammar is typically used in formal or literary contexts to indicate that something is not difficult. Common expressions include 想像に難くない (''not hard to imagine''), 理解に難くない (''not difficult to understand''), 察するに難くない, and so on.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_no_wa_noun_gurai_no_mono_da','～のは Noun ぐらいのものだ',NULL,NULL,'N1','[]','[{"ja":"この小説を読むのは暇つぶしぐらいのものだ。","en":"Reading this novel is nothing but a way to kill time.","romaji":"Kono shousetsu o yomu no wa hima tsubushi gurai no mono da.","zh":""},{"ja":"今日の夕食で良かったのはピザぐらいのものだ。","en":"About the only good thing at tonight''s dinner was the pizza.","romaji":"Kyou no yuushoku de yokatta no wa piza gurai no mono da.","zh":""},{"ja":"この映画を見るのは時間の無駄ぐらいのものだ。","en":"Watching this movie is nothing but a waste of time.","romaji":"Kono eiga o miru no wa jikan no muda gurai no mono da.","zh":""},{"ja":"彼と話すのはストレスぐらいのものだ。","en":"Talking to him is nothing but stressful.","romaji":"Kare to hanasu no wa sutoresu gurai no mono da.","zh":""}]',replace('**Short**: Conveys that ''only (Noun) is the case'' or ''nothing but (Noun)''.\n\n**Formation**: Verb-casual + のは + Noun + ぐらいのものだ, い-Adjective + のは + Noun + ぐらいのものだ, etc.\n\n**Long**: The ～のは Noun ぐらいのものだ pattern indicates that something is exclusively or solely that particular Noun, conveying the sense of ''That''s the only thing...'' or ''There''s nothing but...'' about a situation.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_bamono_o','～ば～ものを',NULL,NULL,'N1','[]','[{"ja":"早く起きれば、遅刻しなかったものを。","en":"If only I''d woken up early, I wouldn''t have been late.","romaji":"Hayaku okireba, chikoku shinakatta mono o.","zh":""},{"ja":"もっと頑張れば、テストに合格したものを。","en":"If only I''d tried harder, I would have passed the test.","romaji":"Motto ganbareba, tesuto ni goukaku shita mono o.","zh":""},{"ja":"お金があれば、新しい車を買ったものを。","en":"If only I had the money, I would have bought a new car.","romaji":"Okane ga areba, atarashii kuruma o katta mono o.","zh":""},{"ja":"友達がいれば、一緒に遊んだものを。","en":"If only I had a friend, I would have hung out together.","romaji":"Tomodachi ga ireba, issho ni asonda mono o.","zh":""}]',replace('**Short**: Expresses regret or a missed opportunity: ''if only'', ''had I but...''.\n\n**Formation**: Verb-ば + Verb-past + ものを, い-Adjective + ければ + ものを, な-Adjective/Noun + であれば + ものを, etc.\n\n**Long**: The ～ば～ものを grammar point shows regret about what could have been, often translated as ''if only...'' or ''it would have been better if...''. It can be used with verbs, adjectives, or nouns, usually in a past or conditional form.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_bita','～びた',NULL,NULL,'N1','[]','[{"ja":"大人びた考え方をする子供","en":"A child who thinks in a very grown-up way","romaji":"Otonabita kangaekata o suru kodomo","zh":""},{"ja":"古びたカバンを捨てられない。","en":"I can''t throw away that old, worn-looking bag.","romaji":"Furubita kaban o suterarenai.","zh":""},{"ja":"田舎びた雰囲気がこの町の魅力だ。","en":"The countrified atmosphere is this town’s charm.","romaji":"Inakabita fun''iki ga kono machi no miryoku da.","zh":""},{"ja":"彼女は少し大人びた服装をしている。","en":"She’s dressed in a slightly grown-up style.","romaji":"Kanojo wa sukoshi otonabita fukusou o shite iru.","zh":""}]',replace('**Short**: A suffix meaning “looking or seeming like ~” (often appears with nouns/adjectives).\n\n**Formation**: [Noun/Adjective stem] + びた (forms a 連体形 modifier, e.g., 大人びた人 “an adult-like person”)\n\n**Long**: The suffix ～びた attaches to certain words to mean “to have the look/feel of ~.” Common examples include 大人びた (adult-like), 古びた (old/worn), 田舎びた (countrified). It expresses that someone or something appears or has become like that noun/adjective.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_biru','～びる',NULL,NULL,'N1','[]','[{"ja":"彼女は年齢より大人びている。","en":"She seems older than her actual age.","romaji":"Kanojo wa nenrei yori otona bite iru.","zh":""},{"ja":"この建物はすっかり古びている。","en":"This building has become completely old and worn.","romaji":"Kono tatemono wa sukkari furubite iru.","zh":""},{"ja":"彼は都会育ちなのに、少し田舎びている話し方をする。","en":"Even though he grew up in the city, he speaks in a somewhat country-like way.","romaji":"Kare wa tokai sodachi na noni, sukoshi inakabite iru hanashikata o suru.","zh":""},{"ja":"子供が急に大人びる瞬間を見ると驚く。","en":"It’s surprising when you see a child suddenly act grown-up.","romaji":"Kodomo ga kyuu ni otona biru shunkan o miru to odoroku.","zh":""}]',replace('**Short**: A suffix meaning “to appear/to become ~,” often used with certain adjectives or nouns.\n\n**Formation**: Adjective/Noun + びる (to form a verb)\n\n**Long**: The suffix ～びる is used to form verbs meaning ''to become like'' or ''to seem like.'' Typical examples include 大人びる (to become or behave like an adult), 古びる (to become old or look old), 田舎びる (to become rustic/countrified).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_butta','～ぶった',NULL,NULL,'N1','[]','[{"ja":"彼は何でも知っているかのようにぶった態度を取る。","en":"He takes on an attitude as though he knows everything.","romaji":"Kare wa nandemo shitteiru ka no you ni butta taido o toru.","zh":""},{"ja":"偉そうぶった物言いをされると、少し腹が立つ。","en":"It irritates me when he speaks in such a high-and-mighty way.","romaji":"Erasou butta monoii o sareru to, sukoshi hara ga tatsu.","zh":""},{"ja":"彼女は大人ぶった口調で話しているが、実はまだ高校生だ。","en":"She’s speaking in a very grown-up manner, but she’s actually still in high school.","romaji":"Kanojo wa otona butta kuchou de hanashite iru ga, jitsu wa mada koukousei da.","zh":""},{"ja":"いい子ぶった態度を取らなくてもいいよ。","en":"You don''t have to pretend to be such a goody-goody.","romaji":"Ii ko butta taido o toranakute mo ii yo.","zh":""}]',replace('**Short**: Often appears as a past form of ～ぶる, meaning ''acted/pretended like ~'' (or literally ''hit/bashed'', depending on context).\n\n**Formation**: Noun/Adjective + ぶる → ぶった (past tense), e.g., 偉そうぶった, 大人ぶった\n\n**Long**: The verb ～ぶる means ''to act/behave as if one is ~'' (e.g., 偉そうにぶる: ''to act all high and mighty''). In its past tense, ～ぶった can describe someone who acted or pretended in a certain way. Be aware that ぶった can also simply be ''hit'' (past tense of 打つ/ぶつ) depending on the kanji/spelling, but as a grammar pattern, it’s about ''putting on airs.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_butte','～ぶって',NULL,NULL,'N1','[]','[{"ja":"彼は何でも知ったかぶって話をする。","en":"He talks as if he knows everything.","romaji":"Kare wa nandemo shittaka butte hanashi o suru.","zh":""},{"ja":"彼女は何も知らないふりをしてぶっていたが、本当は全部わかっている。","en":"She was acting like she didn’t know anything, but in reality, she understands it all.","romaji":"Kanojo wa nanimo shiranai furi o shite butte ita ga, hontou wa zenbu wakatte iru.","zh":""},{"ja":"彼はいつも偉そうぶって周りに指図している。","en":"He’s always bossing people around as if he’s so important.","romaji":"Kare wa itsumo erasou butte mawari ni sashizu shite iru.","zh":""},{"ja":"大人ぶっているけど、まだ子供っぽいところがある。","en":"He acts grown-up, but he still has some childish traits.","romaji":"Otona butte iru kedo, mada kodomoppoi tokoro ga aru.","zh":""}]',replace('**Short**: Te-form of ～ぶる, meaning ''acting/pretending to be ~''.\n\n**Formation**: Noun/Adjective + ぶる → ぶって (te-form)\n\n**Long**: ～ぶる (in te-form: ～ぶって) indicates ''behaving as if one were ~.'' This is often used negatively to criticize someone for putting on airs or pretending to know more than they do (e.g., 知ったかぶって ''to act like a know-it-all'').\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_buri','～ぶり',NULL,NULL,'N1','[]','[{"ja":"三年ぶりに彼に会いました。","en":"I met him for the first time in three years.","romaji":"San-nen buri ni kare ni aimashita.","zh":""},{"ja":"一週間ぶりにジムに行った。","en":"I went to the gym for the first time in a week.","romaji":"Isshuukan buri ni jimu ni itta.","zh":""},{"ja":"一ヶ月ぶりに彼からの手紙が来た。","en":"I received a letter from him for the first time in a month.","romaji":"Ikkagetsu buri ni kare kara no tegami ga kita.","zh":""},{"ja":"五年ぶりに雪が降った。","en":"It snowed for the first time in five years.","romaji":"Go-nen buri ni yuki ga futta.","zh":""}]',replace('**Short**: Expresses the amount of time elapsed since doing something last.\n\n**Formation**: Time expression + ぶり\n\n**Long**: The ～ぶり grammar point is used to express that a certain amount of time has passed since you last did something. It often translates as ''for the first time in ~'' or ''after (time period)''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_buru','～ぶる',NULL,NULL,'N1','[]','[{"ja":"彼はあたかも知っているかのように学者ぶる。","en":"He acts like a scholar, as if he knows everything.","romaji":"Kare wa atakamo shitteiru ka no you ni gakusha buru.","zh":""},{"ja":"女優ぶるのはやめて、自分自身でいろ。","en":"Stop acting like you’re an actress and just be yourself.","romaji":"Joyu buru no wa yamete, jibun jishin de iro.","zh":""},{"ja":"彼女は常にお嬢様ぶっている。","en":"She’s always putting on the airs of a refined lady.","romaji":"Kanojo wa tsune ni ojou-sama butte iru.","zh":""},{"ja":"私がいじめられていると無邪気ぶる彼女を見て、怒りがこみ上げた。","en":"Seeing her act innocent while I was being bullied made my anger surge.","romaji":"Watashi ga ijimerarete iru to mujaki buru kanojo o mite, ikari ga komiageta.","zh":""}]',replace('**Short**: Used when someone is acting or pretending to be something they are not (often a negative connotation).\n\n**Formation**: Noun / (Adjective stem) + ぶる\n\n**Long**: The ～ぶる grammar point is used when someone pretends or acts like something they aren''t. It often has a negative nuance, suggesting insincerity or putting on airs. Common usage includes nouns or descriptive words before ぶる (e.g., 学者ぶる, 偉そうぶる, etc.).\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_made_da','～までだ',NULL,NULL,'N1','[]','[{"ja":"彼とは友達までだ。それ以上の関係ではありません。","en":"With him, it''s only friendship—nothing more.","romaji":"Kare to wa tomodachi made da. Sore ijou no kankei dewa arimasen.","zh":""},{"ja":"飲み放題は9時までだ。それ以降は追加料金が必要だ。","en":"The all-you-can-drink deal is only until nine. After that, there''s an extra charge.","romaji":"Nomihoudai wa kuji made da. Sore ikou wa tsuika ryoukin ga hitsuyou da.","zh":""},{"ja":"私たちの情報は昨日までだ。それ以降のアップデートはありません。","en":"Our information only goes up to yesterday; there are no further updates.","romaji":"Watashitachi no jouhou wa kinou made da. Sore ikou no appudeeto wa arimasen.","zh":""},{"ja":"彼の知識は中学生レベルまでだ。それ以上は理解できない。","en":"His knowledge is only at a junior-high level. He can''t understand anything more advanced.","romaji":"Kare no chishiki wa chuugakusei reberu made da. Sore ijou wa rikai dekinai.","zh":""}]',replace('**Short**: Expresses a limit or extent; ''it''s only up to...'', ''no more than...''.\n\n**Formation**: Verb (dictionary/ない form) + までだ, い-Adjective + までだ, Noun + までだ\n\n**Long**: The ～までだ grammar point is used to emphasize that something goes only up to a certain limit or extent. It can also imply ''it''s only this and nothing more.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mo_nandemonai','～もなんでもない',NULL,NULL,'N1','[]','[{"ja":"100万円を負けるもなんでもない。","en":"Losing a million yen is no big deal at all.","romaji":"Hyaku man-en o makeru mo nandemonai.","zh":""},{"ja":"彼が社長だもなんでもない。","en":"It doesn''t matter one bit that he''s the president.","romaji":"Kare ga shachou da mo nandemonai.","zh":""},{"ja":"あなたが来ないもなんでもない。","en":"It doesn''t matter at all if you don''t come.","romaji":"Anata ga konai mo nandemonai.","zh":""},{"ja":"それが美しいもなんでもない。","en":"It doesn''t matter at all whether it''s beautiful.","romaji":"Sore ga utsukushii mo nandemonai.","zh":""}]',replace('**Short**: Used to dismiss or negate something’s importance; ''it’s nothing at all'', ''it doesn’t matter''.\n\n**Formation**: Verb-dictionary form + もなんでもない, い-Adjective + もなんでもない, な-Adjective + なもなんでもない, Noun + もなんでもない\n\n**Long**: The ～もなんでもない pattern is used to deny or downplay the significance of something. It can mean ''it doesn’t matter at all'' or ''it’s no big deal.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_mono_to_shite','～ものとして',NULL,NULL,'N1','[]','[{"ja":"雨が降るものとして、傘を持って行きました。","en":"Assuming it would rain, I took an umbrella.","romaji":"Ame ga furu mono to shite, kasa o motte ikimashita.","zh":""},{"ja":"彼が病気なものとして、代わりに私が出席した。","en":"On the assumption that he was sick, I attended in his place.","romaji":"Kare ga byouki na mono to shite, kawari ni watashi ga shusseki shita.","zh":""},{"ja":"このケーキが美味しいものとして、みんなに分けよう。","en":"Let’s share this cake, assuming it’s delicious.","romaji":"Kono keeki ga oishii mono to shite, minna ni wakeyou.","zh":""},{"ja":"彼女が学生のものとして、学割を適用しました。","en":"Assuming she is a student, I applied the student discount.","romaji":"Kanojo ga gakusei no mono to shite, gakuwari o tekiyou shimashita.","zh":""}]',replace('**Short**: Indicates an assumption or supposition; ''assuming'', ''under the assumption that''.\n\n**Formation**: Verb-casual + ものとして, い-Adjective + ものとして, な-Adjective + なものとして, Noun + のものとして\n\n**Long**: The ～ものとして grammar pattern is used to express a supposition or assumption: ''assuming that ~'', ''on the premise that ~''. It often sets up a condition or rule as the basis for some action or decision.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_n_ga_tame_ni','～んがために',NULL,NULL,'N1','[]','[{"ja":"健康を保たんがために、毎日運動をしています。","en":"I exercise daily in order to maintain my health.","romaji":"Kenkou o tamotan ga tame ni, mainichi undou o shite imasu.","zh":""},{"ja":"合格せんがために、一生懸命勉強します。","en":"I study hard in order to pass.","romaji":"Goukaku sen ga tame ni, isshoukenmei benkyou shimasu.","zh":""},{"ja":"明日の試験に備えんがため、今夜は早く寝るつもりです。","en":"I plan to go to bed early so I can prepare for tomorrow’s exam.","romaji":"Ashita no shiken ni sonaen ga tame, kon''ya wa hayaku neru tsumori desu.","zh":""},{"ja":"彼女の笑顔を見んがために、毎日会いに行きます。","en":"I go to see her every day in order to see her smile.","romaji":"Kanojo no egao o min ga tame ni, mainichi ai ni ikimasu.","zh":""}]',replace('**Short**: Emphasizes the reason or purpose for an action; ''in order to'', ''for the sake of''.\n\n**Formation**: Verb-negative stem + んがために\n\n**Long**: The ～んがために form is a formal/literary expression meaning ''in order to'' or ''for the purpose of.'' It attaches to the negative stem (ない-form minus ない) of the verb: e.g., する→せん, 行く→いかん, 保つ→たもたん, etc.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_n_bakari_ni','～んばかりに',NULL,NULL,'N1','[]','[{"ja":"彼は何も知らんばかりに、私の質問を無視した。","en":"He ignored my question as if he didn’t know anything.","romaji":"Kare wa nanimo shir-an bakari ni, watashi no shitsumon o mushi shita.","zh":""},{"ja":"その子は泣かんばかりに顔をしかめた。","en":"The child made a face as if he were about to cry.","romaji":"Sono ko wa nakan bakari ni kao o shikameta.","zh":""},{"ja":"彼女は笑わんばかりに口元を押さえた。","en":"She covered her mouth as though she were about to burst out laughing.","romaji":"Kanojo wa warawan bakari ni kuchimoto o osaeta.","zh":""},{"ja":"彼は退屈だと言わんばかりに、ため息を何度もついた。","en":"He sighed over and over as if to say he was bored.","romaji":"Kare wa taikutsu da to iwan bakari ni, tameiki o nando mo tsuita.","zh":""}]',replace('**Short**: Indicates ''as though about to ~'' or ''as if to say ~''.\n\n**Formation**: Verb-negative stem + ん + ばかりに\n\n**Long**: The ～んばかりに form is typically built on the negative stem of a verb (ない-form minus ない: 行か→行かん, 言わ→言わん, 知ら→知らん, etc.) + ばかり. It describes someone’s action or expression as though it were about to happen, or as though conveying a certain meaning without explicitly stating it.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_sashitsukaenai','～差し支えない',NULL,NULL,'N1','[]','[{"ja":"多少遅くても差し支えないです。","en":"It’s no problem if you’re a bit late.","romaji":"Tashou osokute mo sashitsukaenai desu.","zh":""},{"ja":"部屋が少し汚くても差し支えない。","en":"It doesn’t matter if the room is slightly messy.","romaji":"Heya ga sukoshi kitanakute mo sashitsukaenai.","zh":""},{"ja":"雨が降っても差し支えない。","en":"It’s not an issue even if it rains.","romaji":"Ame ga futte mo sashitsukaenai.","zh":""},{"ja":"彼がここにいることが差し支えないですか？","en":"Is it okay (no problem) for him to be here?","romaji":"Kare ga koko ni iru koto ga sashitsukaenai desu ka?","zh":""}]',replace('**Short**: Indicates no problem or obstacle; ''it’s fine if...'', ''there’s no issue''.\n\n**Formation**: Verb-て form + も差し支えない, Noun + が差し支えない\n\n**Long**: The ～差し支えない grammar point expresses that doing something (or something occurring) is not a problem and causes no inconvenience. It’s often used in polite or formal situations.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_ori_ni','～折に',NULL,NULL,'N1','[]','[{"ja":"父が病気の折に、私は留学していました。","en":"When my father was ill, I was studying abroad.","romaji":"Chichi ga byouki no ori ni, watashi wa ryuugaku shite imashita.","zh":""},{"ja":"日本へ行く折に、お土産を買ってきてください。","en":"When you go to Japan, please buy souvenirs.","romaji":"Nihon e iku ori ni, omiyage o katte kite kudasai.","zh":""},{"ja":"子供が寝ている折に、静かにしてください。","en":"Please be quiet when the child is sleeping.","romaji":"Kodomo ga nete iru ori ni, shizuka ni shite kudasai.","zh":""},{"ja":"彼に会う折に、この手紙を渡してください。","en":"Please give him this letter when you see him.","romaji":"Kare ni au ori ni, kono tegami o watashite kudasai.","zh":""}]',replace('**Short**: Indicates the time or occasion when something happens; ''when'', ''at the time of''.\n\n**Formation**: Verb-dictionary form + 折に, Verb-た形 + 折に, Noun + の折に\n\n**Long**: The ～折に grammar point is used in a somewhat formal register to express that one event or action takes place on the occasion of another. It essentially means ''when'' or ''at the time of''.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kiwamarinai','～極まりない',NULL,NULL,'N1','[]','[{"ja":"彼の失礼な態度は極まりない。","en":"His rude attitude is utterly beyond words.","romaji":"Kare no shitsurei na taido wa kiwamarinai.","zh":""},{"ja":"その運転は危険極まりない。","en":"That driving is extremely dangerous.","romaji":"Sono unten wa kiken kiwamarinai.","zh":""},{"ja":"彼女のわがままぶりは非常識極まりない。","en":"Her selfishness is utterly irrational.","romaji":"Kanojo no wagamama-buri wa hijoushiki kiwamarinai.","zh":""},{"ja":"この部屋の汚さは不衛生極まりない。","en":"The filthiness of this room is extremely unsanitary.","romaji":"Kono heya no kitasa wa fueisei kiwamarinai.","zh":""}]',replace('**Short**: Expresses an extreme state, often negative; ''utterly'', ''extremely'', ''boundlessly''.\n\n**Formation**: な-Adjective（語幹）+ 極まりない, い-Adjective（連用形）+ こと + 極まりない, Noun + の極まりない\n\n**Long**: The ～極まりない grammar point indicates an extreme or utmost degree, most commonly with a negative nuance (e.g., 失礼極まりない, 危険極まりない). It can sometimes be used for positive contexts, but that usage is less common.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kiwamaru','～極まる',NULL,NULL,'N1','[]','[{"ja":"彼の言動は失礼極まる。","en":"His words and actions are extremely rude.","romaji":"Kare no gendou wa shitsurei kiwamaru.","zh":""},{"ja":"その態度は非常識極まる。","en":"That behavior is utterly irrational.","romaji":"Sono taido wa hijoushiki kiwamaru.","zh":""},{"ja":"彼女の発言は無責任極まる。","en":"Her remark is extremely irresponsible.","romaji":"Kanojo no hatsugen wa musekinin kiwamaru.","zh":""},{"ja":"このような誤解は遺憾極まる。","en":"Such a misunderstanding is exceedingly regrettable.","romaji":"Kono youna gokai wa ikan kiwamaru.","zh":""}]',replace('**Short**: Also expresses an extreme degree or state, typically negative.\n\n**Formation**: な-Adjective（語幹）+ 極まる, い-Adjective（連用形）+ こと + 極まる, etc.\n\n**Long**: The ～極まる form often appears with な-adjectives: e.g., 失礼極まる, 非常識極まる (''extremely rude/unreasonable''). It''s largely synonymous with ～極まりない but tends to appear in set phrases. Both forms are quite formal and emphatic.\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_tarinai','～足りない',NULL,NULL,'N1','[]','[{"ja":"私の日本語の能力はまだまだ足りない。","en":"My Japanese skills are still not enough.","romaji":"Watashi no nihongo no nouryoku wa madamada tarinai.","zh":""},{"ja":"時間が足りないから、今すぐ行かなきゃ。","en":"We don''t have enough time, so we must go right now.","romaji":"Jikan ga tarinai kara, ima sugu ikanakya.","zh":""},{"ja":"彼の説明には詳細が足りない。","en":"His explanation lacks detail.","romaji":"Kare no setsumei ni wa shousai ga tarinai.","zh":""},{"ja":"料理するための食材が足りない。","en":"There''s not enough food to cook with.","romaji":"Ryouri suru tame no shokuzai ga tarinai.","zh":""}]',replace('**Short**: Expresses insufficiency or lack; ''not enough'', ''insufficient''.\n\n**Formation**: Noun + (が) 足りない, Verb-casual + ほど/だけ + (が) 足りない\n\n**Long**: The ～足りない pattern simply means that something is not sufficient in quantity, time, detail, ability, etc. It’s the negative form of 足りる (''to be enough'').\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_taru_noun','～足る Noun',NULL,NULL,'N1','[]','[{"ja":"彼は信頼に足る人物だ。","en":"He is a person worthy of trust.","romaji":"Kare wa shinrai ni taru jinbutsu da.","zh":""},{"ja":"この小説は読むに足る価値がある。","en":"This novel is well worth reading.","romaji":"Kono shousetsu wa yomu ni taru kachi ga aru.","zh":""},{"ja":"検討に足るデータが十分に集まった。","en":"We''ve gathered enough data to be worth examining.","romaji":"Kentou ni taru deeta ga juubun ni atsumatta.","zh":""},{"ja":"彼の説明は信用に足るものだと思う。","en":"I think his explanation is worthy of trust.","romaji":"Kare no setsumei wa shinyou ni taru mono da to omou.","zh":""}]',replace('**Short**: Indicates that something is worthy or sufficient to be called/used as ~; ''worthy of'', ''enough to ~''.\n\n**Formation**: Noun/Verb-dictionary form + に足る + Noun\n\n**Long**: The classical pattern ''Noun + に足る + Noun'' or ''Verb + に足る + Noun'' means ''something is worthy of or sufficient for ~.'' For instance, ''信頼に足る人物'' means ''a person worthy of trust.'' It’s different from the everyday verb 足りる (''to be enough'').\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
INSERT INTO grammar_points VALUES('g_kagiri_da','～限りだ',NULL,NULL,'N1','[]','[{"ja":"彼女が急に辞めてしまった。驚きの限りだ。","en":"She suddenly quit. I''m as shocked as can be.","romaji":"Kanojo ga kyuu ni yamete shimatta. Odoroki no kagiri da.","zh":""},{"ja":"息子が成功した。嬉しい限りだ。","en":"My son succeeded. I''m so happy.","romaji":"Musuko ga seikou shita. Ureshii kagiri da.","zh":""},{"ja":"こんなに綺麗な花が見られるなんて、幸せの限りだ。","en":"I''m as happy as can be to see such beautiful flowers.","romaji":"Konna ni kirei na hana ga mirareru nante, shiawase no kagiri da.","zh":""},{"ja":"試験に合格できて、ほっとした限りだ。","en":"I passed the exam—what a relief!","romaji":"Shiken ni goukaku dekite, hotto shita kagiri da.","zh":""}]',replace('**Short**: Expresses an extreme degree of emotion or reaction; ''I feel so ~'', ''as ~ as can be''.\n\n**Formation**: い-Adjective + 限りだ, な-Adjective + な/である + 限りだ, Noun + の + 限りだ\n\n**Long**: The ～限りだ structure is often used with adjectives describing the speaker''s emotion, highlighting how strongly the speaker feels. Translations often include ''I’m as ~ as can be,'' ''I feel so ~.''\n\n\n_Source: hanabira.org (CC)_','\n',char(10)));
